// ═════════════ 27. Session Guest Star SOLO — pas de compteur combiné ═════════════
titre('27. Session solo — un host.id sans collaboration ne fabrique rien');
{
  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 30 * 60_000).toISOString();
    // Forme observée sur trafic réel : session ouverte, UN seul participant
    // (l'hôte lui-même), et collaborationViewersCount à null — Twitch ne
    // calcule pas de combiné tant qu'il n'y a personne avec qui combiner.
    window.__fx = {
      theguill84: { id:'36318615', createdAt:h, viewers:739, game:'Minecraft', tags:[] },
      voisin:     { id:'99',       createdAt:h, viewers:739, game:'Minecraft', tags:[] },
    };
    window.__gs = {
      '36318615': { hostId:'36318615', hostLogin:'theguill84',
                    guests:[{ id:'36318615', login:'theguill84', viewers:739, combined:null }] },
    };
    window.__addCard('theguill84', 'Minecraft', '700');
    window.__addCard('voisin',     'Minecraft', '700');
  });
  await wait(page, 2500);
  const s = await page.evaluate(() => [...document.querySelectorAll('.side-nav-card')].map(c => ({
    login: c.dataset.tseLogin, key: c.dataset.tseCostreamKey,
    viewers: c.dataset.tseViewers,
    shown: c.querySelector('.tse-viewers')?.textContent ?? null
  })));
  const by = Object.fromEntries(s.map(c => [c.login, c]));
  ok('l\'audience propre est affichée, pas de NaN', nz(by.theguill84.shown) === '739', by.theguill84.shown);
  ok('le dataset reste exact',                      by.theguill84.viewers === '739', by.theguill84.viewers);
  // Un host.id existe, mais il ne couvre qu'une carte : aucun groupe ne doit
  // naître, et surtout pas avec un voisin qui affiche le même nombre.
  ok('aucun groupe de co-stream fabriqué', !by.theguill84.key, JSON.stringify(by.theguill84));
  ok('le voisin au même compteur n\'est pas happé', !by.voisin.key, JSON.stringify(by.voisin));
  await page.close();
}

// ═════════════ 28. Anti-pub — inerte hors iframe ═════════════
titre('28. Anti-pub — chargé avec la sidebar, mais strictement inerte en top-level');
{
  const page = await fresh();
  const probe = await page.evaluate(() => ({
    // Le fichier a-t-il seulement été chargé ? Sans ça, tout le reste du
    // scénario passerait pour de mauvaises raisons.
    loaded:    typeof TSE_ADBLOCK_ENABLED !== 'undefined' && TSE_ADBLOCK_ENABLED === true,
    api:       typeof window.vaft2,
    marker1:   typeof window.vaftVersion,
    marker2:   typeof window.twitchAdSolutionsVersion,
    fetchKept: window.fetch === window.__mockFetch,
    workerNative: /\[native code\]/.test(String(window.Worker))
  }));
  ok('le module est bien chargé', probe.loaded === true, JSON.stringify(probe));
  ok('aucune API console posée', probe.api === 'undefined', probe.api);
  ok('le marqueur vaftVersion n\'est pas revendiqué', probe.marker1 === 'undefined', probe.marker1);
  ok('ni twitchAdSolutionsVersion', probe.marker2 === 'undefined', probe.marker2);
  // Les deux crochets que pose le module : ni l'un ni l'autre hors iframe.
  ok('fetch n\'est pas accroché',  probe.fetchKept === true, JSON.stringify(probe));
  ok('Worker n\'est pas accroché', probe.workerNative === true, String(probe.workerNative));
  await page.close();
}

// ═════════════ 29. Palette co-stream — teintes réellement distinctes ═════════════
titre('29. Palette — deux collaborations voisines doivent se distinguer');
{
  // Contrôle STATIQUE : la palette est une donnée, pas un comportement. On la
  // lit dans la source plutôt que de l'exposer au global pour les besoins du test.
  const source = readFileSync(join(ICI, '..', 'content.js'), 'utf8');
  const block = source.slice(source.indexOf('const COSTREAM_PALETTE = ['));
  const entries = [...block.slice(0, block.indexOf('];')).matchAll(
    /color:\s*'#([0-9a-f]{6})'[^}]*?bg:\s*'rgba\((\d+),\s*(\d+),\s*(\d+),\s*0\.18\)'[^}]*?fade:\s*'rgba\((\d+),\s*(\d+),\s*(\d+),\s*0\.06\)'/gi)];

  ok('la palette est lisible et non vide', entries.length >= 4, `${entries.length} entrées`);

  const hexToRgb = (h) => [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16));
  const hue = (h) => {
    const [r, g, b] = hexToRgb(h).map(v => v / 255);
    const max = Math.max(r, g, b), min = Math.min(r, g, b), d = max - min;
    if (!d) return 0;
    const t = max === r ? ((g - b) / d) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
    return (t * 60 + 360) % 360;
  };

  // 1) Les rgba doivent décrire EXACTEMENT la couleur hex de leur entrée.
  //    Une coquille ici passe inaperçue à la relecture : le liseré serait d'une
  //    couleur et son halo d'une autre.
  const mismatched = entries.filter(m => {
    const [r, g, b] = hexToRgb(m[1]);
    return +m[2] !== r || +m[3] !== g || +m[4] !== b
        || +m[5] !== r || +m[6] !== g || +m[7] !== b;
  }).map(m => '#' + m[1]);
  ok('chaque rgba correspond à son hex', mismatched.length === 0, mismatched.join(', '));

  // 2) Écart de teinte minimum sur le cercle, en incluant le retour au début.
  const hues = entries.map(m => hue(m[1])).sort((a, b) => a - b);
  let worst = 360, pair = '';
  for (let i = 0; i < hues.length; i++) {
    const a = hues[i], b = hues[(i + 1) % hues.length];
    const d = ((b - a) % 360 + 360) % 360;
    if (d < worst) { worst = d; pair = `${a.toFixed(0)}° ↔ ${b.toFixed(0)}°`; }
  }
  ok('aucune paire de teintes sous 40°', worst >= 40, `pire paire ${pair} = ${worst.toFixed(0)}°`);
  console.log(`     → ${entries.length} couleurs, écart minimum ${worst.toFixed(0)}°`);
}

// ═════════════ 30. Aperçu — révélé à la PREMIÈRE IMAGE, pas au `load` ═════════════
titre('30. Aperçu — l\'iframe n\'apparaît qu\'une fois une image affichée');
{
  // Le lecteur Twitch est remplacé par une page servie depuis la VRAIE origine
  // player.twitch.tv (interception réseau) : la garde d'hôte du pont s'applique
  // donc pour de bon, et le message franchit une frontière cross-origin réelle.
  // Les modules sont chargés par <script src>, dans l'ordre du manifeste, et
  // servis par la route de player.twitch.tv — donc à la bonne origine.
  const fakePlayer = (withVideo) => `<!doctype html><html><body>
    <script src="/adblock.test.js"></script>
    <script src="/content.test.js"></script>
    <script>
      ${withVideo ? `
      // Vidéo RÉELLE : un canvas animé capturé en MediaStream. Les images sont
      // donc réellement présentées, ce qui est la seule façon de déclencher
      // requestVideoFrameCallback pour de vrai.
      // La video et son flux existent TOUT DE SUITE, et play() est appele
      // aussitot : l'evenement playing et readyState peuvent donc partir tres
      // tot. Mais le canvas n'est dessine qu'apres un delai, donc AUCUNE image
      // n'est presentee avant. C'est exactement ce qui separe << la lecture a
      // demarre >> de << il y a quelque chose a voir >>.
      const c = document.createElement('canvas');
      c.width = 32; c.height = 18;
      const ctx = c.getContext('2d');
      const v = document.createElement('video');
      v.autoplay = true; v.muted = true; v.playsInline = true;
      v.srcObject = c.captureStream(25);
      document.body.appendChild(v);
      v.play().catch(() => {});
      window.__firstDrawAt = null;
      setTimeout(() => {
        window.__firstDrawAt = performance.now();
        setInterval(() => {
          ctx.fillStyle = '#' + Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0');
          ctx.fillRect(0, 0, 32, 18);
        }, 40);
      }, 700);
      ` : '/* aucune vidéo : le signal n\'arrivera jamais */'}
    </script>
  </body></html>`;

  const loadedState = (page) => page.evaluate(() => {
    const f = document.querySelector('.tse-preview__iframe');
    return f ? (f.dataset.tseLoaded ?? null) : 'pas-d-iframe';
  });

  // ── a) cas nominal : le pont signale, le parent dévoile ──────────────────
  {
    const page = await freshTwitch(fakePlayer(true));
    await page.evaluate(() => {
      window.__fx = { alpha: { id:'1', createdAt:new Date(Date.now()-3600_000).toISOString(),
                               viewers:1000, game:'G', tags:[] } };
      window.__addCard('alpha', 'G', '1 k');
    });
    await wait(page, 2000);  // laisse le voile de chargement se lever
    await hoverCard(page, 0);

    // 300 ms : la lecture a démarré, mais le canvas n'est pas encore dessiné.
    // Si le code se contentait de `playing` ou de readyState, il dévoilerait ICI.
    await wait(page, 300);
    const early = await loadedState(page);
    ok('rien n\'est dévoilé avant qu\'une image existe', early !== 'true', String(early));

    // On ATTEND le dévoilement au lieu de l'échantillonner à date fixe. Le
    // premier dessin a lieu à 700 ms et le filet de sécurité à 1500 ms, mais
    // sous charge un « attendre 1000 ms » s'étire : le prélèvement tombait
    // avant que le message de l'iframe n'ait été traité, et l'assertion
    // constatait un non-dévoilement qui n'existait pas. L'attente est bornée —
    // si le dévoilement n'a jamais lieu, elle expire et l'assertion tombe.
    await attendre(page, () => {
      const f = document.querySelector('.tse-preview__iframe');
      return !!f && f.dataset.tseLoaded === 'true';
    }, 6000);
    const late = await loadedState(page);
    ok('dévoilée dès la première image', late === 'true', String(late));
    await page.close();
  }

  // ── b) le signal n'arrive jamais : le filet doit prendre le relais ───────
  {
    const page = await freshTwitch(fakePlayer(false));
    await page.evaluate(() => {
      window.__fx = { beta: { id:'2', createdAt:new Date(Date.now()-3600_000).toISOString(),
                              viewers:1000, game:'G', tags:[] } };
      window.__addCard('beta', 'G', '1 k');
    });
    await wait(page, 2000);
    await hoverCard(page, 0);

    await wait(page, 900);
    const before = await loadedState(page);
    ok('le filet ne se déclenche pas trop tôt', before !== 'true', String(before));

    // Le filet se déclenche à PREVIEW_REVEAL_FALLBACK_MS (1500 ms). On l'ATTEND
    // au lieu de prélever après 1400 ms de plus : sous charge, ce prélèvement
    // arrive avant que le minuteur de la page n'ait été servi. Borné — sans
    // filet, l'attente expire et l'assertion tombe.
    await attendre(page, () => {
      const f = document.querySelector('.tse-preview__iframe');
      return !!f && f.dataset.tseLoaded === 'true';
    }, 6000);
    const after = await loadedState(page);
    ok('sans signal, le filet dévoile quand même', after === 'true', String(after));
    await page.close();
  }

  // ── c) aucun écouteur postMessage ne doit s'accumuler d'un survol à l'autre
  {
    const page = await freshTwitch(fakePlayer(true));
    await page.evaluate(() => {
      const h = new Date(Date.now() - 3600_000).toISOString();
      window.__fx = {
        un:   { id:'1', createdAt:h, viewers:1000, game:'G', tags:[] },
        deux: { id:'2', createdAt:h, viewers:900,  game:'G', tags:[] },
      };
      // Compte les écouteurs 'message' posés sur window.
      window.__msgListeners = 0;
      const add = window.addEventListener.bind(window);
      const rem = window.removeEventListener.bind(window);
      window.addEventListener = (t, ...rest) => { if (t === 'message') window.__msgListeners++; return add(t, ...rest); };
      window.removeEventListener = (t, ...rest) => { if (t === 'message') window.__msgListeners--; return rem(t, ...rest); };
      window.__addCard('un',   'G', '1 k');
      window.__addCard('deux', 'G', '900');
    });
    await wait(page, 2000);
    for (let i = 0; i < 4; i++) {
      await hoverCard(page, i % 2);
      await wait(page, 400);
      await unhoverCard(page, i % 2);
    }
    await wait(page, 600);
    const leaked = await page.evaluate(() => window.__msgListeners);
    ok('aucun écouteur laissé derrière après 4 survols', leaked <= 1, `${leaked} restant(s)`);
    await page.close();
  }
}

// ═════════════ 31. Vignette — cache utilisable, et pas de rectangle noir ═════════════
titre('31. Vignette — l\'URL doit être stable, et l\'attente ne doit pas être noire');
{
  const cdnUrls = [];
  // Ouvert AVANT la page : depuis le préchargement, les premières miniatures
  // partent sans qu'aucun survol n'ait eu lieu. La fenêtre doit les couvrir.
  const t0 = Date.now();
  const page = await freshTwitch('<!doctype html><html><body>lecteur</body></html>', cdnUrls);
  await page.evaluate(() => {
    window.__fx = {
      alpha: { id:'1', createdAt:new Date(Date.now()-3600_000).toISOString(), viewers:1000, game:'G', tags:[] },
      beta:  { id:'2', createdAt:new Date(Date.now()-3600_000).toISOString(), viewers:900,  game:'G', tags:[] },
    };
    window.__addCard('alpha', 'G', '1 k');
    window.__addCard('beta',  'G', '900');
  });
  await wait(page, 2000);

  // Trois survols d'alpha, entrecoupés d'un passage sur beta.
  for (const i of [0, 1, 0, 0]) {
    await hoverCard(page, i);
    await wait(page, 350);
    await unhoverCard(page, i);
    await wait(page, 150);
  }

  const alphaUrls = cdnUrls.filter(u => u.includes('live_user_alpha'));
  ok('la vignette d\'alpha a bien été demandée', alphaUrls.length >= 2, `${alphaUrls.length} demande(s)`);
  // LE point : DANS UNE MÊME TRANCHE, l'URL ne doit pas changer d'un survol à
  // l'autre — sinon le navigateur ne peut jamais rien resservir de son cache,
  // ce qui était le cas avec un horodatage à la milliseconde. Formulé par
  // tranche et non dans l'absolu : une tranche FINIT par changer, c'est même
  // sa raison d'être, et le harnais l'accélère justement pour l'observer.
  const distinct = [...new Set(alphaUrls)];
  const parTranche = new Map();
  for (const u of distinct) {
    const b = u.split('?_=')[1];
    if (!parTranche.has(b)) parTranche.set(b, []);
    parTranche.get(b).push(u);
  }
  const multiples = [...parTranche].filter(([, urls]) => urls.length > 1);
  ok('une seule URL par tranche', multiples.length === 0,
     multiples.map(([b, urls]) => `${b}: ${urls.length}`).join(' | '));
  ok('l\'URL ne change QUE d\'une tranche à l\'autre',
     distinct.length === parTranche.size, `${distinct.length} URLs / ${parTranche.size} tranche(s)`);

  // La tranche doit valoir Math.floor(now / PREVIEW_THUMB_CACHE_MS) : on vérifie
  // la FORMULE, pas seulement la stabilité — deux survols rapprochés seraient
  // stables même avec une tranche d'une seconde. La durée est relue dans la
  // source plutôt que recopiée ici, pour que le test suive si elle change.
  // Lue dans le fichier RÉELLEMENT exécuté : le harnais accélère cette
  // constante, comparer à la source ferait échouer le test sur un chiffre qui
  // n'est pas celui qui tourne.
  const declared = /PREVIEW_THUMB_CACHE_MS:\s*([\d_]+)/
    .exec(readFileSync(join(ICI, 'content.test.js'), 'utf8'));
  ok('la durée de tranche est déclarée', !!declared, String(declared));
  const slice = Number(declared[1].replaceAll('_', ''));
  // Comparée à la FENÊTRE pendant laquelle les survols ont eu lieu, et non à
  // l'instant de l'assertion : le scénario dure plusieurs secondes, et à
  // l'échelle accélérée du harnais la tranche a le temps de changer entre les
  // deux. Une tolérance en dur masquerait le problème au lieu de le poser.
  const bornes = [Math.floor(t0 / slice), Math.floor(Date.now() / slice)];
  const vues = [...parTranche.keys()].map(Number);
  ok(`les tranches vues tombent dans la fenêtre des survols (${slice / 1000} s)`,
     vues.every(b => b >= bornes[0] && b <= bornes[1]),
     `${vues.join(', ')} hors de [${bornes[0]}, ${bornes[1]}]`);

  // La taille demandée au CDN doit venir des constantes CDN, pas de la largeur
  // du popup : les deux ont été découplées, et rien ne doit les recoller sans
  // qu'on s'en aperçoive — un changement de mise en page changerait alors
  // l'objet réclamé au réseau.
  const conf = readFileSync(join(ICI, '..', 'content.js'), 'utf8');
  const w = /PREVIEW_THUMB_CDN_W:\s*(\d+)/.exec(conf);
  const h = /PREVIEW_THUMB_CDN_H:\s*(\d+)/.exec(conf);
  ok('les dimensions CDN sont déclarées à part', !!w && !!h, `${w && w[1]}x${h && h[1]}`);
  ok('l\'URL demandée porte bien ces dimensions',
     distinct[0].includes(`-${w[1]}x${h[1]}.jpg`), distinct[0]);

  // L'attente ne doit pas se présenter comme un rectangle noir.
  await hoverCard(page, 0);
  // La vignette apparaît EN FONDU. Prélever son opacité 300 ms après le survol
  // revenait à l'attraper en pleine transition : 0,885 relevé sous charge, pour
  // un seuil de 0,9. On attend donc la fin du fondu — bornée. Le seuil garde
  // ses dents : une vignette qui resterait invisible ne l'atteindrait jamais.
  await attendre(page, () => {
    const i = document.querySelector('.tse-preview__thumb');
    return !!i && i.dataset.tseLoaded === 'true' && Number(getComputedStyle(i).opacity) > 0.9;
  }, 5000);
  const look = await page.evaluate(() => {
    const wrap = document.querySelector('.tse-preview__thumb-wrap');
    const img = document.querySelector('.tse-preview__thumb');
    return { bg: wrap ? getComputedStyle(wrap).backgroundColor : null,
             loaded: img ? (img.dataset.tseLoaded ?? null) : null,
             opacity: img ? getComputedStyle(img).opacity : null };
  });
  ok('le fond d\'attente n\'est pas noir', look.bg !== 'rgb(0, 0, 0)', String(look.bg));
  ok('la vignette est marquée chargée', look.loaded === 'true', String(look.loaded));
  ok('…et donc visible', Number(look.opacity) > 0.9, String(look.opacity));
  await page.close();
}

// ═════════════ 32. Aperçu — l'échelle de qualité doit être plafonnée ═════════════
titre('32. Qualité — le jeton d\'accès doit être demandé en « autoplay »');
{
  // Le type de lecteur porté par la requête de jeton décide de l'ÉCHELLE que
  // Twitch renvoie. On vérifie ici la réécriture de bout en bout, à travers le
  // vrai code du module, et non la seule valeur de la constante.
  const tokenBodies = [];
  const player = `<!doctype html><html><body>
    <script src="/adblock.test.js"></script>
    <script>
      // Requête de jeton telle que le lecteur de Twitch l'émet, avec le type
      // que porterait notre iframe. Le module doit la réécrire au passage.
      setTimeout(() => {
        fetch('https://gql.twitch.tv/gql', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify([{
            operationName: 'PlaybackAccessToken',
            variables: { isLive: true, login: 'alpha', isVod: false, vodID: '',
                         playerType: 'site', platform: 'web' }
          }])
        }).catch(() => {});
      }, 200);
    </script>
  </body></html>`;

  const page = await freshTwitch(player);
  await page.route('https://gql.twitch.tv/**', (route) => {
    try { tokenBodies.push(JSON.parse(route.request().postData() || '[]')); } catch { /* ignore */ }
    route.fulfill({ contentType: 'application/json',
                    body: JSON.stringify([{ data: { streamPlaybackAccessToken: null } }]) });
  });
  await page.evaluate(() => {
    window.__fx = { alpha: { id:'1', createdAt:new Date(Date.now()-3600_000).toISOString(),
                             viewers:1000, game:'G', tags:[] } };
    window.__addCard('alpha', 'G', '1 k');
  });
  await wait(page, 2000);
  await hoverCard(page, 0);
  await wait(page, 1500);

  const ops = tokenBodies.flat().filter(o => o?.operationName === 'PlaybackAccessToken');
  ok('la requête de jeton a bien été émise', ops.length >= 1, `${ops.length} requête(s)`);
  const types = [...new Set(ops.map(o => o?.variables?.playerType))];
  // 'site' serait la valeur d'origine : si elle survit, la réécriture n'a pas eu
  // lieu et l'échelle n'est pas plafonnée.
  ok('le type est réécrit en « autoplay »',
     types.length === 1 && types[0] === 'autoplay', JSON.stringify(types));

  // Et la constante doit rester en accord avec ce que le test vient de prouver.
  const declared = /ForceAccessTokenPlayerType:\s*'([a-z_]+)'/
    .exec(readFileSync(join(ICI, '..', 'adblock.js'), 'utf8'));
  ok('la constante déclare bien autoplay', declared && declared[1] === 'autoplay',
     declared ? declared[1] : 'introuvable');
  await page.close();
}

// ═════════════ 33. Préchargement des miniatures ═════════════
titre('33. Préchargement — réchauffer pendant les périodes calmes');
{
  const poser = (page) => page.evaluate(() => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    window.__fx = {
      un:     { id:'1', createdAt:h, viewers:1000, game:'G', tags:[] },
      deux:   { id:'2', createdAt:h, viewers:900,  game:'G', tags:[] },
      trois:  { id:'3', createdAt:h, viewers:800,  game:'G', tags:[] },
      eteint: null,                       // hors direct : pas de miniature
    };
    ['un', 'deux', 'trois'].forEach(l => window.__addCard(l, 'G', '1 k'));
    window.__addCard('eteint', 'G', '0', false);
    // Carte en direct mais ABSENTE de __fx : l'API ne la connaît pas, donc le
    // cache non plus. C'est la situation des sections « Chaînes live » et
    // « Les spectateurs de… », que le scan n'interroge jamais.
    window.__addCard('recommandee', 'G', '2 k');
    // Et une carte hors ligne pour l'API SEULEMENT le temps qu'elle le
    // confirme : tant que le DOM la montre en direct, la réchauffer est le bon
    // choix — c'est l'affichage qui fait foi pour ce que l'utilisateur peut
    // survoler.
    window.__addCard('grisee', 'G', '0', false);
  });
  const logins = (urls) => urls.map(u => u.split('live_user_')[1]?.split('-')[0]);

  // ── a) le pointeur est ailleurs : la passe doit tourner ──────────────────
  {
    const cdn = [];
    const page = await freshTwitch('<!doctype html><html><body>x</body></html>', cdn);
    await poser(page);
    await wait(page, 2500);   // aucun survol, souris jamais déplacée
    const vus = new Set(logins(cdn));
    ok('les chaînes en direct sont réchauffées',
       ['un', 'deux', 'trois'].every(l => vus.has(l)), [...vus].join(', '));
    // Une chaîne hors direct n'a pas de miniature : la demander donnerait un 404.
    ok('une chaîne hors direct n\'est pas demandée', !vus.has('eteint'), [...vus].join(', '));
    // Sections hors « suivis » : la carte est en direct dans le DOM, mais
    // l'extension ne l'a jamais interrogée. Elle doit quand même être servie.
    ok('une carte live inconnue de l\'API est réchauffée', vus.has('recommandee'), [...vus].join(', '));
    ok('une carte à l\'avatar grisé est écartée', !vus.has('grisee'), [...vus].join(', '));
    await page.close();
  }

  // ── b) l'URL préchargée doit être CELLE du survol, au caractère près ─────
  //     C'est le mode de panne évident : un écart d'un caractère et la passe
  //     réchaufferait le vide, sans que rien ne le signale.
  {
    const cdn = [];
    const page = await freshTwitch('<!doctype html><html><body>x</body></html>', cdn);
    await poser(page);
    // Se caler sur un DÉBUT de tranche. Sinon, à l'échelle accélérée du
    // harnais, la tranche peut basculer entre la passe et le survol : le popup
    // demanderait alors légitimement une URL neuve, et le test conclurait à
    // tort que la passe a réchauffé autre chose.
    const slice = Number(/PREVIEW_THUMB_CACHE_MS:\s*([\d_]+)/
      .exec(readFileSync(join(ICI, 'content.test.js'), 'utf8'))[1].replaceAll('_', ''));
    await wait(page, slice - (Date.now() % slice) + 60);
    await wait(page, 900);            // la passe tourne dans la tranche neuve
    // Sélection par TRANCHE, pas par index : la marge de calage suffit à ce
    // qu'un réveil ait déjà lancé la passe, et un découpage positionnel
    // laisserait ces requêtes-là hors du compte.
    const tranche = Math.floor(Date.now() / slice);
    const preloadees = cdn.filter(u => u.includes('live_user_un-') && u.endsWith('?_=' + tranche));
    ok('« un » a bien été préchargée', preloadees.length >= 1, String(preloadees.length));

    const avant = cdn.length;
    await hoverLogin(page, 'un');
    await wait(page, 400);
    const src = await page.evaluate(() =>
      document.querySelector('.tse-preview__thumb')?.src ?? null);
    ok('le popup demande une URL déjà préchargée',
       preloadees.includes(src), `${src}\n     vs ${preloadees[preloadees.length - 1]}`);
    // On ne peut PAS vérifier ici « aucune requête en plus » : sous interception
    // réseau, Playwright sert chaque requête lui-même et le cache HTTP du
    // navigateur n'est jamais consulté. Ce qui reste observable, et qui est le
    // vrai invariant : le survol ne réclame aucune URL INÉDITE. S'il en
    // réclamait une, c'est que la passe aurait réchauffé autre chose que ce
    // qu'il demande — la panne silencieuse qu'on veut exclure.
    const inedites = cdn.slice(avant).filter(u => !cdn.slice(0, avant).includes(u));
    ok('le survol ne réclame aucune URL inédite', inedites.length === 0, inedites.join(' | '));
    await page.close();
  }

  // ── c) la porte, dans les DEUX sens ─────────────────────────────────────
  {
    const cdn = [];
    const page = await freshTwitch('<!doctype html><html><body>x</body></html>', cdn);
    const box = await page.locator('#side-nav').boundingBox();
    ok('la sidebar a une géométrie', !!box, JSON.stringify(box));
    await page.mouse.move(box.x + box.width / 2, box.y + 10);
    await poser(page);

    // ATTENDRE que le navigateur reconnaisse le survol. Chromium ne recalcule
    // pas :hover à la réception du mousemove mais au prochain événement : juste
    // après mouse.move, matches(':hover') répond encore false pendant plusieurs
    // centaines de millisecondes. Mesurer sans cette attente reviendrait à
    // observer une fenêtre où la porte est légitimement ouverte, et à conclure
    // qu'elle ne ferme pas.
    await page.waitForFunction(
      () => document.querySelector('#side-nav')?.matches(':hover') === true,
      null, { timeout: 5000 });
    ok('le survol est reconnu par le navigateur', true);

    // Porte FERMÉE : deux chaînes neuves, jamais préchargées, apparaissent
    // alors que le pointeur est sur la sidebar. Rien ne doit partir.
    const avant = cdn.length;
    await page.evaluate(() => {
      const h = new Date(Date.now() - 3600_000).toISOString();
      window.__fx.quatre = { id:'4', createdAt:h, viewers:700, game:'G', tags:[] };
      window.__fx.cinq   = { id:'5', createdAt:h, viewers:600, game:'G', tags:[] };
      window.__addCard('quatre', 'G', '700');
      window.__addCard('cinq',   'G', '600');
    });
    await wait(page, 1200);
    const pendant = logins(cdn.slice(avant));
    ok('rien n\'est réchauffé tant que le pointeur est sur la sidebar',
       !pendant.includes('quatre') && !pendant.includes('cinq'), pendant.join(', '));

    // Porte OUVERTE : on sort, la passe doit reprendre — et reprendre LÀ où
    // elle s'était arrêtée, donc servir précisément ces deux-là.
    await page.mouse.move(box.x + box.width + 200, box.y + 400);
    await page.waitForFunction(
      () => document.querySelector('#side-nav')?.matches(':hover') === false,
      null, { timeout: 5000 });
    await wait(page, 1500);
    const apres = logins(cdn.slice(avant));
    ok('la passe reprend dès la sortie',
       apres.includes('quatre') && apres.includes('cinq'), apres.join(', '));
    await page.close();
  }

  // ── d) changement de tranche : le registre est purgé, la passe repart ────
  {
    const cdn = [];
    const page = await freshTwitch('<!doctype html><html><body>x</body></html>', cdn);
    await poser(page);
    await wait(page, 2000);
    const tranches1 = new Set(cdn.map(u => u.split('?_=')[1]));
    await wait(page, 4000);          // la tranche du harnais dure 3 s
    const tranches2 = new Set(cdn.map(u => u.split('?_=')[1]));
    ok('la passe repart à la tranche suivante', tranches2.size > tranches1.size,
       `${tranches1.size} → ${tranches2.size} tranche(s)`);
    // Sans purge du registre, la seconde tranche n'aurait rien redemandé.
    //
    // On ATTEND que la tranche la plus récente soit complète au lieu de la
    // prélever au vol : elle vient peut-être de commencer, et n'avoir que deux
    // chaînes sur trois à cet instant ne dit rien de la purge. L'attente est
    // bornée — si la purge n'a pas lieu, elle expire et l'assertion tombe avec
    // ce qui a été vu.
    let vus = new Set();
    for (let i = 0; i < 50; i++) {
      const tr = new Set(cdn.map(u => u.split('?_=')[1]));
      const derniere = [...tr].sort().pop();
      vus = new Set(logins(cdn.filter(u => u.endsWith(derniere))));
      if (['un', 'deux', 'trois'].every(l => vus.has(l))) break;
      await wait(page, 100);
    }
    ok('toutes les chaînes sont redemandées après la purge',
       ['un', 'deux', 'trois'].every(l => vus.has(l)), [...vus].join(', '));
    await page.close();
  }
}

// ═════════════ 34. Chaînes globales — couche de données ═════════════
titre('34. Chaînes globales — classer ce que l\'API refuse de classer');
{
  // Décor commun. 10 catégories d'amorce portant 40 streams (4000, 3900, …
  // 100 spectateurs, répartis en tourniquet), puis une 11e catégorie
  // AU-DESSUS du seuil et deux AU-DESSOUS.
  //
  //   T = 30e score après l'amorce      = 4000 − 29×100 = 1100
  //   « star » (2550) entre au classement → T monte à     1200
  //
  // Le stub rend `streams` EN DÉSORDRE, comme l'API réelle : si le module se
  // contentait de recopier l'ordre reçu, tout ce scénario tomberait.
  const decor = (page) => page.evaluate(() => {
    const cats = [];
    for (let i = 0; i < 10; i++) cats.push({ name: 'c' + i, viewers: 50_000 - i, streams: [] });
    for (let k = 0; k < 40; k++) {
      cats[k % 10].streams.push({ login: 's' + String(k).padStart(2, '0'),
                                  viewers: 4000 - k * 100 });
    }
    cats.push({ name: 'cAbove',  viewers: 5000, streams: [{ login: 'star',  viewers: 2550 }] });
    cats.push({ name: 'cBelow',  viewers: 900,  streams: [{ login: 'ghost', viewers: 900  }] });
    cats.push({ name: 'cBelow2', viewers: 500,  streams: [{ login: 'dust',  viewers: 500  }] });
    window.__cats = cats;
  });
  const catsAsked = (page) => page.evaluate(() => window.__calls.flatMap(c => c.cats || []));

  // ── a) la marche complète, et sa garantie d'exactitude ──────────────────
  {
    const page = await fresh();
    await decor(page);
    const rep = await page.evaluate(() => window.tse.global.on());
    ok('la marche s\'arrête sur la condition d\'exactitude, pas sur le budget',
       rep.complete === true, JSON.stringify(rep));
    ok('le seuil T vaut ce que l\'arithmétique prévoit', rep.threshold === 1200,
       String(rep.threshold));

    const top = await page.evaluate(() => window.tse.global.top(30).map(r => `${r.login}:${r.viewers}`));
    const nums = top.map(s => Number(s.split(':')[1]));
    ok('30 chaînes exactement', nums.length === 30, String(nums.length));
    ok('le classement est strictement décroissant — c\'est NOUS qui trions',
       nums.every((v, i) => !i || nums[i - 1] > v), top.join(' '));
    ok('la chaîne d\'une catégorie HORS amorce est bien montée au classement',
       top.some(s => s.startsWith('star:')), top.join(' '));
    ok('aucune chaîne des catégories sous T n\'apparaît',
       !top.some(s => /^(ghost|dust):/.test(s)), top.join(' '));

    // LE test d'exactitude : une catégorie sous T n'est pas seulement absente
    // du résultat, elle n'est même jamais INTERROGÉE. C'est là que se paie
    // l'inégalité viewers(stream) <= viewers(catégorie).
    const cats = await catsAsked(page);
    ok('les 10 catégories d\'amorce sont interrogées',
       [...Array(10).keys()].every(i => cats.includes('c' + i)), cats.join(','));
    ok('la 11e, au-dessus de T, l\'est aussi', cats.includes('cAbove'), cats.join(','));
    ok('celles sous T ne le sont JAMAIS',
       !cats.includes('cBelow') && !cats.includes('cBelow2'), cats.join(','));

    // Coût : deux requêtes groupées, et pas onze. Le découpage en deux est
    // inhérent — la descente a besoin du T calculé sur l'amorce.
    const posts = await page.evaluate(() => window.__calls
      .filter(c => (c.names || []).includes('TseCategoryTop')).length);
    ok('les 11 opérations catégorie tiennent en 2 requêtes groupées',
       posts === 2, String(posts));
    const forms = await page.evaluate(() => window.__calls
      .filter(c => (c.names || []).some(n => n === 'TseCategories' || n === 'TseCategoryTop'))
      .map(c => c.form));
    ok('aucune opération du mode global ne porte de hash',
       forms.length > 0 && forms.every(f => f === 'inline'), forms.join(','));
    await page.close();
  }

  // ── b) l'ordre rendu par `games` n'est pas cru sur parole ───────────────
  {
    const page = await fresh();
    await decor(page);
    // Le stub sert désormais la liste des catégories À L'ENVERS. Une API qui
    // viole déjà son contrat sur `streams` ne mérite pas qu'on lui fasse
    // confiance sur `games` : le module retrie, donc le résultat est le même.
    await page.evaluate(() => { window.__catsUnsorted = true; });
    const rep = await page.evaluate(() => window.tse.global.on());
    ok('même seuil malgré une liste de catégories servie à l\'envers',
       rep.threshold === 1200, String(rep.threshold));
    const cats = await catsAsked(page);
    ok('l\'amorce reste les 10 PLUS GROSSES catégories',
       [...Array(10).keys()].every(i => cats.includes('c' + i))
       && !cats.includes('cBelow2'), cats.join(','));
    const rows = await page.evaluate(() => window.tse.global.cats(13).map(c => c.viewers));
    ok('les catégories rendues à l\'appelant sont décroissantes',
       rows.every((v, i) => !i || rows[i - 1] >= v), rows.join(','));
    await page.close();
  }

  // ── c) passe légère : elle ne refait pas la marche ──────────────────────
  {
    const page = await fresh();
    await decor(page);
    await page.evaluate(() => window.tse.global.on());
    const avant = (await catsAsked(page)).length;
    // GLOBAL_STRUCT_TICK vaut 600 ms dans le harnais, la marche complète
    // 3 000 ms : la fenêtre observée ne contient donc que des passes légères.
    await wait(page, 1500);
    const apres = await catsAsked(page);
    const delta = apres.slice(avant);
    ok('une passe légère a bien eu lieu', delta.length > 0, String(delta.length));
    ok('elle n\'interroge que l\'amorce, pas toute la descente',
       delta.every(n => /^c[0-9]$/.test(n)), delta.join(','));
    await page.close();
  }

  // ── d) une catégorie qui franchit T est rattrapée au cycle suivant ──────
  {
    const page = await fresh();
    await decor(page);
    await page.evaluate(() => window.tse.global.on());
    ok('la chaîne dormante est absente au départ',
       !(await page.evaluate(() => window.tse.global.top(30).some(r => r.login === 'ghost'))));
    // cBelow explose : son total passe au-dessus de T, et son sommet avec.
    await page.evaluate(() => {
      const c = window.__cats.find(x => x.name === 'cBelow');
      c.viewers = 9000;
      c.streams = [{ login: 'ghost', viewers: 2000 }];
    });
    await wait(page, 1500);
    const cats = await catsAsked(page);
    ok('la catégorie qui vient de franchir T est interrogée',
       cats.includes('cBelow'), cats.join(','));
    const top = await page.evaluate(() => window.tse.global.top(30).map(r => `${r.login}:${r.viewers}`));
    ok('sa chaîne entre au classement, à sa place',
       top.includes('ghost:2000'), top.join(' '));
    // Décroissance LARGE et non stricte : deux chaînes peuvent parfaitement
    // afficher le même compteur, et l'exiger strict ferait échouer le test
    // sur une égalité légitime plutôt que sur un défaut de tri.
    const nums = top.map(s => Number(s.split(':')[1]));
    ok('le classement reste décroissant',
       nums.every((v, i) => !i || nums[i - 1] >= v), top.join(' '));
    await page.close();
  }

  // ── e) un compteur frais de TseChannels reclasse, sans requête de plus ──
  {
    const page = await fresh();
    await decor(page);
    // ORDRE IMPORTANT. La carte de s00 n'est posée qu'APRÈS la vérification
    // de l'état de départ. Elle l'était avant, et sa file TseChannels courait
    // alors contre la marche : sous charge, le compteur frais (12) arrivait
    // parfois AVANT l'assertion, qui trouvait s00 déjà rétrogradé et tombait.
    // Le défaut était dans la mise en scène, pas dans le classement — la
    // rétrogradation est précisément ce que le reste du bloc éprouve, il ne
    // faut donc pas la déclencher avant d'avoir constaté le point de départ.
    await page.evaluate(() => window.tse.global.on());
    ok('s00 est bien en tête après la marche',
       await page.evaluate(() => window.tse.global.top(1)[0]?.login) === 's00');
    // On fige la couche structurelle : seule la file TseChannels peut encore
    // faire bouger le classement. Sans ce gel, la marche suivante restaurerait
    // 4000 et le test mesurerait le hasard.
    const posts0 = await page.evaluate(() => {
      window.__globalFail = true;
      return window.__calls.length;
    });
    // MAINTENANT la sidebar apprend que s00 n'a plus que 12 spectateurs.
    await page.evaluate(() => {
      const h = new Date(Date.now() - 30 * 60_000).toISOString();
      window.__fx = { s00: { id: 'id-s00', createdAt: h, viewers: 12,
                             game: 'Just Chatting', tags: [] } };
      window.__addCard('s00', 'Just Chatting', '4 k');
    });
    await wait(page, 1200);
    const rang = await page.evaluate(() => {
      // 41 chaînes dans le pool (40 d'amorce + « star »). Demander 40
      // trancherait précisément celle qu'on cherche, une fois qu'elle est
      // tombée en dernière position.
      const t = window.tse.global.top(50);
      const i = t.findIndex(r => r.login === 's00');
      return { i, v: t[i]?.viewers ?? null, n: t.length };
    });
    ok('le compteur frais est appliqué', rang.v === 12, JSON.stringify(rang));
    ok('et il fait redescendre la chaîne au bon rang',
       rang.i === rang.n - 1, JSON.stringify(rang));
    // Aucune requête dédiée : le classement a voyagé dans le lot TseChannels.
    const dedies = await page.evaluate((n0) => window.__calls.slice(n0)
      .filter(c => (c.names || []).some(x => x === 'TseCategories' || x === 'TseCategoryTop'))
      .length, posts0);
    const lots = await page.evaluate((n0) => window.__calls.slice(n0)
      .filter(c => (c.names || []).includes('TseChannels')).length, posts0);
    ok('des lots TseChannels ont bien circulé', lots > 0, String(lots));
    ok('et le classement n\'a coûté aucune requête supplémentaire',
       dedies > 0, `${dedies} tentative(s) structurelle(s), toutes en échec forcé`);
    await page.close();
  }

  // ── e bis) fenêtre trop courte : le module refuse de se dire complet ────
  {
    // 100 catégories — la fenêtre entière — toutes AU-DESSUS du seuil. La
    // descente les visite toutes sans jamais croiser T, donc rien ne prouve
    // qu'une 101e catégorie, invisible, n'abrite pas un membre du top 30.
    // Le module doit le dire plutôt que de se déclarer exact.
    const page = await fresh();
    await page.evaluate(() => {
      window.__cats = [...Array(100)].map((_, i) => ({
        name: 'w' + i, viewers: 6000,
        streams: [5000, 4900, 4800, 4700].map((v, k) => ({ login: `w${i}_${k}`, viewers: v }))
      }));
    });
    const rep = await page.evaluate(() => window.tse.global.on());
    ok('le plancher de fenêtre est remonté', rep.windowFloor === 6000, JSON.stringify(rep));
    ok('il est au-dessus de T', rep.windowFloor > rep.threshold,
       `${rep.windowFloor} vs ${rep.threshold}`);
    ok('donc le classement n\'est PAS déclaré complet', rep.complete === false,
       JSON.stringify(rep));
    // Et il reste servi : incomplet ne veut pas dire inutilisable.
    const n = await page.evaluate(() => window.tse.global.top(30).length);
    ok('le classement reste servi malgré tout', n === 30, String(n));
    await page.close();
  }

  // ── g) échantillonnage de l'API : une absence isolée n'évince pas ───────
  {
    // MESURÉ en production : `streams(first: 30)` omet par intermittence une
    // chaîne qui devrait y figurer — rubius, 23 608 spectateurs, présent 4
    // appels sur 6 (●○●○●●). Sans tolérance, une telle chaîne clignoterait
    // dans le classement une passe sur trois.
    const page = await fresh();
    await decor(page);
    await page.evaluate(() => window.tse.global.on());
    const present = () => page.evaluate(() =>
      window.tse.global.top(40).some(r => r.login === 's00'));
    ok('la chaîne est au classement avant de disparaître des réponses', await present());

    // L'API cesse de la rendre. c0 est une catégorie d'amorce, donc chaque
    // passe légère l'interroge et constate l'absence.
    await page.evaluate(() => { window.__hidden = ['s00']; });
    // Passes à ~600 ms d'intervalle ; GLOBAL_MISS_CONFIRM en exige trois.
    await wait(page, 900);
    ok('une absence ne suffit pas à l\'évincer', await present());
    await wait(page, 600);
    ok('deux non plus', await present());
    await wait(page, 1100);
    ok('trois d\'affilée, en revanche, l\'évincent', !(await present()));
    const rep = await page.evaluate(() => window.tse.global.report());
    ok('les absences sont comptées dans le rapport', rep.misses >= 3, JSON.stringify(rep));
    ok('et l\'éviction aussi', rep.evicted >= 1, JSON.stringify(rep));

    // Elle revient dès que l'API la rend de nouveau — c'est bien une
    // tolérance, pas une liste noire.
    await page.evaluate(() => { window.__hidden = []; });
    await wait(page, 1200);
    ok('elle revient dès que l\'API la rend à nouveau', await present());
    await page.close();
  }

  // ── h) ne pas regarder n'est pas constater ──────────────────────────────
  {
    // « star » vit dans cAbove, que la passe légère n'interroge PAS : cette
    // catégorie n'est ni dans l'amorce, ni en train de franchir T. Son absence
    // des réponses ne doit donc RIEN compter contre elle.
    const page = await fresh();
    await decor(page);
    await page.evaluate(() => window.tse.global.on());
    await page.evaluate(() => { window.__hidden = ['star']; });
    // Quatre passes légères tiennent dans cette fenêtre — et la marche
    // complète, seule à redescendre jusqu'à cAbove, n'arrive qu'à 3 000 ms.
    await wait(page, 2400);
    const cats = await page.evaluate(() => window.__calls.flatMap(c => c.cats || []));
    const apresAmorce = cats.slice(11);   // au-delà de la marche initiale
    ok('les passes légères n\'ont pas interrogé sa catégorie',
       !apresAmorce.includes('cAbove'), apresAmorce.join(','));
    ok('elle reste donc au classement, intacte',
       await page.evaluate(() => window.tse.global.top(40).some(r => r.login === 'star')));
    await page.close();
  }

  // ── f) panne confinée : la sidebar suivie ne tombe pas avec le global ───
  {
    const page = await fresh();
    await decor(page);
    const warns = [];
    page.on('console', m => { if (m.type() === 'warning') warns.push(m.text()); });
    await page.evaluate(() => {
      const h = new Date(Date.now() - 30 * 60_000).toISOString();
      window.__fx = { alpha: { id: 'id-alpha', createdAt: h, viewers: 777,
                               game: 'Just Chatting', tags: [] } };
      window.__addCard('alpha', 'Just Chatting', '100');
      window.__globalFail = true;           // le global échoue dès le départ
      window.tse.global.on();
    });
    // GLOBAL_ERROR_COOLDOWN vaut 1 500 ms ici, et il faut GLOBAL_FAIL_DEGRADE
    // (3) échecs consécutifs pour que la cadence se replie.
    await wait(page, 5200);
    const rep = await page.evaluate(() => window.tse.global.report());
    ok('la cadence structurelle se replie d\'elle-même', rep.degraded === true,
       JSON.stringify(rep));
    ok('et le repli est annoncé en console', warns.some(w => /\[tse\]/.test(w)),
       warns.join(' | '));
    ok('le classement reste vide plutôt que faux', rep.pool === 0, String(rep.pool));
    // L'invariant qui compte : la sidebar « Chaînes suivies » n'a rien vu.
    const carte = await page.evaluate(() => {
      const c = [...document.querySelectorAll('.side-nav-card')]
        .find(x => x.dataset.tseLogin === 'alpha');
      return c ? nzText(c) : null;
      function nzText(card) { return card.querySelector('.tse-viewers')?.textContent ?? null; }
    });
    ok('la sidebar suivie continue de se rafraîchir normalement',
       nz(carte) === '777', String(carte));
    await page.close();
  }
}

// ═════════════ 35. Top Chaînes — la bascule et les cartes ═════════════
const S_MENU_ARIA = 'Choisir ce qui s\'affiche dans la barre latérale';
titre('35. Top Chaînes — basculer, afficher, revenir');
{
  const poser = (page) => page.evaluate(() => {
    const h = new Date(Date.now() - 30 * 60_000).toISOString();
    window.__fx = {
      suivi1: { id: 'id-suivi1', createdAt: h, viewers: 400, game: 'Just Chatting', tags: [] },
      suivi2: { id: 'id-suivi2', createdAt: h, viewers: 300, game: 'Just Chatting', tags: [] },
    };
    window.__addCard('suivi1', 'Just Chatting', '400');
    window.__addCard('suivi2', 'Just Chatting', '300');
    // Une carte dans la section de recommandation « Chaînes live ».
    window.__fx.reco1 = { id: 'id-reco1', createdAt: h, viewers: 90,
                          game: 'Just Chatting', tags: [] };
    window.__addReco('reco1', 'Just Chatting', '90');
    // Un classement mondial volontairement petit et sans ambiguïté.
    window.__cats = [
      { name: 'g1', viewers: 90_000, streams: [
        { login: 'alpha', viewers: 50_000 }, { login: 'bravo', viewers: 30_000 }] },
      { name: 'g2', viewers: 40_000, streams: [
        { login: 'charlie', viewers: 25_000 }, { login: 'delta', viewers: 9_000 }] },
      { name: 'g3', viewers: 20_000, streams: [{ login: 'echo', viewers: 12_000 }] },
    ];
  });
  // La bascule est un onglet dans NOTRE bloc filtre. Pas de menu à ouvrir,
  // donc pas d'étape intermédiaire — un seul clic, toujours au même endroit.
  const clic = (page, mode) => page.evaluate((m) => {
    const b = document.querySelector(`#tse-mode-row [data-tse-mode="${m}"]`);
    if (!b) throw new Error('onglet de mode absent : ' + m);
    b.click();
  }, mode);
  const vue = (page) => page.evaluate(() => ({
    titre: document.querySelector('#side-nav .side-nav__title h3')?.textContent?.trim(),
    // L'en-tête natif doit rester masqué dans les deux modes.
    enteteMasque: document.querySelector('.followed-side-nav-header')
                    ?.getAttribute('data-tse-native-header') === 'hidden',
    actif: [...document.querySelectorAll('#tse-mode-row [data-tse-mode]')]
      .filter(b => b.getAttribute('aria-pressed') === 'true')
      .map(b => b.dataset.tseMode),
    mode:  document.body.classList.contains('tse-global-mode'),
    ready: document.body.classList.contains('tse-global-ready'),
    natif: window.__nativeSortOpened,
    // Cartes réellement VISIBLES, dans l'ordre du DOM.
    visibles: [...document.querySelectorAll('.side-nav-card')]
      .filter(c => getComputedStyle(c).display !== 'none')
      .map(c => c.dataset.tseLogin),
  }));

  {
    const page = await fresh();
    await poser(page);
    await wait(page, 1600);

    // ── a) le contrôle nous appartient, et Twitch n'est pas touché ───────
    // Largeur réelle de la barre latérale étendue de Twitch : c'est la seule
    // condition dans laquelle « libellé entier » veut dire quelque chose.
    await page.evaluate(() => {
      const nav = document.getElementById('side-nav');
      nav.style.width = '240px';
      nav.style.boxSizing = 'border-box';
      nav.style.padding = '0 8px';
    });
    await wait(page, 300);
    const ui = await page.evaluate(() => {
      const row = document.getElementById('tse-mode-row');
      const bar = document.getElementById('tse-filter');
      const cs = (el) => {
        const s = getComputedStyle(el);
        return { fond: s.backgroundColor, image: s.backgroundImage, couleur: s.color };
      };
      const actif   = row?.querySelector('[data-tse-mode][aria-pressed="true"]');
      const inactif = row?.querySelector('[data-tse-mode][aria-pressed="false"]');
      return row ? {
        dansFiltre: row.parentElement?.id === 'tse-filter',
        premier: bar?.firstElementChild?.id === 'tse-mode-row',
        aria: row.getAttribute('aria-label'),
        // La bascule doit former UNE piste, à la même trame verticale que la
        // rangée de filtres juste en dessous.
        hauteur: Math.round(row.getBoundingClientRect().height),
        hauteurFiltres: Math.round(
          bar?.querySelector('.tse-filter-row')?.getBoundingClientRect().height || 0),
        filet: getComputedStyle(row).borderTopWidth,
        fondPiste: getComputedStyle(row).backgroundColor,
        actif:   actif   ? cs(actif)   : null,
        inactif: inactif ? cs(inactif) : null,
        onglets: [...row.querySelectorAll('[data-tse-mode]')].map(b => ({
          mode: b.dataset.tseMode,
          label: b.textContent,
          presse: b.getAttribute('aria-pressed'),
          // Débordement horizontal : > 0 signifie libellé coupé.
          coupe: b.scrollWidth - b.clientWidth })),
      } : null;
    });
    ok('la bascule est posée', !!ui, 'absente');
    ok('dans notre bloc filtre, que React ne reconstruit pas',
       ui?.dansFiltre === true, JSON.stringify(ui));
    ok('et en tête du bloc, juste sous la rangée des stories',
       ui?.premier === true, JSON.stringify(ui));
    ok('le groupe annonce son rôle', ui?.aria === S_MENU_ARIA, ui?.aria);
    // Un contrôle segmenté, et non deux pastilles flottantes : la rangée
    // porte elle-même une surface et un filet, comme les listes déroulantes.
    ok('la bascule forme une piste, pas deux boutons posés sur le fond',
       ui?.filet === '1px' && ui?.fondPiste !== 'rgba(0, 0, 0, 0)',
       JSON.stringify({ filet: ui?.filet, fond: ui?.fondPiste }));
    ok('et elle s\'aligne sur la hauteur de la rangée de filtres',
       ui?.hauteur === ui?.hauteurFiltres,
       `bascule ${ui?.hauteur}px / filtres ${ui?.hauteurFiltres}px`);
    // Le mode courant doit se voir SANS lire le texte : l'invariant est que
    // les deux segments ne peuvent pas avoir le même rendu.
    ok('le segment actif se distingue du segment inactif',
       !!ui?.actif && !!ui?.inactif &&
       JSON.stringify(ui.actif) !== JSON.stringify(ui.inactif),
       JSON.stringify({ actif: ui?.actif, inactif: ui?.inactif }));
    ok('deux onglets, dans cet ordre',
       ui?.onglets.map(o => o.mode).join(',') === 'followed,global',
       JSON.stringify(ui?.onglets));
    ok('avec les libellés attendus',
       ui?.onglets.map(o => o.label).join(' | ') === 'Chaînes suivies | Top Chaînes',
       JSON.stringify(ui?.onglets));
    // LE point demandé : aucun libellé tronqué, à largeur réelle de sidebar.
    ok('aucun libellé n\'est coupé, à 240 px de barre latérale',
       ui?.onglets.every(o => o.coupe <= 0),
       JSON.stringify(ui?.onglets.map(o => o.label + ':' + o.coupe)));
    // Les deux libellés FRANÇAIS tiennent de toute façon : mesurer ceux-là
    // ne prouve rien sur la mise en page. On éprouve donc la RÈGLE, avec un
    // libellé plus long que ne le sera jamais aucune traduction.
    const large = await page.evaluate(() => {
      const b = document.querySelector('#tse-mode-row [data-tse-mode="followed"]');
      const avant = b.textContent;
      b.textContent = 'Kanäle, denen du folgst und mehr';
      void b.offsetWidth;                       // force le recalcul
      const coupe = b.scrollWidth - b.clientWidth;
      b.textContent = avant;
      return coupe;
    });
    ok('et la mise en page ne coupe pas même un libellé démesuré',
       large <= 0, `débordement de ${large}px`);
    // Un onglet ne doit JAMAIS porter le nom d'une section : DOM.followedSelector
    // cherche aria-label="Chaînes suivies" et prendrait le bouton pour la
    // section suivie — la sidebar se croirait alors vide.
    ok('aucun onglet n\'usurpe le libellé d\'une section',
       await page.evaluate(() => ![...document.querySelectorAll('#tse-mode-row [data-tse-mode]')]
         .some(b => b.hasAttribute('aria-label'))));
    ok('et la section suivie reste correctement identifiée',
       await page.evaluate(() => document.querySelector('[aria-label="Chaînes suivies"]')
         ?.querySelectorAll('.side-nav-card').length) === 2);
    ok('le mode courant est marqué actif',
       ui?.onglets[0].presse === 'true' && ui?.onglets[1].presse === 'false',
       JSON.stringify(ui?.onglets));

    // La rangée des stories : visible en mode suivi, masquée en Top Chaînes.
    const storiesVisible = () => page.evaluate(() => {
      const el = document.querySelector('[data-tse-stories="row"]');
      return el ? getComputedStyle(el).display !== 'none' : null;
    });
    ok('la rangée des stories est repérée', await storiesVisible() !== null);
    ok('et reste visible sur les chaînes suivies', await storiesVisible() === true);
    // Twitch ne lui pose de marge qu'en haut (0,7rem, en ligne) : sans la
    // nôtre en bas, elle touche le bloc filtre. Mesuré en pixels calculés,
    // donc à l'échelle réelle de Twitch (racine à 62,5 % → 0,7rem = 7px).
    ok('elle respire autant en dessous qu\'au-dessus',
       await page.evaluate(() => {
         const cs = getComputedStyle(document.querySelector('[data-tse-stories="row"]'));
         return cs.marginBottom === cs.marginTop && cs.marginBottom === '7px';
       }),
       await page.evaluate(() => {
         const cs = getComputedStyle(document.querySelector('[data-tse-stories="row"]'));
         return `haut ${cs.marginTop} / bas ${cs.marginBottom}`;
       }));
    ok('le bloc marqué porte bien la vignette ET le libellé',
       await page.evaluate(() => {
         const el = document.querySelector('[data-tse-stories="row"]');
         return !!el?.querySelector('img') && /stories/i.test(el.textContent || '');
       }));
    ok('et il ne contient aucune carte',
       await page.evaluate(() => !document.querySelector('[data-tse-stories="row"] .side-nav-card')));

    // L'en-tête natif — titre ET bouton de tri — est masqué : plus de tri
    // Twitch en concurrence du nôtre, et plus de titre redondant.
    ok('l\'en-tête natif de Twitch est masqué',
       await page.evaluate(() => document.querySelector('.followed-side-nav-header')
         ?.getAttribute('data-tse-native-header') === 'hidden'));
    /* ── ASSERTION TOURNÉE PAR LA 4.12 ────────────────────────────────────
       Elle exigeait que le titre racine ne porte AUCUN bouton, et elle avait
       raison de le faire : la version qui y avait ancré la bascule de mode
       passait son temps à lutter contre React, qui remonte ce titre à chaque
       navigation — d'où la rangée d'onglets, dans un bloc que l'extension
       possède.

       LA 4.12 Y POSE UN BOUTON, ET UN SEUL : la roue qui ouvre le panneau.
       Ce qui était protégé n'était pas « zéro bouton » mais « pas de bascule
       de mode ici », et cette leçon-là tient toujours. L'assertion le dit
       maintenant en toutes lettres, au lieu de compter à zéro.

       ON NE COMPTE QUE LES NÔTRES. La 4.12.1 a donné à ce décor le bouton de
       repli que Twitch y range vraiment — c'est ce qui manquait pour voir que
       la roue se posait après lui. Compter TOUS les boutons du bloc
       reviendrait donc à compter ceux de Twitch, et à échouer le jour où ils
       en ajoutent un troisième qui ne nous regarde pas. */
    ok('le titre racine ne porte qu\'un bouton à nous, la roue, et aucune bascule de mode',
       await page.evaluate(() => {
         const bloc = document.querySelector('#side-nav .side-nav__title');
         const notres = [...bloc.querySelectorAll('button')]
           .filter((b) => b.id.startsWith('tse-') || b.className.includes('tse-'));
         return notres.length === 1
             && notres[0].id === 'tse-roue'
             && !notres[0].hasAttribute('data-tse-mode')
             /* Et le bouton de Twitch est TOUJOURS LÀ : on s'ajoute à son
                bloc, on ne le remplace pas. */
             && !!bloc.querySelector('#native-collapse');
       }));
    // On ne touche plus au bouton de Twitch : ni instrumentation, ni clic.
    ok('le bouton de tri natif n\'est plus instrumenté',
       await page.evaluate(() => !document.querySelector('[data-tse-mode-trigger]')));
    ok('et son gestionnaire n\'est jamais déclenché',
       await page.evaluate(() => window.__nativeSortOpened) === 0);

    // Recliquer l'onglet actif ne bascule pas : un mode est toujours actif.
    await clic(page, 'followed');
    ok('recliquer le mode actif est sans effet',
       await page.evaluate(() => !document.body.classList.contains('tse-global-mode')));

    const avant = await vue(page);
    ok('on part bien des chaînes suivies', avant.titre === 'Chaînes suivies', avant.titre);
    ok('et elles sont visibles',
       avant.visibles.includes('suivi1') && avant.visibles.includes('suivi2'),
       avant.visibles.join(','));

    // Un mode de tri non pertinent est choisi AVANT de basculer : le
    // classement mondial ne doit pas s'y soumettre. En alphabétique, « delta »
    // passerait devant « echo » — alors qu'il a moins de spectateurs.
    await page.evaluate(() =>
      document.querySelector('[data-tse-sort-mode="alpha"]')?.click());
    await wait(page, 300);

    // ── b) la bascule ────────────────────────────────────────────────────
    await clic(page, 'global');
    await wait(page, 1200);
    const apres = await vue(page);
    ok('le titre racine porte le nom du mode', apres.titre === 'Top Chaînes', apres.titre);
    ok('l\'en-tête natif reste masqué', apres.enteteMasque === true);
    ok('l\'onglet Top Chaînes devient actif',
       apres.actif.join(',') === 'global', apres.actif.join(','));
    ok('le menu natif n\'a toujours pas été atteint', apres.natif === 0, String(apres.natif));
    ok('la rangée des stories disparaît en Top Chaînes',
       await storiesVisible() === false);
    // Les sections de recommandation de Twitch parlent de ce que l'utilisateur
    // SUIT : elles n'ont plus de rapport avec un classement mondial.
    const recoVisible = () => page.evaluate(() => {
      const sec = document.querySelector('.side-nav-section[aria-label="Chaînes live"]');
      return sec ? getComputedStyle(sec).display !== 'none' : null;
    });
    ok('les sections de recommandation sont masquées', await recoVisible() === false);
    ok('la ligne des modes de tri est masquée',
       await page.evaluate(() => {
         const r = document.getElementById('tse-sort-row');
         return !r || getComputedStyle(r).display === 'none';
       }));

    // ── c) les cartes du classement, dans l'ordre ────────────────────────
    ok('le classement est prêt', apres.ready === true, JSON.stringify(apres));
    ok('les cartes affichées sont celles du classement, dans l\'ordre',
       apres.visibles.join(',') === 'alpha,bravo,charlie,echo,delta',
       apres.visibles.join(','));
    ok('aucune chaîne suivie ne reste visible',
       !apres.visibles.includes('suivi1') && !apres.visibles.includes('suivi2'),
       apres.visibles.join(','));
    // Le compteur ne doit PAS être celui de la carte qui a servi de modèle.
    const compteur = await page.evaluate(() => {
      const c = [...document.querySelectorAll('.side-nav-card')]
        .find(x => x.dataset.tseLogin === 'alpha');
      return c?.querySelector('.tse-viewers')?.textContent ?? null;
    });
    ok('chaque carte porte SON compteur, pas celui du modèle',
       nz(compteur) === '50 k', String(compteur));

    // ── d) retour ────────────────────────────────────────────────────────
    await clic(page, 'followed');
    await wait(page, 600);
    const retour = await vue(page);
    ok('le titre revient', retour.titre === 'Chaînes suivies', retour.titre);
    ok('l\'onglet Chaînes suivies redevient actif',
       retour.actif.join(',') === 'followed', retour.actif.join(','));
    ok('le mode de tri choisi avant la bascule est retrouvé intact',
       await page.evaluate(() =>
         document.querySelector('[data-tse-sort-mode="alpha"]')?.getAttribute('aria-pressed'))
         === 'true');
    ok('la rangée des stories revient avec les chaînes suivies',
       await storiesVisible() === true);
    ok('et les sections de recommandation aussi', await recoVisible() === true);
    ok('les chaînes suivies réapparaissent',
       retour.visibles.includes('suivi1') && retour.visibles.includes('suivi2'),
       retour.visibles.join(','));
    ok('et les cartes du classement sont retirées du DOM',
       await page.evaluate(() =>
         document.querySelectorAll('.side-nav-card[data-tse-global="true"]').length) === 0);

    // ── e) re-bascule sur un classement REFROIDI ─────────────────────────
    // Le pool n'est pas purgé en sortant du mode : y revenir reconstruit les
    // cartes à partir d'enregistrements dont l'horodatage a dépassé LIVE_TTL.
    // Le cache est alors périmé, la file TseChannels ne connaît pas ces
    // chaînes — et sans compteur écrit à la fabrication, chaque carte
    // afficherait celui de la chaîne qui lui a servi de modèle.
    // La couche structurelle est gelée : sans ce gel, la re-bascule
    // relancerait une marche qui, avec un stub instantané, rafraîchirait les
    // horodatages en 1 ms — et le cas « à froid » n'existerait jamais.
    await page.evaluate(() => { window.__globalFail = true; });
    await wait(page, 1500);          // > LIVE_TTL : les enregistrements refroidissent
    await clic(page, 'global');
    await wait(page, 400);           // court : avant qu'une nouvelle marche ne rafraîchisse
    const froid = await page.evaluate(() => {
      const c = [...document.querySelectorAll('.side-nav-card')]
        .find(x => x.dataset.tseLogin === 'alpha');
      return { compteur: c?.querySelector('.tse-viewers')?.textContent ?? null,
               // Texte brut joint au message d'échec : sans lui, un `null`
               // ne dirait pas QUEL chiffre s'affiche à la place.
               brut: (c?.textContent || '').replace(/\s+/g, ' ').trim() };
    });
    ok('même reconstruite à froid, la carte porte SON compteur',
       nz(froid.compteur) === '50 k', JSON.stringify(froid));
    await page.close();
  }

  // ── e) le bandeau d'honnêteté ────────────────────────────────────────────
  {
    const page = await fresh();
    await poser(page);
    await wait(page, 1600);
    await clic(page, 'global');
    await wait(page, 1200);
    ok('classement prouvé complet → aucun bandeau',
       await page.evaluate(() => !document.getElementById('tse-global-partial')));
    await page.close();
  }
  {
    // 100 catégories toutes au-dessus du seuil : la fenêtre est trop courte,
    // le classement est servi mais ne peut pas être déclaré complet.
    const page = await fresh();
    await page.evaluate(() => {
      window.__fx = {};
      window.__addCard('suivi1', 'Just Chatting', '400');
      window.__cats = [...Array(100)].map((_, i) => ({
        name: 'w' + i, viewers: 6000,
        streams: [5000, 4900, 4800, 4700].map((v, k) => ({ login: `w${i}_${k}`, viewers: v }))
      }));
    });
    await wait(page, 1600);
    await clic(page, 'global');
    await wait(page, 1500);
    const texte = await page.evaluate(() =>
      document.getElementById('tse-global-partial')?.textContent ?? null);
    ok('classement non prouvé complet → le bandeau le dit', !!texte, 'absent');
    ok('et il le dit dans la langue de l\'interface',
       (texte || '').startsWith('Classement partiel'), String(texte));
    await page.close();
  }
  // ── g) la bascule est couverte par le voile, pas subie à nu ─────────────
  {
    const page = await fresh();
    await poser(page);
    await page.evaluate(() => { window.__catDelay = 250; });
    await wait(page, 1600);                    // voile de démarrage levé
    ok('le voile de démarrage est bien retombé',
       await page.evaluate(() => !document.body.classList.contains('tse-loading')));

    // On observe un ORDRE, pas un état à un instant choisi. Prélever « le voile
    // est-il encore là ? » 450 ms après le clic revenait à parier que la
    // marche n'a pas fini — et sous charge, c'est le PRÉLÈVEMENT qui arrive en
    // retard, pas la marche qui va vite. Le témoin ci-dessous date les deux
    // événements dans la page elle-même : la question « le voile a-t-il tenu
    // jusqu'au classement ? » se répond alors sans dépendre d'aucune horloge
    // extérieure.
    await page.evaluate(() => {
      window.__ordre = { pret: null, leve: null };
      const t0 = Date.now();
      const mo = new MutationObserver(() => {
        const c = document.body.classList;
        if (window.__ordre.pret === null && c.contains('tse-global-ready')) {
          window.__ordre.pret = Date.now() - t0;
        }
        if (window.__ordre.leve === null && !c.contains('tse-loading')) {
          window.__ordre.leve = Date.now() - t0;
        }
      });
      mo.observe(document.body, { attributes: true, attributeFilter: ['class'] });
      document.querySelector('#tse-mode-row [data-tse-mode="global"]').click();
    });
    ok('le voile se lève dès le clic',
       await page.evaluate(() => document.body.classList.contains('tse-loading')));

    // Sans le verrou, le voile retomberait AVANT le classement : la liste des
    // chaînes suivies est peuplée et stable, donc « présentable » au sens du
    // cycle de boot — alors même que le classement n'existe pas encore.
    await attendre(page, () => window.__ordre.leve !== null, 8000);
    const ordre = await page.evaluate(() => window.__ordre);
    ok('il tient tant que le classement n\'est pas rendu',
       ordre.pret !== null && ordre.leve !== null && ordre.pret <= ordre.leve,
       JSON.stringify(ordre));

    await wait(page, 1400);
    const apres = await page.evaluate(() => ({
      voile: document.body.classList.contains('tse-loading'),
      cartes: document.querySelectorAll('.side-nav-card[data-tse-global="true"]').length,
    }));
    ok('puis retombe une fois les cartes posées',
       apres.voile === false, JSON.stringify(apres));
    ok('et le classement est bien là', apres.cartes > 0, JSON.stringify(apres));

    // Revenir est instantané : les cartes suivies n'ont jamais quitté le DOM.
    await clic(page, 'followed');
    ok('le retour ne rappelle aucun voile',
       await page.evaluate(() => !document.body.classList.contains('tse-loading')));
    await page.close();
  }

  // ── h) plus aucune chaîne suivie en direct : le mode marche quand même ──
  {
    // Le modèle de carte est cloné d'une carte native EN DIRECT. Sans mémoire
    // du modèle, un utilisateur dont personne ne streame ne verrait RIEN dans
    // Top Chaînes — alors que le classement mondial est parfaitement connu.
    const page = await fresh();
    await poser(page);
    await wait(page, 1500);
    await clic(page, 'global');
    await wait(page, 1200);
    ok('le classement s\'affiche une première fois',
       await page.evaluate(() =>
         document.querySelectorAll('.side-nav-card[data-tse-global="true"]').length) > 0);

    await clic(page, 'followed');
    await wait(page, 400);
    // Toutes les cartes natives disparaissent du DOM : plus un seul modèle.
    await page.evaluate(() => {
      document.querySelectorAll('.side-nav-card').forEach(c => {
        if (c.dataset.tseGlobal !== 'true') c.remove();
      });
    });
    await wait(page, 400);
    ok('il ne reste aucune carte native à cloner',
       await page.evaluate(() => ![...document.querySelectorAll('.side-nav-card')]
         .some(c => c.dataset.tseGlobal !== 'true' && c.dataset.tseSynthetic !== 'true')));

    await clic(page, 'global');
    await wait(page, 1200);
    const n = await page.evaluate(() =>
      document.querySelectorAll('.side-nav-card[data-tse-global="true"]').length);
    ok('le classement s\'affiche quand même, grâce au modèle mémorisé',
       n > 0, `${n} carte(s)`);
    await page.close();
  }

}


// ═════════════ 36. Top Chaînes — le filtre catégorie ═════════════
titre('36. Catégories — choisir, ce n\'est pas filtrer');
{
  // Décor conçu autour d'UN point : « petite » est sous le seuil T, donc la
  // marche mondiale ne l'interroge JAMAIS et ses chaînes n'existent nulle
  // part dans le classement du monde. Si elles apparaissent après sélection,
  // c'est nécessairement qu'une requête dédiée est partie — un filtre sur les
  // cartes présentes ne pourrait pas les inventer.
  const decor36 = (page) => page.evaluate(() => {
    const h = new Date(Date.now() - 30 * 60_000).toISOString();
    window.__fx = {
      suivi1: { id: 'id-suivi1', createdAt: h, viewers: 400, game: 'Just Chatting', tags: [] },
    };
    window.__addCard('suivi1', 'Just Chatting', '400');
    const cats = [];
    for (let i = 0; i < 10; i++) cats.push({ name: 'c' + i, viewers: 50_000 - i, streams: [] });
    for (let k = 0; k < 40; k++) {
      cats[k % 10].streams.push({ login: 's' + String(k).padStart(2, '0'),
                                  viewers: 4000 - k * 100 });
    }
    cats.push({ name: 'petite', viewers: 900, streams: [
      { login: 'cache1', viewers: 900 }, { login: 'cache2', viewers: 800 }] });
    window.__cats = cats;
  });
  const choisirCat = (page, val) => page.evaluate((v) => {
    const opt = [...document.querySelectorAll('#tse-cat-dd .tse-dd-opt')]
      .find(o => (o.dataset.value || '') === v);
    if (!opt) throw new Error('option absente : ' + JSON.stringify(v));
    opt.click();
  }, val);
  const logins = (page) => page.evaluate(() =>
    [...document.querySelectorAll('.side-nav-card[data-tse-global="true"]')]
      .map(c => c.dataset.tseLogin));

  const page = await fresh();
  await decor36(page);
  await wait(page, 1500);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await wait(page, 1500);

  // ── a) la liste des catégories ─────────────────────────────────────────
  const dd = await page.evaluate(() =>
    [...document.querySelectorAll('#tse-cat-dd .tse-dd-opt')]
      .filter(o => o.dataset.value)
      .map(o => ({ val: o.dataset.value,
                   n: o.querySelector('.tse-dd-n')?.textContent?.trim(),
                   label: o.querySelector('.tse-dd-name')?.textContent })));
  ok('les catégories sont proposées', dd.length === 11, String(dd.length));
  ok('classées par audience décroissante',
     dd.map(o => o.val).join(',') === 'c0,c1,c2,c3,c4,c5,c6,c7,c8,c9,petite',
     dd.map(o => o.val).join(','));
  ok('le compteur est une AUDIENCE, pas un nombre de chaînes',
     nz(dd[0].n) === '50 k |', dd[0].n);
  ok('même pour une petite catégorie', nz(dd[10].n) === '900 |', dd[10].n);
  ok('le libellé est le nom canonique, celui que portent les cartes',
     dd[10].label === 'petite', dd[10].label);

  // ── b) les chaînes de « petite » n'existent pas dans le monde ──────────
  const monde = await logins(page);
  ok('le classement mondial est servi', monde.length === 30, String(monde.length));
  ok('et il ignore totalement les chaînes de « petite »',
     !monde.includes('cache1') && !monde.includes('cache2'), monde.join(','));
  const catsVues = await page.evaluate(() => window.__calls.flatMap(c => c.cats || []));
  ok('sa catégorie n\'a même jamais été interrogée',
     !catsVues.includes('petite'), catsVues.join(','));

  // ── c) sélectionner la catégorie déclenche une requête dédiée ──────────
  const avant = await page.evaluate(() => window.__calls.length);
  await choisirCat(page, 'petite');
  ok('le voile couvre le changement de catégorie',
     await page.evaluate(() => document.body.classList.contains('tse-loading')));
  await wait(page, 1500);
  const apres = await logins(page);
  ok('les chaînes de la catégorie sont affichées',
     apres.join(',') === 'cache1,cache2', apres.join(','));
  ok('et rien du classement mondial ne subsiste',
     !apres.some(l => /^s\d\d$/.test(l)), apres.join(','));
  const req = await page.evaluate((n0) => window.__calls.slice(n0)
    .filter(c => (c.names || []).includes('TseCategoryTop'))
    .map(c => ({ cats: c.cats, firsts: c.firsts })), avant);
  ok('une requête dédiée est bien partie', req.length > 0, JSON.stringify(req));
  ok('elle porte sur la catégorie choisie, et sur elle seule',
     req.every(r => r.cats.length === 1 && r.cats[0] === 'petite'), JSON.stringify(req));
  ok('et demande le maximum autorisé par l\'API, soit 30',
     req.every(r => r.firsts.every(n => n === 30)), JSON.stringify(req));
  ok('le voile est retombé', await page.evaluate(() =>
     !document.body.classList.contains('tse-loading')));

  // ── d) revenir à « toutes » est IMMÉDIAT : le pool n'a pas été purgé ───
  await choisirCat(page, '');
  ok('revenir à toutes les catégories ne voile pas',
     await page.evaluate(() => !document.body.classList.contains('tse-loading')));
  // 150 ms : le temps d'un debounce de scan, très loin d'un aller-retour de
  // marche complète. Si les 30 cartes sont là, elles viennent du pool
  // conservé, pas d'une requête. Mesurer « aucune requête » serait faux ici :
  // le harnais accélère la marche complète à 3 s, donc en relancer une après
  // quelques secondes de test est le comportement CORRECT — ce serait un
  // artefact d'accélération, pas un défaut.
  await wait(page, 150);
  const retour = await logins(page);
  ok('le classement mondial est servi immédiatement, sans attendre le réseau',
     retour.length === 30 && !retour.includes('cache1'), retour.join(','));

  // ── e) en mode suivi, le compteur reste un nombre de chaînes ──────────
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="followed"]').click());
  await wait(page, 600);
  const ddSuivi = await page.evaluate(() =>
    [...document.querySelectorAll('#tse-cat-dd .tse-dd-opt')]
      .filter(o => o.dataset.value)
      .map(o => o.querySelector('.tse-dd-n')?.textContent?.trim()));
  ok('le mode suivi retrouve ses décomptes de chaînes',
     ddSuivi.length === 1 && nz(ddSuivi[0]) === '1 |', JSON.stringify(ddSuivi));
  await page.close();
}


// ═════════════ 37. Voile — un seul cycle au chargement ═════════════
titre('37. Voile — la sidebar ne doit s\'initialiser qu\'une fois');
{
  const cycles = (page) => page.evaluate(() => window.tse.global && window.tse
    ? (window.tse.cycles ? window.tse.cycles() : []) : []);

  // ── a) sidebar déjà présente : un seul cycle, nommé ────────────────────
  {
    const page = await fresh();
    await wait(page, 2000);
    const j = await page.evaluate(() => window.tse.cycles());
    const démarrages = j.filter(e => e.evt === 'cycle');
    ok('un seul cycle de voile au chargement', démarrages.length === 1,
       JSON.stringify(j));
    ok('et il s\'appelle « démarrage »', démarrages[0]?.detail === 'démarrage',
       JSON.stringify(démarrages));
    await page.close();
  }

  // ── b) sidebar montée APRÈS le démarrage, en mode réduit ───────────────
  {
    // Le cas qui casse : au démarrage de l'extension, #side-nav n'existe pas
    // encore, donc l'état « réduit » se lit comme « étendu » par défaut. Quand
    // la sidebar arrive RÉDUITE, la comparaison voit une bascule qui n'a
    // jamais eu lieu et déclenche voile + purge du cache + re-scan complet —
    // l'utilisateur voit la sidebar s'initialiser deux fois.
    const page = await browser.newPage();
    page.on('pageerror', e => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
    await page.addInitScript(() => { window.__lateMount = true; window.__lateCollapsed = true; });
    await page.goto(URL_PAGE);
    await wait(page, 2000);
    const j = await page.evaluate(() => window.tse.cycles());
    const bascules = j.filter(e => e.detail === 'bascule réduit/étendu');
    ok('la sidebar est bien arrivée après le démarrage, et réduite',
       await page.evaluate(() => !!document.querySelector('.side-nav--collapsed #side-nav')));
    ok('aucune fausse bascule réduit/étendu n\'est déclenchée',
       bascules.length === 0, JSON.stringify(j));
    await page.close();
  }

  // ── c) une VRAIE bascule, elle, déclenche bien un cycle ────────────────
  {
    // La garde ne doit pas rendre la détection aveugle : après la ligne de
    // base, un changement réel doit toujours provoquer la ré-initialisation.
    const page = await fresh();
    await wait(page, 1800);
    const avant = await page.evaluate(() =>
      window.tse.cycles().filter(e => e.evt === 'cycle').length);
    await page.evaluate(() => {
      document.getElementById('root').classList.add('side-nav--collapsed');
      // L'observateur ne surveille PAS les attributs : poser une classe ne
      // déclenche rien par soi-même. Twitch, lui, RECONSTRUIT ses cartes en
      // basculant — c'est cette mutation-là qui porte la détection, et le
      // test doit la reproduire au lieu de compter sur un remous voisin.
      const d = document.createElement('div');
      document.getElementById('cards').appendChild(d);
      d.remove();
    });
    await wait(page, 600);
    const j = await page.evaluate(() => window.tse.cycles());
    ok('une bascule réelle relance bien un cycle',
       j.filter(e => e.evt === 'cycle').length === avant + 1, JSON.stringify(j));
    ok('et elle est nommée pour ce qu\'elle est',
       j.some(e => e.detail === 'bascule réduit/étendu'), JSON.stringify(j));
    await page.close();
  }
}


// ═════════════ 38. Monde + langue — une descente, pas un filtre ═════════════
titre('38. Monde + langue — descendre en langue, pas filtrer un pool');
{
  // Le décor rend les deux approches DISCERNABLES, et c'est tout son objet.
  // Chaque grosse catégorie contient 30 chaînes anglaises devant 10 françaises
  // plus petites : la récolte toutes langues, plafonnée à 30 par l'API, ne
  // ramène donc AUCUNE française. Filtrer ce pool ne peut rendre que les trois
  // françaises de « frcat », seule catégorie où elles tiennent dans le top 30.
  // Une descente menée EN LANGUE, elle, demande à chaque catégorie son sommet
  // français et en trouve trente.
  const decor38 = (page) => page.evaluate(() => {
    const h = new Date(Date.now() - 30 * 60_000).toISOString();
    window.__fx = { suivi1: { id: 'id-suivi1', createdAt: h, viewers: 400,
                              game: 'Just Chatting', tags: [] } };
    window.__addCard('suivi1', 'Just Chatting', '400');
    const cats = [];
    for (let i = 0; i < 9; i++) {
      const streams = [];
      for (let k = 0; k < 30; k++) {
        streams.push({ login: `en${i}_${k}`, viewers: 9000 - i * 100 - k, tags: ['English'] });
      }
      for (let k = 0; k < 10; k++) {
        streams.push({ login: `fr${i}_${k}`, viewers: 3000 - i * 100 - k * 10, tags: ['Français'] });
      }
      cats.push({ name: 'c' + i, viewers: 500_000 - i, streams });
    }
    // Seule catégorie dont le top 30 toutes langues contient du français :
    // c'est elle qui fait exister « Français » dans la liste des langues.
    cats.push({ name: 'frcat', viewers: 499_990, streams: [
      { login: 'vis1', viewers: 100, tags: ['Français'] },
      { login: 'vis2', viewers: 90,  tags: ['Français'] },
      { login: 'vis3', viewers: 80,  tags: ['Français'] },
    ] });
    window.__cats = cats;
  });
  const logins = (page) => page.evaluate(() =>
    [...document.querySelectorAll('.side-nav-card[data-tse-global="true"]')]
      .map(c => c.dataset.tseLogin));
  const choisirLangue = (page, val) => page.evaluate((v) => {
    const opt = [...document.querySelectorAll('#tse-lang-dd .tse-dd-opt')]
      .find(o => (o.dataset.value || '') === v);
    if (!opt) throw new Error('langue absente : ' + JSON.stringify(v));
    opt.click();
  }, val);

  const page = await fresh();
  await decor38(page);
  await wait(page, 1500);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await wait(page, 1800);

  // ── a) le classement toutes langues ────────────────────────────────────
  const monde = await logins(page);
  ok('le classement mondial sert 30 chaînes', monde.length === 30, String(monde.length));
  ok('et elles sont anglaises, les françaises étant hors des top 30',
     monde.every(l => l.startsWith('en')), monde.slice(0, 3).join(','));
  ok('le classement est annoncé complet',
     await page.evaluate(() => window.tse.global.report().complete) === true);

  // ── b) « Français » est proposable, grâce au pool TOUTES LANGUES ───────
  const opts = await page.evaluate(() =>
    [...document.querySelectorAll('#tse-lang-dd .tse-dd-opt')]
      .filter(o => o.dataset.value).map(o => o.dataset.value));
  ok('la langue est proposée bien qu\'absente du top 30',
     opts.includes('Français'), opts.join(','));

  // ── c) la descente en langue ───────────────────────────────────────────
  await choisirLangue(page, 'Français');
  await wait(page, 2000);
  const fr = await logins(page);
  ok('trente chaînes françaises, et non les trois du pool',
     fr.length === 30, String(fr.length));
  ok('toutes françaises', fr.every(l => /^(fr\d|vis)/.test(l)), fr.slice(0, 3).join(','));
  // LE point : ces chaînes n'existaient nulle part dans le pool toutes
  // langues. Un filtre, quel qu'il soit, ne pouvait pas les inventer.
  ok('dont des chaînes que le pool toutes langues ne contenait pas',
     fr.some(l => !monde.includes(l) && l.startsWith('fr')), fr.join(','));
  ok('classées par audience', await page.evaluate(() => {
    const v = [...document.querySelectorAll('.side-nav-card[data-tse-global="true"]')]
      .map(c => Number(c.dataset.tseViewers));
    return v.every((x, i) => !i || v[i - 1] >= x);
  }));
  ok('la plus grosse est bien la plus grosse française',
     fr[0] === 'fr0_0', fr[0]);

  // ── d) l'exactitude est REVENDIQUÉE, car l'API a filtré ───────────────
  const rep = await page.evaluate(() => window.tse.global.report());
  ok('l\'API est créditée du filtre', rep.langApplied === true, JSON.stringify(rep));
  ok('et le classement reste annoncé complet', rep.complete === true, JSON.stringify(rep));
  ok('aucun bandeau d\'approximation',
     await page.evaluate(() => !document.getElementById('tse-global-partial')));

  // ── d bis) une langue non demandable dégrade, elle ne vide pas ─────────
  // Le stub ne connaît que FR, EN et DE : « IT » lui arrache la même erreur
  // qu'un code absent du schéma de Twitch. La descente ne peut alors pas
  // aboutir — et le pire serait qu'elle soit réclamée quand même, laissant la
  // barre latérale vide en attendant un classement qui n'arrivera jamais.
  await choisirLangue(page, '');
  await wait(page, 1200);
  await page.evaluate(() => {
    // « Italiano » n'est pas dans le pool : on l'y injecte le temps du test,
    // via une catégorie supplémentaire visible dans le top 30.
    window.__cats.push({ name: 'itcat', viewers: 499_985, streams: [
      { login: 'it1', viewers: 70, tags: ['Italiano'] }] });
  });
  await wait(page, 2000);
  const dispo = await page.evaluate(() =>
    [...document.querySelectorAll('#tse-lang-dd .tse-dd-opt')].map(o => o.dataset.value));
  ok('la langue non demandable est bien proposée', dispo.includes('Italiano'),
     dispo.join(','));
  await choisirLangue(page, 'Italiano');
  await wait(page, 2500);
  const it = await logins(page);
  ok('la barre latérale n\'est PAS vide', it.length > 0, String(it.length));
  ok('elle sert le repli par tags', it.every(l => l.startsWith('it')), it.join(','));
  ok('et cesse de revendiquer l\'exactitude',
     await page.evaluate(() => window.tse.global.report().complete) === false);

  // ── e) revenir à « toutes les langues » est instantané ─────────────────
  await choisirLangue(page, '');
  ok('aucun voile au retour',
     await page.evaluate(() => !document.body.classList.contains('tse-loading')));
  await wait(page, 150);
  const retour = await logins(page);
  ok('le classement toutes langues est servi sans attendre le réseau',
     retour.length === 30 && retour.every(l => l.startsWith('en')), retour.slice(0, 3).join(','));
  await page.close();
}

// ═════════════ 39. Catégorie + langue — une requête dédiée ═════════════
titre('39. Catégorie + langue — demander, pas filtrer');
{
  // MESURÉ sur quatre catégories réelles : `game(name:){ streams(options:
  // {broadcasterLanguages:[FR]}) }` rend LE SOMMET FRANÇAIS de la catégorie.
  // Aucune chaîne française du top 30 brut ne manque, et la requête en révèle
  // 23 à 29 de plus. Filtrer les trente cartes n'en laissait que sept.
  //
  // Le décor pousse le contraste à l'extrême : les 30 plus grosses chaînes de
  // la catégorie sont TOUTES anglaises. Filtrer l'affichage donnerait zéro
  // résultat ; demander à l'API en donne trente.
  const decor39 = (page) => page.evaluate(() => {
    const h = new Date(Date.now() - 30 * 60_000).toISOString();
    window.__fx = { suivi1: { id: 'id-suivi1', createdAt: h, viewers: 400,
                              game: 'Just Chatting', tags: [] } };
    window.__addCard('suivi1', 'Just Chatting', '400');
    const streams = [];
    for (let i = 0; i < 30; i++) streams.push({ login: 'en' + i, viewers: 9000 - i * 10, tags: ['English'] });
    for (let i = 0; i < 30; i++) streams.push({ login: 'fr' + i, viewers: 3000 - i * 10, tags: ['Français'] });
    window.__cats = [
      { name: 'grosse', viewers: 400_000, streams },
      // Une seconde catégorie porte du français : c'est elle qui fait
      // apparaître « Français » dans le pool mondial, donc dans la liste des
      // langues proposables. Sans elle, la langue qu'on veut demander à
      // « grosse » ne serait proposée nulle part.
      { name: 'autre',  viewers: 10_000, streams: [
        { login: 'x1', viewers: 500, tags: ['English'] },
        { login: 'x2', viewers: 400, tags: ['Français'] },
        // L'italien sert au test de repli : le stub ne connaît que FR, EN et
        // DE, donc « IT » lui arrache la même erreur qu'un code absent du
        // schéma de Twitch.
        { login: 'x3', viewers: 300, tags: ['Italiano'] },
      ] },
    ];
  });
  const logins = (page) => page.evaluate(() =>
    [...document.querySelectorAll('.side-nav-card[data-tse-global="true"]')]
      .map(c => c.dataset.tseLogin));
  const choisir = (page, sel, val) => page.evaluate(([s, v]) => {
    const opt = [...document.querySelectorAll(s + ' .tse-dd-opt')]
      .find(o => (o.dataset.value || '') === v);
    if (!opt) throw new Error('option absente : ' + v);
    opt.click();
  }, [sel, val]);

  const page = await fresh();
  await decor39(page);
  await wait(page, 1500);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await wait(page, 1200);
  await choisir(page, '#tse-cat-dd', 'grosse');
  await wait(page, 1200);

  const brut = await logins(page);
  ok('la catégorie sert ses 30 plus grosses chaînes',
     brut.length === 30 && brut.every(l => l.startsWith('en')), brut.slice(0, 3).join(','));
  ok('dont aucune française', !brut.some(l => l.startsWith('fr')));

  await choisir(page, '#tse-lang-dd', 'Français');
  await wait(page, 1200);
  const fr = await logins(page);
  ok('choisir la langue rend 30 chaînes, pas zéro', fr.length === 30, String(fr.length));
  ok('et elles sont toutes françaises',
     fr.every(l => l.startsWith('fr')), fr.slice(0, 3).join(','));
  ok('classées par audience', await page.evaluate(() => {
    const v = [...document.querySelectorAll('.side-nav-card[data-tse-global="true"]')]
      .map(c => Number(c.dataset.tseViewers));
    return v.every((x, i) => !i || v[i - 1] >= x);
  }));

  // La requête porte bien l'option, et sur la seule catégorie choisie.
  const req = await page.evaluate(() => window.__calls
    .filter(c => (c.names || []).includes('TseCategoryTop'))
    .slice(-3).map(c => ({ cats: c.cats, fr: /broadcasterLanguages/.test(c.q || '') })));
  ok('une requête de catégorie a bien été émise', req.length > 0, JSON.stringify(req));

  // C'est bien l'API qui a filtré : le classement reste annoncé EXACT, alors
  // qu'un filtre par pool sous langue renoncerait à la complétude.
  ok('l\'exactitude reste revendiquée, car l\'API a filtré elle-même',
     await page.evaluate(() => window.tse.global.report().langApplied) === true);

  await choisir(page, '#tse-lang-dd', '');
  await wait(page, 800);
  ok('retirer la langue rend les 30 plus grosses',
     (await logins(page)).every(l => l.startsWith('en')));

  // ── Repli : un code de langue refusé par le schéma ─────────────────────
  // Ma table LANG_API est écrite d'après l'ISO 639-1 ; si Twitch nommait une
  // langue autrement, la requête entière échouerait. Le module doit
  // l'apprendre UNE fois et retomber sur le filtre par tags, pas répéter
  // indéfiniment une requête vouée à l'échec.
  const avantIT = await page.evaluate(() => window.__calls.length);
  await choisir(page, '#tse-lang-dd', 'Italiano');
  await wait(page, 2000);
  const tentatives = await page.evaluate((k) => window.__calls.slice(k)
    .flatMap(c => c.langs || []).filter(l => l === 'IT').length, avantIT);
  /* ZÉRO, ET NON PLUS UN — ET C'EST UN PROGRÈS, PAS UN RELÂCHEMENT.
     Le relevé qui remplit les chiffres des menus interroge toutes les langues
     d'une catégorie, donc TOUS les codes, dès la première catégorie choisie.
     Il apprend là ceux que le schéma refuse, et les partage avec la descente
     par `langApiRejected`. Quand l'utilisateur choisit enfin l'italien, son
     code est déjà connu mauvais : plus une seule requête ne part avec lui.

     L'invariant que cette ligne tenait — « on n'insiste pas sur un code
     refusé » — est donc éprouvé PLUS FORT qu'avant : non pas une fois, mais
     zéro. Et il ne peut pas passer à vide : les trois assertions qui suivent
     exigent que le repli ait bien eu lieu et que la barre soit peuplée. */
  ok('un code déjà connu refusé n\'est plus jamais renvoyé', tentatives === 0,
     `${tentatives} tentative(s)`);
  ok('et la portée est bien re-demandée sans lui',
     await page.evaluate(() => window.tse.global.report().langApplied) === false);
  ok('le classement n\'est plus annoncé exact',
     await page.evaluate(() => window.tse.global.report().complete) === false);
  ok('rien n\'a planté : le module répond toujours',
     await page.evaluate(() => Array.isArray(window.tse.global.top(30))));

  await choisir(page, '#tse-lang-dd', '');
  await wait(page, 1000);
  ok('et l\'on retrouve la catégorie complète',
     (await logins(page)).length === 30);

  // ── Une COUPURE RÉSEAU ne vaut pas un rejet du serveur ─────────────────
  // Les deux se ressemblent — dans les deux cas la requête ne rend rien —
  // mais un rejet est un verdict sur la requête, une coupure n'apprend rien.
  // Les confondre condamnerait la langue pour toute la session sur un simple
  // hoquet réseau.
  await page.evaluate(() => { window.__failLang = 1; });
  const avantNet = await page.evaluate(() => window.__calls.length);
  await choisir(page, '#tse-lang-dd', 'Français');
  await wait(page, 3000);          // > GLOBAL_ERROR_COOLDOWN du harnais
  const essaisFR = await page.evaluate((k) => window.__calls.slice(k)
    .flatMap(c => c.langs || []).filter(l => l === 'FR').length, avantNet);
  ok('la langue est REDEMANDÉE après la coupure', essaisFR >= 2,
     `${essaisFR} tentative(s)`);
  const apresNet = await logins(page);
  ok('et le classement français finit par s\'afficher',
     apresNet.length === 30 && apresNet.every(l => l.startsWith('fr')),
     apresNet.slice(0, 3).join(','));
  ok('l\'API est bien créditée du filtre',
     await page.evaluate(() => window.tse.global.report().langApplied) === true);
  await page.close();
}

// ═════════════ 40. Top Chaînes — ni trou dans la liste, ni barre en travers ═════════════
titre('40. Top Chaînes — ce qui est demandé s\'affiche, et rien ne déborde');
{
  // Deux défauts observés en mode « Top Chaînes », de même racine : le code
  // continuait de traiter le classement comme une liste de chaînes suivies —
  // à filtrer, et dont les cartes masquées seraient encore là.
  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 30 * 60_000).toISOString();
    // Deux chaînes SUIVIES, en co-stream Guest Star avéré.
    window.__fx = {
      mastu:  { id: '63936838',  createdAt: h, viewers: 10616, game: 'Just Chatting', tags: [] },
      // Audience PROPRE choisie au-dessus du compteur combiné de mastu, tout
      // comme son propre combiné : quel que soit l'instant où la réponse Guest
      // Star arrive, hctuan se classe entre le dernier « fr » et les cartes
      // « mastu ». C'est ce qui rend l'adjacence — donc la mesure de la
      // jointure — reproductible d'une exécution à l'autre.
      hctuan: { id: '175560856', createdAt: h, viewers: 11900, game: 'Just Chatting', tags: [] },
    };
    const guests = [
      { id: '63936838',  login: 'mastu',  viewers: 10616, combined: 11736 },
      { id: '175560856', login: 'hctuan', viewers: 11900, combined: 11821 },
    ];
    window.__gs = {
      '63936838':  { hostId: '63936838', hostLogin: 'mastu', guests },
      '175560856': { hostId: '63936838', hostLogin: 'mastu', guests },
    };
    window.__addCard('mastu',  'Just Chatting', '11 k');
    window.__addCard('hctuan', 'Just Chatting', '11,9 k');

    // Le classement mondial. « fr* » DIFFUSE en français sans porter le tag
    // « Français » — c'est le cas courant, et exactement ce que Twitch sert
    // quand on demande broadcasterLanguages: [FR]. « tag1 » porte le tag :
    // c'est lui, et lui seul, qui fait exister « Français » dans la liste des
    // langues proposées (laquelle se lit sur le pool TOUTES LANGUES).
    const frs = [];
    for (let k = 0; k < 6; k++) {
      frs.push({ login: 'fr' + k, viewers: 30_000 - k * 1_000, lang: 'FR', tags: [] });
      // Ces chaînes RÉPONDENT aussi à TseChannels, qui fait autorité sur les
      // tags et rafraîchit toute carte affichée. Sans cette moitié du décor,
      // le tag posé par la descente survivrait indéfiniment et le défaut
      // resterait invisible.
      window.__fx['fr' + k] = { id: 'id-fr' + k, createdAt: h,
                                viewers: 30_000 - k * 1_000, game: 'g1', tags: [] };
    }
    window.__cats = [
      { name: 'g1', viewers: 90_000, streams: [
        { login: 'en1',  viewers: 50_000, tags: ['English'] },
        { login: 'tag1', viewers: 31_000, tags: ['Français'] },
        ...frs,
        // Une des deux chaînes suivies figure AUSSI au classement français :
        // le mode global lui fabrique alors une carte, tandis que la carte
        // native de Twitch reste là, masquée. Deux cartes pour une chaîne,
        // même clé de co-stream, l'une visible et l'autre non — la situation
        // qui produisait une barre de plusieurs centaines de pixels.
        { login: 'mastu', viewers: 11_000, lang: 'FR', tags: [] },
      ] },
    ];
  });
  await wait(page, 1500);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await wait(page, 1800);
  await page.evaluate(() => {
    const opt = [...document.querySelectorAll('#tse-lang-dd .tse-dd-opt')]
      .find(o => (o.dataset.value || '') === 'Français');
    if (!opt) throw new Error('« Français » absent de la liste des langues');
    opt.click();
  });
  await wait(page, 2500);

  const etat = () => page.evaluate(() => [...document.querySelectorAll('.side-nav-card')].map(c => ({
    login:   c.dataset.tseLogin,
    global:  c.dataset.tseGlobal === 'true',
    affiche: getComputedStyle(c).display !== 'none',
    cle:     c.dataset.tseCostreamKey || null,
    barre:   c.classList.contains('tse-costream'),
    h:       c.getBoundingClientRect().height,
    jt:      c.style.getPropertyValue('--tse-costream-jt'),
    jb:      c.style.getPropertyValue('--tse-costream-jb'),
  })));

  // ── a) une carte sans boîte n'est pas un membre de co-stream ───────────
  // L'invariant est énoncé sur le style CALCULÉ : c'est la seule façon de
  // vérifier que notre prédicat interne dit bien la même chose que la règle
  // CSS de classe qu'il recopie.
  const g0 = await etat();
  ok('le classement est bien à l\'écran au moment de la mesure',
     g0.filter(c => c.global && c.affiche).length >= 7,
     JSON.stringify(g0.map(c => [c.login, c.affiche])));
  const fantomes = g0.filter(c => !c.affiche && (c.cle || c.barre));
  ok('aucune carte masquée ne porte de marque de co-stream',
     fantomes.length === 0, JSON.stringify(fantomes));
  ok('et toute carte colorée est bien à l\'écran',
     g0.filter(c => c.cle).every(c => c.affiche),
     JSON.stringify(g0.filter(c => c.cle)));
  /* ── CE QUE LA 4.19 A RENVERSÉ ICI, ET POURQUOI C'EST PLUS FORT ─────────
     CETTE ASSERTION TENAIT « la carte de mastu n'est pas colorée toute
     seule » : hctuan ne diffuse pas en français, le filtre l'écartait du
     classement, et colorer mastu seul aurait annoncé un co-stream dont on ne
     montre pas l'autre moitié. L'utilisateur a tranché autrement — un
     co-stream amputé par le filtre est un co-stream faux — et depuis la 4.19
     la place se complète SOUS filtre de langue, chaque membre hors langue
     portant le drapeau de la sienne. Hctuan revient donc, mastu n'est plus
     seul, et exiger le contraire serait désormais exiger le défaut.

     ELLE EXIGE DÉSORMAIS L'INVERSE, ET C'EST MESURÉ. Hctuan ne figure NULLE
     PART dans `__cats` : sous filtre « Français » il ne peut arriver à
     l'écran que par la complétion de la place. Mutant posé et mesuré — un
     `if (state.languageFilter) return presents;` en tête de `completer`,
     c'est-à-dire le retour exact à la 4.18.1 — et la ligne tombe : plus
     aucun groupe à l'écran, hctuan disparu, mastu seul. C'est mot pour mot la
     capture « le co-stream devrait être composé de trois streamers, là il n'y
     en a que deux ».

     CE QUE JE N'AI PAS ÉCRIT ICI, ET POURQUOI. J'avais d'abord ajouté deux
     clauses générales — « aucune carte colorée n'est seule dans son groupe »
     et « toute carte portant la clé porte la couleur ». Vérification faite
     dans le code, ni l'une ni l'autre ne peut tomber : un groupe ne se
     constitue que de cartes `cardShown`, il n'est retenu qu'à partir de deux
     membres, et la classe et la clé sont posées sur la même carte dans la
     même boucle. Deux assertions vertes par construction valent moins que
     rien — elles font croire qu'on surveille. */
  const visibles = g0.filter(c => c.affiche);
  const tailleGroupe = new Map();
  for (const c of visibles) {
    if (!c.cle) continue;
    tailleGroupe.set(c.cle, (tailleGroupe.get(c.cle) || 0) + 1);
  }
  ok('sous filtre de langue, la place se complète et le groupe se dessine à deux',
     tailleGroupe.get('gs:63936838') === 2
     && visibles.some(c => c.login === 'hctuan' && c.barre),
     JSON.stringify({ groupes: [...tailleGroupe],
                      vus: visibles.map(c => [c.login, c.cle, c.barre]) }));

  // ── b) aucune barre ne déborde de sa carte ─────────────────────────────
  // L'extension d'une barre vaut la moitié de l'interstice entre deux cartes
  // voisines : quelques pixels. Mesurée contre un rectangle nul — celui d'une
  // carte masquée par une classe — elle valait la moitié de la page, soit un
  // trait vertical en travers de tout le classement.
  const debords = [];
  for (const c of g0) {
    for (const [nom, v] of [['jt', c.jt], ['jb', c.jb]]) {
      if (!v) continue;
      const px = Math.abs(parseFloat(v));
      if (px > Math.max(c.h, 1)) debords.push({ login: c.login, nom, px, h: c.h });
    }
  }
  ok('aucune barre ne s\'étend au-delà de la hauteur d\'une carte',
     debords.length === 0, JSON.stringify(debords));

  // ── c) le classement demandé s'affiche EN ENTIER ───────────────────────
  // La langue a été appliquée par l'API. La descente pose le tag canonique sur
  // ses enregistrements, mais TseChannels fait autorité sur les tags et le
  // remplace par les freeformTags réels — ici, aucun. En régime nominal la
  // marche réécrit l'entrée juste avant qu'elle ne périme (LIVE_TTL et
  // GLOBAL_STRUCT_TICK valent tous deux 30 s) : la fenêtre existe, mais elle
  // est étroite et l'attendre rendrait le test capricieux. On la force donc
  // en coupant les marches — l'entrée cesse d'être rafraîchie, périme, et
  // TseChannels reprend la main. C'est le même état, atteint à coup sûr.
  await page.evaluate(() => { window.__globalFail = true; });
  // Le témoin est la RÉPONSE elle-même : dès que TseChannels a parlé de ces
  // chaînes, le cache partagé porte leurs tags réels — aucun — et c'est cet
  // état-là que le filtre de langue voyait.
  let ecrase = false;
  for (let i = 0; i < 60 && !ecrase; i++) {
    ecrase = await page.evaluate(() => {
      const dits = new Set(window.__calls.flatMap(c => c.ops || []));
      return [0, 1, 2, 3, 4, 5].every(k => dits.has('fr' + k));
    });
    if (!ecrase) await wait(page, 200);
  }
  ok('TseChannels a répondu sur les chaînes du classement, sans tag de langue',
     ecrase);

  const g = await etat();
  const vus = g.filter(c => c.affiche).map(c => c.login);
  const attendus = ['tag1', 'fr0', 'fr1', 'fr2', 'fr3', 'fr4', 'fr5', 'mastu'];
  ok('le classement français reste affiché en entier',
     attendus.every(l => vus.includes(l)),
     `manquantes : ${attendus.filter(l => !vus.includes(l)).join(',') || '—'} / vues : ${vus.join(',')}`);
  ok('et aucune chaîne anglaise ne s\'y est glissée', !vus.includes('en1'), vus.join(','));
  ok('les cartes suivies, elles, restent effacées',
     g.filter(c => !c.global && c.affiche).length === 0,
     JSON.stringify(g.filter(c => !c.global && c.affiche)));

  // ── d) le retour en mode suivi rend le co-stream intact ────────────────
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="followed"]').click());
  await wait(page, 1200);
  const f = await etat();
  const parLogin = Object.fromEntries(f.filter(c => !c.global).map(c => [c.login, c]));
  ok('les deux co-streamers sont de nouveau regroupés',
     !!parLogin.mastu?.cle && parLogin.mastu.cle === parLogin.hctuan?.cle,
     JSON.stringify([parLogin.mastu, parLogin.hctuan]));
  ok('et bien colorés', parLogin.mastu?.barre === true && parLogin.hctuan?.barre === true,
     JSON.stringify([parLogin.mastu, parLogin.hctuan]));
  ok('la jointure est de quelques pixels, pas de quelques centaines',
     Math.abs(parseFloat(parLogin.mastu.jb || parLogin.mastu.jt || '0')) <= parLogin.mastu.h,
     JSON.stringify(parLogin.mastu));
  await page.close();
}

// ═════════ 41. Le classement n'écrit pas dans le cache des chaînes suivies ═════════
titre('41. Cache — le mode global ne doit rien laisser derrière lui');
{
  // « mastu » est SUIVI et figure AUSSI au classement français. Deux
  // conséquences à vérifier, l'une visuelle et l'autre invisible :
  //   • une seule carte doit le servir — celle de Twitch, empruntée, et non
  //     une contrefaçon posée à côté d'une carte native masquée ;
  //   • la descente en langue pose le tag « Français » sur SON enregistrement
  //     (l'API vient d'affirmer la langue de diffusion), alors que TseChannels
  //     ne lui connaît aucun tag. Ce tag ne doit pas survivre au mode : sinon
  //     la chaîne repart rangée sous un filtre de langue qu'elle n'a jamais
  //     porté, dans une liste qui n'a rien demandé au classement.
  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 30 * 60_000).toISOString();
    window.__fx = {
      mastu: { id: 'id-mastu', createdAt: h, viewers: 12000, game: 'Just Chatting', tags: [] },
      zeta:  { id: 'id-zeta',  createdAt: h, viewers: 300,   game: 'Just Chatting', tags: ['English'] },
    };
    window.__addCard('mastu', 'Just Chatting', '12 k');
    window.__addCard('zeta',  'Just Chatting', '300');
    window.__cats = [{ name: 'g1', viewers: 90_000, streams: [
      { login: 'tag1',  viewers: 31_000, tags: ['Français'] },   // fait exister « Français »
      { login: 'mastu', viewers: 12_000, lang: 'FR', tags: [] }, // diffuse en FR, sans le tag
    ] }];
  });
  await wait(page, 1500);

  // ── a) en mode suivi, la langue proposée est celle des tags réels ───────
  const avant = await page.evaluate(() => ({
    langs: [...document.querySelectorAll('.side-nav-card')]
      .filter(c => c.dataset.tseLogin === 'mastu').map(c => c.dataset.tseLangs),
    options: [...document.querySelectorAll('#tse-lang-dd .tse-dd-opt')].map(o => o.dataset.value),
  }));
  ok('au départ, la chaîne suivie ne porte aucune langue',
     avant.langs.every(l => l === ''), JSON.stringify(avant));
  ok('et « Français » n\'est pas proposé dans la liste suivie',
     !avant.options.includes('Français'), avant.options.join(','));

  // ── b) une seule carte par chaîne dans le classement ───────────────────
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await wait(page, 1800);
  await page.evaluate(() => {
    const opt = [...document.querySelectorAll('#tse-lang-dd .tse-dd-opt')]
      .find(o => (o.dataset.value || '') === 'Français');
    if (!opt) throw new Error('« Français » absent de la liste des langues');
    opt.click();
  });
  await wait(page, 2500);
  const cartes = await page.evaluate(() =>
    [...document.querySelectorAll('.side-nav-card')]
      .filter(c => c.dataset.tseLogin === 'mastu')
      .map(c => ({ synthetique: c.dataset.tseSynthetic === 'true',
                   global: c.dataset.tseGlobal === 'true',
                   affiche: getComputedStyle(c).display !== 'none' })));
  ok('une seule carte sert la chaîne, pas deux', cartes.length === 1, JSON.stringify(cartes));
  ok('et c\'est celle de Twitch, empruntée plutôt que contrefaite',
     cartes[0]?.synthetique === false && cartes[0]?.global === true && cartes[0]?.affiche === true,
     JSON.stringify(cartes));

  // ── c) rien de tout cela ne doit rester en sortant ──────────────────────
  // On coupe TseChannels — et lui seul — avant de sortir, puis on attend une
  // marche complète de plus. L'horodatage du cache partagé est alors figé
  // pendant que celui du classement avance : c'est la condition exacte dans
  // laquelle une amorce écrite dans ce cache prend le dessus sur la réponse
  // de Twitch, et elle ne survient autrement qu'au hasard d'une course.
  // La coupure sert aussi après la bascule : plus rien ne peut effacer la
  // trace, donc ce que porte le cache est exactement ce que le mode global y
  // a laissé.
  const marches = () => page.evaluate(() => window.tse.global.report().walks);
  const avantMarche = await marches();
  await page.evaluate(() => { window.__failChannels = true; });
  for (let i = 0; i < 60 && (await marches()) <= avantMarche; i++) await wait(page, 200);
  ok('une marche a bien eu lieu pendant que TseChannels était coupé',
     (await marches()) > avantMarche, `${avantMarche} → ${await marches()}`);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="followed"]').click());
  await wait(page, 1500);
  const apres = await page.evaluate(() => {
    const cs = [...document.querySelectorAll('.side-nav-card')]
      .filter(c => c.dataset.tseLogin === 'mastu');
    return {
      n: cs.length,
      synthetique: cs.map(c => c.dataset.tseSynthetic === 'true'),
      marque: cs.map(c => c.dataset.tseGlobal ?? null),
      affiche: cs.map(c => getComputedStyle(c).display !== 'none'),
      langs: cs.map(c => c.dataset.tseLangs),
      options: [...document.querySelectorAll('#tse-lang-dd .tse-dd-opt')].map(o => o.dataset.value),
    };
  });
  ok('la carte native est rendue, pas supprimée',
     apres.n === 1 && apres.synthetique[0] === false && apres.affiche[0] === true,
     JSON.stringify(apres));
  ok('elle ne porte plus la marque du classement',
     apres.marque[0] === null, JSON.stringify(apres));
  // LE point : le tag posé par la descente ne doit pas avoir déteint.
  ok('la chaîne suivie ne repart pas avec un tag posé par la descente',
     !(apres.langs[0] || '').includes('Français'), JSON.stringify(apres));
  ok('et la liste suivie ne propose toujours pas « Français »',
     !apres.options.includes('Français'), apres.options.join(','));
  await page.close();
}

// ═════════ 42. Abonnements — lus sur la page, jamais demandés ═════════
titre('42. Abonnements — le tri « mes abos en tête », sans une requête');
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  // Ce scénario éprouve la lecture PAR VISITE. Le relevé complet, testé
  // au scénario 43, verserait ses propres chaînes et fausserait les comptes.
  const SANS_PAGE = () => { window.__noSubsPage = true; };
  const decor = (page) => page.evaluate(() => {
    const h = (m) => new Date(Date.now() - m * 60_000).toISOString();
    window.__fx = {
      gros:      { id:'1', createdAt:h(120), viewers:9000, game:'Just Chatting', tags:[] },
      moyen:     { id:'2', createdAt:h(90),  viewers:4000, game:'Just Chatting', tags:[] },
      omofficial:{ id:'3', createdAt:h(30),  viewers:120,  game:'Just Chatting', tags:[] },
    };
    window.__addCard('gros',       'Just Chatting', '9 k');
    window.__addCard('moyen',      'Just Chatting', '4 k');
    window.__addCard('omofficial', 'Just Chatting', '120');
  });
  const boutons = (page) => page.evaluate(() =>
    [...document.querySelectorAll('#tse-sort-row button[data-tse-sort-mode]')]
      .map(b => ({ mode: b.dataset.tseSortMode, off: b.disabled, titre: b.title })));
  const ordre = (page) => page.evaluate(() =>
    [...document.querySelectorAll('#side-nav .side-nav-card')].map(c => c.dataset.tseLogin));

  // ── a) rien de connu : le bouton est là, à sa place, et il est grisé ────
  {
    const page = await freshTwitch(PLAYER, [], '/', SANS_PAGE);
    await decor(page);
    await wait(page, 1800);
    const b = await boutons(page);
    ok('six modes de tri, dans l\'ordre attendu',
       b.map(x => x.mode).join(',') === 'viewers,subs,popular,uptime,alpha,costream',
       b.map(x => x.mode).join(','));
    const sub = b.find(x => x.mode === 'subs');
    // Sans une seule chaîne repérée, le tri ne trierait rien : il doit se
    // griser et DIRE pourquoi, plutôt que d'offrir un bouton inerte.
    ok('grisé tant qu\'aucun abonnement n\'est repéré', sub?.off === true, JSON.stringify(sub));
    ok('et le survol explique pourquoi',
       /abonnement/i.test(sub?.titre || ''), sub?.titre);
    await page.close();
  }

  // ── b) sur la page d'une chaîne abonnée, l'extension le relève ──────────
  {
    const page = await freshTwitch(PLAYER, [], '/omofficial', SANS_PAGE);
    await decor(page);
    // Le marqueur MESURÉ sur Twitch : abonné → data-a-target="manage-sub-button".
    await page.evaluate(() => {
      const b = document.createElement('button');
      b.setAttribute('data-a-target', 'manage-sub-button');
      b.textContent = 'Gérer';
      document.body.appendChild(b);
    });
    const avant = await page.evaluate(() => window.__calls.length);
    await wait(page, 1500);
    const memoire = await page.evaluate(() => {
      try { return JSON.parse(localStorage.getItem('tse:subs') || 'null'); }
      catch { return 'illisible'; }
    });
    ok('l\'abonnement est mémorisé', !!memoire?.omofficial, JSON.stringify(memoire));
    ok('avec l\'état « abonné »', memoire?.omofficial?.[0] === 1, JSON.stringify(memoire));

    // LE point qui justifie toute cette voie : aucune requête n'a été émise
    // pour l'obtenir. Le statut a été LU sur la page, pas demandé au réseau.
    const requetes = await page.evaluate((k) => window.__calls.slice(k)
      .flatMap(c => c.names || []), avant);
    ok('aucune requête n\'a servi à l\'apprendre',
       !requetes.some(n => /sub/i.test(n)), JSON.stringify([...new Set(requetes)]));

    // ── c) le tri met l'abonné en tête, malgré ses 120 spectateurs ────────
    const b = await boutons(page);
    ok('le bouton s\'active une fois un abonnement connu',
       b.find(x => x.mode === 'subs')?.off === false, JSON.stringify(b));
    ok('avant le tri, l\'abonné est bon dernier',
       (await ordre(page)).at(-1) === 'omofficial', (await ordre(page)).join(','));
    await page.evaluate(() =>
      document.querySelector('#tse-sort-row [data-tse-sort-mode="subs"]').click());
    await wait(page, 900);
    const apres = await ordre(page);
    ok('après le tri, il passe en tête', apres[0] === 'omofficial', apres.join(','));
    ok('et les autres gardent l\'ordre par spectateurs',
       apres.slice(1).join(',') === 'gros,moyen', apres.join(','));

    // ── d) une visite ultérieure corrige un désabonnement ─────────────────
    // C'est ce qui rend la mémoire honnête : on mémorise aussi le NON.
    await page.evaluate(() => {
      document.querySelector('[data-a-target="manage-sub-button"]').remove();
      const b = document.createElement('button');
      b.setAttribute('data-a-target', 'subscribe-button');
      document.body.appendChild(b);
    });
    await wait(page, 1200);
    const apresDesabo = await page.evaluate(() =>
      JSON.parse(localStorage.getItem('tse:subs') || 'null'));
    ok('le désabonnement est enregistré à la visite suivante',
       apresDesabo?.omofficial?.[0] === 0, JSON.stringify(apresDesabo));
    await page.close();
  }

  // ── f) la pastille de comptage ─────────────────────────────────────────
  {
    const pastille = (page) => page.evaluate(() => {
      const el = document.querySelector('#tse-sort-row [data-tse-sort-mode="subs"] .tse-sort-count');
      return el ? el.textContent : null;
    });
    const page = await freshTwitch(PLAYER, [], '/omofficial', SANS_PAGE);
    await decor(page);
    await wait(page, 1500);
    ok('aucune pastille tant qu\'aucun abonnement n\'est connu',
       (await pastille(page)) === null, String(await pastille(page)));

    await page.evaluate(() => {
      const b = document.createElement('button');
      b.setAttribute('data-a-target', 'manage-sub-button');
      document.body.appendChild(b);
    });
    await wait(page, 1200);
    ok('elle affiche 1 dès le premier abonnement repéré',
       (await pastille(page)) === '1', String(await pastille(page)));

    // Deux abonnements de plus, injectés dans la mémoire : on teste le
    // COMPTAGE, pas une seconde fois la détection. « moyen » a une carte dans
    // la sidebar, « autrechaine » n'en a pas — et la pastille les compte tous
    // les deux, parce qu'elle dit à combien de chaînes on est abonné, pas
    // combien émettent.
    await page.evaluate(() => {
      const m = JSON.parse(localStorage.getItem('tse:subs'));
      m.moyen = [1, Date.now()];
      m.autrechaine = [1, Date.now()];
      localStorage.setItem('tse:subs', JSON.stringify(m));
    });
    await page.reload();
    await decor(page);
    await page.evaluate(() => {
      const b = document.createElement('button');
      b.setAttribute('data-a-target', 'manage-sub-button');
      document.body.appendChild(b);
    });
    await wait(page, 1800);
    ok('et 3 quand trois abonnements sont connus, à l\'antenne ou non',
       (await pastille(page)) === '3', String(await pastille(page)));

    // La pastille ne doit pas entretenir de boucle de scan : son texte n'est
    // réécrit que s'il change. On vérifie que le nombre de scans se calme.
    const compte = () => page.evaluate(() => window.__calls.length);
    const a1 = await compte();
    await wait(page, 1500);
    const a2 = await compte();
    ok('elle n\'entretient pas de boucle de re-scan', a2 - a1 <= 4,
       `${a2 - a1} requête(s) en 1,5 s`);
    await page.close();
  }

  // ── e) hors d'une page de chaîne, on n'invente rien ─────────────────────
  {
    const page = await freshTwitch(PLAYER, [], '/directory', SANS_PAGE);
    await decor(page);
    await page.evaluate(() => {
      const b = document.createElement('button');
      b.setAttribute('data-a-target', 'manage-sub-button');
      document.body.appendChild(b);
    });
    await wait(page, 1400);
    const memoire = await page.evaluate(() =>
      localStorage.getItem('tse:subs'));
    // « directory » est un chemin RÉSERVÉ : ce n'est pas une chaîne, et
    // enregistrer « abonné à directory » polluerait la mémoire pour toujours.
    ok('un chemin réservé n\'est jamais pris pour une chaîne',
       memoire === null || !JSON.parse(memoire).directory, String(memoire));
    await page.close();
  }
}

// ═════ 43. Relevé complet des abonnements via /subscriptions ═════
titre('43. Abonnements — la liste complète, lue dans une iframe');
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const memoire = (page) => page.evaluate(() => {
    try { return JSON.parse(localStorage.getItem('tse:subs') || 'null'); }
    catch { return null; }
  });

  const page = await freshTwitch(PLAYER, [], '/');
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = { omofficial: { id:'1', createdAt:h, viewers:500, game:'G', tags:[] } };
    window.__addCard('omofficial', 'G', '500');
  });
  // Le relevé part PENDANT le chargement, et non après un délai : à 250 ms
  // l'iframe est déjà en place, alors que la page de test ne rendra ses
  // cartes qu'à 600 ms. Rien n'est donc encore mémorisé, mais le travail,
  // lui, a commencé.
  await wait(page, 250);
  const enCours = await page.evaluate(() => [...document.querySelectorAll('iframe')]
    .filter(f => (f.src || '').includes('/subscriptions')).length);
  ok('le relevé est en cours dès le chargement de la sidebar', enCours === 1, String(enCours));
  ok('et rien n\'est encore mémorisé', (await memoire(page)) === null,
     JSON.stringify(await memoire(page)));

  await attendre(page, () => !!localStorage.getItem('tse:substs'));
  const m = await memoire(page);
  const trouves = Object.keys(m || {}).sort();
  // Les trois onglets configurés : trois cartes en « paid », une en « gifts »,
  // une en « mobile ». La page de test en sert deux autres — « turbo » et
  // « expired » — qui ne doivent PAS remonter : un abonnement expiré n'en est
  // plus un, et le relevé étant additif, le lire marquerait « abonné » pour
  // 120 jours quelqu'un qu'on ne l'est plus.
  const abonnes = Object.entries(m || {}).filter(([, v]) => v[0] === 1).map(([k]) => k).sort();
  ok('les cinq abonnements des trois onglets sont relevés',
     abonnes.join(',') === 'clem_mlrt,etoiles,omofficial,roicheese,zerator', JSON.stringify(abonnes));
  ok('Turbo n\'est pas lu', !trouves.includes('jamais_turbo'), JSON.stringify(trouves));
  // Les EXPIRÉS entrent en mémoire — c'est ce qui nourrit « anciennement
  // abonné » — mais jamais comme des abonnements en cours.
  ok('les expirés sont mémorisés sans être comptés pour abonnés',
     trouves.includes('jenfirer') && !abonnes.includes('jenfirer'), JSON.stringify(trouves));
  ok('et tous marqués « abonné »',
     abonnes.length === 5, JSON.stringify(m));

  // L'iframe est un moyen, pas une trace : elle ne doit rien laisser derrière.
  ok('aucune iframe ne reste accrochée à la page',
     await page.evaluate(() => document.querySelectorAll('iframe').length) === 0,
     String(await page.evaluate(() => document.querySelectorAll('iframe').length)));

  // La pastille suit : quatre abonnements connus, quatre sur le bouton.
  const pastille = () => page.evaluate(() => {
    const el = document.querySelector('#tse-sort-row [data-tse-sort-mode="subs"] .tse-sort-count');
    return el ? el.textContent : null;
  });
  // La pastille compte le TOTAL des abonnements connus, pas ceux qui émettent :
  // c'est un fait sur le compte, pas sur l'antenne. Cinq relevés, cinq
  // affichés, alors qu'une seule de ces chaînes a une carte dans la sidebar.
  // Les onglets rentrant l'un après l'autre depuis la 3.50, la pastille EXISTE
  // dès le premier — avec un compte partiel. On attend donc qu'elle se pose,
  // pas qu'elle apparaisse. L'attente est bornée : une pastille qui n'atteint
  // jamais la bonne valeur fait échouer l'assertion, simplement plus tard.
  await attendre(page, () => {
    const el = document.querySelector('#tse-sort-row [data-tse-sort-mode="subs"] .tse-sort-count');
    return el && el.textContent === '5';
  });
  ok('la pastille affiche le total des abonnements connus',
     (await pastille()) === '5', String(await pastille()));

  // Le relevé est horodaté : dans le TTL, il ne doit pas recommencer.
  const stamp = await page.evaluate(() => localStorage.getItem('tse:substs'));
  // L'horodatage porte le NUMÉRO DU LECTEUR qui l'a produit : « 2:<date> ».
  // C'est ce qui permet à une correction du relevé de périmer d'office les
  // relevés des versions antérieures, au lieu d'attendre six heures.
  ok('le relevé est horodaté, avec son numéro de lecteur',
     /^2:\d+$/.test(stamp || ''), String(stamp));
  await wait(page, 1500);
  ok('et ne recommence pas dans le délai',
     (await page.evaluate(() => localStorage.getItem('tse:substs'))) === stamp,
     'horodatage modifié');

  // Forcer le relevé doit, lui, repasser outre le délai.
  const forcees = await page.evaluate(() => window.tse.subs.refresh());
  ok('tse.subs.refresh() force un nouveau relevé',
     Array.isArray(forcees) && forcees.length === 5, JSON.stringify(forcees));
  await page.close();
}

titre('44. Abonnements — le relevé part avec la sidebar, pas avec un minuteur');
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const cadres = (page) => page.evaluate(() => [...document.querySelectorAll('iframe')]
    .filter(f => (f.src || '').includes('/subscriptions')).length);
  const stamp = (page) => page.evaluate(() => localStorage.getItem('tse:substs'));

  // ── a) Sidebar sans chaîne suivie : le relevé ne part JAMAIS. ──────────
  // C'est la garde « session déconnectée » : personne n'a de chaînes suivies
  // sans compte, donc la page authentifiée n'est jamais demandée. Une carte
  // de RECOMMANDATION ne compte pas — elle ne porte pas le marqueur « suivi ».
  {
    const page = await freshTwitch(PLAYER, [], '/');
    await page.evaluate(() => {
      const h = new Date(Date.now() - 60 * 60_000).toISOString();
      window.__fx = { reco1: { id: '9', createdAt: h, viewers: 20, game: 'G', tags: [] } };
      window.__addReco('reco1', 'G', '20');
    });
    await wait(page, 1500);
    ok('sans chaîne suivie, aucune iframe n\'est ouverte', (await cadres(page)) === 0,
       String(await cadres(page)));
    ok('et aucun relevé n\'est horodaté', (await stamp(page)) === null,
       String(await stamp(page)));

    // La première carte SUIVIE, elle, déclenche le relevé. Le même document,
    // le même instant : seule la nature de la carte a changé.
    await page.evaluate(() => {
      const h = new Date(Date.now() - 60 * 60_000).toISOString();
      window.__fx.omofficial = { id: '1', createdAt: h, viewers: 500, game: 'G', tags: [] };
      window.__addCard('omofficial', 'G', '500');
    });
    await wait(page, 300);
    ok('la première carte suivie déclenche le relevé', (await cadres(page)) === 1,
       String(await cadres(page)));
    await attendre(page, () => !!localStorage.getItem('tse:substs'));
    const su = await page.evaluate(() => Object.keys(
      JSON.parse(localStorage.getItem('tse:subs') || '{}')).sort().join(','));
    ok('et il aboutit',
       su === 'antoinedaniel,clem_mlrt,etoiles,jenfirer,omofficial,roicheese,zerator', su);
    await page.close();
  }

  // ── b) Premier démarrage : le voile ATTEND le relevé. ──────────────────
  // Page d'abonnements ralentie à 500 ms par onglet (≈ 1,1 s pour les deux).
  // Sans retenue, le voile se lèverait dès la sidebar stable, ~350 ms après
  // le premier scan. À 700 ms, il doit donc être encore là.
  const LENT = () => { window.__subsDelay = 500; };
  {
    const page = await freshTwitch(PLAYER, [], '/', LENT);
    await page.evaluate(() => {
      const h = new Date(Date.now() - 60 * 60_000).toISOString();
      window.__fx = { omofficial: { id: '1', createdAt: h, viewers: 500, game: 'G', tags: [] } };
      window.__addCard('omofficial', 'G', '500');
    });
    // Sans retenue, le voile se lève dès la sidebar stable, ~350 ms après le
    // premier scan. Avec, il va jusqu'à son délai dur (1,2 s dans le harnais).
    // On mesure QUAND il s'est levé, pas s'il l'était à un instant choisi :
    // l'assertion ne dépend plus de la vitesse de la machine.
    // Le verrou est POSÉ — constaté, pas déduit. Il l'est au premier scan qui
    // voit une carte suivie, donc on l'attend au lieu de le lire à l'aveugle.
    let pose = [];
    for (let i = 0; i < 60; i++) {
      pose = await page.evaluate(() => window.tse.verrous());
      if (pose.includes('subs')) break;
      await wait(page, 40);
    }
    ok('rien en mémoire : le voile retient', pose.includes('subs'), JSON.stringify(pose));
    await attendre(page, () => window.__voileLeve !== null, 8000);
    const leve = await page.evaluate(() => window.__voileLeve);
    ok('et il attend le relevé', leve !== null && leve > 900,
       `voile levé après ${leve} ms`);
    // Et le délai dur reste souverain : la retenue ne peut pas l'éterniser
    // (1,2 s dans le harnais, 15 s en production).
    ok('mais le délai dur du voile reste souverain', leve !== null && leve < 4000,
       `voile levé après ${leve} ms`);
    await page.close();
  }

  // ── c) Démarrage suivant : rien à attendre. ────────────────────────────
  // Un abonnement est déjà connu du disque, donc la décoration est posée dès
  // la première carte. Faire patienter la sidebar pour un simple
  // rafraîchissement serait une rançon sans contrepartie — même page lente,
  // et cette fois le voile se lève à l'heure.
  {
    const TIEDE = () => {
      try {
        localStorage.setItem('tse:subs',
          JSON.stringify({ omofficial: [1, Date.now()] }));
        // Un démarrage TIÈDE, c'est un relevé qui a DÉJÀ abouti : son
        // horodatage est là, au format du lecteur courant. C'est lui, et non
        // la présence d'abonnements, qui dit qu'il n'y a rien à attendre.
        // Daté d'il y a 10 s, donc hors du TTL du harnais (4 s) : un
        // rafraîchissement de routine part quand même — et ne doit rien
        // retenir, puisque ce qu'il rafraîchit est déjà à l'écran.
        localStorage.setItem('tse:substs', '2:' + (Date.now() - 10_000));
      } catch { /* stockage refusé : le test échouera, et c'est correct */ }
    };
    const page = await freshTwitch(PLAYER, [], '/', TIEDE);
    await page.evaluate(() => {
      const h = new Date(Date.now() - 60 * 60_000).toISOString();
      window.__fx = { omofficial: { id: '1', createdAt: h, viewers: 500, game: 'G', tags: [] } };
      window.__addCard('omofficial', 'G', '500');
    });
    // On observe le VERROU, pas l'instant où le voile se lève. Le relevé fait
    // démarrer plusieurs pages en arrière-plan ; sous cette charge, le voile
    // peut atteindre son délai dur pour des raisons qui n'ont rien à voir avec
    // une retenue. Mesurer la décision plutôt que son effet rend l'assertion
    // indépendante de la machine — et c'est bien la décision qu'on a changée.
    let poses = null;
    for (let i = 0; i < 40; i++) {
      poses = await page.evaluate(() => window.tse.verrous());
      if (await page.evaluate(() => [...document.querySelectorAll('iframe')]
        .some(f => (f.src || '').includes('/subscriptions')))) break;
      await wait(page, 50);
    }
    ok('un abonnement déjà connu : le voile ne retient rien',
       Array.isArray(poses) && !poses.includes('subs'), JSON.stringify(poses));
    // Le rafraîchissement de routine, lui, part quand même — simplement sans
    // rien retenir. Les onglets partant ENSEMBLE depuis la 3.49, plusieurs
    // iframes coexistent, là où il n'y en avait qu'une à la fois.
    await attendre(page, () => [...document.querySelectorAll('iframe')]
      .some(f => (f.src || '').includes('/subscriptions')), 8000);
    ok('et le rafraîchissement de routine tourne quand même en arrière-plan',
       (await cadres(page)) >= 1, String(await cadres(page)));
    await page.close();
  }
}

titre('45. Abonnements — le tri se grise quand aucun abonné n\'émet');
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  // Relevé complet coupé : ce scénario décide de la DISPONIBILITÉ du tri à
  // partir de ce qui est en mémoire, et la page /subscriptions y verserait
  // ses propres chaînes.
  const SANS_PAGE = () => { window.__noSubsPage = true; };
  // Deux abonnements connus dès le départ, dont un seul aura une carte.
  const MEMOIRE = () => {
    window.__noSubsPage = true;
    try {
      localStorage.setItem('tse:subs', JSON.stringify({
        omofficial: [1, Date.now()],
        absente:    [1, Date.now()],
      }));
    } catch { /* stockage refusé : le test échouera, et c'est correct */ }
  };
  const bouton = (page) => page.evaluate(() => {
    const b = document.querySelector('#tse-sort-row [data-tse-sort-mode="subs"]');
    const p = b && b.querySelector('.tse-sort-count');
    return b ? { off: b.disabled, titre: b.title, pastille: p ? p.textContent : null } : null;
  });

  // ── a) des abonnements connus, mais aucun à l'antenne ──────────────────
  {
    const page = await freshTwitch(PLAYER, [], '/', MEMOIRE);
    await page.evaluate(() => {
      const h = new Date(Date.now() - 60 * 60_000).toISOString();
      window.__fx = { autre: { id: '9', createdAt: h, viewers: 300, game: 'G', tags: [] } };
      window.__addCard('autre', 'G', '300');
    });
    await wait(page, 1800);
    const b = await bouton(page);
    ok('deux abonnements connus, aucun en direct : le bouton est grisé',
       b?.off === true, JSON.stringify(b));
    // L'explication doit être la BONNE des deux : inviter à ouvrir une chaîne
    // quelqu'un dont le relevé est déjà fait serait un contresens.
    ok('et l\'explication parle du direct, pas du relevé',
       /direct/i.test(b?.titre || ''), b?.titre);
    // ET POURTANT la pastille reste, avec le total : le grisé dit « rien à
    // trier maintenant », la pastille dit « vous avez deux abonnements ». Les
    // effacer ensemble perdrait la seconde information avec la première.
    ok('mais la pastille reste, et donne le total', b?.pastille === '2', JSON.stringify(b));

    // La chaîne abonnée entre en direct : le bouton s'ouvre, sans rien d'autre
    // qu'une carte de plus. C'est ce qui donne des dents aux trois assertions
    // précédentes — le grisé vient bien de l'antenne, pas de la mémoire.
    await page.evaluate(() => {
      const h = new Date(Date.now() - 60 * 60_000).toISOString();
      window.__fx.omofficial = { id: '1', createdAt: h, viewers: 500, game: 'G', tags: [] };
      window.__addCard('omofficial', 'G', '500');
    });
    await wait(page, 1200);
    const c = await bouton(page);
    ok('un abonné passe en direct : le bouton s\'ouvre', c?.off === false, JSON.stringify(c));
  // Le survol donne le TOTAL, celui de la pastille — qui, elle, tronque au-delà
  // de 99 et ne dit pas ce qu'elle compte.
  ok('et son survol annonce le total des abonnements',
     /2 abonnements au total/.test(c?.titre || ''), String(c && c.titre));
    ok('et la pastille affiche toujours le total', c?.pastille === '2', JSON.stringify(c));

    // Puis il s'éteint. Twitch garde la carte quelques minutes ; l'extension,
    // elle, l'a déjà marquée hors ligne — et le tri redevient sans objet.
    await page.evaluate(() => {
      window.__fx.omofficial = null;
      const c2 = [...document.querySelectorAll('.side-nav-card')]
        .find(x => x.dataset.tseLogin === 'omofficial');
      c2.querySelector('.side-nav-card__avatar').classList.add('side-nav-card__avatar--offline');
    });
    await wait(page, 1500);
    const d = await bouton(page);
    ok('il s\'éteint : le bouton se regrise', d?.off === true, JSON.stringify(d));
    ok('sans que la pastille bouge', d?.pastille === '2', JSON.stringify(d));
    // La pastille doit être LISIBLE sur un bouton grisé, pas seulement
    // présente : l'opacité du grisé porte sur l'icône, pas sur le groupe — une
    // opacité posée sur le bouton emporterait la pastille avec elle.
    const opacites = await page.evaluate(() => {
      const b = document.querySelector('#tse-sort-row [data-tse-sort-mode="subs"]');
      return {
        bouton:   getComputedStyle(b).opacity,
        icone:    getComputedStyle(b.querySelector('svg')).opacity,
        pastille: getComputedStyle(b.querySelector('.tse-sort-count')).display,
      };
    });
    ok('et le grisé ne l\'éteint pas',
       opacites.bouton === '1' && opacites.icone !== '1' && opacites.pastille !== 'none',
       JSON.stringify(opacites));
    await page.close();
  }

  // ── b) rien en mémoire : l'autre explication ──────────────────────────
  {
    const page = await freshTwitch(PLAYER, [], '/', SANS_PAGE);
    await page.evaluate(() => {
      const h = new Date(Date.now() - 60 * 60_000).toISOString();
      window.__fx = { autre: { id: '9', createdAt: h, viewers: 300, game: 'G', tags: [] } };
      window.__addCard('autre', 'G', '300');
    });
    await wait(page, 1800);
    const b = await bouton(page);
    ok('aucun abonnement connu : le bouton est grisé aussi', b?.off === true, JSON.stringify(b));
    ok('mais l\'explication invite à ouvrir une chaîne',
       /ouvrez|repér/i.test(b?.titre || ''), b?.titre);
    await page.close();
  }
}

titre('46. Abonnements — un onglet vide ne coûte pas le garde-fou');
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  // « gifts » et « mobile » ne rendront aucune carte : c'est le cas d'un compte
  // qui n'a que des abonnements payants. Rien ne distingue un onglet vide d'une
  // page lente, sinon la barre latérale — rendue par la même application.
  const VIDES = () => { window.__subsVides = ['gifts', 'mobile']; };
  const page = await freshTwitch(PLAYER, [], '/', VIDES);
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = { omofficial: { id: '1', createdAt: h, viewers: 500, game: 'G', tags: [] } };
    window.__addCard('omofficial', 'G', '500');
  });
  const debut = Date.now();
  // LE point de la levée anticipée : l'onglet peuplé rentre vite, les deux
  // onglets vides s'attardent jusqu'à leur apaisement. Le verrou du voile doit
  // tomber AVEC le premier — pas avec le dernier. On compare deux événements
  // entre eux (verrou levé / relevé horodaté) et non à une horloge : un onglet
  // vide n'a rien à montrer, il n'a donc rien à retenir.
  let verrouVu = false;
  let verrouLeveAvantLaFin = null;
  for (let i = 0; i < 300; i++) {
    const [verrous, stamp] = await page.evaluate(() => [
      window.tse.verrous(), localStorage.getItem('tse:substs')]);
    const pose = verrous.includes('subs');
    if (pose) verrouVu = true;
    // On ne conclut qu'APRÈS avoir vu le verrou posé : sans cette condition,
    // la boucle répondait « levé » au premier tour, avant même que le relevé
    // n'ait démarré — une assertion qui ne prouvait rien.
    if (verrouVu && !pose && verrouLeveAvantLaFin === null) verrouLeveAvantLaFin = !stamp;
    if (stamp) break;
    await wait(page, 50);
  }
  ok('la retenue a bien été posée', verrouVu === true, 'verrou jamais observé');
  const duree = Date.now() - debut;
  ok('le voile est levé dès le premier onglet peuplé, sans attendre les vides',
     verrouLeveAvantLaFin === true, String(verrouLeveAvantLaFin));
  const trouves = await page.evaluate(() => Object.keys(
    JSON.parse(localStorage.getItem('tse:subs') || '{}')).sort().join(','));
  ok('l\'onglet peuplé est relevé quand même',
     trouves === 'antoinedaniel,etoiles,jenfirer,omofficial,roicheese', trouves);
  // Budget du relevé complet dans le harnais : deux onglets PEUPLÉS (rendu à
  // 600 ms + 900 ms de stabilité chacun) et deux onglets VIDES. Ces derniers
  // coûtent 1,2 s d'apaisement pièce, soit ~2,4 s — contre 12 s si chacun
  // attendait le garde-fou de 6 s. La borne est posée entre les deux totaux,
  // assez large pour ne pas dépendre de la charge de la machine, assez serrée
  // pour tomber si l'apaisement disparaît (vérifié par mutation).
  // Mesuré : 5,2 s avec les onglets lancés ensemble, 8,3 s en les enchaînant,
  // 15,0 s sans l'apaisement des onglets vides. La borne est posée entre les
  // deux dernières valeurs : elle tombe si l'apaisement disparaît, et laisse
  // assez de marge pour ne pas dépendre de la charge de la machine.
  ok('et les deux onglets vides n\'ont pas attendu le garde-fou',
     duree < 11_000, `relevé complet en ${duree} ms`);
  ok('aucune iframe ne reste accrochée',
     await page.evaluate(() => document.querySelectorAll('iframe').length) === 0);
  await page.close();
}

titre('47. Tri — le mode choisi revient quand il redevient possible');
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const MEMOIRE = () => {
    window.__noSubsPage = true;
    try {
      localStorage.setItem('tse:subs', JSON.stringify({ omofficial: [1, Date.now()] }));
    } catch { /* stockage refusé : le test échouera, et c'est correct */ }
  };
  const page = await freshTwitch(PLAYER, [], '/', MEMOIRE);
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = {
      omofficial: { id: '1', createdAt: h, viewers: 100, game: 'G', tags: [] },
      autre:      { id: '2', createdAt: h, viewers: 900, game: 'G', tags: [] },
    };
    window.__addCard('omofficial', 'G', '100');
    window.__addCard('autre', 'G', '900');
  });
  await wait(page, 1500);
  const mode = () => page.evaluate(() => {
    const b = document.querySelector('#tse-sort-row [aria-pressed="true"]');
    return b ? b.dataset.tseSortMode : null;
  });

  await page.evaluate(() => {
    document.querySelector('#tse-sort-row [data-tse-sort-mode="subs"]').click();
  });
  await wait(page, 300);
  ok('le tri « mes abonnements » est choisi', (await mode()) === 'subs', String(await mode()));

  // Le seul abonné s'éteint. Le tri n'a plus rien à faire : il retombe sur
  // « spectateurs », et le bouton se grise.
  await page.evaluate(() => {
    window.__fx.omofficial = null;
    [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.dataset.tseLogin === 'omofficial')
      .querySelector('.side-nav-card__avatar').classList.add('side-nav-card__avatar--offline');
  });
  await wait(page, 1500);
  ok('il s\'éteint : le tri retombe sur « spectateurs »',
     (await mode()) === 'viewers', String(await mode()));

  // Il revient. LE point de ce scénario : le choix de l'utilisateur revient
  // avec lui. Sans mémoire du souhait, le repli serait définitif — on aurait
  // perdu un réglage parce qu'un streamer avait éteint quelques minutes.
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx.omofficial = { id: '1', createdAt: h, viewers: 100, game: 'G', tags: [] };
    window.__goLive('omofficial');
  });
  await wait(page, 1800);
  ok('il revient : le tri choisi revient aussi', (await mode()) === 'subs', String(await mode()));
  await page.close();
}

titre('48. Abonnements — l\'ancienneté, lue sans lire le français');
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const page = await freshTwitch(PLAYER, [], '/');
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = {
      omofficial: { id: '1', createdAt: h, viewers: 500, game: 'G', tags: [] },
      roicheese:  { id: '2', createdAt: h, viewers: 400, game: 'G', tags: [] },
    };
    window.__addCard('omofficial', 'G', '500');
    window.__addCard('roicheese', 'G', '400');
  });
  await attendre(page, () => !!localStorage.getItem('tse:substs'));
  await wait(page, 400);
  const mem = await page.evaluate(() =>
    JSON.parse(localStorage.getItem('tse:subs') || '{}'));

  // LE point du scénario. La carte payante de « roicheese » porte QUATRE
  // nombres : 9 jours avant l'anniversaire, 4 mois au total, 3 mois à la
  // suite, une date d'expiration. Prendre le premier venu donnerait 9 ;
  // prendre le dernier « N mois » donnerait 3. Seule l'étiquette — apprise
  // sur une carte expirée, où elle est seule — donne 4.
  ok('l\'ancienneté totale est lue, pas le compte à rebours',
     mem.roicheese?.[2] === 4, JSON.stringify(mem.roicheese));
  ok('ni la série en cours', mem.roicheese?.[2] !== 3, JSON.stringify(mem.roicheese));
  ok('un abonnement d\'un mois est lu comme tel',
     mem.omofficial?.[2] === 1, JSON.stringify(mem.omofficial));

  // Les cartes expirées, elles, n'ont qu'une paire : c'est ce qui les rend
  // enseignables. On vérifie qu'elles sont relevées, et marquées « ancien ».
  ok('un ancien abonnement porte son ancienneté',
     mem.antoinedaniel?.[2] === 29, JSON.stringify(mem.antoinedaniel));
  ok('et la marque « ancien abonné »',
     mem.antoinedaniel?.[3] === 1, JSON.stringify(mem.antoinedaniel));
  ok('sans être compté comme abonné en cours',
     mem.antoinedaniel?.[0] === 0, JSON.stringify(mem.antoinedaniel));

  // Le réabonnement : « etoiles » figure dans les expirés ET dans les payants.
  // La lecture des expirés ne doit pas dégrader un abonnement en cours — et
  // c'est bien pour ça qu'elle ne touche jamais à l'état d'abonnement.
  ok('une chaîne réabonnée reste abonnée', mem.etoiles?.[0] === 1, JSON.stringify(mem.etoiles));
  ok('avec son ancienneté', mem.etoiles?.[2] === 12, JSON.stringify(mem.etoiles));

  // L'ancienneté survit à une observation de visite, qui vient d'une AUTRE
  // source et n'a rien à dire sur le nombre de mois.
  await page.evaluate(() => {
    const b = document.createElement('button');
    b.setAttribute('data-a-target', 'manage-sub-button');
    document.body.appendChild(b);
    history.pushState({}, '', '/roicheese');
  });
  await wait(page, 800);
  const apres = await page.evaluate(() =>
    JSON.parse(localStorage.getItem('tse:subs') || '{}'));
  ok('une visite n\'efface pas l\'ancienneté',
     apres.roicheese?.[2] === 4, JSON.stringify(apres.roicheese));
  await page.close();
}

titre('49. Abonnements — une liste qui s\'écrit par morceaux');
{
  // Une liste React n'apparaît pas d'un bloc : le lien d'une carte peut être
  // rendu avant son ancienneté. Un relevé qui conclut au PREMIER passage où
  // il voit une carte lit donc la chaîne, et rien d'autre — l'étiquette n'est
  // jamais apprise, et plus aucun badge n'apparaît nulle part.
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const MORCEAUX = () => { window.__subsProgressif = 700; };
  const page = await freshTwitch(PLAYER, [], '/', MORCEAUX);
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = { roicheese: { id: '2', createdAt: h, viewers: 400, game: 'G', tags: [] } };
    window.__addCard('roicheese', 'G', '400');
  });
  await attendre(page, () => !!localStorage.getItem('tse:substs'), 20_000);
  await wait(page, 400);
  const mem = await page.evaluate(() => JSON.parse(localStorage.getItem('tse:subs') || '{}'));
  ok('les chaînes sont relevées malgré le rendu en deux temps',
     mem.roicheese?.[0] === 1, JSON.stringify(mem.roicheese));
  ok('et leur ancienneté aussi', mem.roicheese?.[2] === 4, JSON.stringify(mem.roicheese));
  ok('y compris celle apprise sur les expirés',
     mem.antoinedaniel?.[2] === 29, JSON.stringify(mem.antoinedaniel));
  await page.close();
}

// Une correction du relevé doit atteindre les mémoires déjà écrites. Un
// horodatage laissé par un lecteur ANTÉRIEUR — la 3.48.0 relevait les chaînes
// sans leur ancienneté — ne doit pas interdire le nouveau relevé pendant six
// heures, sinon la correction ne se voit qu'au lendemain.
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const VIEUX = () => {
    // Format nu, sans numéro de lecteur : celui d'avant la 3.48.1. Et tout
    // frais, donc parfaitement dans le TTL.
    try { localStorage.setItem('tse:substs', String(Date.now())); } catch {}
  };
  const page = await freshTwitch(PLAYER, [], '/', VIEUX);
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = { roicheese: { id: '2', createdAt: h, viewers: 400, game: 'G', tags: [] } };
    window.__addCard('roicheese', 'G', '400');
  });
  await attendre(page, () => /^2:/.test(localStorage.getItem('tse:substs') || ''), 20_000);
  const mem = await page.evaluate(() => JSON.parse(localStorage.getItem('tse:subs') || '{}'));
  ok('un relevé d\'un lecteur antérieur ne bloque pas la correction',
     mem.roicheese?.[2] === 4, JSON.stringify(mem.roicheese));
  ok('et le nouvel horodatage porte son numéro de lecteur',
     /^2:\d+$/.test(await page.evaluate(() => localStorage.getItem('tse:substs'))),
     await page.evaluate(() => localStorage.getItem('tse:substs')));

  // tse.reset() doit aussi emporter cet horodatage : effacer les abonnements
  // puis s'interdire d'aller les rechercher n'est pas une remise à zéro.
  await page.evaluate(() => window.tse.reset());
  ok('tse.reset() emporte l\'horodatage du relevé',
     (await page.evaluate(() => localStorage.getItem('tse:substs'))) === null,
     String(await page.evaluate(() => localStorage.getItem('tse:substs'))));
  await page.close();
}

// LE cas signalé : des abonnements DÉJÀ connus, mais un relevé produit par un
// lecteur devenu périmé. La sidebar a donc de quoi s'afficher tout de suite —
// et pourtant il manque l'ancienneté, que seul un nouveau relevé apportera.
// Le voile doit le couvrir, sans quoi le badge arrive après lui.
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const CONNUS_MAIS_PERIMES = () => {
    window.__subsDelay = 500;
    try {
      localStorage.setItem('tse:subs', JSON.stringify({ roicheese: [1, Date.now()] }));
      localStorage.setItem('tse:substs', String(Date.now()));   // format sans lecteur
    } catch { /* stockage refusé : le test échouera, et c'est correct */ }
  };
  const page = await freshTwitch(PLAYER, [], '/', CONNUS_MAIS_PERIMES);
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = { roicheese: { id: '2', createdAt: h, viewers: 400, game: 'G', tags: [] } };
    window.__addCard('roicheese', 'G', '400');
  });
  await attendre(page, () => window.__voileLeve !== null, 8000);
  const leve = await page.evaluate(() => window.__voileLeve);
  ok('abonnements connus mais relevé périmé : le voile attend quand même',
     leve !== null && leve > 900, `voile levé après ${leve} ms`);
  await page.close();
}

titre('50. Aperçu — le badge d\'abonnement');
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const page = await freshTwitch(PLAYER, [], '/');
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = {
      roicheese:     { id: '2', createdAt: h, viewers: 400, game: 'G', tags: [] },
      antoinedaniel: { id: '3', createdAt: h, viewers: 300, game: 'G', tags: [] },
      inconnue:      { id: '4', createdAt: h, viewers: 200, game: 'G', tags: [] },
    };
    window.__addCard('roicheese', 'G', '400');
    window.__addCard('antoinedaniel', 'G', '300');
    window.__addCard('inconnue', 'G', '200');
  });
  await attendre(page, () => !!localStorage.getItem('tse:substs'));
  await wait(page, 500);

  const badge = async (login) => {
    await hoverLogin(page, login);
    await wait(page, 500);
    const b = await page.evaluate(() => {
      const el = document.querySelector('.tse-preview__badge--sub, .tse-preview__badge--exsub');
      return el ? { classe: el.className, texte: el.textContent.trim() } : null;
    });
    await unhoverCard(page, 0);
    await wait(page, 200);
    return b;
  };

  const abo = await badge('roicheese');
  ok('un abonnement en cours affiche sa durée',
     abo?.texte === 'Abonné • 4 MOIS', JSON.stringify(abo));
  ok('avec la teinte « abonné »',
     (abo?.classe || '').includes('--sub'), JSON.stringify(abo));

  const ancien = await badge('antoinedaniel');
  ok('un ancien abonnement le dit, au passé',
     ancien?.texte === 'Ancien abonné • 29 MOIS', JSON.stringify(ancien));
  ok('avec sa propre teinte, désaturée',
     (ancien?.classe || '').includes('--exsub'), JSON.stringify(ancien));

  // Une chaîne dont on ne sait rien : PAS de badge. Un « Abonné » sans durée
  // n'apprendrait rien que le filet doré de la carte ne dise déjà.
  const rien = await badge('inconnue');
  ok('une chaîne sans historique n\'affiche aucun badge', rien === null, JSON.stringify(rien));

  /* ── LA LIGNE DE TWITCH, PONCTUÉE COMME LES NÔTRES ──────────────────────
     Twitch injecte sous certaines cartes une ligne à lui — une série de
     visionnage, par exemple — que l'aperçu reprend en badge. Elle arrive avec
     son nombre collé à sa phrase : « Série de visionnage 1 ». Dans une rangée
     où tous nos badges séparent leur intitulé de leur valeur par une puce
     (« Abonné • 4 MOIS », « Subathon • JOUR 12 »), cette seule ligne se lisait
     comme un objet d'une autre espèce.

     ON NE LA RETRADUIT PAS, ET C'EST LE SUJET DE L'ASSERTION. Recomposer la
     phrase de Twitch en dix langues à partir d'une chaîne qu'on ne peut pas
     lire d'ici serait inventer dix traductions ; on se contente de détacher le
     NOMBRE FINAL, qui est un nombre partout. Les mots restent les siens. */
  await page.evaluate(() => {
    const carte = [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.dataset.tseLogin === 'inconnue');
    const rangee = document.createElement('div');
    rangee.innerHTML = '<p>Série de visionnage 1</p>';
    carte.querySelector('.mainblock').appendChild(rangee);
    window.tse.rescan();
  });
  await wait(page, 600);
  /* L'aperçu est un SINGLETON : re-survoler la carte déjà survolée ne le
     rouvre pas. On relâche pour de bon avant de redemander. */
  await page.evaluate(() => {
    [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.dataset.tseLogin === 'inconnue')
      ?.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
  });
  await attendre(page,
    () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);
  await hoverLogin(page, 'inconnue');
  await attendre(page,
    () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
  await wait(page, 300);
  const ligne = await page.evaluate(() =>
    [...document.querySelectorAll('.tse-preview__badge')]
      .map(b => b.textContent.trim()).find(t => /visionnage/.test(t)) || null);
  ok('une ligne de Twitch prend la puce des autres badges, sans être retraduite',
     ligne === 'Série de visionnage • 1', JSON.stringify(ligne));
  await page.close();
}

titre('51. Abonnements — la carte d\'une chaîne abonnée');
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const page = await freshTwitch(PLAYER, [], '/');
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = {
      omofficial: { id: '1', createdAt: h, viewers: 500, game: 'G', tags: [] },
      inconnue:   { id: '2', createdAt: h, viewers: 900, game: 'G', tags: [] },
      etoiles:    { id: '3', createdAt: h, viewers: 700, game: 'G', tags: [] },
    };
    window.__addCard('omofficial', 'G', '500');
    window.__addCard('inconnue', 'G', '900');
    /* UNE TROISIÈME CARTE, ABONNÉE ET SANS LE CROCHET DE TWITCH. L'or du nom
       était écrit pour p[data-a-target=side-nav-title] : sur une carte décorée
       — « En live avec », co-stream, et sur TOUTE carte fabriquée par clonage
       d'une telle carte — il ne s'appliquait pas, en silence. Personne ne l'a
       signalé ; c'est un audit qui l'a trouvé, en recensant ce qui dépendait
       encore de ce crochet. */
    window.__addCard('etoiles', 'G', '700');
    [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.querySelector('a[href="/etoiles"]'))
      .querySelector('p[data-a-target="side-nav-title"]')
      .removeAttribute('data-a-target');
  });
  await attendre(page, () => !!localStorage.getItem('tse:substs'));
  await wait(page, 400);   // le scan qui applique la décoration suit le relevé

  const marque = (login) => page.evaluate((l) => {
    const c = [...document.querySelectorAll('.side-nav-card')].find(x => x.dataset.tseLogin === l);
    if (!c) return null;
    const apres = getComputedStyle(c, '::after');
    const av = c.querySelector('.side-nav-card__avatar figure, .side-nav-card__avatar .tw-avatar');
    const avApres = av ? getComputedStyle(av, '::after') : null;
    /* LE NOM EST DÉSIGNÉ PAR UNE CLASSE, comme la catégorie et pour la même
       raison : le crochet d'automatisation de Twitch manque sur les cartes
       décorées, et une feuille de style qui s'y accroche cesse de s'appliquer
       sans rien dire. Lire ici par la MARQUE, c'est aussi vérifier qu'elle est
       posée — sans elle, nomStyle serait null et tout ce bloc tomberait. */
    const nom = c.querySelector('p.tse-nom');
    const nomStyle = nom ? getComputedStyle(nom) : null;
    // La catégorie est désormais DÉSIGNÉE par une classe, posée en JS d'après
    // cardCategoryEl() : plus de cascade à recopier ici non plus.
    const cat = c.querySelector('.tse-sub-cat');
    const catStyle = cat ? getComputedStyle(cat) : null;
    return {
      classe:    c.classList.contains('tse-sub'),
      phase:     c.style.getPropertyValue('--tse-sub-phase'),
      anim:      apres.animationName,
      pointeur:  apres.pointerEvents,
      // La lueur se peint SOUS le contenu : un z-index négatif dans le
      // contexte d'empilement de la carte. C'est ce qui lui permet de
      // cohabiter avec le fond de « frais » et du co-stream.
      plan:      apres.zIndex,
      avatar:    avApres ? avApres.animationName : null,
      nomAnim:   nomStyle ? nomStyle.animationName : null,
      nomFill:   nomStyle ? nomStyle.webkitTextFillColor : null,
      nomPoids:  nomStyle ? nomStyle.fontWeight : null,
      catTexte:  cat ? cat.textContent : null,
      catAnim:   catStyle ? catStyle.animationName : null,
      catFill:   catStyle ? catStyle.webkitTextFillColor : null,
      catDuree:  catStyle ? catStyle.animationDuration : null,
      nomDuree:  nomStyle ? nomStyle.animationDuration : null,
      avSouffle: av ? getComputedStyle(av).animationName : null,
    };
  }, login);

  const abo = await marque('omofficial');
  const non = await marque('inconnue');
  const sansCrochet = await marque('etoiles');
  ok('la chaîne abonnée porte la marque', abo && abo.classe === true, JSON.stringify(abo));
  ok('la chaîne non abonnée ne la porte pas', non && non.classe === false, JSON.stringify(non));
  // La décoration EXISTE vraiment côté rendu : deux animations nommées sur le
  // ::after, et un halo sur la carte. Sans ça, la classe ne prouverait rien.
  ok('la lueur de fond est animée', abo?.anim === 'tse-sub-lueur', String(abo && abo.anim));
  // Elle se peint SOUS le contenu de la carte, et sous la barre de gauche de
  // « frais » et du co-stream : c'est ce plan négatif qui rend la cohabitation
  // possible sans une seule règle de départage.
  ok('et posée sous le contenu de la carte', abo?.plan === '-1', String(abo && abo.plan));
  // Le nom passe à l'or, et le dégradé le traverse.
  ok('le nom porte le dégradé doré',
     (abo?.nomAnim || '').includes('tse-sub-titre'), String(abo && abo.nomAnim));
  ok('en découpe dans le texte',
     (abo?.nomFill || '').includes('rgba(0, 0, 0, 0)'), String(abo && abo.nomFill));
  ok('et il est mis en gras', abo?.nomPoids === '700', String(abo && abo.nomPoids));
  /* ET LA MÊME CHOSE SANS LE CROCHET DE TWITCH. C'est l'assertion qui manquait :
     l'or tenait à un attribut que Twitch ne pose pas sur les cartes décorées,
     ni sur aucune carte fabriquée par clonage de l'une d'elles. */
  ok('une carte abonnée SANS le crochet de Twitch reçoit le même or',
     (sansCrochet?.nomAnim || '').includes('tse-sub-titre')
     && sansCrochet?.nomPoids === '700', JSON.stringify(sansCrochet));
  // La catégorie reçoit le même traitement, en plus sourd et plus lent : les
  // deux rangs doivent rester distincts, sans quoi la hiérarchie que Twitch
  // installe par la taille et la couleur s'aplatit.
  ok('la catégorie est bien celle visée, pas le nom',
     abo?.catTexte === 'G', String(abo && abo.catTexte));
  ok('elle porte elle aussi le dégradé', abo?.catAnim === 'tse-sub-titre',
     String(abo && abo.catAnim));
  ok('en découpe dans le texte',
     (abo?.catFill || '').includes('rgba(0, 0, 0, 0)'), String(abo && abo.catFill));
  // Le nom porte DEUX animations (reflet + halo), la catégorie une seule ; et
  // le reflet du nom est plus rapide. C'est cette différence qui tient la
  // hiérarchie.
  ok('le nom porte en plus un halo qui respire',
     (abo?.nomAnim || '').includes('tse-sub-halo'), String(abo && abo.nomAnim));
  ok('et son reflet va plus vite que celui de la catégorie',
     parseFloat(abo?.nomDuree) < parseFloat(abo?.catDuree),
     `${abo && abo.nomDuree} contre ${abo && abo.catDuree}`);
  ok('la catégorie, elle, n\'a qu\'une animation',
     (abo?.catAnim || '').split(',').length === 1, String(abo && abo.catAnim));
  ok('la catégorie d\'une chaîne non abonnée n\'est même pas marquée',
     non !== null && non.catAnim === null, String(non && non.catAnim));
  // La catégorie est DÉSIGNÉE par cardCategoryEl, plus cherchée par un
  // sélecteur qui exigeait un attribut title : c'est ce qui la met à l'abri
  // du défaut signalé sur l'avatar. On vérifie qu'elle porte bien la marque
  // et que c'est le bon élément.
  ok('la catégorie est marquée par la fonction de référence',
     await page.evaluate(() => {
       const c = [...document.querySelectorAll('.side-nav-card')]
         .find(x => x.dataset.tseLogin === 'omofficial');
       const marque = c.querySelectorAll('.tse-sub-cat');
       return marque.length === 1 && marque[0].textContent === 'G';
     }));
  ok('le nom d\'une chaîne non abonnée est laissé tel quel',
     !non || (non.nomAnim === 'none' && non.nomPoids !== '700'),
     JSON.stringify(non && { a: non.nomAnim, p: non.nomPoids }));
  // L'avatar garde son anneau : c'est le SEUL élément qui subsiste en mode
  // réduit, où il n'y a ni fond ni nom à colorer.
  ok('l\'avatar garde son anneau tournant', !!abo && (abo.avatar || '').includes('tse-sub-turn'),
     String(abo && abo.avatar));
  ok('et son halo respire', abo?.avSouffle === 'tse-sub-souffle', String(abo && abo.avSouffle));
  ok('la chaîne non abonnée n\'a pas d\'anneau d\'avatar',
     !non || non.avatar === 'none', String(non && non.avatar));
  ok('et le décor ne capte pas les clics', !!abo && abo.pointeur === 'none',
     String(abo && abo.pointeur));
  ok('la chaîne non abonnée n\'anime rien', !!non && non.anim === 'none',
     String(non && non.anim));

  // La phase vient du LOGIN, pas du rang : elle doit survivre à un changement
  // de tri. Sans quoi l'animation repartirait de zéro à chaque reclassement.
  const avant = abo.phase;
  ok('la phase est posée', /^\d+$/.test(avant), String(avant));
  await page.evaluate(() => {
    const b = document.querySelector('#tse-sort-row [data-tse-sort-mode="subs"]');
    if (b) b.click();
  });
  await wait(page, 400);
  const apresTri = await marque('omofficial');
  ok('et ne bouge pas quand le tri change', apresTri.phase === avant,
     avant + ' -> ' + apresTri.phase);
  ok('la marque non plus', apresTri.classe === true, JSON.stringify(apresTri));

  /* MOUVEMENT RÉDUIT : L'EXTENSION N'EN PARLE PLUS. Jusqu'à la 4.14.0 une
     feuille entière éteignait le décor sous « prefers-reduced-motion ». Elle
     n'existe plus : c'est une demande, après comparaison des deux moutures
     côte à côte. Le contrat change donc de forme, et il en sort RENFORCÉ.
     « Ça s'arrête » se vérifiait sur un état ; « rien ne change » se vérifie
     sur la différence entre deux relevés, et retombe dès qu'une seule règle
     réduite reparaît — y compris une règle qu'on n'aurait pas pensé à
     interroger ici. Supprimer les assertions aurait laissé le trou ouvert. */
  const libre = await marque('omofficial');
  await page.emulateMedia({ reducedMotion: 'reduce' });
  const calme = await marque('omofficial');
  const bouge = ['anim', 'nomAnim', 'catAnim', 'avatar', 'avSouffle',
                 'nomDuree', 'catDuree', 'pointeur', 'plan'];
  const ecarts = bouge.filter((k) => calme[k] !== libre[k]);
  ok('mouvement réduit : le décor est rigoureusement le même qu\'en mouvement libre',
     ecarts.length === 0,
     JSON.stringify(Object.fromEntries(ecarts.map((k) => [k, [libre[k], calme[k]]]))));
  // Et ce « même » est bien un décor vivant, pas deux fois rien : l'invariance
  // ci-dessus serait vraie aussi si tout était éteint des deux côtés.
  ok('le fond anime toujours', calme.anim === 'tse-sub-lueur', String(calme.anim));
  ok('le nom aussi', (calme.nomAnim || '').includes('tse-sub-titre'), String(calme.nomAnim));
  ok('la catégorie aussi', calme.catAnim === 'tse-sub-titre', String(calme.catAnim));
  ok('et la catégorie reste marquée', calme.catTexte === 'G', String(calme.catTexte));
  ok('l\'avatar garde son anneau', (calme.avatar || '').includes('tse-sub-turn'),
     String(calme.avatar));
  ok('et son halo respire encore', calme.avSouffle === 'tse-sub-souffle',
     String(calme.avSouffle));
  ok('mais la marque demeure', calme.classe === true, JSON.stringify(calme));
  await page.emulateMedia({ reducedMotion: 'no-preference' });

  // La décoration suit la CHAÎNE, pas la carte : React recycle ses cartes
  // d'une chaîne à l'autre, et une marque oubliée décorerait un inconnu.
  await page.evaluate(() => {
    const c = [...document.querySelectorAll('.side-nav-card')]
      .find(x => x.dataset.tseLogin === 'omofficial');
    c.querySelector('a[href="/omofficial"]').setAttribute('href', '/recyclee');
  });
  await wait(page, 600);
  const recyclee = await marque('recyclee');
  ok('carte recyclée sur une autre chaîne : la marque tombe',
     !!recyclee && recyclee.classe === false, JSON.stringify(recyclee));
  await page.close();
}

titre('53. Abonnements — les onglets partent ensemble, l\'étiquette est retenue');
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const poser = (page) => page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = { roicheese: { id: '2', createdAt: h, viewers: 400, game: 'G', tags: [] } };
    window.__addCard('roicheese', 'G', '400');
  });
  // Nombre maximal d'iframes /subscriptions coexistant pendant le relevé.
  // C'est la mesure directe du parallélisme : à une par instant, le relevé
  // durait la SOMME des onglets et ne pouvait pas tenir sous le voile.
  const compter = (page) => page.evaluate(() => [...document.querySelectorAll('iframe')]
    .filter(f => (f.src || '').includes('/subscriptions')).length);
  const pic = async (page, ms) => {
    let max = 0;
    const fin = Date.now() + ms;
    while (Date.now() < fin) {
      max = Math.max(max, await compter(page));
      await wait(page, 100);
    }
    return max;
  };
  // Pic mesuré à partir de la PREMIÈRE iframe, sur une fenêtre courte. C'est
  // ce qui distingue les deux cas : sans étiquette connue, l'onglet des
  // expirés tourne SEUL pendant ce temps-là ; avec, toute la volée est déjà
  // partie. Les départs étant décalés (SUBS_PAGE_STAGGER), on ne regarde pas
  // le tout premier instant mais une fenêtre qui les couvre.
  const picInitial = async (page, ms) => {
    await attendre(page, () => [...document.querySelectorAll('iframe')]
      .some(f => (f.src || '').includes('/subscriptions')), 8000);
    return pic(page, ms);
  };

  // ── a) profil neuf : l'étiquette est apprise, puis mémorisée ───────────
  {
    const page = await freshTwitch(PLAYER, [], '/');
    await poser(page);
    const debut = await picInitial(page, 900);
    const max = await pic(page, 5000);
    await attendre(page, () => !!localStorage.getItem('tse:substs'));
    ok('plusieurs onglets sont lus en même temps', max >= 2, `pic de ${max} iframe(s)`);
    // Étiquette inconnue : l'onglet des expirés doit passer SEUL d'abord.
    ok('mais l\'étiquette inconnue impose une passe préalable, seule',
       debut === 1, `pic initial de ${debut} iframe(s)`);
    const etiq = await page.evaluate(() => localStorage.getItem('tse:submois'));
    ok('l\'étiquette apprise est mémorisée',
       etiq === 'Nombre total de mois abonné :', String(etiq));
    // tse.reset() doit l'emporter : elle vient de la même lecture.
    await page.evaluate(() => window.tse.reset());
    ok('et tse.reset() l\'emporte',
       (await page.evaluate(() => localStorage.getItem('tse:submois'))) === null,
       String(await page.evaluate(() => localStorage.getItem('tse:submois'))));
    await page.close();
  }

  // ── b) étiquette déjà connue : plus de passe préalable ─────────────────
  // Sans elle, l'onglet des expirés doit passer SEUL en premier — les autres
  // ne sauraient pas quoi chercher. Avec elle, tout part d'un bloc, et c'est
  // ce qui fait tenir le relevé sous la retenue du voile.
  {
    const SU = () => {
      try { localStorage.setItem('tse:submois', 'Nombre total de mois abonné :'); } catch {}
    };
    const page = await freshTwitch(PLAYER, [], '/', SU);
    await poser(page);
    // Même fenêtre, même mesure : cette fois toute la volée est déjà partie.
    const dabord = await picInitial(page, 900);
    ok('l\'étiquette connue supprime la passe préalable', dabord >= 3,
       `pic initial de ${dabord} iframe(s)`);
    await attendre(page, () => !!localStorage.getItem('tse:substs'));
    await wait(page, 400);
    const mem = await page.evaluate(() => JSON.parse(localStorage.getItem('tse:subs') || '{}'));
    ok('et l\'ancienneté est lue quand même', mem.roicheese?.[2] === 4,
       JSON.stringify(mem.roicheese));
    await page.close();
  }
}

titre('54. Abonnements — l\'origine est retenue, la teinte reste l\'or');
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const page = await freshTwitch(PLAYER, [], '/');
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = {
      omofficial: { id: '1', createdAt: h, viewers: 500, game: 'G', tags: [] },  // payant
      clem_mlrt:  { id: '5', createdAt: h, viewers: 150, game: 'G', tags: [] },  // offert
      zerator:    { id: '6', createdAt: h, viewers: 840, game: 'G', tags: [] },  // mobile
      inconnue:   { id: '4', createdAt: h, viewers: 900, game: 'G', tags: [] },
    };
    for (const l of ['omofficial', 'clem_mlrt', 'zerator', 'inconnue']) {
      window.__addCard(l, 'G', '100');
    }
  });
  await attendre(page, () => !!localStorage.getItem('tse:substs'));
  await wait(page, 500);

  const mem = await page.evaluate(() => JSON.parse(localStorage.getItem('tse:subs') || '{}'));
  // L'origine est le CINQUIÈME champ de la forme compacte. Aucune interface ne
  // s'en sert — la teinte par origine a été essayée puis retirée — mais elle
  // est relevée sans requête supplémentaire et tse.subs() la montre.
  ok('l\'onglet d\'origine est mémorisé', mem.omofficial?.[4] === 'paid',
     JSON.stringify(mem.omofficial));
  ok('un abonnement offert le sait', mem.clem_mlrt?.[4] === 'gifts', JSON.stringify(mem.clem_mlrt));
  ok('un abonnement mobile aussi', mem.zerator?.[4] === 'mobile', JSON.stringify(mem.zerator));
  ok('les expirés ne posent pas d\'origine', !mem.antoinedaniel?.[4],
     JSON.stringify(mem.antoinedaniel));
  ok('et tse.subs() la rend lisible',
     (await page.evaluate(() => window.tse.subs().find(e => e.login === 'clem_mlrt')?.origine))
       === 'gifts');

  // L'OR POUR TOUS, quelle que soit l'origine : c'est ce que l'interface dit.
  const teinte = (login) => page.evaluate((l) => {
    const c = [...document.querySelectorAll('.side-nav-card')].find(x => x.dataset.tseLogin === l);
    return c ? getComputedStyle(c).getPropertyValue('--tse-sub-or').trim() : null;
  }, login);
  const teintes = [await teinte('omofficial'), await teinte('clem_mlrt'), await teinte('zerator')];
  ok('les trois origines portent le même or', new Set(teintes).size === 1,
     JSON.stringify(teintes));
  ok('et c\'est bien de l\'or', /255,\s*196,\s*92/.test(teintes[0] || ''), String(teintes[0]));
  ok('aucune carte ne porte d\'attribut d\'origine',
     await page.evaluate(() => document.querySelectorAll('[data-tse-sub-src]').length) === 0);
  await page.close();
}

titre('55. Abonnements — l\'anneau suit l\'avatar, quelle que soit sa forme');
{
  // Twitch ne rend pas toujours le même markup d'avatar : avatarOf() en
  // couvre cinq formes. Le CSS n'en recopiait que trois — d'où un anneau
  // présent sur une carte et absent sur sa voisine, pour la même raison
  // invisible : un <figure> ici, un simple <div class="tw-avatar"> là.
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const NU = () => {
    window.__noSubsPage = true;
    // Quatre cartes, quatre formes d'avatar. La dernière — hors du bloc
    // habituel ET sans <figure> — est celle qu'aucun sélecteur de la feuille
    // de style n'atteignait : c'est la quatrième branche de avatarOf().
    window.__avatarNu = ['clem_mlrt', 'domingo'];
    window.__avatarStories = ['hasanabi', 'domingo'];
    try {
      localStorage.setItem('tse:subs', JSON.stringify({
        etoiles: [1, Date.now()], clem_mlrt: [1, Date.now()],
        hasanabi: [1, Date.now()], domingo: [1, Date.now()],
      }));
    } catch { /* stockage refusé : le test échouera, et c'est correct */ }
  };
  const page = await freshTwitch(PLAYER, [], '/', NU);
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = {
      etoiles:   { id: '3', createdAt: h, viewers: 2600, game: 'G', tags: [] },
      clem_mlrt: { id: '5', createdAt: h, viewers: 174,  game: 'G', tags: [] },
      hasanabi:  { id: '7', createdAt: h, viewers: 29800, game: 'G', tags: [] },
      domingo:   { id: '8', createdAt: h, viewers: 14200, game: 'G', tags: [] },
    };
    window.__addCard('etoiles', 'G', '2,6 k');
    window.__addCard('clem_mlrt', 'G', '174');
    window.__addCard('hasanabi', 'G', '29,8 k');
    window.__addCard('domingo', 'G', '14,2 k');
  });
  await wait(page, 1800);

  const anneau = (login) => page.evaluate((l) => {
    const c = [...document.querySelectorAll('.side-nav-card')].find(x => x.dataset.tseLogin === l);
    if (!c) return null;
    // La cascade COMPLÈTE de avatarOf() : c'est elle qui fait autorité sur
    // « où est l'avatar », et c'est elle que la décoration doit suivre.
    const av = c.querySelector('.side-nav-card__avatar figure')
            || c.querySelector('.side-nav-card__avatar .tw-avatar')
            || c.querySelector('figure.tw-avatar')
            || c.querySelector('.tw-avatar')
            || c.querySelector('img.tw-image-avatar')?.closest('figure, .tw-avatar, div');
    if (!av) return { forme: 'introuvable' };
    const ap = getComputedStyle(av, '::after');
    return {
      forme:  av.tagName.toLowerCase(),
      anneau: ap.content !== 'none',
      anim:   ap.animationName,
      halo:   getComputedStyle(av).animationName,
    };
  }, login);

  const avecFigure = await anneau('etoiles');
  const sansFigure = await anneau('clem_mlrt');
  const horsBloc  = await anneau('hasanabi');
  ok('le harnais sert bien trois formes différentes',
     avecFigure?.forme === 'figure' && sansFigure?.forme === 'div'
     && horsBloc?.forme === 'figure',
     JSON.stringify([avecFigure?.forme, sansFigure?.forme, horsBloc?.forme]));
  ok('l\'avatar enveloppé d\'un <figure> porte l\'anneau',
     avecFigure?.anneau === true && avecFigure?.anim === 'tse-sub-turn',
     JSON.stringify(avecFigure));
  ok('celui qui n\'en a pas le porte aussi',
     sansFigure?.anneau === true && sansFigure?.anim === 'tse-sub-turn',
     JSON.stringify(sansFigure));
  ok('et son halo respire de même', sansFigure?.halo === 'tse-sub-souffle',
     JSON.stringify(sansFigure));
  // LE cas signalé : un avatar rendu hors du bloc habituel — une chaîne qui
  // publie des stories — n'avait pas d'anneau, alors que sa voisine en avait un.
  ok('et celui qui est rendu hors du bloc habituel aussi',
     horsBloc?.anneau === true && horsBloc?.anim === 'tse-sub-turn',
     JSON.stringify(horsBloc));
  ok('avec son halo', horsBloc?.halo === 'tse-sub-souffle', JSON.stringify(horsBloc));
  // LA forme qu'aucun sélecteur n'atteignait : hors du bloc ET sans <figure>.
  const nulPart = await anneau('domingo');
  ok('et celui qui cumule les deux différences aussi',
     nulPart?.anneau === true && nulPart?.anim === 'tse-sub-turn', JSON.stringify(nulPart));
  // La marque suit l'avatar, et elle est UNIQUE dans la carte : une carte
  // recyclée ne doit pas garder l'ancienne.
  ok('une seule marque d\'avatar par carte',
     await page.evaluate(() => [...document.querySelectorAll('.side-nav-card')]
       .every(c => c.querySelectorAll('.tse-sub-avatar').length <= 1)));
  // La marque doit TOMBER quand la carte cesse d'être abonnée — sinon un
  // anneau doré survivrait sur une chaîne quelconque, la carte ayant été
  // recyclée par React.
  await page.evaluate(() => {
    const c = [...document.querySelectorAll('.side-nav-card')]
      .find(x => x.dataset.tseLogin === 'etoiles');
    c.querySelector('a[href="/etoiles"]').setAttribute('href', '/recyclee');
  });
  await wait(page, 600);
  ok('et elle tombe quand la carte change de chaîne',
     await page.evaluate(() => {
       const c = [...document.querySelectorAll('.side-nav-card')]
         .find(x => x.dataset.tseLogin === 'recyclee');
       return !!c && c.querySelectorAll('.tse-sub-avatar').length === 0;
     }));
  await page.close();
}

titre('56. Filtres — la rangée de tri est alignée sur celle des filtres');
{
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const page = await freshTwitch(PLAYER, [], '/');
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = { alpha: { id: '1', createdAt: h, viewers: 500, game: 'G', tags: [] } };
    window.__addCard('alpha', 'G', '500');
  });
  await wait(page, 1500);
  const bords = await page.evaluate(() => {
    const filtres = document.querySelector('.tse-filter-row');
    const boutons = [...document.querySelectorAll('#tse-sort-row button[data-tse-sort-mode]')];
    if (!filtres || boutons.length < 2) return null;
    const f = filtres.getBoundingClientRect();
    const p = boutons[0].getBoundingClientRect();
    const d = boutons[boutons.length - 1].getBoundingClientRect();
    return { gauche: +(p.left - f.left).toFixed(2), droite: +(f.right - d.right).toFixed(2),
             largeur: +p.width.toFixed(2), n: boutons.length };
  });
  /* ── DEUX ASSERTIONS TOURNÉES : ÉTALÉ N'EST PAS CENTRÉ ──────────────────
     Elles exigeaient que le premier bouton TOUCHE le bord gauche des filtres
     et le dernier le bord droit — c'est-à-dire « justify-content:
     space-between ». C'était juste tant que les six boutons étaient toujours
     là : ils remplissaient la rangée, et l'étalement se confondait avec un
     alignement.

     LES RÉGLAGES ONT RENDU LEUR NOMBRE VARIABLE, et l'étalement est devenu
     absurde — à deux boutons, un dans chaque coin. Un utilisateur l'a
     demandé : « il faut toujours centrer horizontalement, qu'il y en ait une,
     deux, trois, quatre, cinq ou six ». La rangée se centre donc, et ce qu'on
     exige n'est plus le contact avec les bords mais leur SYMÉTRIE — la seule
     propriété qui reste vraie dans les six cas.

     LA TROISIÈME ASSERTION NE BOUGE PAS, et c'est elle qui portait déjà le
     sens : marges égales. Elle était vraie sous « space-between » parce que
     les deux valaient zéro ; elle l'est encore, autrement. */
  ok('la rangée de tri est centrée dans celle des filtres',
     bords !== null && Math.abs(bords.gauche - bords.droite) <= 1, JSON.stringify(bords));
  ok('…et elle y tient, sans déborder d\'un côté ni de l\'autre',
     bords !== null && bords.gauche >= -1 && bords.droite >= -1, JSON.stringify(bords));
  // La contrepartie assumée : des boutons un peu plus larges que les 28 px
  // d'origine, sans devenir des pavés.
  ok('les boutons se sont élargis en conséquence',
     bords !== null && bords.largeur > 28 && bords.largeur <= 44, JSON.stringify(bords));
  await page.close();
}

titre('57. Mémoire — un abonnement en cours passe avant un abonnement révolu');
{
  // Depuis que l'onglet des expirés est lu, des dizaines d'entrées arrivent
  // dans la même milliseconde que les abonnements en cours. Trier la purge sur
  // la seule date perdait alors des abonnements ACTIFS — ceux qui portent le
  // tri, la pastille et le style — au profit de révolus qui ne nourrissent
  // qu'un badge au survol.
  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const TROP = () => {
    window.__noSubsPage = true;
    const m = {};
    const t = Date.now();
    // 420 révolus, au-delà de la borne de 400, tous datés du même instant.
    for (let i = 0; i < 420; i++) m['revolu' + i] = [0, t, 3, 1];
    // Et cinq abonnements EN COURS, noyés dedans.
    for (let i = 0; i < 5; i++) m['actif' + i] = [1, t];
    try { localStorage.setItem('tse:subs', JSON.stringify(m)); } catch {}
  };
  const page = await freshTwitch(PLAYER, [], '/', TROP);
  await wait(page, 1200);
  const vue = await page.evaluate(() => window.tse.subs());
  const actifs = vue.filter(e => e.sub).map(e => e.login).sort();
  ok('la mémoire est bien ramenée sous la borne', vue.length <= 400, String(vue.length));
  ok('et les cinq abonnements en cours ont tous survécu',
     actifs.join(',') === 'actif0,actif1,actif2,actif3,actif4', JSON.stringify(actifs));
  await page.close();
}

// ═════════ 58. Aperçu — l'interstitielle de classification est levée ═════════
titre('58. Aperçu — l\'écran « Commencer à regarder » ne doit plus figer la vignette');
{
  /* Le lecteur étiqueté, reproduit d'après la capture du 02/09/2026 : un
     sur-cadre [data-a-target="content-classification-gate-overlay"] contenant
     le bouton « Commencer à regarder ». La vidéo n'existe QU'APRÈS le clic —
     c'est tout le problème qu'on corrige : sans clic, aucune image, donc aucun
     signal de première image, donc une vignette figée pour toujours.

     `cedeAuClic` sépare les deux mondes : à true le bouton fait son office ;
     à false il est là mais ne ferme rien, ce qui modélise le jour où Twitch
     changera son interstitielle sans changer le nom du bouton. Le harnais ne
     peut pas prédire ce jour-là ; il peut vérifier qu'on y dégrade proprement. */
  const lecteurEtiquete = (cedeAuClic) => `<!doctype html><html><body>
    <div data-a-target="content-classification-gate-overlay">
      <p>Le contenu de cette chaîne est destiné à certains publics</p>
      <button data-a-target="content-classification-gate-overlay-start-watching-button">
        Commencer à regarder
      </button>
      <button data-a-target="content-classification-gate-overlay-go-home-button">
        Aller sur l'accueil
      </button>
    </div>
    <script>
      /* L'écouteur est posé AVANT les modules, et l'ordre est tout sauf un
         détail : à l'inverse, le pont cliquait un bouton encore sourd, la
         modale ne se fermait pas, et le harnais accusait le produit d'un défaut
         qui n'était que le sien. Sur le vrai Twitch, React attache son
         gestionnaire en rendant l'interstitielle — donc bien avant qu'un
         script tiers ne puisse cliquer. */
      window.__clics = 0;
      const zone = document.querySelector('[data-a-target="content-classification-gate-overlay"]');
      zone.querySelector('button').addEventListener('click', () => {
        window.__clics++;
        ${cedeAuClic ? `
        zone.remove();
        // La vidéo n'arrive qu'ici : c'est l'acquittement qui la débloque.
        const c = document.createElement('canvas');
        c.width = 32; c.height = 18;
        const ctx = c.getContext('2d');
        const v = document.createElement('video');
        v.autoplay = true; v.muted = true; v.playsInline = true;
        v.srcObject = c.captureStream(25);
        document.body.appendChild(v);
        v.play().catch(() => {});
        setInterval(() => {
          ctx.fillStyle = '#' + Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0');
          ctx.fillRect(0, 0, 32, 18);
        }, 40);
        ` : '/* le bouton ne ferme rien : la modale tient bon */'}
      });
    </script>
    <script src="/adblock.test.js"></script>
    <script src="/content.test.js"></script>
  </body></html>`;

  const etatIframe = (page) => page.evaluate(() => {
    const f = document.querySelector('.tse-preview__iframe');
    return f ? (f.dataset.tseLoaded ?? 'posee') : 'pas-d-iframe';
  });
  // Le compteur de clics vit dans l'iframe : on va le chercher par sa frame.
  const clics = async (page) => {
    const f = page.frames().find(x => x.url().startsWith('https://player.twitch.tv/'));
    if (!f) return -1;
    try { return await f.evaluate(() => window.__clics ?? -1); } catch { return -1; }
  };
  const poserCarte = (page, login) => page.evaluate((l) => {
    window.__fx = { [l]: { id:'1', createdAt:new Date(Date.now()-3600_000).toISOString(),
                           viewers:1000, game:'G', tags:[],
                           // L'étiquette qui, jusqu'ici, suffisait à supprimer l'iframe.
                           ccl: [{ id: 'MatureGame' }] } };
    window.__addCard(l, 'G', '1 k');
  }, login);

  // ── a) l'interstitielle cède : la vidéo part, l'aperçu se dévoile ────────
  {
    const page = await freshTwitch(lecteurEtiquete(true));
    await poserCarte(page, 'alpha');
    await wait(page, 2000);
    await hoverCard(page, 0);

    // Avant tout : l'iframe doit exister. Jusqu'à la 3.54, une étiquette de
    // classification la faisait annuler — c'est le renoncement qu'on lève.
    await attendre(page, () => !!document.querySelector('.tse-preview__iframe'), 4000);
    ok('une chaîne étiquetée reçoit bien une iframe',
       (await etatIframe(page)) !== 'pas-d-iframe', await etatIframe(page));

    // La question qui compte pour l'œil : rien ne doit changer AVANT que la
    // vidéo ne parte. La vignette est dans le même conteneur que l'iframe, qui
    // se pose PAR-DESSUS et reste transparente jusqu'à sa première image — le
    // même enchaînement que sur une chaîne sans étiquette. C'est structurel, pas
    // une affaire d'instant : on le vérifie comme tel.
    const socle = await page.evaluate(() => {
      const wrap = document.querySelector('.tse-preview__thumb-wrap');
      const img = wrap && wrap.querySelector('.tse-preview__thumb');
      const f = wrap && wrap.querySelector('.tse-preview__iframe');
      return { vignette: !!img, chargee: img ? (img.dataset.tseLoaded ?? null) : null,
               memeConteneur: !!(img && f) };
    });
    ok('la vignette est posée sous l\'iframe, comme sans modale',
       socle.vignette && socle.memeConteneur && socle.chargee === 'true',
       JSON.stringify(socle));

    await attendre(page, () => {
      const f = document.querySelector('.tse-preview__iframe');
      return !!f && f.dataset.tseLoaded === 'true';
    }, 8000);
    ok('et elle se dévoile, donc la vidéo joue', (await etatIframe(page)) === 'true',
       await etatIframe(page));

    const n = await clics(page);
    ok('le bouton « Commencer à regarder » a bien été cliqué', n >= 1, String(n));
    ok('et une seule fois, sans boucle', n === 1, String(n));
    await page.close();
  }

  /* ── a bis) L'ORDRE DE LA PRODUCTION : la <video> AVANT la modale ─────────

     Le cas qui a échappé à la 3.55, et le seul qui compte vraiment : Twitch
     pose son élément <video> avec le lecteur, puis rend l'écran d'acquittement
     par-dessus. La veille du pont s'arrêtait alors juste avant — « une vidéo
     est sous surveillance, aucune modale à l'écran, il n'y a plus rien à
     faire » — et la modale apparaissait dans une frame que plus personne ne
     regardait. Le harnais ne pouvait pas le voir : il rendait sa modale
     d'emblée, donc AVANT la vidéo.

     La <video> est ici présente dès le départ mais SANS flux : readyState 0,
     aucun `playing`. Elle ne reçoit son canvas qu'au clic. C'est exactement ce
     que fait un lecteur bloqué par son écran d'acquittement. */
  {
    const lecteurVideoDAbord = `<!doctype html><html><body>
      <video id="v" autoplay muted playsinline></video>
      <script>
        window.__clics = 0;
        window.__modaleA = null;
        // La modale n'arrive qu'APRÈS : 400 ms, largement de quoi laisser la
        // veille se retirer si elle a le droit de le faire.
        setTimeout(() => {
          const zone = document.createElement('div');
          zone.setAttribute('data-a-target', 'content-classification-gate-overlay');
          zone.innerHTML = '<p>destiné à certains publics</p>' +
            '<button data-a-target="content-classification-gate-overlay-start-watching-button"' +
            ' style="width:120px;height:32px">Commencer à regarder</button>';
          document.body.appendChild(zone);
          window.__modaleA = performance.now();
          zone.querySelector('button').addEventListener('click', () => {
            window.__clics++;
            zone.remove();
            const c = document.createElement('canvas');
            c.width = 32; c.height = 18;
            const ctx = c.getContext('2d');
            const v = document.getElementById('v');
            v.srcObject = c.captureStream(25);
            v.play().catch(() => {});
            setInterval(() => {
              ctx.fillStyle = '#' + Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0');
              ctx.fillRect(0, 0, 32, 18);
            }, 40);
          });
        }, 400);
      </script>
      <script src="/adblock.test.js"></script>
      <script src="/content.test.js"></script>
    </body></html>`;

    const page = await freshTwitch(lecteurVideoDAbord);
    await poserCarte(page, 'omega');
    await wait(page, 2000);
    await hoverCard(page, 0);

    await attendre(page, () => {
      const f = document.querySelector('.tse-preview__iframe');
      return !!f && f.dataset.tseLoaded === 'true';
    }, 9000);
    /* Dévoilée ET en train de jouer. La seule chose dévoilée ne prouve rien :
       sous la régression, le filet ordinaire dévoilait AUSSI — sauf qu'il
       dévoilait la modale. C'est la lecture effective qui sépare les deux. */
    const lecture = await (async () => {
      const f = page.frames().find(x => x.url().startsWith('https://player.twitch.tv/'));
      if (!f) return null;
      try {
        return await f.evaluate(() => {
          const v = document.getElementById('v');
          return v ? { pause: v.paused, pret: v.readyState } : null;
        });
      } catch { return null; }
    })();
    ok('modale rendue APRÈS la vidéo : l\'aperçu se dévoile ET la vidéo joue',
       (await etatIframe(page)) === 'true'
       && !!lecture && lecture.pause === false && lecture.pret >= 2,
       JSON.stringify({ iframe: await etatIframe(page), lecture }));
    const n = await clics(page);
    ok('et le bouton a bien été cliqué, la veille ne s\'était pas retirée',
       n === 1, String(n));

    // Le journal de diagnostic doit raconter la même histoire, dans l'ordre.
    const journal = await page.evaluate(() => window.tse.apercu().map(e => e.evt));
    ok('le journal note le pont, la modale, puis la première image',
       journal.includes('pont') && journal.includes('modale')
       && journal.indexOf('modale') < journal.indexOf('premiere-image'),
       JSON.stringify(journal));
    await page.close();
  }

  /* ── a ter) LE NŒUD <video> EST REMPLACÉ APRÈS L'ACQUITTEMENT ────────────

     Un lecteur ne garde pas forcément le même élément vidéo d'un bout à
     l'autre : quand la source repart — ce qui est précisément ce que fait
     l'acquittement de l'interstitielle — Twitch peut jeter son <video> et en
     poser un neuf. Le pont surveillait « une vidéo, la première trouvée » ; il
     restait alors accroché à un nœud détaché, où `playing` n'arrive jamais.
     Aucune première image annoncée, donc le filet d'interstitielle rend la main
     à la vignette — au moment même où la vidéo joue à côté, dans l'autre nœud.

     Le harnais force ce remplacement au clic. Sans le correctif, l'iframe
     disparaît ; avec, elle se dévoile et c'est le NOUVEAU nœud qui joue. */
  {
    const lecteurVideoRemplacee = `<!doctype html><html><body>
      <video id="v1" autoplay muted playsinline></video>
      <script>
        window.__clics = 0;
        setTimeout(() => {
          const zone = document.createElement('div');
          zone.setAttribute('data-a-target', 'content-classification-gate-overlay');
          zone.innerHTML = '<p>destiné à certains publics</p>' +
            '<button data-a-target="content-classification-gate-overlay-start-watching-button"' +
            ' style="width:120px;height:32px">Commencer à regarder</button>';
          document.body.appendChild(zone);
          zone.querySelector('button').addEventListener('click', () => {
            window.__clics++;
            zone.remove();
            // Le point du scénario : l'ancien nœud s'en va, un neuf le remplace.
            document.getElementById('v1').remove();
            const c = document.createElement('canvas');
            c.width = 32; c.height = 18;
            const ctx = c.getContext('2d');
            const v = document.createElement('video');
            v.id = 'v2';
            v.autoplay = true; v.muted = true; v.playsInline = true;
            v.srcObject = c.captureStream(25);
            document.body.appendChild(v);
            v.play().catch(() => {});
            setInterval(() => {
              ctx.fillStyle = '#' + Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0');
              ctx.fillRect(0, 0, 32, 18);
            }, 40);
          });
        }, 400);
      </script>
      <script src="/adblock.test.js"></script>
      <script src="/content.test.js"></script>
    </body></html>`;

    const page = await freshTwitch(lecteurVideoRemplacee);
    await poserCarte(page, 'sigma');
    await wait(page, 2000);
    await hoverCard(page, 0);

    await attendre(page, () => {
      const f = document.querySelector('.tse-preview__iframe');
      return !!f && f.dataset.tseLoaded === 'true';
    }, 9000);
    const relais = await (async () => {
      const f = page.frames().find(x => x.url().startsWith('https://player.twitch.tv/'));
      if (!f) return null;
      try {
        return await f.evaluate(() => {
          const v = document.querySelector('video');
          return v ? { id: v.id, pause: v.paused, pret: v.readyState } : null;
        });
      } catch { return null; }
    })();
    ok('un <video> remplacé est repris en surveillance : l\'aperçu joue quand même',
       (await etatIframe(page)) === 'true'
       && !!relais && relais.id === 'v2' && relais.pause === false && relais.pret >= 2,
       JSON.stringify({ iframe: await etatIframe(page), relais }));
    await page.close();
  }

  // ── b) l'interstitielle tient bon : retour à la vignette, pas de modale ──
  {
    const page = await freshTwitch(lecteurEtiquete(false));
    await poserCarte(page, 'beta');
    await wait(page, 2000);
    await hoverCard(page, 0);

    await attendre(page, () => !!document.querySelector('.tse-preview__iframe'), 4000);
    ok('l\'iframe est tentée malgré tout', (await etatIframe(page)) !== 'pas-d-iframe',
       await etatIframe(page));

    // Le filet ORDINAIRE (1,5 s) dévoilerait ici. Il ne doit pas : ce qu'il
    // dévoilerait n'est pas un lecteur noir mais une modale en travers de
    // l'aperçu. C'est l'assertion qui distingue les deux filets.
    await wait(page, 2000);
    ok('le filet ordinaire ne dévoile pas la modale', (await etatIframe(page)) !== 'true',
       await etatIframe(page));

    // Et pendant ces deux secondes, ce que l'utilisateur voit est la vignette :
    // l'iframe est bien là, mais transparente. C'est ce qui distingue « pas
    // encore de vidéo » de « une modale en travers de l'aperçu ».
    const dessous = await page.evaluate(() => {
      const img = document.querySelector('.tse-preview__thumb');
      const f = document.querySelector('.tse-preview__iframe');
      return { chargee: img ? (img.dataset.tseLoaded ?? null) : null,
               opaciteIframe: f ? getComputedStyle(f).opacity : null };
    });
    ok('la vignette reste visible et l\'iframe transparente',
       dessous.chargee === 'true' && dessous.opaciteIframe === '0',
       JSON.stringify(dessous));

    // Et le filet d'interstitielle rend la main à la vignette.
    await attendre(page, () => !document.querySelector('.tse-preview__iframe'), 6000);
    ok('l\'iframe est retirée, la vignette reprend la main',
       (await etatIframe(page)) === 'pas-d-iframe', await etatIframe(page));
    const vignette = await page.evaluate(() =>
      !!document.querySelector('.tse-preview__thumb'));
    ok('et la vignette est toujours là pour la remplacer', vignette, String(vignette));
    await page.close();
  }
}

// ═════════ 59. Aperçu — le badge des étiquettes de classification ═════════
titre('59. Aperçu — ce que l\'interstitielle disait, le badge le dit maintenant');
{
  /* Lever l'écran d'acquittement sans afficher les étiquettes reviendrait à
     SUPPRIMER l'information au lieu de la déplacer. Ce scénario vérifie qu'elle
     est bien déplacée — et qu'un identifiant inconnu ne fuit pas brut dans
     l'interface. Le harnais tourne en français : les libellés attendus sont
     ceux de la table française. */
  const PLAYER_NU = '<!doctype html><html><body>lecteur</body></html>';
  const badgeCcl = (page) => page.evaluate(() => {
    const b = document.querySelector('.tse-preview__badge--ccl');
    if (!b) return null;
    const zone = b.parentElement;
    return {
      texte: b.querySelector('.tse-preview__badge-text').textContent.trim(),
      // Un avertissement se lit avant le contexte : il doit être le premier.
      premier: zone.firstElementChild === b,
      // La composition interne du badge, dans l'ordre du DOM.
      enfants: [...b.children].map(n => ({
        classe: n.className, texte: n.textContent.trim(),
        muet: n.getAttribute('aria-hidden'),
      })),
    };
  });
  const poser = (page, fixtures) => page.evaluate((fx) => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    window.__fx = {};
    for (const [login, ccl] of Object.entries(fx)) {
      window.__fx[login] = { id: 'id-' + login, createdAt: h, viewers: 1000,
                             game: 'G', tags: [], ccl };
      window.__addCard(login, 'G', '1 k');
    }
  }, fixtures);

  {
    const page = await freshTwitch(PLAYER_NU);
    await poser(page, {
      alpha: [{ id: 'MatureGame' }],
      beta:  [{ id: 'Gambling' }, { id: 'SexualThemes' }],
      gamma: [{ id: 'UneEtiquetteQueTwitchAjouteraUnJour' }],
      delta: [],
    });
    await wait(page, 2000);

    await hoverCard(page, 0);
    await attendre(page, () => !!document.querySelector('.tse-preview__badge--ccl'), 5000);
    const un = await badgeCcl(page);
    ok('une étiquette connue est traduite', un && un.texte === 'Jeux matures',
       JSON.stringify(un));
    ok('et le badge passe en tête des autres', !!un && un.premier === true,
       JSON.stringify(un));
    /* Le pictogramme encadre le texte des DEUX côtés. À gauche seulement, il
       passerait pour une puce de liste ; de part et d'autre, il fait un
       panneau. Et il est aria-hidden : une synthèse vocale doit lire « Jeux
       matures », pas « avertissement Jeux matures avertissement ». */
    const marques = (un && un.enfants) || [];
    ok('un pictogramme ⚠️ de chaque côté du texte, muet pour les lecteurs d\'écran',
       marques.length === 3
       && marques[0].classe === 'tse-preview__badge-mark' && marques[0].texte === '⚠️'
       && marques[1].classe === 'tse-preview__badge-text'
       && marques[2].classe === 'tse-preview__badge-mark' && marques[2].texte === '⚠️'
       && marques[0].muet === 'true' && marques[2].muet === 'true',
       JSON.stringify(marques));
    /* ATTENDRE LA FERMETURE, PUIS LA RÉOUVERTURE, et pas seulement le badge.
       Le popup est un singleton : il reste dans le document, invisible, avec
       les badges de la carte précédente. « il existe un badge CCL » était donc
       vrai AVANT que la carte suivante n'ait rendu quoi que ce soit, et cette
       attente-là se satisfaisait du badge de la carte d'avant. Elle passait par
       chance tant que l'aperçu s'ouvrait dans l'instant ; le délai d'intention
       de la 3.95 a fait apparaître ce qu'elle mesurait vraiment. Le repère
       juste est la VISIBILITÉ, que open() ne pose qu'après avoir reconstruit
       toute la rangée de badges. */
    await unhoverCard(page, 0);
    await attendre(page,
      () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);

    await hoverCard(page, 1);
    await attendre(page,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 5000);
    await attendre(page, () => !!document.querySelector('.tse-preview__badge--ccl'), 5000);
    const deux = await badgeCcl(page);
    ok('deux étiquettes tiennent dans un seul badge',
       !!deux && deux.texte === 'Jeux d\'argent · Thèmes sexuels', JSON.stringify(deux));
    await unhoverCard(page, 1);
    await attendre(page,
      () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);

    await hoverCard(page, 2);
    await attendre(page,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 5000);
    await attendre(page, () => !!document.querySelector('.tse-preview__badge--ccl'), 5000);
    const trois = await badgeCcl(page);
    // Le point qui compte : « UneEtiquetteQueTwitchAjouteraUnJour » dans une
    // interface française serait pire que rien.
    ok('une étiquette inconnue passe au libellé générique, jamais son identifiant',
       !!trois && trois.texte === 'Contenu classifié', JSON.stringify(trois));
    await unhoverCard(page, 2);
    await attendre(page,
      () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);

    await hoverCard(page, 3);
    await wait(page, 1500);
    const quatre = await badgeCcl(page);
    ok('et une chaîne sans étiquette n\'a pas de badge du tout', quatre === null,
       JSON.stringify(quatre));
    await page.close();
  }
}

// ═════════ 60. Aperçu — chaque type de badge a SA couleur ═════════
titre('60. Aperçu — chaque type de badge a sa couleur, et elles sont distinctes');
{
  /* Le défaut que ce scénario existe pour empêcher est déjà arrivé : le badge
     d'étiquettes est né ambre, à 2° de teinte du badge hype train — la même
     couleur à l'œil, sur deux badges qui peuvent coexister. Personne ne l'avait
     vu, parce que « ambre » et « orange » sont deux mots différents et que
     personne n'avait sorti la calculatrice.

     Deux choses sont vérifiées, et il faut les deux :
      a) chaque type a une couleur DÉFINIE — une classe sans règle héritera du
         gris de base sans que rien ne proteste ;
      b) les couleurs sont DISTINCTES — deux règles peuvent exister et dire la
         même chose.

     Le type « other » (ligne annexe non identifiée, cf. markExtraRows) est
     volontairement absent de la liste : il n'a pas de modificateur et tombe sur
     le gris de base, ce qui est sa couleur définie. */
  const TYPES = ['hype', 'discount', 'costream', 'squad', 'sponsor', 'sub', 'exsub', 'ccl'];

  const page = await freshTwitch('<!doctype html><html><body>lecteur</body></html>');
  await wait(page, 2000);
  const releve = await page.evaluate((types) => {
    // Les badges sont mesurés DANS le popup : sa couleur de fond compose les
    // fonds translucides, et c'est la composition qui se voit, pas le rgba.
    const hote = document.createElement('div');
    hote.className = 'tse-preview';
    hote.style.cssText = 'opacity:1;left:0;top:0';
    hote.innerHTML = '<div class="tse-preview__body"><div class="tse-preview__badges">' +
      types.map(t => `<span class="tse-preview__badge tse-preview__badge--${t}">x</span>`).join('') +
      '<span class="tse-preview__badge">base</span>' +
      '</div></div>';
    document.body.appendChild(hote);
    const lus = [...hote.querySelectorAll('.tse-preview__badge')].map(el => {
      const cs = getComputedStyle(el);
      return { fond: cs.backgroundColor, texte: cs.color };
    });
    const popup = getComputedStyle(hote).backgroundColor;
    hote.remove();
    return { lus, popup };
  }, TYPES);

  const rgba = (s) => (s.match(/[\d.]+/g) || []).map(Number);
  const composer = ([r, g, b, a = 1], base) =>
    [r * a + base[0] * (1 - a), g * a + base[1] * (1 - a), b * a + base[2] * (1 - a)];
  const teinte = ([r, g, b]) => {
    r /= 255; g /= 255; b /= 255;
    const mx = Math.max(r, g, b), mn = Math.min(r, g, b), d = mx - mn;
    if (!d) return null;                       // gris : pas de teinte à comparer
    const h = mx === r ? ((g - b) / d + (g < b ? 6 : 0)) : mx === g ? ((b - r) / d + 2)
                                                                    : ((r - g) / d + 4);
    return Math.round(h * 60);
  };
  const ecart = (a, b) => { const d = Math.abs(a - b) % 360; return Math.round(d > 180 ? 360 - d : d); };
  const fondPopup = rgba(releve.popup);
  const base = releve.lus[TYPES.length];       // le badge sans modificateur
  const badges = TYPES.map((t, i) => ({
    type: t,
    fond: releve.lus[i].fond, texte: releve.lus[i].texte,
    hFond: teinte(composer(rgba(releve.lus[i].fond), fondPopup)),
    hTexte: teinte(rgba(releve.lus[i].texte)),
  }));

  // a) une couleur DÉFINIE : ni le fond ni le texte ne doivent être ceux du
  //    badge de base, sinon la classe n'a simplement pas de règle.
  const sansRegle = badges.filter(b => b.fond === base.fond || b.texte === base.texte);
  ok('les huit types de badge ont chacun une couleur définie',
     sansRegle.length === 0, JSON.stringify(sansRegle.map(b => b.type)));

  // b) DISTINCTES : deux règles peuvent exister et dire la même chose.
  const doublons = [];
  for (let i = 0; i < badges.length; i++) for (let j = i + 1; j < badges.length; j++) {
    if (badges[i].fond === badges[j].fond) doublons.push([badges[i].type, badges[j].type, 'fond']);
    if (badges[i].texte === badges[j].texte) doublons.push([badges[i].type, badges[j].type, 'texte']);
  }
  ok('et aucune paire ne partage exactement la même couleur',
     doublons.length === 0, JSON.stringify(doublons));

  /* c) L'écart de TEINTE, qui est ce que l'œil lit vraiment, avec le seuil de
        20° sous lequel deux teintes cessent d'être deux couleurs.

        Trois paires en sont dispensées, et aucune ne l'est par commodité :

         • sub ↔ exsub (2°) — c'est le MÊME or à dessein. « Abonné » et « ancien
           abonné » sont le même signal, l'un désaturé ; les distinguer par la
           teinte contredirait ce qu'ils disent.

         • hype ↔ sub (13°) et hype ↔ exsub (15°) — les deux teintes sont
           ANCRÉES hors de la palette : l'orange du hype est celui de Twitch
           (rgb 255,105,5), l'or du badge d'abonnement est celui du filet des
           cartes abonnées (--tse-sub-or, 38°), qui existe précisément pour
           qu'on reconnaisse le signal d'une surface à l'autre. Les écarter
           demanderait de rompre l'un des deux ancrages — un arbitrage de
           produit, pas une correction, et il n'a pas été rendu.

        La différence avec l'ambre que le rouge remplace est là : l'ambre
        n'était ancrée à rien. Elle était libre, et elle s'était posée à 2° du
        hype train. Cette liste ne doit donc s'allonger que pour une couleur
        qui, elle aussi, tient à quelque chose d'extérieur. */
  const ANCREES = new Set(['sub|exsub', 'hype|sub', 'hype|exsub']);
  const trop = [];
  for (let i = 0; i < badges.length; i++) for (let j = i + 1; j < badges.length; j++) {
    const a = badges[i], b = badges[j];
    if (ANCREES.has(`${a.type}|${b.type}`)) continue;
    if (a.hTexte == null || b.hTexte == null) continue;
    const d = ecart(a.hTexte, b.hTexte);
    if (d < 20) trop.push([a.type, b.type, d + '°']);
  }
  ok('aucune paire librement choisie sous 20° de teinte',
     trop.length === 0, JSON.stringify(trop));

  /* d) La paire qui a motivé le rouge, nommée explicitement. Le badge
        d'étiquettes et le hype train peuvent coexister sur la même chaîne, et
        ils étaient à 2°. Sur le TEXTE comme sur le FOND : la 3.55 les avait
        rapprochés des deux côtés à la fois. */
  const ccl = badges.find(b => b.type === 'ccl');
  const hype = badges.find(b => b.type === 'hype');
  ok('le badge d\'étiquettes est franchement rouge, loin de l\'orange du hype train',
     ecart(ccl.hTexte, hype.hTexte) >= 20 && ecart(ccl.hFond, hype.hFond) >= 20
     && (ccl.hTexte >= 330 || ccl.hTexte <= 10),
     JSON.stringify({ texte: [ccl.hTexte, hype.hTexte, ecart(ccl.hTexte, hype.hTexte) + '°'],
                      fond:  [ccl.hFond,  hype.hFond,  ecart(ccl.hFond,  hype.hFond)  + '°'] }));
  await page.close();
}

// ═════════ 61. Firefox — le pont privé des API que Chrome a en plus ═════════
titre('61. Firefox — l\'aperçu tient sans les API que Chrome a en plus');
{
  /* Ce dépôt ne peut pas lancer Firefox : la politique réseau de
     l'environnement bloque le téléchargement du binaire de Playwright. On ne
     va donc PAS prétendre avoir vérifié le portage bout en bout. Ce qu'on peut
     faire — et qui vaut mieux qu'une lecture — c'est reproduire dans Chromium
     les manques exacts de Firefox et regarder le code s'en sortir.

     Deux API que Chrome a et que Firefox n'a pas au plancher déclaré (140),
     retirées par DEUX mécanismes différents, et la différence n'est pas un
     détail de mise en œuvre :

      • location.ancestorOrigins — jamais implémentée par Firefox avant ~148
        (Mozilla la tenait pour une fuite de vie privée). Le pont s'en sert
        pour VISER son postMessage ; sans elle, il retombe sur les deux
        origines que le manifeste déclare. C'est LA divergence du portage, et
        un repli cassé ne se verrait nulle part : l'aperçu ne se dévoilerait
        simplement jamais sous Firefox.

        Elle est [LegacyUnforgeable] — propriété propre, non configurable —
        donc impossible à retirer depuis la page. Le retrait se fait à la
        construction, sur une copie (cf. tests/build.mjs), et ce scénario
        charge cette variante : /content.firefox.test.js.

      • requestVideoFrameCallback — arrivée en Firefox 132, donc présente au
        plancher. Elle est tout de même retirée ici, et celle-là POUR DE VRAI
        depuis la page : le réglage media.rvfc.enabled peut la couper, et la
        course à trois signaux du pont doit tenir sur les deux qui restent.

     Le décor est VÉRIFIÉ avant tout le reste (window.__fxSansApi). La première
     version de ce scénario croyait retirer ancestorOrigins par `delete` et ne
     retirait rien : ses deux assertions vertes ne testaient personne. */
  const lecteurFirefox = `<!doctype html><html><body>
    <script>
      // rVFC vit sur le prototype et s'y supprime pour de bon. ancestorOrigins,
      // elle, résiste — c'est la variante de build qui s'en charge.
      delete HTMLVideoElement.prototype.requestVideoFrameCallback;
      window.__fxSansApi = {
        rvfc: !('requestVideoFrameCallback' in HTMLVideoElement.prototype),
      };
    </script>
    <script>
      const c = document.createElement('canvas');
      c.width = 32; c.height = 18;
      const ctx = c.getContext('2d');
      const v = document.createElement('video');
      v.autoplay = true; v.muted = true; v.playsInline = true;
      v.srcObject = c.captureStream(25);
      document.body.appendChild(v);
      v.play().catch(() => {});
      setInterval(() => {
        ctx.fillStyle = '#' + Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0');
        ctx.fillRect(0, 0, 32, 18);
      }, 40);
    </script>
    <script src="/adblock.test.js"></script>
    <script src="/content.firefox.test.js"></script>
  </body></html>`;

  const page = await freshTwitch(lecteurFirefox);
  await page.evaluate(() => {
    window.__fx = { renard: { id: 'r1', createdAt: new Date(Date.now() - 3600_000).toISOString(),
                              viewers: 1000, game: 'G', tags: [] } };
    window.__addCard('renard', 'G', '1 k');
  });
  await wait(page, 2000);
  await hoverCard(page, 0);

  await attendre(page, () => {
    const f = document.querySelector('.tse-preview__iframe');
    return !!f && f.dataset.tseLoaded === 'true';
  }, 9000);

  // D'abord : le décor est-il bien celui qu'on croit ? Un `delete` qui aurait
  // échoué rendrait tout le reste du scénario complaisant.
  const decor = await (async () => {
    const f = page.frames().find(x => x.url().startsWith('https://player.twitch.tv/'));
    if (!f) return null;
    try {
      return await f.evaluate(() => ({
        rvfc: window.__fxSansApi?.rvfc ?? null,
        // La variante de build est-elle bien celle qui tourne ? On lit la
        // ligne substituée dans le source servi, pas une intention.
        variante: [...document.scripts].some(s => s.src.endsWith('/content.firefox.test.js')),
      }));
    } catch { return null; }
  })();
  ok('le décor est bien celui qu\'on croit : rVFC retirée, variante Firefox chargée',
     !!decor && decor.rvfc === true && decor.variante === true,
     JSON.stringify(decor));

  const etat = await page.evaluate(() => {
    const f = document.querySelector('.tse-preview__iframe');
    return f ? (f.dataset.tseLoaded ?? 'posee') : 'pas-d-iframe';
  });
  ok('sans ancestorOrigins ni rVFC, l\'aperçu se dévoile quand même',
     etat === 'true', etat);

  /* Le postMessage a bien traversé : c'est LE point du repli d'origines. Le
     journal ne peut porter « pont » que si un message est arrivé au parent,
     donc si la cible de repli était la bonne. */
  const journal = await page.evaluate(() => window.tse.apercu().map(e => e.evt));
  ok('le pont a parlé et la première image est passée par les origines de repli',
     journal.includes('pont') && journal.includes('premiere-image'),
     JSON.stringify(journal));
  await page.close();
}

// ═════════ 62. Le rendu ne construit plus de balisage ═════════
titre('62. Rendu — une donnée de Twitch est du TEXTE, jamais du balisage');
{
  /* Ce scénario existe pour une raison précise. Jusqu'ici le rendu assemblait
     des chaînes HTML et comptait sur `escapeHtml` à chaque point d'insertion.
     C'était correct — on l'a relu site par site — mais la correction tenait à
     ce qu'aucun appel n'oublie l'échappement, et aucune relecture ne garantit
     ça pour l'avenir. Le rendu construit maintenant des NŒUDS : les valeurs
     venues de Twitch passent par textContent ou setAttribute, qui ne peuvent
     rien interpréter. `escapeHtml` a disparu du fichier faute d'appelant.

     Le banc ne couvrait ni le contenu de ces badges ni cette propriété : la
     refonte aurait pu perdre le <strong> des noms, ou pire, sans rien casser
     de visible. Trois choses sont donc vérifiées ici — la phrase traduite, le
     <strong> autour du nom, et qu'un nom hostile reste du texte. */
  const PIEGE = '<img src=x onerror="window.__injecte=1">Marmotte';

  const page = await freshTwitch('<!doctype html><html><body>lecteur</body></html>');
  await page.evaluate(() => { window.__injecte = 0; });

  // Carte « squad » : le badge « En live avec … » se déclenche sur un
  // mini-avatar dont l'alt porte le nom de l'invité (cf. getSquadInfo).
  await page.evaluate((piege) => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    window.__fx = {
      corbeau: { id: 'c1', createdAt: h, viewers: 1000, game: 'G', tags: [] },
      // La CATÉGORIE vient de l'API et alimente la liste déroulante des
      // filtres : c'est l'autre chemin par lequel du texte de Twitch atteint
      // le DOM, et il passe par le code refondu des options.
      belette: { id: 'b1', createdAt: h, viewers: 900, game: piege, tags: [] },
    };
    window.__addCard('corbeau', 'G', '1 k');
    window.__addCard('belette', 'G', '900');
    const carte = [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.querySelector('a')?.getAttribute('href') === '/corbeau');
    const mini = document.createElement('div');
    mini.className = 'primary-with-small-avatar__mini-avatar';
    const img = document.createElement('img');
    img.setAttribute('alt', piege);       // le nom de l'invité, piégé
    mini.appendChild(img);
    carte.querySelector('a').appendChild(mini);
  }, PIEGE);
  await wait(page, 2500);

  await hoverCard(page, 0);
  await attendre(page, () => !!document.querySelector('.tse-preview__badge--squad'), 5000);
  const squad = await page.evaluate(() => {
    const b = document.querySelector('.tse-preview__badge--squad');
    if (!b) return null;
    const fort = b.querySelector('strong');
    return {
      texte: b.textContent.trim(),
      nomEnGras: fort ? fort.textContent : null,
      // Le piège a-t-il produit un ÉLÉMENT ? C'est la question qui compte.
      imgInjectee: !!b.querySelector('img'),
      injecte: window.__injecte,
    };
  });

  /* La phrase traduite doit être intacte : le <strong> est sorti des tables de
     locale, mais pas un mot du libellé. Le harnais tourne en français. */
  ok('la phrase traduite a survécu à la sortie du HTML des locales',
     !!squad && squad.texte.startsWith('En live avec '), JSON.stringify(squad?.texte));

  ok('le nom de l\'invité est bien en gras, via la fente',
     !!squad && squad.nomEnGras === PIEGE, JSON.stringify(squad?.nomEnGras));

  /* LE point du scénario. Sous l'ancien rendu, oublier un escapeHtml ici
     insérait une <img> et exécutait son onerror. Avec textContent, le même
     nom est affiché caractère pour caractère et rien ne s'exécute. */
  ok('un nom hostile reste du texte : aucune balise, aucun code exécuté',
     !!squad && squad.imgInjectee === false && squad.injecte === 0,
     JSON.stringify({ img: squad?.imgInjectee, injecte: squad?.injecte }));
  await unhoverCard(page, 0);

  // L'autre chemin : la catégorie que Twitch renvoie, affichée dans la liste
  // déroulante des filtres (code des options, refondu lui aussi).
  const option = await page.evaluate((piege) => {
    const opts = [...document.querySelectorAll('.tse-dd--cat .tse-dd-opt')];
    const cible = opts.find(o => o.dataset.value === piege);
    if (!cible) return { trouvee: false, valeurs: opts.map(o => o.dataset.value) };
    return {
      trouvee: true,
      texte: cible.querySelector('.tse-dd-name')?.textContent ?? null,
      imgInjectee: !!cible.querySelector('img'),
      injecte: window.__injecte,
    };
  }, PIEGE);
  ok('une catégorie hostile s\'affiche en toutes lettres, sans rien exécuter',
     option.trouvee && option.texte === PIEGE
     && option.imgInjectee === false && option.injecte === 0,
     JSON.stringify(option));
  await page.close();
}

// ═════════ 63. Basculement de catégorie ═════════
titre('63. Aperçu — « Vient de passer sur … », et seulement quand c\'en est un');
{
  /* Twitch n'annonce nulle part qu'une chaîne vient de changer de catégorie :
     l'information naît de la COMPARAISON de deux relevés, que le pipeline fait
     déjà toutes les 30 s et jetait jusqu'ici.

     Tout le scénario porte sur la DISTINCTION demandée : un basculement en
     cours de session mérite le badge, un début de stream non. La différence se
     lit sur `stream.id`, que le harnais sait maintenant piloter (`sid`).

     Le badge est aussi PÉRISSABLE, et sa péremption est vérifiée par le temps
     réel du navigateur — pas par une horloge simulée : le harnais accélère les
     cadences du pipeline, jamais Date.now(). On abaisse donc le TTL depuis la
     page pour que dix minutes tiennent dans un test. */
  const page = await freshTwitch('<!doctype html><html><body>lecteur</body></html>');
  const badgeSwitch = (page) => page.evaluate(() => {
    const b = document.querySelector('.tse-preview__badge--switch');
    if (!b) return null;
    const zone = b.parentElement;
    return { texte: b.textContent.trim(),
             gras: b.querySelector('strong')?.textContent ?? null,
             premier: zone.firstElementChild === b };
  });

  const h = () => new Date(Date.now() - 3600_000).toISOString();
  await page.evaluate((ts) => {
    const vieux = new Date(Date.now() - 3600_000).toISOString();
    window.__fx = {
      // Bascule en cours de session : même sid, catégorie qui change.
      renard:  { id: 'r', sid: 's-fixe', createdAt: vieux, viewers: 1000, game: 'Pêche', tags: [] },
      // Nouvelle session : le sid changera EN MÊME TEMPS que la catégorie.
      blaireau:{ id: 'b', sid: 'sess-1',  createdAt: vieux, viewers: 900,  game: 'Pêche', tags: [] },
      // Témoin : ne bouge pas du tout.
      loutre:  { id: 'l', sid: 's-loutre', createdAt: vieux, viewers: 800, game: 'Pêche', tags: [] },
    };
    window.__addCard('renard', 'Pêche', '1 k');
    window.__addCard('blaireau', 'Pêche', '900');
    window.__addCard('loutre', 'Pêche', '800');
  }, h());
  await wait(page, 2500);

  // ── a) le témoin, avant tout : aucun badge sans changement ──────────────
  await hoverCard(page, 2);
  await wait(page, 1500);
  ok('une chaîne qui ne change pas de catégorie n\'a pas de badge',
     (await badgeSwitch(page)) === null, JSON.stringify(await badgeSwitch(page)));
  await unhoverCard(page, 2);

  // ── b) LE cas : bascule en cours de session ─────────────────────────────
  await page.evaluate(() => { window.__fx.renard.game = 'Elden Ring'; });
  await attendre(page, () => (window.tse.bascules?.() || []).length > 0, 6000);
  await hoverCard(page, 0);
  await attendre(page, () => !!document.querySelector('.tse-preview__badge--switch'), 5000);
  const bascule = await badgeSwitch(page);
  ok('un changement en cours de session affiche « Vient de passer sur … »',
     !!bascule && bascule.texte === 'Vient de passer sur Elden Ring', JSON.stringify(bascule));
  ok('le nom du jeu est en gras, via la fente',
     !!bascule && bascule.gras === 'Elden Ring', JSON.stringify(bascule?.gras));
  ok('et le badge est en tête : une nouvelle se lit avant le contexte',
     !!bascule && bascule.premier === true, JSON.stringify(bascule));
  await unhoverCard(page, 0);

  // ── c) un DÉBUT de stream n'est pas un basculement ──────────────────────
  /* Le sid change en même temps que la catégorie : c'est une nouvelle session,
     pas un streamer qui bascule. C'est exactement la confusion que le badge ne
     doit pas faire, et le seul point où `stream.id` gagne son existence. */
  await page.evaluate(() => {
    window.__fx.blaireau.sid = 'sess-2';
    window.__fx.blaireau.game = 'Minecraft';
  });
  await wait(page, 3000);
  await hoverCard(page, 1);
  await wait(page, 1500);
  const debut = await badgeSwitch(page);
  ok('une NOUVELLE session ne déclenche pas le badge, même si la catégorie diffère',
     debut === null, JSON.stringify(debut));
  await unhoverCard(page, 1);

  /* ── d) la péremption ────────────────────────────────────────────────────

     Le badge est PÉRISSABLE, et c'est la moitié de son comportement : celui
     qui ne s'efface pas finit par mentir sur la fraîcheur de ce qu'il annonce.

     tests/build.mjs ramène CATEGORY_SWITCH_TTL de dix minutes à 2,5 s, comme
     il le fait pour les autres durées de production. C'est donc la MÊME
     horloge et le MÊME code qui périment l'entrée — on ne déplace pas un
     horodatage à la main.

     Ce cas a d'ailleurs corrigé sa première écriture : le basculement de (b)
     avait déjà péri pendant les 3 s du cas (c), et l'assertion « encore
     frais » tombait. Elle mesurait l'ordre du scénario, pas le registre. D'où
     un basculement NEUF, déclenché ici. */
  await page.evaluate(() => { window.__fx.loutre.game = 'Factorio'; });
  await attendre(page, () =>
    window.tse.bascules().some(b => b['passée sur'] === 'Factorio'), 6000);
  const frais = await page.evaluate(() =>
    window.tse.bascules().find(b => b['passée sur'] === 'Factorio') ?? null);
  ok('un basculement neuf est listé, avec sa catégorie et son âge',
     !!frais && frais['il y a (s)'] >= 0, JSON.stringify(frais));

  await hoverCard(page, 2);
  await attendre(page, () => !!document.querySelector('.tse-preview__badge--switch'), 5000);
  ok('et son badge est bien à l\'écran avant la péremption',
     (await badgeSwitch(page))?.texte === 'Vient de passer sur Factorio',
     JSON.stringify(await badgeSwitch(page)));
  await unhoverCard(page, 2);

  await wait(page, 3000);
  const apres = await page.evaluate(() =>
    window.tse.bascules().filter(b => b['passée sur'] === 'Factorio').length);
  ok('passé le délai, le basculement n\'est plus listé', apres === 0, String(apres));

  await hoverCard(page, 2);
  await wait(page, 1500);
  ok('et le badge a disparu de l\'aperçu', (await badgeSwitch(page)) === null,
     JSON.stringify(await badgeSwitch(page)));
  await page.close();
}

// ═════════ 64. Les cinq langues ajoutées ═════════
titre('64. Localisation — italien, polonais, russe, japonais, chinois');
{
  /* La parité des clés (scénario 18) dit qu'aucune table n'a de trou. Elle ne
     dit rien de ce qui compte ici : que la langue se DÉTECTE, et que ce qui
     s'affiche soit juste dans cette langue.

     a) La DÉTECTION s'observe par un effet mesurable plutôt que par une
        variable interne : la clé `locale` de chaque table pilote le formatage
        des nombres. Si la table choisie est la bonne, 29339 s'écrit avec le
        séparateur du pays ; sinon, avec celui de l'anglais.

     b) Le PLURIEL SLAVE est le point aveugle du lot. Le français et l'anglais
        n'ont que deux formes ; le polonais et le russe en ont TROIS, et la
        troisième reprend la main sur 11-14 malgré leur chiffre des unités.
        Aucune relecture non slavophone ne repère une branche fausse — seul un
        tableau de valeurs le fait. Il est écrit à la main d'après la
        grammaire, JAMAIS recopié de la sortie du code : un tableau produit par
        le code ne ferait que confirmer son propre bug. */

  // ── a) la détection, lue dans deux effets mesurables ─────────────────────
  /* Le libellé français est RETIRÉ du DOM, et c'est le cœur du montage. La
     détection consulte d'abord les libellés natifs de Twitch ; le harnais en
     porte un en français, qui gagnerait sur html.lang et rendrait le test muet
     — première écriture de ce scénario, six assertions vertes en apparence et
     « 29,3 k » partout, c'est-à-dire du français.

     Sans ce libellé, on reproduit exactement la situation d'un utilisateur
     italien, polonais, russe, japonais ou chinois : l'interface de Twitch est
     dans une langue dont l'extension ne connaît AUCUN libellé, la détection
     passe donc par html.lang, et la sidebar tient sur son ancre structurelle
     (followed-side-nav-header). Les deux mécanismes de repli sont éprouvés
     ensemble, ce qui est bien ce qu'on veut vérifier. */
  const rendusDe = async (htmlLang) => {
    const page = await browser.newPage();
    page.on('pageerror', e => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
    await page.goto(URL_PAGE);
    await page.evaluate((l) => {
      document.querySelector('.side-nav-section').removeAttribute('aria-label');
      document.documentElement.lang = l;
      window.__fx = { alpha: { id: '1', createdAt: new Date(Date.now() - 3600_000).toISOString(),
                               viewers: 29339, game: 'G', tags: [] } };
      window.__addCard('alpha', 'G', '29 339');
    }, htmlLang);
    await wait(page, 2000);
    const s = await state(page);
    const onglet = await page.evaluate(() =>
      document.querySelector('.tse-mode-tab')?.textContent ?? null);
    await page.close();
    return { nombre: nz(s[0]?.shown ?? ''), onglet };
  };

  /* Deux signaux, et il faut les deux. Le LIBELLÉ prouve que c'est la bonne
     table qui est branchée ; le NOMBRE prouve que sa clé `locale` est juste —
     une table peut être choisie correctement et porter un mauvais code de
     locale, auquel cas les chiffres sortiraient dans la convention d'un autre
     pays sans que le texte le laisse voir.

     Les formats sont relevés DANS CHROMIUM, et il fallait le faire : l'ICU de
     Node rend « 29,3K » pour l'italien là où celle du navigateur rend
     « 29.339 ». Une valeur attendue prise dans le mauvais moteur fait échouer
     un test qui n'a rien à reprocher au code — c'est arrivé ici. Le japonais
     et le chinois comptent par myriades (2.9万), le polonais et le russe
     écrivent leur abréviation en toutes lettres. */
  for (const [htmlLang, libelle, nombre, nom] of [
    ['it-IT', 'Canali seguiti',        '29.339',    'italien'],
    ['pl-PL', 'Obserwowane kanały',    '29,3 tys.', 'polonais'],
    ['ru-RU', 'Отслеживаемые каналы',  '29,3 тыс.', 'russe'],
    ['ja-JP', 'フォロー中のチャンネル',      '2.9万',      'japonais'],
    ['zh-CN', '关注的频道',              '2.9万',      'chinois'],
  ]) {
    const r = await rendusDe(htmlLang);
    ok(`${nom} : le libellé vient de la bonne table`, r.onglet === libelle, String(r.onglet));
    ok(`${nom} : et sa clé locale formate les nombres du pays (${nombre})`,
       r.nombre === nombre, r.nombre);
  }

  /* zh-TW n'a pas sa table : il retombe sur `zh` par le préfixe à deux lettres,
     et non sur l'anglais. Mieux vaut du chinois simplifié que de l'anglais pour
     un lecteur de Taïwan. */
  const tw = await rendusDe('zh-TW');
  ok('zh-TW retombe sur la table chinoise, pas sur l\'anglais',
     tw.onglet === '关注的频道', String(tw.onglet));

  /* Et une langue vraiment inconnue retombe sur l'anglais — le défaut, qui
     doit rester atteignable maintenant que neuf préfixes le précèdent. */
  const xx = await rendusDe('xx-XX');
  ok('une langue inconnue retombe toujours sur l\'anglais',
     xx.onglet === 'Followed Channels', String(xx.onglet));

  // ── b) le pluriel slave, par analyse statique ────────────────────────────
  {
    const src = readFileSync(join(ICI, 'content.test.js'), 'utf8');
    const regle = src.match(/const plurielSlave = \([\s\S]*?\n {2}\};/)[0];
    const subMonthsDe = (lang) => {
      const bloc = src.match(new RegExp('\\n    ' + lang + ': Object\\.freeze\\(\\{([\\s\\S]*?)\\n    \\}\\)'))[1];
      return bloc.match(/uiBadgeSubMonths:\s*(\(n\) => `[^`]*`)/)[1];
    };
    const fabriquer = (lang) => new Function(`${regle}\nreturn ${subMonthsDe(lang)};`)();

    /* LES FORMES SONT ÉCRITES EN CAPITALES, comme le badge les affiche depuis
       que sa valeur est détachée par une puce (« Subskrypcja • 5 MIESIĘCY »).
       Ce n'est pas la casse qu'on éprouve ici mais la RÈGLE DE PLURIEL, qui
       ne change pas : trois formes, et le piège des 11-14. La recopier en
       minuscules aurait fait échouer douze comparaisons sur une question de
       typographie, ce qui aurait masqué la seule qui compte. */
    const attendus = {
      pl: { 1: '1 MIESIĄC', 2: '2 MIESIĄCE', 4: '4 MIESIĄCE', 5: '5 MIESIĘCY',
            11: '11 MIESIĘCY', 12: '12 MIESIĘCY', 14: '14 MIESIĘCY',
            21: '21 MIESIĄC', 22: '22 MIESIĄCE', 25: '25 MIESIĘCY',
            111: '111 MIESIĘCY', 122: '122 MIESIĄCE' },
      ru: { 1: '1 МЕСЯЦ', 2: '2 МЕСЯЦА', 4: '4 МЕСЯЦА', 5: '5 МЕСЯЦЕВ',
            11: '11 МЕСЯЦЕВ', 12: '12 МЕСЯЦЕВ', 14: '14 МЕСЯЦЕВ',
            21: '21 МЕСЯЦ', 22: '22 МЕСЯЦА', 25: '25 МЕСЯЦЕВ',
            111: '111 МЕСЯЦЕВ', 122: '122 МЕСЯЦА' },
    };
    for (const [lang, table] of Object.entries(attendus)) {
      const f = fabriquer(lang);
      const faux = [];
      for (const [n, attendu] of Object.entries(table)) {
        const rendu = f(Number(n));
        if (!rendu.endsWith(attendu)) faux.push(`${n} → « ${rendu} », attendu « …${attendu} »`);
      }
      ok(`pluriel ${lang} : les trois formes, y compris le piège des 11-14`,
         faux.length === 0, faux.join(' | '));
    }
  }
}

// ═════════ 65. Nom canonique et nom traduit ═════════
titre('65. Catégories — l\'identité décide, la traduction s\'affiche');
{
  /* Le défaut, tel qu'il se voyait : sous une interface française, la carte
     annonçait « Just Chatting » là où Twitch écrivait « Discussions ». La
     sidebar prenait le nom que rend `game.name` — le nom CANONIQUE, celui des
     URL — et l'écrivait par-dessus le libellé traduit que Twitch avait déjà
     posé. L'extension remplaçait donc du français par de l'anglais.

     Le nom canonique n'est pas pour autant à jeter : c'est lui, et lui seul,
     que `game(name:)` accepte, et c'est de lui que dépendent le filtre, le
     regroupement des co-streams et la détection d'un basculement. Les deux
     valeurs existent donc côte à côte — `game` pour l'identité, `gameLabel`
     pour l'affichage — et ce scénario vérifie qu'aucune des deux ne prend le
     travail de l'autre.

     Le stub traduit d'après Accept-Language, comme Twitch. Sans cela rien ne
     distinguerait une extension qui affiche la traduction d'une qui affiche
     l'anglais : les deux chaînes seraient égales, et six assertions vertes
     n'auraient rien prouvé. */

  const cartes = (page) => page.evaluate(() =>
    [...document.querySelectorAll('.side-nav-card')].map(c => {
      const el = c.querySelector('[data-a-target="side-nav-card-metadata"] p[title]');
      return { login: c.dataset.tseLogin,
               texte: el?.textContent?.trim() ?? null,
               infobulle: el?.getAttribute('title') ?? null,
               identite: c.dataset.tseCategory ?? null,
               libelle: c.dataset.tseCategoryLabel ?? null };
    }));

  const options = (page) => page.evaluate(() =>
    [...document.querySelectorAll('#tse-cat-dd .tse-dd-opt')]
      .filter(o => o.dataset.value)
      .map(o => ({ valeur: o.dataset.value,
                   libelle: o.querySelector('.tse-dd-name')?.textContent ?? null })));

  /* Le menu accuse UN BALAYAGE de retard sur les cartes, et c'est normal : la
     réponse de l'API écrit sur les cartes, mais c'est le balayage suivant qui
     rebâtit le menu à partir d'elles. Mesuré ici : au premier regard après la
     condition d'attente, le menu porte encore « Just Chatting » ; il porte
     « Discussions » 32 ms plus tard.

     Ce décalage a fait tomber ce scénario dans un banc complet alors qu'il
     passait trois fois sur trois en isolation — la charge suffit à décaler la
     lecture dans la fenêtre. Un échec qui ne se reproduit pas est celui qu'on
     finit par relancer sans le lire, donc par ignorer.

     On attend la STABILITÉ, pas le contenu attendu : deux lectures identiques
     séparées de plus qu'un balayage. Attendre « Discussions » ferait de
     l'assertion sa propre condition d'entrée, et elle ne pourrait plus échouer
     que par expiration — ce qui est une autre façon de ne rien tester. */
  const optionsStables = async (page) => {
    let avant = null;
    for (let i = 0; i < 40; i++) {
      const vu = JSON.stringify(await options(page));
      if (vu === avant) return JSON.parse(vu);
      avant = vu;
      await wait(page, 150);
    }
    return JSON.parse(avant);
  };

  const monter = async (htmlLang) => {
    const page = await browser.newPage();
    page.on('pageerror', e => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
    await page.goto(URL_PAGE);
    await page.evaluate((l) => {
      // Le libellé natif du harnais est français et gagnerait sur html.lang :
      // on le retire pour que la langue demandée soit bien celle qui décide
      // (même montage qu'au scénario 64).
      document.querySelector('.side-nav-section').removeAttribute('aria-label');
      document.documentElement.lang = l;
      const vieux = new Date(Date.now() - 3600_000).toISOString();
      window.__fx = {
        alpha: { id: 'a', sid: 's-a', createdAt: vieux, viewers: 1000,
                 game: 'Just Chatting', tags: [] },
        beta:  { id: 'b', sid: 's-b', createdAt: vieux, viewers: 900,
                 game: 'Elden Ring', tags: [] },
      };
      // Le DOM porte le nom canonique : c'est le cas le PLUS défavorable, celui
      // où l'extension doit écrire quelque chose plutôt que se taire.
      window.__addCard('alpha', 'Just Chatting', '1 k');
      window.__addCard('beta',  'Elden Ring',    '900');
    }, htmlLang);
    /* On attend que TseChannels ait RÉPONDU et que sa réponse soit posée, pas
       seulement que les cartes existent : data-tse-category est amorcé depuis
       le DOM avant toute requête, et s'y fier faisait tout lire une seconde
       trop tôt — première écriture de ce scénario, quatre assertions rouges
       qui décrivaient l'état d'avant la réponse. Le compteur repris par
       l'extension est le signal neutre : il ne peut venir que de l'API, et il
       ne dit rien des catégories qu'on s'apprête à juger. */
    await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 2);
    return page;
  };

  // ── a) l'en-tête, puisque c'est lui qui décide ──────────────────────────
  const page = await monter('fr');
  const entete = await page.evaluate(() => window.__lastAcceptLanguage);
  ok('la requête annonce la langue de l\'interface, pas celle du navigateur',
     entete === 'fr-FR', String(entete));

  // ── b) ce que la carte montre, et ce qu'elle retient ────────────────────
  const fr = await cartes(page);
  ok('la carte affiche la catégorie traduite',
     fr[0]?.texte === 'Discussions', JSON.stringify(fr[0]));
  ok('et son infobulle aussi — c\'est elle que relit getCardCategory',
     fr[0]?.infobulle === 'Discussions', JSON.stringify(fr[0]?.infobulle));
  ok('l\'identité, elle, reste le nom canonique',
     fr[0]?.identite === 'Just Chatting', JSON.stringify(fr[0]?.identite));
  ok('une catégorie que Twitch ne traduit pas s\'écrit telle quelle',
     fr[1]?.texte === 'Elden Ring' && fr[1]?.identite === 'Elden Ring',
     JSON.stringify(fr[1]));

  // ── c) le menu déroulant : libellé traduit, valeur canonique ────────────
  const opts = await optionsStables(page);
  const oJC = opts.find(o => o.valeur === 'Just Chatting');
  ok('le menu propose la traduction…', oJC?.libelle === 'Discussions',
     JSON.stringify(opts));
  ok('…sous la valeur canonique, qui est ce que le clic filtrera',
     !!oJC, JSON.stringify(opts.map(o => o.valeur)));

  // ── d) et le filtre marche toujours ─────────────────────────────────────
  await page.evaluate(() => {
    const o = [...document.querySelectorAll('#tse-cat-dd .tse-dd-opt')]
      .find(x => x.dataset.value === 'Just Chatting');
    if (!o) throw new Error('option « Just Chatting » absente');
    o.click();
  });
  await wait(page, 600);
  const visibles = await page.evaluate(() =>
    [...document.querySelectorAll('.side-nav-card')]
      .filter(c => c.style.display !== 'none').map(c => c.dataset.tseLogin));
  ok('choisir la catégorie traduite filtre bien sur son identité',
     visibles.length === 1 && visibles[0] === 'alpha', JSON.stringify(visibles));
  await page.evaluate(() => {
    document.querySelector('#tse-cat-dd .tse-dd-opt[data-value=""]')?.click();
  });
  await wait(page, 600);

  // ── e) le badge de basculement parle la même langue ─────────────────────
  await page.evaluate(() => { window.__fx.beta.game = 'Just Chatting'; });
  await attendre(page, () => (window.tse.bascules?.() || []).length > 0, 8000);
  await hoverCard(page, 1);
  await attendre(page, () => !!document.querySelector('.tse-preview__badge--switch'), 6000);
  const badge = await page.evaluate(() => {
    const b = document.querySelector('.tse-preview__badge--switch');
    return b ? { texte: b.textContent.trim(), gras: b.querySelector('strong')?.textContent } : null;
  });
  ok('« Vient de passer sur … » nomme la catégorie dans la langue de l\'interface',
     badge?.gras === 'Discussions', JSON.stringify(badge));
  await unhoverCard(page, 1);

  // ── f) LE piège : changer de langue n'est pas changer de catégorie ──────
  /* C'est l'assertion qui tient toute la séparation. Si le registre des
     basculements comparait les LIBELLÉS, passer l'interface en allemand
     ferait passer « Discussions » à « Nur Chatten » et l'extension
     annoncerait, sur les deux chaînes à la fois, un changement de catégorie
     que personne n'a fait. Comparer des noms canoniques est ce qui l'en
     empêche — et rien d'autre ne l'en empêche. */
  const avant = await page.evaluate(() => (window.tse.bascules() || []).length);
  await page.evaluate(() => { document.documentElement.lang = 'de'; });
  // Signal neutre là encore : l'en-tête du lot suivant, qui ne dit rien de ce
  // qui sera écrit sur les cartes.
  await attendre(page, () => window.__lastAcceptLanguage === 'de-DE', 10_000);
  await wait(page, 800);
  const de = await cartes(page);
  ok('la même catégorie repasse en allemand quand l\'interface change',
     de[0]?.texte === 'Nur Chatten' && de[0]?.identite === 'Just Chatting',
     JSON.stringify(de[0]));
  const apres = await page.evaluate(() => (window.tse.bascules() || []).length);
  ok('et ce changement de langue ne fabrique aucun faux basculement',
     apres <= avant, `avant=${avant} après=${apres}`);
  await page.close();

  // ── g) les DIX langues, et pas seulement celles qu'on a sous la main ────
  /* La question posée est « les catégories ont-elles bien la traduction de
     Twitch dans les autres langues ». Ce banc ne peut pas répondre pour
     Twitch — il ne l'appelle pas. Il répond pour NOTRE moitié, qui est la
     seule qu'on écrive : chaque langue demande-t-elle sa propre locale, et
     affiche-t-elle ce que le serveur lui rend pour cette locale-là ?

     La catégorie témoin n'a pas de nom réel et sa traduction est fabriquée
     depuis la langue demandée. C'est délibéré : inventer dix noms que Twitch
     n'a jamais écrits donnerait un test qui a l'air de connaître les
     traductions de Twitch, ce qu'aucune ligne d'ici ne peut savoir. Ce qu'on
     éprouve est le CHEMIN, langue par langue. */
  const LOCALES = { fr: 'fr-FR', en: 'en-US', de: 'de-DE', es: 'es-MX', pt: 'pt-BR',
                    it: 'it-IT', pl: 'pl-PL', ru: 'ru-RU', ja: 'ja-JP', zh: 'zh-CN' };
  const boiteux = [];
  for (const [lang, locale] of Object.entries(LOCALES)) {
    const p = await browser.newPage();
    p.on('pageerror', e => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
    await p.goto(URL_PAGE);
    await p.evaluate(({ l, langues }) => {
      document.querySelector('.side-nav-section').removeAttribute('aria-label');
      document.documentElement.lang = l;
      const t = {};
      for (const x of langues) t[x] = 'témoin-' + x;
      window.__i18nCats = { 'Catégorie témoin': t };
      window.__fx = { seul: { id: 's', createdAt: new Date(Date.now() - 3600_000).toISOString(),
                              viewers: 1000, game: 'Catégorie témoin', tags: [] } };
      window.__addCard('seul', 'Catégorie témoin', '1 k');
    }, { l: lang, langues: Object.keys(LOCALES) });
    await attendre(p, () => document.querySelectorAll('[data-tse-viewers]').length === 1);
    const vu = await p.evaluate(() => {
      const c = document.querySelector('.side-nav-card');
      const el = c.querySelector('[data-a-target="side-nav-card-metadata"] p[title]');
      return { entete: window.__lastAcceptLanguage,
               texte: el?.textContent?.trim() ?? null,
               identite: c.dataset.tseCategory ?? null };
    });
    await p.close();
    if (vu.entete !== locale || vu.texte !== 'témoin-' + lang
        || vu.identite !== 'Catégorie témoin') {
      boiteux.push(`${lang} → ${JSON.stringify(vu)}`);
    }
  }
  ok('les dix langues demandent leur locale et affichent ce qu\'elle rend',
     boiteux.length === 0, boiteux.join(' | '));
}

// ═════════ 66. Le dégraissage du code livré ═════════
titre('66. Paquet — retirer les commentaires sans toucher au programme');
{
  /* Le paquet part sans ses commentaires depuis la 3.59 : 687 Ko deviennent
     391. Le gain est réel, et le risque aussi — un découpage naïf casserait le
     fichier en silence, et il n'y a pas de « silence » plus complet qu'une
     extension qui ne démarre plus chez l'utilisateur.

     Deux garde-fous, et ils ne prouvent PAS la même chose.

     Le premier est le flux de JETONS, vérifié à chaque assemblage : si les
     deux textes rendent les mêmes jetons dans le même ordre, rien d'autre
     qu'un commentaire n'est parti. C'est nécessaire, et ce n'est pas
     suffisant : l'insertion automatique de points-virgules ne se voit PAS
     dans le flux de jetons. « return /* saut de ligne *\/ 5 » et « return 5 »
     ont exactement les mêmes jetons et ne rendent pas la même chose — le
     premier rend undefined. C'est pourquoi un bloc multiligne est remplacé
     par un saut de ligne au lieu d'être supprimé.

     Le second garde-fou est donc l'EXÉCUTION : on fait tourner des extraits
     choisis pour leurs pièges, avant et après, et on compare ce qu'ils
     rendent. */

  const rend = (src) => { try { return JSON.stringify(Function(src)()); }
                          catch (e) { return 'ERREUR: ' + e.message; } };

  const PIEGES = [
    ['l\'ASI d\'un return coupé par un bloc multiligne',
     'return /*\n*/ 5;'],
    /* Le saut de ligne qui SUIT un commentaire de ligne ne lui appartient pas,
       et c'est tout sauf un détail : l'emporter avec lui recolle « return » et
       ce qui vient après, donc rend 5 là où le programme rendait undefined.
       Deux jetons identiques, deux résultats différents — ce piège-là est le
       seul qui distingue un découpage juste d'un découpage qui mord. */
    ['le saut de ligne après un commentaire de ligne ne part pas avec lui',
     'return // fin\n5;'],
    ['deux jetons séparés par le seul commentaire ne se recollent pas',
     'const x = 1; return typeof/* c */x;'],
    ['un « // » dans une chaîne n\'est pas un commentaire',
     'return "https://gql.twitch.tv/gql";'],
    ['un début de bloc dans une chaîne non plus',
     'return "a /* b */ c";'],
    ['ni dans un littéral de gabarit',
     'const x = 1; return `v=${x} // pas un commentaire`;'],
    ['une expression régulière qui contient des barres obliques',
     'return "https://x/y".replace(/\\/\\//, "@").length;'],
    ['un commentaire de ligne en fin de fichier, sans saut final',
     'const a = 1; return a; // fin'],
  ];
  const faux = [];
  for (const [nom, src] of PIEGES) {
    const avant = rend(src), apres = rend(degraisser(src));
    if (avant !== apres) faux.push(`${nom} : ${avant} → ${apres}`);
  }
  ok('les pièges du découpage rendent la même chose avant et après',
     faux.length === 0, faux.join(' | '));

  /* Un dégraisseur qui ne ferait RIEN passerait tout ce qui précède. On mesure
     donc qu'il enlève vraiment quelque chose, et sur les vrais fichiers. */
  const RACINE = join(ICI, '..');
  const mesures = ['content.js', 'adblock.js'].map((f) => {
    const src = readFileSync(join(RACINE, f), 'utf8');
    const out = degraisser(src);
    return { f, souci: memeCode(src, out),
             avant: Buffer.byteLength(src), apres: Buffer.byteLength(out) };
  });
  const abimes = mesures.filter(m => m.souci);
  ok('content.js et adblock.js gardent leur flux de jetons exact',
     abimes.length === 0, abimes.map(m => `${m.f} : ${m.souci}`).join(' | '));
  const gain = 1 - mesures.reduce((n, m) => n + m.apres, 0)
                 / mesures.reduce((n, m) => n + m.avant, 0);
  ok(`et le paquet perd au moins un tiers de son poids (${(gain * 100).toFixed(0)} %)`,
     gain > 0.33, mesures.map(m => `${m.f} ${m.avant}→${m.apres}`).join(' | '));

  /* La notice MIT du code tiers doit survivre : la licence l'exige de toute
     copie, et un dégraisseur zélé en ferait une infraction sans rien casser
     de visible. */
  const adbNu = degraisser(readFileSync(join(RACINE, 'adblock.js'), 'utf8'));
  ok('la notice MIT du module anti-pub survit au dégraissage',
     /Licence : MIT/.test(adbNu)
     && /Copyright \(c\) 2020-present TwitchAdSolutions/.test(adbNu));

  /* …et le reste doit bien être parti, sinon « conserver les mentions
     légales » deviendrait « ne rien enlever ». La mesure est exacte : après
     dégraissage, il ne doit rester QUE les notices, ni plus ni moins.
     content.js passe de 2721 commentaires à 2 — les deux crédits OpenMoji,
     dont la licence CC BY-SA exige l'attribution — et adblock.js de 290 à 2,
     qui portent la notice MIT d'amont. */
  const restants = ['content.js', 'adblock.js'].map((f) => {
    const src = readFileSync(join(RACINE, f), 'utf8');
    const a = compterCommentaires(src);
    const b = compterCommentaires(degraisser(src));
    return { f, avant: a.total, legaux: a.legaux, apres: b.total };
  });
  const boiteuses = restants.filter(r => r.apres !== r.legaux || r.legaux === 0
                                      || r.avant < r.legaux + 100);
  ok('après dégraissage il ne reste QUE les notices, dans les deux fichiers',
     boiteuses.length === 0,
     restants.map(r => `${r.f} ${r.avant}→${r.apres} (légaux ${r.legaux})`).join(' | '));

  /* ── Le CSS, qui n'est pas du JavaScript ────────────────────────────────
     La feuille de style vit dans un littéral de gabarit : pour acorn, c'est
     une chaîne, et ses 77 commentaires ne sont pas des commentaires JS. Un
     second passage les retire, et il a ses propres pièges — un « /* » dans
     une chaîne CSS n'ouvre rien, et un commentaire collé à un jeton des deux
     côtés ne peut pas être retiré sans changer la règle. */
  const PIEGES_CSS = [
    ['un commentaire ordinaire part',
     '.a { color: red; /* rouge */ }', '.a { color: red;  }'],
    ['une séquence /* dans une chaîne CSS n\'ouvre pas de commentaire',
     '.a::after { content: "/* pas un commentaire */"; }',
     '.a::after { content: "/* pas un commentaire */"; }'],
    ['ni dans une chaîne à apostrophes',
     '.a::after { content: \'/*\'; color: red; }',
     '.a::after { content: \'/*\'; color: red; }'],
    ['un commentaire collé des deux côtés est CONSERVÉ, faute de pouvoir le retirer',
     '.a/*x*/.b { color: red; }', '.a/*x*/.b { color: red; }'],
    ['mais une espace d\'un seul côté suffit à le retirer',
     '.a /*x*/.b { color: red; }', '.a .b { color: red; }'],
    ['un commentaire non fermé ne fait rien perdre',
     '.a { color: red; /* ouvert', '.a { color: red; /* ouvert'],
  ];
  const fauxCss = [];
  for (const [nom, entree, attendu] of PIEGES_CSS) {
    const rendu = sansCommentairesCss(entree);
    if (rendu !== attendu) fauxCss.push(`${nom} : « ${rendu} »`);
  }
  ok('les pièges du CSS sont traités comme du CSS, pas comme du texte',
     fauxCss.length === 0, fauxCss.join(' | '));

  const cssAvant = readFileSync(join(RACINE, 'content.js'), 'utf8');
  const gainCss = Buffer.byteLength(degraisserJs(cssAvant))
                - Buffer.byteLength(degraisser(cssAvant));
  ok(`le passage CSS retire à lui seul plus de 20 Ko (${(gainCss / 1024).toFixed(0)} Ko)`,
     gainCss > 20 * 1024, String(gainCss));

  /* LA preuve, et elle ne se fait pas dans Node : c'est le navigateur qui lit
     ce CSS, donc c'est LUI qu'on interroge. On prend la feuille que
     l'extension a réellement injectée — interpolations résolues comprises —,
     on la dégraisse, et on demande à Chromium de parser les deux. S'il rend
     les mêmes règles, dans le même ordre, avec les mêmes déclarations, les
     deux feuilles sont la même feuille.

     Les règles sont comparées après un retrait de commentaires des DEUX
     côtés, et il a fallu une première écriture rouge pour comprendre
     pourquoi. Chromium NORMALISE ce qu'il ressert — « #fff » devient
     « rgb(255, 255, 255) », les raccourcis sont éclatés — SAUF les valeurs qui
     contiennent un `var()` : celles-là, il les rend telles qu'on les a
     écrites, commentaire au milieu compris. La règle 58 en porte un dans son
     `background`, et deux textes bruts ne pouvaient donc pas être égaux.

     Normaliser des deux côtés n'affaiblit pas le contrôle : là où Chromium
     normalise, il a déjà retiré les commentaires pour nous, et tout écart de
     sélecteur, de valeur ou de nombre de règles reste visible. Le seul cas
     vraiment dangereux — un commentaire retiré ENTRE deux jetons d'une valeur,
     « foo/*x*\/bar » devenant « foobar » au lieu de « foo bar » — tombe
     précisément là où Chromium normalise, donc il est vu. */
  const pageCss = await browser.newPage();
  pageCss.on('pageerror', e => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
  await pageCss.goto(URL_PAGE);
  await attendre(pageCss, () => !!document.getElementById('tse-css'));
  const feuille = await pageCss.evaluate(() => document.getElementById('tse-css').textContent);
  const [avantR, apresR] = await pageCss.evaluate(({ avant, apres }) => {
    // `media="not all"` : les deux sondes sont analysées sans rien peindre.
    const regles = (texte) => {
      const s = document.createElement('style');
      s.media = 'not all';
      s.textContent = texte;
      document.head.appendChild(s);
      const out = [...s.sheet.cssRules].map(r => r.cssText);
      s.remove();
      return out;
    };
    return [regles(avant), regles(apres)];
  }, { avant: feuille, apres: sansCommentairesCss(feuille) });
  await pageCss.close();

  let ecart = avantR.length !== apresR.length
    ? `${avantR.length} règles avant, ${apresR.length} après` : null;
  for (let i = 0; !ecart && i < avantR.length; i++) {
    const a = sansCommentairesCss(avantR[i]), b = sansCommentairesCss(apresR[i]);
    if (a !== b) ecart = `règle ${i} : « ${a.slice(0, 90)} » → « ${b.slice(0, 90)} »`;
  }
  ok(`Chromium rend les MÊMES règles avant et après (${avantR.length} règles)`,
     !ecart, ecart ?? '');
  /* Et la feuille dégraissée n'en porte plus aucun. Le contrôle ci-dessus
     normalise les deux côtés : à lui seul, il passerait aussi pour un
     dégraisseur inerte. Celui-ci ferme la porte — et il ne se prononce QUE sur
     la sortie, car l'entrée n'a déjà plus de commentaires quand le banc tourne
     sur le code livré (`npm run test-livre`). Le cas « ne fait rien » est
     couvert deux lignes plus haut, sur le fichier du dépôt, où la mesure vaut
     dans les deux modes. */
  ok('…et la feuille servie au navigateur ne porte plus un seul commentaire CSS',
     !sansCommentairesCss(feuille).includes('/*'),
     `${(sansCommentairesCss(feuille).match(/\/\*/g) || []).length} restants`);
}

// ═════════ 67. L'onglet qu'on ne regarde plus ═════════
titre('67. Arrière-plan — ce qui s\'arrête, et ce qui repart');
{
  /* Soixante-cinq scénarios, et aucun ne parlait de l'onglet caché. C'était le
     trou le plus large du banc : tout le chemin de retour — voile, purge,
     repeuplement — n'avait jamais été joué une seule fois.

     CE QUE CE SCÉNARIO SIMULE, ET CE QU'IL NE SIMULE PAS. Il pose le SIGNAL
     que le navigateur envoie : `document.hidden`, `visibilityState`,
     l'événement `visibilitychange`. C'est ce que l'extension lit, et c'est
     donc sa logique à elle qui est éprouvée. Il ne reproduit PAS le
     ralentissement que Chrome inflige aux minuteurs d'un onglet caché — cela
     ne se simule pas depuis la page. Le dernier cas va plus loin et gèle
     vraiment la page par le protocole DevTools, ce qui est la chose réelle. */

  const cacher = (page, cache) => page.evaluate((c) => {
    Object.defineProperty(document, 'hidden', { configurable: true, get: () => c });
    Object.defineProperty(document, 'visibilityState',
      { configurable: true, get: () => (c ? 'hidden' : 'visible') });
    document.dispatchEvent(new Event('visibilitychange'));
  }, cache);

  /* Attendre que le pipeline se taise AVANT de cacher l'onglet. Sans cela le
     test est une course, et il l'a été : un balayage encore programmé, ou un
     lot encore en vol, retombait pendant la mesure et faisait échouer le
     scénario UNE FOIS SUR TROIS — sur du code sain. Un banc intermittent est
     pire qu'un banc absent : il apprend à ignorer ses propres échecs.

     Le silence se constate sur le compteur de requêtes du stub : deux relevés
     consécutifs identiques, et plus rien ne peut retomber. */
  const calme = async (page) => {
    let precedent = -1;
    for (let i = 0; i < 40; i++) {
      const n = await page.evaluate(() => window.__calls.length);
      if (n === precedent) return true;
      precedent = n;
      await wait(page, 250);
    }
    return false;
  };

  /* Combien de fois le relevé « sidebar réduite ? » interroge le document.
     C'est un COMPTEUR, pas un chronomètre : une assertion de coût fondée sur
     le temps serait à la merci de la charge de la machine, et deviendrait le
     genre d'échec qu'on finit par ignorer. */
  const compterReplis = () => {
    const vrai = Document.prototype.querySelector;
    window.__replis = 0;
    Document.prototype.querySelector = function (sel) {
      if (typeof sel === 'string' && sel.includes('side-nav--collapsed')) window.__replis++;
      return vrai.call(this, sel);
    };
    /* Les minuteurs armés, aussi. La porte de scheduleScan et celle de son
       rappel font la même promesse — « pas de balayage en arrière-plan » — et
       la seconde suffit à la tenir : retirer la première ne fait donc tomber
       aucun test de comportement. Ce qu'elle apporte en propre est de ne pas
       ARMER de minuteur du tout, et cela ne se voit qu'ici. */
    const vraiTO = window.setTimeout;
    window.__armes = 0;
    window.setTimeout = function (...args) { window.__armes++; return vraiTO.apply(this, args); };
  };

  const monter = async () => {
    const page = await browser.newPage();
    page.on('pageerror', e => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
    await page.addInitScript(compterReplis);
    await page.goto(URL_PAGE);
    await page.evaluate(() => {
      const h = new Date(Date.now() - 3600_000).toISOString();
      window.__fx = {
        alpha: { id: 'a', createdAt: h, viewers: 1000, game: 'Just Chatting', tags: [] },
        beta:  { id: 'b', createdAt: h, viewers: 900,  game: 'Elden Ring',    tags: [] },
      };
      window.__addCard('alpha', 'Just Chatting', '1 k');
      window.__addCard('beta',  'Elden Ring',    '900');
    });
    await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 2);
    return page;
  };

  // ── a) caché : plus de requêtes, plus de décoration ─────────────────────
  const page = await monter();
  ok('le pipeline se tait avant qu\'on cache l\'onglet', await calme(page));

  /* ── LA COURSE, reconstruite exprès ────────────────────────────────────
     Entre la programmation d'un balayage et son départ il s'écoule
     SCAN_DEBOUNCE, et l'onglet peut se cacher dans cet intervalle. Le
     minuteur, lui, est déjà armé : sans porte dans son rappel, il part quand
     même, avec son balayage complet et ses requêtes.

     Ce cas n'a pas été trouvé en lisant le code : c'est le banc qui échouait
     UNE FOIS SUR TROIS sur du code sain, parce qu'il tombait par hasard dans
     cette fenêtre. Trois écritures ont raté sa reconstruction, et les deux
     premières PASSAIENT — la pire façon de rater :

       1. mutation et masquage dans une seule évaluation synchrone. Le rappel
          d'un MutationObserver est une microtâche : il ne tournait qu'APRÈS
          le masquage, prenait sa propre porte, et n'armait donc rien ;
       2. un tour complet cédé entre les deux. Mesuré : l'observateur n'arme
          son minuteur que ~19 ms après la mutation, bien après le tour ;
       3. accrochée à l'armement, mais la carte posée trop tôt — un balayage
          d'une activité précédente l'a décorée avant qu'on ait rien caché.

     Les deux premières ne testaient rien du tout, et la mutation qui retire
     la porte du rappel y a survécu deux rondes complètes.

     CE QUI MARCHE, et pourquoi il n'y a plus d'horloge dans le raisonnement :
     on s'accroche à l'ÉVÉNEMENT « un balayage vient d'être armé » — observable,
     c'est un setTimeout au délai de SCAN_DEBOUNCE — puis on fait TOUT le reste
     dans UNE SEULE microtâche : poser la carte, puis cacher l'onglet. Rien ne
     peut s'intercaler entre les deux, donc aucun balayage ne peut voir la
     carte tant que l'onglet est visible. Le balayage en attente, lui, expirera
     forcément onglet caché. La microtâche plutôt que l'appel direct : se
     glisser au milieu de scheduleScan produirait une réentrance que la
     production ne connaît pas.

     ON NE PEUT PAS ATTENDRE LE SILENCE D'ABORD — mesuré aussi : au repos, le
     banc accéléré arme un balayage toutes les 100 ms (REFRESH_TICK), et le
     plus grand trou observé sur 3 s est de 131 ms. Il n'existe aucun instant
     tranquille où se placer ; c'est bien pour cela qu'il faut s'accrocher à
     l'événement plutôt qu'à une accalmie.

     TROIS TÉMOINS pour un seul fait, parce qu'un fait à un seul témoin dans un
     test asynchrone est une coïncidence en puissance : aucune requête, la
     carte non décorée, et AUCUN relevé du repli — ce dernier étant le plus
     direct, puisque scanSidebar commence par refreshSidebarCollapsed et qu'un
     balayage qui tourne ne peut pas le cacher.

     Le troisième témoin est plus large que les deux autres, et il faut le
     savoir pour lire un échec : retirer la porte de l'OBSERVATEUR le fait
     parler aussi, avec `appels: 0, delta: false`. C'est exact — un observateur
     non gardé sonde le repli en arrière-plan — mais ce n'est pas le défaut que
     cette assertion nomme, et l'assertion dédiée le dit deux lignes plus bas.
     Trois témoins dont un seul parle, ce sont les deux muets qu'il faut lire :
     ils disent qu'aucun balayage n'a tourné.

     Le délai est LU dans le fichier construit. build.mjs donne à SCAN_DEBOUNCE
     une valeur distincte de BATCH_DELAY précisément pour que ces lignes
     puissent nommer leur minuteur au lieu d'en attraper un autre. */
  const DEBOUNCE = Number(/SCAN_DEBOUNCE:\s*([\d_]+)/
    .exec(readFileSync(join(ICI, 'content.test.js'), 'utf8'))[1].replaceAll('_', ''));
  const course = await page.evaluate((debounce) => new Promise((resolve) => {
    const vraiTO = window.setTimeout;          // le compteur posé par compterReplis
    let pris = false;
    window.setTimeout = function (fn, d, ...r) {
      const id = vraiTO.call(this, fn, d, ...r);
      if (d === debounce && !pris) {
        pris = true;
        queueMicrotask(() => {
          window.setTimeout = vraiTO;
          // La carte, PUIS le masquage — sans rien entre les deux.
          window.__fx.delta = { id: 'd', createdAt: new Date(Date.now() - 600_000).toISOString(),
                                viewers: 400, game: 'Art', tags: [] };
          window.__addCard('delta', 'Art', '400');
          Object.defineProperty(document, 'hidden', { configurable: true, get: () => true });
          Object.defineProperty(document, 'visibilityState',
            { configurable: true, get: () => 'hidden' });
          document.dispatchEvent(new Event('visibilitychange'));
          // Les témoins sont remis à zéro APRÈS le masquage : tout ce qu'ils
          // compteront désormais aura eu lieu dans un onglet caché.
          window.__replis = 0;
          const appels0 = window.__calls.length;
          vraiTO(() => resolve({
            arme: true,
            replis: window.__replis,
            appels: window.__calls.length - appels0,
            delta: !!document.querySelector('[data-tse-login="delta"]'),
          }), debounce * 8);                   // très au-delà de l'échéance
        });
      }
      return id;
    };
    vraiTO(() => { window.setTimeout = vraiTO; resolve({ arme: false }); }, 3000);
  }), DEBOUNCE);
  /* LA PRÉCONDITION, et elle vaut assertion à part entière : sans balayage
     armé, il n'y a pas de course, et ce qui suit ne prouve rien. C'est
     exactement le piège dans lequel les deux premières écritures sont
     tombées — en vert. */
  ok(`la course est bien armée : l'onglet se cache pendant qu'un balayage attend (${DEBOUNCE} ms)`,
     course.arme === true, 'aucun balayage n\'a été armé en 3 s');
  ok('un balayage déjà armé ne part pas si l\'onglet se cache avant son échéance',
     course.replis === 0 && course.appels === 0 && course.delta === false,
     JSON.stringify(course));

  const appelsAvant = await page.evaluate(() => window.__calls.length);
  /* Twitch continue de vivre pendant l'absence : une carte apparaît. Avant
     cette version, chaque mutation de ce genre déclenchait un balayage complet
     et son lot de requêtes, dans un onglet que personne ne regarde. */
  await page.evaluate(() => {
    window.__fx.gamma = { id: 'g', createdAt: new Date(Date.now() - 600_000).toISOString(),
                          viewers: 500, game: 'Art', tags: [] };
    window.__addCard('gamma', 'Art', '500');
  });
  await wait(page, 1000);
  const pendant = await page.evaluate(() => ({
    appels: window.__calls.length,
    decoree: !!document.querySelector('[data-tse-login="gamma"]'),
  }));
  ok('onglet caché : aucune requête ne part',
     pendant.appels === appelsAvant, `${appelsAvant} → ${pendant.appels}`);
  ok('onglet caché : la carte apparue n\'est pas traitée',
     pendant.decoree === false, JSON.stringify(pendant));

  /* ── le COÛT, et pas seulement le comportement ──────────────────────────
     Le relevé « sidebar réduite ? » coûte 130 µs sur un DOM de la taille de
     celui de Twitch : un sélecteur de classe sans correspondance oblige le
     moteur à parcourir tout le document. Il se faisait à CHAQUE lot de
     mutations, chat compris.

     Deux portes le bornent désormais, et aucune ne se voit dans un test de
     comportement — c'est pourquoi la première mutation de ce lot n'était
     tombée nulle part. On compte donc les relevés pendant 300 lots de
     mutations HORS sidebar, comme en produit un chat qui défile. */
  const churn = (page) => page.evaluate(async () => {
    const bruit = document.createElement('div');
    document.body.appendChild(bruit);
    window.__replis = 0; window.__armes = 0;
    for (let i = 0; i < 300; i++) {
      const d = document.createElement('div');
      d.innerHTML = '<span>message ' + i + '</span>';
      bruit.appendChild(d);
      if (bruit.childElementCount > 40) bruit.firstElementChild.remove();
      await null;                       // un lot par message, comme un vrai chat
    }
    bruit.remove();
    return { replis: window.__replis, armes: window.__armes };
  });

  const caches = await churn(page);
  ok('onglet caché : le relevé du repli ne tourne pas une seule fois',
     caches.replis === 0, `${caches.replis} relevés pour 300 lots`);
  ok('onglet caché : aucun minuteur de balayage n\'est même armé',
     caches.armes === 0, `${caches.armes} minuteurs armés pour 300 lots`);

  // ── b) retour COURT : le balayage retenu est rejoué ─────────────────────
  /* L'absence dure moins que REVISIT_RELOAD_MS : pas de voile, pas de purge —
     mais la carte arrivée pendant l'absence doit être rattrapée. C'est
     exactement ce que le drapeau « scan en retard » existe pour garantir. */
  /* On redevient visible ET on lit DANS LA MÊME évaluation : aucun minuteur
     n'a pu s'exécuter entre les deux, donc ce qu'on trouve vient forcément du
     gestionnaire de retour. Sans cette précaution le test ne prouvait rien —
     le réveil périodique (5 s en production, 100 ms dans le banc accéléré)
     finissait par balayer de toute façon, et retirer le rattrapage ne faisait
     tomber aucune assertion. La différence est pourtant réelle : jusqu'à cinq
     secondes de sidebar périmée à chaque retour sur l'onglet. */
  const apresCourt = await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, get: () => false });
    Object.defineProperty(document, 'visibilityState',
      { configurable: true, get: () => 'visible' });
    document.dispatchEvent(new Event('visibilitychange'));
    return { gamma: !!document.querySelector('[data-tse-login="gamma"]'),
             delta: !!document.querySelector('[data-tse-login="delta"]'),
             cartes: document.querySelectorAll('[data-tse-login]').length };
  });
  ok('retour court : les deux balayages retenus sont rejoués DANS le gestionnaire',
     apresCourt.gamma && apresCourt.delta && apresCourt.cartes === 4,
     JSON.stringify(apresCourt));

  /* Onglet VISIBLE, et du bruit hors sidebar : le relevé ne doit presque
     jamais tourner. Première écriture de cette assertion, je l'attendais
     « échantillonnée, entre 1 et 30 » — elle rend zéro, et c'est elle qui
     avait tort : 300 lots passent en bien moins d'une seconde, donc le filet
     d'une seconde n'a aucune raison de se déclencher. Sans la porte, ce même
     bruit produisait 300 relevés à 130 µs.

     Le seuil laisse passer le filet au cas où la rafale chevaucherait une
     seconde ; ce test compte un ordre de grandeur, il ne chronomètre pas une
     machine. */
  await calme(page);
  const visible = await churn(page);
  ok('onglet visible : le bruit hors sidebar ne déclenche presque aucun relevé',
     visible.replis <= 5, `${visible.replis} relevés pour 300 lots`);

  /* LE CONTRÔLE POSITIF, et il est indispensable : sans lui, « ne relève
     presque jamais » serait aussi satisfait par une porte qui ne s'ouvre
     jamais — c'est-à-dire par un repli/dépli qu'on ne verrait plus. Une
     mutation DANS la sidebar doit relever tout de suite. */
  const replisSidebar = await page.evaluate(async () => {
    window.__replis = 0;
    const nav = document.getElementById('side-nav');
    const d = document.createElement('div');
    nav.appendChild(d); await null;
    d.remove(); await null;
    return window.__replis;
  });
  ok('…mais une mutation DANS la sidebar le déclenche immédiatement',
     replisSidebar > 0, `${replisSidebar} relevés`);

  // ── c) retour LONG : voile, purge, repeuplement ─────────────────────────
  await cacher(page, true);
  await wait(page, 2200);            // > REVISIT_RELOAD_MS accéléré (1,5 s)
  await cacher(page, false);
  await attendre(page, () =>
    document.querySelectorAll('[data-tse-login][data-tse-viewers]').length === 4, 8000);
  const apresLong = await page.evaluate(() => ({
    cartes: document.querySelectorAll('[data-tse-login][data-tse-viewers]').length,
    uptime: [...document.querySelectorAll('.tse-uptime')].map(e => e.textContent).filter(Boolean).length,
  }));
  ok('retour après une longue absence : les quatre cartes sont repeuplées',
     apresLong.cartes === 4, JSON.stringify(apresLong));
  ok('…durées de stream comprises',
     apresLong.uptime === 4, JSON.stringify(apresLong));
  await page.close();

  // ── d) l'onglet qui NAÎT caché ──────────────────────────────────────────
  /* Cas oublié par l'écriture d'origine : `hiddenSince` valait 0, donc le
     retour ne faisait rien du tout. Une page ouverte dans un onglet
     d'arrière-plan — un lien ouvert en nouvel onglet, une session restaurée —
     n'avait alors aucun chemin de rattrapage. */
  const p2 = await browser.newPage();
  p2.on('pageerror', e => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
  await p2.addInitScript(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, get: () => true });
    Object.defineProperty(document, 'visibilityState', { configurable: true, get: () => 'hidden' });
  });
  await p2.goto(URL_PAGE);
  await p2.evaluate(() => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    window.__fx = { seul: { id: 's', createdAt: h, viewers: 700, game: 'Art', tags: [] } };
    window.__addCard('seul', 'Art', '700');
  });
  await wait(p2, 1200);
  const neCache = await p2.evaluate(() => window.__calls.length);
  // Lecture synchrone, même raison qu'au retour court : c'est le gestionnaire
  // qu'on éprouve, pas la patience du réveil périodique.
  const ne = await p2.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, get: () => false });
    Object.defineProperty(document, 'visibilityState',
      { configurable: true, get: () => 'visible' });
    document.dispatchEvent(new Event('visibilitychange'));
    return { balaye: !!document.querySelector('[data-tse-login="seul"]') };
  });
  /* Le balayage est synchrone, les DONNÉES ne le sont pas : viewers et durée
     viennent d'une réponse réseau. Exiger les deux dans la même évaluation —
     première écriture — revenait à demander au gestionnaire de faire un
     aller-retour GraphQL sans rendre la main. Deux assertions, donc : le
     gestionnaire balaie, puis les données arrivent. */
  ok('un onglet né caché est balayé dès le premier regard',
     ne.balaye, `${JSON.stringify(ne)} — ${neCache} requêtes pendant l'absence`);
  await attendre(p2, () => !!document.querySelector('[data-tse-login="seul"][data-tse-viewers]'), 8000);
  const peuple = await p2.evaluate(() => {
    const c = document.querySelector('[data-tse-login="seul"]');
    return { viewers: c?.dataset.tseViewers ?? null,
             uptime: c?.querySelector('.tse-uptime')?.textContent ?? null };
  });
  ok('…et se peuple ensuite comme n\'importe quel onglet',
     !!peuple.viewers && !!peuple.uptime, JSON.stringify(peuple));
  await p2.close();

  // ── e) un vrai gel, par le protocole DevTools ───────────────────────────
  /* Ici on ne simule plus : Chrome gèle réellement la page — minuteurs
     suspendus, rien ne tourne — puis la réveille. C'est ce que fait le
     navigateur à un onglet d'arrière-plan qu'il juge inutile, et c'est le seul
     moyen de vérifier que l'extension survit à autre chose qu'un drapeau. */
  const p3 = await monter();
  const cdp = await p3.context().newCDPSession(p3);
  await cacher(p3, true);
  await cdp.send('Page.setWebLifecycleState', { state: 'frozen' });
  await new Promise(r => setTimeout(r, 2500));
  await cdp.send('Page.setWebLifecycleState', { state: 'active' });
  await cacher(p3, false);
  await attendre(p3, () =>
    document.querySelectorAll('[data-tse-login][data-tse-viewers]').length === 2, 10_000);
  const degele = await p3.evaluate(() => ({
    cartes: document.querySelectorAll('[data-tse-login][data-tse-viewers]').length,
    tri: !!document.getElementById('tse-sort-row'),
    filtre: !!document.getElementById('tse-filter'),
  }));
  ok('après un gel RÉEL de la page, la sidebar repart entière',
     degele.cartes === 2 && degele.tri && degele.filtre, JSON.stringify(degele));
  await p3.close();
}

// ═════════ 69. Le panneau — ce que la page rend, et par où ═════════
titre('69. Panneau — la donnée nue, et le pont qui la porte');
{
  /* CE QUE CE SCÉNARIO PEUT ÉPROUVER, ET CE QU'IL NE PEUT PAS. Le panneau est
     une page d'extension : il vit dans un contexte que Playwright ne peut pas
     ouvrir sans charger l'extension elle-même, et le harnais sert la page en
     file:// avec un <script> — il n'y a donc ni chrome.runtime, ni service
     worker, ni monde ISOLATED ici.

     Ce qui EST éprouvable est précisément la moitié qui peut casser en
     silence : la couche de données de content.js, et le protocole de messages
     par lequel bridge.js l'interroge. Les deux vivent dans le monde MAIN, que
     le harnais reproduit fidèlement. Le reste — le port, l'aiguillage — est du
     transport sans logique propre, et se voit tout de suite à l'usage.

     Le cas qui a motivé ce scénario est réel : la première écriture répondait
     avec `location.origin` comme targetOrigin. Sur une origine opaque —
     file://, une iframe bac à sable — cette valeur est la chaîne "null", et le
     message est jeté SANS ERREUR. Le panneau serait resté à tourner. */
  const page = await browser.newPage();
  page.on('pageerror', e => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
  await page.goto(URL_PAGE);
  await page.evaluate(() => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    window.__fx = {
      alpha: { id: 'a', createdAt: h, viewers: 1000, game: 'Just Chatting', tags: [] },
      beta:  { id: 'b', createdAt: h, viewers: 900,  game: 'Elden Ring',    tags: [] },
    };
    window.__addCard('alpha', 'Just Chatting', '1 k');
    window.__addCard('beta',  'Elden Ring',    '900');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 2);

  /* ── Les dix sections rendent la forme annoncée ────────────────────────
     Le panneau dessine ses colonnes à partir de `colonnes`, dans cet ordre :
     une section qui rendrait un objet sans cette clé donnerait un tableau
     vide, sans erreur. */
  const SECTIONS = ['scores', 'subs', 'roster', 'lag', 'bascules',
                    'cycles', 'apercu', 'diagnose', 'global', 'categories'];
  const formes = await page.evaluate((noms) => noms.map((n) => {
    try {
      const d = window.tse.panneau(n);
      return { n, ok: Array.isArray(d.colonnes) && d.colonnes.length > 0
                    && Array.isArray(d.lignes) && !!d.resume && typeof d.resume === 'object' };
    } catch (e) { return { n, ok: false, err: e.message }; }
  }), SECTIONS);
  ok(`les ${SECTIONS.length} sections rendent { colonnes, lignes, resume }`,
     formes.every(f => f.ok), JSON.stringify(formes.filter(f => !f.ok)));

  /* ── AUCUNE section n'écrit en console ─────────────────────────────────
     C'est la promesse qui sépare cette couche de l'API console : les deux
     doivent pouvoir servir en même temps. Une section qui appellerait
     console.table inonderait la console de l'utilisateur à chaque ouverture
     du panneau — et rien d'autre ne le verrait. */
  const bavardage = await page.evaluate((noms) => {
    const vrais = { log: console.log, table: console.table, warn: console.warn };
    let n = 0;
    console.log = console.table = console.warn = () => { n++; };
    try { for (const s of noms) window.tse.panneau(s); }
    finally { Object.assign(console, vrais); }
    return n;
  }, SECTIONS);
  ok('aucune section n\'écrit en console — le panneau n\'est pas un spectateur de la console',
     bavardage === 0, `${bavardage} écritures`);

  /* ── Le panneau connaît-il toutes les colonnes qu'on lui envoie ? ───────
     Croisement RUNTIME ↔ STATIQUE, et c'est le seul contrôle qui puisse
     l'attraper : content.js peut gagner un champ, panneau.js l'ignorer, et
     la colonne disparaîtrait de l'affichage sans le moindre message. Le
     panneau filtre en effet sur ce qu'il connaît, précisément pour ne jamais
     afficher d'intitulé non traduit — la contrepartie est ce silence-ci. */
  const emises = await page.evaluate((noms) => {
    const vues = new Set();
    for (const n of noms) for (const c of window.tse.panneau(n).colonnes) vues.add(c);
    return [...vues];
  }, SECTIONS);
  const connues = [...readFileSync(join(ICI, '..', 'panneau.js'), 'utf8')
    .matchAll(/^\s{2}([a-zA-Zé]+):\s*\{ cle: '/gm)].map(m => m[1]);
  const inconnues = emises.filter(c => !connues.includes(c));
  ok('le panneau connaît chaque colonne que la page lui envoie',
     inconnues.length === 0 && connues.length >= 20,
     `inconnues : ${JSON.stringify(inconnues)} — ${connues.length} colonnes déclarées`);

  /* ── LE PONT ───────────────────────────────────────────────────────────
     bridge.js ne fait rien d'autre que ces deux messages ; s'ils marchent
     ici, ils marchent chez lui. */
  const pont = (charge) => page.evaluate((c) => new Promise((res) => {
    const minuteur = setTimeout(() => res({ expire: true }), 3000);
    window.addEventListener('message', function ecoute(e) {
      if (e.source !== window || !e.data || e.data.tse !== 'tse-panneau-res'
          || e.data.id !== c.id) return;
      clearTimeout(minuteur);
      window.removeEventListener('message', ecoute);
      res(e.data);
    });
    window.postMessage({ tse: 'tse-panneau-req', ...c }, '*');
  }), charge);

  const r1 = await pont({ id: 1, section: 'diagnose' });
  ok('une requête du pont revient, avec son identifiant et ses données',
     r1.ok === true && r1.id === 1 && Array.isArray(r1.data?.lignes) && r1.data.lignes.length > 0,
     JSON.stringify(r1).slice(0, 140));

  /* Une section inconnue doit REVENIR EN ÉCHEC, pas se taire. Un panneau qui
     n'obtient pas de réponse affiche « chargement » indéfiniment ; c'est la
     pire des trois issues, et la seule qui ne se diagnostique pas. */
  const r2 = await pont({ id: 2, section: 'nexistepas' });
  ok('une section inconnue rend un échec nommé, jamais un silence',
     r2.ok === false && r2.erreur === 'inconnu', JSON.stringify(r2));

  const r3 = await pont({ id: 3, action: 'nexistepas' });
  ok('une action inconnue aussi', r3.ok === false && r3.erreur === 'inconnu', JSON.stringify(r3));

  /* Une action ordinaire, et son effet. rescan est la moins destructrice des
     cinq : elle refait ce qu'un retour d'onglet fait déjà tout seul. */
  const r4 = await pont({ id: 4, action: 'rescan' });
  ok('une action déclarée s\'exécute et rend son compte-rendu',
     r4.ok === true && r4.data?.fait === true, JSON.stringify(r4));

  /* ── Ce à quoi le pont NE doit PAS répondre ────────────────────────────
     Le listener écoute la fenêtre entière : tout script de la page peut y
     poster. Il ne doit répondre qu'à ce qui porte sa marque ET un identifiant
     — sans quoi il répondrait à ses PROPRES réponses, en boucle. */
  const muet = await page.evaluate(() => new Promise((res) => {
    let n = 0;
    const compter = (e) => { if (e.data && e.data.tse === 'tse-panneau-res') n++; };
    window.addEventListener('message', compter);
    window.postMessage({ tse: 'tse-panneau-req', section: 'scores' }, '*');       // pas d'id
    window.postMessage({ tse: 'tse-panneau-req', id: 'x', section: 'scores' }, '*'); // id non numérique
    window.postMessage({ tse: 'autre-chose', id: 9, section: 'scores' }, '*');    // pas notre marque
    window.postMessage({ tse: 'tse-panneau-res', id: 9, ok: true }, '*');         // une RÉPONSE
    setTimeout(() => { window.removeEventListener('message', compter); res(n); }, 600);
  }));
  ok('un message mal formé, ou une réponse, ne déclenche aucune réponse',
     muet === 1, `${muet} réponses vues (1 = la nôtre, rejouée en écho)`);

  /* ── reset ─────────────────────────────────────────────────────────────
     La seule action irréversible, et la seule que le panneau fait confirmer.
     On vérifie qu'elle fait ce qu'elle dit : après elle, les compteurs sont
     à zéro. */
  await page.evaluate(() => { window.tse.panneau('scores'); });
  /* LES COMPTEURS SE LISENT DANS LA MÊME TÂCHE QUE LA RÉPONSE, et c'est une
     course réelle qu'on ferme ici — vue une fois en vert sur une branche et en
     rouge sur l'autre, à code identique. Le roster REPEUPLE légitimement : il
     enregistre les cartes visibles à chaque balayage, et le harnais balaie à
     cadence accélérée. Un aller-retour de plus entre l'effacement et la lecture
     suffisait donc à en voir revenir deux, et l'assertion accusait `reset` d'un
     défaut qui n'était pas le sien. Lire depuis le gestionnaire de la réponse
     ne laisse aucun tour de boucle s'intercaler. */
  const reset = await page.evaluate(() => new Promise((res) => {
    /* ── ON RETIRE D'ABORD CE QUI REPEUPLE ────────────────────────────────
       DEUXIÈME CORRECTION DE CETTE MÊME ASSERTION, et la première ne suffisait
       pas. Lire depuis le gestionnaire de la réponse empêchait bien un tour de
       boucle de s'intercaler APRÈS l'effacement — mais rien n'empêchait un
       balayage de tomber entre l'effacement et la réponse. Relevé sur du code
       sain, une fois sur plusieurs dizaines : « roster: 2 ».

       CE QU'ON DEMANDAIT N'ÉTAIT PAS UN INVARIANT DU PRODUIT. Le roster
       enregistre les cartes visibles à chaque passe : tant qu'il y a des
       cartes, il se remplit, et c'est son travail. On retire donc les cartes
       avant d'effacer — alors « vide » devient une propriété vraie, et non une
       course qu'on espère gagner. Après l'effacement le roster est vide, donc
       aucune carte en avance n'est refabriquée. */
    document.querySelectorAll('.side-nav-card').forEach((c) => c.remove());
    const minuteur = setTimeout(() => res({ expire: true }), 3000);
    window.addEventListener('message', function ecoute(e) {
      if (e.source !== window || !e.data || e.data.tse !== 'tse-panneau-res'
          || e.data.id !== 5) return;
      clearTimeout(minuteur);
      window.removeEventListener('message', ecoute);
      res({ reponse: e.data,
            scores: window.tse.panneau('scores').lignes.length,
            roster: window.tse.panneau('roster').lignes.length,
            subs:   window.tse.panneau('subs').lignes.length });
    });
    window.postMessage({ tse: 'tse-panneau-req', id: 5, action: 'reset' }, '*');
  }));
  const r5 = reset.reponse || {};
  const apresReset = reset;
  ok('reset vide bien l\'historique, les abonnements et le roster',
     r5.ok === true && apresReset.scores === 0 && apresReset.roster === 0 && apresReset.subs === 0,
     JSON.stringify(apresReset));

  await page.close();
}

// ═════════ 70. Le panneau — ce qu'on voit vraiment ═════════
titre('70. Panneau — la page rendue, mesurée');
{
  /* CE SCÉNARIO EXISTE PARCE QUE J'AVAIS ÉCRIT QU'IL ÉTAIT IMPOSSIBLE. Le
     panneau est une page d'extension, donc hors de portée de Playwright sans
     charger l'extension — c'est vrai du PORT et du service worker, ce n'est
     pas vrai de la PAGE. panneau.html se charge en file:// comme n'importe
     quelle page ; il suffit de poser un `chrome` de substitution avant elle.

     Deux défauts sont passés en production faute de ce scénario, et tous deux
     se voient à l'œil sur une capture :

       1. le pied SORTAIT DE LA FENÊTRE. La hauteur du corps était calculée en
          dur — calc(580px - 47px - 45px) — et l'en-tête en fait 58, pas 47.
          Les deux boutons étaient coupés en deux. Aucun débordement visible :
          le corps est en overflow:hidden, il coupe sans rien dire ;
       2. « Chargement… » S'AFFICHAIT SOUS LE TABLEAU qu'il devait remplacer.
          L'attribut `hidden` pose display:none par la feuille du NAVIGATEUR,
          et une règle d'auteur qui déclare un display l'emporte. .message
          était en display:flex — donc toujours visible. Le piège avait été vu
          pour .voile et manqué pour les deux autres.

     Ce sont deux fautes de MISE EN PAGE, la seule famille que ni le linter, ni
     la parité des locales, ni un test de comportement ne peuvent voir. Il faut
     mesurer la page rendue. */
  const messages = JSON.parse(
    readFileSync(join(ICI, '..', '_locales', 'fr', 'messages.json'), 'utf8'));

  /* Le `chrome` de substitution. Il ne simule PAS le pont — celui-ci est
     éprouvé au scénario 69, côté page — mais l'API que le panneau appelle :
     i18n, l'onglet actif, et l'aller-retour de messages. */
  const stub = (msgs) => {
    const T = (k, sub) => {
          const m = msgs[k] ? msgs[k].message : '';
          if (sub === undefined || sub === null) return m;
          const args = Array.isArray(sub) ? sub : [sub];
          return String(m).replace(/\$(\d)/g,
            (t, i) => (args[i - 1] === undefined ? t : String(args[i - 1])));
        };
    /* `extra` porte ce qui n'est ni colonne, ni ligne, ni résumé — la grille
       du rythme, aujourd'hui. Le panneau passe le paquet ENTIER au dessin. */
    const paquet = (colonnes, lignes, resume, extra) =>
      ({ ok: true, data: { colonnes, lignes, resume, ...(extra || {}) } });
    const REPONSES = {
      scores: () => paquet(['login', 'score', 'visits', 'last'],
        [{ login: 'alpha', score: 3.5, visits: 12, last: Date.now() },
         { login: 'beta',  score: 1.2, visits: 4,  last: Date.now() }],
        { chaines: 2 }),
      subs: () => paquet(['login', 'sub', 'ts', 'mois', 'ancien', 'origine'],
        [{ login: 'alpha', sub: true, ts: Date.now(), mois: 7, ancien: false, origine: 'page' }],
        { chaines: 1, abonnees: 1, releve: Date.now() }),
      roster: () => paquet(['login', 'ts'], [], { chaines: 0 }),   // section VIDE
      /* Le rythme n'a PAS de tableau : ni colonnes, ni lignes, et pourtant du
         contenu. C'est le cas qui a demandé de séparer « rien à tabuler » de
         « rien à montrer » — cf. scénario 89, qui l'éprouve pour de bon. */
      rythme: () => paquet([], [], { visites: 3, chaines: 2,
                                     pic: { jour: 2, heure: 21, n: 2 },
                                     premier: Date.now() - 3 * 86_400_000,
                                     dernier: Date.now() },
        { grille: (() => {
            const g = Array.from({ length: 7 }, () => new Array(24).fill(0));
            g[2][21] = 2; g[5][9] = 1;
            return g;
          })() }),
      diagnose: () => paquet(['label', 'status', 'critical', 'detail'],
        [{ label: '#side-nav', status: 'ok', critical: true, detail: '' },
         { label: 'avatarOf()', status: 'na', critical: false, detail: 'aucune carte' }],
        { sondes: 2, cassees: 0, critiquesCassees: 0, casse: false }),
      lag: () => paquet(['login', 'lag', 'gain', 'ts'], [],
        { mesures: 0, medianeLag: null, p90Lag: null, gains: 0, medianeGain: null }),
      cycles: () => paquet(['t', 'evt', 'detail'], [], { evenements: 0, verrous: [] }),
      apercu: () => paquet(['t', 'evt', 'detail'], [], { evenements: 0 }),
      bascules: () => paquet(['login', 'libelle', 'canonique', 'ageSec'], [], { bascules: 0 }),
      global: () => paquet(['rang', 'login', 'viewers', 'game'],
        [{ rang: 1, login: 'ZEVENT', viewers: 703774, game: 'ZEVENT' }],
        { actif: true, complete: true }),
      categories: () => paquet(['rang', 'libelle', 'canonique', 'viewers'],
        [{ rang: 1, libelle: 'Discussions', canonique: 'Just Chatting', viewers: 376011 }],
        { categories: 1, actif: true }),
    };
    window.__envois = [];
    /* Un rapport de fixture qui porte des VALEURS RECONNAISSABLES : c'est ce
       qui permet d'affirmer ensuite que le fichier les contient — ou, pour les
       listes personnelles, qu'il ne les contient pas. */
    window.__rapport = {
      genere: Date.now(),
      page: { chemin: '/domingo', cachee: false, sidebar: true, repliee: false,
              voile: false, cartes: 42, fabriquees: 3, decorees: 39, liens: 44 },
      langue: { interface: 'fr', page: 'fr' },
      mode: { global: false },
      sondes: [
        { id: 'sidebarRoot', label: '#side-nav', critical: true, status: 'ok', detail: '' },
        { id: 'followedSection', label: 'DOM.followedSelector', critical: true,
          status: 'broken', detail: 'section introuvable' },
      ],
      compteurs: { visites: 137, abonnements: 12, abonnes: 5, roster: 88, mesures: 6,
                   bascules: 1, cache: 40 },
      /* `detectes` ET `marquees` VOLONTAIREMENT DIFFÉRENTS. C'est l'écart qui
         fait tout l'intérêt de ce bloc — trois subathons dans le cache, deux
         cartes décorées — et deux nombres distincts sont aussi ce qui empêche
         une assertion de passer sur un bloc qui n'en rendrait qu'un. */
      subathons: { detectes: 3, sansJour: 1, voies: { nom: 1, thon: 1, tag: 1 },
                   marquees: 2 },
      relevesAbonnements: { horodatage: 0, enAttente: false },
      global: { enabled: false, complete: false },
      journaux: { verrous: [], cycles: [{ t: 12, evt: 'depart', detail: 'boot' }], apercu: [] },
      reseau: { pauseGqlMs: 12000 },
      retards: { medianeMs: 90000, p90Ms: 210000 },
      ancienneteMs: 43000,
      demarrage: { etape: 'pret', dureeMs: 812 },
      erreurs: [{ t: 5120, source: 'stockage', message: 'visites : QuotaExceededError',
                  detail: '', n: 3 }],
    };
    window.chrome = {
      i18n: { getMessage: T, getUILanguage: () => 'fr' },
      tabs: { query: () => Promise.resolve([{ id: 1 }]) },
      runtime: {
        /* Le manifeste, tel que le rapport le lit. Sa forme compte autant que
           son contenu : c'est elle qui dit « chrome » ou « firefox » et quelle
           écriture du fond de tâche est déclarée — les deux premières lignes
           qu'on regarde quand un panneau ne répond pas. */
        getManifest: () => ({
          version: '9.9.9',
          background: { service_worker: 'background.js' },
          action: { default_popup: 'panneau.html' },
        }),
        sendMessage: (m) => {
          window.__envois.push(m);
          /* Panne simulée : l'envoi lui-même REJETTE. C'est ce que fait Chrome
             quand personne n'écoute au bout de chrome.runtime — service worker
             non démarré. À ne pas confondre avec une réponse « absent », qui
             veut dire l'inverse : le worker répond, mais n'a pas de pont pour
             cet onglet. */
          if (window.__panne === 'fond') {
            return Promise.reject(new Error('Could not establish connection. Receiving end does not exist.'));
          }
          /* L'ÉTAT DU WORKER passe AVANT les pannes de page, et l'ordre est le
             fond du sujet : cette demande ne traverse pas le pont, donc une
             page en panne ne doit pas l'empêcher de répondre. C'est même la
             seule raison qu'elle existe. */
          if (m.type === 'tse-panneau-etat') {
            return Promise.resolve({ ok: true, ponts: [1], enVol: 0, workerMs: 4200 });
          }
          /* DÉMARRAGE INACHEVÉ. content.js est entré mais n'a pas fini : son
             pont, posé en tête de fichier, répond quand même — avec l'étape
             atteinte et le journal d'erreurs déjà rempli. C'est le seul cas où
             un rapport en échec explique quelque chose, et il ne pouvait pas
             se produire avant : l'écouteur était déclaré cinq mille lignes
             trop loin, et le panneau n'obtenait qu'une expiration muette. */
          if (window.__panne === 'demarrage') {
            return Promise.resolve({ ok: false, erreur: 'demarrage',
              detail: 'étape i18n',
              partiel: { etape: 'i18n', depuisMs: 137,
                         erreurs: [{ t: 12, source: 'interne',
                                     message: 'STRINGS[LANG] is not defined',
                                     detail: '', n: 2 }] },
              observations: { marque: 'i18n', etat: 'loading', hote: 'www.twitch.tv',
                              cachee: false, pont: 'branché', reprises: 0, pageMs: 900 } });
          }
          if (m.rapport) return Promise.resolve({ ok: true, data: window.__rapport });
          if (m.action) return Promise.resolve({ ok: true, data: { fait: true } });
          const f = REPONSES[m.section];
          return Promise.resolve(f ? f() : { ok: false, erreur: 'inconnu' });
        },
      },
    };
  };

  const page = await browser.newPage({ viewport: { width: 760, height: 580 } });
  page.on('pageerror', e => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
  await page.addInitScript(stub, messages);
  await page.goto(pathToFileURL(join(ICI, '..', 'panneau.html')).href);
  await attendre(page, () => document.querySelectorAll('.rail-item').length > 0);
  /* LE PANNEAU S'OUVRE SUR LE MODE D'EMPLOI, qui ne montre aucun tableau — il
     ne demande rien à la page, c'est tout son objet (scénario 96). Ce
     scénario-ci mesure la mise en page d'une section de DONNÉES : on va donc
     en chercher une, au lieu d'attendre un tableau qui n'arriverait jamais. */
  await page.evaluate(() => [...document.querySelectorAll('.rail-item')]
    .find(b => b.dataset.id === 'scores').click());
  await attendre(page, () => document.querySelectorAll('.tableau tbody tr').length > 0);

  /* ── LA GÉOMÉTRIE ──────────────────────────────────────────────────────
     Le pied doit tenir ENTIÈREMENT dans la fenêtre. C'est le défaut n° 1, et
     il ne se voit que comme ça : on mesure le bas du dernier bouton contre la
     hauteur de la popup. */
  const geo = await page.evaluate(() => {
    const bas = (s) => Math.round(document.querySelector(s).getBoundingClientRect().bottom);
    return {
      hauteur: window.innerHeight,
      piedBas: bas('.pied'),
      boutonBas: Math.round(Math.max(
        ...[...document.querySelectorAll('.pied .bouton')].map(b => b.getBoundingClientRect().bottom))),
      corpsDeborde: document.body.scrollHeight - window.innerHeight,
      railDeborde: document.getElementById('rail').scrollWidth
                 - document.getElementById('rail').clientWidth,
    };
  });
  ok('le pied tient entièrement dans la fenêtre — boutons compris',
     geo.boutonBas <= geo.hauteur && geo.piedBas <= geo.hauteur,
     JSON.stringify(geo));
  ok('rien ne déborde de la popup : c\'est le contenu qui défile, pas la page',
     geo.corpsDeborde <= 0 && geo.railDeborde <= 0, JSON.stringify(geo));

  /* ── L'ATTRIBUT `hidden` MASQUE-T-IL VRAIMENT ? ────────────────────────
     Le défaut n° 2. On ne demande pas si l'attribut est POSÉ — il l'était —
     mais si l'élément OCCUPE ENCORE DE LA PLACE. C'est la seule formulation
     qui distingue les deux. */
  const place = (s) => page.evaluate((sel) => {
    const e = document.querySelector(sel);
    const r = e.getBoundingClientRect();
    return { attribut: e.hidden, hauteur: Math.round(r.height) };
  }, s);

  const msgAvecTableau = await place('#message');
  ok('avec un tableau à l\'écran, le bloc de message n\'occupe aucune place',
     msgAvecTableau.attribut === true && msgAvecTableau.hauteur === 0,
     JSON.stringify(msgAvecTableau));

  const etatAvant = await place('#etat');
  ok('la pastille d\'état reste invisible tant qu\'on n\'a pas vu le diagnostic',
     etatAvant.attribut === true && etatAvant.hauteur === 0, JSON.stringify(etatAvant));

  const voileAvant = await place('#voile');
  ok('la boîte de confirmation n\'occupe aucune place au repos',
     voileAvant.attribut === true && voileAvant.hauteur === 0, JSON.stringify(voileAvant));

  /* ── UNE SECTION VIDE : le message remplace le tableau, il ne s'y ajoute pas ── */
  await page.evaluate(() => [...document.querySelectorAll('.rail-item')]
    .find(b => b.dataset.id === 'roster').click());
  await attendre(page, () => !document.getElementById('message').hidden);
  const vide = await page.evaluate(() => ({
    message: Math.round(document.getElementById('message').getBoundingClientRect().height),
    tableau: Math.round(document.getElementById('tableau-cadre').getBoundingClientRect().height),
    texte: document.getElementById('message-texte').textContent,
  }));
  ok('une section vide montre son message À LA PLACE du tableau',
     vide.message > 0 && vide.tableau === 0 && vide.texte.length > 0,
     JSON.stringify(vide));

  /* ── LA TRADUCTION EST-ELLE APPLIQUÉE ? ────────────────────────────────
     getMessage d'une clé inconnue rend la chaîne vide, et T() retombe alors
     sur le NOM DE LA CLÉ. Un libellé qui vaut « navScores » est donc la
     signature exacte d'une clé manquante — visible ici, et nulle part
     ailleurs. On vérifie aussi qu'aucun libellé n'est vide. */
  const libelles = await page.evaluate(() => [
    ...[...document.querySelectorAll('.rail-item, .rail-groupe')].map(e => e.textContent),
    ...[...document.querySelectorAll('.pied .bouton')].map(e => e.textContent),
    document.querySelector('.tete-titre').textContent,
    document.querySelector('.tete-sous').textContent,
  ]);
  const CLE = /^(nav|desc|col|sum|btn|state|status|val|health|reset|grp|panel|ext|guide)[A-Z]/;
  const brutes = libelles.filter(t => CLE.test(t.trim()));
  const vides  = libelles.filter(t => !t.trim());
  ok(`les ${libelles.length} libellés visibles sont traduits, aucun n'est un nom de clé`,
     brutes.length === 0 && vides.length === 0,
     `bruts : ${JSON.stringify(brutes)} — vides : ${vides.length}`);

  /* ── LE RAIL EST COMPLET ───────────────────────────────────────────────
     Treize sections, cinq groupes. Une section ajoutée à content.js sans être
     ajoutée ici resterait invisible : le panneau n'affiche que ce qu'il
     déclare. Le premier est le mode d'emploi, qui ouvre son propre groupe en
     tête — c'est cette place-là qui en fait la page d'accueil ; le second est
     l'onglet des réglages, et il est juste derrière pour la même raison : on
     lit ce que l'extension fait, puis on choisit ce qu'elle fera. */
  const rail = await page.evaluate(() => ({
    items: document.querySelectorAll('.rail-item').length,
    groupes: document.querySelectorAll('.rail-groupe').length,
  }));
  ok('le rail porte les treize sections, en cinq groupes',
     rail.items === 13 && rail.groupes === 5, JSON.stringify(rail));

  /* ── LES NOMBRES SUIVENT LA LOCALE DU PANNEAU ──────────────────────────
     376011 doit s'écrire avec un séparateur de milliers français, pas à
     l'anglaise et pas collé. C'est chrome.i18n.getUILanguage() qui décide,
     donc la langue de l'INTERFACE et non celle du système. */
  await page.evaluate(() => [...document.querySelectorAll('.rail-item')]
    .find(b => b.dataset.id === 'categories').click());
  await attendre(page, () => document.querySelectorAll('.tableau tbody tr').length > 0);
  const nombre = await page.evaluate(() =>
    [...document.querySelectorAll('.tableau tbody td')].map(t => t.textContent).find(t => /376/.test(t)));
  ok('les nombres sont formatés dans la langue du panneau',
     /^376[   ]011$/.test(nombre || ''), JSON.stringify(nombre));

  /* ── LA CONFIRMATION D'EFFACEMENT ──────────────────────────────────────
     La seule action irréversible. Elle ne doit jamais partir sur un clic
     unique, et Échap doit pouvoir en sortir. */
  await page.evaluate(() => document.getElementById('btn-reset').click());
  const ouverte = await place('#voile');
  const envoisApresOuverture = await page.evaluate(() =>
    window.__envois.filter(m => m.action === 'reset').length);
  ok('« Effacer » ouvre une confirmation et n\'efface rien tout seul',
     ouverte.attribut === false && ouverte.hauteur > 0 && envoisApresOuverture === 0,
     JSON.stringify({ ouverte, envoisApresOuverture }));

  await page.keyboard.press('Escape');
  const fermee = await place('#voile');
  ok('Échap referme la confirmation sans rien effacer',
     fermee.attribut === true && fermee.hauteur === 0, JSON.stringify(fermee));

  await page.evaluate(() => {
    document.getElementById('btn-reset').click();
    document.getElementById('boite-ok').click();
  });
  await attendre(page, () => window.__envois.some(m => m.action === 'reset'));
  const efface = await page.evaluate(() =>
    window.__envois.filter(m => m.action === 'reset').length);
  ok('…et la confirmation, elle, envoie bien l\'ordre', efface === 1, String(efface));

  /* ── DEUX PANNES QU'IL NE FAUT PAS CONFONDRE ───────────────────────────
     Rapport réel : le panneau affichait « ouvrez un onglet twitch.tv et
     mettez-le au premier plan » à quelqu'un qui en avait un sous les yeux,
     avec la sidebar visiblement décorée par l'extension. Le message accusait
     l'onglet alors que le fautif était le service worker — sur Chrome, un
     manifeste déclarant `background.scripts` au lieu de `service_worker`
     donne exactement cela : content scripts vivants, fond de tâche absent.

     Un message qui désigne le mauvais coupable est pire qu'un message
     générique : il envoie chercher là où il n'y a rien. */
  const panne = await page.evaluate(async () => {
    window.__panne = 'fond';
    const avant = window.__envois.length;
    [...document.querySelectorAll('.rail-item')].find(b => b.dataset.id === 'scores').click();
    // Au-delà du total de l'échelle (250 + 750 + 1800), avec de la marge.
    await new Promise(r => setTimeout(r, 3400));
    return { texte: document.getElementById('message-texte').textContent,
             tentatives: window.__envois.length - avant };
  });
  const attenduFond = messages.stateNoWorker.message;
  const attenduOnglet = messages.stateAbsent.message;
  ok('un service worker muet est nommé comme tel, et pas comme un onglet manquant',
     panne.texte.startsWith(attenduFond) && !panne.texte.includes(attenduOnglet),
     JSON.stringify(panne.texte).slice(0, 160));
  ok('…et le message du navigateur est reproduit tel quel, pour être recopié',
     /Receiving end does not exist/.test(panne.texte), JSON.stringify(panne.texte).slice(0, 160));
  /* L'ASSERTION QUI AURAIT ATTRAPÉ LA COURSE. Le panneau ne réessayait qu'UNE
     fois, à 500 ms, quand bridge.js reconnectait à 1 000 : la tentative tenait
     tout entière dans le trou qu'elle devait franchir, et « Réessayer »
     retombait au même endroit. Compter les tentatives est la seule façon de
     voir la différence — le message affiché, lui, est identique. */
  ok('un échec de transport est réessayé plusieurs fois, pas une seule',
     panne.tentatives >= 4, `${panne.tentatives} tentatives pour une échelle de 3 délais`);

  /* ── LE RAPPORT DE DIAGNOSTIC ──────────────────────────────────────────
     Une VUE, plus un fichier. Le changement n'est pas cosmétique : un fichier
     téléchargé ne se relit pas avant d'être envoyé, et toutes les promesses
     du rapport — aucune liste personnelle, du texte lisible — n'étaient alors
     vérifiables qu'après coup. À l'écran, elles le sont avant le geste.

     Le banc y gagne aussi : on lit la zone de texte, au lieu d'intercepter un
     Blob et de neutraliser un clic de téléchargement. Ce qu'on mesure est
     exactement ce que l'utilisateur voit. */
  await page.evaluate(() => { window.__panne = null; });
  const vue = await page.evaluate(async () => {
    document.getElementById('btn-rapport').click();
    const zone = document.getElementById('rapport-zone');
    for (let i = 0; i < 60 && !/SONDES/.test(zone.value); i++) {
      await new Promise(r => setTimeout(r, 50));
    }
    const r = document.getElementById('rapport');
    return {
      ouverte: !r.hidden && Math.round(r.getBoundingClientRect().height) > 0,
      texte: zone.value,
      titre: document.getElementById('rapport-titre').textContent,
      desc: document.querySelector('.rapport-desc').textContent,
      // Le pied doit tenir : c'est le défaut qui avait coupé les boutons du
      // panneau, et cette vue a sa propre colonne flexible.
      piedBas: Math.round(document.querySelector('.rapport-pied').getBoundingClientRect().bottom),
      hauteur: window.innerHeight,
    };
  });

  ok('le bouton ouvre le rapport EN PLEIN PANNEAU, avec titre et description',
     vue.ouverte && vue.titre.length > 0 && vue.desc.length > 40,
     JSON.stringify({ ouverte: vue.ouverte, titre: vue.titre }));
  ok('…et son pied tient dans la fenêtre, boutons compris',
     vue.piedBas <= vue.hauteur, `${vue.piedBas} / ${vue.hauteur}`);

  const contient = (x) => typeof vue.texte === 'string' && vue.texte.includes(x);
  ok('le rapport porte l\'environnement, le transport et les sondes',
     contient('ENVIRONNEMENT') && contient('TRANSPORT') && contient('SONDES')
     && contient('followedSection') && contient('broken'),
     JSON.stringify((vue.texte || '').slice(0, 120)));
  ok('…les compteurs et l\'état de la page, avec leurs valeurs',
     contient('137') && contient('/domingo') && contient('42'),
     'visites 137, chemin /domingo, 42 cartes');

  /* LE BLOC DES ERREURS, qui n'existait pas et qui était le plus grand trou du
     rapport : l'extension n'en consignait aucune, donc il n'en portait aucune.
     On vérifie qu'il rend l'entrée ET son compteur de répétitions — une erreur
     vue trois fois n'est pas la même information qu'une erreur vue une fois. */
  ok('le rapport porte le journal d\'erreurs, avec le compte des répétitions',
     contient('ERREURS') && contient('QuotaExceededError') && contient('×3'),
     JSON.stringify((vue.texte || '').slice(0, 60)));
  ok('…l\'état du réseau et les quantiles de retard',
     contient('pauseGqlMs') && contient('12000') && contient('210000'),
     'pause GraphQL et p90');
  /* LE BLOC DES SUBATHONS. La règle qui les reconnaît ne lit que le titre du
     direct et n'a jamais pu être exécutée contre le vrai Twitch : ce bloc est
     la seule mesure qu'on en aura, et un bloc absent du rapport ne mesure
     rien. On exige les DEUX nombres — celui du cache et celui du DOM, qui
     diffèrent dans la fixture — et le détail par règle : un bloc qui ne
     rendrait que le total passerait sans dire ce qu'on lui demande. */
  ok('…le bloc des subathons : l\'écart cache/DOM, et la règle qui a tranché',
     contient('SUBATHONS') && /detectes\s+3/.test(vue.texte)
     && /marquees\s+2/.test(vue.texte) && /voies\.thon\s+1/.test(vue.texte)
     && /sansJour\s+1/.test(vue.texte),
     JSON.stringify((vue.texte.match(/SUBATHONS[\s\S]{0,160}/) || [])[0]));
  /* L'ÉTAPE DE DÉMARRAGE FIGURE AUSSI QUAND TOUT VA BIEN. Un champ qu'on ne
     voit que le jour de la panne ne se compare à rien : il faut savoir qu'il
     aurait dû être là pour remarquer qu'il manque. Ici il vaut « pret », ne
     dit rien de neuf, et c'est précisément ce qui rend lisible le rapport où
     il vaut autre chose. Même raison pour le bloc HORS PAGE. */
  ok('…l\'étape de démarrage et le bloc HORS PAGE, MÊME sur un rapport réussi',
     contient('démarrage / boot') && contient('pret (812 ms)')
     && contient('DIAGNOSTIC HORS PAGE') && contient('worker — âge'),
     JSON.stringify((vue.texte.match(/démarrage \/ boot.*/) || [])[0]));

  /* LA PROMESSE, TENUE PAR UN CONTRÔLE. Les logins de la fixture n'ont AUCUNE
     raison d'apparaître : le rapport ne transporte que des comptes. Si l'un
     d'eux s'y trouve, c'est qu'une liste personnelle a été ajoutée — et c'est
     exactement ce que cette assertion existe pour interdire. */
  const fuites = ['alpha', 'beta', 'gamma', 'delta'].filter(l => contient(l));
  ok('le rapport ne contient AUCUNE liste personnelle — seulement des comptes',
     fuites.length === 0, `fuites : ${JSON.stringify(fuites)}`);
  ok('…et il le dit lui-même, dans les deux langues, en tête de fichier',
     contient('AUCUNE LISTE PERSONNELLE') && contient('NO PERSONAL LISTS'));

  /* ── COPIER ────────────────────────────────────────────────────────────
     navigator.clipboard n'existe pas sur une page file:// : c'est donc le
     REPLI qui s'exécute ici — sélection du textarea puis execCommand. Le
     tester est plus utile que de tester la voie propre, puisque c'est celui
     qui rattrape les navigateurs qui refusent l'autre. */
  const copie = await page.evaluate(async () => {
    let copie = null;
    document.execCommand = (cmd) => {
      if (cmd === 'copy') { copie = document.getElementById('rapport-zone').value; return true; }
      return false;
    };
    document.getElementById('rapport-copier').click();
    for (let i = 0; i < 40 && copie === null; i++) await new Promise(r => setTimeout(r, 50));
    return { copie, note: document.getElementById('rapport-note').textContent,
             visible: !document.getElementById('rapport-note').hidden };
  });
  ok('« Copier » met le rapport ENTIER dans le presse-papier, et le confirme',
     copie.copie === vue.texte && copie.visible && copie.note.length > 0,
     JSON.stringify({ egal: copie.copie === vue.texte, note: copie.note }));

  /* ── ACTUALISER ────────────────────────────────────────────────────────
     Le rapport date l'instant où on le lit, pas celui où le panneau s'est
     ouvert. Le bouton doit donc REDEMANDER à la page, pas réafficher ce qu'il
     a déjà — c'est toute la différence entre actualiser et ne rien faire. */
  const actualise = await page.evaluate(async () => {
    const avant = window.__envois.filter(m => m.rapport).length;
    window.__rapport.compteurs.visites = 999;      // la page a changé entre-temps
    document.getElementById('rapport-actualiser').click();
    const zone = document.getElementById('rapport-zone');
    for (let i = 0; i < 60 && !/999/.test(zone.value); i++) await new Promise(r => setTimeout(r, 50));
    return { demandes: window.__envois.filter(m => m.rapport).length - avant,
             frais: /999/.test(zone.value) };
  });
  ok('« Actualiser » redemande à la page, et affiche la mesure neuve',
     actualise.demandes >= 1 && actualise.frais, JSON.stringify(actualise));

  /* ── FERMER ────────────────────────────────────────────────────────────
     La vue recouvre tout : si elle ne se referme pas, le panneau est perdu. */
  const rapportFerme = await page.evaluate(async () => {
    document.getElementById('rapport-fermer').click();
    await new Promise(r => setTimeout(r, 50));
    const r = document.getElementById('rapport');
    return { attribut: r.hidden, hauteur: Math.round(r.getBoundingClientRect().height) };
  });
  ok('« Fermer » rend le panneau, et la vue n\'occupe plus aucune place',
     rapportFerme.attribut === true && rapportFerme.hauteur === 0,
     JSON.stringify(rapportFerme));

  /* ── IL DOIT MARCHER QUAND RIEN NE MARCHE ──────────────────────────────
     C'est son seul moment utile : sans réponse de la page, le rapport doit
     tout de même porter l'environnement et dire POURQUOI le reste manque. */
  const sansPage = await page.evaluate(async () => {
    window.__panne = 'fond';
    document.getElementById('btn-rapport').click();
    const zone = document.getElementById('rapport-zone');
    for (let i = 0; i < 160 && !/TRANSPORT/.test(zone.value); i++) {
      await new Promise(r => setTimeout(r, 50));
    }
    window.__panne = null;
    return zone.value;
  });
  ok('sans réponse de la page, le rapport existe quand même et dit pourquoi',
     /ENVIRONNEMENT/.test(sansPage) && /Receiving end does not exist/.test(sansPage)
     && /did not fully answer/.test(sansPage),
     JSON.stringify((sansPage || '').slice(-180)));
  /* CE QUE LE RAPPORT D'ÉCHEC DOIT PORTER, et ne portait pas. Le rapport
     envoyé par un utilisateur tenait en quinze lignes : environnement,
     transport, « la page n'a pas répondu ». Or trois sources répondaient à cet
     instant-là — le worker, le pont, et le panneau lui-même — et aucune
     n'était consignée. Un rapport vide le jour de la panne ne sert à
     personne : c'est le seul jour où il sert. */
  ok('…et il porte le bloc HORS PAGE, avec la trace des essais',
     /DIAGNOSTIC HORS PAGE/.test(sansPage)
     && /essais \/ attempts\s+#0 fond/.test(sansPage)
     && /#3 fond/.test(sansPage),
     JSON.stringify((sansPage.match(/essais.*/) || [])[0]));
  ok('…et l\'état du worker, demandé SANS passer par le pont',
     /worker — ponts\s+injoignable \(fond\)/.test(sansPage),
     JSON.stringify((sansPage.match(/worker — ponts.*/) || [])[0]));

  /* ── LE DÉMARRAGE INACHEVÉ ─────────────────────────────────────────────── */
  const sansBoot = await page.evaluate(async () => {
    window.__panne = 'demarrage';
    document.getElementById('rapport-actualiser').click();
    const zone = document.getElementById('rapport-zone');
    for (let i = 0; i < 160 && !/HORS PAGE/.test(zone.value); i++) {
      await new Promise(r => setTimeout(r, 50));
    }
    window.__panne = null;
    return zone.value;
  });
  ok('un démarrage inachevé rend SON JOURNAL D\'ERREURS, seul contenu utile ce jour-là',
     /ERREURS \/ ERRORS \(1\) — démarrage inachevé/.test(sansBoot)
     && /STRINGS\[LANG\] is not defined/.test(sansBoot) && /×2/.test(sansBoot),
     JSON.stringify((sansBoot.match(/ERREURS.*/) || [])[0]));
  ok('…et il dit l\'étape atteinte, dans le bloc ENVIRONNEMENT',
     /démarrage \/ boot\s+i18n — INACHEVÉ/.test(sansBoot),
     JSON.stringify((sansBoot.match(/démarrage \/ boot.*/) || [])[0]));
  ok('…et ce que le monde ISOLATED voyait de la page (jalon, readyState)',
     /page — jalon \/ marker\s+i18n/.test(sansBoot)
     && /page — readyState\s+loading/.test(sansBoot),
     JSON.stringify((sansBoot.match(/page — jalon.*/) || [])[0]));

  await page.close();
}

// ═════════ 71. Le diagnostic — le voit-on jamais détecter quoi que ce soit ? ═════════
titre('71. Diagnostic — il doit crier au bon moment, et se taire au bon moment');
{
  /* CE SCÉNARIO VIENT D'UN RAPPORT RÉEL. Un utilisateur a reçu « des sélecteurs
     critiques ne correspondent plus au DOM de Twitch » — l'auto-diagnostic, qui
     est le filet de sécurité de tout le produit. Or jusqu'ici le banc n'en
     disait qu'UNE chose, et dans un seul sens : « aucune casse sur un décor
     sain ». Une sonde câblée en dur sur 'ok' aurait passé ce test pour
     toujours, et le filet n'aurait retenu personne.

     Les deux directions comptent autant l'une que l'autre :

       — une sonde qui ne détecte RIEN laisse l'extension se dégrader en
         silence, ce qu'elle existe précisément pour empêcher ;
       — une sonde qui crie À TORT est pire qu'absente : elle apprend à
         ignorer les suivantes, y compris la vraie.

     Le second cas n'est pas théorique. La sonde `followedSection` rendait
     « cassé » dès que la section « Chaînes suivies » manquait — c'est-à-dire
     aussi pour une session DÉCONNECTÉE et pour un compte qui NE SUIT PERSONNE,
     deux situations parfaitement normales où le markup de Twitch n'a rien
     changé. Elle utilise désormais le même signal neutre que `cardClass` : le
     nombre de liens de chaîne dans la barre. */
  const page = await browser.newPage();
  page.on('pageerror', e => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
  await page.goto(URL_PAGE);
  await page.evaluate(() => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    window.__fx = {
      alpha: { id: 'a', createdAt: h, viewers: 1000, game: 'Just Chatting', tags: [] },
      beta:  { id: 'b', createdAt: h, viewers: 900,  game: 'Elden Ring',    tags: [] },
    };
    window.__addCard('alpha', 'Just Chatting', '1 k');
    window.__addCard('beta',  'Elden Ring',    '900');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 2);

  const sonde = (id) => page.evaluate((n) =>
    (window.tse.diagnose().find(p => p.id === n) || {}), id);

  const sain = await sonde('followedSection');
  ok('sur un décor sain, la sonde de section répond « ok »',
     sain.status === 'ok', JSON.stringify(sain));

  /* ── LA SONDE DU PSEUDO, AJOUTÉE PAR UN AUDIT ──────────────────────────
     La ligne du pseudo a changé d'emplacement DEUX FOIS en une série de
     versions, et six fonctions ont cessé de la trouver à chaque fois. Aucune
     sonde ne la regardait : le rapport annonçait « tous les sélecteurs
     critiques répondent » pendant que Top Chaînes était vide. */
  const nomSain = await sonde('cardName');
  ok('la sonde de la ligne du pseudo répond « ok », et elle est critique',
     nomSain.status === 'ok' && nomSain.critical === true, JSON.stringify(nomSain));
  /* ON LA CASSE POUR DE VRAI : ni crochet, ni <p> à trouver. C'est le seul
     moyen de distinguer une sonde qui regarde de une sonde qui acquiesce. */
  await page.evaluate(() => {
    for (const c of document.querySelectorAll('.side-nav-card')) {
      for (const q of c.querySelectorAll('[data-a-target="side-nav-card-metadata"] p')) {
        const sp = document.createElement('span');
        sp.textContent = q.textContent;
        q.replaceWith(sp);
      }
    }
  });
  const nomCasse = await sonde('cardName');
  ok('…et « broken » dès que la ligne n\'est plus trouvable',
     nomCasse.status === 'broken', JSON.stringify(nomCasse));
  // On remet le décor d'aplomb : la suite du scénario mesure autre chose.
  await page.evaluate(() => {
    for (const c of document.querySelectorAll('.side-nav-card')) {
      for (const sp of c.querySelectorAll('[data-a-target="side-nav-card-metadata"] span')) {
        if (sp.classList.length) continue;
        const q = document.createElement('p');
        q.textContent = sp.textContent;
        sp.replaceWith(q);
      }
    }
  });

  /* ── LE SENS POSITIF : casser pour de vrai, et voir la sonde le dire ────
     On retire les DEUX prises de la section — l'aria-label et la classe du
     bandeau — puisque followedSection() a un repli sur la seconde. Une seule
     des deux ne prouverait rien : c'est le repli, et non la sonde, qu'on
     mesurerait. */
  await page.evaluate(() => {
    /* UNE BARRE VRAIMENT PEUPLÉE. Le signal neutre de la sonde est le nombre de
       liens de chaîne, et le décor du harnais n'en porte que DEUX — sous le
       seuil de trois. Sans ces liens, le cas « peuplée » n'était jamais
       atteint et l'assertion mesurait l'autre branche sans le dire : elle a
       échoué en rendant 'na' là où elle attendait 'broken'.

       On ajoute des <a> nus, et non des cartes : c'est exactement ce que la
       sonde compte — un signal indépendant de nos propres classes, choisi pour
       distinguer « Twitch a renommé son markup » de « la barre est vide ». */
    const nav = document.getElementById('side-nav');
    for (let i = 0; i < 5; i++) {
      const a = document.createElement('a');
      a.href = '/chaine' + i;
      nav.appendChild(a);
    }
    const sec = document.querySelector('.side-nav-section[aria-label]');
    sec.removeAttribute('aria-label');
    sec.querySelectorAll('[class*="followed-side-nav-header"]')
       .forEach(e => { e.className = 'entete-neutre'; });
    /* ── ET LA TROISIÈME PRISE, DEPUIS LA 3.92 ─────────────────────────
       Ce décor retirait les DEUX prises connues : l'aria-label et la classe du
       bandeau. Il en existe une troisième — le marqueur que Twitch pose sur
       SES cartes suivies, sur lequel `followedSection()` se rabat désormais
       quand aucun candidat libellé ne porte de carte. La laisser en place
       reviendrait à mesurer ce repli au lieu de la sonde, ce qui est
       exactement ce que le commentaire ci-dessus interdit : c'est bien la
       sonde qu'on éprouve, et une sonde ne peut crier que si l'extension a
       RÉELLEMENT perdu la section. On retire donc les trois. */
    document.querySelectorAll('a[data-test-selector="followed-channel"]')
      .forEach(a => a.setAttribute('data-test-selector', 'recommended-channel'));
  });
  const cassee = await sonde('followedSection');
  ok('section introuvable sur une barre PEUPLÉE : la sonde dit « cassé »',
     cassee.status === 'broken' && cassee.critical === true, JSON.stringify(cassee));

  /* ── LE SENS NÉGATIF : une barre vide n'est pas une casse ───────────────
     Même DOM, même section absente — mais plus de cartes ni de liens. C'est
     la sidebar d'un visiteur déconnecté. La sonde ne doit rien affirmer. */
  await page.evaluate(() => {
    document.querySelectorAll('#side-nav a[href^="/"]').forEach(a => a.removeAttribute('href'));
  });
  const vide = await sonde('followedSection');
  ok('même section absente, mais barre quasi vide : « non applicable », pas « cassé »',
     vide.status === 'na', JSON.stringify(vide));

  /* ── L'AVERTISSEMENT, ET SA MÉMOIRE ───────────────────────────────────
     Trois questions d'un coup, et TOUT tient dans UNE SEULE évaluation. Ce
     n'est pas un raccourci : l'auto-diagnostic tourne aussi sur le tour
     d'entretien, accéléré à 1,2 s dans le banc. Un comptage réparti sur
     plusieurs allers-retours verrait ce tour consommer l'incident entre deux
     mesures, et le test échouerait une fois sur deux sur du code sain. Rien
     ne peut s'intercaler dans une évaluation synchrone.

       1. l'avertissement NOMME-T-IL la sonde fautive ? Le rapport d'origine
          ne montrait que la phrase générique : la page « Erreurs » du
          navigateur retient le console.warn et pas le console.table imprimé
          juste après ;
       2. ne crie-t-il qu'UNE FOIS par incident ? Répété tous les tours
          d'entretien, il deviendrait du bruit ;
       3. se RÉARME-T-IL une fois l'incident résolu ? Sans quoi la deuxième
          panne serait silencieuse — le pire des trois défauts. */
  const memoire = await page.evaluate(() => {
    const sec = document.querySelector('.side-nav-section');
    /* LES TROIS PRISES, et non plus deux : depuis la 3.92, `followedSection()`
       se rabat sur le marqueur que Twitch pose sur ses cartes suivies. En
       laisser une seule intacte ferait mesurer le repli au lieu de la sonde. */
    const marqueurs = () => [...document.querySelectorAll(
      'a[data-test-selector="followed-channel"], a[data-test-selector="recommended-channel"]')];
    const casser  = () => { sec.removeAttribute('aria-label');
                            sec.querySelectorAll('[class*="followed-side-nav-header"]')
                               .forEach(e => { e.className = 'entete-neutre'; });
                            marqueurs().forEach(a =>
                              a.setAttribute('data-test-selector', 'recommended-channel')); };
    const reparer = () => { sec.setAttribute('aria-label', 'Chaînes suivies');
                            marqueurs().forEach(a =>
                              a.setAttribute('data-test-selector', 'followed-channel')); };
    // Une barre PEUPLÉE : c'est la condition pour que l'absence de section
    // vaille rupture. On rend leurs liens aux cartes.
    document.querySelectorAll('#side-nav a:not([href])').forEach(a => a.setAttribute('href', '/x'));
    /* ET LE VOILE DOIT ÊTRE LEVÉ. runSelectorHealthCheck sort immédiatement
       tant que body porte `tse-loading` — c'est délibéré côté produit : pendant
       le chargement les cartes ne sont pas rendues, et toute sonde répondrait
       n'importe quoi. Or les mutations qu'on vient de faire sur #side-nav
       relancent un cycle de voile. On le lève donc ici, ce qui reproduit la
       seule situation où ce contrôle s'exécute en production. Sans cette
       ligne, les trois assertions qui suivent mesuraient un garde-fou et non
       la mémoire de l'alerte — elles rendaient zéro avertissement. */
    document.body.classList.remove('tse-loading');

    const vrai = console.warn;
    const dits = [];
    console.warn = (...a) => { dits.push(a.join(' ')); };
    try {
      // État de départ connu : réparé, et la mémoire remise à zéro.
      reparer(); window.tse.diagnose.auto();
      const avant = dits.length;
      /* ── UNE SEULE LECTURE NE DIT RIEN, ET C'EST LE QUATRIÈME POINT ──────
         RAPPORT DE TERRAIN : l'alerte a été criée sur une sidebar EN TRAIN
         d'être rebâtie — « /?lang=fr », un rechargement après changement de
         langue, pendant lequel Twitch remonte ses liens avant l'en-tête de
         section. Le rapport pris juste après donnait la sonde « ok ».

         C'est exactement ce décor-ci : section sans étiquette, marqueurs
         retournés, sept liens en place. La seule chose qui manquait au
         produit était de CONFIRMER avant de conclure — ce que fait le reste
         du fichier partout ailleurs. */
      casser();  window.tse.diagnose.auto();       // ← une lecture : rien
      const uneSeule = dits.length - avant;
      reparer(); window.tse.diagnose.auto();       // ← réparée entre-temps
      const bref = dits.length - avant;

      casser();
      window.tse.diagnose.auto();
      window.tse.diagnose.auto();                  // ← confirmée : doit crier
      const premier = dits.length - avant - bref;
      window.tse.diagnose.auto();
      window.tse.diagnose.auto();                  // ← ne doit plus rien dire
      const repetitions = dits.length - avant - bref - premier;
      reparer(); window.tse.diagnose.auto();       // ← résolution : réarmement
      casser();
      window.tse.diagnose.auto();
      window.tse.diagnose.auto();                  // ← doit crier de nouveau
      const rearme = dits.length - avant - bref - premier - repetitions;
      return { uneSeule, bref, premier, repetitions, rearme,
               texte: dits[avant + bref] || '' };
    } finally { console.warn = vrai; reparer(); }
  });
  ok('l\'avertissement nomme la sonde fautive, pas seulement « des sélecteurs »',
     /followedSection/.test(memoire.texte) && /followedSelector/.test(memoire.texte),
     JSON.stringify(memoire.texte).slice(0, 200));
  /* ── ET LE QUATRIÈME POINT, VENU DU TERRAIN ───────────────────────────
     Mutant — l'alerte sur la première lecture, comme avant — « uneSeule 1 » :
     une sidebar qui se rebâtit est annoncée « peut-être partiellement
     cassée », et l'utilisateur apprend à ignorer l'alerte suivante. */
  ok('une rupture BRÈVE ne dit rien : une seule lecture n\'est pas un verdict',
     memoire.uneSeule === 0 && memoire.bref === 0, JSON.stringify(memoire));
  ok('il est émis une fois à l\'incident CONFIRMÉ, puis se tait',
     memoire.premier === 1 && memoire.repetitions === 0, JSON.stringify(memoire));
  ok('…et se réarme une fois l\'incident résolu, pour la panne suivante',
     memoire.rearme === 1, JSON.stringify(memoire));

  await page.close();
}

// ═════════ 72. Le journal d'erreurs ═════════
titre('72. Erreurs — ce que le rapport ne pouvait pas dire');
{
  /* CE MODULE N'EXISTAIT PAS, et son absence était le plus grand trou du
     rapport de diagnostic. L'extension ne consignait AUCUNE erreur : ni
     window.onerror, ni un seul console.error, et vingt-quatre `catch {}`
     muets. Un utilisateur dont l'historique se vide à chaque rechargement —
     quota de stockage dépassé — n'avait aucune trace de la cause, et personne
     ne pouvait la lui demander.

     LES DEUX DIRECTIONS COMPTENT AUTANT, et la seconde davantage. Le monde
     MAIN est PARTAGÉ avec le JavaScript de Twitch : un journal sans filtre se
     remplirait de centaines d'exceptions qui ne nous concernent pas, et
     chasserait les nôtres de sa fenêtre. Un journal noyé ne vaut pas mieux
     qu'un journal absent — il coûte seulement plus cher à lire. */
  const page = await browser.newPage();
  page.on('pageerror', () => {});   // on PROVOQUE des erreurs ici : elles sont l'objet du test
  /* UN RELEVÉ RÉCENT, et il faut dire pourquoi. Ce scénario affirme qu'une
     page saine ne consigne RIEN — l'affirmation ne vaut que si tout ce qui
     tourne peut réussir. Or le relevé d'abonnements ouvre une iframe sur
     `location.origin + '/subscriptions'`, et `location.origin` vaut la
     chaîne "null" sur un document file:// : il échoue toujours ici, et
     désormais il le DIT. C'est un artefact du harnais, pas du produit.
     On pose donc un horodatage frais — l'état de quelqu'un qui a relevé il
     y a cinq minutes — ce qui écarte le relevé par le chemin normal du
     TTL, sans rien désactiver. */
  await page.addInitScript(() => {
    try { localStorage.setItem('tse:substs', '2:' + Date.now()); } catch { /* file:// */ }
  });
  await page.goto(URL_PAGE);
  await page.evaluate(() => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    window.__fx = { alpha: { id: 'a', createdAt: h, viewers: 1000, game: 'Art', tags: [] } };
    window.__addCard('alpha', 'Art', '1 k');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 1);

  /* ── LE JALON DE DÉMARRAGE, qui est le PREMIER maillon de tout ce qui
     précède ────────────────────────────────────────────────────────────────
     Un rapport d'utilisateur est revenu avec « expiration » pour tout
     contenu : port branché, page muette, et rien pour dire laquelle des deux
     pannes c'était — content.js jamais entré, ou content.js tombé en route.
     Le jalon les sépare, et il ne peut le faire que si les trois maillons
     tiennent : content.js l'écrit sur <html>, bridge.js le lit depuis le monde
     ISOLATED (scénario 73), le panneau l'imprime (scénario 70). Ici, le
     premier — sans lui les deux autres n'observent rien. */
  const boot = await page.evaluate(() => {
    const r = window.tse.panneau.rapport();
    const e = r.demarrage.etapes;
    return {
      marque: document.documentElement.getAttribute('data-tse-boot'),
      etape: r.demarrage.etape,
      dureeMs: r.demarrage.dureeMs,
      dernierJalon: e.length ? e[e.length - 1].ms : null,
      age: r.ancienneteMs,
    };
  });
  ok('content.js pose son jalon sur <html>, et il va jusqu\'à « pret »',
     boot.marque === 'pret', JSON.stringify(boot.marque));
  ok('…et le rapport porte la même étape, pour être lisible sans le DOM',
     boot.etape === 'pret', JSON.stringify(boot.etape));
  /* LA DURÉE DOIT ÊTRE UNE DURÉE. Elle était calculée à la LECTURE du
     rapport — `Date.now() - début` — donc elle valait l'âge de la page,
     déjà donné deux lignes plus haut : un rapport d'utilisateur affichait
     « pret (44303 ms) » sur une page ouverte depuis 44 s. Un champ qui a
     l'air d'une mesure sans en être une est pire qu'un champ absent : on
     le lit, et on en conclut quelque chose de faux. Elle est maintenant
     figée au jalon franchi, ce qui se vérifie de deux façons. */
  /* ── ASSERTION REFAITE : ON ÉPROUVE LA PROPRIÉTÉ, PAS UNE MARGE ────────
     La rédaction d'avant comparait la durée à l'ÂGE de la page, moins deux
     cents millisecondes : `dureeMs < age - 200`. C'est une marge, pas une
     preuve, et elle dépend de la vitesse à laquelle le banc atteint sa
     lecture. Elle a fini par échouer sur du code sain — relevé
     « dureeMs 45, age 208 » sur une machine chargée, où 45 < 8 est faux.
     Une assertion qui tombe sur un produit juste est pire qu'une assertion
     absente : on apprend à l'ignorer.

     CE QU'ON VEUT DIRE EST EXACT ET NE DÉPEND D'AUCUNE HORLOGE : la durée
     est FIGÉE. On la lit deux fois, séparées par une attente, et on exige
     qu'elle n'ait pas bougé — pendant que l'âge de la page, lui, a
     augmenté. Une durée recalculée à la lecture ne peut pas satisfaire les
     deux à la fois. */
  await wait(page, 300);
  const relu = await page.evaluate(() => {
    const r = window.tse.panneau.rapport();
    return { dureeMs: r.demarrage.dureeMs, age: r.ancienneteMs };
  });
  ok('…et la durée de démarrage est FIGÉE au jalon, pas relue à l\'arrivée',
     boot.dureeMs === boot.dernierJalon
     && relu.dureeMs === boot.dureeMs
     && relu.age > boot.age,
     JSON.stringify({ boot, relu }));

  const journal = () => page.evaluate(() => window.tse.panneau.rapport().erreurs);

  const vierge = await journal();
  ok('sur une page saine, le journal est vide — et c\'est une information',
     Array.isArray(vierge) && vierge.length === 0, JSON.stringify(vierge).slice(0, 160));

  /* ── LE QUOTA DE STOCKAGE ──────────────────────────────────────────────
     Le cas qui a motivé ce module : localStorage.setItem lève, le `catch`
     avale, et l'utilisateur voit son historique disparaître à chaque
     rechargement sans que rien n'explique pourquoi.

     PREMIÈRE ÉCRITURE DE CE TEST, il appelait tse.reset() en boucle et
     n'obtenait rien : reset() n'écrit pas, il appelle removeItem. Les points
     instrumentés sont les ÉCRITURES. On passe donc par le roster, qui se
     sérialise sur le tour d'entretien — le seul chemin qui produise vraiment
     un setItem sans rien simuler d'autre. */
  const quota = await page.evaluate(async () => {
    const vrai = Storage.prototype.setItem;
    Storage.prototype.setItem = function () {
      const e = new Error('quota'); e.name = 'QuotaExceededError'; throw e;
    };
    try {
      // Chaque carte neuve salit le roster ; le tour d'entretien le sérialise,
      // et l'écriture échoue. Trois fois : la MÊME panne, trois fois.
      for (const nom of ['gamma', 'delta', 'epsilon']) {
        window.__fx[nom] = { id: nom, createdAt: new Date(Date.now() - 600_000).toISOString(),
                             viewers: 100, game: 'Art', tags: [] };
        window.__addCard(nom, 'Art', '100');
        await new Promise(r => setTimeout(r, 1500));   // > MAINTENANCE_TICK accéléré
      }
    } finally { Storage.prototype.setItem = vrai; }
    return window.tse.panneau.rapport().erreurs;
  });
  const stockage = (quota || []).filter(e => e.source === 'stockage');
  ok('un quota de stockage dépassé laisse enfin une trace',
     stockage.length > 0 && /Quota/.test(stockage[0].message),
     JSON.stringify(quota).slice(0, 220));
  /* CE QU'ON ÉPROUVE ICI, c'est qu'une panne répétée occupe UNE ligne et
     porte son compte — pas que le journal n'en contienne qu'une. La
     première rédaction confondait les deux, et elle est tombée dès qu'un
     second point d'écriture a été instrumenté sous le même quota : elle
     mesurait le nombre de sites instrumentés, pas le dédoublonnage. */
  const rosterQuota = stockage.filter(e => /roster/.test(e.message));
  ok('…et la même panne répétée est COMPTÉE, pas empilée',
     rosterQuota.length === 1 && rosterQuota[0].n > 1
     && new Set(stockage.map(e => e.message)).size === stockage.length,
     JSON.stringify(stockage.map(e => ({ m: e.message, n: e.n }))));

  /* ── LE FILTRE, dans les deux sens ─────────────────────────────────────
     Une exception levée par un script qui n'est PAS le nôtre ne doit pas
     entrer. C'est ce qui sépare un journal lisible d'un déversoir : le monde
     MAIN est partagé, et Twitch y lève des exceptions par dizaines. */
  const avant = (await journal()).length;
  await page.evaluate(() => {
    const sc = document.createElement('script');
    sc.textContent = 'setTimeout(function(){ throw new Error("erreur de Twitch"); }, 0);';
    document.head.appendChild(sc);
  });
  await wait(page, 300);
  const apresTwitch = await journal();
  ok('une exception venue du JavaScript de Twitch n\'entre PAS dans le journal',
     apresTwitch.length === avant && !apresTwitch.some(e => /Twitch/.test(e.message)),
     JSON.stringify(apresTwitch.map(e => e.message)).slice(0, 200));

  /* ── …ET LA NÔTRE, ELLE, DOIT ENTRER ───────────────────────────────────
     L'autre moitié du filtre, et la plus facile à casser sans s'en rendre
     compte : un filtre trop serré ne retiendrait plus rien, et le journal
     serait vide pour une raison qu'aucun test ne dirait.

     ON NE PASSE PAS PAR window.onerror, ET C'EST TOUT L'OBJET DE CE BLOC.
     Mesuré ici même : une exception de notre script arrive au gestionnaire
     `error` sous la forme « Script error. », filename et pile VIDES — masquage
     cross-origin, qui vaut aussi en production puisque notre code vient de
     chrome-extension:// et la page de https://www.twitch.tv. Le filtre par URL
     ne peut donc pas la reconnaître.

     C'est la GARDE qui la rattrape : elle enveloppe nos points d'entrée et ne
     dépend d'aucune origine. On la déclenche par le pont, dont une demande
     inconnue est un défaut réel — panneau et page sont livrés ensemble. */
  const nôtre = await page.evaluate(() => new Promise((res) => {
    window.postMessage({ tse: 'tse-panneau-req', id: 4242, section: 'ça-nexiste-pas' }, '*');
    setTimeout(() => res(window.tse.panneau.rapport().erreurs), 200);
  }));
  ok('…mais un défaut venu de NOTRE code y entre, sans dépendre de l\'origine',
     nôtre.some(e => e.source === 'panneau' && /ça-nexiste-pas/.test(e.message)),
     JSON.stringify(nôtre.map(e => `${e.source}:${e.message}`)).slice(0, 220));

  /* ── LE JOURNAL EST BORNÉ ──────────────────────────────────────────────
     Quarante entrées au plus. Sans borne, une extension laissée ouverte une
     journée finirait par tenir en mémoire tout ce qui a jamais mal tourné.

     Les messages sont DISTINCTS à dessein : le dédoublonnage masquerait
     autrement ce qu'on mesure. Et on exige que le journal soit PLEIN — une
     borne vérifiée sur un journal vide ne vérifie rien, et c'est exactement ce
     que faisait la première version de ce test : elle passait sur zéro
     entrée. */
  const borne = await page.evaluate(() => new Promise((res) => {
    for (let i = 0; i < 80; i++) {
      window.postMessage({ tse: 'tse-panneau-req', id: 5000 + i, section: 'inconnue-' + i }, '*');
    }
    setTimeout(() => res(window.tse.panneau.rapport().erreurs), 400);
  }));
  ok('le journal est borné, et il est bien PLEIN quand on le mesure',
     borne.length === 40, `${borne.length} entrées après 80 défauts distincts`);
  ok('…et ce sont les PLUS RÉCENTES qui restent',
     /inconnue-79/.test(borne[borne.length - 1].message)
     && !borne.some(e => /inconnue-0\b/.test(e.message)),
     JSON.stringify([borne[0].message, borne[borne.length - 1].message]));

  await page.close();
}

titre('73. Le transport — les trois sauts doivent se comprendre');
{
  /* CE SCÉNARIO EXISTE PARCE QUE SON ABSENCE A LAISSÉ PASSER UNE FONCTION QUI
     NE MARCHAIT PAS DU TOUT. Le rapport de diagnostic ne pouvait PAS
     fonctionner : le panneau envoyait `{ rapport: true }`, background.js
     recopiait la demande champ par champ — `section`, `action`, `arg` — et
     jetait `rapport` en silence ; bridge.js exigeait ensuite `section` ou
     `action` et rendait la main sans répondre. La demande n'arrivait nulle
     part, et le panneau attendait 35 secondes pour n'afficher que son propre
     bloc TRANSPORT. Un utilisateur l'a signalé, avec un rapport de quinze
     lignes à l'appui.

     LE BANC ÉTAIT VERT. Les 25 assertions du scénario 70 branchent le panneau
     sur un `chrome` de substitution qui répond directement — donc sautent
     exactement les deux fichiers qui se contredisaient. Ce n'est pas un trou
     de couverture au sens des lignes exécutées : la ligne fautive était
     couverte par le scénario 69, côté page. C'est un trou de CONTRAT — trois
     fichiers énuméraient chacun la même liste de champs, et il suffisait
     qu'un seul en oublie un.

     On charge donc les VRAIS background.js et bridge.js, dans un contexte
     `vm`, autour d'un couple de ports factices. Ce qu'on éprouve n'est pas
     leur comportement pris un par un : c'est qu'une demande entre d'un bout
     et ressorte à l'autre AVEC LES MÊMES CHAMPS. */
  const contexteTransport = ({ marque = 'pret', firefox = false } = {}) => {
    const journal = { versPage: [], reponses: [] };
    let ecouteurPage = null;      // l'écouteur 'message' posé par bridge.js
    let onConnect = null, onMessageFond = null;

    /* Un couple de ports : ce que `chrome.runtime.connect()` rend d'un côté,
       ce que `onConnect` reçoit de l'autre. Les deux se parlent en direct —
       c'est tout ce qu'un port est. */
    const couple = (tabId) => {
      const f = { auts: [], fins: [] }, b = { auts: [], fins: [] };
      const faire = (moi, autre, sender) => ({
        name: 'tse-panneau',
        sender,
        postMessage: (m) => { for (const l of autre.auts) l(m); },
        disconnect:  ()  => { for (const l of autre.fins) l(); },
        onMessage:    { addListener: (l) => moi.auts.push(l) },
        onDisconnect: { addListener: (l) => moi.fins.push(l) },
      });
      return [faire(f, b, undefined), faire(b, f, { tab: { id: tabId } })];
    };

    /* LE FAUX « chrome » DOIT PORTER CE QUE LE VRAI PORTE, sans quoi il ne
       simule plus rien. La leçon a été apprise à la 4.11 : un écouteur
       « onInstalled » ajouté à background.js a fait lever « Cannot read
       properties of undefined » AU CHARGEMENT DU FICHIER, parce que ce décor-ci
       ne portait pas l'API. Le décor était incomplet, pas le code — et la
       tentation de garder l'appel derrière un « ?. » aurait silencieusement
       avalé un navigateur qui ne porterait pas cette API.

       CET ÉCOUTEUR A DISPARU À LA 4.12 avec l'onglet d'installation ; ce qui
       reste est la règle, et elle vaut pour la prochaine API que le fond
       touchera. */
    const chromeFond = {
      runtime: {
        onConnect: { addListener: (l) => { onConnect = l; } },
        onMessage: { addListener: (l) => { onMessageFond = l; } },
        getURL: (c) => 'chrome-extension://tse/' + c,
      },
    };
    const ctxFond = createContext({
      chrome: chromeFond,
      /* `browser` n'existe QUE sur Firefox, et c'est ce qui fait basculer le
         dialecte de réponse. On le définit ou non selon la cible simulée. */
      ...(firefox ? { browser: chromeFond } : {}),
      setTimeout, clearTimeout, Date, console,
    });
    runInContext(readFileSync(join(ICI, '..', 'background.js'), 'utf8'), ctxFond);

    const fen = {
      addEventListener: (t, l) => { if (t === 'message') ecouteurPage = l; },
      postMessage: (m) => journal.versPage.push(m),
    };
    fen.top = fen;                             // cadre principal : la garde passe
    const ctxPont = createContext({
      window: fen,
      document: {
        hidden: false,
        readyState: 'complete',
        documentElement: { getAttribute: () => marque },
        addEventListener: () => {},
      },
      location: { hostname: 'www.twitch.tv' },
      chrome: {
        runtime: {
          connect: () => {
            const [cotePont, coteFond] = couple(7);
            onConnect(coteFond);
            return cotePont;
          },
        },
      },
      setTimeout, clearTimeout, Date, console,
    });
    runInContext(readFileSync(join(ICI, '..', 'bridge.js'), 'utf8'), ctxPont);

    /* Le geste du panneau, à l'identique : c'est `demander()` qui pose cette
       enveloppe, et c'est elle qu'on doit reproduire pour que le test porte. */
    const depuisPanneau = (charge, tabId = 7) => new Promise((res) => {
      const rendu = onMessageFond({ type: 'tse-panneau', tabId, ...charge }, {},
                                  (r) => { journal.reponses.push(r); res(r); });
      journal.rendu = rendu;
      /* Les deux dialectes : Chrome rend `true` et répond par le rappel,
         Firefox rend une PROMESSE et ignore le rappel. Le harnais doit lire
         les deux, sans quoi il ne pourrait éprouver que celui qu'il connaît. */
      if (rendu && typeof rendu.then === 'function') {
        rendu.then((r) => { journal.reponses.push(r); res(r); });
      } else if (rendu === false && !journal.reponses.length) res(undefined);
    });
    // La page répond, dans le monde MAIN : bridge.js écoute la même fenêtre.
    const pageRepond = (charge) =>
      ecouteurPage({ source: fen, data: { tse: 'tse-panneau-res', ...charge } });

    return { journal, depuisPanneau, pageRepond,
             etat: () => new Promise((res) => {
               onMessageFond({ type: 'tse-panneau-etat' }, {}, res);
             }) };
  };

  /* ── LE DÉFAUT LUI-MÊME ─────────────────────────────────────────────────── */
  {
    const t = contexteTransport();
    const p = t.depuisPanneau({ rapport: true });
    ok('la demande de rapport ATTEINT la page (le défaut signalé)',
       t.journal.versPage.length === 1 && t.journal.versPage[0].rapport === true,
       JSON.stringify(t.journal.versPage));
    t.pageRepond({ id: t.journal.versPage[0]?.id, ok: true, data: { genere: 42 } });
    const r = await p;
    ok('…et sa réponse revient intacte jusqu\'au panneau',
       r && r.ok === true && r.data && r.data.genere === 42, JSON.stringify(r));
    /* Les observations du pont n'étaient jointes qu'aux ÉCHECS, et le
       rapport d'un utilisateur dont tout marchait affichait donc « le pont
       n'a pas répondu » — sur une réponse qu'il venait de rendre. Un champ
       de diagnostic qui ment dans le cas nominal fait douter des autres. */
    ok('…accompagnée de ce que le pont voit, MÊME quand tout va bien',
       r.observations && r.observations.marque === 'pret'
       && r.observations.pont === 'branché', JSON.stringify(r.observations));
  }

  /* ── LA CLASSE, PAS L'INSTANCE ──────────────────────────────────────────
     Corriger `rapport` sans corriger la recopie champ par champ aurait laissé
     le prochain champ tomber dans le même trou. On éprouve donc un nom que
     personne n'a écrit nulle part : s'il traverse, c'est que plus aucun des
     deux sauts ne tient de liste. */
  {
    const t = contexteTransport();
    const p = t.depuisPanneau({ champInedit: 'xyz', arg: 3 });
    ok('un champ que ni background.js ni bridge.js ne connaissent traverse quand même',
       t.journal.versPage[0]?.champInedit === 'xyz' && t.journal.versPage[0]?.arg === 3,
       JSON.stringify(t.journal.versPage[0]));
    t.pageRepond({ id: t.journal.versPage[0].id, ok: false, erreur: 'x',
                   observations: { marque: 'pret' }, partiel: { etape: 'i18n' } });
    const r = await p;
    ok('…et les champs d\'EXPLICATION de la réponse aussi (observations, partiel)',
       r?.observations?.marque === 'pret' && r?.partiel?.etape === 'i18n',
       JSON.stringify(r));
  }

  /* ── PAS DE CONTENT.JS : ON LE DIT TOUT DE SUITE ───────────────────────── */
  {
    const t = contexteTransport({ marque: null });
    const r = await t.depuisPanneau({ rapport: true });
    ok('sans le jalon de content.js, le pont répond SANS attendre l\'expiration',
       r && r.ok === false && r.erreur === 'page-absente', JSON.stringify(r));
    ok('…et il n\'a rien envoyé à une page qui n\'écoute pas',
       t.journal.versPage.length === 0, `${t.journal.versPage.length} envoi(s)`);
    ok('…en disant ce qu\'il voit à la place (hôte, readyState, pont)',
       r.observations && r.observations.hote === 'www.twitch.tv'
       && r.observations.etat === 'complete' && r.observations.pont === 'branché',
       JSON.stringify(r.observations));
  }

  /* ── LES DEUX DIALECTES DE RÉPONSE ────────────────────────────────────────
     Une réponse asynchrone à `runtime.onMessage` se signale de deux façons qui
     s'excluent : Chrome veut `return true` plus `sendResponse`, Firefox veut
     une PROMESSE. Ce fichier ne parlait que le premier. Je n'ai pas pu
     l'exécuter sur un vrai Firefox — il n'y en a pas sur cette machine — donc
     le code ne PARIE plus : il parle les deux, et c'est ici qu'on l'exige. */
  {
    const t = contexteTransport();
    const p = t.depuisPanneau({ rapport: true });
    ok('sur Chrome, l\'écouteur rend `true` et répond par sendResponse',
       t.journal.rendu === true, JSON.stringify(String(t.journal.rendu)));
    t.pageRepond({ id: t.journal.versPage[0].id, ok: true, data: { genere: 1 } });
    ok('…et la réponse arrive bien par ce chemin-là', (await p)?.ok === true);
  }
  {
    const t = contexteTransport({ firefox: true });
    const p = t.depuisPanneau({ rapport: true });
    ok('sur Firefox, il rend une PROMESSE — `true` n\'y suffit pas',
       !!t.journal.rendu && typeof t.journal.rendu.then === 'function',
       JSON.stringify(String(t.journal.rendu)));
    t.pageRepond({ id: t.journal.versPage[0].id, ok: true, data: { genere: 2 } });
    const r = await p;
    ok('…et cette promesse porte la réponse, sans passer par sendResponse',
       r && r.ok === true && r.data.genere === 2, JSON.stringify(r));
  }

  /* ── L'ONGLET SANS PONT, ET L'ÉTAT DU WORKER ───────────────────────────── */
  {
    const t = contexteTransport();
    const r = await t.depuisPanneau({ rapport: true }, 999);
    ok('un onglet sans pont rend « absent », et nomme les ponts connus',
       r && r.erreur === 'absent' && /7/.test(r.detail || ''), JSON.stringify(r));
    const e = await t.etat();
    ok('le worker sait se décrire sans passer par le pont',
       e && e.ok === true && e.ponts.join() === '7' && typeof e.workerMs === 'number',
       JSON.stringify(e));
  }
}

titre('74. Erreurs — la taxonomie, et ce qu\'elle rend visible');
{
  /* CE SCÉNARIO EXISTE PARCE QUE « le rapport porte les erreurs » ÉTAIT VRAI
     ET NE VOULAIT PRESQUE RIEN DIRE. Le journal existait ; ce qui le
     remplissait, non. Sur les cinquante-deux `catch` du fichier, sept étaient
     instrumentés — et pas ceux qui comptent.

     Le trou le plus large : `post()`, l'unique point de passage du réseau,
     repliait CINQ échecs sur une même sentinelle muette. Un 429, un 5xx, un
     abandon au délai, un `fetch` qui rejette et un corps illisible se lisaient
     tous comme un cache vide. C'est LA panne la plus probable d'une extension
     dont tout l'affichage dépend d'une API tierce, et le rapport n'en disait
     pas un mot. Ce qui suit exige que chacune ait son nom. */
  const page = await freshTwitch();
  page.on('pageerror', () => {});
  await page.evaluate(() => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    window.__fx = { alpha: { id: 'a', createdAt: h, viewers: 1000, game: 'Art', tags: [] } };
    window.__addCard('alpha', 'Art', '1 k');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 1);

  /* Chaque levier se consomme en un appel : on arme, on force un balayage, et
     on attend que le journal ait GRANDI — pas une durée fixe, qui mentirait
     dès que la machine est chargée. */
  const provoquer = async (etat) => {
    const avant = await page.evaluate(() => window.tse.panneau.rapport().erreurs.length);
    await page.evaluate((e) => { Object.assign(window, e); window.tse.rescan(); }, etat);
    await attendre(page, (n) => window.tse.panneau.rapport().erreurs.length > n, 6000, avant);
  };
  await provoquer({ __httpStatus: 429 });
  await provoquer({ __abort: true });
  await provoquer({ __badJson: true });
  await provoquer({ __failNext: 1 });
  await provoquer({ __gqlErrors: true });

  const gql = await page.evaluate(() =>
    window.tse.panneau.rapport().erreurs.filter(e => e.source === 'gql').map(e => e.message));
  const porte = (m) => gql.some(x => x.includes(m));
  ok('un statut HTTP est recopié tel quel — 429 ne se répare pas comme un 503',
     porte('HTTP 429'), JSON.stringify(gql));
  ok('un abandon au délai est nommé abandon, et dit son délai',
     gql.some(x => /^abandon après \d+ ms$/.test(x)), JSON.stringify(gql));
  ok('un corps illisible n\'est pas confondu avec une panne de réseau',
     porte('corps illisible'), JSON.stringify(gql));
  ok('un fetch qui rejette est nommé échec de fetch',
     porte('échec de fetch'), JSON.stringify(gql));
  /* CELUI-CI EST LE PLUS SOURNOIS : HTTP 200, transport parfait, et un corps
     qui ne porte que des refus. Rien dans la couche réseau ne bronchait, et le
     cache restait vide sans la moindre trace. */
  ok('un 200 porteur d\'erreurs GraphQL est consigné, sans rien changer au flux',
     porte('erreurs GraphQL'), JSON.stringify(gql));

  const res = await page.evaluate(() => window.tse.panneau.rapport().reseau);
  ok('le rapport dit combien d\'appels ont été passés, et combien ont échoué',
     res.appels >= 5 && res.echecs >= 4, JSON.stringify(res));
  ok('…et depuis quand le dernier a réussi — zéro appel et zéro succès se ressemblaient',
     Number.isFinite(res.dernierSuccesIlYaMs), JSON.stringify(res.dernierSuccesIlYaMs));

  /* ── LES COMPTEURS SURVIVENT À CE QUE LA FENÊTRE LAISSE TOMBER ─────────── */
  const bilan = await page.evaluate(async () => {
    const av = window.tse.panneau.rapport().bilanErreurs.total;
    for (let i = 0; i < 80; i++) {
      window.postMessage({ tse: 'tse-panneau-req', id: 9000 + i, section: 'noyade-' + i }, '*');
    }
    await new Promise(r => setTimeout(r, 400));
    const r = window.tse.panneau.rapport();
    return { av, total: r.bilanErreurs.total, sources: r.bilanErreurs.sources,
             journal: r.erreurs.length,
             gqlEncore: r.erreurs.some(e => e.source === 'gql') };
  });
  ok('quatre-vingts défauts n\'entrent pas dans une fenêtre de quarante',
     bilan.journal === 40, `${bilan.journal} entrées`);
  ok('…mais le TOTAL, lui, les compte tous — la fenêtre ne ment plus par omission',
     bilan.total >= bilan.av + 80, JSON.stringify({ av: bilan.av, total: bilan.total }));
  ok('…et la fenêtre a bien évincé les erreurs réseau — sans quoi le total ne prouve rien',
     bilan.gqlEncore === false, 'des entrées gql sont encore dans le journal');
  ok('…et chaque famille garde son compte, sa première et sa dernière apparition',
     bilan.sources.some(s => s.source === 'gql' && s.n >= 5
                             && s.premiere > 0 && s.derniere >= s.premiere),
     JSON.stringify(bilan.sources.find(s => s.source === 'gql')));

  /* ── DEUX DÉFAUTS QUI ALTERNENT NE DOIVENT PAS VIDER LE JOURNAL ─────────
     Le dédoublonnage ne comparait qu'à la DERNIÈRE entrée. Deux problèmes qui
     se succèdent — un échec réseau et le repli qui le suit — se réinsèrent
     alors l'un l'autre indéfiniment et chassent tout le reste en quelques
     secondes. La comparaison porte maintenant sur toute la liste. */
  const alterne = await page.evaluate(async () => {
    for (let i = 0; i < 60; i++) {
      window.postMessage({ tse: 'tse-panneau-req', id: 20000 + i,
                           section: i % 2 ? 'ping' : 'pong' }, '*');
    }
    await new Promise(r => setTimeout(r, 400));
    const j = window.tse.panneau.rapport().erreurs;
    return { deux: j.filter(e => /ping|pong/.test(e.message)),
             autres: j.filter(e => /noyade-/.test(e.message)).length };
  });
  ok('deux défauts qui alternent tiennent en DEUX entrées, comptées',
     alterne.deux.length === 2 && alterne.deux.every(e => e.n === 30),
     JSON.stringify(alterne.deux.map(e => [e.message, e.n])));
  ok('…donc ils n\'ont chassé personne du journal',
     alterne.autres > 0, `${alterne.autres} entrées antérieures survivantes`);

  /* ── LES SONDES CASSÉES ENTRENT AU JOURNAL ────────────────────────────────
     Twitch qui change son markup est la panne la plus probable de ce produit —
     c'est la raison d'être des sondes. Elle n'apparaissait pourtant pas dans
     le bloc ERREURS : elle ne se lisait que dans le tableau des sondes, qui
     donne l'état de MAINTENANT. Un rapport pris après un rechargement réussi
     n'en gardait aucune trace. */
  const sondes = await page.evaluate(() => {
    const vrai = console.warn; console.warn = () => {};
    try {
      /* On casse `followedSection`, et PAS `#side-nav` : sans racine, le
         contrôle sort avant d'avoir sondé quoi que ce soit, et l'assertion
         mesurerait un garde-fou. Le seuil de la sonde demande par ailleurs
         une barre peuplée — le harnais n'a que deux liens — d'où les cinq
         ancres ajoutées, et le voile levé comme au scénario 71. */
      const nav = document.getElementById('side-nav');
      for (let i = 0; i < 5; i++) {
        const a = document.createElement('a'); a.href = '/x' + i; nav.appendChild(a);
      }
      const sec = document.querySelector('.side-nav-section[aria-label]');
      sec.removeAttribute('aria-label');
      sec.querySelectorAll('[class*="followed-side-nav-header"]')
         .forEach(e => { e.className = 'entete-neutre'; });
      /* La troisième prise, depuis la 3.92 : le marqueur de Twitch, sur lequel
         `followedSection()` se rabat. Une sonde ne peut crier que si
         l'extension a réellement perdu la section. */
      document.querySelectorAll('a[data-test-selector="followed-channel"]')
        .forEach(a => a.setAttribute('data-test-selector', 'recommended-channel'));
      document.body.classList.remove('tse-loading');
      /* DEUX LECTURES, parce qu'une seule n'est plus un verdict : une rupture
         se confirme avant de s'annoncer (cf. scénario 71). Le journal ne doit
         donc porter la trace QUE d'un incident confirmé — c'est la même
         exigence, vue depuis l'autre bout. */
      window.tse.diagnose.auto();
      window.tse.diagnose.auto();
      return window.tse.panneau.rapport().erreurs.filter(e => e.source === 'sondes');
    } finally { console.warn = vrai; }
  });
  ok('une sonde critique cassée est DATÉE au journal, pas seulement affichée',
     sondes.length > 0 && sondes.some(e => /followedSection/.test(e.message)),
     JSON.stringify(sondes.map(e => e.message)));

  await page.close();

  /* ── LE STOCKAGE : LA LECTURE COMPTE AUTANT QUE L'ÉCRITURE ────────────────
     Les quatre ÉCRITURES étaient instrumentées, les quatre LECTURES non. C'est
     pourtant la lecture qui explique « mon historique a disparu » : un JSON
     corrompu par une écriture interrompue se lit comme une mémoire vide, et
     l'extension repartait de zéro sans un mot. On empoisonne les quatre
     magasins AVANT le chargement de la page — c'est le seul moment où load()
     tourne. */
  const poison = await freshTwitch(undefined, [], '/', () => {
    try {
      for (const k of ['tse:visits', 'tse:subs', 'tse:roster', 'tse:livelag']) {
        localStorage.setItem(k, '{ceci n\'est pas du JSON');
      }
    } catch { /* stockage refusé : le test s'en apercevra */ }
  });
  poison.on('pageerror', () => {});
  await attendre(poison, () => !!(window.tse && window.tse.panneau));
  const lectures = await poison.evaluate(() =>
    window.tse.panneau.rapport().erreurs
      .filter(e => e.source === 'stockage').map(e => e.message));
  ok('les QUATRE magasins signalent leur lecture illisible, chacun par son nom',
     ['visites', 'abonnements', 'roster', 'mesures']
       .every(m => lectures.some(x => x.includes('lecture ' + m))),
     JSON.stringify(lectures));

  /* ── EFFACER, ET SAVOIR QUE ÇA N'A PAS EFFACÉ ─────────────────────────── */
  const efface = await poison.evaluate(() => {
    const vrai = Storage.prototype.removeItem;
    Storage.prototype.removeItem = function () {
      throw new DOMException('refusé', 'SecurityError');
    };
    try { window.tse.reset(); } catch { /* on veut le journal, pas l'exception */ }
    finally { Storage.prototype.removeItem = vrai; }
    return window.tse.panneau.rapport().erreurs
      .filter(e => /effacement/.test(e.message)).map(e => e.message);
  });
  ok('un effacement refusé est consigné — « j\'ai effacé et ça revient » s\'instruit',
     efface.length > 0 && efface.some(m => /SecurityError/.test(m)),
     JSON.stringify(efface));

  await poison.close();
}

titre('75. Abonnements — un relevé vide et une session expirée ne sont pas la même chose');
{
  /* LA CAUSE N°1 D'UN RELEVÉ VIDE CHEZ QUELQU'UN QUI A DES ABONNEMENTS : la
     page /subscriptions exige d'être connecté, et Twitch renvoie ailleurs
     quand la session a expiré. L'extension rendait alors une liste vide —
     rigoureusement indiscernable de « vous n'avez aucun abonnement ». Deux
     verdicts opposés sous la même apparence, et rien nulle part pour trancher.

     DEUX FORMES, ET ELLES NE SE RÉPARENT PAS PAREIL :
       — la page répond, mais ailleurs. Le chemin est LISIBLE, et il porte
         l'information : « /login » dit une session expirée ;
       — la page n'est même pas lisible. `contentWindow.location` jette une
         SecurityError, et on ne sait rien de plus que « ce n'est pas nous ».

     Sur la première, la simulation mérite un mot. Une redirection HTTP servie
     par le harnais donne au cadre une ORIGINE OPAQUE — mesuré : la cible du
     302 n'est pas ré-interceptée, part sur le vrai réseau et échoue. Elle
     produit donc la SECONDE forme, pas la première. Pour obtenir la première,
     le document servi change son propre chemin par `history.replaceState` :
     l'observable dont dépend le produit — `contentWindow.location.pathname`,
     même origine, différent de '/subscriptions' — est reproduit exactement,
     et c'est le seul observable qu'il lise. */
  const relever = async (mode, connus = 0) => {
    const page = await browser.newPage();
    page.on('pageerror', () => {});
    /* La mémoire d'avant le relevé. C'est elle qui décide si « rien
       trouvé » est une panne ou le compte de quelqu'un sans abonnement. */
    await page.addInitScript((n) => {
      try {
        const m = {};
        for (let i = 0; i < n; i++) m['abo' + i] = [1, Date.now()];
        localStorage.setItem('tse:subs', JSON.stringify(m));
      } catch { /* stockage refusé */ }
    }, connus);
    await page.route('https://www.twitch.tv/**', (route) => {
      const url = route.request().url();
      const name = url.split('/').pop().split('?')[0];
      if (name.endsWith('.js')) {
        return route.fulfill({ contentType: 'application/javascript; charset=utf-8',
                               body: fileText(name) });
      }
      if (url.includes('/subscriptions')) {
        return mode === 'chemin'
          ? route.fulfill({ contentType: 'text/html; charset=utf-8',
              body: '<!doctype html><meta charset="utf-8">'
                  + '<script>history.replaceState(null, "", "/login");</script>' })
          : route.fulfill({ status: 302,
                            headers: { location: 'https://www.twitch.tv/login' } });
      }
      return route.fulfill({ contentType: 'text/html; charset=utf-8',
                             body: fileText('page.html') });
    });
    await page.route('https://static-cdn.jtvnw.net/**',
                     (r) => r.fulfill({ contentType: 'image/png', body: PIXEL }));
    await page.goto('https://www.twitch.tv/alpha');
    await page.evaluate(() => {
      const h = new Date(Date.now() - 3600_000).toISOString();
      window.__fx = { alpha: { id: 'a', createdAt: h, viewers: 1000, game: 'Art', tags: [] } };
      window.__addCard('alpha', 'Art', '1 k');
    });
    await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 1);
    /* ON ATTEND LA FIN DU RELEVÉ, pas sa première erreur. La rédaction
       précédente lisait le journal dès qu'une entrée `abonnements` paraissait,
       c'est-à-dire au premier onglet renvoyé — donc AVANT le verdict d'ensemble,
       qui ne se rend qu'à la fin. Elle faisait échouer l'assertion qui le
       cherche, et surtout elle rendait VIDE celle qui vérifie son silence : on
       constatait une absence qui n'avait pas encore eu lieu.
       L'horodatage est écrit juste avant ce verdict, dans le même bloc
       synchrone : le voir frais, c'est savoir que le relevé est allé au bout. */
    const t0 = await page.evaluate(() => {
      const t = Date.now();
      window.tse.subs.refresh();
      return t;
    });
    await attendre(page,
      (d) => window.tse.panneau.rapport().relevesAbonnements.horodatage >= d, 30_000, t0);
    const abo = await page.evaluate(() => window.tse.panneau.rapport().erreurs
      .filter(e => e.source === 'abonnements').map(e => ({ m: e.message, d: e.detail })));
    await page.close();
    return abo;
  };

  const parChemin = await relever('chemin', 3);
  ok('une session expirée est NOMMÉE, avec le chemin où Twitch a renvoyé',
     parChemin.some(e => /renvoyé vers \/login/.test(e.m)), JSON.stringify(parChemin));
  ok('…et l\'onglet fautif est nommé — trois onglets sont relevés, trois verdicts possibles',
     parChemin.some(e => /onglet « \w+ »/.test(e.m)), JSON.stringify(parChemin.map(e => e.m)));
  ok('…et le détail oriente vers la bonne réparation',
     parChemin.some(e => /session expirée/.test(e.d || '')),
     JSON.stringify(parChemin.map(e => e.d)));

  /* ── LE VERDICT DU RELEVÉ ENTIER, ET SON SILENCE ─────────────────────────
     Une première rédaction consignait « onglet vide » pour CHAQUE onglet sans
     carte. L'onglet « mobile » l'est pour presque tout le monde — les
     abonnements achetés dans une application mobile sont rares — et le premier
     rapport reçu portait donc une ligne rouge qui ne disait rien. Un journal
     qu'on apprend à ignorer ne sert plus. Le verdict ne se rend qu'à la fin,
     et seulement quand les deux chiffres se contredisent. */
  ok('un relevé entier sans résultat est signalé QUAND on connaissait des abonnements',
     parChemin.some(e => /relevé complet sans résultat, 3 abonnement\(s\)/.test(e.m)),
     JSON.stringify(parChemin.map(e => e.m)));

  const sansMemoire = await relever('chemin', 0);
  ok('…et il se TAIT pour un compte sans abonnement, où « rien » est la bonne réponse',
     !sansMemoire.some(e => /relevé complet sans résultat/.test(e.m)),
     JSON.stringify(sansMemoire.map(e => e.m)));
  ok('…sans pour autant taire la redirection, qui reste une panne dans les deux cas',
     sansMemoire.some(e => /renvoyé vers \/login/.test(e.m)),
     JSON.stringify(sansMemoire.map(e => e.m)));

  const parOrigine = await relever('opaque');
  ok('un cadre devenu illisible est distingué d\'un cadre qui répond ailleurs',
     parOrigine.some(e => /origine illisible/.test(e.m))
     && !parOrigine.some(e => /renvoyé vers/.test(e.m)), JSON.stringify(parOrigine));
  ok('…et il nomme l\'exception, qui est tout ce qu\'on sait de lui',
     parOrigine.some(e => /SecurityError/.test(e.d || '')),
     JSON.stringify(parOrigine.map(e => e.d)));
}

titre('76. Aperçu — la souris qui sort de la fenêtre par la gauche');
{
  /* RAPPORT D'UTILISATEUR, second écran à GAUCHE : l'aperçu restait affiché
     après que la souris eut quitté la fenêtre, et plus rien ne le refermait
     jamais.

     LA CAUSE EST LE GARDE-FOU LUI-MÊME. Le `mouseleave` d'une carte relit
     `elementFromPoint(lastMouseX, lastMouseY)` pour distinguer un vrai
     départ d'une réconciliation React — Twitch déplace ses cartes, ce qui
     émet un mouseleave parasite alors que la souris n'a pas bougé. Or
     `lastMouse*` ne bouge qu'au rythme des `mousemove` REÇUS, et il n'en
     arrive plus une fois le pointeur hors de la fenêtre : la dernière
     position connue est celle du bord. La barre latérale touchant le bord
     GAUCHE, cette position est encore sur la carte — le garde-fou concluait
     « toujours dessus » et gardait l'aperçu ouvert.

     LES DEUX SENS SONT ÉPROUVÉS ICI, et le second davantage : un correctif
     qui refermerait aussi sur une réconciliation aurait rendu l'aperçu
     inutilisable pendant que Twitch trie sa barre — c'est-à-dire tout le
     temps. */
  const page = await freshTwitch();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    window.__fx = { alpha: { id: 'a', createdAt: h, viewers: 1000, game: 'Art', tags: [] } };
    window.__addCard('alpha', 'Art', '1 k');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 1);
  const carte = await page.evaluate(() => {
    const r = document.querySelector('.side-nav-card').getBoundingClientRect();
    return { x: r.x, y: r.y, w: r.width, h: r.height };
  });
  const centreY = carte.y + carte.h / 2;
  const visible = () => page.evaluate(() =>
    !!document.querySelector('.tse-preview[data-tse-visible="true"]'));
  const survoler = async () => {
    await page.mouse.move(carte.x + carte.w / 2, centreY);
    await attendre(page,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
    return visible();
  };

  ok('un survol ouvre bien l\'aperçu — sans quoi le reste ne prouverait rien',
     await survoler(), 'aperçu non ouvert au survol');

  /* LA CONDITION EXACTE DU DÉFAUT, ET ELLE SE VÉRIFIE — sans quoi l'assertion
     qui suit passerait sans rien prouver. Ce qui piège le garde-fou n'est pas
     la coordonnée 0 : c'est que la DERNIÈRE position reçue soit encore sur la
     carte. En production la barre touche le bord gauche, donc c'est le cas ;
     dans le harnais la carte commence à quelques pixels du bord, et viser le
     bord littéral aurait produit un test vert et vide. On part donc du dernier
     point INTÉRIEUR à la carte, ce qui reproduit l'état exact du défaut : plus
     aucun mousemove ne viendra, et `lastMouse*` reste sur la carte. */
  const dernierPoint = Math.round(carte.x + 2);
  const surLaCarte = await page.evaluate(([x, y]) => {
    const u = document.elementFromPoint(x, y);
    const c = document.querySelector('.side-nav-card');
    return !!(u && c.contains(u));
  }, [dernierPoint, centreY]);
  ok('…et la dernière position avant la sortie est bien SUR la carte (la condition du défaut)',
     surLaCarte === true, 'sans cela le garde-fou refermerait de lui-même : test vide');

  await page.mouse.move(dernierPoint, centreY);
  await page.mouse.move(-8, centreY);
  await wait(page, 400);
  ok('la souris sortie de la fenêtre referme l\'aperçu',
     (await visible()) === false, 'aperçu resté ouvert après la sortie');

  /* ── L'AUTRE SENS : ce qui ne doit PAS refermer ────────────────────────── */
  ok('un nouveau survol rouvre normalement', await survoler(), 'aperçu non rouvert');
  await page.evaluate(() => {
    // Détache puis rattache la carte sous une souris IMMOBILE : c'est ce que
    // fait React, et c'est ce que le garde-fou existe pour absorber.
    const c = document.querySelector('.side-nav-card');
    c.parentElement.appendChild(c);
  });
  await wait(page, 400);
  ok('…et une carte détachée puis rattachée sous une souris immobile ne le referme pas',
     (await visible()) === true, 'l\'anti-fantôme a été cassé par le correctif');

  await page.close();
}

titre('77. Firefox — le panneau sous un `chrome.*` qui ne rend pas de promesse');
{
  /* DEUX NAMESPACES QUI NE SE COMPORTENT PAS PAREIL. Firefox expose
     `browser.*` (promesses) ET `chrome.*` (façade de compatibilité, à
     rappels) ; Chrome n'expose que `chrome.*`, promesses comprises depuis MV3.

     Le panneau appelait `chrome.runtime.sendMessage(…).catch(…)` et
     `chrome.tabs.query(…).then(…)`. Si la façade de Firefox ne rend rien, ces
     deux lignes lèvent une TypeError sur `undefined`, et le panneau n'affiche
     RIEN — pas une section, pas un rapport, pas même un message d'erreur,
     puisque c'est le transport qui casse avant tout affichage.

     JE N'AI PAS PU L'EXÉCUTER : il n'y a pas de Firefox sur cette machine, et
     une extension ne se charge pas dans un navigateur absent. Ce scénario ne
     prétend donc pas dire ce que Firefox FAIT — il exige que le panneau tienne
     dans l'hypothèse la PIRE, celle d'une façade qui ne rend rien. Si Firefox
     est plus généreux, le test reste vrai ; s'il ne l'est pas, il l'était déjà.
     Le code ne dépend plus de la réponse, et c'est tout l'objet. */
  const messages = JSON.parse(
    readFileSync(join(ICI, '..', '_locales', 'fr', 'messages.json'), 'utf8'));

  const stubFirefox = (msgs) => {
    const T = (k, sub) => {
          const m = msgs[k] ? msgs[k].message : '';
          if (sub === undefined || sub === null) return m;
          const args = Array.isArray(sub) ? sub : [sub];
          return String(m).replace(/\$(\d)/g,
            (t, i) => (args[i - 1] === undefined ? t : String(args[i - 1])));
        };
    const paquet = { ok: true, data: {
      colonnes: ['login', 'score', 'visits', 'last'],
      lignes: [{ login: 'alpha', score: 3.5, visits: 12, last: Date.now() }],
      resume: { chaines: 1, sondes: 1, critiquesCassees: 0, casse: false,
                mesures: 0, evenements: 0, bascules: 0, categories: 0,
                actif: false, complete: false, abonnees: 0 } } };
    /* Le namespace de Firefox : celui dont les promesses sont garanties. */
    const promesses = {
      i18n: { getMessage: T, getUILanguage: () => 'fr' },
      tabs: { query: () => Promise.resolve([{ id: 1 }]) },
      runtime: {
        getManifest: () => ({ version: '9.9.9',
                              background: { scripts: ['background.js'] },
                              action: { default_popup: 'panneau.html' } }),
        sendMessage: (m) => {
          if (m.type === 'tse-panneau-etat') {
            return Promise.resolve({ ok: true, ponts: [1], enVol: 0, workerMs: 12 });
          }
          if (m.rapport) {
            return Promise.resolve({ ok: true, data: {
              genere: Date.now(), ancienneteMs: 1000,
              demarrage: { etape: 'pret', dureeMs: 42, etapes: [{ etape: 'pret', ms: 42 }] },
              page: { chemin: '/x', cachee: false, sidebar: true, cartes: 1 },
              langue: { interface: 'fr', page: 'fr' }, mode: { global: false },
              sondes: [], compteurs: { visites: 1 },
              relevesAbonnements: { horodatage: 0, enAttente: false },
              reseau: { pauseGqlMs: 0, appels: 3, echecs: 0 },
              retards: { medianeMs: null, p90Ms: null },
              erreurs: [], bilanErreurs: { total: 0, sources: [] },
              global: { enabled: false },
              journaux: { verrous: [], cycles: [], apercu: [] } } });
          }
          return Promise.resolve(paquet);
        },
      },
    };
    window.browser = promesses;
    /* LA FAÇADE `chrome` DE FIREFOX, dans l'hypothèse pessimiste : elle
       fonctionne par RAPPEL et ne rend rien. C'est précisément ce sur quoi le
       panneau s'appuyait, et ce dont il ne doit plus dépendre. */
    window.chrome = {
      i18n: promesses.i18n,
      runtime: {
        getManifest: promesses.runtime.getManifest,
        sendMessage: (m, cb) => { promesses.runtime.sendMessage(m).then((r) => cb && cb(r)); },
      },
      tabs: { query: (q, cb) => { promesses.tabs.query(q).then((t) => cb && cb(t)); } },
    };
  };

  const page = await browser.newPage({ viewport: { width: 760, height: 580 } });
  const plantages = [];
  page.on('pageerror', (e) => plantages.push(e.message));
  await page.addInitScript(stubFirefox, messages);
  await page.goto(pathToFileURL(join(ICI, '..', 'panneau.html')).href);
  await attendre(page, () => document.querySelectorAll('.rail-item').length > 0, 5000);

  ok('le panneau se construit — aucune exception au chargement',
     plantages.length === 0, JSON.stringify(plantages).slice(0, 200));
  /* LA SECTION D'ACCUEIL NE TRAVERSE PAS LE PONT — c'est le mode d'emploi, et
     il s'affiche justement sans lui. Pour éprouver le transport il faut donc
     demander une section qui l'emprunte, ce qui rend d'ailleurs l'assertion
     plus franche qu'avant : elle nomme ce qu'elle vérifie au lieu de compter
     sur l'ordre du rail. */
  await page.evaluate(() => [...document.querySelectorAll('.rail-item')]
    .find(b => b.dataset.id === 'scores').click());
  await attendre(page, () => document.querySelectorAll('.tableau tbody tr').length > 0, 5000);
  const lignes = await page.evaluate(() =>
    document.querySelectorAll('.tableau tbody tr').length);
  ok('…et une section de données affiche ses lignes, donc le transport a répondu',
     lignes > 0, `${lignes} lignes`);

  await page.evaluate(() => document.getElementById('btn-rapport').click());
  await attendre(page, () => /ENVIRONNEMENT/.test(
    document.getElementById('rapport-zone').value), 6000);
  const texte = await page.evaluate(() => document.getElementById('rapport-zone').value);
  ok('…et le rapport se construit aussi, worker compris',
     /ENVIRONNEMENT/.test(texte) && /worker — ponts\s+1/.test(texte),
     JSON.stringify((texte.match(/worker — ponts.*/) || [])[0]));
  ok('…en lisant le manifeste par le namespace disponible (forme Firefox du fond)',
     /fond \/ background\s+scripts/.test(texte),
     JSON.stringify((texte.match(/fond \/ background.*/) || [])[0]));

  await page.close();
}

titre('78. Aperçu — la frise des catégories traversées');
{
  /* CE QUE CE BLOC SAIT ET QUE TWITCH NE MONTRE PAS. Les chapitres d'un
     stream n'existent, chez Twitch, que sur le VOD et après coup. Pour un live
     EN COURS, la suite des catégories traversées n'est affichée nulle part —
     alors que le pipeline la voit passer toutes les 30 s et la jetait.

     LA FRISE NE SAIT QUE CE QU'ELLE A VU, et c'est le point le plus délicat de
     l'affichage : un onglet ouvert à la troisième heure d'un live ignore les
     deux premières. Présenter le premier segment observé comme le début du
     live serait une invention. On connaît l'heure de départ du stream, donc la
     part non observée est MESURÉE et dessinée à sa vraie proportion. */
  const page = await freshTwitch();
  const DEBUT = Date.now() - 30 * 60_000;          // live commencé il y a 30 min
  await page.evaluate((d) => {
    window.__fx = { alpha: { id: 'a', createdAt: new Date(d).toISOString(),
                             viewers: 1000, game: 'Just Chatting', tags: [] } };
    window.__addCard('alpha', 'Just Chatting', '1 k');
  }, DEBUT);
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 1);

  const survoler = async () => {
    await hoverLogin(page, 'alpha');
    await attendre(page,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
  };
  const relacher = async () => {
    await page.evaluate(() => {
      const c = document.querySelector('.side-nav-card');
      c.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
    });
    await attendre(page,
      () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);
  };
  // Bascule de catégorie : on change la fixture, on force un relevé, et on
  // attend que la CARTE porte la nouvelle catégorie — pas une durée fixe, qui
  // mentirait dès que la machine est chargée.
  const basculer = async (jeu) => {
    await page.evaluate((j) => { window.__fx.alpha.game = j; window.tse.rescan(); }, jeu);
    await attendre(page,
      (j) => document.querySelector('.side-nav-card')?.dataset.tseCategory === j, 8000, jeu);
  };
  const frise = () => page.evaluate(() => {
    const bloc = document.querySelector('.tse-preview__frise');
    if (!bloc) return null;
    return {
      parts: [...bloc.querySelectorAll('.tse-preview__frise-part')].map(p => ({
        poids: parseFloat(p.style.flex),
        inconnu: p.classList.contains('tse-preview__frise-part--inconnu'),
      })),
      lignes: [...bloc.querySelectorAll('.tse-preview__frise-ligne')].map(l => ({
        nom: l.querySelector('.tse-preview__frise-nom').textContent,
        duree: l.querySelector('.tse-preview__frise-duree')?.textContent || '',
        inconnu: l.classList.contains('tse-preview__frise-ligne--inconnu'),
        encours: l.classList.contains('tse-preview__frise-ligne--encours'),
      })),
      barreCachee: bloc.querySelector('.tse-preview__frise-barre')
                       .getAttribute('aria-hidden') === 'true',
    };
  });

  /* ── LE CAS OÙ LA FRISE N'A RIEN À DIRE ──────────────────────────────────
     Ce seuil a bougé DEUX fois, et les deux mouvements viennent de rapports
     d'utilisateur — c'est-à-dire de la seule source qui puisse trancher.

     D'abord un basculement était EXIGÉ. « Je n'ai pas la nouveauté », cinq
     minutes après l'installation : une fonctionnalité qui peut rester
     invisible des heures ne se distingue pas d'une fonctionnalité cassée.

     Puis le seuil est tombé à un segment, et l'affichage est devenu ceci :
     « non observé 2h52 / Discussions 3m ». Deuxième rapport : « il faut pas
     qu'on puisse avoir la partie non observé ». Il avait raison — cette
     barre-là ne dit rien du LIVE, elle dit que nous regardons depuis trois
     minutes.

     LE POINT D'ÉQUILIBRE est donc « avoir quelque chose à dire », et non
     « avoir vu un basculement » : deux segments, OU un prélude venu du VOD,
     OU un live vu depuis son début. Ce que l'on ne fait PAS, c'est prolonger
     la catégorie courante jusqu'au départ du stream pour faire disparaître le
     hachuré : un streamer qui a basculé cinq minutes avant qu'on ouvre Twitch
     se verrait attribuer sept heures d'une catégorie qu'il vient de prendre. */
  await survoler();
  ok('un live commencé avant nous, dont on ne connaît qu\'une catégorie, se tait',
     (await frise()) === null,
     'la frise a montré une barre presque entièrement hachurée');
  await relacher();

  /* Deux durées franchement différentes, pour que la proportion se mesure. */
  await basculer('Hades II');
  await wait(page, 1200);
  await basculer('Overwatch');
  await wait(page, 120);
  await survoler();

  const f = await frise();
  ok('après deux basculements, la frise apparaît',
     f !== null && f.lignes.length > 0, JSON.stringify(f));
  ok('…avec les trois catégories traversées, dans l\'ordre du temps',
     f.lignes.filter(l => !l.inconnu).map(l => l.nom).join(' → ')
       .includes('Hades II') && f.lignes.length === 4,
     JSON.stringify(f.lignes.map(l => l.nom)));
  ok('…la dernière étant marquée « en cours »',
     f.lignes[f.lignes.length - 1].encours === true
     && f.lignes.filter(l => l.encours).length === 1,
     JSON.stringify(f.lignes.map(l => [l.nom, l.encours])));

  /* ── L'AVEU À L'ÉCHELLE ─────────────────────────────────────────────────
     Trente minutes de live avant notre première vue : le segment hachuré doit
     exister ET peser trente minutes, pas un ornement de taille fixe. C'est ce
     qui distingue un aveu d'une décoration. */
  ok('la part NON OBSERVÉE est dessinée, et à sa taille réelle',
     f.parts[0].inconnu === true && f.parts[0].poids > 25 * 60_000
     && f.parts[0].poids < 35 * 60_000,
     JSON.stringify(f.parts[0]));
  ok('…et elle est nommée dans la liste, pas seulement dessinée',
     f.lignes[0].inconnu === true && /^\d+h\d\d$|^\d+m$/.test(f.lignes[0].duree),
     JSON.stringify(f.lignes[0]));
  /* LA PROPORTION, ÉPROUVÉE SUR DES DURÉES QU'ON A IMPOSÉES. Hadès II a duré
     1 200 ms de test, Overwatch 120 : le rapport doit se retrouver dans les
     largeurs, sans quoi la barre serait un ornement plutôt qu'une mesure.

     POURQUOI 1 200 ET NON 450, qui suffisait avant la 3.95 : le dernier
     segment est « en cours », donc son poids se calcule AU RENDU — et le rendu
     n'arrive plus qu'après le délai d'intention. Overwatch pèse désormais ses
     120 ms plus les 200 du délai, soit près du triple de ce qu'on croyait lui
     donner. L'écart imposé doit rester franc devant cette latence, sinon c'est
     elle que l'assertion mesure. La
     première rédaction de cette assertion attendait « le plus long est le
     premier » — c'était faux de MON propre test : le premier segment ne dure
     que le temps qui sépare la première observation du premier basculement,
     soit 75 ms ici. L'assertion mesurait mal ce que le test faisait. */
  ok('les segments pèsent leur durée : Hadès II tient plus du triple d\'Overwatch',
     f.parts.length === 4 && f.parts[2].poids > f.parts[3].poids * 2.5,
     JSON.stringify(f.parts.map(p => Math.round(p.poids))));
  /* La barre porte la couleur, la liste porte le sens. Une barre annoncée aux
     lecteurs d'écran ferait lire quatre div vides. */
  ok('la barre est décorative — c\'est la liste qui porte l\'information',
     f.barreCachee === true, 'la barre n\'est pas aria-hidden');

  /* ── CANONIQUE CONTRE LIBELLÉ, DANS LES DEUX SENS ────────────────────────
     Twitch rend deux noms pour une catégorie : `name` (canonique, stable) et
     `displayName` (traduit, variable). Comparer les LIBELLÉS ferait naître un
     faux segment au premier changement de langue de l'interface ; comparer
     seulement les canoniques sans mémoriser le libellé afficherait des noms
     anglais dans une interface française. Les deux sens comptent. */
  await relacher();
  const langue = await page.evaluate(() => (window.__lastAcceptLanguage || 'en').slice(0, 2));
  await page.evaluate((l) => {
    // MÊME canonique, libellé qui change : Twitch se met à traduire.
    window.__i18nCats['Overwatch'] = { [l]: 'Surveillance' };
    window.tse.rescan();
  }, langue);
  await wait(page, 400);
  await survoler();
  const f2 = await frise();
  ok('un LIBELLÉ qui change ne crée pas de segment — la comparaison est canonique',
     f2.lignes.length === 4, JSON.stringify(f2.lignes.map(l => l.nom)));
  ok('…mais c\'est bien le libellé traduit qui s\'affiche',
     f2.lignes[f2.lignes.length - 1].nom === 'Surveillance',
     JSON.stringify(f2.lignes[f2.lignes.length - 1].nom));

  await relacher();
  await page.evaluate((l) => {
    // DEUX canoniques différents, un SEUL libellé : le segment doit naître
    // quand même. C'est le test qui échouerait si l'on comparait les libellés.
    window.__i18nCats['Fortnite'] = { [l]: 'Surveillance' };
  }, langue);
  await basculer('Fortnite');
  await survoler();
  const f3 = await frise();
  ok('deux catégories qui portent le MÊME libellé restent deux segments',
     f3.lignes.length === 5
     && f3.lignes.slice(-2).every(l => l.nom === 'Surveillance'),
     JSON.stringify(f3.lignes.map(l => l.nom)));

  /* ── UNE NOUVELLE SESSION REPART DE ZÉRO ─────────────────────────────────
     L'identifiant de stream change à chaque redémarrage, et garder la frise
     ferait porter au nouveau live les durées de l'ancien.

     LE DÉCOR A DÛ CHANGER, ET C'EST LE PROPRE DE CE SCÉNARIO DE LE DIRE.
     L'identifiant change AUSSI à chaque reprise après coupure, et ce n'est
     donc plus lui qui décide : c'est l'ORIGINE du direct (cf. scénario 95).
     La rédaction d'avant se contentait de changer l'identifiant — ce qui
     décrit aujourd'hui une reprise, dont la frise est justement CONSERVÉE.
     Pour éprouver une vraie nouvelle session il faut donc une vraie coupure :
     on éteint la chaîne au-delà de la borne de reprise, puis on la rallume. */
  await relacher();
  await page.evaluate(() => {
    window.__avant = { ...window.__fx.alpha };
    window.__fx.alpha = null;
    window.tse.rescan();
  });
  await wait(page, 3400);          // au-delà de RECONNECT_GAP_MAX
  await page.evaluate(() => {
    window.__fx.alpha = { ...window.__avant, sid: 's-neuve',
                          createdAt: new Date().toISOString(), game: 'Just Chatting' };
    window.tse.rescan();
  });
  await attendre(page,
    () => document.querySelector('.side-nav-card')?.dataset.tseCategory === 'Just Chatting', 8000);
  await survoler();
  const f4 = await frise();
  ok('une nouvelle session repart d\'une seule catégorie',
     f4 !== null && f4.lignes.length === 1 && f4.lignes[0].encours === true,
     JSON.stringify(f4 && f4.lignes.map(l => l.nom)));
  /* Et sans part hachurée : le stream vient de commencer, on l'a vu depuis le
     début, il n'y a rien à avouer. C'est le seul cas où la frise est complète. */
  ok('…et sans part non observée, puisqu\'on l\'a vue depuis son début',
     f4.parts.length === 1 && f4.parts[0].inconnu === false,
     JSON.stringify(f4.parts));

  /* ── CE QUE LA 4.3 A RETOURNÉ, ET POURQUOI ───────────────────────────────
     Cette assertion disait l'inverse : une catégorie inconnue EFFAÇAIT la
     frise, « oubliée plutôt que remplie de trous ». Le raisonnement tenait sur
     l'instant et manquait le cas qui compte — un direct qui REPREND n'a pas
     encore de catégorie pendant les premières secondes, et le passé qu'on
     venait de préserver partait avec. Deux signalements l'ont montré : « il
     avait une frise avant, et il n'en a plus du tout quand il a repris », et
     une chaîne qui n'annonce jamais de catégorie n'avait jamais de frise.

     LE SILENCE NE DÉTRUIT PLUS, IL S'ABSTIENT : on n'ouvre pas de segment sur
     une catégorie qu'on ne connaît pas — se taire n'est pas inventer — mais ce
     qui est déjà observé reste. Le décor pose deux catégories AVANT le trou,
     sans quoi la frise se tairait pour une autre raison (un segment unique ne
     fait pas une frise) et l'assertion ne prouverait rien. */
  await relacher();
  await page.evaluate(() => { window.__fx.alpha.game = 'VALORANT'; window.tse.rescan(); });
  await wait(page, 600);
  await page.evaluate(() => { window.__fx.alpha.game = null; window.tse.rescan(); });
  await wait(page, 600);
  await survoler();
  const f5 = await frise();
  ok('une catégorie inconnue laisse la frise en place au lieu de la détruire',
     f5 !== null && f5.lignes.length === 2
     && f5.lignes.some(l => /VALORANT/.test(l.nom)),
     JSON.stringify(f5 && f5.lignes.map(l => l.nom)));

  await page.close();
}

titre('79. Aperçu — le passé du live, comblé par les chapitres du VOD');
{
  /* « FAUDRA LE CONNAÎTRE MÊME SI ON N'ÉTAIT PAS SUR TWITCH. » La frise ne
     savait que ce qu'elle avait vu, et la capture d'un utilisateur le montrait
     crûment : « non observé 6h04 » écrasant deux segments de deux minutes.

     Il existe une source, et une seule. Twitch n'expose nulle part
     l'historique de catégories d'un stream EN COURS — mais si la chaîne
     archive ses diffusions, le VOD existe dès le début et gagne un « moment »
     à chaque changement de jeu.

     CE SCÉNARIO NE PROUVE PAS QUE LA REQUÊTE EST JUSTE. Elle n'a jamais été
     exécutée contre le vrai Twitch : la machine où elle a été écrite n'a pas
     accès à twitch.tv. Ce qu'il prouve, c'est que la FUSION est correcte et
     que TOUT échec retombe sans rien casser — y compris celui qui arriverait
     si la requête était fausse. C'est la seule garantie qu'on puisse donner
     sans exécuter, et c'est celle qui compte : au pire, l'utilisateur retrouve
     la frise d'aujourd'hui. */
  const page = await freshTwitch();
  const H = 60 * 60_000;
  const DEBUT = Date.now() - 3 * H;
  await page.evaluate((d) => {
    const iso = new Date(d).toISOString();
    const mk = (g) => ({ id: 'x', createdAt: iso, viewers: 900, game: g, tags: [] });
    window.__fx = { alpha: mk('Overwatch'), beta: mk('Overwatch'), gamma: mk('Overwatch'),
                    epsilon: mk('Overwatch'), zeta: mk('Overwatch'), eta: mk('Overwatch'),
                    theta: mk('Overwatch'), iota: mk('Overwatch'), kappa: mk('Overwatch'),
                    lambda: mk('Overwatch'),
                    delta: { id: 'x', createdAt: new Date().toISOString(),
                             viewers: 900, game: 'Overwatch', tags: [] } };
    window.__vod = {
      // Trois chapitres : le live a commencé sur Discussions.
      alpha: { createdAt: iso, chapitres: [
        { pos: 0, jeu: 'Just Chatting' },
        { pos: 24 * 60_000, jeu: 'Hades II' },
        { pos: 131 * 60_000, jeu: 'Overwatch' }] },
      // Ce que rendrait un champ que le schéma ne connaît pas.
      beta: 'erreur',
      // Une chaîne qui n'archive pas ses diffusions.
      gamma: 'sansvod',
      /* Un chapitre DANS LE FUTUR par rapport à notre observation. Ce n'est
         pas une lubie : la base de temps du VOD peut être postérieure au
         départ du stream, et les positions se traduisent alors en instants
         plus tardifs que la réalité. Sans garde, notre segment observé
         s'ajouterait APRÈS un chapitre qui commence plus tard que lui — une
         frise qui remonte le temps. */
      epsilon: { createdAt: iso, chapitres: [
        { pos: 0, jeu: 'Just Chatting' },
        { pos: 4 * 60 * 60_000, jeu: 'Hades II' }] },
      /* UN VOD QUI COUVRE LE LIVE ET NE PORTE AUCUN CHANGEMENT. C'est le cas
         que le premier rapport d'utilisateur a révélé — huit sur dix-neuf — et
         ce n'est pas un silence : les chapitres marquent les CHANGEMENTS, donc
         leur absence sur un enregistrement complet atteste que la catégorie
         n'a pas bougé. */
      zeta: { createdAt: iso, chapitres: [] },
      /* Le même, MAIS l'enregistrement a démarré bien après le live. Il ne
         couvre pas le début, donc il n'atteste rien de ce début. */
      eta: { createdAt: new Date(Date.now() - 10 * 60_000).toISOString(), chapitres: [] },
      // theta, iota et kappa n'exposent PAS archiveVideo : le repli s'en charge.
      theta: 'sansvod',
      iota: 'sansvod',
      kappa: 'sansvod',
      lambda: 'sansvod',
    };
    /* LE REPLI. `archiveVideo` a rendu null pour ces deux-là — ce qui peut
       vouloir dire « la chaîne n'archive pas », définitif, ou seulement que
       l'enregistrement en cours n'est pas exposé par CE champ. La seconde
       porte tranche : theta a bien une archive qui couvre son live, iota n'en
       a qu'une d'hier, qui ne prouve rien. */
    window.__vodRecent = {
      theta: { createdAt: iso, lengthSeconds: 3 * 3600, chapitres: [
        { pos: 0, jeu: 'Just Chatting' },
        { pos: 60 * 60_000, jeu: 'Hades II' }] },
      /* iota : le VOD d'il y a trente heures, long de quatre. Il s'est terminé
         vingt-six heures avant que ce live ne commence — aucun recouvrement,
         rejet juste. C'est le cas que la valeur absolue attrapait déjà. */
      iota: { createdAt: new Date(d - 30 * 60 * 60_000).toISOString(),
              lengthSeconds: 4 * 3600, chapitres: [] },
      /* lambda : LE CAS QUE LA VALEUR ABSOLUE JETAIT. L'enregistrement a
         commencé quarante minutes AVANT ce live et tourne toujours : c'est un
         stream qui a reconnecté, `stream.createdAt` est reparti, le VOD non.
         Il recouvre donc le live, et ses chapitres nous regardent. Le rapport
         d'un utilisateur a montré dix rejets de ce type, dont un à −39 min. */
      lambda: { createdAt: new Date(d - 40 * 60_000).toISOString(),
                lengthSeconds: 4 * 3600, chapitres: [
                  { pos: 0, jeu: 'Just Chatting' },
                  { pos: 20 * 60_000, jeu: 'Hades II' },
                  { pos: (40 + 90) * 60_000, jeu: 'Overwatch' }] },
      // kappa : rien du tout. La chaîne n'archive pas, un point c'est tout.
    };
    for (const l of ['alpha', 'beta', 'gamma', 'delta', 'epsilon', 'zeta', 'eta',
                     'theta', 'iota', 'kappa', 'lambda']) {
      window.__addCard(l, 'Overwatch', '900');
    }
  }, DEBUT);
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 11);

  const survoler = async (login) => {
    await hoverLogin(page, login);
    await attendre(page,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
  };
  const relacher = async (login) => {
    await page.evaluate((l) => {
      [...document.querySelectorAll('.side-nav-card')]
        .find(c => c.dataset.tseLogin === l)
        ?.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
    }, login);
    await attendre(page,
      () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);
  };
  const lignes = () => page.evaluate(() =>
    [...document.querySelectorAll('.tse-preview__frise-ligne')].map(l => ({
      nom: l.querySelector('.tse-preview__frise-nom').textContent,
      duree: l.querySelector('.tse-preview__frise-duree')?.textContent || '',
      inconnu: l.classList.contains('tse-preview__frise-ligne--inconnu'),
    })));
  const appelsVod = () => page.evaluate(() =>
    window.__calls.filter(c => (c.names || []).includes('TseVodChapters')).length);
  const bilan = () => page.evaluate(() => window.tse.panneau.rapport().reseau.chapitres);

  /* ── LE CAS QUI MOTIVE TOUT ──────────────────────────────────────────────── */
  await survoler('alpha');
  await attendre(page,
    () => document.querySelectorAll('.tse-preview__frise-ligne').length >= 3, 8000);
  const a = await lignes();
  ok('les chapitres du VOD comblent le passé : la frise part du début du live',
     a.length === 3 && !a.some(l => l.inconnu),
     JSON.stringify(a.map(l => l.nom + ' ' + l.duree)));
  /* Défensive : une assertion qui LÈVE au lieu d'échouer emporte le banc
     entier et masque les scénarios suivants. C'est arrivé ici même. */
  ok('…dans l\'ordre, avec les durées que les positions imposent',
     a.length === 3 && a[0].duree === '24m' && a[1].duree === '1h47',
     JSON.stringify(a.map(l => [l.nom, l.duree])));

  /* ── LA FUSION : CE QUE LES CHAPITRES NE SAVENT PAS ENCORE ────────────────
     Twitch met un moment à publier un chapitre. Un basculement observé APRÈS
     la récupération doit s'ajouter — sans quoi la frise serait figée à l'état
     du VOD, en retard sur ce qu'on voit. */
  await relacher('alpha');
  await page.evaluate(() => { window.__fx.alpha.game = 'Minecraft'; window.tse.rescan(); });
  await attendre(page, () => [...document.querySelectorAll('.side-nav-card')]
    .find(c => c.dataset.tseLogin === 'alpha')?.dataset.tseCategory === 'Minecraft', 8000);
  await survoler('alpha');
  await attendre(page,
    () => document.querySelectorAll('.tse-preview__frise-ligne').length >= 4, 8000);
  const b = await lignes();
  ok('un basculement observé APRÈS les chapitres s\'ajoute à leur suite',
     b.length === 4 && b[3].nom === 'Minecraft' && !b.some(l => l.inconnu),
     JSON.stringify(b.map(l => l.nom)));

  /* ── LES TROIS ÉCHECS, ET LE SEUL COMPORTEMENT ADMIS : NE RIEN CASSER ─────
     Aucun d'eux ne doit produire d'affichage faux. Comme la chaîne n'a qu'une
     catégorie observée et que son live a commencé avant nous, le repli correct
     est le SILENCE — le même que sans chapitres du tout. Ce qui doit parler,
     en revanche, ce sont les compteurs : c'est par eux, et par eux seuls,
     qu'on saura ce que Twitch a répondu. */
  await relacher('alpha');
  await survoler('beta');
  await wait(page, 900);
  ok('une requête REFUSÉE par le schéma ne produit aucun affichage faux',
     (await lignes()).length === 0, JSON.stringify(await lignes()));
  const journal = await page.evaluate(() => window.tse.panneau.rapport().erreurs
    .filter(e => e.source === 'gql' || e.source === 'chapitres').map(e => e.message));
  ok('…et elle est CONSIGNÉE — c\'est ainsi qu\'on saura si la requête est fausse',
     journal.some(m => /erreurs GraphQL/.test(m)), JSON.stringify(journal));

  await relacher('beta');
  await survoler('gamma');
  await wait(page, 900);
  ok('une chaîne qui n\'archive pas ses diffusions ne produit rien non plus',
     (await lignes()).length === 0, JSON.stringify(await lignes()));
  /* ── LE COMPTEUR, QUI EST LA VRAIE LEÇON DE CE SCÉNARIO ───────────────────
     Le premier rapport reçu après la mise en service portait « ERREURS (0) »
     et « echecs 0 ». On ne pouvait donc PAS savoir si la requête avait été
     envoyée, ni ce qu'elle avait rendu — trois causes possibles, trois
     réparations opposées, aucun moyen de choisir. Ces compteurs ferment cette
     question, et ils ne vont PAS au journal d'erreurs : une chaîne qui
     n'archive pas ses diffusions est un cas ordinaire, pas un défaut. C'est la
     leçon de l'onglet « mobile », appliquée avant de la répéter. */

  /* ── LA REQUÊTE QU'ON NE FAIT PAS ────────────────────────────────────────
     Une chaîne suivie depuis le début de son live n'a rien à combler. Une
     requête qui n'apprend rien est une requête de trop, et c'est la seule
     assertion qui empêche ce module de doubler le trafic de l'aperçu. */
  await relacher('gamma');
  const avant = await appelsVod();
  await survoler('delta');
  await wait(page, 900);
  ok('aucune requête pour un live vu depuis son début : rien à combler',
     (await appelsVod()) === avant, `${await appelsVod()} appels contre ${avant}`);

  /* ── LE VOD QUI ATTESTE LA CONTINUITÉ ────────────────────────────────────
     C'est la réponse au deuxième rapport : « j'aimerais quand même avoir cette
     fonctionnalité même s'il y a une seule catégorie durant le stream ». On ne
     l'obtient PAS en prolongeant la catégorie courante par hypothèse — on
     l'obtient parce que l'enregistrement, qui couvre tout le live, ne porte
     aucun changement de jeu. C'est une preuve, pas une supposition. */
  await relacher('epsilon');
  await survoler('zeta');
  await attendre(page,
    () => document.querySelectorAll('.tse-preview__frise-ligne').length >= 1, 8000);
  const z = await lignes();
  ok('un VOD complet SANS changement fait remonter la frise au début du live',
     z.length === 1 && z[0].nom === 'Overwatch' && !z[0].inconnu,
     JSON.stringify(z));
  ok('…et la durée couvre le live entier, pas notre fenêtre d\'observation',
     /^3h0\d$/.test(z[0].duree.split(' ')[0]), JSON.stringify(z[0].duree));

  /* ── ET CELUI QUI N'ATTESTE RIEN ─────────────────────────────────────────
     L'enregistrement a démarré dix minutes après le live : l'absence de
     chapitre ne dit rien des trois heures précédentes. Sans cette garde, la
     preuve deviendrait une hypothèse déguisée. */
  await relacher('zeta');
  await survoler('eta');
  await wait(page, 900);
  ok('un VOD démarré APRÈS le live n\'atteste rien, et la frise se tait',
     (await lignes()).length === 0, JSON.stringify(await lignes()));

  /* ── LA SECONDE PORTE A ÉTÉ RETIRÉE, ET CE QUI LA COUVRAIT AVEC ────────
     QUATRE SOUS-TESTS VIVAIENT ICI — « theta » (le repli prend le relais),
     « iota » (l'archive d'hier n'est pas prise pour celle du live), « kappa »
     (aucune archive du tout) et « lambda » (un enregistrement antérieur qui
     RECOUVRE le live est retenu). Ils éprouvaient le repli par la liste des
     archives, que la 4.17.1 a retiré : quatre rapports de terrain, vingt et
     une tentatives, ZÉRO résultat, et jamais de justesse — l'archive trouvée
     était toujours celle d'un autre jour.

     ON LES RETIRE PLUTÔT QUE DE LES LAISSER VERDIR POUR RIEN. Deux d'entre
     eux — « iota » et « kappa » — passaient encore après le retrait, mais
     pour la mauvaise raison : ils assertent qu'on n'affiche RIEN, ce qui est
     désormais vrai sans qu'aucune garde n'ait à jouer. Une assertion qui ne
     peut plus échouer ne dit plus rien, et en garder deux de cette sorte
     apprendrait à leur faire confiance à tort.

     CE QUI N'EST DONC PLUS COUVERT, ET QUI SE DIT : le cas d'un stream ayant
     RECONNECTÉ dont l'enregistrement, commencé avant le live, le recouvre.
     Sans le repli, la frise s'en tient à `archiveVideo` — le chemin que les
     sous-tests « alpha » à « eta » ci-dessus éprouvent au complet. Si le
     besoin revenait, c'est ce paragraphe qu'il faudrait défaire, et les
     décors sont restés dans le harnais pour ça. */

  /* ── UNE FRISE NE REMONTE PAS LE TEMPS ──────────────────────────────────
     Le dernier chapitre est postérieur à notre propre observation. Notre
     segment ne doit PAS s'ajouter derrière lui : il commencerait avant ce qui
     le précède, et la durée du chapitre serait négative. La frise doit donc
     s'en tenir aux chapitres. */
  await relacher('eta');
  await survoler('epsilon');
  await attendre(page,
    () => document.querySelectorAll('.tse-preview__frise-ligne').length >= 2, 8000);
  const e = await lignes();
  ok('un segment observé ANTÉRIEUR au dernier chapitre n\'est pas ajouté',
     e.length === 2 && e[1].nom === 'Hades II'
     && !e.some(l => l.nom === 'Overwatch'),
     JSON.stringify(e.map(l => l.nom)));
  await relacher('epsilon');

  /* ── LES COMPTEURS, LUS QUAND TOUS LES CAS SONT PASSÉS ───────────────────
     Lus trop tôt, ils ne portent que sur les premiers survols — et une
     assertion qui mesure un état incomplet ne mesure rien. Ici, les sept
     issues ont toutes été rencontrées.

     ILS S'ADDITIONNENT, et ce n'était pas le cas : un rapport a affiché
     « demandes 16 » et des issues qui totalisaient 23, parce que `sansMoment`
     était incrémenté PUIS `continus` sur le même appel. Un lecteur qui
     additionne des compteurs et tombe à côté cesse, à juste titre, de leur
     faire confiance. (Elle valait « demandes moins les replis » tant que le
     repli existait ; il a été retiré, mesuré inutile sur vingt et une
     tentatives.) */
  const b1 = await bilan();
  ok('le rapport dit combien de fois les chapitres ont été DEMANDÉS',
     b1.demandes >= 6, JSON.stringify(b1));
  ok('…et sépare les issues : servies, attestées, sans VOD, sans stream',
     b1.servis >= 1 && b1.continus >= 1 && b1.sansVod >= 1
     && Object.prototype.hasOwnProperty.call(b1, 'sansStream'),
     JSON.stringify(b1));
  ok('…les sept issues sont exclusives, et leur somme vaut le nombre de demandes',
     b1.servis + b1.continus + b1.sansMoment + b1.inexploitables
     + b1.sansVod + b1.sansStream + b1.reseau === b1.demandes, JSON.stringify(b1));
  /* ── LES QUATRE ASSERTIONS DU REPLI SONT PARTIES AVEC LUI ─────────────
     Elles tenaient ses compteurs : tenté/servi, ses trois causes de rejet, le
     CÔTÉ du rejet avec son amplitude, et la somme. Chacune était bonne, et
     c'est même par elles qu'on a su que le repli ne servait à rien — « replis
     12, replisServis 0 » puis, rapport après rapport, vingt et une tentatives
     pour zéro résultat. Elles ont fait leur travail jusqu'au bout : elles ont
     condamné ce qu'elles mesuraient.

     LA SOMME DES SEPT ISSUES, juste au-dessus, s'en trouve simplifiée : elle
     valait « demandes moins les replis », qui comptaient des requêtes
     SUPPLÉMENTAIRES et non des issues. Elle vaut maintenant `demandes` tout
     court, et c'est une phrase de moins à tenir. */

  /* ── ET UNE SEULE PAR STREAM ─────────────────────────────────────────── */
  await relacher('delta');
  const avantB = await appelsVod();
  await survoler('alpha');
  await wait(page, 700);
  await relacher('alpha');
  await survoler('alpha');
  await wait(page, 700);
  ok('les chapitres sont mémorisés : deux survols, aucune requête de plus',
     (await appelsVod()) === avantB, `${await appelsVod()} appels contre ${avantB}`);

  await page.close();
}

titre('80. Aperçu — l\'ordre du corps : les badges ensemble, la frise en dernier');
{
  /* RAPPORT D'UTILISATEUR : « j'ai l'impression que le badge Mature est en
     dessous de la partie Précédemment. Mais le [il devrait être] au même
     endroit que les badges. »

     C'était exact, et la cause est une duplication. TROIS fonctions créaient la
     zone des badges, toutes trois par `appendChild` sur le corps du popup —
     juste tant que la frise n'existait pas. Or la frise est ajoutée en
     dernier, et le badge « Contenu classé » arrive APRÈS elle : il attend la
     réponse de TsePreview, qui est asynchrone. La zone se créait alors sous la
     frise, et le badge avec elle.

     Trois copies d'une même règle finissent toujours par diverger. Elle
     n'existe plus qu'à un endroit, et cette assertion la tient. */
  const page = await freshTwitch();
  const DEBUT = Date.now() - 2 * 60 * 60_000;
  await page.evaluate((d) => {
    const iso = new Date(d).toISOString();
    window.__fx = { alpha: { id: 'a', createdAt: iso, viewers: 900,
                             game: 'Just Chatting', tags: [],
                             // Ce qui déclenche le badge, et il arrive TARD.
                             ccl: [{ id: 'MatureGame' }] } };
    window.__addCard('alpha', 'Just Chatting', '900');
  }, DEBUT);
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 1);

  /* LA FRISE DOIT ÊTRE LÀ AVANT LE BADGE, sans quoi le test ne porte pas sur
     le défaut signalé. La première rédaction la faisait naître d'une requête
     de chapitres — donc APRÈS le badge — et l'ordre était bon par accident :
     la mutation qui casse l'insertion ne la faisait pas échouer. On provoque
     donc un basculement, ce qui donne deux segments OBSERVÉS et une frise
     construite dès le rendu, synchrone. Le badge « Contenu classé », lui,
     attend la réponse de TsePreview. */
  await page.evaluate(() => { window.__fx.alpha.game = 'Overwatch'; window.tse.rescan(); });
  await attendre(page, () => document.querySelector('.side-nav-card')
    ?.dataset.tseCategory === 'Overwatch', 8000);

  await hoverLogin(page, 'alpha');
  await attendre(page,
    () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
  // On attend que LES DEUX soient là : le badge tardif et la frise.
  ok('la frise est posée DÈS le rendu — c\'est la condition du défaut',
     await page.evaluate(() => !!document.querySelector('.tse-preview__frise')),
     'sans frise au rendu, le badge tardif ne pourrait pas passer dessous');
  await attendre(page, () => !!document.querySelector('.tse-preview__badge--ccl'), 8000);

  const ordre = await page.evaluate(() => {
    const corps = document.querySelector('.tse-preview__body');
    const badge = corps.querySelector('.tse-preview__badge--ccl');
    // L'écart VISUEL entre deux blocs : du bas de l'un au haut de l'autre.
    // Mesuré sur le rendu, pas lu dans la feuille de style — une marge peut
    // s'ajouter à un gap flex sans que rien ne le dise dans la règle.
    const ecart = (a, b) =>
      Math.round(b.getBoundingClientRect().top - a.getBoundingClientRect().bottom);
    const titre = corps.querySelector('.tse-preview__title');
    const zone = corps.querySelector('.tse-preview__badges');
    const frise = corps.querySelector('.tse-preview__frise');
    return {
      enfants: [...corps.children].map(e => e.className.split(' ')[0]),
      badgeDansLaZone: !!badge && !!badge.closest('.tse-preview__badges'),
      zones: corps.querySelectorAll('.tse-preview__badges').length,
      dernier: corps.lastElementChild?.className.split(' ')[0] || null,
      titreBadges: ecart(titre, zone),
      badgesFilet: ecart(zone, frise),
    };
  });
  ok('le badge « Contenu classé », arrivé tard, rejoint la ZONE des badges',
     ordre.badgeDansLaZone === true, JSON.stringify(ordre.enfants));
  ok('…et il n\'a pas fabriqué une seconde zone au passage',
     ordre.zones === 1, `${ordre.zones} zones de badges`);
  ok('…la frise restant le DERNIER élément du corps',
     ordre.dernier === 'tse-preview__frise', JSON.stringify(ordre.enfants));
  /* ── LES DEUX RESPIRATIONS SONT ÉGALES ───────────────────────────────────
     Signalé à l'œil : « la marge entre le titre et les badges doit être la
     même que celle entre le badge et le filet ». Elle ne l'était pas — le
     corps est une colonne flex à 6 px de gap, et la frise y ajoutait 9 px de
     marge propre, soit quinze au lieu de six. Deux endroits décidaient d'un
     même espacement ; il n'y en a plus qu'un. */
  ok('…et les deux respirations sont ÉGALES : titre→badges = badges→filet',
     ordre.titreBadges === ordre.badgesFilet && ordre.titreBadges > 0,
     JSON.stringify({ titreBadges: ordre.titreBadges, badgesFilet: ordre.badgesFilet }));
  /* La VALEUR, et pas seulement l'égalité. Six pixels ont été jugés trop
     serrés à l'usage ; dix ont été demandés. Une assertion qui ne vérifierait
     que l'égalité laisserait les deux dériver ensemble sans rien dire. */
  ok('…et elles valent les dix pixels demandés',
     ordre.titreBadges === 10, `${ordre.titreBadges} px`);

  await page.close();
}

titre('81. Top Chaînes — le classement par TAG de langue');
{
  /* IDÉE VENUE D'UN UTILISATEUR, et elle vise juste. Twitch publie
     `/directory/all/tags/Français` : un classement mondial trié par
     spectateurs, filtré sur le TAG de langue. L'extension filtrait jusqu'ici
     sur `broadcasterLanguages`, et les deux ne mesurent pas la même chose —
     la déclaration des réglages d'un côté, la langue posée sur CE stream de
     l'autre. Un francophone qui fait une soirée en anglais garde « FR » dans
     ses réglages et met le tag « English ».

     ET C'EST UNE REQUÊTE, PAS TRENTE. La descente visite les catégories une à
     une ; la voie du tag demande directement le classement trié.

     CE SCÉNARIO NE PROUVE PAS QUE LA REQUÊTE EST JUSTE — elle n'a jamais pu
     être exécutée contre le vrai Twitch. Il prouve que la voie du tag REMPLACE
     la descente quand elle aboutit, et que TOUT échec retombe sur la descente
     d'aujourd'hui sans que l'utilisateur perde quoi que ce soit. */
  const monter = (page) => page.evaluate(() => {
    const h = new Date(Date.now() - 30 * 60_000).toISOString();
    window.__fx = { suivi1: { id: 'id-suivi1', createdAt: h, viewers: 400,
                              game: 'Just Chatting', tags: [] } };
    window.__addCard('suivi1', 'Just Chatting', '400');
    const cats = [];
    for (let i = 0; i < 4; i++) {
      const streams = [];
      for (let k = 0; k < 30; k++) {
        streams.push({ login: `en${i}_${k}`, viewers: 9000 - i * 100 - k, tags: ['English'] });
      }
      cats.push({ name: 'c' + i, viewers: 500_000 - i, streams });
    }
    // Une catégorie qui fait EXISTER « Français » dans la liste des langues :
    // sans elle, la langue ne serait pas proposable et rien ne se déclencherait.
    cats.push({ name: 'frcat', viewers: 499_000, streams: [
      { login: 'vis1', viewers: 100, tags: ['Français'] },
      { login: 'vis2', viewers: 90,  tags: ['Français'] },
    ] });
    window.__cats = cats;
  });
  const choisirLangue = (page, val) => page.evaluate((v) => {
    const opt = [...document.querySelectorAll('#tse-lang-dd .tse-dd-opt')]
      .find(o => (o.dataset.value || '') === v);
    if (!opt) throw new Error('langue absente : ' + JSON.stringify(v));
    opt.click();
  }, val);
  const opsTag = (page) => page.evaluate(() =>
    window.__calls.flatMap(c => c.names || []).filter(n => n === 'TseTagTop').length);
  const bilanTags = (page) => page.evaluate(() => window.tse.global.report().tags);
  const classement = (page) => page.evaluate(() =>
    window.tse.global.top(30).map(r => `${r.login}:${r.viewers}`));

  /* ── LA VOIE DU TAG QUAND ELLE ABOUTIT ─────────────────────────────────── */
  {
    const page = await fresh();
    await monter(page);
    await page.evaluate(() => {
      // Un classement que la DESCENTE ne pourrait pas trouver : ces chaînes
      // n'existent dans aucune catégorie du harnais. Si elles apparaissent,
      // c'est que la réponse vient du tag et de nulle part ailleurs.
      window.__tagTop = { 'Français': [
        { login: 'tagA', viewers: 5000, game: 'Just Chatting', tags: ['Français'] },
        { login: 'tagB', viewers: 3000, game: 'VALORANT',      tags: ['Français'] },
        { login: 'tagC', viewers: 1000, game: 'Just Chatting', tags: [] },
      ] };
    });
    await wait(page, 1500);
    await page.evaluate(() =>
      document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
    await wait(page, 1800);
    await choisirLangue(page, 'Français');
    await attendre(page, () => window.tse.global.report().worldLang === 'Français', 8000);
    await wait(page, 400);

    const top = await classement(page);
    ok('le classement vient du TAG, et non de la descente par catégories',
       top.length === 3 && top.every(t => /^tag[ABC]:/.test(t)), JSON.stringify(top));
    ok('…trié par spectateurs décroissants',
       top.join(' ') === 'tagA:5000 tagB:3000 tagC:1000', JSON.stringify(top));
    /* CE QUI N'EST PAS ÉPROUVÉ ICI, ET POURQUOI JE LE DIS. La voie du tag
       pose le tag demandé sur les enregistrements qui ne le portent pas —
       même geste que `scopePass` et `fullWalk`, pour que le filtre
       d'affichage ne rejette pas une chaîne que la requête vient de
       sélectionner. Cette ligne n'a PAS d'assertion : elle ne se manifeste que
       lorsque `worldLang` diffère de la langue choisie, c'est-à-dire dans la
       fenêtre entre le clic et la fin de la marche — une course, pas un état.
       L'API console ne projette que rang/login/viewers/jeu, et les cartes ne
       portent pas leurs langues dans cet état du harnais. Plutôt qu'une
       assertion que je ne peux pas faire échouer, aucune, et cette note. */
    ok('le classement est annoncé COMPLET — le serveur a trié, pas nous',
       await page.evaluate(() => window.tse.global.report().complete) === true);

    const b = await bilanTags(page);
    ok('une seule requête de tag a suffi là où la descente en demandait des dizaines',
       b.servis >= 1 && b.demandes >= 1 && b.refus === 0, JSON.stringify(b));

    /* LA BORNE, NOMMÉE PLUTÔT QUE SUBIE. Les trois assertions ci-dessus
       tombent déjà si l'on demande trop — mais elles tombent en montrant un
       classement vide, c'est-à-dire le symptôme. Celle-ci montre la cause :
       le nombre demandé. C'est la question à laquelle il a fallu une version
       et un rapport d'utilisateur pour répondre. */
    const demandes = await page.evaluate(() =>
      window.__calls.flatMap(c => c.tagN || []));
    ok('…et elle n\'a jamais demandé plus que les trente qu\'accorde Twitch',
       demandes.length >= 1 && demandes.every(n => n >= 1 && n <= 30),
       JSON.stringify(demandes));
    await page.close();
  }

  /* ── ET QUAND LE SCHÉMA LA REFUSE ────────────────────────────────────────
     C'est l'hypothèse à prendre au sérieux, puisque la requête n'a jamais été
     exécutée contre le vrai Twitch. L'utilisateur ne doit rien perdre : la
     descente d'aujourd'hui reprend la main, et l'on n'insiste pas — un nom
     d'argument ne devient pas valide en cours de session. */
  {
    const page = await fresh();
    await monter(page);
    await page.evaluate(() => { window.__tagTop = { 'Français': 'erreur' }; });
    await wait(page, 1500);
    await page.evaluate(() =>
      document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
    await wait(page, 1800);
    await choisirLangue(page, 'Français');
    await wait(page, 2500);

    const b = await bilanTags(page);
    ok('un refus du schéma est consigné, et la voie du tag est abandonnée',
       b.refus >= 1 && b.refuse === true, JSON.stringify(b));
    const avant = await opsTag(page);
    await page.evaluate(() => window.tse.global.on());
    await wait(page, 1500);
    ok('…et l\'on n\'insiste plus : aucune requête de tag supplémentaire',
       (await opsTag(page)) === avant, `${await opsTag(page)} contre ${avant}`);
    ok('…tandis que le classement, lui, continue d\'être servi',
       (await classement(page)).length > 0, 'classement vide après le repli');
    await page.close();
  }

  /* ── UNE DÉPENDANCE ENTRE DEUX RÉGLAGES, TENUE ICI ───────────────────────
     La voie du tag publie un classement ANNONCÉ COMPLET. Elle n'en a le droit
     que si UNE réponse couvre le top affiché : au-delà, les rangs manquants
     viendraient du report de la passe précédente, du vieux présenté comme
     exact. Le code s'en garde (`GLOBAL_TOP_N <= GLOBAL_TAG_MAX` conditionne
     l'entrée dans la voie du tag), mais cette garde est SILENCIEUSE — elle
     ferait retomber l'extension sur la descente sans que personne ne
     comprenne pourquoi la requête neuve a cessé de servir.

     D'où cette lecture des deux constantes à la source. Elle ne teste pas un
     comportement : elle empêche un réglage de rendre l'autre inopérant, et
     elle le dit au moment où l'on écrit le réglage. Porter GLOBAL_TOP_N à
     quarante la fait tomber — c'est le seul but. */
  {
    const src = readFileSync(join(ICI, '..', 'content.js'), 'utf8');
    const lire = (nom) => {
      const m = new RegExp(nom + ':\\s*(\\d+)').exec(src);
      return m && Number(m[1]);
    };
    const topN = lire('GLOBAL_TOP_N');
    const capTag = lire('GLOBAL_TAG_MAX');
    ok('le top affiché tient dans UNE réponse de tag — sinon la voie se ferme',
       topN >= 1 && capTag >= 1 && topN <= capTag,
       `GLOBAL_TOP_N=${topN}, GLOBAL_TAG_MAX=${capTag}`);
  }
}

titre('82. Frise — elle ne doit pas s\'effacer parce que d\'autres chaînes arrivent');
{
  /* LA PANNE QUE LES COMPTEURS NE POUVAIENT PAS VOIR. Un rapport disait
     « y'a pas tous les Précédemment qui fonctionne », avec des compteurs de
     chapitres impeccables : 55 demandes, 0 erreur, 0 échec réseau. Ils
     n'avaient rien à se reprocher — ils ne comptent que les requêtes PARTIES.

     Le registre des frises était borné à quarante entrées. Or il n'est pas
     alimenté par la carte survolée : `suivreCategorie` reçoit CHAQUE login de
     CHAQUE lot, c'est-à-dire tout le cache de streams — 210 dans ce rapport,
     pour 128 cartes à l'écran. Les 170 en trop créaient chacune une frise en
     évinçant une autre, et trente secondes plus tard les mêmes revenaient sans
     se retrouver. Survoler une carte n'avait qu'une chance sur cinq de trouver
     une frise ; sans frise, il n'y a ni affichage ni requête de chapitres.

     ET L'ÉVICTION VISAIT LA PLUS RICHE. `Map` itère dans l'ordre de PREMIÈRE
     insertion et `set` ne déplace pas une clé existante : purger par la tête
     sortait la frise qui accumulait depuis le plus longtemps — exactement
     celle qui avait un passé à raconter.

     CE SCÉNARIO REPRODUIT LE SYMPTÔME, pas la cause supposée : on construit
     une frise, on fait arriver des chaînes, on regarde si elle est encore là.
     C'est ce que fait l'utilisateur.

     CE QU'IL N'ÉPROUVE PAS, ET POURQUOI JE LE DIS. Le passage de la purge FIFO
     à un « moins récemment observé » n'a AUCUN effet observable ici, et n'en
     aurait aucun dans un banc raisonnable. La purge par le volume ne se
     déclenche plus : la borne couvre le cache, et une chaîne qui s'éteint voit
     sa frise retirée nommément. La faire tomber demanderait de fabriquer plus
     de chaînes que le cache n'en garde — et à ce compte-là, AUCUNE politique
     ne sauve la frise qu'on regarde : on ne tient pas 601 entrées dans 500
     places. J'ai écrit puis jeté ce scénario-là plutôt que de le publier vert
     pour de mauvaises raisons. La réinsertion reste, parce qu'elle est juste
     et qu'elle ne coûte rien ; l'assertion de borne ci-dessous est ce qui
     garde la porte. */
  const page = await freshTwitch();
  const DEBUT = Date.now() - 30 * 60_000;
  await page.evaluate((d) => {
    window.__fx = { alpha: { id: 'a', createdAt: new Date(d).toISOString(),
                             viewers: 90_000, game: 'Just Chatting', tags: [] } };
    window.__addCard('alpha', 'Just Chatting', '90 k');
  }, DEBUT);
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 1);

  const survoler = async () => {
    await hoverLogin(page, 'alpha');
    await attendre(page,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
  };
  const relacher = async () => {
    await page.evaluate(() => {
      const c = [...document.querySelectorAll('.side-nav-card')]
        .find(x => x.dataset.tseLogin === 'alpha');
      c.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
    });
    await attendre(page,
      () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);
  };
  const basculer = async (jeu) => {
    await page.evaluate((j) => { window.__fx.alpha.game = j; window.tse.rescan(); }, jeu);
    await attendre(page, (j) => [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.dataset.tseLogin === 'alpha')?.dataset.tseCategory === j, 8000, jeu);
  };
  const lignes = () => page.evaluate(() => {
    const bloc = document.querySelector('.tse-preview__frise');
    if (!bloc) return null;
    return [...bloc.querySelectorAll('.tse-preview__frise-nom')].map(n => n.textContent);
  });

  /* Deux basculements : la frise a désormais un passé, et c'est ce passé qui
     doit survivre. */
  await basculer('Hades II');
  await wait(page, 400);
  await basculer('Overwatch');
  await wait(page, 120);
  await survoler();
  const avant = await lignes();
  ok('une frise construite sur deux basculements s\'affiche',
     !!avant && avant.length >= 3, JSON.stringify(avant));
  await relacher();

  /* L'AFFLUX. Deux cents chaînes de plus — bien moins que les 210 du rapport,
     et bien plus que les quarante places d'alors. Elles portent moins de
     spectateurs qu'alpha pour que le tri ne la déplace pas hors de portée. */
  const FLOT = 200;
  await page.evaluate((n) => {
    for (let i = 0; i < n; i++) {
      const l = 'flot' + i;
      window.__fx[l] = { id: 'f' + i, createdAt: new Date(Date.now() - 3600_000).toISOString(),
                         viewers: 100 + i, game: 'G' + (i % 5), tags: [] };
      window.__addCard(l, 'G' + (i % 5), '100');
    }
    window.tse.rescan();
  }, FLOT);
  // On attend que le pipeline ait RELEVÉ tout le monde : une carte décorée est
  // une carte passée par le cache, donc par `suivreCategorie`.
  await attendre(page,
    (n) => document.querySelectorAll('[data-tse-viewers]').length >= n + 1, 20_000, FLOT);
  await wait(page, 600);

  await survoler();
  const apres = await lignes();
  ok('…et elle est TOUJOURS là après deux cents chaînes de plus',
     !!apres && apres.length >= 3, JSON.stringify(apres));
  ok('…avec le même passé, et non un redémarrage à zéro',
     !!apres && !!avant && apres.slice(-3).join(' → ') === avant.slice(-3).join(' → '),
     `avant ${JSON.stringify(avant)} · après ${JSON.stringify(apres)}`);
  await relacher();

  /* Le rapport doit désormais pouvoir MONTRER cette panne s'il elle revient :
     `resident` contre `max`, et les survols par issue. */
  const bf = await page.evaluate(() => window.tse.panneau.rapport().frise);
  ok('le rapport dit combien de frises tiennent en mémoire, et pour quelle borne',
     bf && bf.resident >= FLOT && bf.max >= bf.resident,
     JSON.stringify(bf));
  ok('…et les survols sont comptés par issue, exclusivement',
     bf.survols >= 2 && bf.absentes + bf.vides + bf.peuplees === bf.survols,
     JSON.stringify(bf));
  /* LE COMPTEUR QUI AURAIT NOMMÉ LA PANNE, et le seul. Sous la borne fautive,
     les trois ci-dessus restent muets : `absentes` vaut zéro, `peuplees` deux.
     La frise d'alpha était bien présente au survol — recréée vide au relevé
     précédent. Seul le nombre d'évictions distingue un registre sain d'un
     registre qui tourne sur lui-même. */
  ok('…et aucune frise n\'a été évincée : le registre ne tourne pas sur lui-même',
     bf.evincees === 0, JSON.stringify(bf));
  await page.close();

  /* ── LA BORNE DOIT COUVRIR CE QUI L'ALIMENTE ─────────────────────────────
     Le scénario ci-dessus prouve le symptôme à deux cents chaînes. Il ne peut
     pas prouver la borne elle-même sans en fabriquer cinq cents, ce qui
     coûterait une minute de banc pour un renseignement qu'une lecture donne.
     Cette assertion-ci le dit à l'endroit où la faute se commet : le registre
     des frises suit le cache de streams, donc sa borne ne peut pas être plus
     petite que celle du cache. La ramener à quarante la fait tomber. */
  {
    const src = readFileSync(join(ICI, '..', 'content.js'), 'utf8');
    const lire = (nom) => {
      const m = new RegExp(nom + ':\\s*(\\d+)').exec(src);
      return m && Number(m[1]);
    };
    const frises = lire('CATEGORY_TRAIL_MAX');
    const streams = lire('LIVE_CACHE_MAX');
    ok('le registre des frises couvre le cache qui l\'alimente',
       frises >= 1 && streams >= 1 && frises >= streams,
       `CATEGORY_TRAIL_MAX=${frises}, LIVE_CACHE_MAX=${streams}`);
  }
}

titre('83. Langues — la table doit être celle de Twitch, au caractère près');
{
  /* CES CLÉS NE SONT PAS DES LIBELLÉS. Ce sont les noms de TAGS que Twitch
     pose sur les streams, et `LANG_SET` les compare EXACTEMENT. Un caractère
     de trop ou de moins et la langue cesse d'exister pour l'extension : ni
     détectée sur une carte, ni proposable dans le filtre, ni interrogeable par
     la voie du tag. Sans erreur, sans compteur, sans rien dans un rapport.

     C'EST EXACTEMENT CE QUI EST ARRIVÉ AU THAÏ. La table portait « ไทย » là où
     Twitch nomme son tag « ภาษาไทย ». La langue était dans le menu, dans les
     drapeaux, dans LANG_API — et n'avait jamais rien détecté. Rien dans le
     code ne pouvait le dire : il faut comparer à une source EXTÉRIEURE.

     CETTE SOURCE, LA VOICI, et elle est solide : les URLs de
     `/directory/all/tags/…`, relevées par un utilisateur sur Twitch même. Le
     dernier segment d'une de ces URLs EST le nom du tag, à ceci près que les
     espaces y sont retirés — d'où la comparaison sans espaces, et deux
     assertions séparées pour les noms composés.

     Ce n'est pas une liste que j'ai devinée : c'est celle que Twitch publie. */
  const TWITCH = [
    'Čeština', 'Ελληνικά', 'Български', 'Русский', 'Українська', 'العربية',
    'بهاسملايو', 'ภาษาไทย', '中文', '日本語', '한국어', 'Bahasa Indonesia',
    'Català', 'Dansk', 'Deutsch', 'English', 'Español', 'Français', 'Italiano',
    'Magyar', 'Nederlands', 'Norsk', 'Polski', 'Português', 'Română',
    'Slovenčina', 'Suomi', 'Svenska', 'Türkçe', 'Tagalog', 'Tiếng Việt',
  ];

  const src = readFileSync(join(ICI, '..', 'content.js'), 'utf8');
  /* Les clés d'un littéral d'objet, extraites du bloc qui le déclare. Les
     tables sont écrites à la main dans une forme stable ; on lit donc le texte
     plutôt que d'évaluer du code source, ce qui exécuterait le fichier pour
     répondre à une question qui n'en a pas besoin. */
  const clesDe = (nom) => {
    const debut = src.indexOf(`const ${nom} = {`);
    if (debut < 0) return null;
    const fin = src.indexOf('\n  };', debut);
    const bloc = src.slice(debut, fin);
    return [...bloc.matchAll(/'([^']+)'\s*:/g)].map(m => m[1]);
  };
  const cc = clesDe('LANG_CC');
  const api = clesDe('LANG_API');
  const sansEspace = (s) => s.replace(/ /g, '');

  ok('les trente et une langues de Twitch sont dans la table',
     !!cc && TWITCH.every(l => cc.includes(l)),
     'manquantes : ' + JSON.stringify((TWITCH).filter(l => !cc?.includes(l))));
  ok('…et la table n\'en invente aucune que Twitch ne propose pas',
     !!cc && cc.every(l => TWITCH.includes(l)),
     'en trop : ' + JSON.stringify((cc || []).filter(l => !TWITCH.includes(l))));
  /* Le thaï nommément. L'assertion ci-dessus le couvre déjà, mais elle dirait
     « manquantes: [ภาษาไทย] » sans expliquer que la faute a duré des versions.
     Celle-ci nomme le piège pour qui la fera tomber un jour. */
  ok('le tag thaï est le nom COMPLET, et non le seul mot « thaï »',
     !!cc && cc.includes('ภาษาไทย') && !cc.includes('ไทย'),
     JSON.stringify((cc || []).filter(l => l.includes('ไทย'))));
  ok('les deux noms composés gardent leur espace — les URLs, elles, le retirent',
     !!cc && cc.includes('Bahasa Indonesia') && cc.includes('Tiếng Việt')
        && TWITCH.map(sansEspace).includes('BahasaIndonesia'),
     JSON.stringify((cc || []).filter(l => l.includes(' '))));

  /* LES TROIS TABLES DOIVENT S'ACCORDER. LANG_CC donne le drapeau, LANG_API le
     code d'énumération ; une langue présente dans l'une et pas dans l'autre
     s'afficherait sans drapeau, ou ne serait jamais demandable. */
  ok('chaque langue a un code d\'API, et réciproquement',
     !!api && cc.length === api.length && cc.every(l => api.includes(l)),
     `LANG_CC=${cc?.length}, LANG_API=${api?.length}`);
  /* Et chaque code de drapeau doit exister dans FLAG_SVG, sinon `flagMarkup`
     rend null et le menu retombe sur le nom canonique — lisible, mais hors
     sujet dans une colonne de drapeaux. */
  const codes = [...src.slice(src.indexOf('const LANG_CC = {'),
                              src.indexOf('\n  };', src.indexOf('const LANG_CC = {')))
                    .matchAll(/'[^']+'\s*:\s*'([A-Z]{2})'/g)].map(m => m[1]);
  const drapeaux = [...src.slice(src.indexOf('const FLAG_SVG = {'),
                                 src.indexOf('\n  };', src.indexOf('const FLAG_SVG = {')))
                       .matchAll(/'([A-Z]{2})'\s*:\s*`/g)].map(m => m[1]);
  ok('chaque langue a son drapeau dessiné',
     codes.length === cc.length && codes.every(c => drapeaux.includes(c)),
     'sans drapeau : ' + JSON.stringify(codes.filter(c => !drapeaux.includes(c))));
  ok('…et aucun drapeau ne dort sans langue qui le porte',
     drapeaux.every(d => codes.includes(d)),
     'orphelins : ' + JSON.stringify(drapeaux.filter(d => !codes.includes(d))));
}

titre('84. Filtres — deux menus indépendants, et des spectateurs plutôt que des chaînes');
{
  /* DEUX DÉFAUTS QU'UN UTILISATEUR A VUS AVANT MOI, et ils ont la même cause.

     Une version a lié la liste des CATÉGORIES à la langue choisie, pour que
     ses compteurs suivent la langue. La source de cette liste — une requête à
     Twitch qui s'est révélée inexistante sous les deux noms essayés — rendait
     des listes VIDES. Le menu catégorie se vidait donc avec elle et se
     grisait : choisir une langue rendait la catégorie inchoisissable, et
     l'inverse aussi dès qu'on ajoutait la langue après. Les deux filtres
     doivent se poser dans N'IMPORTE QUEL ORDRE.

     Et le menu langue comptait des CHAÎNES là où celui d'à côté affiche une
     AUDIENCE : « 212 » contre « 122 k », deux unités voisines dont une seule
     répond à la question qu'on se pose en ouvrant le menu.

     LA DONNÉE ÉTAIT DÉJÀ LÀ. Chaque enregistrement du pool porte son nombre de
     spectateurs ET ses tags de langue — la même réponse les a apportés. Les
     sommer ne coûte aucune requête, et la somme se restreint à la catégorie
     choisie quand il y en a une. */
  const options = (page, dd) => page.evaluate((id) =>
    [...document.querySelectorAll('#' + id + ' .tse-dd-opt')]
      .map(o => ({ v: o.dataset.value,
                   n: (o.querySelector('.tse-dd-n')?.textContent || '').replace(' |', '').trim() }))
      .filter(o => o.v), dd);
  const grise = (page, dd) => page.evaluate((id) =>
    document.querySelector('#' + id + ' .tse-dd-btn').disabled, dd);
  const choisir = (page, dd, val) => page.evaluate(([id, v]) => {
    const opt = [...document.querySelectorAll('#' + id + ' .tse-dd-opt')]
      .find(o => (o.dataset.value || '') === v);
    if (!opt) throw new Error('option absente de #' + id + ' : ' + JSON.stringify(v));
    opt.click();
  }, [dd, val]);

  const page = await fresh();
  await page.evaluate(() => {
    window.__fx = { suivi1: { id: 'id-suivi1', createdAt: new Date(Date.now() - 1800_000).toISOString(),
                              viewers: 400, game: 'Just Chatting', tags: [] } };
    window.__addCard('suivi1', 'Just Chatting', '400');
    /* Deux catégories, chacune avec du français ET de l'anglais, en
       proportions DIFFÉRENTES : c'est ce qui rend le compteur de langue
       mesurable, et sa dépendance à la catégorie visible. */
    window.__cats = [
      { name: 'cat0', viewers: 100_000, streams: [
        { login: 'a1', viewers: 9000, tags: ['Français'] },
        { login: 'a2', viewers: 1000, tags: ['Français'] },
        { login: 'a3', viewers: 5000, tags: ['English'] },
      ] },
      { name: 'cat1', viewers: 90_000, streams: [
        { login: 'b1', viewers: 8000, tags: ['English'] },
        { login: 'b2', viewers: 2000, tags: ['Français'] },
      ] },
    ];
  });
  await wait(page, 1500);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await attendre(page, () => window.tse.global.top(1).length > 0, 9000);
  await wait(page, 600);

  /* ── LE COMPTEUR EST UNE AUDIENCE ─────────────────────────────────────── */
  const monde = new Map((await options(page, 'tse-lang-dd')).map(o => [o.v, o.n]));
  ok('le menu langue compte des SPECTATEURS, pas des chaînes',
     /k$/.test(monde.get('Français') || ''), `Français → « ${monde.get('Français')} »`);
  ok('…et la somme est celle du monde : 9 000 + 1 000 + 2 000 = 12 k',
     /^12\s*k$/.test(monde.get('Français') || ''), JSON.stringify([...monde]));
  ok('…l\'anglais, à 13 000, passant devant',
     /^13\s*k$/.test(monde.get('English') || ''), JSON.stringify([...monde]));

  /* SANS CATÉGORIE AUSSI, le chiffre doit valoir ce que la sélection donne.
     C'est le cas que l'utilisateur a rencontré — aucune catégorie choisie, un
     drapeau annonçant 21 pour 318 affichés. Le monde se mesure par la voie du
     tag, celle-là même qui servira le classement quand on cliquera. */
  await choisir(page, 'tse-lang-dd', 'Français');
  await attendre(page, () => window.tse.global.report().worldLang === 'Français', 9000);
  await wait(page, 800);
  const vuFr = await page.evaluate(() =>
    window.tse.global.top(30).reduce((n, r) => n + r.viewers, 0));
  ok('le chiffre du monde vaut lui aussi la somme affichée',
     vuFr === 12_000, `${vuFr} affichés contre « ${monde.get('Français')} » annoncés`);
  await choisir(page, 'tse-lang-dd', '');
  await wait(page, 1200);

  /* ── LES DEUX MENUS RESTENT UTILISABLES, DANS LES DEUX ORDRES ─────────── */
  await choisir(page, 'tse-lang-dd', 'Français');
  await wait(page, 1200);
  ok('une langue choisie, le menu CATÉGORIE reste utilisable',
     (await grise(page, 'tse-cat-dd')) === false, 'le menu catégorie est grisé');
  ok('…et il propose toujours toutes les catégories du monde',
     (await options(page, 'tse-cat-dd')).length === 2,
     JSON.stringify(await options(page, 'tse-cat-dd')));

  await choisir(page, 'tse-cat-dd', 'cat0');
  await wait(page, 1500);
  ok('la catégorie ajoutée par-dessus, aucun des deux menus n\'est grisé',
     (await grise(page, 'tse-cat-dd')) === false
     && (await grise(page, 'tse-lang-dd')) === false,
     `cat=${await grise(page, 'tse-cat-dd')} lang=${await grise(page, 'tse-lang-dd')}`);

  /* ── ET LE COMPTEUR SUIT LA CATÉGORIE CHOISIE ─────────────────────────── */
  const dansCat0 = new Map((await options(page, 'tse-lang-dd')).map(o => [o.v, o.n]));
  ok('le compteur de langue porte alors sur CETTE catégorie : 9 000 + 1 000',
     /^10\s*k$/.test(dansCat0.get('Français') || ''),
     `Français → « ${dansCat0.get('Français')} » (monde : ${monde.get('Français')})`);
  ok('…et il a donc CHANGÉ en choisissant la catégorie',
     dansCat0.get('Français') !== monde.get('Français'),
     `${monde.get('Français')} puis ${dansCat0.get('Français')}`);

  /* Revenir au globe côté catégorie rend les totaux mondiaux. */
  await choisir(page, 'tse-cat-dd', '');
  await wait(page, 1500);
  const revenu = new Map((await options(page, 'tse-lang-dd')).map(o => [o.v, o.n]));
  ok('« toutes les catégories » redonne la somme du monde',
     revenu.get('Français') === monde.get('Français'),
     `${revenu.get('Français')} contre ${monde.get('Français')}`);
  await page.close();
}

titre('85. La carte sans catégorie — le pseudo se recentre');
{
  /* TOUTES LES CHAÎNES N'ANNONCENT PAS DE CATÉGORIE. La rangée garde alors la
     hauteur que lui donne sa colonne de droite — spectateurs au-dessus, durée
     en dessous — pendant que la gauche n'a plus qu'une ligne, calée en haut.
     Le pseudo flotte au-dessus d'un vide.

     DEUX ASSERTIONS DE NATURES DIFFÉRENTES, ET IL FAUT LES DEUX. Le MARQUEUR
     est éprouvé sans rien supposer de Twitch : il vient de la réponse de
     TseChannels, qui fait autorité là où le DOM peut être en retard. La
     GÉOMÉTRIE, elle, ne peut se mesurer que dans une rangée mise en page — et
     ce harnais n'a pas la feuille de style de Twitch. Il en porte donc une
     modélisation, décrite en tête de page.html, et l'assertion qui s'en sert
     ne prouve que ceci : notre règle centre bien ce qu'elle vise. */
  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    window.__fx = {
      avecjeu: { id: 'a1', createdAt: h, viewers: 1000, game: 'Just Chatting', tags: [] },
      sansjeu: { id: 'a2', createdAt: h, viewers: 900,  game: null,            tags: [] },
    };
    window.__addCard('avecjeu', 'Just Chatting', '1 k');
    // Catégorie absente : Twitch n'écrit alors AUCUN <p>, il n'en écrit pas un
    // vide. Le harnais fait pareil (cf. __addCard).
    window.__addCard('sansjeu', '', '900');
  });
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 2, 9000);
  await attendre(page, () => !!document.querySelector('[data-tse-nocat="true"]'), 9000);

  const etat = await page.evaluate(() => {
    const carte = (l) => [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.dataset.tseLogin === l);
    const lire = (l) => {
      const c = carte(l);
      const meta = c.querySelector('[data-a-target="side-nav-card-metadata"]');
      const rangee = c.querySelector('.metacell');
      const m = meta.getBoundingClientRect(), r = rangee.getBoundingClientRect();
      const p = meta.querySelector('p').getBoundingClientRect();
      return {
        nocat: c.dataset.tseNocat || null,
        justify: getComputedStyle(meta).justifyContent,
        // Écart entre le centre du PSEUDO et le centre de la rangée.
        ecart: Math.round((p.top + p.height / 2) - (r.top + r.height / 2)),
        hauteurRangee: Math.round(r.height),
        hauteurMeta: Math.round(m.height),
        // Les deux marges de la boîte dans sa rangée. Égales, la boîte est
        // centrée — que sa hauteur soit celle de la rangée ou celle de son
        // contenu. C'est la propriété qu'on veut, et elle ne dit rien du
        // MOYEN employé pour l'obtenir.
        margeHaut: Math.round(m.top - r.top),
        margeBas: Math.round(r.bottom - m.bottom),
      };
    };
    return { avec: lire('avecjeu'), sans: lire('sansjeu') };
  });

  ok('la carte sans catégorie est marquée, celle qui en a une ne l\'est pas',
     etat.sans.nocat === 'true' && etat.avec.nocat === null, JSON.stringify(etat));
  ok('…et le marqueur vient de la réponse de l\'API, pas d\'un <p> vide',
     await page.evaluate(() => {
       const c = [...document.querySelectorAll('.side-nav-card')]
         .find(x => x.dataset.tseLogin === 'sansjeu');
       return c.querySelectorAll('[data-a-target="side-nav-card-metadata"] p').length;
     }) === 1, 'la carte porte un second <p>, le décor ne modélise pas le bon cas');
  /* ── CE QUE CETTE ASSERTION DISAIT, ET POURQUOI ELLE A CHANGÉ ────────────
     Elle exigeait que la boîte soit ÉTIRÉE à la hauteur de sa rangée — le
     moyen qu'employait la 3.98, et non le résultat attendu. La 4.3 centre la
     BOÎTE au lieu de l'étirer, parce qu'une rangée qui épingle sa colonne
     rendait l'étirement inopérant sur la vraie page (le pari, et son prix :
     deux versions vertes au banc et sans effet chez l'utilisateur).

     ON VÉRIFIE DONC LA PROPRIÉTÉ, PAS LE MOYEN : la boîte est à égale distance
     du haut et du bas de sa rangée. C'est vrai des deux mises en page — étirée,
     les deux marges valent zéro ; centrée, elles valent la même chose. Une
     assertion qui nomme le moyen interdit d'en changer sans la réécrire, et
     c'est exactement ce qui vient d'arriver. */
  ok('la metadata sans catégorie est à égale distance du haut et du bas de sa rangée',
     etat.sans.hauteurRangee > 0
     && Math.abs(etat.sans.margeHaut - etat.sans.margeBas) <= 1,
     JSON.stringify(etat.sans));
  ok('…et le pseudo y est CENTRÉ, à un pixel près',
     Math.abs(etat.sans.ecart) <= 1, JSON.stringify(etat.sans));
  /* La carte qui a une catégorie ne doit RIEN changer : c'est ce qui prouve
     que la règle vise le bon sous-ensemble et non toutes les cartes. */
  ok('la carte AVEC catégorie garde son pseudo en haut',
     etat.avec.ecart < -1 && etat.avec.justify !== 'center', JSON.stringify(etat.avec));
  await page.close();
}

titre('86. Top Chaînes — le filtre qui ne rend personne le DIT');
{
  /* UN CLASSEMENT VIDE SOUS DES MENUS QUI ONT L'AIR DE MARCHER se lit comme
     une panne. Une catégorie croisée avec une langue peut n'avoir aucun
     direct — c'est un résultat, et il vaut une phrase.

     LE PIÈGE EST LE MOMENT. Le classement est vide pendant la fraction de
     seconde qui suit chaque changement de filtre, le temps que la passe
     correspondante arrive. Un message posé sur « la liste est vide » clignote
     donc à chaque clic avant de se démentir. C'est la moitié de ce scénario. */
  const page = await fresh();
  await page.evaluate(() => {
    window.__fx = { suivi1: { id: 'id-suivi1', createdAt: new Date(Date.now() - 1800_000).toISOString(),
                              viewers: 400, game: 'Just Chatting', tags: [] } };
    window.__addCard('suivi1', 'Just Chatting', '400');
    const cats = [];
    for (let i = 0; i < 3; i++) {
      const streams = [];
      for (let k = 0; k < 5; k++) {
        streams.push({ login: `en${i}_${k}`, viewers: 9000 - i * 100 - k, tags: ['English'] });
      }
      cats.push({ name: 'cat' + i, viewers: 100_000 - i, streams });
    }
    // Une catégorie SANS aucun direct : c'est elle qui doit produire le message.
    cats.push({ name: 'desert', viewers: 90_000, streams: [] });
    window.__cats = cats;
  });
  await wait(page, 1500);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await attendre(page, () => window.tse.global.top(1).length > 0, 9000);

  const message = () => page.evaluate(() => {
    const el = document.getElementById('tse-global-empty');
    return el ? { texte: el.textContent, apres: el.previousElementSibling?.id || null } : null;
  });
  ok('un classement peuplé n\'affiche aucun message',
     (await message()) === null);

  // Le menu se reconstruit au scan : on ATTEND l'option plutôt que de la
  // supposer présente à l'instant où le classement se peuple.
  await attendre(page, () => [...document.querySelectorAll('#tse-cat-dd .tse-dd-opt')]
    .some(o => o.dataset.value === 'desert'), 9000);
  await page.evaluate(() => {
    [...document.querySelectorAll('#tse-cat-dd .tse-dd-opt')]
      .find(o => o.dataset.value === 'desert').click();
  });
  await attendre(page, () => !!document.getElementById('tse-global-empty'), 9000);
  const m = await message();
  ok('une catégorie sans le moindre direct affiche le message',
     !!m && m.texte.length > 0, JSON.stringify(m));
  ok('…et il est posé SOUS les commandes, après la rangée de tri',
     m.apres === 'tse-sort-row', JSON.stringify(m));
  ok('…dans la langue de l\'interface',
     m.texte === 'Aucune chaîne en direct avec ce filtre', JSON.stringify(m));

  /* IL DISPARAÎT quand la sélection redonne du monde. Sans cette assertion,
     un message qui ne s'effacerait jamais passerait pour un succès. */
  await page.evaluate(() => {
    const opt = [...document.querySelectorAll('#tse-cat-dd .tse-dd-opt')]
      .find(o => (o.dataset.value || '') === '');
    opt.click();
  });
  await attendre(page, () => !document.getElementById('tse-global-empty'), 9000);
  ok('…et il s\'efface dès que la sélection redonne des chaînes',
     (await message()) === null);
  await page.close();

  /* ── ET CE QUI N'EST PAS UN RÉSULTAT : UNE PANNE ────────────────────────
     « Aucune chaîne ne correspond » et « je n'ai rien pu charger » donnent la
     même barre latérale vide, et la première phrase serait un mensonge sur la
     seconde. Sans marche aboutie, on ne dit rien — le voile, lui, est là pour
     ça. Cette assertion tient la garde qui le distingue : la retirer fait
     apparaître le message sur un réseau en panne. */
  {
    const p2 = await fresh();
    await p2.evaluate(() => {
      window.__globalFail = true;   // TseCategories et TseCategoryTop échouent
      window.__fx = { suivi1: { id: 'id-s1', createdAt: new Date(Date.now() - 1800_000).toISOString(),
                                viewers: 400, game: 'Just Chatting', tags: [] } };
      window.__addCard('suivi1', 'Just Chatting', '400');
      window.__cats = [{ name: 'cat0', viewers: 100_000, streams: [] }];
    });
    await wait(p2, 1500);
    await p2.evaluate(() =>
      document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
    await wait(p2, 3000);
    const vide = await p2.evaluate(() => window.tse.global.top(1).length);
    ok('un classement vide FAUTE DE RÉSEAU ne s\'annonce pas comme un résultat',
       vide === 0 && !(await p2.evaluate(() => !!document.getElementById('tse-global-empty'))),
       'le message est apparu alors qu\'aucune marche n\'a abouti');
    await p2.close();
  }
}

titre('86bis. Filtres — le tri, la symétrie, et ce qu\'une sélection apprend');
{
  /* TROIS RETOURS D'UN MÊME UTILISATEUR, SUR LA MÊME CAPTURE.

     1. Les langues sans chiffre remontaient AU-DESSUS de l'anglais à 130 k.
        `Map.get` rend `undefined` pour une langue non mesurée, et
        `undefined - 130100` vaut NaN : un comparateur qui rend NaN ne trie
        pas, il laisse l'ordre au moteur.

     2. Drapeau français choisi, et le menu catégorie affichait toujours les
        totaux du MONDE. Le menu langue suivait la catégorie ; l'inverse
        n'était pas vrai.

     3. Un drapeau sans chiffre, une fois choisi, montrait deux chaînes. Nous
        les avions — la passe de portée en langue les a demandées — et nous ne
        les gardions pas. */
  const options = (page, dd) => page.evaluate((id) =>
    [...document.querySelectorAll('#' + id + ' .tse-dd-opt')]
      .map(o => ({ v: o.dataset.value,
                   n: (o.querySelector('.tse-dd-n')?.textContent || '').replace(' |', '').trim() }))
      .filter(o => o.v), dd);
  const choisir = (page, dd, val) => page.evaluate(([id, v]) => {
    const opt = [...document.querySelectorAll('#' + id + ' .tse-dd-opt')]
      .find(o => (o.dataset.value || '') === v);
    if (!opt) throw new Error('option absente de #' + id + ' : ' + JSON.stringify(v));
    opt.click();
  }, [dd, val]);

  const page = await fresh();
  await page.evaluate(() => {
    window.__fx = { suivi1: { id: 'id-s1', createdAt: new Date(Date.now() - 1800_000).toISOString(),
                              viewers: 400, game: 'Just Chatting', tags: [] } };
    window.__addCard('suivi1', 'Just Chatting', '400');
    /* Le pool mondial ne verra QUE de l'anglais et du français : le tchèque
       existe sur « cat0 » mais trop bas pour y figurer. C'est exactement la
       situation de la capture — un drapeau sans chiffre qui, choisi, rend
       deux chaînes. */
    /* LA SITUATION DE LA CAPTURE, REPRODUITE. Sur « cat0 », vingt-neuf
       chaînes anglaises et une française occupent tout le top que la marche
       récolte : les deux tchèques, à quarante et vingt spectateurs, en sont
       exclues. Le tchèque EXISTE pourtant dans le monde — « cat2 » en porte —
       donc il est proposé au menu, mais sans chiffre sur cette catégorie-là.
       C'est exactement ce que l'utilisateur décrit : un drapeau sans nombre
       qui, choisi, rend deux chaînes. */
    const gros = [{ login: 'f1', viewers: 8500, tags: ['Français'] }];
    for (let k = 0; k < 29; k++) {
      gros.push({ login: 'e' + k, viewers: 9000 - k, tags: ['English'] });
    }
    window.__cats = [
      { name: 'cat0', viewers: 100_000, streams: [
        ...gros,
        { login: 'c1', viewers: 40, lang: 'CS', tags: ['Čeština'] },
        { login: 'c2', viewers: 20, lang: 'CS', tags: ['Čeština'] },
      ] },
      { name: 'cat1', viewers: 90_000, streams: [
        { login: 'z2', viewers: 8000, tags: ['English'] },
      ] },
      // Le tchèque quelque part dans le monde : sans quoi il ne serait pas
      // même PROPOSÉ, et le scénario ne pourrait pas le choisir.
      { name: 'cat2', viewers: 80_000, streams: [
        { login: 'c9', viewers: 500, lang: 'CS', tags: ['Čeština'] },
      ] },
    ];
  });
  await wait(page, 1500);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await attendre(page, () => window.tse.global.top(1).length > 0, 9000);
  await wait(page, 600);

  /* ── 1. LE TRI ───────────────────────────────────────────────────────── */
  await choisir(page, 'tse-cat-dd', 'cat0');
  await wait(page, 1500);
  const langs = await options(page, 'tse-lang-dd');
  const chiffres = langs.filter(o => o.n).map(o => o.v);
  ok('les langues chiffrées sont EN TÊTE, décroissantes',
     langs.slice(0, chiffres.length).every(o => o.n)
     && chiffres[0] === 'English' && chiffres[1] === 'Français',
     JSON.stringify(langs.slice(0, 5)));
  ok('…et celles qu\'on n\'a pas mesurées suivent, sans « 0 »',
     langs.slice(chiffres.length).every(o => o.n === ''),
     JSON.stringify(langs.slice(chiffres.length, chiffres.length + 3)));

  /* ── 3. LE CHIFFRE EST CELUI QUE LA SÉLECTION DONNERA ────────────────────
     C'EST LE CŒUR DE CE SCÉNARIO, et il vient d'un utilisateur qui a compté à
     la main : « le drapeau hongrois me donne 21, et j'en vois environ 318 ».
     Il avait raison, et l'écart n'était pas une approximation — c'était un
     autre nombre, quinze fois plus grand. Le compteur sommait alors le pool
     MONDIAL, qui est un TOP : les chaînes d'une petite langue passent toutes
     sous son seuil, si bien que la somme portait sur ce qui restait, c'est-à-
     dire presque rien.

     Le tchèque reproduit exactement ce cas : deux chaînes à quarante et vingt
     spectateurs, invisibles du pool mondial. La seule définition qui tienne
     est donc celle-ci, et elle se vérifie en la comparant à l'affichage. */
  const avant = new Map(langs.map(o => [o.v, o.n]));
  ok('un drapeau porte un chiffre même quand le pool mondial l\'ignore',
     /\d/.test(avant.get('Čeština') || ''), `Čeština → « ${avant.get('Čeština')} »`);
  await choisir(page, 'tse-lang-dd', 'Čeština');
  await attendre(page, () => window.tse.global.report().scopeSize > 0, 9000);
  await wait(page, 800);
  const somme = await page.evaluate(() =>
    window.tse.global.top(30).reduce((n, r) => n + r.viewers, 0));
  const apres = new Map((await options(page, 'tse-lang-dd')).map(o => [o.v, o.n]));
  ok('…et il vaut EXACTEMENT la somme de ce que la sélection affiche',
     somme === 60 && avant.get('Čeština') === apres.get('Čeština')
     && apres.get('Čeština') === '60',
     `menu « ${apres.get('Čeština')} » contre ${somme} affichés`);

  /* ── 2. LA SYMÉTRIE ──────────────────────────────────────────────────── */
  await choisir(page, 'tse-cat-dd', '');
  await wait(page, 1200);
  await choisir(page, 'tse-lang-dd', 'Français');
  await attendre(page, () => window.tse.global.report().worldLang === 'Français', 9000);
  await wait(page, 800);
  const cats = await options(page, 'tse-cat-dd');
  const parCat = new Map(cats.map(o => [o.v, o.n]));
  ok('une langue choisie, le menu CATÉGORIE ne montre plus les totaux du monde',
     parCat.get('cat0') !== '' && !/^100\s*k$/.test(parCat.get('cat0') || ''),
     `cat0 → « ${parCat.get('cat0')} » (mondial : 100 k)`);
  ok('…mais bien ce que cette langue y pèse : 8 500',
     /^8,5\s*k$/.test(parCat.get('cat0') || ''), `cat0 → « ${parCat.get('cat0')} »`);
  /* UN ZÉRO MESURÉ PORTE SON ZÉRO. C'est une réponse — « le français n'a
     personne sur cette catégorie » — et la taire ferait croire qu'on n'a pas
     regardé. Ce qui reste muet, c'est ce qu'on n'a PAS mesuré, et l'on ne
     peut donc pas confondre les deux d'un coup d'œil. */
  ok('…et la catégorie où elle n\'a personne porte un « 0 » mesuré',
     parCat.get('cat1') === '0', `cat1 → « ${parCat.get('cat1')} »`);
  /* CHAQUE CATÉGORIE OÙ CETTE LANGUE EXISTE PORTE SON CHIFFRE, et pas
     seulement celle qu'on avait déjà visitée. C'est le trou de la 3.84 : le
     registre n'était rempli que dans un sens — une catégorie fixée, toutes
     les langues — si bien que choisir une langue laissait le menu catégorie
     sans le moindre nombre. Le tri retombait alphabétique, ce qui se voyait
     tout de suite sur une capture. */
  ok('…et la mesure couvre TOUTES les catégories, pas la seule visitée',
     [...parCat.values()].every(n => n !== ''), JSON.stringify([...parCat]));
  ok('…l\'ordre suivant ces chiffres, et non l\'alphabet',
     cats[0].v === 'cat0', JSON.stringify(cats.map(o => o.v)));
  ok('…la liste des catégories restant complète et utilisable',
     cats.length === 3
     && (await page.evaluate(() => document.querySelector('#tse-cat-dd .tse-dd-btn').disabled)) === false,
     JSON.stringify(cats));
  await page.close();
}

titre('87. La troisième porte — les clips, pour qui n\'archive pas');
{
  /* UN QUART DES SURVOLS N'A AUCUN ENREGISTREMENT. Un rapport : dix-neuf
     chaînes sur soixante-dix-sept, dont cinq sans la moindre archive. Ces
     chaînes ne permettent pas le replay ; leur passé n'existe nulle part sous
     forme de VOD. Restent les clips, seule trace publique de ce qu'une chaîne
     diffusait à un instant passé.

     CE QU'UN CLIP PROUVE : sa date et sa catégorie, donc « à cet instant, elle
     était là-dessus ». CE QU'IL NE PROUVE PAS : ce qui s'est passé entre deux
     clips. Un segment ne commence donc qu'au PREMIER clip d'une suite portant
     la même catégorie — jamais avant — et la part qui précède reste avouée.

     LA PRÉSENTATION EN DÉCOULE. Une frise de clips ne se lit pas comme une
     frise de chapitres : ses bornes sont des minorants. Elle le DIT. */
  const page = await freshTwitch();
  const DEBUT = Date.now() - 240 * 60_000;          // live commencé il y a 4 h
  await page.evaluate((d) => {
    window.__fx = { sansvod: { id: 'sv', createdAt: new Date(d).toISOString(),
                               viewers: 1200, game: 'Hades II', tags: [] } };
    window.__addCard('sansvod', 'Hades II', '1,2 k');
    /* « sansvod » = un stream bien vivant, mais AUCUN archiveVideo. Un login
       absent de `__vod` voudrait dire « aucun stream », ce qui est un tout
       autre cas et n'atteint jamais la troisième porte. */
    window.__vod = { sansvod: 'sansvod' }; window.__vodRecent = {};
    window.__clips = { sansvod: [
      { jeu: 'Just Chatting', ilYaMin: 230 },
      { jeu: 'Just Chatting', ilYaMin: 215 },
      { jeu: 'Hades II',      ilYaMin: 150 },
      { jeu: 'Hades II',      ilYaMin: 40 },
    ] };
  }, DEBUT);
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 1);

  await hoverLogin(page, 'sansvod');
  await attendre(page,
    () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 9000);
  const f = await page.evaluate(() => {
    const bloc = document.querySelector('.tse-preview__frise');
    return {
      clips: bloc.classList.contains('tse-preview__frise--clips'),
      source: bloc.querySelector('.tse-preview__frise-source')?.textContent || null,
      total: bloc.querySelector('.tse-preview__frise-total').textContent,
      lignes: [...bloc.querySelectorAll('.tse-preview__frise-ligne')].map(l => ({
        nom: l.querySelector('.tse-preview__frise-nom').textContent,
        duree: l.querySelector('.tse-preview__frise-duree')?.textContent || '',
        inconnu: l.classList.contains('tse-preview__frise-ligne--inconnu'),
      })),
      /* LES COULEURS SE COMPARENT APRÈS NORMALISATION. Une propriété
         personnalisée rend le TEXTE écrit — « #3ddc84 » — quand
         `style.backgroundColor` rend la forme calculée du navigateur —
         « rgb(61, 220, 132) ». Les deux désignent la même couleur et ne sont
         pas la même chaîne : comparer les textes bruts faisait échouer une
         assertion sur une différence de notation, pas de teinte. On passe donc
         chacune par le moteur, qui rend une forme unique. */
      parts: (() => {
        const sonde = document.createElement('span');
        const teinte = (v) => {
          if (!v) return '';
          sonde.style.color = ''; sonde.style.color = v;
          return sonde.style.color;
        };
        return [...bloc.querySelectorAll('.tse-preview__frise-part')].map(p => ({
          inconnu: p.classList.contains('tse-preview__frise-part--inconnu'),
          flou:  p.classList.contains('tse-preview__frise-part--flou'),
          large: p.style.getPropertyValue('--tse-flou').trim(),
          vers:  teinte(p.style.getPropertyValue('--tse-flou-vers').trim()),
          de:    teinte(p.style.getPropertyValue('--tse-flou-de').trim()),
          couleur: teinte(p.style.backgroundColor),
          couture: getComputedStyle(p).boxShadow,
          /* LA HACHURE A ÉTÉ RETIRÉE : elle assombrissait les couleurs d'un
             ruban dont toute la fonction est de les faire correspondre à une
             légende, et ce qu'elle avouait est mieux dit par la vague et le
             fondu. Un motif répété qui reviendrait ici serait une régression,
             et rien d'autre ne l'attraperait. */
          hachuree: getComputedStyle(p).backgroundImage.includes('repeating'),
        }));
      })(),
    };
  });
  ok('une chaîne sans enregistrement obtient tout de même une frise',
     f.lignes.length >= 3, JSON.stringify(f));
  ok('…qui porte les deux catégories que les clips attestent, dans l\'ordre',
     f.lignes.filter(l => !l.inconnu).map(l => l.nom).join(' → ')
       === 'Discussions → Hades II', JSON.stringify(f.lignes));
  ok('…et DIT qu\'elle vient des clips, parce qu\'elle ne se lit pas pareil',
     f.clips === true && f.source === 'd\'après les clips', JSON.stringify(f));
  ok('…la part antérieure au premier clip étant nommée pour ce qu\'elle est',
     f.lignes[0].inconnu === true && f.lignes[0].nom === 'avant le premier clip',
     JSON.stringify(f.lignes[0]));

  /* ── LA BORNE QU'ON NE SAIT PAS PLACER, ET SA LARGEUR EXACTE ─────────────
     LE DÉCOR DONNE UN NOMBRE VÉRIFIABLE À LA MAIN, et c'est pour cela qu'on
     l'éprouve ici plutôt que sur une frise inventée. Les clips tombent à
     −230 et −215 pour « Discussions », puis à −150 et −40 pour « Hades II ».
     Le segment Discussions est donc dessiné de −230 à −150, soit 80 minutes ;
     mais le DERNIER clip qui prouve « Discussions » date de −215, et le
     PREMIER qui prouve « Hades II » de −150. Entre les deux — 65 minutes — le
     basculement a eu lieu sans que rien ne dise quand.

     65 sur 80 font 81,25 % du segment, et c'est cette proportion-là que le
     ruban doit estomper : ni une largeur forfaitaire, ni le segment entier.
     Une tolérance d'un dixième de point absorbe l'arrondi à deux décimales
     que le rendu écrit ; elle ne laisserait passer aucune autre règle.

     LE FONDU VA VERS LA COULEUR DU SUIVANT, et part de la sienne : ce sont
     les deux bouts d'une rampe opaque, et les intervertir donnerait une borne
     qui fond dans le mauvais sens — visuellement plausible, et fausse. */
  const douteuse = f.parts[1];
  ok('la borne que les clips ne datent pas est estompée, et à sa largeur RÉELLE',
     douteuse.flou === true
     && Math.abs(parseFloat(douteuse.large) - 81.25) < 0.1,
     JSON.stringify({ large: douteuse.large, parts: f.parts.map(p => p.flou) }));
  ok('…d\'une teinte à l\'autre, dans le sens du temps',
     douteuse.de === douteuse.couleur
     && douteuse.vers === f.parts[2].couleur && douteuse.vers !== douteuse.de,
     JSON.stringify({ de: douteuse.de, vers: douteuse.vers,
                      suivante: f.parts[2].couleur }));
  /* LA COUTURE SE TAIT LÀ OÙ L'ON DOUTE. Un trait net tracé au milieu du
     fondu réaffirmerait la minute que le fondu vient de retirer : les deux se
     contredisaient à un pixel d'écart, et la capture l'a montré. */
  ok('…et la couture ne redessine pas la rupture qu\'on vient d\'effacer',
     f.parts[2].couture === 'none' && f.parts[0].couture === 'none',
     JSON.stringify(f.parts.map(p => p.couture)));
  /* ── LA PART INCONNUE S'ESTOMPE SUR TOUTE SA LARGEUR ────────────────────
     Elle ne se réduit pas à « du temps qu'aucun clip ne couvre ». Le premier
     segment commence au premier clip qui le PROUVE ; la catégorie, elle, avait
     commencé avant — quelque part entre le départ du direct et ce clip. Cet
     intervalle douteux est donc la part inconnue TOUT ENTIÈRE, d'où 100 % :
     le fondu ne dit pas « c'était cette catégorie », il dit « ça l'est devenu
     quelque part là-dedans ». La hachure reste par-dessus, parce que le fondu
     ne rachète pas l'ignorance.

     LA DERNIÈRE PART, ELLE, N'A RIEN À ESTOMPER : elle finit à maintenant,
     qui est certain. Deux parts estompées sur trois, et pas trois. */
  /* ── LA VAGUE, ET CE QU'ELLE QUALIFIE EXACTEMENT ────────────────────────
     Sur une frise de clips, la durée d'une catégorie est une APPROCHE : ses
     bornes sont les instants où un clip prouve qu'elle était en cours, et le
     vrai début est antérieur. « ~2h28 » le dit en un caractère.

     ELLE NE SE POSE PAS SUR TOUT, ET C'EST CE QUI LUI DONNE SON SENS. La part
     « avant le premier clip » va du départ du direct au premier clip : deux
     instants CONNUS, donc une durée exacte. Le total de l'en-tête est la durée
     du direct, exacte elle aussi. Une vague posée partout serait décorative ;
     posée sur le seul approché, elle se lit. On exige donc les deux sens —
     présente sur les catégories, ABSENTE sur les deux durées exactes — faute
     de quoi un préfixe collé à toutes les durées passerait le contrôle. */
  const lignesClips = f.lignes;
  ok('la vague ne marque que les durées APPROCHÉES, et les deux exactes s\'en passent',
     lignesClips.filter(l => !l.inconnu).every(l => l.duree.startsWith('~'))
     && lignesClips.filter(l => !l.inconnu).length >= 2
     && !lignesClips.find(l => l.inconnu).duree.startsWith('~')
     && !f.total.startsWith('~'),
     JSON.stringify({ total: f.total, lignes: lignesClips.map(l => [l.nom, l.duree]) }));
  ok('…la part antérieure au premier clip s\'estompe, elle, sur TOUTE sa largeur',
     f.parts[0].flou === true && parseFloat(f.parts[0].large) === 100
     && f.parts[0].vers === f.parts[1].couleur,
     JSON.stringify({ large: f.parts[0].large, vers: f.parts[0].vers,
                      premiere: f.parts[1].couleur }));
  ok('…tandis que la part en cours n\'a pas de borne après elle',
     f.parts[2].flou === false,
     JSON.stringify(f.parts.map(p => ({ inconnu: p.inconnu, flou: p.flou }))));
  /* AUCUNE PART N'EST HACHURÉE, PAS MÊME L'INCONNUE. C'est une frise de clips,
     celle qui l'était le plus : ses parts ET sa part inconnue portaient chacune
     leur propre hachure. Zéro sur les trois, et le contrôle vaut pour toutes
     les frises puisque c'est ici qu'il y en avait le plus. */
  ok('…et plus aucune part n\'est hachurée, sur la frise qui l\'était le plus',
     f.parts.every(p => !p.hachuree),
     JSON.stringify(f.parts.map(p => p.hachuree)));

  const b = await page.evaluate(() => window.tse.panneau.rapport().reseau.chapitres);
  ok('le rapport compte la troisième porte à part, par issue',
     b.clips === 1 && b.clipsServis === 1
     && b.clipsServis + b.clipsHorsSujet + b.clipsRefus + b.clipsErreur === b.clips,
     JSON.stringify(b));
  await page.close();

  /* ── ET QUAND LE SCHÉMA REFUSE ───────────────────────────────────────── */
  {
    const p2 = await freshTwitch();
    await p2.evaluate((d) => {
      window.__fx = { sansvod: { id: 'sv2', createdAt: new Date(d).toISOString(),
                                 viewers: 1200, game: 'Hades II', tags: [] } };
      window.__addCard('sansvod', 'Hades II', '1,2 k');
      window.__vod = { sansvod: 'sansvod' }; window.__vodRecent = {};
      window.__clips = { sansvod: 'erreur' };
    }, DEBUT);
    // La forme en jeu AVANT le refus : c'est son changement qu'on éprouve.
    const avantForme = await p2.evaluate(() =>
      window.tse.panneau.rapport().reseau.chapitres.clipsForme);
    await attendre(p2, () => document.querySelectorAll('[data-tse-viewers]').length === 1);
    await hoverLogin(p2, 'sansvod');
    await attendre(p2,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
    await wait(p2, 1500);
    ok('un refus se solde par le silence, jamais par une frise inventée',
       (await p2.evaluate(() => !!document.querySelector('.tse-preview__frise'))) === false);
    const b2 = await p2.evaluate(() => window.tse.panneau.rapport().reseau.chapitres);
    /* UNE RÉPONSE ARRIVÉE ET PORTEUSE D'ERREURS N'EST PAS UN INCIDENT RÉSEAU,
       et les confondre a coûté cinq tentatives identiques : Twitch a répondu
       cinq fois « server error » à la même forme de requête, et l'extension
       l'a redemandée telle quelle à chaque chaîne. Le refus doit se compter
       comme un refus — et faire AVANCER le candidat. */
    ok('…et il est consigné comme REFUS, non comme incident réseau',
       b2.clips === 1 && b2.clipsRefus === 1 && b2.clipsErreur === 0
       && b2.clipsServis === 0 && b2.clipsHorsSujet === 0,
       JSON.stringify(b2));
    ok('…et la forme essayée a changé : on ne redemande pas la même',
       typeof b2.clipsForme === 'string' && b2.clipsForme !== avantForme,
       `${avantForme} puis ${b2.clipsForme}`);
    await p2.close();
  }
}

titre('88. Les bornes de mémoire — celle qui manquait, celle qui ne couvrait qu\'un cas');
{
  /* DEUX OMISSIONS DE LA MÊME FAMILLE, trouvées par un audit et non par une
     panne. C'est exactement pourquoi ce scénario existe : rien ne les avait
     signalées, et rien n'empêchait la seconde de revenir.

     LE MÉMO DE CHAPITRES N'AVAIT AUCUN PLAFOND. Une entrée par diffusion
     survolée — jusqu'à trente segments chacune quand la source est les clips
     — et jamais rien qui l'efface : le TTL décide de REDEMANDER, pas
     d'oublier, et `preludeDe` lit ce registre sans le consulter, à dessein,
     le passé d'un direct ne se dément pas. Tous ses pairs sont bornés
     (LIVE_CACHE_MAX, META_CACHE_MAX, GS_CACHE_MAX, CATEGORY_TRAIL_MAX,
     CAT_LANGUE_MAX, CATEGORY_SWITCH_MAX). Il était le seul à ne pas l'être —
     et le seul dont l'occupation n'était pas au rapport. Les deux vont
     ensemble : une borne qu'on ne peut pas observer ne se vérifie pas.

     LA RÉINSERTION DES FRISES NE COUVRAIT QU'UN CAS SUR DEUX. Écrite pour la
     frise qu'on POURSUIT, elle laissait celle d'une chaîne qui REDÉMARRE une
     diffusion passer par un `set` sec sur une clé déjà présente — que `Map`
     ne déplace pas. Une chaîne suivie de longue date qui relance un direct
     gardait donc la position la plus ANCIENNE et serait sortie la première,
     à l'instant même où on venait de l'observer. */
  const page = await freshTwitch();
  const DEBUT = Date.now() - 240 * 60_000;          // live commencé il y a 4 h
  await page.evaluate((d) => {
    const iso = new Date(d).toISOString();
    window.__fx = {
      archive:  { id: 'st-arch', createdAt: iso, viewers: 3000, game: 'Hades II',     tags: [] },
      immobile: { id: 'st-imm',  createdAt: iso, viewers: 2000, game: 'Just Chatting', tags: [] },
      muette:   { id: 'st-mue',  createdAt: iso, viewers: 1000, game: 'Hades II',     tags: [] },
    };
    window.__addCard('archive',  'Hades II',      '3 k');
    window.__addCard('immobile', 'Just Chatting', '2 k');
    window.__addCard('muette',   'Hades II',      '1 k');
    /* TROIS ISSUES DIFFÉRENTES, et le mémo doit garder les trois. Mémoriser
       un ÉCHEC est tout son intérêt : sans cela, chaque survol relancerait la
       même requête pour la même réponse vide. */
    window.__vod = {
      archive: { createdAt: iso, chapitres: [{ pos: 0, jeu: 'Just Chatting' },
                                             { pos: 60 * 60_000, jeu: 'Hades II' }] },
      immobile: 'vide',        // archive bien là, mais aucun changement de jeu
      muette:   'sansvod',     // n'archive pas — et sans clip, la porte se ferme
    };
    window.__vodRecent = {}; window.__clips = {};
  }, DEBUT);
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 3);

  const chap = () => page.evaluate(() => window.tse.panneau.rapport().reseau.chapitres);
  const survoler = async (login) => {
    await hoverLogin(page, login);
    await attendre(page,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
    await page.evaluate((l) => {
      const c = [...document.querySelectorAll('.side-nav-card')]
        .find(x => x.dataset.tseLogin === l);
      c.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
    }, login);
    await attendre(page,
      () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);
  };

  for (const l of ['archive', 'immobile', 'muette']) await survoler(l);
  await attendre(page, () => window.tse.panneau.rapport().reseau.chapitres.demandes >= 3, 12_000);
  const b1 = await chap();
  ok('trois diffusions survolées, trois entrées au mémo — les issues muettes comprises',
     b1.demandes === 3 && b1.resident === 3, JSON.stringify(b1));
  /* LA BORNE ET SON TÉMOIN. `resident` contre `max`, sur le modèle de
     `frise: { resident, max }` — c'était la seule structure du produit dont
     l'occupation n'apparaissait nulle part. */
  ok('…et le rapport DIT ce que le mémo occupe, et pour quelle borne',
     Number.isInteger(b1.resident) && Number.isInteger(b1.max)
     && b1.max > 0 && b1.resident <= b1.max, JSON.stringify(b1));

  /* LE MÉMO SERT, ET IL SERT LES DEUX FORMES. « archive » repasse par
     `preludeDe`, qui trouve des segments ; « muette » n'en a aucun et repasse
     par le TTL de `fetchChapitres`. Deux chemins distincts, une seule
     exigence : aucune requête de plus, aucune entrée de plus. */
  await survoler('archive');
  await survoler('muette');
  await wait(page, 800);
  const b2 = await chap();
  ok('re-survolées, elles ne coûtent plus rien : ni requête, ni entrée',
     b2.demandes === 3 && b2.resident === 3, JSON.stringify(b2));
  await page.close();

  /* ── CE QU'UN BANC RAISONNABLE NE PEUT PAS ÉPROUVER, ET QU'IL DIT ────────
     Faire tomber l'une ou l'autre de ces bornes demanderait trois cents
     diffusions survolées et cinq cent une chaînes en cache. Le scénario 82 a
     déjà tranché cette question pour le registre des frises, et sa conclusion
     vaut ici : on ne publie pas vert un scénario qui coûte une minute pour un
     renseignement qu'une lecture donne. Ce qui garde la porte est donc écrit
     à l'endroit où la faute se commet — dans la forme du code d'écriture,
     seule chose qu'une régression future toucherait forcément. */
  {
    const src = readFileSync(join(ICI, '..', 'content.js'), 'utf8');

    const max = /CHAPITRES_MAX:\s*(\d+)/.exec(src);
    ok('le mémo de chapitres a une borne, déclarée avec ses pairs',
       !!max && Number(max[1]) > 0, max ? max[0] : '(CHAPITRES_MAX absent de CFG)');

    /* `retenir` est le SEUL point d'écriture du mémo : la borne y tient donc
       à tout instant, et non seulement au réveil d'un minuteur. */
    const ret = /const retenir = [\s\S]*?\n    \};/.exec(src);
    const corps = ret ? ret[0] : '';
    ok('…tenue à l\'écriture, contre CFG.CHAPITRES_MAX',
       /while\s*\(chapitres\.size > CFG\.CHAPITRES_MAX\)/.test(corps)
       && /chapitres\.delete\(chapitres\.keys\(\)\.next\(\)\.value\)/.test(corps),
       corps ? '(borne absente de retenir)' : '(retenir introuvable)');
    /* Sans la réinsertion, la purge sortirait l'entrée apprise en PREMIER
       plutôt que la moins récemment apprise — la faute même que le registre
       des frises a payée. */
    ok('…et l\'entrée est réinsérée avant d\'être écrite, sinon la purge vise à l\'envers',
       corps.indexOf('chapitres.delete(streamId)') >= 0
       && corps.indexOf('chapitres.delete(streamId)') < corps.indexOf('chapitres.set(streamId'),
       corps ? '(réinsertion absente)' : '(retenir introuvable)');

    /* LA RÉINSERTION DES FRISES DOIT PRÉCÉDER L'AIGUILLAGE. Placée dans une
       seule branche, elle ne couvre que la frise qu'on poursuit ; placée
       avant, elle couvre aussi celle qui redémarre. Un `set` resté dans une
       branche ramènerait exactement le défaut corrigé. */
    /* LA TRANCHE COMMENCE À `let f`, ET CE N'EST PAS UN DÉTAIL. Plus haut dans
       la même fonction, le chemin hors-ligne porte son propre
       `frises.delete(login)` — celui qui retire la frise d'un stream fini.
       Chercher la première occurrence dans toute la fonction tombait donc sur
       CELUI-LÀ, et l'assertion restait verte même en remettant la réinsertion
       dans la branche. Elle passait sans rien prouver ; la mutation l'a dit. */
    const sc = /const suivreCategorie = [\s\S]*?const friseACombler/.exec(src);
    const entier = sc ? sc[0] : '';
    const bloc = entier.slice(entier.indexOf('let f = frises.get(login);'));
    const iDel = bloc.indexOf('frises.delete(login)');
    const iBranche = bloc.indexOf('if (!f || (f.streamId !== id && !memeDirect))');
    ok('le registre des frises réinsère AVANT l\'aiguillage, donc dans les deux cas',
       iDel >= 0 && iBranche >= 0 && iDel < iBranche,
       `delete@${iDel} branche@${iBranche}`);
    ok('…et il n\'écrit qu\'une fois, hors de toute branche',
       (bloc.match(/frises\.set\(login, f\)/g) || []).length === 1,
       `${(bloc.match(/frises\.set\(login, f\)/g) || []).length} écriture(s)`);
  }
}

titre('89. Le panneau dessine — la semaine des visites, la courbe des retards');
{
  /* DEUX VUES QUI NE SE TABULENT PAS, et deux pièges qu'elles ont révélés.

     LE PREMIER TIENT AU PANNEAU LUI-MÊME. Il affichait « rien à afficher » dès
     qu'une section ne portait aucune LIGNE — ce qui était vrai tant que toute
     section était un tableau. Le rythme n'en est pas un : sa semaine EST le
     contenu, et il n'a ni colonne ni ligne. La vacuité se juge donc désormais
     sur les deux, et c'est la première chose qu'on éprouve ici.

     LE SECOND EST UN DÉFAUT DE DESSIN, trouvé en photographiant la courbe sur
     un décor réaliste. En abscisse LINÉAIRE, deux relevés lointains — une
     demi-heure, quand la masse tient sous deux minutes — écrasaient toute la
     distribution dans les trois premiers pour cent de la largeur. La cumulée
     ne dégénère pas en ordonnée, mais elle dégénère en abscisse dès que la
     queue est lourde, et une distribution de latences l'est toujours.
     L'assertion qui garde cette porte mesure exactement cela : où tombe la
     médiane sur la largeur du tracé. */
  const semaine = () => {
    const g = Array.from({ length: 7 }, () => new Array(24).fill(0));
    g[3][21] = 9;      // le pic
    g[3][20] = 3;
    g[1][9]  = 1;      // une seule visite : un palier, mais pas le dernier
    return g;
  };
  /* Une masse sous deux minutes et deux traînards à une demi-heure : le décor
     exact qui avait mis la première version de la courbe en défaut. */
  const retards = [];
  for (let i = 0; i < 120; i++) retards.push(2000 + Math.round(i * 900));
  retards.push(1_800_000, 2_100_000);

  const stub = ([msg, grille, retards]) => {
    const T = (k, sub) => {
          const m = msg[k] ? msg[k].message : k;
          if (sub === undefined || sub === null) return m;
          const args = Array.isArray(sub) ? sub : [sub];
          return String(m).replace(/\$(\d)/g,
            (t, i) => (args[i - 1] === undefined ? t : String(args[i - 1])));
        };
    const paquet = (colonnes, lignes, resume, extra) =>
      ({ ok: true, data: { colonnes, lignes, resume, ...(extra || {}) } });
    const trie = retards.slice().sort((a, b) => a - b);
    const q = (p) => trie[Math.min(trie.length - 1, Math.floor(trie.length * p))];
    const REPONSES = {
      rythme: () => paquet([], [], { visites: 13, chaines: 4,
                                     pic: { jour: 3, heure: 21, n: 9 },
                                     premier: Date.now() - 20 * 86_400_000,
                                     dernier: Date.now() }, { grille }),
      lag: () => paquet(['login', 'lag', 'gain', 'ts'],
        retards.map((l, i) => ({ login: 'ch' + i, lag: l, gain: null, ts: Date.now() })),
        { mesures: retards.length, medianeLag: q(0.5), p90Lag: q(0.9),
          gains: 0, medianeGain: null }),
      /* Trois relevés : le tableau les montre, la courbe se tait. Quatre
         marches ne sont pas une distribution. */
      cycles: () => paquet(['login', 'lag', 'gain', 'ts'],
        [{ login: 'a', lag: 1000, gain: null, ts: Date.now() },
         { login: 'b', lag: 2000, gain: null, ts: Date.now() },
         { login: 'c', lag: 3000, gain: null, ts: Date.now() }],
        { evenements: 3, verrous: [] }),
    };
    window.chrome = {
      i18n: { getMessage: T, getUILanguage: () => 'fr' },
      tabs: { query: () => Promise.resolve([{ id: 1 }]) },
      runtime: {
        getManifest: () => ({ version: '9.9.9' }),
        sendMessage: (m) => {
          if (m.type === 'tse-panneau-etat') return Promise.resolve({ ok: true, ponts: [1] });
          const f = REPONSES[m.section];
          return Promise.resolve(f ? f() : paquet(['login'], [], {}));
        },
      },
    };
  };

  const messages = JSON.parse(readFileSync(join(ICI, '..', '_locales', 'fr', 'messages.json'), 'utf8'));
  const page = await browser.newPage({ viewport: { width: 760, height: 580 } });
  page.on('pageerror', (e) => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
  await page.addInitScript(stub, [messages, semaine(), retards]);
  await page.goto(pathToFileURL(join(ICI, '..', 'panneau.html')).href);
  await attendre(page, () => document.querySelectorAll('.rail-item').length > 0);

  const aller = async (id) => {
    await page.evaluate((i) => [...document.querySelectorAll('.rail-item')]
      .find((b) => b.dataset.id === i).click(), id);
    await attendre(page, () => document.getElementById('message').hidden
                            || !document.getElementById('visuel').hidden, 6000);
  };

  /* ── LA SEMAINE ────────────────────────────────────────────────────────── */
  await aller('rythme');
  const sem = await page.evaluate(() => {
    const cases = [...document.querySelectorAll('.rythme-grille .rythme-case')];
    const palier = (el) => {
      const m = /rythme-case--(\d)/.exec(el.className);
      return m ? Number(m[1]) : 0;
    };
    return {
      cases: cases.length,
      jours: document.querySelectorAll('.rythme-jour').length,
      heures: [...document.querySelectorAll('.rythme-heure')].filter(e => e.textContent).length,
      paliers: cases.map(palier),
      barres: document.querySelectorAll('.rythme-barre').length,
      hauteurs: [...document.querySelectorAll('.rythme-barre')].map(b => parseFloat(b.style.height)),
      messageCache: document.getElementById('message').hidden,
      tableauCache: document.getElementById('tableau-cadre').hidden,
      infobulle: cases.filter(c => c.title).length,
    };
  });
  ok('la semaine se dessine : sept jours, vingt-quatre heures, cent soixante-huit cases',
     sem.cases === 168 && sem.jours === 7 && sem.heures === 8, JSON.stringify(
       { cases: sem.cases, jours: sem.jours, heures: sem.heures }));
  /* SANS CETTE ASSERTION, LE PANNEAU DIRAIT « RIEN À AFFICHER » AU-DESSUS
     D'UNE GRILLE PLEINE. C'est le défaut que la section a révélé : la
     vacuité se jugeait sur les seules lignes. */
  ok('…une section sans tableau n\'est pas une section vide',
     sem.messageCache === true && sem.tableauCache === true, JSON.stringify(
       { message: sem.messageCache, tableau: sem.tableauCache }));
  const pleins = sem.paliers.filter((p) => p > 0);
  ok('…et les paliers distinguent le vide, le peu et le pic',
     sem.paliers.filter((p) => p === 4).length === 1
     && pleins.length === 3
     && pleins.filter((p) => p > 0 && p < 4).length === 2,
     JSON.stringify(sem.paliers.filter(Boolean)));
  ok('…chaque case porte sa valeur en infobulle, la couleur n\'étant pas une donnée',
     sem.infobulle === 168, `${sem.infobulle} case(s) sur 168`);
  /* LE PROFIL EST LA PROJECTION DE LA GRILLE, et non un second dessin : la
     colonne de 21 h pèse neuf visites, celle de 9 h une seule. */
  ok('le profil horaire projette la grille : 21 h domine 9 h dans le même rapport',
     sem.barres === 24 && sem.hauteurs[21] === 100
     && Math.abs(sem.hauteurs[9] - 100 / 9) < 0.5,
     JSON.stringify({ h21: sem.hauteurs[21], h9: sem.hauteurs[9] }));

  /* ── LA COURBE ─────────────────────────────────────────────────────────── */
  await aller('lag');
  const cb = await page.evaluate(() => {
    const svg = document.querySelector('.courbe');
    if (!svg) return null;
    const d = svg.querySelector('.courbe-trait').getAttribute('d');
    const pts = d.split(/[ML]/).filter(Boolean)
      .map((p) => p.split(',').map(Number));
    const verticales = [...svg.querySelectorAll('.courbe-repere')]
      .filter((l) => l.getAttribute('x1') === l.getAttribute('x2'))
      .map((l) => Number(l.getAttribute('x1'))).sort((a, b) => a - b);
    return { pts, verticales,
             graduations: [...svg.querySelectorAll('.courbe-texte')].map(t => t.textContent) };
  });
  ok('la courbe existe et ne redescend jamais : une cumulée ne peut que monter',
     cb !== null && cb.pts.every((p, i) => i === 0 || p[1] <= cb.pts[i - 1][1] + 0.05),
     cb ? `${cb.pts.length} points` : '(aucune courbe)');
  ok('…elle atteint le bord droit à 100 %, sans diagonale de fermeture',
     cb.pts[cb.pts.length - 1][0] === 540 && cb.pts[cb.pts.length - 1][1] === 10,
     JSON.stringify(cb.pts[cb.pts.length - 1]));
  /* L'ASSERTION QUI GARDE L'AXE. Sur ce décor, la médiane vaut environ une
     minute et le maximum trente-cinq : en abscisse linéaire elle tomberait à
     moins de trois pour cent de la largeur, illisible. En logarithmique elle
     se pose au-delà du tiers. Le seuil est choisi loin des deux valeurs pour
     que l'assertion dise « lisible » et non « exactement ceci ». */
  const largeur = 540 - 6;
  ok('…et deux traînards n\'écrasent pas la masse : la médiane reste lisible',
     cb.verticales.length === 2 && (cb.verticales[0] - 6) / largeur > 0.25,
     JSON.stringify(cb.verticales.map((x) => Math.round((x - 6) / largeur * 100) + ' %')));
  ok('…l\'axe est gradué en durées rondes, pas en puissances de dix',
     cb.graduations.some((t) => /^1 min$/.test(t)) && !cb.graduations.some((t) => /00$/.test(t)),
     JSON.stringify(cb.graduations));

  /* ── SOUS CINQ RELEVÉS, PAS DE COURBE ──────────────────────────────────── */
  await aller('cycles');
  const maigre = await page.evaluate(() => ({
    courbe: !!document.querySelector('.courbe'),
    lignes: document.querySelectorAll('.tableau tbody tr').length,
  }));
  ok('trois relevés se tabulent et ne se courbent pas',
     maigre.courbe === false && maigre.lignes === 3, JSON.stringify(maigre));
  await page.close();
}

titre('90. La frise d\'un subathon — une ligne par catégorie, pas par basculement');
{
  /* LE CAS VIENT D'UN UTILISATEUR, ET IL EST RÉEL. Une chaîne en subathon :
     un direct qui ne s'arrête pas. Trente et une heures sur la capture reçue,
     quinze basculements, dont HUIT retours à « Discussions » — entre deux
     jeux, une streameuse repasse par sa catégorie de discussion. La frise
     comptait chaque retour comme une entrée neuve et faisait deux fois la
     hauteur de la vignette.

     ET LA LISTE N'ÉTAIT PAS BORNÉE. CATEGORY_TRAIL_SEGMENTS plafonne le
     registre OBSERVÉ à douze ; les chapitres du VOD, eux, arrivent tous. D'où
     quinze lignes là où douze étaient la limite supposée — et cent sur une
     diffusion de plusieurs jours. Ce scénario tient les deux bouts : ce que la
     liste montre, et ce que le ruban supporte.

     LES DURÉES SONT CELLES DE LA CAPTURE, à la minute près, de sorte que les
     sommes attendues ci-dessous soient vérifiables à la main. */
  const MIN = 60_000;
  const SUB = [
    ['Just Chatting', 14], ['We Were Here Together', 177], ['Just Chatting', 96],
    ['Watch Your Plastic Duck', 434], ['Just Chatting', 88], ['ROBLOX', 160],
    ['Just Chatting', 166], ['Grounded 2', 1], ['How to Fish', 297],
    ['Just Chatting', 17], ['A Weird Game About Sausage', 204], ['Just Chatting', 5],
    ['Welcome to Elderfield', 80], ['Just Chatting', 60], ['Watch Your Plastic Duck', 68],
  ];
  const TOTAL_MIN = SUB.reduce((n, s) => n + s[1], 0);          // 1867 = 31 h 07

  const page = await freshTwitch();
  await page.evaluate(([SUB, TOTAL_MIN, MIN]) => {
    const debut = Date.now() - TOTAL_MIN * MIN;
    const iso = (t) => new Date(t).toISOString();
    /* Positions cumulées : le chapitre n° i commence à la somme des durées
       qui le précèdent. Le dernier court jusqu'à maintenant. */
    let pos = 0;
    const chapitres = SUB.map(([jeu, min]) => {
      const c = { pos: pos * MIN, jeu };
      pos += min;
      return c;
    });
    /* Douze catégories DISTINCTES : au-delà de la palette, le repli entre en
       jeu. La dernière est la plus COURTE et se trouve être celle en cours —
       elle doit survivre au repli malgré sa durée. */
    const variete = Array.from({ length: 12 }, (_, k) => ({
      pos: k * 100 * MIN, jeu: 'Jeu ' + (k + 1),
    }));
    /* CENT SOIXANTE BASCULEMENTS, ET LE NOMBRE EST MESURÉ, PAS CHOISI. Le
       ruban fait 456 px dans un popup de 480 ; sous l'ancienne largeur
       plancher de quatre pixels, il faut donc dépasser 114 traits pour qu'il
       déborde. Une première rédaction en posait cent : l'assertion passait —
       et elle passait SANS RIEN PROUVER, quatre cents pixels tenant encore
       dans quatre cent cinquante-six. La mutation l'a dit. Cent soixante
       traits demandent 644 px sous l'ancienne règle : le débordement est
       alors certain, et c'est lui qu'on mesure.

       Ce n'est pas un décor extravagant : un subathon de deux semaines à
       une douzaine de basculements par jour y arrive. */
    const cent = Array.from({ length: 160 }, (_, k) => ({
      pos: k * 30 * MIN, jeu: k % 2 ? 'Just Chatting' : 'Jeu ' + (k % 9),
    }));

    window.__fx = {
      mouse:  { id: 's-mouse',  createdAt: iso(debut), viewers: 8400,
                game: 'Watch Your Plastic Duck', tags: [] },
      simple: { id: 's-simple', createdAt: iso(Date.now() - 155 * MIN), viewers: 900,
                game: 'VALORANT', tags: [] },
      varie:  { id: 's-varie',  createdAt: iso(Date.now() - 1200 * MIN), viewers: 700,
                game: 'Jeu 12', tags: [] },
      cent:   { id: 's-cent',   createdAt: iso(Date.now() - 4830 * MIN), viewers: 600,
                game: 'Jeu 1', tags: [] },
    };
    window.__addCard('mouse',  'Watch Your Plastic Duck', '8,4 k');
    window.__addCard('simple', 'VALORANT', '900');
    window.__addCard('varie',  'Jeu 12', '700');
    window.__addCard('cent',   'Jeu 1', '600');
    window.__vod = {
      mouse:  { createdAt: iso(debut), chapitres },
      // Deux catégories, aucun retour : le cas ordinaire ne doit RIEN payer.
      simple: { createdAt: iso(Date.now() - 155 * MIN),
                chapitres: [{ pos: 0, jeu: 'League of Legends' },
                            { pos: 95 * MIN, jeu: 'VALORANT' }] },
      varie:  { createdAt: iso(Date.now() - 1200 * MIN), chapitres: variete },
      cent:   { createdAt: iso(Date.now() - 4830 * MIN), chapitres: cent },
    };
    window.__vodRecent = {}; window.__clips = {};
  }, [SUB, TOTAL_MIN, MIN]);
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 4);

  const lire = async (login) => {
    await hoverLogin(page, login);
    await attendre(page,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
    await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 9000);
    const vu = await page.evaluate(() => {
      const bloc = document.querySelector('.tse-preview__frise');
      if (!bloc) return null;
      const barre = bloc.querySelector('.tse-preview__frise-barre');
      const l0 = bloc.querySelector('.tse-preview__frise-ligne');
      const n0 = l0.querySelector('.tse-preview__frise-nom');
      const f0 = l0.querySelector('.tse-preview__frise-fois');
      const d0 = l0.querySelector('.tse-preview__frise-duree');
      return {
        total: bloc.querySelector('.tse-preview__frise-total').textContent,
        parts: barre.querySelectorAll('.tse-preview__frise-part').length,
        debord: Math.round(barre.scrollWidth - barre.clientWidth),
        /* AUCUNE BORNE ESTOMPÉE sur une frise de chapitres : chaque heure y
           est donnée par Twitch, et un fondu y avouerait un doute qu'on n'a
           pas. Le compte doit être exactement zéro. */
        flous: barre.querySelectorAll('.tse-preview__frise-part--flou').length,
        /* LA GÉOMÉTRIE DE LA PREMIÈRE LIGNE, MESURÉE SUR LE TEXTE ET NON SUR
           LA BOÎTE. C'est la correction que la mutation a imposée : sous
           l'ancienne règle, la boîte du nom s'étirait sur tout l'espace libre
           — 392 px pour un texte de soixante-dix — et le « ×7 » suivait cette
           boîte à cinq pixels. Comparer les BORDS DE BOÎTE donnait donc cinq
           pixels dans les deux cas, et l'assertion passait sans rien prouver.
           Ce qui se voit est la distance au TEXTE : une plage la donne, une
           boîte ne la donne pas. */
        ecartNom: f0 && n0 ? (() => {
          const t = [...n0.childNodes].find(x => x.nodeType === 3);
          if (!t) return null;
          const r = document.createRange(); r.selectNodeContents(t);
          return Math.round(f0.getBoundingClientRect().left - r.getBoundingClientRect().right);
        })() : null,
        ecartDuree: f0 && d0 ? Math.round(d0.getBoundingClientRect().left
                                          - f0.getBoundingClientRect().right) : null,
        /* L'ÉCART DE LIGNE DE BASE entre le « ×N » et le nom qu'il compte. Le
           « ×N » est écrit plus petit ; centrés verticalement, deux corps
           différents ne reposent pas sur la même ligne. La sonde est une boîte
           de hauteur nulle en « vertical-align: baseline », dont le bord
           inférieur EST la ligne de base — comparer des rectangles de glyphes
           de corps différents ne dirait rien, leurs bas ne coïncidant jamais. */
        ecartBase: (f0 && n0) ? (() => {
          const sonde = () => { const i = document.createElement('i');
            i.style.cssText = 'display:inline-block;width:0;height:0;vertical-align:baseline';
            return i; };
          const a = sonde(), b = sonde();
          n0.appendChild(a); f0.appendChild(b);
          const d = b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom;
          a.remove(); b.remove();
          return +d.toFixed(2);
        })() : null,
        bordDuree: d0 && barre ? Math.round(barre.getBoundingClientRect().right
                                            - d0.getBoundingClientRect().right) : null,
        lignes: [...bloc.querySelectorAll('.tse-preview__frise-ligne')].map((l) => ({
          nom: l.querySelector('.tse-preview__frise-nom').textContent,
          duree: l.querySelector('.tse-preview__frise-duree')?.textContent || '',
          fois: l.querySelector('.tse-preview__frise-fois')?.textContent || '',
          teinte: l.querySelector('.tse-preview__frise-puce').style.backgroundColor,
          encours: l.classList.contains('tse-preview__frise-ligne--encours'),
          autres: l.classList.contains('tse-preview__frise-ligne--autres'),
        })),
      };
    });
    await page.evaluate((l) => {
      const c = [...document.querySelectorAll('.side-nav-card')].find(x => x.dataset.tseLogin === l);
      c.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
    }, login);
    await attendre(page,
      () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);
    return vu;
  };

  /* ── LE SUBATHON ────────────────────────────────────────────────────────── */
  const sub = await lire('mouse');
  ok('quinze basculements ne font plus quinze lignes, mais huit catégories',
     sub !== null && sub.lignes.length === 8 && sub.parts === 15,
     sub ? `${sub.lignes.length} ligne(s), ${sub.parts} trait(s)` : '(aucune frise)');
  /* LA SOMME EST LE RENSEIGNEMENT QUE LA LISTE NE DONNAIT PAS. Sept passages
     par « Discussions » pèsent 7 h 26 ; deux par Plastic Duck, 8 h 22 — un
     chiffre que personne n'additionnait. */
  const parNom = Object.fromEntries(sub.lignes.map((l) => [l.nom, l]));
  ok('…chaque catégorie porte la SOMME de ses passages, et leur nombre',
     parNom.Discussions?.duree === '7h26' && parNom.Discussions?.fois === '×7'
     && parNom['Watch Your Plastic Duck']?.duree.startsWith('8h22')
     && parNom['Watch Your Plastic Duck']?.fois === '×2',
     JSON.stringify(sub.lignes.map((l) => [l.nom, l.duree, l.fois])));
  /* L'ORDRE EST CELUI DE LA PREMIÈRE APPARITION, et il n'est pas décoratif :
     c'est ce qui permet de suivre le ruban de gauche à droite et de retrouver
     les lignes dans le même ordre. Un tri par durée mettrait Plastic Duck en
     tête et casserait la correspondance. */
  ok('…dans l\'ordre de PREMIÈRE apparition, celui du ruban',
     sub.lignes.map((l) => l.nom).join(' → ')
       === 'Discussions → We Were Here Together → Watch Your Plastic Duck → ROBLOX'
        + ' → Grounded 2 → How to Fish → A Weird Game About Sausage → Welcome to Elderfield',
     JSON.stringify(sub.lignes.map((l) => l.nom)));
  ok('…une seule ligne est « en cours », et c\'est la catégorie du moment',
     sub.lignes.filter((l) => l.encours).length === 1
     && sub.lignes.find((l) => l.encours).nom === 'Watch Your Plastic Duck',
     JSON.stringify(sub.lignes.filter((l) => l.encours).map((l) => l.nom)));
  ok('…et le total couvre bien les trente et une heures',
     sub.total === '31h07', sub.total);
  /* ── LE « ×N » APPARTIENT AU NOM, PAS À LA DURÉE ─────────────────────────
     Il était rejeté contre la colonne des durées : le nom portait
     « flex: 1 1 auto » et prenait tout l'espace libre, si bien que « ×7 » se
     retrouvait à l'autre bout de la ligne, à trois centimètres de la
     catégorie qu'il compte. « Discussions ×7 » est UNE information ; la
     couper en deux morceaux éloignés obligeait l'œil à faire le chemin.

     LA MESURE PORTE SUR LE TEXTE, et c'est la mutation qui l'a exigé. Écrite
     sur les bords de boîte, elle rendait cinq pixels quelle que soit la règle
     — la boîte du nom s'étirant avec l'espace libre, le « ×7 » la suit de près
     tout en étant loin du mot. L'assertion passait alors sans rien prouver, et
     j'ai failli en conclure que la correction était inutile. Sur le texte,
     l'écart vaut cinq pixels avec la règle et plus de trois cents sans elle. */
  ok('« ×7 » se lit contre le nom qu\'il compte, et non contre la durée',
     sub.ecartNom !== null && sub.ecartNom < sub.ecartDuree && sub.ecartNom <= 6,
     JSON.stringify({ auNom: sub.ecartNom, aLaDuree: sub.ecartDuree }));
  /* ── ET IL REPOSE SUR LA MÊME LIGNE QUE LUI ──────────────────────────────
     Un utilisateur l'a vu avant le banc : « les ×8 ou ×2 ne sont pas bien
     alignés avec les catégories ». Le « ×N » fait 10,5 px contre 12 pour le
     nom ; la rangée les centrait, et deux corps différents centrés ne reposent
     pas sur la même ligne — mesuré, 0,81 px d'écart. Moins d'un pixel, et
     parfaitement visible, parce qu'une liste en donne huit exemplaires l'un
     sous l'autre et que l'œil lit la colonne, pas la ligne. On exige donc
     l'égalité STRICTE des lignes de base. */
  ok('…et il repose EXACTEMENT sur la ligne de base du nom, malgré son corps plus petit',
     sub.ecartBase === 0, `${sub.ecartBase} px d'écart de ligne de base`);
  /* ET LA COLONNE DES DURÉES NE BOUGE PAS. C'est elle que l'œil parcourt
     verticalement ; le nom ne la poussait plus une fois qu'il a cessé de
     s'étirer, d'où le « margin-left: auto » qui la remet au bord. */
  ok('…et la durée reste collée au bord droit, comme la colonne l\'exige',
     sub.bordDuree === 0, `${sub.bordDuree} px du bord`);
  /* SUR UNE FRISE DE CHAPITRES, RIEN NE S'ESTOMPE — pas même la part en tête.
     Le VOD donne l'heure du premier changement comme celle des suivants : il
     n'y a aucune borne douteuse à avouer, et en dessiner une serait avouer un
     doute qu'on n'a pas. C'est l'exact pendant de la frise de clips, où deux
     parts sur trois s'estompent. */
  ok('…aucune borne n\'est estompée : les chapitres donnent l\'heure exacte',
     sub.flous === 0, `${sub.flous} part(s) estompée(s)`);
  /* ET AUCUNE VAGUE NON PLUS. Le pendant de l'assertion des clips : une frise
     de chapitres donne des heures, pas des approches. Sans ce contrôle, un
     préfixe posé sur toutes les frises passerait pour une correction. */
  ok('…ni aucune vague : une durée de chapitre n\'est pas une approche',
     sub.lignes.every(l => !l.duree.startsWith('~')),
     JSON.stringify(sub.lignes.map(l => l.duree)));

  /* ── LE CAS ORDINAIRE NE PAIE RIEN ──────────────────────────────────────── */
  const simple = await lire('simple');
  ok('un direct sans retour rend exactement ce qu\'il rendait : deux lignes, aucun « × »',
     simple.lignes.length === 2 && simple.parts === 2
     && simple.lignes.every((l) => l.fois === ''),
     JSON.stringify(simple.lignes.map((l) => [l.nom, l.duree, l.fois])));

  /* ── AU-DELÀ DE LA PALETTE, LE REPLI ────────────────────────────────────── */
  const varie = await lire('varie');
  const repli = varie.lignes.find((l) => l.autres);
  ok('douze catégories distinctes : huit lignes, puis une ligne de repli',
     varie.lignes.length === 9 && !!repli && repli.duree !== '',
     JSON.stringify(varie.lignes.map((l) => [l.nom, l.duree])));
  /* LA CATÉGORIE EN COURS SURVIT AU REPLI, quelle que soit sa durée. Ici elle
     est la DERNIÈRE et la plus courte : triée sur la seule durée, elle serait
     tombée — et le survol n'aurait plus répondu à la question qu'on lui pose. */
  ok('…la catégorie EN COURS est gardée même quand elle est la plus courte',
     varie.lignes.some((l) => l.encours && !l.autres),
     JSON.stringify(varie.lignes.map((l) => [l.nom, l.encours])));
  /* LE DÉFAUT QUE LA CAPTURE A TROUVÉ. La palette s'épuise à huit ; servie
     dans l'ordre chronologique, elle donnait à une ligne AFFICHÉE la teinte
     d'une autre ligne affichée. Une légende dont deux entrées se ressemblent
     ne légende plus rien. */
  const teintes = varie.lignes.filter((l) => !l.autres).map((l) => l.teinte);
  ok('…et les huit lignes affichées ont huit teintes DISTINCTES',
     teintes.length === 8 && new Set(teintes).size === 8,
     JSON.stringify(teintes));

  /* ── CENT BASCULEMENTS : LE RUBAN NE DÉBORDE PAS ────────────────────────── */
  const cent = await lire('cent');
  /* La largeur plancher des parts était fixe : cent fois quatre pixels
     dépassent la largeur du popup, et le ruban étant en débordement caché,
     les derniers segments — dont celui EN COURS — disparaissaient sans un
     mot. La mesure est directe : ce qui dépasse, en pixels.

     CENT SOIXANTE ET UN, ET NON CENT SOIXANTE : le décor pose cent soixante
     chapitres de VOD, et notre PROPRE observation en ajoute un. Le dernier
     chapitre est « Discussions », la carte porte « Jeu 1 » — deux catégories
     différentes, donc un segment de plus, celui que nous avons vu nous-mêmes.
     J'attendais le compte rond ; le banc a eu raison, et le compte exact vaut
     mieux qu'une inégalité qui laisserait aussi passer une frise tronquée. */
  /* UN PIXEL EST TOLÉRÉ, ET LE CHIFFRE VIENT D'UNE MESURE. Flexbox répartit
     en sous-pixels puis arrondit chaque part ; sur cent soixante et une, les
     arrondis s'additionnent en une fraction de pixel, et `scrollWidth` étant
     entier, il la rend comme 1. Mesuré en isolation : la somme exacte des
     parts vaut 455,3 px pour 456 de large — rien ne dépasse réellement.
     L'écart qu'on garde est celui qui compte : 188 px sous l'ancienne règle,
     soit une quarantaine de segments avalés, contre au plus un pixel
     aujourd'hui. Exiger zéro serait exiger que le moteur de rendu compte en
     nombres exacts, ce qu'il ne fait pas. */
  ok('cent soixante basculements tiennent dans le ruban, sans rien rogner à sa fin',
     cent.parts === 161 && cent.debord <= 1,
     `${cent.parts} trait(s), ${cent.debord} px de débordement`);
  ok('…et la liste, elle, reste à neuf lignes',
     cent.lignes.length === 9, `${cent.lignes.length} ligne(s)`);
  await page.close();
}

titre('91. Le subathon — le reconnaître au titre, le dire sur la carte');
{
  /* DEUX MOITIÉS, ET ELLES NE SE PROUVENT PAS DE LA MÊME FAÇON. La RÈGLE est
     une fonction pure : on l'extrait de la source et on la nourrit de titres
     réels, ce qui permet d'en couvrir trente d'un coup. La CARTE, elle, ne se
     juge que dans un navigateur, à travers le vrai relevé — c'est là que se
     tiennent les défauts qu'une fonction pure ne peut pas avoir : la pose qui
     empile, la marque qui ne se défait pas, l'espace laissé derrière.

     POURQUOI CE SCÉNARIO EXISTE À CE POINT DE DÉTAIL. Cette détection ne
     tourne que sur ce que Twitch écrit dans le titre, et je n'ai aucun moyen
     de l'exécuter contre le vrai Twitch. Le banc est donc la SEULE preuve, et
     il doit valoir pour les langues où l'on diffuse — le numéro de jour ne
     s'écrit pas au même endroit en japonais qu'en anglais. */

  // ── LA RÈGLE, EXTRAITE DE LA SOURCE ET JOUÉE TELLE QUELLE ────────────────
  /* On n'en recopie pas une deuxième version : deux rédactions de la même
     expression finissent toujours par diverger d'un caractère, et c'est
     l'originale qu'il faut mettre en cause. */
  const srcTse = readFileSync(join(ICI, '..', 'content.js'), 'utf8');
  const debRegle = srcTse.indexOf('  const RE_SUBATHON_NOM');
  const finRegle = srcTse.indexOf('  const TSE_CHANNELS_QUERY');
  const ctxRegle = createContext({});
  runInContext(srcTse.slice(debRegle, finRegle)
    + '\nglobalThis.__detecter = detecterSubathon;', ctxRegle);
  const detecter = ctxRegle.__detecter;
  ok('la règle s\'extrait de la source, et c\'est bien une fonction',
     debRegle > 0 && finRegle > debRegle && typeof detecter === 'function');

  /* « voie:jour » en une chaîne : le verdict ET la règle qui l'a rendu. Sans
     la voie, un cas passant par la mauvaise règle passerait inaperçu — et
     c'est exactement ce que le rapport de diagnostic aura à dire. */
  const dit = (t, tags = []) => {
    const r = detecter(t, tags);
    return r === null ? 'NON' : r.voie + ':' + r.jour;
  };
  const juger = (cas) => cas
    .filter(([t, tags, attendu]) => dit(t, tags) !== attendu)
    .map(([t, tags, attendu]) => `${JSON.stringify(t)}${tags.length ? ' ' + JSON.stringify(tags) : ''}`
      + ` -> ${dit(t, tags)} (attendu ${attendu})`);

  /* (a) LE TITRE NOMME L'ÉVÉNEMENT — il suffit, avec ou sans numéro. Les
     séparateurs sont ceux qu'on lit vraiment : « SUB-A-THON », « SUB A THON »,
     « sub_a_thon ». Et « 24H SUBATHON » est nommé sans être numéroté : la
     carte le marquera sans pastille, ce qui est la vérité. */
  const ecartsA = juger([
    ['SUBATHON DAY 12 | !socials',        [], 'nom:12'],
    ['[SUB-A-THON JOUR 3] on continue !', [], 'nom:3'],
    ['SUB A THON - Tag 7',                [], 'nom:7'],
    ['sub_a_thon Dia 4',                  [], 'nom:4'],
    ['subathon day9',                     [], 'nom:9'],
    ['SUBATHON DAY 9/30',                 [], 'nom:9'],
    ['Subathon',                          [], 'nom:null'],
    ['24H SUBATHON',                      [], 'nom:null'],
  ]);
  ok('le titre qui NOMME un subathon suffit — et son numéro est lu quand il y en a un',
     ecartsA.length === 0, ecartsA.join(' | '));

  /* (b) UN MOT EN « thon » NE SUFFIT PAS : il lui faut le numéro de jour.
     C'est la conjonction qui fait la justesse de la règle, et les deux
     dernières lignes sont là pour la prouver — « Marathon » est un jeu, et
     une soirée dessus n'est pas un événement de plusieurs jours. */
  const ecartsB = juger([
    ['!MOUSEATHON DAY 9 AHHHH 50% TO IMMUNE DEFICIENCY FOUNDATION', [], 'thon:9'],
    ['Kabathon dzien 8',    [], 'thon:8'],
    ['SLEEPATHON dia 2',    [], 'thon:2'],
    ['Marathon - Day 3',    [], 'thon:3'],
    ['Marathon avec les potes', [], 'NON'],
    ['Marathon',            [], 'NON'],
  ]);
  ok('un mot en « thon » ne vaut QUE s\'il est accompagné d\'un numéro de jour',
     ecartsB.length === 0, ecartsB.join(' | '));

  /* (c) LE TAG NE SUFFIT PAS NON PLUS. Twitch propose « Subathon » et
     « SubathonStream » ; on les ramène à leurs lettres avant de comparer,
     donc la casse et la ponctuation ne comptent pas. Les quatre lignes en
     écriture non latine sont le vrai enjeu de cette règle : le titre n'y
     porte aucun mot latin, et sans le tag rien ne le rattraperait. */
  const ecartsC = juger([
    ['Chill stream jour 5',  ['Subathon'],       'tag:5'],
    ['Chill stream Day 5',   ['subathonstream'], 'tag:5'],
    ['Chill stream Day 5',   ['Français', 'Subathon 2026'], 'tag:5'],
    ['サブアソン 9日目', ['Subathon'], 'tag:9'],
    ['第12天 挑战',                  ['subathon'], 'tag:12'],
    ['서브어톰 3일차',       ['SubathonStream'], 'tag:3'],
    ['Стрим день 21', ['Subathon'], 'tag:21'],
    ['Chill stream',         ['Subathon'],       'NON'],
    ['Chill stream Day 5',   ['Français', 'FPS'], 'NON'],
  ]);
  ok('le tag ne vaut QUE s\'il est accompagné d\'un numéro de jour, en toute écriture',
     ecartsC.length === 0, ecartsC.join(' | '));

  /* (d) CE QUI NE DOIT RIEN DÉCLENCHER. « Decathlon » et « Triathlon » se
     terminent en « hlon » et non en « thon » — la règle les laisse passer
     d'elle-même. Le mot NU « thon » est le poisson : deux lettres sont exigées
     devant lui, et « du thon jour 4 » ne décore rien.

     LA DERNIÈRE LIGNE EST UN FAUX POSITIF CONNU, ET IL EST ICI POUR ÊTRE VU.
     « Python » est un mot en « thon » : une série de code numérotée par jours
     sera prise pour un subathon. Le resserrer à « athon » le supprimerait au
     prix des noms fabriqués en « -thon » sans « a », que la règle demandée
     couvre expressément. On le nomme plutôt que de le taire — et si un jour
     il faut trancher autrement, cette ligne dira ce qu'on perd. */
  const ecartsD = juger([
    ['GTA RP tranquille',           [], 'NON'],
    ['Je mange du thon jour 4',     [], 'NON'],
    ['Decathlon sponsor day 2',     [], 'NON'],
    ['Triathlon day 2',             [], 'NON'],
    ['DAY 1 OF ASKING for a follow', [], 'NON'],
    [null,                          [], 'NON'],
    ['',                            ['Subathon'], 'NON'],
    ['Python - Day 3',              [], 'thon:3'],
  ]);
  ok('rien d\'autre ne déclenche — et le seul faux positif connu est nommé, pas tu',
     ecartsD.length === 0, ecartsD.join(' | '));

  // ── LA CARTE, DANS LE NAVIGATEUR, À TRAVERS LE VRAI RELEVÉ ───────────────
  /* VINGT-QUATRE CARACTÈRES, ce qui est une longueur de pseudo Twitch
     ordinaire et non un cas tordu : la colonne du nom fait environ 128 px,
     soit une quinzaine de caractères. Il DOIT dépasser, faute de quoi
     l'assertion sur l'abrègement ne prouverait rien. */
  const LONG = 'unpseudovraimenttreslong';
  const page = await fresh();
  /* LE DÉCOR NE CONTRAINT PAS LA LARGEUR, ET TWITCH SI. La colonne du pseudo
     fait environ 128 px dans la vraie sidebar ; la page de banc, elle, laisse
     la carte s'étendre sur toute la fenêtre, si bien qu'aucun pseudo n'y est
     jamais trop long et que la règle qu'on veut éprouver ne joue pas — mesuré :
     la pastille à 1062 px du bord, le nom jamais abrégé. On repose donc la
     contrainte réelle, et sur elle seule : c'est la seule chose qui manque au
     décor pour que le cas existe. */
  await page.addStyleTag({ content:
    '[data-a-target="side-nav-card-metadata"] { max-width: 128px; }' });
  /* ── LE TÉMOIN POSÉ SUR LE NŒUD DE TEXTE DE TWITCH ────────────────────────
     La seule chose qui distingue « déplacer » de « recopier » est l'IDENTITÉ
     du nœud, et une identité ne traverse pas la frontière du banc : elle se
     vérifie dans la page. On marque donc chaque nœud de texte de pseudo au
     moment où la carte paraît, d'une propriété que seul cet objet-là porte ;
     si l'enveloppe contient un nœud sans le témoin, c'est une copie — et
     React, qui écrit dans l'original, écrirait désormais dans un nœud
     détaché : le pseudo cesserait de suivre la chaîne affichée. */
  await page.evaluate((LONG) => {
    /* MÊME `createdAt` POUR « mouse » ET « ordi », ET C'EST LE POINT. La
       durée affichée doit être EXACTEMENT la même de part et d'autre : on la
       compare l'une à l'autre plutôt que de recopier un format, ce qui prouve
       que la pastille s'AJOUTE et ne réécrit rien. */
    const h = new Date(Date.now() - 1865 * 60_000).toISOString();     // 31 h 05
    const court = new Date(Date.now() - 74 * 60_000).toISOString();   //  1 h 14
    window.__fx = {
      mouse: { id:'1', createdAt:h, viewers:8400, game:'Watch Your Plastic Duck',
               tags:[], title:'!MOUSEATHON DAY 9 AHHHH 50% TO IMMUNE DEFICIENCY FOUNDATION' },
      nomme: { id:'2', createdAt:court, viewers:2100, game:'Just Chatting',
               tags:[], title:'24H SUBATHON' },
      partag:{ id:'3', createdAt:court, viewers:900,  game:'Just Chatting',
               tags:['Français', 'Subathon'], title:'Chill stream jour 5' },
      ordi:  { id:'4', createdAt:h, viewers:7800, game:'Just Chatting',
               tags:[], title:'GTA RP tranquille' },
      /* LE CAS LE PLUS LARGE QUE LA COLONNE AIT À PORTER, et il n'est pas
         théorique : un subathon de quatre mois affiche « J120 » devant une
         durée à trois chiffres. La colonne de droite prend sa largeur du
         NOMBRE DE SPECTATEURS, ici volontairement court ; le compteur y
         déborde donc franchement, et c'est la seule façon d'éprouver la règle
         qui l'empêche de se couper en deux. Avec « 8,4 k » au-dessus, la
         colonne était assez large pour que le défaut ne paraisse pas — le
         mutant qui retirait la règle a d'abord SURVÉCU, faute de ce décor. */
      [LONG]: { id:'5', createdAt:new Date(Date.now() - 10120 * 60_000).toISOString(),
               viewers:900, game:'Just Chatting', tags:[], title:'SUBATHON DAY 120' },
    };
    window.__addCard('mouse',  'Watch Your Plastic Duck', '8,4 k');
    window.__addCard('nomme',  'Just Chatting', '2,1 k');
    window.__addCard('partag', 'Just Chatting', '900');
    window.__addCard('ordi',   'Just Chatting', '7,8 k');
    window.__addCard(LONG,     'Just Chatting', '900');
    /* LA SESSION GUEST STAR SE POSE AVEC LE DÉCOR, ET NON PLUS TARD. Elle se
       relève par LOTS, au rythme des relevés : posée après le premier, le lot
       a déjà retenu « aucune session » et le badge ne paraît jamais. Elle sert
       tout en bas du scénario, où l'on vérifie que le pseudo de la chaîne en
       subathon reste « mouse » dans la phrase d'un badge. */
    window.__gs = { '4': { hostId: '4', hostLogin: 'ordi',
                           guests: [{ id: '1', login: 'mouse', combined: 9000 }] } };
    /* MARQUÉ ICI, ET PAS PLUS TARD. La décoration est asynchrone : au moment
       où ce bloc se termine, les <p> portent encore le nœud de texte que
       Twitch y a mis, et lui seul. Marquer après coup marquerait une copie
       éventuelle, ce qui ne prouverait rien. */
    for (const p of document.querySelectorAll('p[data-a-target="side-nav-title"]')) {
      for (const n of p.childNodes) if (n.nodeType === 3) n.__tseTemoin = true;
    }
  }, LONG);
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 9);

  const lire = () => page.evaluate(() => {
    const out = {};
    for (const c of document.querySelectorAll('.side-nav-card')) {
      const up = c.querySelector('.tse-uptime');
      const t  = c.querySelector('p[data-a-target="side-nav-title"]');
      const pu = t && t.querySelector(':scope > .tse-subathon-jour');
      const nm = t && t.querySelector(':scope > .tse-subathon-nom');
      out[c.dataset.tseLogin] = {
        marquee:  c.dataset.tseSubathon === 'true',
        jour:     c.dataset.tseSubathonDay ?? null,
        /* AUCUN NŒUD N'EST INJECTÉ DANS LA CARTE. L'anneau qui s'y posait a
           été retiré ; ce compteur reste pour l'attester, parce qu'un signal
           supprimé qu'on cesse de mesurer revient tôt ou tard. */
        ajouts:   c.querySelectorAll(':scope > :not(a)').length,
        pastille: pu ? pu.textContent : null,
        /* LE PSEUDO TEL QUE LE RESTE DU CODE LE LIRA. Sur une carte de
           subathon le <p> porte aussi la pastille : son `textContent` vaut
           « SardocheJ9 », qui n'est le pseudo de personne. */
        titreTexte: t ? t.textContent : null,
        nomEnveloppe: nm ? nm.textContent : null,
        /* LE COMPTEUR D'ANCIENNETÉ, qui ne doit plus rien porter du tout —
           ni pastille, ni couleur à part, ni second nœud. */
        texte:    up ? up.textContent : null,
        noeuds:   up ? up.childNodes.length : 0,
        couleurDuree: up ? getComputedStyle(up).color : null,
        graisseDuree: up ? getComputedStyle(up).fontWeight : null,
        /* LES MESURES DE LA PASTILLE, prises sur le rendu et non déduites.
           La ligne de référence est celle du PSEUDO, contre lequel elle se
           pose désormais. */
        hauteurTitre: t ? +t.getBoundingClientRect().height.toFixed(2) : 0,
        corpsPastille: pu ? getComputedStyle(pu).fontSize : null,
        fondPastille:  pu ? getComputedStyle(pu).backgroundColor : null,
        bordPastille:  pu ? getComputedStyle(pu).borderTopWidth : null,
        /* CENTRÉE SUR LE NOM : on compare les MILIEUX des deux boîtes, seule
           mesure qui vaille pour un alignement demandé « au centre ». */
        ecartCentre: (pu && nm) ? +(
          (pu.getBoundingClientRect().top + pu.getBoundingClientRect().bottom) / 2
          - (nm.getBoundingClientRect().top + nm.getBoundingClientRect().bottom) / 2
        ).toFixed(2) : null,
        /* LA PASTILLE DÉBORDE-T-ELLE DU <p> ? C'est ce qui arrive sur un
           pseudo long si le nom refuse de rétrécir. */
        debordPastille: (pu && t) ? Math.round(
          pu.getBoundingClientRect().right - t.getBoundingClientRect().right) : null,
        nomAbrege: nm ? nm.scrollWidth > nm.clientWidth : null,
        /* LE MÉCANISME DE L'ELLIPSE, à défaut de son effet : le caractère « … »
           n'existe que dans les pixels, il n'ajoute aucun nœud et ne change
           aucun rectangle. On contrôle donc que les deux propriétés sont bien
           calculées sur l'enveloppe. Plus faible qu'un contrôle d'effet, et
           c'est dit — mais sans elles le nom serait coupé net par-dessus la
           pastille au lieu d'être abrégé devant elle. */
        coupeNom: nm ? getComputedStyle(nm).overflow + '/' + getComputedStyle(nm).textOverflow
                     : null,
        /* Le nœud de Twitch a-t-il SURVÉCU à l'enveloppement, ou a-t-il été
           recopié ? Le témoin ne voyage pas : une copie ne l'a pas. */
        noeudDorigine: nm ? [...nm.childNodes].some(n => n.nodeType === 3 && n.__tseTemoin)
                          : (t ? [...t.childNodes].some(n => n.nodeType === 3 && n.__tseTemoin)
                               : null),
        toutLeTexte: c.textContent,
      };
    }
    return out;
  });
  const v = await lire();

  ok('la carte d\'un subathon porte la pastille de son jour, contre le pseudo',
     v.mouse.marquee && v.mouse.pastille === 'J9' && v.mouse.jour === '9'
     && v.mouse.ajouts === 0 && v.mouse.nomEnveloppe === 'mouse',
     JSON.stringify(v.mouse));
  /* LA DURÉE EST LE RENSEIGNEMENT PRINCIPAL DE CETTE LIGNE, et la pastille ne
     doit pas l'abîmer. La comparaison est faite avec une carte ORDINAIRE de
     même ancienneté : si `ecrireUptime` écrasait le contenu au lieu de viser
     le nœud texte, les deux ne se ressembleraient plus. */
  /* ── LE COMPTEUR D'ANCIENNETÉ REDEVIENT CELUI DE TOUT LE MONDE ───────────
     Il a porté la pastille, puis une chaleur en braise, et les deux ont été
     retirés : un chiffre qu'on lit pour lui-même n'a pas à être repeint, et
     deux cartes voisines dont l'une est teinte ne se comparent plus. On exige
     donc l'identité STRICTE avec une carte ordinaire de même ancienneté —
     texte, nombre de nœuds, couleur et graisse. Quatre autres scénarios lisent
     ce texte : c'est l'invariant le plus chargé de la carte. */
  ok('…et le compteur d\'ancienneté est EXACTEMENT celui d\'une carte ordinaire',
     /^\d+h\d+$/.test(v.ordi.texte) && v.mouse.texte === v.ordi.texte
     && v.mouse.noeuds === 1
     && v.mouse.couleurDuree === v.ordi.couleurDuree
     && v.mouse.graisseDuree === v.ordi.graisseDuree,
     JSON.stringify({ subathon: v.mouse.texte, ordinaire: v.ordi.texte,
                      couleur: v.mouse.couleurDuree, ordCouleur: v.ordi.couleurDuree,
                      graisse: v.mouse.graisseDuree, noeuds: v.mouse.noeuds }));
  /* LE PSEUDO RESTE LISIBLE PAR LE RESTE DU CODE. Le <p> porte maintenant deux
     enfants, et son `textContent` vaut « mouseJ9 » : c'est l'enveloppe qu'il
     faut lire, et `displayNameFor` le fait — sans quoi l'aperçu titrerait une
     chaîne qui n'existe pas. */
  ok('…le pseudo se lit dans son enveloppe, et non collé au numéro de jour',
     v.mouse.titreTexte === 'mouseJ9' && v.mouse.nomEnveloppe === 'mouse',
     JSON.stringify({ p: v.mouse.titreTexte, nom: v.mouse.nomEnveloppe }));
  /* ENVELOPPER, C'EST DÉPLACER — JAMAIS RECOPIER. React tient une référence
     sur CE nœud de texte pour y écrire le pseudo. Le recopier dans un élément
     neuf et jeter l'original le ferait écrire dans un nœud détaché de la page,
     et le nom cesserait de suivre la chaîne que la carte affiche — un défaut
     qui ne se voit qu'après un recyclage de carte, c'est-à-dire jamais pendant
     qu'on l'écrit. Le témoin le dit tout de suite. */
  ok('…et l\'enveloppe DÉPLACE le nœud de Twitch, elle ne le recopie pas',
     v.mouse.noeudDorigine === true && v.ordi.noeudDorigine === true,
     JSON.stringify({ subathon: v.mouse.noeudDorigine, ordinaire: v.ordi.noeudDorigine }));
  /* ── LA PASTILLE SE MESURE, ELLE NE SE REGARDE PAS ────────────────────────
     Trois grandeurs, et chacune répond à une demande précise.

     LE CORPS. « À la même taille que le temps de stream » : les deux valeurs
     calculées doivent être ÉGALES, et non voisines. La feuille l'obtient par
     « font-size: inherit », si bien qu'elles ne peuvent plus diverger — mais
     c'est une propriété du rendu qu'on vérifie ici, pas une déclaration.

     LA HAUTEUR DE LIGNE. Une pastille bordée est plus haute que le texte nu ;
     si elle dépasse la ligne, la carte grandit et la colonne entière se
     décale d'un pixel — un défaut qui ne se voit que sur quinze cartes à la
     fois, c'est-à-dire jamais pendant qu'on l'écrit. On exige donc l'égalité
     STRICTE avec la ligne d'une carte ordinaire de même contenu.

     LE FOND. « Le fond de l'élément est la couleur de fond standard de la
     carte » : pas une couleur choisie qui lui ressemble — AUCUNE couleur, de
     sorte que la carte se voie au travers quel que soit son état (survol,
     abonné, sélection). Ce qui se mesure est donc une transparence totale. */
  ok('…au corps demandé, centrée sur le nom, sans grandir la rangée du pseudo',
     v.mouse.corpsPastille === '10px' && v.mouse.ecartCentre === 0
     && v.mouse.hauteurTitre === v.ordi.hauteurTitre,
     JSON.stringify({ corps: v.mouse.corpsPastille, ecartCentre: v.mouse.ecartCentre,
                      titre: v.mouse.hauteurTitre, ordinaire: v.ordi.hauteurTitre }));
  ok('…creuse et non pleine : un contour, et le fond de la carte au travers',
     v.mouse.fondPastille === 'rgba(0, 0, 0, 0)' && v.mouse.bordPastille === '1px',
     JSON.stringify({ fond: v.mouse.fondPastille, bord: v.mouse.bordPastille }));
  /* LE CAS QUI FAIT DÉBORDER LA COLONNE. « J120 » devant une durée à trois
     chiffres est plus large que la place que le nombre de spectateurs laisse ;
     sans règle, le compteur passe à la ligne et la carte double de hauteur —
     ce qui décale toute la colonne, et ne se voit qu'à quinze cartes. On exige
     donc que MÊME CELLE-LÀ tienne sur une ligne, à la hauteur d'une carte
     ordinaire. */
  /* ── LE PSEUDO LONG, ET CE QUI CÈDE ──────────────────────────────────────
     Le <p> du titre porte l'ellipse de Twitch. Tant que le pseudo y était un
     nœud de texte NU, il devenait sous flex un élément anonyme — et un élément
     anonyme ne peut pas recevoir « min-width: 0 », donc refuse de rétrécir :
     c'est la PASTILLE qui sortait de la boîte, mesurée à 98 px hors cadre, et
     disparaissait. Enveloppé, le nom s'abrège et la pastille reste entière.

     C'EST LE BON ARBITRAGE, et il n'est pas arbitraire : « J9 » abrégé ne veut
     plus rien dire, « UnPseudoTresLong… » se lit encore. On exige donc les
     deux à la fois — pastille dans le cadre, ET nom effectivement abrégé,
     faute de quoi le décor serait trop court pour prouver quoi que ce soit. */
  ok('…et un pseudo trop long abrège LE NOM, jamais la pastille',
     v[LONG].pastille === 'J120' && v[LONG].debordPastille <= 0
     && v[LONG].nomAbrege === true && v[LONG].coupeNom === 'hidden/ellipsis'
     && v[LONG].hauteurTitre === v.ordi.hauteurTitre,
     JSON.stringify({ debord: v[LONG].debordPastille, abrege: v[LONG].nomAbrege,
                      coupe: v[LONG].coupeNom,
                      titre: v[LONG].hauteurTitre, ordinaire: v.ordi.hauteurTitre }));
  /* UN SUBATHON PEUT NE PAS SE COMPTER. « 24H SUBATHON » nomme l'événement
     sans en numéroter le jour : la carte le marque et n'affiche pas de
     pastille. On ne montre pas un nombre qu'on n'a pas — et surtout on ne
     retombe pas sur « J1 » par défaut, ce qui serait une invention. */
  ok('un subathon NOMMÉ mais non numéroté garde sa chaleur et n\'invente pas de pastille',
     v.nomme.marquee && v.nomme.pastille === null
     && v.nomme.jour === null && v.nomme.noeuds === 1,
     JSON.stringify(v.nomme));
  ok('le tag « Subathon » décore la carte dès que le titre porte un numéro',
     v.partag.marquee && v.partag.pastille === 'J5' && v.partag.jour === '5',
     JSON.stringify(v.partag));
  /* LA CARTE ORDINAIRE EST LE VRAI RISQUE DE CE CHANTIER : c'est elle qu'il y
     a des milliers de fois, et c'est son compteur que quatre autres scénarios
     lisent. Un seul nœud, aucun attribut, aucun anneau. */
  ok('la carte ordinaire ne change pas d\'un caractère : un seul nœud, aucune marque',
     !v.ordi.marquee && v.ordi.ajouts === 0 && v.ordi.noeuds === 1
     && v.ordi.pastille === null,
     JSON.stringify(v.ordi));
  /* LE TITRE EST LU, JAMAIS ÉCRIT. Il n'entre dans l'extension que pour y
     chercher un motif, et seul un NOMBRE en ressort. Cette assertion est la
     seule qui le vérifie, et elle vaut d'être là : c'est du texte d'un tiers. */
  ok('rien du titre ne traverse jusqu\'à la carte — seul un nombre en ressort',
     !v.mouse.toutLeTexte.includes('MOUSEATHON')
     && !v.mouse.toutLeTexte.includes('IMMUNE')
     && !v.partag.toutLeTexte.includes('Chill'),
     JSON.stringify([v.mouse.toutLeTexte, v.partag.toutLeTexte]));

  /* LE RAPPORT EST LE SEUL ŒIL QU'ON AURA SUR LE VRAI TWITCH. `detectes` vient
     du cache, `marquees` du DOM : leur écart désignerait laquelle des deux
     moitiés est en panne. Et `voies` dit quelle règle porte les cas — ici les
     trois, une chacune, ce qui prouve que les trois chemins sont vivants. */
  const rap = await page.evaluate(() => window.tse.panneau.rapport().subathons);
  ok('le rapport compte ce que le DOM montre, et NOMME la règle qui a tranché',
     rap.detectes === 4 && rap.marquees === 4 && rap.sansJour === 1
     && rap.voies.nom === 2 && rap.voies.thon === 1 && rap.voies.tag === 1,
     JSON.stringify(rap));

  /* IDEMPOTENCE. La pose est rejouée à CHAQUE relevé — toutes les trente
     secondes en production, plusieurs fois par seconde ici. Une pose qui
     ajoute au lieu de converger empilerait un anneau par relevé, et le défaut
     ne se verrait qu'au bout de quelques minutes d'utilisation réelle. */
  await wait(page, 2500);
  const encore = await lire();
  ok('rejouée à chaque relevé, la marque n\'empile rien',
     encore.mouse.ajouts === 0 && encore.mouse.pastille === 'J9'
     && encore.mouse.nomEnveloppe === 'mouse'
     && encore.mouse.titreTexte === 'mouseJ9'
     && encore.mouse.texte === encore.ordi.texte,
     JSON.stringify(encore.mouse));
  /* ET LA DURÉE NE SE RETEINT PAS EN CHEMIN. Le premier relevé passe par
     `renderUptime`, les suivants par `refreshUptime` : une couleur reposée
     dans le second seulement ne se verrait pas sur un contrôle fait à
     l'ouverture. On revérifie donc APRÈS plusieurs relevés — c'est là qu'un
     mutant a survécu à la première rédaction. */
  ok('…et la durée n\'a pas repris de couleur à part en cours de route',
     encore.mouse.couleurDuree === encore.ordi.couleurDuree
     && encore.mouse.graisseDuree === encore.ordi.graisseDuree,
     JSON.stringify({ subathon: encore.mouse.couleurDuree,
                      ordinaire: encore.ordi.couleurDuree,
                      graisse: encore.mouse.graisseDuree }));

  /* ── LE PSEUDO TEL QUE LE RESTE DE L'EXTENSION LE LIT ────────────────────
     `displayNameFor` résout un login en pseudo affichable, et il le lit dans le
     <p> du titre — celui-là même qui porte maintenant la pastille. Lu en bloc,
     il rendrait « mouseJ9 », un pseudo qui n'est celui de personne, et ce nom-là
     part dans les badges de l'aperçu et dans les phrases de co-stream.

     C'EST LE SEUL ENDROIT OÙ LA CORRUPTION SE VERRAIT, et aucune autre
     assertion ne l'atteignait : le mutant qui relisait le <p> entier a survécu
     à tout le reste du scénario. On monte donc un Guest Star qui NOMME la
     chaîne de subathon depuis la carte d'une autre, et l'on lit le nom en gras
     du badge — exactement ce qu'un utilisateur verrait.

     ET CE CONTRÔLE SE PLACE AVANT CELUI QUI DÉFAIT LA MARQUE. Écrit après, il
     interrogeait une carte dont la pastille venait d'être retirée : le <p> y
     était redevenu un simple « mouse », et le mutant passait encore. Une
     assertion posée au mauvais moment du scénario ne prouve rien de plus
     qu'une assertion absente. */
  /* ── LEQUEL DES DEUX BADGES, ET POURQUOI ÇA NE CHANGE RIEN ICI ─────────
     CE CONTRÔLE LISAIT LE BADGE VIOLET, et la 4.16.0 l'a fait changer de
     place : le violet ne nomme plus que les membres ABSENTS de la barre, et
     « mouse » y a une carte — son nom part donc désormais dans le bleu. Le
     banc l'a dit en une ligne : « Co-stream avec mouse », le bon pseudo dans
     l'autre badge.

     LE SUJET DE CETTE ASSERTION N'EST NI L'UN NI L'AUTRE : c'est que
     `displayNameFor` lise le pseudo dans SON ENVELOPPE et non le <p> entier,
     qui rendrait « mouseJ9 ». On interroge donc le badge qui NOMME, quel
     qu'il soit — la règle de partage des deux badges a son propre scénario
     (150), et la mêler à celui-ci reviendrait à éprouver deux choses avec une
     assertion qui n'en dirait plus clairement aucune. */
  const BADGES_NOMMANTS = '.tse-preview__badge--squad, .tse-preview__badge--costream';
  await hoverLogin(page, 'ordi');
  await attendre(page, (sel) => !!document.querySelector(sel), 6000, BADGES_NOMMANTS);
  const nomBadge = await page.evaluate((sel) => {
    const b = document.querySelector(sel);
    return b ? { gras: b.querySelector('strong')?.textContent ?? null,
                 texte: b.textContent.trim() }
             : { gras: null, texte: null,
                 badgesVus: [...document.querySelectorAll('.tse-preview__badge')]
                   .map(x => x.className + ' :: ' + x.textContent.trim()).join(' | '),
                 apercu: !!document.querySelector('.tse-preview[data-tse-visible="true"]') };
  }, BADGES_NOMMANTS);
  ok('le pseudo d\'une chaîne en subathon reste « mouse » partout ailleurs',
     nomBadge.gras === 'mouse' && !nomBadge.texte.includes('J9'),
     JSON.stringify(nomBadge));
  await page.evaluate(() => {
    const c = [...document.querySelectorAll('.side-nav-card')]
      .find(x => x.dataset.tseLogin === 'ordi');
    c.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
  });
  await attendre(page,
    () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);

  /* ET ELLE SE DÉFAIT. Un streamer retire « subathon » de son titre au milieu
     de sa diffusion ; React réutilise aussi la même carte d'une chaîne à
     l'autre. Une marque qui ne sait que se poser resterait sur une carte qui
     ne la mérite plus — et l'anneau, lui, se verrait. */
  await page.evaluate(() => { window.__fx.mouse.title = 'GTA RP tranquille'; });
  /* L'ATTENTE NE PORTE QUE SUR L'ATTRIBUT, et c'est délibéré : une attente
     fondée sur l'anneau la rendrait solidaire de la façon dont l'anneau est
     écrit, et une mutation SANS RAPPORT — retirer son `aria-hidden` — la
     ferait rendre la main tout de suite, sur un DOM qui n'a pas encore
     bougé. Les assertions qui suivent liraient alors un état intermédiaire
     et échoueraient pour la mauvaise raison. La mutation l'a montré. */
  await attendre(page, () => ![...document.querySelectorAll('.side-nav-card')]
    .find(c => c.dataset.tseLogin === 'mouse')?.dataset.tseSubathon, 6000);
  const apres = await lire();
  ok('le titre cesse de le dire : la pastille et l\'attribut partent ensemble',
     !apres.mouse.marquee && apres.mouse.pastille === null
     && apres.mouse.jour === null && apres.mouse.ajouts === 0,
     JSON.stringify(apres.mouse));
  /* LE DÉFAUT QUE CETTE LIGNE A TROUVÉ. L'espace qui séparait la pastille de
     la durée vit dans le nœud texte, pas dans la pastille : la retirer seule
     laissait « ␣31h05 » sur la carte jusqu'au relevé suivant. Comparer au
     texte d'une carte ordinaire le dit immédiatement ; un `includes` ne
     l'aurait pas vu. */
  /* LE <p> REND SON NŒUD DE TEXTE À SA PLACE, sans enveloppe et sans copie.
     C'est là que React écrit le pseudo : une enveloppe oubliée, ou un nœud
     recopié, et le nom cesserait de suivre la chaîne que la carte affiche. */
  ok('…et le <p> du pseudo retrouve EXACTEMENT la forme de toutes les autres cartes',
     apres.mouse.nomEnveloppe === null && apres.mouse.titreTexte === 'mouse'
     && apres.mouse.hauteurTitre === apres.ordi.hauteurTitre
     && apres.mouse.noeuds === 1 && apres.mouse.texte === apres.ordi.texte,
     JSON.stringify({ titre: apres.mouse.titreTexte, enveloppe: apres.mouse.nomEnveloppe,
                      duree: apres.mouse.texte }));
  const rapApres = await page.evaluate(() => window.tse.panneau.rapport().subathons);
  ok('…et le rapport le compte en moins, des deux côtés',
     rapApres.detectes === 3 && rapApres.marquees === 3 && rapApres.voies.thon === 0,
     JSON.stringify(rapApres));
  await page.close();
}

titre('92. La section suivie — une section vide fait taire toute l\'extension');
{
  /* ── LE DÉFAUT VIENT D'UN RAPPORT, ET IL ÉTAIT MUET ──────────────────────
     « De temps en temps l'ensemble de mes chaînes suivies a disparu. » Le
     rapport joint ne portait aucune erreur, aucun échec réseau, aucune pause :
     `appels 1676`, `echecs 0`, `erreurs (0)`. Il portait en revanche trois
     chiffres qui, ensemble, ne peuvent pas être vrais :

       cartes 9 · decorees 9 · roster 128 · cache 136 · fabriquees 0

     Cent vingt-huit chaînes connues, cent trente-six en cache, neuf cartes à
     l'écran — et AUCUNE carte fabriquée. Le module des cartes en avance existe
     précisément pour ce cas. Et les sondes disaient la contradiction en
     toutes lettres : « cardClass ok — 9 carte(s) » à côté de « cardLink na —
     aucune carte à sonder ». Neuf cartes existaient, et il n'y en avait
     aucune à sonder.

     LA CAUSE. Les sondes ne prélèvent que DANS la section suivie ; le module
     des cartes en avance y cherche son modèle de clonage. `followedSection()`
     rendait une section RÉELLE mais VIDE : tous ses appelants concluaient que
     la barre était vide, et se taisaient ensemble — sans erreur, sans
     compteur, sans rien qui dise pourquoi. Rendre `null` aurait au moins été
     honnête ; rendre une section vide fait croire à une sidebar déserte.

     DEUX CAUSES MÈNENT À CE MÊME SYMPTÔME, et ce scénario les monte toutes
     les deux, parce qu'aucune n'est écartable depuis un rapport : un autre
     nœud portant le même `aria-label` qui usurpe la section, et un remaniement
     de Twitch où l'en-tête et la liste cessent de partager une section. */

  /* ── (a) L'USURPATEUR ────────────────────────────────────────────────────
     Un nœud qui porte le libellé de la section, dans une section À LUI, posée
     AVANT la vraie. `querySelectorAll` rend les nœuds dans l'ordre du
     document : l'ancienne rédaction prenait donc le premier, c'est-à-dire le
     mauvais, et n'y trouvait aucune carte. */
  {
    const page = await fresh();
    await page.evaluate(() => {
      const h = new Date(Date.now() - 60 * 60_000).toISOString();
      window.__fx = {
        alpha: { id:'1', createdAt:h, viewers:1000, game:'VALORANT', tags:[] },
        beta:  { id:'2', createdAt:h, viewers:2000, game:'VALORANT', tags:[] },
      };
      window.__addCard('alpha', 'VALORANT', '1 k');
      window.__addCard('beta',  'VALORANT', '2 k');
      /* L'imposteur : même libellé, sa propre section, aucune carte, et placé
         en tête de la barre. */
      const faux = document.createElement('div');
      faux.className = 'side-nav-section';
      const dedans = document.createElement('div');
      dedans.setAttribute('aria-label', 'Chaînes suivies');
      faux.appendChild(dedans);
      const nav = document.querySelector('#side-nav');
      nav.insertBefore(faux, nav.firstChild);
    });
    await wait(page, 1800);

    const vu = await page.evaluate(() => {
      const sec = window.tse.panneau.rapport();
      const sondes = Object.fromEntries(sec.sondes.map(s => [s.id, s.status]));
      return { voie: sec.sectionSuivie.voie, parCartes: sec.sectionSuivie.parCartes,
               cartes: sec.page.cartes, decorees: sec.page.decorees,
               cardClass: sondes.cardClass, cardLink: sondes.cardLink,
               liveStatus: sondes.liveStatus };
    });
    /* LA SECTION EST CELLE QUI PORTE LES CARTES, et le rapport le DIT : c'est
       « cartes » qu'on veut lire, pas « libelle ». Un rapport qui ne nomme pas
       la voie prise laisse à déduire ce qu'il pouvait écrire. */
    ok('un nœud qui usurpe le libellé ne fait plus passer la barre pour vide',
       vu.voie === 'cartes' && vu.parCartes >= 1,
       JSON.stringify(vu));
    /* LA CONTRADICTION DU RAPPORT REÇU, retournée en assertion : des cartes
       existent ET il y en a à sonder. C'est elle qui doit devenir impossible. */
    ok('…et les sondes cessent de dire « aucune carte à sonder » avec 2 cartes',
       vu.cardClass === 'ok' && vu.cardLink === 'ok' && vu.liveStatus === 'ok'
       && vu.cartes === 2 && vu.decorees === 2,
       JSON.stringify(vu));
    await page.close();
  }

  /* ── (b) LE REMANIEMENT ──────────────────────────────────────────────────
     L'en-tête reste dans sa section ; les cartes passent dans une section
     SŒUR. Plus aucun candidat désigné par le libellé ne porte de carte, et
     c'est le marqueur de Twitch — `data-test-selector="followed-channel"`,
     que les recommandations ne portent pas — qui tranche. */
  {
    const page = await fresh();
    await page.evaluate(() => {
      const h = new Date(Date.now() - 60 * 60_000).toISOString();
      window.__fx = {
        alpha: { id:'1', createdAt:h, viewers:1000, game:'VALORANT', tags:[] },
        beta:  { id:'2', createdAt:h, viewers:2000, game:'VALORANT', tags:[] },
      };
      window.__addCard('alpha', 'VALORANT', '1 k');
      window.__addCard('beta',  'VALORANT', '2 k');
      /* On déplace le conteneur des cartes hors de la section qui porte le
         libellé, dans une section sœur sans libellé — exactement la forme
         qu'aurait un remaniement de Twitch. */
      const nav = document.querySelector('#side-nav');
      const ancienne = document.querySelector('.side-nav-section[aria-label="Chaînes suivies"]');
      const soeur = document.createElement('div');
      soeur.className = 'side-nav-section';
      soeur.appendChild(document.getElementById('cards'));
      ancienne.after(soeur);
    });
    await wait(page, 1800);
    const vu = await page.evaluate(() => {
      const r = window.tse.panneau.rapport();
      const sondes = Object.fromEntries(r.sondes.map(s => [s.id, s.status]));
      return { voie: r.sectionSuivie.voie, decorees: r.page.decorees,
               cardLink: sondes.cardLink, liveStatus: sondes.liveStatus };
    });
    ok('un remaniement qui sépare l\'en-tête des cartes est rattrapé par le marqueur',
       vu.voie === 'marqueur' && vu.cardLink === 'ok' && vu.liveStatus === 'ok'
       && vu.decorees === 2,
       JSON.stringify(vu));
    await page.close();
  }

  /* ── (c) CE QUE LE SILENCE COÛTAIT VRAIMENT ──────────────────────────────
     Le symptôme que l'utilisateur décrit n'est pas « les sondes sont na » :
     c'est « mes chaînes ont disparu ». Elles disparaissent parce que le module
     des CARTES EN AVANCE cherche son modèle de clonage DANS la section suivie.
     Section vide, pas de modèle, `return` — et la chaîne que Twitch n'a pas
     encore posée n'apparaît nulle part. C'est `fabriquees 0` du rapport, avec
     un roster de 128.

     On monte donc le cas complet : une chaîne apprise, que Twitch retire de sa
     barre puis qui repasse en direct, sous un libellé usurpé. Sans la
     correction, elle reste invisible. */
  {
    const page = await fresh();
    await page.evaluate(() => {
      const h = new Date(Date.now() - 60 * 60_000).toISOString();
      window.__fx = {
        alpha:  { id:'1', createdAt:h, viewers:1000, game:'VALORANT', tags:[] },
        tardif: null,                       // suivie, hors ligne : elle entre au roster
      };
      window.__addCard('alpha',  'VALORANT', '1 k');
      window.__addCard('tardif', 'Discussions', '0', false);
      const faux = document.createElement('div');
      faux.className = 'side-nav-section';
      const dedans = document.createElement('div');
      dedans.setAttribute('aria-label', 'Chaînes suivies');
      faux.appendChild(dedans);
      const nav = document.querySelector('#side-nav');
      nav.insertBefore(faux, nav.firstChild);
    });
    await wait(page, 1500);
    ok('la chaîne hors ligne entre bien au roster malgré l\'usurpateur',
       (await page.evaluate(() => window.tse.roster().map(e => e[0]))).includes('tardif'));

    // Twitch retire sa carte, puis la chaîne repasse en direct sans qu'il
    // repose quoi que ce soit : c'est à nous de la fabriquer.
    await page.evaluate(() => {
      [...document.querySelectorAll('.side-nav-card')]
        .find(c => c.querySelector('a[href="/tardif"]'))?.remove();
      window.__fx.tardif = { id:'9', name:'TardifTV',
                             createdAt:new Date(Date.now() - 120_000).toISOString(),
                             viewers:4200, game:'Rocket League', tags:['Français'] };
    });
    await wait(page, 2500);
    const faite = await page.evaluate(() => {
      const c = [...document.querySelectorAll('.side-nav-card')]
        .find(x => x.dataset.tseLogin === 'tardif');
      return { existe: !!c, fabriquee: c?.dataset.tseSynthetic === 'true',
               nom: c?.querySelector('p[data-a-target="side-nav-title"]')?.textContent ?? null,
               visible: c ? getComputedStyle(c).display !== 'none' : false,
               compte: window.tse.panneau.rapport().page.fabriquees };
    });
    /* L'ASSERTION QUI PORTE LE SYMPTÔME. Sans la correction, `faite.existe`
       est faux et `compte` vaut zéro — c'est mot pour mot le rapport reçu. */
    ok('la chaîne que Twitch n\'affiche plus est fabriquée, malgré l\'usurpateur',
       faite.existe && faite.fabriquee && faite.visible
       && faite.nom === 'TardifTV' && faite.compte >= 1,
       JSON.stringify(faite));
    await page.close();
  }

  /* ── (d) LE CAS NORMAL NE CHANGE PAS ─────────────────────────────────────
     Une section suivie qui ne porte aucune carte est parfaitement ordinaire :
     personne n'est en ligne, ou l'utilisateur ne suit personne. On rendait une
     section, on continue d'en rendre une — changer cela ferait sortir quinze
     appelants sur `if (!section) return` pour un cas qui n'a rien d'anormal. */
  {
    const page = await fresh();
    await wait(page, 1200);
    const vu = await page.evaluate(() => {
      const r = window.tse.panneau.rapport();
      return { voie: r.sectionSuivie.voie, vides: r.sectionSuivie.vides,
               cartes: r.page.cartes };
    });
    ok('une barre réellement vide rend toujours sa section, et le rapport le nomme',
       vu.cartes === 0 && vu.voie === 'libelle-vide' && vu.vides >= 1,
       JSON.stringify(vu));
    await page.close();
  }
}

titre('93. Le subathon dans l\'aperçu — un badge, un arc-en-ciel, et pas un clignotement');
{
  /* ── CE QUE CE SCÉNARIO GARDE ────────────────────────────────────────────
     Trois demandes d'un même retour d'usage, et elles ne se vérifient pas de
     la même façon : un badge est du DOM, un arc-en-ciel est une animation dont
     seuls les pixels comptent, et un clignotement ne se voit qu'en rejouant le
     cycle de relevé qui le produisait. */
  const page = await fresh();
  await page.evaluate(() => {
    const h = (m) => new Date(Date.now() - m * 60_000).toISOString();
    window.__fx = {
      mouse: { id: '1', createdAt: h(2277), viewers: 8400, game: 'Just Chatting',
               tags: [], title: '!MOUSEATHON DAY 10 AHHHH' },
      nomme: { id: '2', createdAt: h(74), viewers: 2100, game: 'Just Chatting',
               tags: [], title: '24H SUBATHON' },
      ordi:  { id: '3', createdAt: h(74), viewers: 7800, game: 'Just Chatting',
               tags: [], title: 'GTA RP tranquille' },
    };
    window.__addCard('mouse', 'Discussions', '8,4 k');
    window.__addCard('nomme', 'Discussions', '2,1 k');
    window.__addCard('ordi',  'Discussions', '7,8 k');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 3);

  const survoler = async (login) => {
    await hoverLogin(page, login);
    await attendre(page,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
    await wait(page, 400);
  };
  const quitter = async (login) => {
    await page.evaluate((l) => {
      [...document.querySelectorAll('.side-nav-card')]
        .find(c => c.dataset.tseLogin === l)
        ?.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
    }, login);
    await attendre(page,
      () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);
  };

  /* ── LE BADGE ────────────────────────────────────────────────────────── */
  await survoler('mouse');
  const avec = await page.evaluate(() => {
    const b = document.querySelector('.tse-preview__badge--subathon');
    return b ? { texte: b.textContent.trim(),
                 rang: [...document.querySelectorAll('.tse-preview__badge')].indexOf(b) }
             : null;
  });
  ok('une chaîne en subathon porte un badge qui en donne le jour',
     avec !== null && avec.texte === 'Subathon • JOUR 10', JSON.stringify(avec));
  await quitter('mouse');

  /* UN SUBATHON NOMMÉ SANS NUMÉRO garde son badge et n'invente pas de jour.
     « Subathon • JOUR null » serait le seul défaut que ce cas puisse produire,
     et il se produirait sur un titre parfaitement ordinaire — « 24H SUBATHON »
     nomme l'événement sans le compter. Le libellé connaît donc son cas nul. */
  await survoler('nomme');
  const sansJour = await page.evaluate(() =>
    document.querySelector('.tse-preview__badge--subathon')?.textContent.trim() ?? null);
  ok('…et un subathon non numéroté garde le badge sans inventer de jour',
     sansJour === 'Subathon', JSON.stringify(sansJour));
  await quitter('nomme');

  await survoler('ordi');
  const sans = await page.evaluate(() =>
    !!document.querySelector('.tse-preview__badge--subathon'));
  ok('…et une chaîne ordinaire n\'en porte aucun',  !sans, String(sans));
  await quitter('ordi');

  /* ── L'ARC-EN-CIEL, ÉCHANTILLONNÉ SUR TOUT SON CYCLE ──────────────────────
     C'est ici que le contrôle doit être plus qu'un coup d'œil. Le navigateur
     interpole en sRGB entre deux arrêts : le MILIEU d'un segment n'est ni
     l'un ni l'autre, et deux couleurs voisines peuvent se croiser en une
     teinte plus sombre que les deux. Contrôler les huit arrêts écrits dans la
     feuille ne dirait donc rien du chemin entre eux.

     ET LA CLARTÉ NE SE DEVINE PAS DE LA TEINTE : à clarté HSL égale, un bleu
     pèse trois fois moins qu'un jaune en luminance. Un arc-en-ciel écrit sans
     mesure s'éteint sur le bleu et le violet — c'est exactement le défaut que
     ce contrôle existe pour attraper.

     On rejoue donc l'animation pas à pas, on lit la couleur CALCULÉE à chaque
     pas, et on calcule le contraste comme le ferait un outil d'accessibilité.
     Quarante pas sur douze secondes : un tous les trois dixièmes. */
  await survoler('mouse');
  const arc = await page.evaluate(async () => {
    const lum = (c) => {
      const [r, g, b] = c.match(/[\d.]+/g).slice(0, 3).map(Number)
        .map(v => v / 255).map(v => v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4));
      return 0.2126 * r + 0.7152 * g + 0.0722 * b;
    };
    const contraste = (a, b) => {
      const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p);
      return (x + 0.05) / (y + 0.05);
    };
    /* LE FOND DU BADGE EST TRANSLUCIDE : le texte ne se lit pas sur la couleur
       écrite, mais sur sa COMPOSITION par-dessus le fond de l'aperçu. Un
       contraste calculé sur la couleur brute serait faux — et faux dans le
       sens rassurant, ce qui est le pire. */
    const composer = (couche, dessous) => {
      const c = couche.match(/[\d.]+/g).map(Number);
      const d = dessous.match(/[\d.]+/g).slice(0, 3).map(Number);
      const a = c.length > 3 ? c[3] : 1;
      return 'rgb(' + c.slice(0, 3).map((v, i) => v * a + d[i] * (1 - a)).join(', ') + ')';
    };
    const badge = document.querySelector('.tse-preview__badge--subathon');
    const puce  = document.querySelector('.tse-subathon-jour');
    const fondApercu = getComputedStyle(document.querySelector('.tse-preview')).backgroundColor;
    const anims = document.getAnimations();
    /* LA DURÉE SE LIT SUR L'ANIMATION, ELLE NE SE RECOPIE PAS. Écrite en dur,
       elle a menti dès que le cycle a changé de vitesse : l'échantillonnage
       parcourait alors huit tours au lieu d'un, deux arrêts par pas, et le
       contrôle du fondu tombait sur un code parfaitement sain. Un banc qui
       recopie une constante du produit mesure sa propre copie. */
    const duree = anims.reduce((m, a) =>
      Math.max(m, Number(a.effect.getComputedTiming().duration) || 0), 0);
    /* LE PLUS GRAND SAUT D'UNE IMAGE À L'AUTRE, en distance RGB. C'est ce qui
       distingue un FONDU d'une succession de paliers, et compter les couleurs
       distinctes ne le distingue pas : la première rédaction le faisait, et un
       mutant qui remplaçait le fondu par « steps(8) » lui a survécu. Sur
       quarante pas et huit arrêts, un fondu ne parcourt qu'un cinquième de
       segment par pas ; des paliers font le segment entier d'un coup. */
    let pireBadge = Infinity, pirePuce = Infinity, maxBadge = 0, maxSaut = 0;
    let precedente = null;
    const vues = new Set();
    for (let i = 0; i < 40; i++) {
      anims.forEach(a => { a.pause(); a.currentTime = i * duree / 40; });
      await new Promise(r => requestAnimationFrame(r));
      const cb = getComputedStyle(badge);
      const rb = contraste(cb.color, composer(cb.backgroundColor, fondApercu));
      const rp = contraste(getComputedStyle(puce).color, getComputedStyle(puce.closest('.side-nav-card')
        ? document.body : document.body).backgroundColor || 'rgb(24, 24, 27)');
      pireBadge = Math.min(pireBadge, rb); maxBadge = Math.max(maxBadge, rb);
      pirePuce = Math.min(pirePuce, rp);
      const v = cb.color.match(/[\d.]+/g).slice(0, 3).map(Number);
      if (precedente) {
        maxSaut = Math.max(maxSaut, Math.hypot(...v.map((x, k) => x - precedente[k])));
      }
      precedente = v;
      vues.add(cb.color);
    }
    anims.forEach(a => a.play());
    return { pireBadge: +pireBadge.toFixed(2), maxBadge: +maxBadge.toFixed(2),
             pirePuce: +pirePuce.toFixed(2), maxSaut: +maxSaut.toFixed(1),
             vues: vues.size, duree,
             anime: !!badge.getAnimations().length };
  });
  /* DEUX PROPRIÉTÉS, ET IL LES FAUT TOUTES DEUX — chacune seule laisse passer
     un défaut que l'autre attrape :

       • il TRAVERSE. Sans cela, une animation supprimée laisserait le badge sur
         sa couleur de repos, parfaitement contrastée et parfaitement immobile :
         le contrôle du contraste passerait, celui du saut aussi. Le mutant qui
         retire l'animation a survécu à la première rédaction pour cette raison,
         et `anims.length` ne le voyait pas — la pastille, elle, était toujours
         animée. On interroge donc LE BADGE.

       • il FOND. Quarante pas pour huit arrêts : un fondu avance d'un cinquième
         de segment par pas, des paliers franchissent le segment d'un coup. Le
         seuil est posé entre les deux et loin de chacun.

     Compter les couleurs ne suffit pas non plus : un « steps(8) » posé ENTRE
     chaque arrêt en rend soixante-quatre, ce qui fond encore — cette mutation
     n'était pas un défaut, et c'est « steps(1) » qui en est un. */
  ok('la couleur traverse l\'arc-en-ciel, et elle y fond au lieu d\'y sauter',
     arc.anime && arc.vues >= 20 && arc.maxSaut <= 45, JSON.stringify(arc));
  /* LE CONTRASTE TENU SUR TOUT LE CHEMIN. La famille des badges tient entre
     6,38 et 7,67:1 ; l'arc-en-ciel doit y rester à chacun des quarante pas,
     et non seulement à ses arrêts. Le plancher d'un petit texte est 4,5:1 :
     on exige la fourchette de la famille, qui est bien plus étroite. */
  ok('…et le contraste du badge reste dans la fourchette de ses voisins, à chaque pas',
     arc.pireBadge >= 6.38 && arc.maxBadge <= 7.67,
     `${arc.pireBadge} à ${arc.maxBadge}:1 (famille : 6,38 à 7,67)`);
  ok('…la pastille de la carte ne s\'éteint sur aucune teinte',
     arc.pirePuce >= 4.5, `${arc.pirePuce}:1 au pire`);
  await quitter('mouse');
  await page.close();

  /* ── LE CLIGNOTEMENT DE « TOP CHAÎNES » ──────────────────────────────────
     « En Top Chaînes, l'élément J… clignote toutes les 30 secondes. » La cause
     n'est pas dans l'animation : c'est l'AMORCE du mode. Une carte du
     classement est décorée deux fois par relevé — d'abord avec une entrée
     bâtie à la main depuis le classement, puis avec la réponse de TseChannels.
     Le classement ne demande pas les titres (il en pèserait mille six cents
     pour une marque décorative), donc son amorce n'a rien à dire du subathon —
     et une absence de champ se lisait comme « ce n'en est pas un ». La
     pastille tombait à l'amorce et revenait à la réponse. Une fois par relevé,
     indéfiniment.

     ON L'ÉCHANTILLONNE IMAGE PAR IMAGE, et c'est la seule façon de l'attraper :
     le trou dure le temps d'un aller-retour réseau. Deux relevés complets sous
     les durées accélérées du banc, une lecture à chaque rafraîchissement
     d'écran, et l'on compte les images où la pastille a disparu APRÈS être
     apparue. Zéro est la seule réponse acceptable. */
  {
    const p2 = await fresh();
    await p2.evaluate(() => {
      window.__cats = [{ name: 'cSub', viewers: 9000,
                         streams: [{ login: 'mouseglobal', viewers: 8400 }] }];
      window.__fx = {
        mouseglobal: { id: 'g1',
          createdAt: new Date(Date.now() - 2277 * 60_000).toISOString(),
          viewers: 8400, game: 'Just Chatting', tags: [],
          title: '!MOUSEATHON DAY 10 AHHHH' },
        /* UNE CARTE DE TWITCH DOIT ÊTRE LÀ, et ce n'est pas un artifice de
           décor : le mode Top Chaînes CLONE une carte native pour fabriquer
           les siennes. Sans modèle, il n'en fabrique aucune, et le scénario
           ne mesurerait rien du tout — c'est ce qui est arrivé à la première
           rédaction, qui veillait sur une sidebar vide. */
        modele: { id: 'm',
          createdAt: new Date(Date.now() - 60 * 60_000).toISOString(),
          viewers: 1000, game: 'Just Chatting', tags: [], title: 'rien' },
      };
      window.__addCard('modele', 'Discussions', '1 k');
    });
    await attendre(p2, () => document.querySelectorAll('[data-tse-viewers]').length === 1);
    await p2.evaluate(() => window.tse.global.on());
    await attendre(p2, () => !!document.querySelector('.tse-subathon-jour'), 12000);

    const veille = await p2.evaluate(() => new Promise((resolve) => {
      const fin = performance.now() + 3000;
      let images = 0, absences = 0, jours = new Set();
      const pas = () => {
        const p = document.querySelector('.side-nav-card[data-tse-global="true"] .tse-subathon-jour');
        images++;
        if (!p) absences++; else jours.add(p.textContent);
        if (performance.now() < fin) requestAnimationFrame(pas);
        else resolve({ images, absences, jours: [...jours] });
      };
      requestAnimationFrame(pas);
    }));
    ok('en Top Chaînes, la pastille ne disparaît plus une seule image sur deux relevés',
       veille.absences === 0 && veille.images > 60
       && veille.jours.length === 1 && veille.jours[0] === 'J10',
       JSON.stringify(veille));
    await p2.close();
  }
}

titre('94. L\'aperçu au survol — un délai d\'intention, et ce qu\'il filtre');
{
  /* ── CE QUE CE SCÉNARIO GARDE ────────────────────────────────────────────
     `mouseenter` appelait `open()` sans détour. Descendre la liste pour aller
     ailleurs ouvrait donc un aperçu PAR CARTE FRANCHIE, chacun payé d'un
     rendu, d'une requête TsePreview et d'un journal écrasé. Le délai
     d'intention de la 3.95 répare ça, et ce scénario tient les quatre
     comportements qui le composent — parce qu'ils se cassent séparément.

     LE POINTEUR EST UN VRAI POINTEUR. Les autres scénarios fabriquent des
     MouseEvent à la main, ce qui suffit tant qu'on regarde ce que fait un
     handler. Ici c'est le NAVIGATEUR qui doit décider quelles cartes sont
     entrées et lesquelles sont quittées, et dans quel ordre — un événement
     fabriqué court-circuiterait précisément la mécanique qu'on éprouve.
     D'où `page.mouse.move`, et des coordonnées relevées sur le rendu. */
  const page = await fresh();
  await page.evaluate(() => {
    const h = (m) => new Date(Date.now() - m * 60_000).toISOString();
    window.__fx = {};
    for (const l of ['un', 'deux', 'trois', 'quatre', 'cinq']) {
      window.__fx[l] = { id: 'i-' + l, createdAt: h(90), viewers: 500,
                         game: 'Just Chatting', tags: [] };
      window.__addCard(l, 'Discussions', '500');
    }
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 9);
  /* ATTENDRE QUE LE VOILE SE LÈVE, et ce n'est pas une précaution de confort :
     le voile de chargement couvre la barre, et un VRAI pointeur ne traverse
     pas un élément posé par-dessus. Tant qu'il est là, aucune carte ne reçoit
     d'entrée — le scénario passait donc ses cinq premières assertions sans
     avoir rien survolé du tout. Un MouseEvent fabriqué, lui, aurait ignoré le
     voile et n'aurait rien appris. C'est le prix du vrai pointeur, et il se
     paie une fois. */
  await attendre(page, () => !document.body.classList.contains('tse-loading'), 8000);

  const centres = await page.evaluate(() =>
    [...document.querySelectorAll('.side-nav-card')].map((c) => {
      const r = c.getBoundingClientRect();
      return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
    }));
  // Un point FRANCHEMENT hors de la liste, pour poser et reposer le pointeur
  // entre deux épreuves sans frôler une carte au passage.
  const ailleurs = { x: 900, y: 40 };

  const visible = () => page.evaluate(() =>
    !!document.querySelector('.tse-preview[data-tse-visible="true"]'));
  const survol = () => page.evaluate(() => window.tse.panneau.rapport().survol);
  const demandes = () => page.evaluate(() =>
    window.__calls.filter(c => (c.names || []).includes('TsePreview')).length);
  const remiseAZero = () => page.evaluate(() => { window.__calls.length = 0; });

  await page.mouse.move(ailleurs.x, ailleurs.y);
  await remiseAZero();

  /* ── LA TRAVERSÉE ────────────────────────────────────────────────────────
     Soixante millisecondes par carte : c'est ce qu'un pointeur passe sur une
     rangée de 42 px lorsqu'il descend à 700 px/s, soit un geste ordinaire.
     Bien en deçà des 200 ms du délai, donc rien ne doit s'ouvrir — et c'est
     la première fois qu'on le demande. */
  const vuPendant = [];
  for (const c of centres) {
    await page.mouse.move(c.x, c.y);
    await wait(page, 60);
    /* RELEVÉ PENDANT, ET PAS SEULEMENT APRÈS. La première forme de cette
       assertion regardait l'écran une fois la traversée finie, où l'aperçu
       s'était de toute façon refermé : elle survivait au défaut qu'elle était
       censée décrire. Ce que l'utilisateur voit, c'est la série de battements
       PENDANT le geste ; c'est donc elle qu'il faut relever. */
    vuPendant.push(await visible());
  }
  await page.mouse.move(ailleurs.x, ailleurs.y);
  await wait(page, 600);          // largement au-delà du délai

  ok('traverser la liste n\'ouvre aucun aperçu, pas même le temps d\'un battement',
     vuPendant.every(v => v === false) && (await visible()) === false,
     JSON.stringify(vuPendant));
  /* L'ASSERTION QUI COMPTE VRAIMENT. Un aperçu qu'on n'affiche pas mais dont
     on a quand même payé la requête n'aurait rien réparé : le défaut était
     autant une dépense qu'une gêne. */
  ok('…et n\'émet aucune requête d\'aperçu', (await demandes()) === 0,
     `${await demandes()} requête(s) TsePreview`);
  const apresTraversee = await survol();
  ok('…ce que le rapport dit en toutes lettres',
     apresTraversee.armes >= 5 && apresTraversee.ouverts === 0
     && apresTraversee.delaiMs > 0,
     JSON.stringify(apresTraversee));

  /* ── L'INTENTION ─────────────────────────────────────────────────────────
     L'autre moitié du contrat, et celle qu'un délai trop long casserait sans
     qu'aucune des assertions précédentes ne bronche. */
  await page.mouse.move(centres[1].x, centres[1].y);
  await attendre(page,
    () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);
  ok('une carte tenue sous le pointeur ouvre bien l\'aperçu', await visible());
  ok('…et c\'est elle, et elle seule, qui a coûté la requête',
     (await demandes()) >= 1 && (await survol()).ouverts === 1,
     JSON.stringify({ demandes: await demandes(), survol: await survol() }));

  /* ── LE DÉPART PENDANT L'ATTENTE ─────────────────────────────────────────
     LE PIÈGE, et il a bien failli être posé. Le handler de sortie se gardait
     par `card !== currentCard` : sur une carte encore en attente, il ne
     reconnaissait rien et laissait le minuteur courir jusqu'au bout. L'aperçu
     se serait ouvert APRÈS le départ du pointeur — plus tard que le défaut
     qu'on répare, et sur une carte que l'utilisateur ne désigne plus. */
  await page.mouse.move(ailleurs.x, ailleurs.y);
  await attendre(page,
    () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);
  const avantDepart = (await survol()).ouverts;
  await page.mouse.move(centres[3].x, centres[3].y);
  await wait(page, 100);          // la moitié du délai : l'attente est en cours
  await page.mouse.move(ailleurs.x, ailleurs.y);
  await wait(page, 700);          // trois fois et demie le délai
  ok('repartir pendant l\'attente n\'ouvre rien, ni maintenant ni plus tard',
     (await visible()) === false && (await survol()).ouverts === avantDepart,
     JSON.stringify(await survol()));

  /* ── LA SORTIE DE LA FENÊTRE PENDANT L'ATTENTE ───────────────────────────
     Le troisième chemin d'annulation, et il ne passe pas par la carte : c'est
     le `mouseleave` de <html>, celui qui ne se produit que lorsque le pointeur
     quitte vraiment la page. Sans lui, un minuteur armé survivrait au pointeur
     qui l'a armé — plus aucun événement ne viendrait, et l'aperçu s'ouvrirait
     sur un écran que personne ne regarde.

     ICI L'ÉVÉNEMENT EST POSÉ, ET C'EST LA SEULE FAÇON. Ailleurs dans ce
     scénario le pointeur est un vrai pointeur ; pas pour cette épreuve-là,
     parce qu'elle est irreproductible autrement. `mouse.move(-8, y)` fait
     dispatcher au navigateur un `mousemove` À CETTE POSITION : la dernière
     position connue devient extérieure, la sortie de la carte se voit donc
     toute seule, et le handler de <html> n'a plus rien à rattraper — mesuré,
     le mutant qui le vide passe ce test sans broncher. Le défaut réel est
     l'inverse : sur une machine à deux écrans, le curseur part sur l'écran de
     gauche et la page ne reçoit PLUS AUCUN mousemove, si bien que la dernière
     position connue est encore sur la carte. C'est cet état-là qu'on pose —
     le signal que le navigateur envoie, comme on pose `visibilitychange`
     juste en dessous. */
  const avantSortie = (await survol()).ouverts;
  await page.mouse.move(centres[4].x, centres[4].y);
  await wait(page, 60);           // l'attente court, bien en deçà du délai
  await page.evaluate(() =>
    document.documentElement.dispatchEvent(new MouseEvent('mouseleave')));
  await wait(page, 700);
  ok('quitter la fenêtre pendant l\'attente ne laisse rien s\'ouvrir',
     (await visible()) === false && (await survol()).ouverts === avantSortie,
     JSON.stringify(await survol()));

  /* ── L'ONGLET QUI PASSE EN ARRIÈRE-PLAN PENDANT L'ATTENTE ────────────────
     Le quatrième chemin. Un minuteur armé ne doit pas ouvrir un aperçu — ni
     partir en requête — sur un onglet que personne ne regarde plus. On pose le
     SIGNAL que le navigateur enverrait ; c'est lui que l'extension lit. */
  const cacher = (p, c) => p.evaluate((v) => {
    Object.defineProperty(document, 'hidden', { configurable: true, get: () => v });
    Object.defineProperty(document, 'visibilityState',
      { configurable: true, get: () => (v ? 'hidden' : 'visible') });
    document.dispatchEvent(new Event('visibilitychange'));
  }, c);
  const avantCache = (await survol()).ouverts;
  await page.mouse.move(centres[2].x, centres[2].y);
  await wait(page, 60);
  await cacher(page, true);
  await wait(page, 700);
  ok('un onglet qui s\'efface pendant l\'attente n\'ouvre rien non plus',
     (await visible()) === false && (await survol()).ouverts === avantCache,
     JSON.stringify(await survol()));
  await cacher(page, false);

  /* ── LA MODALE DE TWITCH, PENDANT L'ATTENTE ──────────────────────────────
     LE DÉFAUT QU'UN UTILISATEUR A VU AVANT CE BANC. Twitch pose une
     `.tw-dialog-layer` au survol d'une carte — le conteneur React de son
     propre tooltip d'aperçu. L'extension la masque par
     `body.tse-preview-active`, et ce drapeau était posé par open(). Tant que
     le survol ouvrait dans l'instant, les deux moments se confondaient ; le
     délai d'intention a ouvert entre eux deux dixièmes de seconde pendant
     lesquels la modale de Twitch apparaissait seule. Une petite fenêtre grise,
     juste avant l'aperçu.

     ON MESURE L'EFFET, PAS LE DRAPEAU. Vérifier que <body> porte la classe
     dirait que l'intention est là, pas que la règle mord : un sélecteur mal
     écrit passerait. On injecte donc une vraie `.tw-dialog-layer` et on lit le
     `display` que le navigateur lui calcule. C'est aussi la première fois que
     ce masquage est éprouvé — il n'existait dans aucun décor du banc, ce qui
     est précisément pourquoi la régression est passée. */
  await page.evaluate(() => {
    const d = document.createElement('div');
    d.className = 'tw-dialog-layer';
    d.id = 'sonde-modale';
    d.textContent = 'modale de Twitch';
    document.body.appendChild(d);
  });
  const modale = () => page.evaluate(() =>
    getComputedStyle(document.getElementById('sonde-modale')).display);

  await page.mouse.move(ailleurs.x, ailleurs.y);
  await wait(page, 700);          // le voile se lève avec retard
  ok('hors survol, la modale de Twitch reste la sienne',
     (await modale()) !== 'none', await modale());

  await page.mouse.move(centres[0].x, centres[0].y);
  await wait(page, 60);           // PENDANT l'attente : l'aperçu n'est pas là
  const pendantAttente = await modale();
  const apercuPasEncore = await visible();
  ok('dès l\'entrée du pointeur, et avant même l\'aperçu, elle est masquée',
     pendantAttente === 'none' && apercuPasEncore === false,
     JSON.stringify({ modale: pendantAttente, apercu: apercuPasEncore }));

  /* ET ELLE DOIT REVENIR. Le voile posé plus tôt se paie ici : une simple
     traversée de la liste ne doit pas laisser Twitch sans ses modales — le
     menu utilisateur et les paramètres passent par la même couche. */
  await page.mouse.move(ailleurs.x, ailleurs.y);
  await attendre(page,
    () => getComputedStyle(document.getElementById('sonde-modale')).display !== 'none',
    3000);
  ok('…et une attente abandonnée la lui rend',
     (await modale()) !== 'none', await modale());

  /* ── CE QUE CE SCÉNARIO NE PROUVE PAS, ET POURQUOI ───────────────────────
     L'attente est aussi protégée contre la RÉCONCILIATION REACT : une carte
     déplacée sous un pointeur immobile ne doit ni annuler le minuteur ni le
     réarmer. Deux gardes le tiennent — le test anti-fantôme du `mouseleave`,
     partagé avec l'aperçu déjà ouvert, et le `card === pendingCard` de
     l'entrée.

     Aucun des deux n'est éprouvé ici, et ce n'est pas un oubli : ils sont
     INATTEIGNABLES depuis ce banc. Mesuré, sur ce moteur, pointeur immobile
     au centre d'une carte :

       parentElement.appendChild(carte)   → aucun événement
       remove() puis append() même tâche  → aucun événement
       remove(), deux images, append()    → « enter » seul
       display:none puis retour           → « leave » puis « enter »

     Or c'est la PREMIÈRE forme que produisent Twitch et applySorting, et elle
     n'émet rien du tout : il n'y a pas de fantôme à absorber. Les deux gardes
     restent — ils coûtent une ligne chacun et la quatrième forme, elle, existe
     — mais on n'écrira pas ici d'assertion qui passerait sans rien toucher.
     C'est le même relevé qui montre que l'assertion « une carte détachée puis
     rattachée ne referme pas l'aperçu » du scénario 76 ne touche rien non plus. */

  await page.close();
}
titre('95. La reprise après coupure — un badge, une barre, et une frise qui ne recommence pas');
{
  /* ── CE QUE CE SCÉNARIO GARDE ────────────────────────────────────────────
     `createdAt` mesure la SESSION, pas le direct. Un streamer qui perd sa
     connexion et revient repart de zéro, et la barre violette « vient de
     démarrer » s'allume sur un live qui en est à sa sixième heure. Ce n'est
     pas une information approximative, c'est la seule du produit qui affirmait
     le CONTRAIRE de la vérité : « tu n'as rien raté » à quelqu'un qui a tout
     raté.

     QUATRE CAS, ET IL FAUT LES QUATRE. Deux disent ce que la règle doit
     attraper, deux ce qu'elle ne doit pas : une règle qui ne se trompe jamais
     dans un sens se trompe toujours dans l'autre, et c'est le sur-déclenchement
     qui coûterait le plus cher ici — un badge « reprise » sur une chaîne qui
     vient réellement d'ouvrir serait pire que pas de badge du tout. */
  const page = await fresh();
  const h = (min) => new Date(Date.now() - min * 60_000).toISOString();
  await page.evaluate((debuts) => {
    window.__fx = {
      coupe:   { id: 'c1', sid: 's-coupe-1',  createdAt: debuts.vieux, viewers: 900,
                 game: 'Just Chatting', tags: [] },
      longue:  { id: 'c3', sid: 's-longue-1', createdAt: debuts.vieux, viewers: 700,
                 game: 'Just Chatting', tags: [] },
      agee:    { id: 'c4', sid: 's-agee-1',   createdAt: debuts.vieux, viewers: 600,
                 game: 'Just Chatting', tags: [] },
      brieve:  { id: 'c5', sid: 's-brieve-1', createdAt: debuts.vieux, viewers: 500,
                 game: 'Just Chatting', tags: [] },
      // Un subathon, reconnu à son titre. Il redémarrera comme les autres —
      // et ne devra PAS être compté comme une coupure (cf. plus bas).
      marathon: { id: 'c6', sid: 's-marathon-1', createdAt: debuts.vieux, viewers: 400,
                  game: 'Just Chatting', tags: [],
                  title: 'SUBATHON JOUR 6 — on continue !' },
    };
    // « neuve » a une carte dès le départ mais AUCUNE entrée dans __fx : elle
    // est donc hors ligne, comme une chaîne suivie qui n'émet pas encore.
    for (const l of ['coupe', 'neuve', 'longue', 'agee', 'brieve', 'marathon']) {
      window.__addCard(l, 'Discussions', '900');
    }
  }, { vieux: h(360) });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 9);

  const etat = (login) => page.evaluate((l) => {
    const c = [...document.querySelectorAll('.side-nav-card')].find(x => x.dataset.tseLogin === l);
    return c ? { frais: c.classList.contains('tse-fresh'),
                 debut: c.dataset.tseStartedAt,
                 duree: c.querySelector('.tse-uptime')?.textContent || '' } : null;
  }, login);
  const compteurs = () => page.evaluate(() => window.tse.panneau.rapport().compteurs);
  const bilanFrise = () => page.evaluate(() => window.tse.panneau.rapport().frise);

  /* Reprend le direct d'une chaîne : nouvel identifiant de stream, nouveau
     départ. C'est exactement ce que Twitch sert après une reconnexion. */
  const reprendre = (login, ilYaMin, n = 2) => page.evaluate(([l, iso, k]) => {
    window.__fx[l].sid = 's-' + l + '-' + k;
    window.__fx[l].createdAt = iso;
    window.tse.rescan();
  }, [login, new Date(Date.now() - ilYaMin * 60_000).toISOString(), n]);

  const survoler = async (login) => {
    await hoverLogin(page, login);
    await attendre(page,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
    return page.evaluate(() => [...document.querySelectorAll('.tse-preview__badge')]
      .map(b => ({ classe: b.className, texte: b.textContent.trim() })));
  };
  /* Ce que la frise de l'aperçu affiche, lu après coup : l'aperçu est un
     singleton, il faut donc l'avoir ouvert sur la bonne carte. */
  const frise = () => page.evaluate(() => {
    const f = document.querySelector('.tse-preview__frise');
    if (!f) return null;
    const t = (sel) => f.querySelector(sel)?.textContent.trim() || '';
    return {
      total:    t('.tse-preview__frise-total'),
      coupures: t('.tse-preview__frise-coupures'),
      marques:  [...f.querySelectorAll('.tse-preview__frise-coupure')]
        .map(m => ({ gauche: parseFloat(m.style.left), large: parseFloat(m.style.width) })),
      lignes:   [...f.querySelectorAll('.tse-preview__frise-ligne')]
        .map(li => li.textContent.trim()),
    };
  });
  const changerJeu = (login, jeu) => page.evaluate(([l, j]) => {
    window.__fx[l].game = j;
    window.tse.rescan();
  }, [login, jeu]);
  const relacher = async (login) => {
    await page.evaluate((l) => {
      [...document.querySelectorAll('.side-nav-card')]
        .find(c => c.dataset.tseLogin === l)
        ?.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
    }, login);
    await attendre(page,
      () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);
  };

  /* ── 1. LA REPRISE ───────────────────────────────────────────────────────
     Six heures de direct, une coupure, et le revoilà avec un compteur à zéro. */
  const avant = await etat('coupe');
  ok('avant la coupure, la carte n\'est évidemment pas « fraîche »',
     avant !== null && avant.frais === false, JSON.stringify(avant));

  /* ── UNE FRISE À SAUVER ──────────────────────────────────────────────────
     Un seul segment ne fait pas une frise : le bloc se tait quand il n'aurait
     à raconter que notre propre fenêtre d'observation. On fait donc basculer
     la chaîne une fois AVANT la coupure — c'est le cas réaliste, et c'est le
     seul décor où « la frise n'a pas recommencé » veut dire quelque chose. */
  await changerJeu('coupe', 'Elden Ring');
  await wait(page, 900);
  await survoler('coupe');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 6000);
  const friseAvant = await frise();
  await relacher('coupe');
  ok('avant la coupure, la frise porte les deux catégories et aucune coupure',
     friseAvant !== null && friseAvant.lignes.length >= 2
     && friseAvant.lignes.some(l => /Elden Ring/.test(l))
     && friseAvant.coupures === '' && friseAvant.marques.length === 0,
     JSON.stringify(friseAvant));

  await reprendre('coupe', 0);
  await attendre(page, async () => true);
  await wait(page, 900);           // le temps d'un relevé à la cadence du banc

  const apres = await etat('coupe');
  /* L'ASSERTION QUI COMPTE. Sans la correction, `createdAt` vaut « maintenant »
     et la barre violette s'allume — le produit dirait « vient de démarrer »
     d'un live commencé il y a six heures. */
  ok('une reprise ne rallume pas la barre « vient de démarrer »',
     apres !== null && apres.frais === false,
     JSON.stringify(apres));

  /* ── LA CARTE COMPTE LE DIRECT, ET C'EST LE TROISIÈME TOUR DE CETTE LIGNE ─
     ELLE A DIT LES DEUX CHOSES TOUR À TOUR, et il faut dire pourquoi elle
     s'arrête ici. Premier tour : le compteur devait repartir de l'origine.
     Deuxième tour : non, la carte compte la SESSION comme Twitch, et l'aperçu
     porte le direct entier — « deux vérités pour une même chose valent moins
     qu'une seule bien placée ».

     LE TERRAIN A TRANCHÉ, CAPTURE À L'APPUI : une carte annonçait « 3h41 »
     pendant que l'aperçu, juste en dessous, annonçait « 10h11 · 1 coupure »
     pour le même direct. Les deux vérités étaient donc tenues QUAND MÊME —
     simplement, c'est l'utilisateur qui devait les réconcilier. Le raisonnement
     du deuxième tour était juste et sa conclusion fausse : il supposait qu'on
     pouvait n'en montrer qu'une.

     ENTRE SUIVRE TWITCH ET RÉPONDRE À LA QUESTION QU'ON SE POSE — « depuis
     combien de temps il diffuse » — c'est la seconde qui gagne. */
  ok('…et le compteur de la carte garde le départ du DIRECT, non celui du tronçon',
     apres !== null && apres.debut === avant.debut,
     JSON.stringify({ avant: avant.debut, apres: apres && apres.debut,
                      duree: apres && apres.duree }));
  /* ET ÇA SE VOIT À L'ÉCRAN, pas seulement dans le dataset : une durée en
     minutes seules serait le compteur du tronçon, qui vient de repartir. */
  ok('…ce qui se lit sur la carte en heures, et non en minutes de tronçon',
     apres !== null && /h/.test(apres.duree),
     JSON.stringify({ duree: apres && apres.duree }));

  const badges = await survoler('coupe');
  const reprise = badges.find(b => b.classe.includes('tse-preview__badge--reprise'));
  ok('…et l\'aperçu le dit, dans un badge',
     !!reprise && reprise.texte.length > 0, JSON.stringify(badges));
  /* LE VERT DU BASCULEMENT, ET PAS UNE SECONDE TEINTE. C'est la même espèce de
     nouvelle, et le scénario 60 exige qu'un TYPE de badge ait une couleur à
     lui : en inventer une pour celui-ci irait contre ce qu'il protège. La
     classe `--reprise` nomme la chose ; c'est `--switch` qui la colore. */
  ok('…en portant le vert du badge de basculement, et non une teinte de plus',
     !!reprise && reprise.classe.includes('tse-preview__badge--switch'),
     reprise && reprise.classe);
  await relacher('coupe');

  ok('le rapport compte la reprise', (await compteurs()).reprises === 1,
     JSON.stringify(await compteurs()));

  /* ══ LA FRISE TRAVERSE LA COUPURE ══════════════════════════════════════════
     C'est la moitié qui manquait, et c'était la plus visible : l'identifiant
     de stream change à chaque reprise, et la frise repartait donc de zéro. Un
     spectateur qui survolait après une coupure de trois minutes ne voyait plus
     rien du direct — « Précédemment sur ce live » recommençait à la sixième
     heure, ce qui est exactement le contraire de ce que ce bloc promet.

     TROIS CHOSES À ÉPROUVER, et elles se cassent séparément : le passé est
     gardé, le total couvre toujours le direct entier, et la coupure est DITE
     — en toutes lettres dans l'en-tête, et d'un trait sur le ruban. */
  await survoler('coupe');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 6000);
  const friseApres = await frise();
  await relacher('coupe');

  ok('la frise n\'a pas recommencé : les catégories d\'avant la coupure y sont encore',
     friseApres !== null
     && friseApres.lignes.some(l => /Elden Ring/.test(l))
     && friseApres.lignes.length >= friseAvant.lignes.length,
     JSON.stringify({ avant: friseAvant && friseAvant.lignes, apres: friseApres && friseApres.lignes }));

  /* LE TOTAL EST LA SEULE DURÉE JUSTE DU PRODUIT, et c'est ici qu'on l'exige.
     La carte compte la session — deux minutes — et c'est assumé ; l'en-tête de
     la frise, lui, couvre le direct entier, coupure comprise. Six heures, et
     non deux minutes, sur la même chaîne au même instant. */
  ok('…et son total couvre toujours le direct entier, pas le tronçon',
     friseApres !== null && /^(\d+)h\d\d$/.test(friseApres.total)
     && Number(/^(\d+)h/.exec(friseApres.total)[1]) >= 5,
     JSON.stringify({ total: friseApres && friseApres.total, carte: apres && apres.duree }));

  /* LE FAIT, ET NON LA NOUVELLE. Le badge s'éteint au bout de dix minutes ;
     le compte des coupures, lui, appartient au direct et reste tant qu'il
     dure. Une marque sur le ruban par coupure, à sa place. */
  ok('…avec le compte des coupures en tête, et un trait sur le ruban',
     friseApres !== null && /\b1\b/.test(friseApres.coupures)
     && friseApres.coupures !== '' && friseApres.marques.length === 1
     && friseApres.marques[0].gauche >= 0 && friseApres.marques[0].gauche <= 100,
     JSON.stringify({ coupures: friseApres && friseApres.coupures,
                      marques: friseApres && friseApres.marques }));

  /* LA CHAÎNE DE REPRISES. Un direct qui saute deux fois ne redémarre pas deux
     fois : le total doit encore couvrir depuis la première origine, et le
     compte passer à deux. C'est l'origine MÉMORISÉE qu'on reprend, et non le
     départ du tronçon d'avant — sans quoi chaque coupure grignoterait un
     tronçon de direct. */
  await reprendre('coupe', 0, 3);
  await wait(page, 900);
  await survoler('coupe');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 6000);
  const frise2 = await frise();
  await relacher('coupe');
  ok('une deuxième coupure s\'ajoute au compte et au ruban, sans toucher au total',
     frise2 !== null && /\b2\b/.test(frise2.coupures) && frise2.marques.length === 2
     && /^(\d+)h\d\d$/.test(frise2.total)
     && Number(/^(\d+)h/.exec(frise2.total)[1]) >= 5,
     JSON.stringify({ coupures: frise2 && frise2.coupures, total: frise2 && frise2.total,
                      marques: frise2 && frise2.marques.length }));

  /* ── 2. CE QUI N'EST PAS UNE REPRISE ─────────────────────────────────────
     Trois façons de sur-déclencher, trois gardes, et chacune se mute seule. */

  /* a) LE CAS ORDINAIRE, et le plus important des trois : une chaîne suivie
        qui passe en direct. Jamais vue en ligne auparavant, donc aucune
        mémoire à reprendre — son départ est le sien, et la barre violette doit
        s'allumer comme avant. Si la règle mordait ici, elle éteindrait le
        signal « vient de démarrer » sur toutes les chaînes qui démarrent : une
        régression bien plus grave que le défaut réparé.

        La première rédaction éprouvait autre chose : elle faisait RAJEUNIR un
        direct sans changer son identifiant de stream. Cela ne peut pas
        arriver — `createdAt` appartient au stream, s'il change c'est que le
        stream a changé — et le cas ne décrivait donc rien de réel. */
  await page.evaluate(() => {
    window.__fx.neuve = { id: 'c2', sid: 's-neuve-1', createdAt: new Date().toISOString(),
                          viewers: 800, game: 'Just Chatting', tags: [] };
    window.tse.rescan();
  });
  await wait(page, 900);
  const neuve = await etat('neuve');
  const badgesNeuve = await survoler('neuve');
  ok('une chaîne qui passe en direct garde sa barre « vient de démarrer »',
     neuve !== null && neuve.frais === true
     && !badgesNeuve.some(b => b.classe.includes('--reprise')),
     JSON.stringify({ neuve, badges: badgesNeuve.map(b => b.texte) }));
  await relacher('neuve');

  /* a bis) LA COUPURE QU'ON VOIT PASSER. Les cas ci-dessus changent
        d'identifiant d'un relevé à l'autre : la chaîne n'est jamais observée
        hors ligne, ce qui est le cas le plus fréquent à trente secondes de
        cadence. Mais une coupure de trois minutes tombe sur cinq ou six
        relevés, et la frise était alors détruite au premier — il ne restait
        plus rien à raccorder au retour. C'est la RETENUE qu'on éprouve ici, et
        elle ne se voit que sur une chaîne qu'on a vraiment vue s'éteindre. */
  await changerJeu('brieve', 'Minecraft');
  await wait(page, 900);
  await page.evaluate(() => { window.__fx.brieve = null; window.tse.rescan(); });
  await wait(page, 700);            // hors ligne, mais sous RECONNECT_GAP_MAX
  await page.evaluate(() => {
    window.__fx.brieve = { id: 'c5', sid: 's-brieve-2',
                           createdAt: new Date().toISOString(), viewers: 500,
                           game: 'Minecraft', tags: [] };
    window.tse.rescan();
  });
  await wait(page, 900);
  await survoler('brieve');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 6000);
  const friseBrieve = await frise();
  await relacher('brieve');
  ok('une coupure VUE PASSER ne détruit pas la frise : elle est retenue, puis reprise',
     friseBrieve !== null && friseBrieve.lignes.some(l => /Minecraft/.test(l))
     && /\b1\b/.test(friseBrieve.coupures) && friseBrieve.marques.length === 1,
     JSON.stringify(friseBrieve));

  /* b) La coupure LONGUE. Au-delà de RECONNECT_GAP_MAX, une chaîne qui revient
        ouvre un nouveau direct : « vient de démarrer » redevient vrai, et il
        n'y a plus rien à corriger.

        IL FAUT VRAIMENT LA COUPER, et la première rédaction ne le faisait pas :
        elle attendait 3,2 s en laissant la chaîne EN LIGNE, puis changeait son
        identifiant. Or la mémoire du dernier direct se rafraîchit à chaque
        relevé tant que la chaîne émet — l'écart mesuré restait donc celui d'un
        relevé, jamais 3,2 s, et le test disait « coupure longue » en n'en
        ayant produit aucune. C'est le décor qui était faux, pas la règle : elle
        avait raison de voir une reprise. On la met donc hors ligne pour de
        bon, ce qui est la seule façon d'arrêter cette mémoire. */
  await changerJeu('longue', 'Valorant');
  await wait(page, 900);
  await page.evaluate(() => { window.__fx.longue = null; window.tse.rescan(); });
  await wait(page, 3400);          // hors ligne, bien au-delà de RECONNECT_GAP_MAX
  await page.evaluate(() => {
    window.__fx.longue = { id: 'c3', sid: 's-longue-2',
                           createdAt: new Date().toISOString(), viewers: 700,
                           game: 'Just Chatting', tags: [] };
    window.tse.rescan();
  });
  await wait(page, 900);
  const longue = await etat('longue');
  ok('après une coupure LONGUE, le direct est neuf et sa barre s\'allume',
     longue !== null && longue.frais === true, JSON.stringify(longue));

  /* LA RETENUE EST BORNÉE, et c'est ce qui empêche le registre de se remplir
     de chaînes éteintes. Passé GAP, la frise est lâchée : la chaîne qui revient
     en ouvre une NEUVE, qui repart de son propre départ. Deux catégories
     avaient pourtant été observées avant la coupure ; les revoir ici voudrait
     dire que la retenue ne s'arrête jamais.

     LE BLOC NE DISPARAÎT PAS POUR AUTANT, et c'est une distinction qui compte :
     un direct qu'on suit depuis sa première seconde a une frise dès son unique
     catégorie — c'est la règle posée au scénario 87, et elle n'a rien à voir
     avec celle-ci. Ce qu'on exige, c'est qu'elle ait TOUT OUBLIÉ : pas de
     Valorant, et un total qui se compte en minutes et non en heures. */
  await survoler('longue');
  await wait(page, 400);
  const friseLongue = await frise();
  await relacher('longue');
  ok('…et sa frise a bien été lâchée en route : elle repart de zéro',
     friseLongue !== null
     && !friseLongue.lignes.some(l => /Valorant/.test(l))
     && /^\d+m$/.test(friseLongue.total) && friseLongue.coupures === '',
     JSON.stringify(friseLongue));

  /* ── ET LE REGISTRE, LUI, S'EST VIDÉ ─────────────────────────────────────
     L'assertion ci-dessus ne dit PAS que la frise retenue a été relâchée : la
     comparaison d'origine suffirait à la faire repartir de zéro même si le
     registre gardait la vieille entrée jusqu'à la fin des temps. Ce qui se
     joue ici n'est donc pas l'affichage mais la MÉMOIRE — une retenue sans
     borne remplirait `frises` de chaînes éteintes, et rien à l'écran ne le
     dirait jamais. Le rapport, lui, le dit : `retenues` compte les frises
     entrées en attente, `lachees` celles que l'attente a fini par emporter. */
  const bf = await bilanFrise();
  ok('…et le registre a relâché ce qu\'il retenait — la retenue est bornée',
     bf.retenues >= 2 && bf.lachees >= 1 && bf.lachees < bf.retenues,
     JSON.stringify({ retenues: bf.retenues, lachees: bf.lachees,
                      resident: bf.resident }));

  /* b bis) LE SUBATHON, QUI NE COUPE PAS MAIS RECOMMENCE ───────────────────
        Twitch impose de relancer une diffusion au moins toutes les
        quarante-huit heures. Un subathon est donc FAIT de redémarrages, et
        chacun ressemble trait pour trait à une reprise : identifiant neuf,
        compteur à zéro, quelques minutes d'interruption. Les chaîner
        produirait une frise de plusieurs jours — illisible par construction,
        le ruban n'ayant que quelques centaines de pixels — et un compte de
        coupures qui alarmerait sur une routine.

        Le numéro de jour, lui, continue de dire où en est l'événement : c'est
        la pastille qui porte la durée longue, et elle la porte mieux qu'un
        ruban. */
  await changerJeu('marathon', 'Elden Ring');
  await wait(page, 900);
  await reprendre('marathon', 0);
  await wait(page, 900);
  const badgesMarathon = await survoler('marathon');
  const friseMarathon = await frise();
  await relacher('marathon');
  ok('un subathon qui redémarre n\'est pas une reprise : ni badge, ni compte',
     !badgesMarathon.some(b => b.classe.includes('--reprise'))
     && badgesMarathon.some(b => b.classe.includes('--subathon'))
     && (friseMarathon === null || friseMarathon.coupures === ''),
     JSON.stringify({ badges: badgesMarathon.map(b => b.texte),
                      coupures: friseMarathon && friseMarathon.coupures }));
  /* La frise d'avant portait DEUX catégories et six heures ; celle d'après
     n'en porte qu'une, celle du moment, et se compte en minutes. C'est bien un
     nouveau direct, pas la suite de l'ancien. */
  ok('…et sa frise repart avec lui, au lieu de s\'étendre sur des jours',
     friseMarathon === null
     || (friseMarathon.lignes.length === 1 && /^\d+m$/.test(friseMarathon.total)),
     JSON.stringify(friseMarathon));

  /* c) Le direct qui revient AVEC DE L'ÂGE. Identifiant neuf, coupure courte,
        mais un départ qui ne date pas d'aujourd'hui : il n'y a pas de compteur
        reparti de zéro, donc rien à corriger, donc rien à annoncer. C'est la
        garde qui borne le dégât — on ne marque jamais une reprise qu'on ne
        serait pas en train de réparer. */
  await reprendre('agee', 180);
  await wait(page, 900);
  const agee = await etat('agee');
  const badgesAgee = await survoler('agee');
  ok('un direct qui revient avec trois heures au compteur n\'est pas une reprise',
     agee !== null && agee.frais === false
     && !badgesAgee.some(b => b.classe.includes('--reprise')),
     JSON.stringify({ agee, badges: badgesAgee.map(b => b.texte) }));
  await relacher('agee');

  await page.close();
}
titre('96. Le mode d\'emploi — la première vue, et la seule qui n\'ait besoin de rien');
{
  /* ── CE QUE CE SCÉNARIO ATTRAPE, ET POURQUOI IL A FALLU L'ÉCRIRE ──────────
     Le panneau n'était jusqu'ici éprouvé que par le CONTRAT DE DONNÉES : le
     scénario 69 vérifie que la page rend bien les colonnes que panneau.js sait
     peindre, et la parité vérifie que chaque clé demandée existe dans les
     douze fiches. Ni l'un ni l'autre n'ouvre la page. Personne, donc, ne
     regardait ce que panneau.html affiche — et un mode d'emploi de treize
     chapitres est précisément le genre de chose qui peut se casser en silence :
     une clé oubliée rend une chaîne VIDE, un chapitre mal formé rend un bloc
     blanc, et rien n'écrit en console.

     On l'ouvre donc pour de vrai, en remplaçant `chrome.*` par un bouchon qui
     lit les VRAIES fiches de _locales. Le bouchon n'a aucun onglet à offrir,
     ce qui est le cas de figure exact que cette vue existe pour couvrir :
     quelqu'un qui vient d'installer l'extension et clique sur son icône. */
  const URL_PANNEAU = pathToFileURL(join(ICI, '..', 'panneau.html')).href;
  const fiche = (loc) => JSON.parse(
    readFileSync(join(ICI, '..', '_locales', loc, 'messages.json'), 'utf8'));

  const ouvrirPanneau = async (loc) => {
    const p = await browser.newPage({ viewport: { width: 760, height: 600 } });
    p.on('pageerror', (e) => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
    /* Le mouvement est refusé pour la durée du relevé de couleurs : l'arc-en-ciel
       du subathon traverse toutes les teintes, et comparer dix badges pendant
       qu'un onzième change rendrait le résultat dépendant de l'instant. La
       feuille honore `prefers-reduced-motion`, on s'en sert. */
    await p.emulateMedia({ reducedMotion: 'reduce' });
    await p.addInitScript((d) => {
      /* Le compteur d'appels est le vrai sujet de la deuxième assertion : il
         dit si cette vue a demandé quoi que ce soit au navigateur. */
      window.__queries = 0;
      const table = d.table;
      window.chrome = {
        /* LA SUBSTITUTION EST CELLE DE CHROME, et ce bouchon ne la faisait pas.
           `chrome.i18n.getMessage(cle, sub)` remplace « $1 » … « $9 » par les
           arguments ; le bouchon rendait le message brut. Le banc n'avait donc
           JAMAIS vu un message substitué — ni le renvoi de chapitre, ni le
           « $1 h » des réglages — et l'assertion du renvoi, écrite d'abord
           contre ce bouchon, lisait « (chapter $1) » sans rien dire de plus.
           Un bouchon plus simple que la chose qu'il remplace rend vertes des
           assertions que le produit ferait tomber. */
        i18n: { getMessage: (k, sub) => {
          const m = table[k] ? table[k].message : '';
          if (sub === undefined || sub === null) return m;
          const args = Array.isArray(sub) ? sub : [sub];
          return String(m).replace(/\$(\d)/g,
            (t, i) => (args[i - 1] === undefined ? t : String(args[i - 1])));
        },
                getUILanguage: () => d.loc.replace('_', '-') },
        tabs: { query: async () => { window.__queries++; return []; } },
        runtime: { sendMessage: async () => ({ ok: false, erreur: 'absent' }),
                   getManifest: () => ({ version: '0.0.0', action: {}, permissions: [] }) },
      };
    }, { table: fiche(loc), loc });
    await p.goto(URL_PANNEAU);
    await attendre(p, () => !document.getElementById('guide').hidden, 5000);
    return p;
  };

  const page = await ouvrirPanneau('en');
  const en = fiche('en');

  /* ── 1. C'EST LA PAGE D'ACCUEIL ──────────────────────────────────────────── */
  const accueil = await page.evaluate(() => ({
    titre: document.getElementById('vue-titre').textContent,
    visible: !document.getElementById('guide').hidden,
    courant: [...document.querySelectorAll('.rail-item')]
      .filter(b => b.getAttribute('aria-current') === 'true').map(b => b.dataset.id),
    premier: document.querySelector('.rail-item').dataset.id,
  }));
  ok('le panneau s\'ouvre sur le mode d\'emploi, et le rail le marque',
     accueil.visible && accueil.titre === en.navGuide.message
     && accueil.courant.length === 1 && accueil.courant[0] === 'guide'
     && accueil.premier === 'guide',
     JSON.stringify(accueil));

  /* ── 2. SANS RIEN DEMANDER À PERSONNE ─────────────────────────────────────
     L'assertion qui porte tout le reste : cette vue doit s'afficher sans
     onglet Twitch. Le compteur est posé sur `tabs.query`, qui est la PREMIÈRE
     chose que fait `demander` — avant même d'envoyer quoi que ce soit au
     service worker. Un court-circuit oublié se voit donc ici, et nulle part
     ailleurs : le panneau afficherait « ouvrez un onglet twitch.tv » en guise
     de bienvenue, ce qui est un message parfaitement fonctionnel. */
  const q = await page.evaluate(() => ({ n: window.__queries,
                                         message: !document.getElementById('message').hidden }));
  ok('…sans interroger le navigateur, et sans réclamer d\'onglet Twitch',
     q.n === 0 && q.message === false, JSON.stringify(q));

  /* ── 3. LES QUINZE CHAPITRES ─────────────────────────────────────────────── */
  const plan = await page.evaluate(() => {
    const chaps = [...document.querySelectorAll('#guide .guide-chapitre')];
    return {
      n: chaps.length,
      nums: chaps.map(c => c.querySelector('.guide-num').textContent),
      titres: chaps.map(c => c.querySelector('.guide-titre').textContent
                              .replace(/^\d+/, '').trim()),
      sansCorps: chaps.filter(c => !c.querySelector('.guide-p, .guide-liste li')).length,
      intro: (document.querySelector('#guide .guide-intro') || {}).textContent || '',
    };
  });
  ok('quinze chapitres, numérotés de 1 à 15, chacun avec un titre et du texte',
     plan.n === 15
     && plan.nums.join(',') === Array.from({ length: 15 }, (_, i) => i + 1).join(',')
     && plan.titres.every(t => t.length > 2)
     && plan.sansCorps === 0
     && plan.intro.length > 40,
     JSON.stringify({ n: plan.n, nums: plan.nums, sansCorps: plan.sansCorps }));

  /* ── 4. AUCUN LIBELLÉ MANQUANT ────────────────────────────────────────────
     `chrome.i18n.getMessage` d'une clé inconnue ne lève pas : elle rend la
     chaîne vide, et `T` rend alors le NOM DE LA CLÉ. Un libellé oublié
     s'affiche donc en clair — « guideAboTitre » au milieu du texte — sans
     erreur et sans console. On cherche les cent cinquante-cinq noms de clés
     dans ce qui est rendu : aucun n'a le droit d'y être. */
  const rendu = await page.evaluate(() => document.getElementById('guide').textContent);
  const fuites = Object.keys(en).filter(k => rendu.includes(k));
  ok('aucun nom de clé ne s\'affiche à la place de son libellé',
     fuites.length === 0, fuites.join(', '));

  /* ── 5. LES PUCES SONT DES PUCES ──────────────────────────────────────────
     Le corps d'un chapitre est un seul message à retours à la ligne : une
     ligne qui commence par « • » devient un élément de liste, les autres des
     paragraphes. Si cette grammaire cesse d'être appliquée, le texte s'affiche
     quand même — avec ses puces en caractères, dans des paragraphes. C'est le
     genre de régression qu'on ne voit pas en relisant le code. */
  const puces = await page.evaluate(() => ({
    items: document.querySelectorAll('#guide .guide-liste li').length,
    paraAvecPuce: [...document.querySelectorAll('#guide .guide-p')]
      .filter(p => p.textContent.trim().startsWith('•')).length,
    itemAvecPuce: [...document.querySelectorAll('#guide .guide-liste li')]
      .filter(li => li.textContent.trim().startsWith('•')).length,
    vides: [...document.querySelectorAll('#guide .guide-liste li, #guide .guide-p')]
      .filter(e => !e.textContent.trim()).length,
  }));
  /* LE PLANCHER EST BAS EXPRÈS. Ce qu'il attrape n'est pas « trop peu de
     puces » — leur nombre change à chaque relecture du guide, et une borne
     serrée se contenterait de casser le banc au premier paragraphe retiré.
     Ce qu'il attrape, c'est ZÉRO : le jour où la grammaire des corps cesse
     d'être appliquée, il n'y a plus une seule puce dans les quinze chapitres. */
  ok('les puces sont devenues des éléments de liste, marqueur retiré',
     puces.items >= 20 && puces.paraAvecPuce === 0 && puces.itemAvecPuce === 0
     && puces.vides === 0,
     JSON.stringify(puces));

  /* ── 5 bis. LE CHAPITRE DU PANNEAU DÉCRIT LE RAIL QUI EST À CÔTÉ ─────────
     TROUVÉ EN RELISANT LE GUIDE, PAS EN LISANT LE CODE : le chapitre annonce
     « cinq groupes, à gauche » et les énumère — et il en donnait deux dans un
     ordre que le rail n'a jamais eu. Personne ne l'aurait vu en relisant la
     traduction : il faut avoir les deux sous les yeux.

     LA PROSE SE LIE DONC AU PRODUIT. Les intitulés de groupe du rail sont lus
     dans leur ordre d'affichage, et on exige qu'ils apparaissent dans CET
     ordre dans le chapitre. Déplacer une section sans toucher au texte fait
     tomber cette ligne, et c'est exactement ce qu'on veut : une liste qui ne
     correspond plus à ce qu'on a sous les yeux vaut moins que pas de liste. */
  const railEtTexte = await page.evaluate(() => {
    const groupes = [...document.querySelectorAll('#rail .rail-groupe')]
      .map((h) => h.textContent.trim()).filter(Boolean);
    /* LE CHAPITRE SE DÉSIGNE PAR SON CONTENU, pas par son rang : il est le
       seul à nommer les CINQ intitulés. Le numéroter ici obligerait à revenir
       dans ce fichier au prochain remaniement de l'ordre des chapitres, ce
       qui est exactement la dette que ce scénario existe pour éviter. */
    const chap = [...document.querySelectorAll('#guide .guide-chapitre')]
      .find((c) => groupes.length && groupes.every((g) => c.textContent.includes(g)));
    return { groupes, texte: chap ? chap.textContent : '' };
  });
  const places = railEtTexte.groupes.map((g) => railEtTexte.texte.indexOf(g));
  ok('le chapitre du panneau nomme les cinq groupes du rail, et dans l\'ordre du rail',
     railEtTexte.groupes.length === 5 && places.every((i) => i >= 0)
     && places.every((v, i) => i === 0 || v > places[i - 1]),
     JSON.stringify({ groupes: railEtTexte.groupes, places }));

  /* ── 5 ter. LE RENVOI D'UN CHAPITRE À L'AUTRE DÉSIGNE LE BON ────────────
     MÊME ESPÈCE DE DÉFAUT QUE CI-DESSUS, ET TROUVÉ DE LA MÊME FAÇON : le
     chapitre des co-streams renvoie aux tris par son NUMÉRO. Le numéro était
     recopié dans les douze fiches, et le remaniement de l'ordre l'a laissé
     pointer deux chapitres trop haut — dans les douze langues à la fois.

     UNE TRADUCTION JUSTE PEUT PORTER UN RENVOI FAUX : c'est ce qui rend ce
     défaut invisible à la relecture. On lit donc le numéro tel qu'il est
     RENDU, et on va voir ce qu'il y a à ce rang. */
  const renvois = await page.evaluate(() => {
    const chaps = [...document.querySelectorAll('#guide .guide-chapitre')];
    const titres = chaps.map((c) => c.querySelector('.guide-titre').textContent
                                     .replace(/^\d+/, '').trim());
    const vus = [];
    chaps.forEach((c, i) => {
      const corps = [...c.querySelectorAll('.guide-p, .guide-liste li')]
        .map((e) => e.textContent).join(' ');
      for (const m of corps.matchAll(/[(（][^)）]*?(\d+)[^)）]*?[)）]/g))
        vus.push({ depuis: i + 1, vers: Number(m[1]), texte: m[0] });
    });
    return { n: chaps.length, titres, vus };
  });
  /* IL Y EN A AU MOINS UN : sans cette moitié, l'assertion serait verte le
     jour où le renvoi disparaîtrait par accident. */
  const horsBornes = renvois.vus.filter((r) => !(r.vers >= 1 && r.vers <= renvois.n));
  const versSoi = renvois.vus.filter((r) => r.vers === r.depuis);
  ok('chaque renvoi du mode d\'emploi désigne un chapitre qui existe, et pas lui-même',
     renvois.vus.length >= 1 && horsBornes.length === 0 && versSoi.length === 0,
     JSON.stringify(renvois.vus));
  /* ET IL DÉSIGNE LE BON. Le renvoi des co-streams vise les tris : on vérifie
     que le chapitre pointé est bien celui qui parle de trier, par son titre
     tel que la langue de la vue le rend. */
  const tri = await page.evaluate(() => {
    const t = [...document.querySelectorAll('#guide .guide-chapitre .guide-titre')]
      .map((h) => h.textContent.replace(/^\d+/, '').trim());
    return t.findIndex((x) => /sort|filter/i.test(x)) + 1;
  });
  ok('…et le renvoi des co-streams tombe sur le chapitre des tris',
     tri >= 1 && renvois.vus.some((r) => r.vers === tri),
     JSON.stringify({ triEstAuRang: tri, renvois: renvois.vus }));

  /* ── 6. LA PALETTE DES BADGES ─────────────────────────────────────────────
     Douze badges, ONZE modificateurs, DIX couleurs, et les deux exceptions
     sont le sujet de l'assertion.
     Chaque type de badge a sa teinte, choisie par un calcul qui cherche le
     créneau libre le plus large — les recopier ici sans les distinguer
     donnerait une maquette monochrome qui n'explique plus rien. Mais
     « reprise » n'a jamais eu de couleur à lui : c'est la même espèce de
     nouvelle que le basculement, et il porte sa classe. Cette parenté doit
     survivre à la recopie, sinon la maquette contredirait le produit. */
  /* ── LE RELEVÉ FIGE CE QU'IL MESURE, IL NE COMPTE PLUS SUR LE PRODUIT ───
     Cette vue est ouverte sous « mouvement réduit », et jusqu'ici c'était la
     feuille qui arrêtait l'arc-en-ciel, ce qui rendait les dix teintes
     comparables. Depuis la 4.9 le produit le RALENTIT au lieu de l'arrêter —
     un utilisateur a eu raison de le demander — et le relevé redeviendrait
     dépendant de l'instant. Un banc qui s'appuie sur un comportement du
     produit pour tenir sa mesure change de sujet dès que ce comportement
     change ; il doit maîtriser son décor lui-même. */
  await page.evaluate(() => {
    for (const a of document.getAnimations()) a.pause();
  });
  const teintes = await page.evaluate(() => {
    const out = {};
    for (const b of document.querySelectorAll('#guide .d-badge')) {
      const mod = [...b.classList].find(c => c.startsWith('d-badge--'));
      if (mod && !(mod in out)) out[mod] = getComputedStyle(b).color;
    }
    /* La couleur d'un badge SANS modificateur, mesurée et non recopiée : c'est
       la valeur que prend un badge dont la règle n'a pas pris — classe mal
       orthographiée, règle perdue dans une réécriture. Compter les teintes
       distinctes ne le verrait pas (une teinte fausse reste une teinte), et
       c'est pourtant le seul défaut de palette qui arrive vraiment. */
    const temoin = document.createElement('span');
    temoin.className = 'd-badge';
    document.querySelector('#guide .d-badges').appendChild(temoin);
    out.__nu = getComputedStyle(temoin).color;
    temoin.remove();
    return out;
  });
  /* ON RELANCE CE QU'ON A FIGÉ. Le chapitre suivant mesure justement que
     l'arc-en-ciel COURT : laisser les animations en pause ferait échouer une
     assertion qui n'a rien à voir avec celle-ci — le genre d'effet de bord
     qu'un décor mal rendu produit deux scénarios plus loin. */
  await page.evaluate(() => { for (const a of document.getAnimations()) a.play(); });
  const nu = teintes.__nu;
  delete teintes.__nu;
  const mods = Object.keys(teintes);
  const distinctes = new Set(Object.values(teintes));
  ok('onze modificateurs, dix couleurs, aucune par défaut — et « reprise » porte celle du basculement',
     mods.length === 11 && distinctes.size === 10
     && teintes['d-badge--reprise'] === teintes['d-badge--switch']
     && !Object.values(teintes).includes(nu),
     JSON.stringify({ mods: mods.length, distinctes: distinctes.size, nu, teintes }));
  /* ── LE DOUZIÈME BADGE EST CELUI QUI N'A PAS DE COULEUR ──────────────────
     Le mode d'emploi n'en montrait que dix, et un utilisateur a demandé « tous
     les badges possibles ». Il en manquait deux : l'ancien abonné — même or,
     désaturé — et le NEUTRE, celui qui reprend telle quelle une mention
     ajoutée par Twitch. Le neutre se définit par l'ABSENCE de modificateur ;
     lui en donner un le trahirait, et c'est pourquoi il faut l'asserter
     autrement : il doit porter exactement la couleur par défaut, celle-là même
     qu'aucun des onze autres n'a le droit d'avoir. */
  const neutre = await page.evaluate(() => {
    const b = [...document.querySelectorAll('#guide .d-badge')]
      .find(x => ![...x.classList].some(c => c.startsWith('d-badge--')));
    return b ? { texte: (b.textContent || '').trim(), couleur: getComputedStyle(b).color }
             : null;
  });
  ok('…et le douzième, le badge neutre, porte la couleur par défaut et aucun modificateur',
     !!neutre && neutre.couleur === nu && neutre.texte.length > 0,
     JSON.stringify({ neutre, nu }));
  /* L'ANCIEN ABONNÉ PARTAGE LA TEINTE DE L'ABONNÉ SANS LA COPIER : c'est la
     seule paire de la palette qui se ressemble volontairement, et le dire ici
     empêche qu'une réécriture les confonde tout à fait — ou les sépare. */
  ok('…et « ancien abonné » est un or plus pâle que celui de l\'abonné, non le même',
     teintes['d-badge--exsub'] !== teintes['d-badge--sub']
     && !!teintes['d-badge--exsub'],
     JSON.stringify({ sub: teintes['d-badge--sub'], exsub: teintes['d-badge--exsub'] }));

  /* ── LA MAQUETTE MONTRE CE QUE LE PRODUIT FAIT, Y COMPRIS ICI ───────────
     DEUX TOURS POUR CETTE ASSERTION, ET LA MÊME LEÇON À CHAQUE FOIS. Au
     premier, la feuille du panneau s'annonçait exhaustive — « * { animation:
     none !important } » — alors que le sélecteur universel désigne des
     ÉLÉMENTS : ::before et ::after n'en sont pas, et la barre violette de
     cette maquette continuait de battre sous les yeux de qui demande
     l'immobilité. Au second, la feuille gardait DEUX exceptions annoncées
     « à l'identique de content.js » — un battement calme, un arc-en-ciel
     ralenti — qui ne l'étaient plus, le bloc du produit ayant été retiré.

     LE PANNEAU N'A DONC PLUS DE BLOC NON PLUS, et ce n'est pas seulement pour
     s'aligner : une maquette dont le seul métier est de montrer ce que le
     produit fait ne peut pas garder un régime que le produit a perdu. On
     mesure l'INVARIANCE, comme sur le produit — les deux relevés doivent être
     rigoureusement le même. */
  const barreSous = async (mouvement) => {
    await page.emulateMedia({ reducedMotion: mouvement });
    await wait(page, 200);
    return page.evaluate(async () => {
      const e = document.querySelector('#guide .d-carte--frais');
      if (!e) return null;
      const st = getComputedStyle(e, '::before');
      /* L'amplitude se balaie sur un cycle : lue d'un coup, elle ne dirait que
         la phase où on est tombé, et les deux relevés ne sont jamais en
         phase. */
      const ech = [];
      const duree = parseFloat(st.animationDuration) * 1000 || 1400;
      const fin = performance.now() + duree * 1.1;
      while (performance.now() < fin) {
        const c = getComputedStyle(e, '::before');
        ech.push(parseFloat(c.width) * (new DOMMatrixReadOnly(c.transform).a || 1));
        await new Promise(requestAnimationFrame);
      }
      return { anim: st.animationName, duree: st.animationDuration,
               lMin: +Math.min(...ech).toFixed(2), lMax: +Math.max(...ech).toFixed(2) };
    });
  };
  const barreCalme = await barreSous('reduce');
  const barreVive = await barreSous('no-preference');
  ok('mouvement réduit : la barre de la maquette bat exactement comme sans ce réglage',
     !!barreCalme && !!barreVive
     && barreCalme.anim === barreVive.anim && barreCalme.duree === barreVive.duree
     && Math.abs((barreCalme.lMax - barreCalme.lMin)
                 - (barreVive.lMax - barreVive.lMin)) < 0.15,
     JSON.stringify({ calme: barreCalme, vive: barreVive }));
  /* ET C'EST UN VRAI BATTEMENT DES DEUX CÔTÉS : l'égalité seule serait vraie
     aussi si la maquette était figée en haut comme en bas. */
  ok('…et c\'est bien un battement, celui de la maquette du stream frais',
     barreCalme.anim === 'd-respire'
     && barreCalme.lMax - barreCalme.lMin >= 2,
     JSON.stringify(barreCalme));
  await page.emulateMedia({ reducedMotion: 'reduce' });

  /* ── 7. L'ARC-EN-CIEL COURT VRAIMENT ──────────────────────────────────────
     Le badge de subathon est le seul qui n'ait pas de couleur : il les
     traverse toutes. Au repos — mouvement refusé — il vaut le cyan qu'on vient
     de compter ; mouvement autorisé, il doit CHANGER. Sans cette assertion, une
     animation supprimée laisserait un badge cyan parfaitement plausible. */
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  const teinteSub = () => page.evaluate(() =>
    getComputedStyle(document.querySelector('#guide .d-badge--subathon')).color);
  const t1 = await teinteSub();
  await wait(page, 400);
  const t2 = await teinteSub();
  ok('…et le badge de subathon les traverse toutes, en mouvement',
     t1 !== t2, `${t1} → ${t2}`);
  await page.emulateMedia({ reducedMotion: 'reduce' });

  /* ── 8. LES MAQUETTES NE SE LISENT PAS À VOIX HAUTE ───────────────────────
     Même règle que la frise et la grille du rythme : la forme pour l'œil, le
     texte pour l'information. Une maquette lue par une synthèse vocale ne
     donnerait qu'une bouillie de pseudos inventés et de durées, et le chapitre
     dit déjà tout en toutes lettres. */
  const muettes = await page.evaluate(() => {
    const cadres = [...document.querySelectorAll('#guide .d-cadre')];
    return { n: cadres.length,
             nues: cadres.filter(c => c.getAttribute('aria-hidden') !== 'true').length,
             texteDedans: cadres.some(c => c.querySelector('.guide-p, .guide-liste')) };
  });
  ok('les maquettes sont masquées à la synthèse vocale, et ne portent aucun texte du guide',
     muettes.n >= 8 && muettes.nues === 0 && muettes.texteDedans === false,
     JSON.stringify(muettes));

  /* ── 9. ÇA DÉFILE DEDANS, PAS DEHORS ──────────────────────────────────────
     Une popup de barre d'outils ne défile pas : elle est bornée par le
     navigateur, et ce qui dépasse est simplement coupé — sans barre, sans
     erreur, sans rien. Un guide de trois mille pixels de haut dans un conteneur
     qui ne défile pas, ce sont douze chapitres sur treize invisibles. */
  const defile = await page.evaluate(() => {
    const g = document.getElementById('guide');
    return { haut: g.scrollHeight, visible: g.clientHeight,
             page: document.documentElement.scrollHeight,
             largeurPage: document.documentElement.scrollWidth,
             largeurGuide: [g.scrollWidth, g.clientWidth] };
  });
  ok('le guide défile pour son compte, et rien ne déborde en largeur',
     defile.haut > defile.visible * 3 && defile.page <= 600
     && defile.largeurPage <= 760 && defile.largeurGuide[0] <= defile.largeurGuide[1] + 1,
     JSON.stringify(defile));

  /* ── 10. IL SE RANGE, ET IL REVIENT ───────────────────────────────────────
     Le guide est posé dans la même vue que les tableaux. S'il ne se range pas
     en partant, il resterait affiché SOUS la section suivante — et comme
     celle-ci échoue faute d'onglet, on aurait un message d'erreur posé sur un
     mode d'emploi. */
  await page.click('.rail-item[data-id="scores"]');
  await attendre(page, () => document.getElementById('guide').hidden, 5000);
  const parti = await page.evaluate(() => ({
    guide: document.getElementById('guide').hidden,
    message: !document.getElementById('message').hidden,
    queries: window.__queries,
  }));
  await page.click('.rail-item[data-id="guide"]');
  await attendre(page, () => !document.getElementById('guide').hidden, 5000);
  const revenu = await page.evaluate(() => ({
    guide: !document.getElementById('guide').hidden,
    chapitres: document.querySelectorAll('#guide .guide-chapitre').length,
    message: !document.getElementById('message').hidden,
  }));
  ok('une autre section le range et demande la page ; y revenir le repose intact',
     parti.guide === true && parti.message === true && parti.queries > 0
     && revenu.guide === true && revenu.chapitres === 15 && revenu.message === false,
     JSON.stringify({ parti, revenu }));
  await page.close();

  /* ── 11. LES DOUZE FICHES, ET PAS SEULEMENT L'ANGLAISE ────────────────────
     La parité garantit que les douze fiches portent les mêmes clés, non
     vides ; elle ne peut pas dire si le RENDU tient dans une autre langue. Le
     japonais est le cas le plus éloigné de l'anglais qu'on ait : pas d'espaces
     entre les mots, des chiffres à chasse pleine, et des puces écrites de la
     même main que le reste. S'il passe, la grammaire du corps ne dépend pas de
     la langue. */
  const pageJa = await ouvrirPanneau('ja');
  const ja = fiche('ja');
  const rendJa = await pageJa.evaluate(() => {
    const g = document.getElementById('guide');
    return { titre: document.getElementById('vue-titre').textContent,
             chapitres: g.querySelectorAll('.guide-chapitre').length,
             items: g.querySelectorAll('.guide-liste li').length,
             puces: [...g.querySelectorAll('.guide-p, .guide-liste li')]
               .filter(e => e.textContent.trim().startsWith('•')).length,
             texte: g.textContent,
             largeur: document.documentElement.scrollWidth };
  });
  ok('le mode d\'emploi se rend aussi en japonais, sans clé nue ni débordement',
     rendJa.titre === ja.navGuide.message && rendJa.chapitres === 15
     && rendJa.items >= 20 && rendJa.puces === 0 && rendJa.largeur <= 760
     && !Object.keys(ja).some(k => rendJa.texte.includes(k)),
     JSON.stringify({ titre: rendJa.titre, chapitres: rendJa.chapitres,
                      items: rendJa.items, puces: rendJa.puces, largeur: rendJa.largeur }));
  await pageJa.close();
}

titre('97. Le passé d\'avant la coupure, et le basculement qu\'on n\'a pas vu passer');
{
  /* ── DEUX CHOSES QUE LE VOD SAIT ET QUE NOUS IGNORONS ─────────────────────
     Ce scénario éprouve une correction et un ajout, qui ont la même racine :
     l'enregistrement en sait plus que nous, et on s'interdisait de le lire.

     LA CORRECTION. La 3.99 refusait toute demande de chapitres dès qu'une
     coupure était connue, au motif que Twitch ouvre un enregistrement par
     session. La prémisse était fausse, et ce dépôt portait déjà la preuve du
     contraire : `segmentsDuVod` traite nommément « un enregistrement qui
     commence AVANT le stream courant : c'est le cas d'une reconnexion, où le
     VOD continue pendant que createdAt repart », et un rapport d'utilisateur
     l'avait mesuré à trente-neuf minutes. Le passé d'avant la coupure est donc
     enregistré — il suffisait de dater la demande sur l'ORIGINE du direct et
     non sur le départ du tronçon.

     L'AJOUT. Le badge « Vient de passer sur … » naissait d'une observation :
     deux relevés, même identifiant, deux catégories. Il manquait donc
     exactement là où il sert — on ouvre Twitch, on survole, la frise dit
     « 7m · en cours » et rien ne le signale. Les chapitres du VOD datent ce
     basculement à la seconde ; le badge peut s'en déduire. */
  const page = await freshTwitch();
  const M = 60_000;
  const ORIGINE = Date.now() - 240 * M;             // direct commencé il y a 4 h

  await page.evaluate((o) => {
    const iso = new Date(o).toISOString();
    window.__fx = {
      // Le direct qui va se couper : quatre heures, trois catégories, et la
      // dernière prise à l'instant (l'instant exact est posé plus bas).
      coupe: { id: 'c1', sid: 's-coupe-1', createdAt: iso, viewers: 900,
               game: 'Valorant', tags: [] },
      // « neuf » n'entre en direct qu'au moment de son épreuve : il faut que
      // son unique catégorie soit prise À L'INSTANT, sinon le refus qu'on
      // éprouve serait acquis par l'âge et non par la règle (cf. plus bas).
      // Une chaîne qui n'archive pas : son passé ne tient qu'aux clips, dont
      // les bornes sont des minorants.
      clipe: { id: 'c3', sid: 's-clipe-1', createdAt: iso, viewers: 200,
               game: 'Hades II', tags: [] },
      // Un basculement qui date d'une heure : la frise le porte, le badge non.
      vieux: { id: 'c4', sid: 's-vieux-1', createdAt: iso, viewers: 400,
               game: 'Overwatch', tags: [] },
      // Une chaîne dont l'enregistrement commence APRÈS notre arrivée — celle
      // qui a activé l'archivage en cours de route. Son VOD est posé plus bas,
      // une fois qu'on l'a déjà observée un moment.
      tardif: { id: 'c5', sid: 's-tardif-1', createdAt: iso, viewers: 500,
                game: 'Minecraft', tags: [] },
    };
    window.__vod = {
      coupe: { createdAt: iso, chapitres: [
        { pos: 0,          jeu: 'Just Chatting' },
        { pos: 180 * 60_000, jeu: 'Elden Ring' },
        { pos: 233 * 60_000, jeu: 'Valorant' }] },
      clipe: 'sansvod',
      vieux: { createdAt: iso, chapitres: [
        { pos: 0,           jeu: 'Just Chatting' },
        { pos: 180 * 60_000, jeu: 'Overwatch' }] },
    };
    window.__vodRecent = {};
    /* Le dernier clip date de MAINTENANT — le stub les horodate à la requête,
       donc il l'est encore au survol. Sans cela, le refus des frises de clips
       serait acquis par l'âge du segment et non par sa nature, et la règle
       qu'on croit éprouver ne le serait pas. */
    window.__clips = { clipe: [
      { jeu: 'Just Chatting', ilYaMin: 200 },
      { jeu: 'Just Chatting', ilYaMin: 160 },
      { jeu: 'Hades II',      ilYaMin: 0.01 }] };
    for (const l of ['coupe', 'neuf', 'clipe', 'vieux', 'tardif']) {
      window.__addCard(l, l, '900');
    }
  }, ORIGINE);
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 4);

  const survoler = async (login) => {
    await page.evaluate(() => {
      for (const c of document.querySelectorAll('.side-nav-card')) {
        c.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
      }
    });
    await attendre(page,
      () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);
    await hoverLogin(page, login);
    await attendre(page,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
  };
  const vue = () => page.evaluate(() => {
    const f = document.querySelector('.tse-preview__frise');
    return {
      lignes: f ? [...f.querySelectorAll('.tse-preview__frise-nom')].map(n => n.textContent) : null,
      total: f ? f.querySelector('.tse-preview__frise-total').textContent : null,
      coupures: f ? (f.querySelector('.tse-preview__frise-coupures')?.textContent || '') : null,
      badges: [...document.querySelectorAll('.tse-preview__badge')]
        .map(b => ({ classe: b.className, texte: b.textContent.trim(),
                     frise: b.dataset.tseBasculeFrise === 'true' })),
    };
  });

  /* ── 1. LE PASSÉ, AVANT MÊME LA COUPURE ──────────────────────────────────
     Rien n'a été observé : l'onglet vient de s'ouvrir. Les trois catégories
     ne peuvent venir que des chapitres.

     LE DERNIER CHAPITRE EST DATÉ JUSTE AVANT LE SURVOL, et ce n'est pas du
     confort de décor. CATEGORY_SWITCH_TTL vaut dix minutes en production et
     deux secondes et demie dans ce banc : un chapitre « vieux de sept minutes »
     y serait périmé, et l'assertion sur le badge passerait ou tomberait pour
     une raison qui n'a rien à voir avec ce qu'elle prétend éprouver. On pose
     donc l'instant du basculement à la seconde où l'on va survoler. */
  await page.evaluate((o) => {
    const ch = window.__vod.coupe.chapitres;
    ch[ch.length - 1].pos = Date.now() - o - 200;
  }, ORIGINE);
  await survoler('coupe');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 9000);
  await attendre(page, () => document.querySelectorAll('.tse-preview__frise-nom').length >= 3, 9000);
  const avant = await vue();
  ok('les chapitres du VOD rendent les trois catégories du direct',
     avant.lignes !== null && avant.lignes.length === 3
     && /Just Chatting|Discussions/.test(avant.lignes[0])
     && /Elden Ring/.test(avant.lignes[1]) && /Valorant/.test(avant.lignes[2]),
     JSON.stringify(avant.lignes));

  /* L'AJOUT, ET SA RAISON D'ÊTRE : aucun basculement n'a été OBSERVÉ ici —
     l'extension vient d'arriver. Le badge ne peut donc venir que de la frise,
     et sa marque le dit. */
  const badgeAvant = avant.badges.find(b => b.classe.includes('--switch'));
  ok('…et le dernier, tout frais, met le badge « vient de passer sur »',
     !!badgeAvant && badgeAvant.frise === true && /Valorant/.test(badgeAvant.texte),
     JSON.stringify(avant.badges));

  /* ── 2. LA COUPURE, ET CE QU'ELLE NE DOIT PAS EMPORTER ───────────────────
     Nouvel identifiant, compteur à zéro, et le VOD qui continue : c'est ce que
     Twitch sert après une reconnexion. La frise doit garder ses quatre heures. */
  await page.evaluate(() => {
    document.querySelectorAll('.side-nav-card').forEach(c =>
      c.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false })));
    window.__fx.coupe.sid = 's-coupe-2';
    window.__fx.coupe.createdAt = new Date().toISOString();
    window.tse.rescan();
  });
  await wait(page, 900);
  await survoler('coupe');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 9000);
  await attendre(page, () => document.querySelectorAll('.tse-preview__frise-nom').length >= 3, 9000);
  const apres = await vue();
  ok('après la coupure, les chapitres d\'AVANT sont toujours là',
     apres.lignes !== null && apres.lignes.length === 3
     && /Elden Ring/.test(apres.lignes[1]) && /Valorant/.test(apres.lignes[2]),
     JSON.stringify(apres.lignes));
  /* SANS LA CORRECTION, la demande partait sur le départ du TRONÇON : les
     trois chapitres, tous antérieurs, se repliaient sur cet instant et la
     frise ne montrait plus que quelques minutes. Le total est donc l'assertion
     qui tient la correction. */
  ok('…et le total couvre les quatre heures, pas les deux minutes du tronçon',
     apres.total !== null && /^(\d+)h\d\d$/.test(apres.total)
     && Number(/^(\d+)h/.exec(apres.total)[1]) >= 3,
     JSON.stringify({ total: apres.total, coupures: apres.coupures }));

  /* ── 3. CE QUI NE MÉRITE PAS LE BADGE ────────────────────────────────────
     Deux refus, et chacun éviterait une affirmation fausse. */

  /* a) UN DÉBUT N'EST PAS UN BASCULEMENT. Une seule catégorie, prise à
        l'instant parce que le direct commence à l'instant : dire « vient de
        passer sur Minecraft » ferait croire qu'il a changé quand il a
        commencé. Le direct naît ici même, pour que son unique segment tombe
        DANS la fenêtre du badge — sans quoi le refus serait acquis par l'âge. */
  await page.evaluate(() => {
    window.__fx.neuf = { id: 'c2', sid: 's-neuf-1',
                         createdAt: new Date().toISOString(),
                         viewers: 300, game: 'Minecraft', tags: [] };
    window.tse.rescan();
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 3, 6000);
  await survoler('neuf');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 6000);
  const neuf = await vue();
  ok('un direct qui vient de commencer n\'a pas « vient de passer sur »',
     !neuf.badges.some(b => b.classe.includes('--switch')),
     JSON.stringify({ lignes: neuf.lignes, badges: neuf.badges.map(b => b.texte) }));

  /* b) UNE FRISE DE CLIPS NE BORNE PAS, ELLE MINORE. Le dernier clip a trois
        minutes, mais la catégorie avait commencé avant — de combien, rien ne
        le dit. Déduire « vient de passer » d'un minorant, c'est affirmer une
        heure qu'on n'a pas. */
  await survoler('clipe');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 9000);
  await wait(page, 600);
  const clipe = await vue();
  ok('une frise de CLIPS ne met pas le badge : ses bornes sont des minorants',
     clipe.lignes !== null && clipe.lignes.length >= 2
     && !clipe.badges.some(b => b.classe.includes('--switch')),
     JSON.stringify({ lignes: clipe.lignes, badges: clipe.badges.map(b => b.texte) }));

  /* c) UN BASCULEMENT D'IL Y A UNE HEURE N'EST PAS UNE NOUVELLE. La frise le
        porte — c'est son métier — mais le badge annonce ce qui VIENT de se
        passer, et il a la même péremption que celui qu'on observe. */
  await survoler('vieux');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 9000);
  await attendre(page, () => document.querySelectorAll('.tse-preview__frise-nom').length >= 2, 9000);
  const vieux = await vue();
  ok('un basculement ancien reste dans la frise, sans badge',
     vieux.lignes !== null && vieux.lignes.length === 2
     && !vieux.badges.some(b => b.classe.includes('--switch')),
     JSON.stringify({ lignes: vieux.lignes, badges: vieux.badges.map(b => b.texte) }));

  /* ── 4. LE VOD EN RETARD SUR NOUS ────────────────────────────────────────
     Une chaîne qui active l'archivage en cours de diffusion : son
     enregistrement commence APRÈS notre première observation. Le raccord pose
     les chapitres d'abord puis n'ajoute nos segments que s'ils sont
     postérieurs — les nôtres, plus anciens, tombaient donc dans le vide. Ce
     que nous avons vu de nos yeux doit rester devant ce que le VOD raconte. */
  await page.evaluate(() => {
    window.__vod.tardif = { createdAt: new Date().toISOString(),
                            chapitres: [{ pos: 0, jeu: 'Overwatch' }] };
    window.__fx.tardif.game = 'Overwatch';
    window.tse.rescan();
  });
  await wait(page, 900);
  await survoler('tardif');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 9000);
  await attendre(page, () => document.querySelectorAll('.tse-preview__frise-nom').length >= 2, 9000);
  const tardif = await vue();
  /* La part non observée ouvre la liste — le live a quatre heures et nous
     n'en avons vu que la fin. Ce qui compte ici est l'ORDRE des deux
     catégories, et surtout la présence de la nôtre. */
  const ordre = (tardif.lignes || []).filter(n => /Minecraft|Overwatch/.test(n));
  ok('un VOD commencé après nous ne fait pas disparaître ce qu\'on a observé',
     ordre.length === 2 && /Minecraft/.test(ordre[0]) && /Overwatch/.test(ordre[1]),
     JSON.stringify(tardif.lignes));

  await page.close();
}

titre('98. Les tags de langue empilés — dix langues n\'en font parler aucune');
{
  /* ── LE SIGNALEMENT, ET CE QU'IL DÉCRIT ──────────────────────────────────
     Les tags de langue sont libres : rien n'empêche un streamer d'en poser
     dix pour figurer dans dix classements. Une chaîne ne diffuse pas en dix
     langues à la fois — le tag ne dit alors plus ce qu'on parle, il dit qu'on
     veut être trouvé partout.

     DEUX, PARCE QUE DEUX EXISTE. Un stream bilingue est courant : un
     francophone qui fait sa soirée en anglais, un événement doublé. L'écarter
     serait punir un usage réel. Trois ne l'est plus.

     CE QUE CE SCÉNARIO TIENT VRAIMENT. Trois choses se cassent séparément :
     la borne elle-même, le fait qu'on compte les tags de LANGUE et non tous
     les tags, et le fait que la règle s'applique aux DEUX voies d'entrée du
     classement — la descente par catégories et la voie du tag. La dernière
     est la plus facile à perdre : deux chemins, un seul filtre. */
  const LANGUES_EMPILEES = ['Français', 'English', 'Deutsch', 'Español',
                            'Italiano', 'Polski', 'Русский', '日本語'];

  const monter = (page) => page.evaluate((huit) => {
    const h = new Date(Date.now() - 30 * 60_000).toISOString();
    window.__fx = { suivi1: { id: 'id-suivi1', createdAt: h, viewers: 400,
                              game: 'Just Chatting', tags: [] } };
    window.__addCard('suivi1', 'Just Chatting', '400');
    const cats = [];
    // Du remplissage, pour que la descente ait un pool crédible à parcourir.
    for (let i = 0; i < 3; i++) {
      const streams = [];
      for (let k = 0; k < 30; k++) {
        streams.push({ login: `en${i}_${k}`, viewers: 500 - k, tags: ['English'] });
      }
      cats.push({ name: 'c' + i, viewers: 400_000 - i, streams });
    }
    /* Les cinq cas, tous assez gros pour être en tête du classement : s'ils
       n'y sont pas, c'est la règle qui les a écartés et rien d'autre. */
    cats.push({ name: 'vitrine', viewers: 399_000, streams: [
      { login: 'mono',  viewers: 9000, tags: ['Français'] },
      { login: 'bi',    viewers: 8000, tags: ['Français', 'English'] },
      // DEUX langues, et deux tags qui n'en sont pas : elle passe. C'est la
      // différence entre « compter les tags » et « compter les langues ».
      { login: 'mixte', viewers: 7000,
        tags: ['Français', 'Speedrun', 'English', 'LGBTQIAPlus'] },
      { login: 'tri',   viewers: 6000, tags: ['Français', 'English', 'Deutsch'] },
      { login: 'spam',  viewers: 5000, tags: huit },
    ] });
    window.__cats = cats;
  }, LANGUES_EMPILEES);

  const page = await fresh();
  await monter(page);
  await wait(page, 1500);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await attendre(page, () => window.tse.global.top(30).length > 0, 9000);
  await wait(page, 1500);

  const top = await page.evaluate(() => window.tse.global.top(30).map(r => r.login));
  ok('une chaîne qui déclare une ou deux langues reste au classement',
     top.includes('mono') && top.includes('bi'), JSON.stringify(top.slice(0, 8)));
  ok('…celle qui en déclare trois ou huit en sort',
     !top.includes('tri') && !top.includes('spam'), JSON.stringify(top.slice(0, 8)));
  /* LA RÈGLE COMPTE LES LANGUES, PAS LES TAGS. « mixte » en porte quatre, dont
     deux seulement sont des langues : un filtre qui compterait les tags
     l'écarterait, et écarterait avec elle toute chaîne un peu renseignée. */
  ok('…et quatre tags dont deux langues, c\'est deux langues',
     top.includes('mixte'), JSON.stringify(top.slice(0, 8)));

  /* L'EXCLUSION SE COMPTE. Une exclusion silencieuse est une exclusion dont on
     ne saura jamais si elle mord trop : le rapport porte le nombre. */
  const bilan = await page.evaluate(() => window.tse.global.report().tagsEmpiles);
  ok('le rapport dit combien de CHAÎNES distinctes ont été écartées pour cela',
     Number.isFinite(bilan) && bilan >= 2, String(bilan));

  /* ── LA SECONDE VOIE D'ENTRÉE ────────────────────────────────────────────
     Le classement par TAG de langue ne passe pas par la descente : c'est une
     requête à part, dont les réponses entrent par la même lecture. Si le
     filtre avait été posé dans la descente plutôt que dans cette lecture, la
     voie du tag laisserait passer tout ce que l'autre écarte — et c'est
     précisément la voie qu'un empileur de tags cherche à atteindre. */
  await page.evaluate((huit) => {
    window.__tagTop = { 'Français': [
      { login: 'tagPropre', viewers: 5000, game: 'Just Chatting', tags: ['Français'] },
      { login: 'tagSpam',   viewers: 4000, game: 'Just Chatting', tags: huit },
    ] };
  }, LANGUES_EMPILEES);
  await page.evaluate(() => {
    const opt = [...document.querySelectorAll('#tse-lang-dd .tse-dd-opt')]
      .find(o => (o.dataset.value || '') === 'Français');
    if (!opt) throw new Error('langue absente du menu');
    opt.click();
  });
  await attendre(page,
    () => window.tse.global.top(30).some(r => r.login === 'tagPropre'), 9000);
  await wait(page, 400);
  const parTag = await page.evaluate(() => window.tse.global.top(30).map(r => r.login));
  ok('la voie du tag applique la même règle : l\'empileur n\'y entre pas non plus',
     parTag.includes('tagPropre') && !parTag.includes('tagSpam'),
     JSON.stringify(parTag.slice(0, 8)));

  await page.close();
}

titre('99. Le co-streamer sans catégorie — centrer une boîte qui n\'est pas vide');
{
  /* ── LE SIGNALEMENT ───────────────────────────────────────────────────────
     « Dans un co-stream, si l'un des streamers n'a pas mis de catégorie, il
     n'est pas centré verticalement. » La règle de la 3.98 existe pourtant, et
     le scénario 85 la tient : elle étire la boîte des métadonnées sur la
     hauteur de la rangée, puis centre son contenu.

     CE QU'ELLE SUPPOSAIT SANS LE DIRE : que le pseudo soit SEUL dans la boîte.
     C'est vrai d'une carte ordinaire. Ça ne l'est pas d'une carte de
     co-stream : Twitch y pose un mini-avatar DANS le bloc metadata — celui
     dont l'alt nomme l'hôte, et dont getCostreamInfo tire ce login. La boîte
     fait alors deux lignes même sans catégorie ; la centrer ne déplace rien.

     CE QUE CE SCÉNARIO TIENT, et pourquoi il en faut cinq assertions : la
     géométrie du cas signalé ; le fait que la règle ne DÉBORDE pas sur la
     carte de co-stream qui a une catégorie ; le fait qu'un masquage n'est pas
     une perte — l'hôte reste lisible dans le DOM, donc l'aperçu le dira ; et
     le garde-fou, qui est la seule assertion à parler d'un Twitch futur. */
  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    window.__fx = {
      duoavec:  { id: 'c1', createdAt: h, viewers: 900, game: 'Just Chatting', tags: [] },
      duosans:  { id: 'c2', createdAt: h, viewers: 800, game: null,            tags: [] },
      solosans: { id: 'c3', createdAt: h, viewers: 700, game: null,            tags: [] },
      figee:    { id: 'c5', createdAt: h, viewers: 650, game: null,            tags: [] },
      nohook:   { id: 'c4', createdAt: h, viewers: 600, game: null,            tags: [] },
      /* UN SUBATHON SANS CATÉGORIE. Les deux conditions se rencontrent
         rarement, et c'est précisément pour cela qu'un audit était nécessaire :
         la règle qui vide la metadata d'une carte sans catégorie masquait tout
         ce qui n'est pas le <p> du pseudo — or la pastille du jour ET
         l'enveloppe du nom vivent DEDANS. La carte perdait son nom. */
      subsanscat: { id: 'c6', createdAt: h, viewers: 550, game: null, tags: [],
                    title: 'SUBATHON JOUR 3 — on continue' },
      /* ET UN SUBATHON DONT LE PSEUDO N'A PAS SON CROCHET, comme les cartes
         « En live avec » que Twitch rend autrement. Signalement : jour 14 dans
         l'aperçu, aucune pastille sur la carte. */
      subsanshook: { id: 'c7', createdAt: h, viewers: 500, game: 'Just Chatting',
                     tags: [], title: 'MOUSEATHON DAY 14' },
    };
    // Trois cartes de CO-STREAM (mini-avatar dans la metadata), une ordinaire.
    window.__costreamHost = { duoavec: 'hote', duosans: 'hote', nohook: 'hote' };
    /* LA RANGÉE ÉPINGLÉE, et c'est le cas qui a coûté deux versions. Une
       correction qui se contente de DEMANDER l'étirement de la colonne perd
       contre une règle de Twitch qui l'épingle en haut : verte au banc,
       sans effet sur la vraie page. Le harnais épingle donc pour de bon. */
    window.__rangeeFigee = ['figee'];
    window.__addCard('duoavec',  'Just Chatting', '900');
    window.__addCard('duosans',  '', '800');
    window.__addCard('solosans', '', '700');
    window.__addCard('figee',    '', '650');
    window.__addCard('nohook',   '', '600');
    window.__addCard('subsanscat', '', '550');
    window.__addCard('subsanshook', 'Just Chatting', '500');
    /* LE GARDE-FOU N'A DE SENS QUE SI ON PEUT LE DÉCLENCHER. La règle épargne
       ce qui porte le hook du pseudo ; si Twitch le retirait, elle n'aurait
       plus rien à épargner et effacerait la carte. On retire donc le hook sur
       UNE carte, et on vérifie qu'elle garde son texte. */
    for (const l of ['nohook', 'subsanshook']) {
      [...document.querySelectorAll('.side-nav-card')]
        .find(c => c.querySelector(`a[href="/${l}"]`))
        .querySelector('p[data-a-target="side-nav-title"]')
        .removeAttribute('data-a-target');
    }
  });
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 7, 9000);
  await attendre(page,
    () => document.querySelectorAll('[data-tse-nocat="true"]').length === 5, 9000);

  const etat = await page.evaluate(() => {
    const carte = (l) => [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.querySelector(`a[href="/${l}"]`));
    const lire = (l) => {
      const c = carte(l);
      const rangee = c.querySelector('.metacell');
      // Le pseudo : par le hook quand il existe, par le premier <p> sinon —
      // c'est justement la carte dont on a retiré le hook qu'il faut mesurer.
      const p = c.querySelector('p[data-a-target="side-nav-title"]')
             || c.querySelector('[data-a-target="side-nav-card-metadata"] p');
      const r = rangee.getBoundingClientRect(), pr = p.getBoundingClientRect();
      const mini = c.querySelector('[data-a-target="side-nav-card-metadata"] .tse-mini');
      const cat  = c.querySelector('[data-a-target="side-nav-card-metadata"] p[title]');
      return {
        // Écart entre le centre du PSEUDO et le centre de la rangée.
        ecart: Math.round((pr.top + pr.height / 2) - (r.top + r.height / 2)),
        pseudoVisible: pr.height > 0 && (p.textContent || '').trim() === l,
        miniAffiche: !!mini && getComputedStyle(mini).display !== 'none',
        // L'hôte se lit-il encore dans le DOM, masqué ou non ?
        hote: !!c.querySelector('img[alt^="Co-stream d\'un stream de "]'),
        catAffichee: !!cat && getComputedStyle(cat).display !== 'none'
                     && (cat.textContent || '').trim(),
        hauteurRangee: Math.round(r.height),
      };
    };
    return { duoavec: lire('duoavec'), duosans: lire('duosans'),
             solosans: lire('solosans'), figee: lire('figee'),
             nohook: lire('nohook') };
  });

  /* LE CAS SIGNALÉ. Une carte de co-stream sans catégorie : le mini-avatar
     cesse d'occuper une ligne, et le pseudo se retrouve au milieu. */
  ok('le pseudo d\'un co-streamer sans catégorie est centré, à un pixel près',
     Math.abs(etat.duosans.ecart) <= 1 && etat.duosans.hauteurRangee > 0,
     JSON.stringify(etat.duosans));
  ok('…parce que le mini-avatar du co-stream n\'occupe plus de ligne',
     etat.duosans.miniAffiche === false && etat.solosans.miniAffiche === false,
     JSON.stringify({ duo: etat.duosans.miniAffiche, solo: etat.solosans.miniAffiche }));
  /* MASQUER N'EST PAS PERDRE. Le CSS ne change rien à ce que lisent
     querySelector et textContent : l'hôte reste extractible, donc l'aperçu
     au survol continue de dire « Co-stream de … ». */
  ok('…et l\'hôte reste lisible dans le DOM, donc l\'aperçu le dira encore',
     etat.duosans.hote === true, JSON.stringify(etat.duosans));
  /* LA RÈGLE NE DÉBORDE PAS. Elle ne vise que les cartes marquées sans
     catégorie ; celle qui en a une garde la sienne, mini-avatar compris.
     « Discussions » et non « Just Chatting » : la catégorie affichée est le
     libellé TRADUIT, celui que l'extension écrit depuis la réponse. */
  ok('la carte de co-stream AVEC catégorie n\'est pas touchée',
     etat.duoavec.catAffichee === 'Discussions' && etat.duoavec.miniAffiche === true,
     JSON.stringify(etat.duoavec));
  /* LA RANGÉE QUI ÉPINGLE SA COLONNE. C'est le cas que deux versions ont
     manqué : demander l'étirement ne suffit pas, il faut centrer la BOÎTE et
     passer devant la règle de Twitch. Cette assertion-ci est la seule du
     scénario qui distingue la correction de la 4.3 de celle de la 3.98. */
  ok('…et il l\'est aussi quand la rangée épingle sa colonne en haut',
     Math.abs(etat.figee.ecart) <= 1, JSON.stringify(etat.figee));
  /* ── L'ASSERTION EST TOURNÉE, ET C'EST UN AUDIT QUI L'A EXIGÉ ──────────
     Elle disait : « sans le hook du pseudo, la règle s'efface au lieu
     d'effacer la carte ». C'était vrai, et c'était un aveu — la règle était
     INERTE sur les cartes décorées, c'est-à-dire sur le décor EXACT du
     signalement qui l'a fait écrire. Trois versions ont cru corriger un
     centrage qui ne s'appliquait pas là où il était demandé.

     LA RÈGLE SUIT DÉSORMAIS NOTRE PROPRE MARQUE, posée par le scan sur la
     ligne que `cardNameEl` retrouve. Le garde-fou demeure — si la ligne
     n'était pas trouvée, la règle resterait inerte — mais il ne se déclenche
     plus sur une carte que Twitch a simplement décorée. On exige donc les
     DEUX : le texte est là, ET la carte est centrée comme ses voisines. */
  ok('une carte sans le hook garde son texte ET se centre comme les autres',
     etat.nohook.pseudoVisible === true && Math.abs(etat.nohook.ecart) <= 1,
     JSON.stringify(etat.nohook));

  /* ── CE QU'UN AUDIT A TROUVÉ, ET QUE PERSONNE N'AURAIT SIGNALÉ ───────────
     La règle ci-dessus vide la metadata d'une carte sans catégorie. Elle
     épargnait le <p> du pseudo et ses ANCÊTRES, et masquait tout le reste —
     y compris ce qui vit DEDANS. Or le pseudo d'une carte de subathon n'est
     pas un texte nu : c'est une enveloppe et une pastille, toutes deux posées
     dans le <p>. La carte perdait donc son nom, et il aurait fallu qu'un
     subathon sans catégorie se présente pour que ça se voie. */
  await attendre(page,
    () => !!document.querySelector('[data-tse-subathon-day]'), 9000);
  const sub = await page.evaluate(() => {
    const carte = (l) => [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.querySelector(`a[href="/${l}"]`));
    const lire = (l) => {
      const c = carte(l);
      const nom = c.querySelector('.tse-subathon-nom');
      const puce = c.querySelector('.tse-subathon-jour');
      const vu = (x) => !!x && getComputedStyle(x).display !== 'none'
                     && x.getBoundingClientRect().height > 0;
      return { jour: c.dataset.tseSubathonDay || null,
               nomVu: vu(nom), nomTexte: (nom?.textContent || '').trim(),
               puceVue: vu(puce), puceTexte: (puce?.textContent || '').trim() };
    };
    return { sanscat: lire('subsanscat'), sanshook: lire('subsanshook') };
  });
  ok('un subathon sans catégorie garde son pseudo visible',
     sub.sanscat.nomVu === true && sub.sanscat.nomTexte === 'subsanscat',
     JSON.stringify(sub.sanscat));
  ok('…et sa pastille du jour, qui vit dans le même <p>',
     sub.sanscat.puceVue === true && sub.sanscat.puceTexte === 'J3',
     JSON.stringify(sub.sanscat));
  /* LE REPLI DU CROCHET. Une carte dont le pseudo n'a pas son
     data-a-target — comme les cartes « En live avec » de Twitch — recevait sa
     détection de subathon sans jamais recevoir sa pastille. */
  ok('un subathon dont le pseudo n\'a pas son crochet reçoit quand même sa pastille',
     sub.sanshook.jour === '14' && sub.sanshook.puceTexte === 'J14',
     JSON.stringify(sub.sanshook));

  await page.close();
}

titre('100. La langue déclarée — le second témoin de celles qui en posent deux');
{
  /* ── CE QUE LA BORNE À DEUX NE SAIT PAS FAIRE ─────────────────────────────
     Elle écarte qui pose dix langues. Elle laisse passer qui en pose deux, et
     c'est voulu — un stream bilingue existe. Mais deux tags suffisent aussi à
     entrer dans deux classements sans parler ni l'une ni l'autre, et rien
     dans les tags ne sépare les deux cas.

     LE TÉMOIN NE VIENT DONC PAS DES TAGS : c'est la langue DÉCLARÉE dans les
     réglages de la chaîne. Le tag suit la soirée, la déclaration suit le
     compte — on ne la retouche pas pour le classement du jour.

     CE QUE CE SCÉNARIO TIENT, et pourquoi chaque cas est là :
       — la règle écarte, et elle écarte le bon (faux) ;
       — elle regarde les DEUX tags, pas seulement le premier (second) ;
       — le SILENCE n'écarte pas — ni une chaîne dont Twitch ne dit rien
         (muet), ni une langue hors de notre table (exotique) ;
       — UN tag n'est pas un empilement : la règle ne s'y applique pas du tout
         (mono, dont la déclaration ne correspond pourtant à rien) ;
       — et un refus du schéma n'écarte personne, ni ne se redemande sans fin.
     Les deux derniers sont ceux qu'on perd le plus facilement. */
  const monter = (page, declarees) => page.evaluate((decl) => {
    window.__declarees = decl;
    const h = new Date(Date.now() - 30 * 60_000).toISOString();
    window.__fx = { suivi1: { id: 'id-suivi1', createdAt: h, viewers: 400,
                              game: 'Just Chatting', tags: [] } };
    window.__addCard('suivi1', 'Just Chatting', '400');
    const cats = [];
    // Du remplissage, pour que la descente ait un pool crédible à parcourir.
    for (let i = 0; i < 3; i++) {
      const streams = [];
      for (let k = 0; k < 30; k++) {
        streams.push({ login: `en${i}_${k}`, viewers: 500 - k, tags: ['English'] });
      }
      cats.push({ name: 'c' + i, viewers: 400_000 - i, streams });
    }
    /* Les six cas, tous assez gros pour être en tête : s'ils n'y sont pas,
       c'est la règle qui les a écartés et rien d'autre. */
    cats.push({ name: 'vitrine', viewers: 399_000, streams: [
      // Déclaration = le PREMIER de ses deux tags.
      { login: 'temoin',   viewers: 9000, tags: ['Français', 'English'] },
      // Déclaration = le SECOND. Une règle qui ne lirait que le premier tag
      // l'écarterait — c'est la seule chose qui distingue ce cas du précédent.
      { login: 'second',   viewers: 8500, tags: ['Français', 'English'] },
      // Déclaration = NI L'UN NI L'AUTRE. Le seul qui doit sortir.
      { login: 'faux',     viewers: 8000, tags: ['Français', 'Português'] },
      // Twitch répond, mais ne déclare rien : le silence n'écarte pas.
      { login: 'muet',     viewers: 7500, tags: ['Français', 'English'] },
      // Déclaration hors de notre table : on ne sait pas traduire, donc on ne
      // juge pas. Même conclusion, par une autre voie.
      { login: 'exotique', viewers: 7000, tags: ['Français', 'English'] },
      // UN SEUL TAG, et une déclaration qui ne correspond pas. La règle ne le
      // concerne pas : une langue déclarée une fois n'est pas un empilement.
      { login: 'mono',     viewers: 6500, tags: ['Français'] },
    ] });
    window.__cats = cats;
  }, declarees);

  const DECLAREES = { temoin: 'fr', second: 'en', faux: 'en',
                      exotique: 'xx', mono: 'de' };

  const page = await fresh();
  await monter(page, DECLAREES);
  await wait(page, 1500);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await attendre(page, () => window.tse.global.top(30).length > 0, 9000);
  /* L'EXCLUSION EST DIFFÉRÉE, ET C'EST LE CŒUR DU DISPOSITIF. Au premier
     passage la langue déclarée n'est pas connue : la chaîne ENTRE. La demande
     part, la réponse arrive, et c'est la lecture SUIVANTE qui l'écarte. On
     attend donc la disparition — ce qui prouve du même coup que la requête a
     réellement eu lieu et changé le résultat. */
  await attendre(page,
    () => !window.tse.global.top(30).some(r => r.login === 'faux'), 9000);
  await wait(page, 600);

  const top = await page.evaluate(() => window.tse.global.top(30).map(r => r.login));
  ok('une chaîne dont la déclaration est l\'un de ses deux tags reste',
     top.includes('temoin') && top.includes('second'), JSON.stringify(top.slice(0, 8)));
  ok('…celle dont la déclaration n\'est ni l\'un ni l\'autre sort',
     !top.includes('faux'), JSON.stringify(top.slice(0, 8)));
  ok('…le silence n\'écarte pas : ni sans déclaration, ni hors de notre table',
     top.includes('muet') && top.includes('exotique'), JSON.stringify(top.slice(0, 8)));
  /* UN SEUL TAG N'EST PAS UN EMPILEMENT. « mono » déclare l'allemand et pose
     « Français » : la règle ne le regarde pas, et c'est délibéré — ce qu'on
     traque est l'empilement, pas le désaccord entre un réglage et un tag. */
  ok('…et un tag unique n\'est pas concerné, même en désaccord avec le réglage',
     top.includes('mono'), JSON.stringify(top.slice(0, 8)));

  const bilan = await page.evaluate(() => window.tse.global.report().langueDeclaree);
  ok('le rapport dit ce que le second témoin a fait',
     bilan && bilan.refuse === false && bilan.servis >= 1 && bilan.ecartees >= 1,
     JSON.stringify(bilan));

  /* ── LE REFUS DU SCHÉMA ──────────────────────────────────────────────────
     `broadcastSettings { language }` est une RECONSTITUTION : cette machine
     n'a pas accès à twitch.tv. Si le schéma ne le connaît pas, la règle doit
     n'écarter personne — et ne pas redemander cinquante fois. */
  const p2 = await fresh();
  await monter(p2, 'erreur');
  await wait(p2, 1500);
  await p2.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await attendre(p2, () => window.tse.global.top(30).length > 0, 9000);
  // Plusieurs marches, pour que l'insistance se verrait si elle avait lieu.
  await wait(p2, 4000);
  const apresRefus = await p2.evaluate(() => ({
    top: window.tse.global.top(30).map(r => r.login),
    bilan: window.tse.global.report().langueDeclaree,
  }));
  ok('un schéma qui refuse la requête n\'écarte personne',
     apresRefus.top.includes('faux') && apresRefus.bilan.ecartees === 0,
     JSON.stringify(apresRefus.bilan));
  ok('…et le refus est retenu : on ne redemande pas à chaque marche',
     apresRefus.bilan.refuse === true && apresRefus.bilan.demandes === 1,
     JSON.stringify(apresRefus.bilan));

  await p2.close();
  await page.close();
}

titre('101. Une catégorie absente ne détruit pas la frise');
{
  /* ── LA LIGNE QUI EFFAÇAIT TOUT ──────────────────────────────────────────
     `suivreCategorie` jetait le registre entier dès qu'un relevé rendait un
     direct EN LIGNE sans catégorie : « rien ne dit ce qu'on regarde ». Le
     raisonnement tenait sur l'instant et manquait le cas qui compte — un
     direct qui REPREND n'a pas encore de catégorie pendant les premières
     secondes. Le badge de reprise se posait, puis la ligne suivante jetait le
     passé que la reprise venait de préserver.

     SIGNALEMENT : « il avait une frise avant, et il n'en a plus du tout quand
     il a repris. » Deux symptômes, une seule ligne : la chaîne qui n'annonce
     JAMAIS de catégorie n'avait jamais de frise non plus.

     TROIS CAS, ET ILS SE CASSENT SÉPARÉMENT : la traversée d'un trou de
     catégorie, la reprise dont le premier relevé est muet, et le fait que le
     trou n'ouvre PAS de segment — se taire n'est pas inventer. */
  const page = await fresh();
  const h = (min) => new Date(Date.now() - min * 60_000).toISOString();
  await page.evaluate((vieux) => {
    window.__fx = {
      trou:    { id: 't1', sid: 's-trou-1',   createdAt: vieux, viewers: 900,
                 game: 'Just Chatting', tags: [] },
      revient: { id: 't2', sid: 's-revient-1', createdAt: vieux, viewers: 800,
                 game: 'Just Chatting', tags: [] },
    };
    window.__addCard('trou',    'Discussions', '900');
    window.__addCard('revient', 'Discussions', '800');
  }, h(180));
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 2);

  const changerJeu = (login, jeu) => page.evaluate(([l, j]) => {
    window.__fx[l].game = j;
    window.tse.rescan();
  }, [login, jeu]);
  const survoler = async (login) => {
    await hoverLogin(page, login);
    await attendre(page,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
  };
  const relacher = async (login) => {
    await page.evaluate((l) => {
      [...document.querySelectorAll('.side-nav-card')]
        .find(c => c.dataset.tseLogin === l)
        ?.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
    }, login);
    await attendre(page,
      () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);
  };
  const frise = () => page.evaluate(() => {
    const f = document.querySelector('.tse-preview__frise');
    if (!f) return null;
    return {
      total:  f.querySelector('.tse-preview__frise-total')?.textContent.trim() || '',
      lignes: [...f.querySelectorAll('.tse-preview__frise-ligne')]
        .map(li => li.textContent.trim()),
    };
  });

  /* ── 1. LE TROU DE CATÉGORIE ─────────────────────────────────────────────
     Deux catégories observées, puis un relevé muet, puis la catégorie revient.
     Sans la correction, le relevé muet efface les deux. */
  await changerJeu('trou', 'Elden Ring');
  await wait(page, 900);
  await changerJeu('trou', null);
  await wait(page, 900);
  await survoler('trou');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 6000);
  const pendant = await frise();
  await relacher('trou');
  ok('un relevé sans catégorie ne détruit pas la frise accumulée',
     pendant !== null && pendant.lignes.length >= 2
     && pendant.lignes.some(l => /Elden Ring/.test(l)),
     JSON.stringify(pendant));

  /* ET IL N'OUVRE PAS DE SEGMENT. Se taire n'est pas inventer : on ne sait pas
     que la catégorie a changé, donc la dernière s'étend. Une frise qui
     gagnerait une ligne à chaque trou dirait un basculement qui n'a pas eu
     lieu. */
  await changerJeu('trou', 'Elden Ring');
  await wait(page, 900);
  await survoler('trou');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 6000);
  const apresTrou = await frise();
  await relacher('trou');
  ok('…et il n\'ouvre aucun segment : la catégorie qui revient est la même',
     apresTrou !== null
     && apresTrou.lignes.filter(l => /Elden Ring/.test(l)).length === 1,
     JSON.stringify(apresTrou));

  /* ── 2. LA REPRISE DONT LE PREMIER RELEVÉ EST MUET ───────────────────────
     C'est le cas signalé, et il tient en trois temps : on observe, la chaîne
     coupe, elle revient SANS catégorie. La frise doit traverser les trois. */
  await changerJeu('revient', 'VALORANT');
  await wait(page, 900);
  await page.evaluate(() => { window.__fx.revient = null; window.tse.rescan(); });
  await wait(page, 600);
  await page.evaluate((iso) => {
    window.__fx.revient = { id: 't2', sid: 's-revient-2', createdAt: iso,
                            viewers: 800, game: null, tags: [] };
    window.tse.rescan();
  }, new Date().toISOString());
  await wait(page, 900);
  await survoler('revient');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 6000);
  const apresReprise = await frise();
  const badges = await page.evaluate(() =>
    [...document.querySelectorAll('.tse-preview__badge')].map(b => b.className));
  await relacher('revient');
  ok('une reprise dont le premier relevé n\'a pas de catégorie garde sa frise',
     apresReprise !== null && apresReprise.lignes.length >= 2
     && apresReprise.lignes.some(l => /VALORANT/.test(l)),
     JSON.stringify(apresReprise));
  /* LE BADGE ET LA FRISE VONT ENSEMBLE, et c'est ce que le défaut séparait :
     le badge se posait — il ne dépend pas de la catégorie — et la frise
     disparaissait dans la même microtâche. */
  ok('…et son badge de reprise, qui n\'a jamais cessé de s\'afficher',
     badges.some(c => /tse-preview__badge--reprise/.test(c)), JSON.stringify(badges));
  /* L'ORIGINE A SURVÉCU : le total couvre les trois heures du direct, et non
     les quelques secondes du tronçon. C'est ce que la frise existe pour dire. */
  ok('…et le total couvre le direct entier, pas le tronçon d\'après la coupure',
     apresReprise !== null && /\dh/.test(apresReprise.total),
     JSON.stringify(apresReprise));

  await page.close();
}

titre('102. La coupure qu\'on n\'a pas vue passer — la demander à Twitch');
{
  /* ── CE QUE LA MÉMOIRE NE PEUT PAS SAVOIR ────────────────────────────────
     Tout le dispositif de reprise repose sur une OBSERVATION : pour savoir
     qu'un direct a repris, il fallait l'avoir vu en ligne avant la coupure,
     dans cette page-ci. Un onglet ouvert pendant la coupure, un rechargement,
     une chaîne qu'on ne suit pas — et le direct repart de zéro.

     LE SIGNALEMENT VENAIT AVEC SA PREUVE : une chaîne coupée trois minutes,
     reprise, et rien. Or la page « Vidéos » de cette chaîne portait les deux
     enregistrements côte à côte — celui d'avant, terminé, et celui d'après, en
     cours. Ce que nous n'avons pas vu, Twitch l'a archivé.

     LE CRITÈRE EST UN RACCORD : l'archive précédente doit se TERMINER dans la
     fenêtre de reprise avant le départ du direct courant. Trois cas le
     cassent séparément — le raccord lui-même, la fenêtre, et l'exception du
     subathon — et un quatrième vérifie qu'on ramène AUSSI le passé.

     ATTENTION À L'ÉCHELLE. `RECONNECT_GAP_MAX` vaut dix minutes en production
     et 2,5 SECONDES dans ce banc (cf. tests/build.mjs). Les trous ci-dessous
     sont donc exprimés en secondes : un trou de 1 s est une reprise, un trou
     de 10 s n'en est pas une. Les écrire en minutes rendrait les deux hors
     fenêtre, et les deux assertions passeraient sans rien prouver. */
  const page = await fresh();
  const ilYa = (ms) => new Date(Date.now() - ms).toISOString();

  await page.evaluate(({ neuf, vieux, vieilDepart, milieu, troisHeures }) => {
    // Les quatre chaînes viennent de démarrer : c'est la seule situation où la
    // sonde part, et c'est celle d'un onglet ouvert pendant la coupure.
    const mk = (id, titre) => ({ id, sid: 's-' + id, createdAt: neuf, viewers: 900,
                                 game: 'VALORANT', tags: [],
                                 ...(titre ? { title: titre } : {}) });
    window.__fx = {
      revenu:   mk('r1'),
      loin:     mk('r2'),
      marathon: mk('r3', 'SUBATHON JOUR 12 — on continue'),
      sansvod:  mk('r4'),
      muette:   mk('r5'),
      /* LE CAS PAYO. Le direct tourne depuis DEUX HEURES après une coupure de
         rien du tout. La 4.3 ne le sondait pas — une garde exigeait un direct
         de moins de dix minutes — et le rapport de l'utilisateur l'a dit en un
         chiffre : « sondes 1 » sur deux cent vingt-neuf survols. L'âge du
         direct et le trou entre les deux tronçons sont deux durées sans
         rapport : la seconde ne bouge plus jamais. */
      ancien:   { id: 'r6', sid: 's-r6', createdAt: vieilDepart, viewers: 900,
                  game: 'VALORANT', tags: [] },
      /* DEUX COUPURES. Le signalement le décrit en une phrase : « il a déjà eu
         une coupure, qui s'est bien affichée ; il en a eu une deuxième, et là
         plus rien ». La sonde ne remontait qu'UN cran de la chaîne. */
      double:   mk('r7'),
      /* LE TRONÇON COURANT A SON PROPRE PASSÉ, et il doit survivre à la
         coupure suivante comme celui des tronçons d'avant. Trois heures de
         direct, des chapitres de VOD, AUCUNE archive qui raccorde : rien ici
         ne vient de la sonde, tout vient de la requête de chapitres. */
      garde:    { id: 'r8', sid: 's-r8', createdAt: troisHeures, viewers: 900,
                  game: 'Rust', tags: [] },
      /* LE MÊME CAS QUE « ancien », DANS L'AUTRE ORDRE. Deux réponses lancées
         ensemble ne reviennent pas dans un ordre garanti, et le passé doit
         arriver entier quel que soit celui qui gagne. Celui-ci est survolé
         SANS retard — la sonde répond la première ; « ancien » est survolé
         avec, et les chapitres arrivent avant elle. Un seul des deux ordres
         laisse survivre un mutant différent. */
      croise:   { id: 'r9', sid: 's-r9', createdAt: vieilDepart, viewers: 900,
                  game: 'VALORANT', tags: [] },
    };
    /* CINQ HEURES D'ARCHIVE, terminées juste avant le départ du direct : c'est
       le tronçon d'avant. Les chapitres qu'elle porte sont le passé que plus
       aucune observation ne peut rattraper. */
    /* ── LE TROU SE VISE, IL NE SE SUBIT PAS ────────────────────────────────
       `lengthSeconds` est un ENTIER de secondes : la fin d'une archive n'est
       donc connue qu'à une demi-seconde près. Viser un trou de zéro le rendait
       NÉGATIF une fois sur deux — et un trou négatif est rejeté, donc le
       raccord sautait selon l'heure qu'il était. Le banc l'a montré en
       changeant de valeur quand un cas s'est ajouté devant.

       On vise donc 1,2 s : avec l'arrondi, le trou réel tient dans [0,7 ; 1,7],
       très à l'intérieur de la fenêtre de 2,5 s du banc, et très en dehors
       pour le cas « hors fenêtre », visé à dix secondes. */
    const archiveAvant = (debutISO, borneISO, chapitres) => ({
      createdAt: debutISO,
      lengthSeconds: Math.round(
        (Date.parse(borneISO) - 1_200 - Date.parse(debutISO)) / 1000),
      chapitres,
    });
    const archive = (ecartMs, chapitres) => ({
      createdAt: vieux,
      lengthSeconds: Math.round(
        (Date.parse(neuf) - ecartMs - Date.parse(vieux)) / 1000),
      chapitres,
    });
    const passe = [{ pos: 0, jeu: 'Just Chatting' },
                   { pos: 2 * 3600_000, jeu: 'Elden Ring' }];
    window.__vodRecent = {
      // La PREMIÈRE archive est celle du direct en cours : elle commence avec
      // lui, donc elle ne raccorde rien. C'est la SECONDE qu'il faut trouver —
      // une implémentation qui ne regarderait que la plus récente échoue ici.
      revenu:   [{ createdAt: neuf, lengthSeconds: 60, chapitres: [] },
                 archive(1_200, passe)],
      // Terminée dix secondes avant le départ : au-delà de la fenêtre.
      loin:     [archive(10_000, passe)],
      marathon: [archive(1_200, passe)],
      sansvod:  [],
      // Une archive qui raccorde, mais SANS le moindre chapitre : on apprend
      // l'origine et la coupure, rien du contenu.
      muette:   [archive(1_200, [])],
      /* L'archive d'avant s'est terminée une seconde avant le départ de ce
         direct-là — c'est-à-dire il y a deux heures et une seconde. Le trou
         vaut toujours une seconde. */
      ancien:   [{ createdAt: vieilDepart, lengthSeconds: 7200, chapitres: [] },
                 archiveAvant(vieux, vieilDepart, passe)],
      croise:   [{ createdAt: vieilDepart, lengthSeconds: 7200, chapitres: [] },
                 archiveAvant(vieux, vieilDepart, passe)],
      /* TROIS ARCHIVES, DONC DEUX COUPURES. La chaîne se remonte de proche en
         proche : le direct courant raccorde au tronçon du milieu, qui raccorde
         lui-même au premier. Le passé le plus ancien — « Just Chatting » — n'est
         atteignable qu'au SECOND cran, et c'est lui qui prouve que la chaîne
         est remontée en entier plutôt qu'à moitié.
           t-5h      ┤ premier tronçon (Just Chatting, puis Elden Ring)
           t-1h -1s  ┤ fin, coupure d'une seconde
           t-1h      ┤ tronçon du milieu (Rocket League)
           t-1s      ┤ fin, coupure d'une seconde
           maintenant┤ tronçon courant */
      garde:    [],
      double:   [{ createdAt: neuf, lengthSeconds: 60, chapitres: [] },
                 archiveAvant(milieu, neuf, [{ pos: 0, jeu: 'Rocket League' }]),
                 archiveAvant(vieux, milieu, passe)],
    };
    /* Les chapitres du tronçon COURANT de « garde », servis par TseVodChapters
       et non par la liste des archives. */
    /* LA SONDE RÉPOND APRÈS LES CHAPITRES, et c'est l'ordre qu'il faut jouer :
       l'autre vient tout seul. Le passé du tronçon courant est alors rangé sous
       l'origine d'AVANT l'adoption, et il faut le reporter sous celle d'après —
       sans quoi la sonde l'écrase en arrivant. Un réseau ne garantit pas
       l'ordre de deux réponses ; du code juste dans un seul des deux ordres est
       faux la moitié du temps. */
    window.__retardOp = {};
    window.__vod = {
      garde:  { createdAt: troisHeures, chapitres: [
        { pos: 0, jeu: 'Minecraft' }, { pos: 2 * 3600_000, jeu: 'Rust' }] },
      /* Les chapitres du tronçon COURANT de « ancien », qui arrivent par la
         requête ordinaire pendant que la sonde ramène ceux de la chaîne. Les
         deux doivent se retrouver dans la même frise : c'est ce qui éprouve à
         la fois l'accumulation et le report sous la nouvelle origine. */
      ancien: { createdAt: vieilDepart, chapitres: [{ pos: 0, jeu: 'Fortnite' }] },
      croise: { createdAt: vieilDepart, chapitres: [{ pos: 0, jeu: 'Apex Legends' }] },
    };
    for (const l of ['revenu', 'loin', 'marathon', 'sansvod', 'muette', 'ancien',
                     'double', 'garde', 'croise']) {
      window.__addCard(l, 'VALORANT', '900');
    }
  }, { neuf: ilYa(1_000), vieux: ilYa(5 * 3600_000),
       vieilDepart: ilYa(2 * 3600_000), milieu: ilYa(3600_000 + 1_000),
       troisHeures: ilYa(3 * 3600_000) });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length === 9);

  const survoler = async (login) => {
    await hoverLogin(page, login);
    await attendre(page,
      () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
  };
  const relacher = async (login) => {
    await page.evaluate((l) => {
      [...document.querySelectorAll('.side-nav-card')]
        .find(c => c.dataset.tseLogin === l)
        ?.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
    }, login);
    await attendre(page,
      () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 3000);
  };
  const vue = () => page.evaluate(() => {
    const f = document.querySelector('.tse-preview__frise');
    return {
      badges: [...document.querySelectorAll('.tse-preview__badge')].map(b => b.className),
      frise: f ? {
        total:    f.querySelector('.tse-preview__frise-total')?.textContent.trim() || '',
        coupures: f.querySelector('.tse-preview__frise-coupures')?.textContent.trim() || '',
        marques:  f.querySelectorAll('.tse-preview__frise-coupure').length,
        lignes:   [...f.querySelectorAll('.tse-preview__frise-ligne')]
          .map(li => li.textContent.trim()),
      } : null,
    };
  });

  /* ── 1. LE RACCORD ───────────────────────────────────────────────────────
     L'archive d'avant s'est terminée une seconde avant le départ du direct.
     C'est une reprise, et nous ne l'avons jamais vue. */
  await survoler('revenu');
  await attendre(page,
    () => !!document.querySelector('.tse-preview__badge--reprise'), 6000);
  await attendre(page,
    () => /coupure/.test(document.querySelector('.tse-preview__frise')?.textContent || ''),
    6000);
  await wait(page, 300);
  const revenu = await vue();
  await relacher('revenu');
  ok('un direct dont l\'archive d\'avant raccorde gagne son badge de reprise',
     revenu.badges.some(c => /tse-preview__badge--reprise/.test(c)),
     JSON.stringify(revenu.badges));
  ok('…et son compte de coupures, sur une coupure que personne n\'a observée',
     /1/.test(revenu.frise?.coupures || '') && revenu.frise?.marques >= 1,
     JSON.stringify(revenu.frise));
  /* LE PASSÉ VIENT AVEC. Les chapitres de l'archive d'avant sont ce que le
     direct a traversé, datés par Twitch. Sans eux le badge dirait « il a été
     coupé » sur une frise qui ne montre que la dernière seconde. */
  ok('…et la frise porte le passé d\'avant la coupure, pas le seul tronçon d\'après',
     revenu.frise !== null && /\dh/.test(revenu.frise.total)
     && revenu.frise.lignes.some(l => /Elden Ring/.test(l)),
     JSON.stringify(revenu.frise));

  /* ── 1 bis. LA COUPURE SUIVANTE NE DOIT RIEN EFFACER ─────────────────────
     Le passé ramené par la sonde était rangé sous l'identifiant de STREAM. À
     la coupure suivante cet identifiant change — c'est la définition même
     d'une reprise — et tout disparaissait avec lui. Le signalement : « il a
     déjà eu une coupure, qui s'est bien affichée ; il en a eu une deuxième, et
     là plus rien ».

     ON OBSERVE DONC LA SECONDE COUPURE, à la suite de celle qu'on a adoptée :
     nouvel identifiant, nouveau départ. La frise doit garder le passé de la
     première ET compter la seconde. */
  await page.evaluate(() => {
    window.__fx.revenu.sid = 's-r1-suite';
    window.__fx.revenu.createdAt = new Date().toISOString();
    window.tse.rescan();
  });
  await wait(page, 900);
  await survoler('revenu');
  await attendre(page,
    () => /coupure/.test(document.querySelector('.tse-preview__frise')?.textContent || ''),
    6000);
  await wait(page, 300);
  const suite = await vue();
  await relacher('revenu');
  ok('une seconde coupure n\'efface pas le passé ramené pour la première',
     suite.frise !== null && suite.frise.lignes.some(l => /Elden Ring/.test(l)),
     JSON.stringify(suite.frise && suite.frise.lignes));
  ok('…et elle s\'ajoute au compte au lieu de le remplacer',
     /2/.test(suite.frise?.coupures || ''), JSON.stringify(suite.frise));

  /* ── 2. LA FENÊTRE ───────────────────────────────────────────────────────
     Dix secondes de trou, quatre fois la fenêtre du banc : ce n'est pas une
     reprise, c'est un autre direct. Un raccord sans borne ferait passer pour
     une reprise l'archive d'avant-hier. */
  await survoler('loin');
  await wait(page, 900);
  const loin = await vue();
  await relacher('loin');
  ok('une archive terminée hors de la fenêtre ne fait pas une reprise',
     !loin.badges.some(c => /tse-preview__badge--reprise/.test(c)),
     JSON.stringify(loin.badges));

  /* ── 3. L'EXCEPTION DU SUBATHON ──────────────────────────────────────────
     Twitch force un redémarrage toutes les 48 h : ce n'est pas une coupure.
     L'exception vaut pour la sonde comme pour l'observation directe, sans quoi
     la sonde la contournerait par la porte de derrière.

     CE QUE CETTE ASSERTION PROUVE DEPUIS LA 4.15.12, ET CE QU'ELLE NE PROUVE
     PLUS. La garde s'est déplacée EN AMONT : la sonde ne part plus du tout sur
     un subathon (scénario 148), si bien que « pas de badge » s'obtient ici
     sans que `adopterReprise` ait eu à refuser quoi que ce soit. L'assertion
     tiendrait donc même si SA garde à lui disparaissait.

     ON LA GARDE QUAND MÊME, et on écrit pourquoi : c'est la défense de
     dernier rang. Une chaîne peut devenir un subathon APRÈS avoir été sondée
     — le titre change en cours de direct — et c'est alors ce refus-là, et lui
     seul, qui empêche le badge. Le scénario 148 tient l'autre moitié : que la
     requête ne parte pas. Les deux ensemble disent « ni dépensé, ni adopté ». */
  await survoler('marathon');
  await wait(page, 900);
  const marathon = await vue();
  await relacher('marathon');
  ok('un subathon qui redémarre n\'est pas une reprise, même par la sonde',
     !marathon.badges.some(c => /tse-preview__badge--reprise/.test(c)),
     JSON.stringify(marathon.badges));

  /* ── 4. AUCUNE ARCHIVE DU TOUT ───────────────────────────────────────────
     Une chaîne qui n'archive pas ses diffusions rend une liste vide. Ce n'est
     ni une panne ni un refus : la sonde part, elle est servie, et elle ne
     trouve rien. Le cas est ordinaire et ne doit rien casser. */
  await survoler('sansvod');
  await wait(page, 900);
  const sansvod = await vue();
  await relacher('sansvod');
  ok('une chaîne sans la moindre archive ne fait ni reprise ni dégât',
     !sansvod.badges.some(c => /tse-preview__badge--reprise/.test(c)),
     JSON.stringify(sansvod.badges));

  /* ── 5. L'ORIGINE RECALÉE, ET CE QU'ELLE EMPÊCHE ─────────────────────────
     Une archive qui raccorde mais ne porte AUCUN chapitre : on apprend
     l'origine et la coupure, rien du contenu. C'est le seul décor où le
     recalage de la frise sur l'origine se voie — ailleurs, les chapitres
     d'avant la portent déjà.

     SANS LUI, la frise garde le départ du TRONÇON et annonce « 0m » sur un
     direct de cinq heures : elle ne se tait pas, elle se trompe. Avec lui,
     elle constate qu'elle n'a rien observé de ces cinq heures et se tait —
     ce que ce module fait partout ailleurs plutôt que de combler par
     hypothèse. L'assertion accepte donc les deux issues honnêtes et refuse la
     seule qui mente. */
  await survoler('muette');
  await wait(page, 900);
  const muette = await vue();
  await relacher('muette');
  ok('une archive sans chapitre ne fait pas dire « 0m » à un direct de cinq heures',
     muette.frise === null || /\dh/.test(muette.frise.total),
     JSON.stringify(muette.frise));

  /* ── 5 bis. LES DEUX SOURCES, DANS L'ORDRE NATUREL ───────────────────────
     La sonde répond la première, puis les chapitres du tronçon courant : ces
     derniers doivent se ranger sous l'origine que l'adoption vient de poser,
     et non sous celle qu'ils connaissaient au départ de la requête. C'est
     l'ordre opposé à celui du cas suivant, et chacun laisse survivre un mutant
     que l'autre tue. */
  await survoler('croise');
  await attendre(page,
    () => /Apex/.test(document.querySelector('.tse-preview__frise')?.textContent || ''),
    6000);
  await wait(page, 300);
  const croise = await vue();
  await relacher('croise');
  ok('les deux sources du passé se rejoignent quand la sonde répond la première',
     croise.frise !== null
     && croise.frise.lignes.some(l => /Elden Ring/.test(l))
     && croise.frise.lignes.some(l => /Apex/.test(l)),
     JSON.stringify(croise.frise && croise.frise.lignes));

  /* ── 6. LE DIRECT ANCIEN — LE CAS QUI A COÛTÉ UNE VERSION ────────────────
     Deux heures de direct après une coupure d'une seconde. La 4.3 ne le
     sondait pas : une garde confondait l'ÂGE du direct courant avec le TROU
     entre les deux tronçons. Le premier grandit sans cesse, le second est
     figé dans le passé.

     PAS DE BADGE, ET C'EST JUSTE : « Reprise après coupure » est une nouvelle,
     elle s'éteint au bout de dix minutes. Le FAIT, lui, appartient au direct
     entier — c'est la frise qui le porte, et c'est elle qu'on vérifie ici.

     ET L'ORDRE INVERSE DU CAS PRÉCÉDENT : les chapitres arrivent AVANT la
     sonde. Le passé du tronçon courant est alors rangé sous l'origine d'avant
     l'adoption, et c'est la sonde qui doit le reprendre. */
  await page.evaluate(() => { window.__retardOp = { TseVodRecent: 200 }; });
  await survoler('ancien');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 6000);
  // La sonde répond APRÈS les chapitres (cf. __retardOp) : la frise paraît une
  // première fois sans elle, et c'est la seconde forme qu'on mesure.
  await attendre(page,
    () => /coupure/.test(document.querySelector('.tse-preview__frise')?.textContent || ''),
    6000);
  await wait(page, 300);
  const ancien = await vue();
  await relacher('ancien');
  ok('un direct de deux heures gagne sa coupure comme un direct d\'une seconde',
     /1/.test(ancien.frise?.coupures || ''), JSON.stringify(ancien.frise));
  ok('…et son passé d\'avant la coupure, qui ne dépend pas de son âge',
     ancien.frise !== null && ancien.frise.lignes.some(l => /Elden Ring/.test(l)),
     JSON.stringify(ancien.frise));
  /* DEUX SOURCES, UNE SEULE FRISE. « Elden Ring » vient de la chaîne d'archives
     rapportée par la sonde ; « Fortnite » vient de la requête de chapitres
     ordinaire, partie AVANT que l'adoption ne déplace l'origine. Les deux
     doivent y être : le passé s'accumule, et il est reporté sous la nouvelle
     origine au lieu d'être abandonné sous l'ancienne. */
  ok('…et les deux sources du passé se retrouvent dans la même frise',
     ancien.frise !== null && ancien.frise.lignes.some(l => /Fortnite/.test(l)),
     JSON.stringify(ancien.frise && ancien.frise.lignes));
  /* LE BADGE NE SE RALLUME PAS POUR AUTANT : son horodatage est celui du
     tronçon, pas celui de la découverte. Sans quoi une coupure vieille de deux
     heures s'annoncerait comme une nouvelle pendant dix minutes de plus. */
  ok('…sans rallumer un badge que la nouvelle a cessé d\'être',
     !ancien.badges.some(c => /tse-preview__badge--reprise/.test(c)),
     JSON.stringify(ancien.badges));

  /* ── 7. DEUX COUPURES, ET LA CHAÎNE SE REMONTE EN ENTIER ─────────────────
     C'est le signalement : la première coupure s'affichait, la seconde faisait
     tout disparaître. La sonde ne remontait qu'un cran — elle cherchait
     l'archive qui raccorde au départ du direct, et s'arrêtait là.

     TROIS ASSERTIONS, ET ELLES SE CASSENT SÉPARÉMENT : le COMPTE des coupures,
     le nombre de MARQUES sur le ruban, et le passé du tronçon le plus ancien —
     « Just Chatting », qui n'est atteignable qu'au SECOND cran. Une chaîne
     remontée à moitié donne le bon compte de rien du tout mais perd ce
     passé-là, et c'est ce qu'un seul compteur ne dirait pas. */
  await survoler('double');
  await attendre(page,
    () => /coupure/.test(document.querySelector('.tse-preview__frise')?.textContent || ''),
    6000);
  await wait(page, 300);
  const deux = await vue();
  await relacher('double');
  ok('un direct coupé deux fois annonce DEUX coupures, pas une',
     /2/.test(deux.frise?.coupures || ''), JSON.stringify(deux.frise));
  ok('…et le ruban porte deux marques, une par coupure',
     deux.frise?.marques === 2, JSON.stringify(deux.frise));
  /* LE SECOND CRAN. « Rocket League » vient du tronçon du milieu, atteignable
     au premier cran ; « Just Chatting » vient du plus ancien, qui n'existe que
     si la chaîne a été remontée jusqu'au bout. */
  ok('…et la frise porte le passé des DEUX tronçons d\'avant',
     deux.frise !== null
     && deux.frise.lignes.some(l => /Rocket League/.test(l))
     && deux.frise.lignes.some(l => /Discussions|Just Chatting/.test(l)),
     JSON.stringify(deux.frise && deux.frise.lignes));

  /* ── 8. LE PASSÉ DU TRONÇON COURANT SURVIT AUSSI ─────────────────────────
     Les deux cas précédents portent un passé venu de la SONDE. Celui-ci vient
     de la requête de chapitres ordinaire — trois heures de direct observées
     tard, aucune archive qui raccorde — et il doit traverser la coupure
     suivante par le même chemin. Sans quoi le produit garderait le passé des
     tronçons qu'il n'a pas vus et perdrait celui qu'il a demandé lui-même. */
  await survoler('garde');
  await attendre(page,
    () => !!document.querySelector('.tse-preview__frise-ligne'), 6000);
  await wait(page, 600);
  const avantCoupureGarde = await vue();
  await relacher('garde');
  ok('les chapitres du tronçon courant arrivent bien dans la frise',
     avantCoupureGarde.frise !== null
     && avantCoupureGarde.frise.lignes.some(l => /Minecraft/.test(l)),
     JSON.stringify(avantCoupureGarde.frise && avantCoupureGarde.frise.lignes));
  /* L'ARCHIVE SUIT LE TRONÇON, comme sur le vrai Twitch : le nouvel
     enregistrement ne sait rien de ce qui précède la coupure. Sans ce
     remplacement, une seconde requête de chapitres rapporterait le passé
     toute seule et l'assertion ne prouverait rien. */
  await page.evaluate(() => {
    window.__fx.garde.sid = 's-r8-suite';
    window.__fx.garde.createdAt = new Date().toISOString();
    window.__vod.garde = { createdAt: new Date().toISOString(),
                           chapitres: [{ pos: 0, jeu: 'Rust' }] };
    window.tse.rescan();
  });
  await wait(page, 900);
  await survoler('garde');
  await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 6000);
  await wait(page, 400);
  const apresCoupureGarde = await vue();
  await relacher('garde');
  ok('…et ils survivent à la coupure, comme ceux des tronçons d\'avant',
     apresCoupureGarde.frise !== null
     && apresCoupureGarde.frise.lignes.some(l => /Minecraft/.test(l)),
     JSON.stringify(apresCoupureGarde.frise && apresCoupureGarde.frise.lignes));

  /* UN VRAI NOUVEAU DIRECT REPART VIERGE. Le passé est rangé par ORIGINE
     précisément pour cela : une chaîne éteinte au-delà de la fenêtre de
     reprise, puis rallumée, commence un autre direct — lui resservir les
     chapitres de la veille daterait le live d'hier. L'invalidation ne demande
     aucune purge : la clé ne correspond plus, et c'est tout. */
  await page.evaluate(() => { window.__fx.garde = null; window.tse.rescan(); });
  await wait(page, 3400);            // au-delà de la fenêtre de reprise du banc
  await page.evaluate(() => {
    window.__fx.garde = { id: 'r8', sid: 's-r8-neuf',
                          createdAt: new Date().toISOString(),
                          viewers: 900, game: 'Rust', tags: [] };
    window.__vod.garde = null;
    window.tse.rescan();
  });
  await wait(page, 900);
  await survoler('garde');
  await wait(page, 900);
  const neufDirect = await vue();
  await relacher('garde');
  ok('un vrai nouveau direct ne réhérite pas du passé de la veille',
     neufDirect.frise === null
     || !neufDirect.frise.lignes.some(l => /Minecraft/.test(l)),
     JSON.stringify(neufDirect.frise && neufDirect.frise.lignes));

  /* ── 9. CE QUE LA SONDE A COÛTÉ ET RAPPORTÉ ──────────────────────────────
     Le rapport est le seul œil qu'on ait sur ce mécanisme depuis une vraie
     page. `sondes` compte les directs jeunes interrogés — quatre, un par
     chaîne — et `adoptees` ceux qui ont gagné leur origine : un seul.

     ── CE CHIFFRE A CHANGÉ EN 4.15.12, ET PAS POUR ARRANGER LE BANC ────────
     Il disait « trouvees 6 · adoptees 5 », et cet écart d'une unité était LE
     SUBATHON : sondé, son chaînage trouvé, puis jeté par l'adoption. Le banc
     tenait donc en place une requête gâchée — c'est la troisième fois qu'une
     assertion de ce fichier se révèle être le contrat du défaut plutôt que
     celui du produit, et ça se reconnaît à ceci qu'elle épouse un nombre sans
     dire d'où il vient.

     LES DEUX RAPPORTS DE TERRAIN PORTAIENT LE MÊME ÉCART — « trouvees 5 ·
     adoptees 4 » puis « trouvees 4 · adoptees 3 », avec « subathons.detectes
     1 » les deux fois. La garde est maintenant en amont (scénario 148), donc
     le subathon n'est plus sondé du tout.

     ET ON EXIGE DÉSORMAIS L'ÉGALITÉ, ce qui vaut mieux qu'un nombre : tant
     que tout ce qui est trouvé est adopté, aucune sonde n'a été dépensée pour
     une réponse qu'on jette. Un écart qui reviendrait ici voudrait dire
     quelque chose, au lieu d'être le bruit de fond qu'il était. */
  const bilan = await page.evaluate(() =>
    window.tse.panneau.rapport().reseau.chapitres.reprise);
  ok('le rapport dit ce que la sonde a demandé et ce qu\'elle a trouvé',
     bilan && bilan.sondes >= 9 && bilan.trouvees === 5
     && bilan.trouvees === bilan.adoptees && bilan.chaines === 1,
     JSON.stringify(bilan));
  /* UNE SEULE FOIS PAR SESSION DE STREAM. Le survol se répète, la requête non :
     sans cette garde, chaque passage de souris relancerait la même opération
     pour la même réponse.

     ON RE-SURVOLE UNE CHAÎNE QUI N'A RIEN DONNÉ, et c'est tout l'intérêt : sur
     une chaîne adoptée, la garde « déjà chaînée » suffirait à elle seule et
     l'assertion passerait même sans registre des sondes. La première rédaction
     re-survolait l'adoptée ; le mutant qui retirait le registre survivait. */
  await survoler('loin');
  await wait(page, 600);
  await relacher('loin');
  await survoler('sansvod');
  await wait(page, 600);
  await relacher('sansvod');
  const apres = await page.evaluate(() =>
    window.tse.panneau.rapport().reseau.chapitres.reprise);
  ok('…et elle ne repart pas au survol suivant : une opération par session',
     apres.sondes === bilan.sondes, JSON.stringify(apres));

  await page.close();
}

titre('103. Le tri ne déplace pas ce qu\'on est en train de lire');
{
  /* ── LE SIGNALEMENT ───────────────────────────────────────────────────────
     « Quand on regarde les cartes en Top Chaînes, la liste s'update souvent et
     parfois on n'a pas le temps de lire une carte : elle disparaît car la
     liste s'update et la souris n'est plus sur la carte qu'on survole. »

     C'est structurel : le classement mondial se retrie à chaque relevé, une
     chaîne gagne mille spectateurs, et la carte glisse sous un pointeur qui
     n'a pas bougé. L'aperçu se ferme alors non pas parce qu'on l'a quitté,
     mais parce que la carte est partie.

     TROIS ASSERTIONS, ET IL FAUT LES TROIS. Que l'ordre TIENNE pendant la
     lecture ; que les CONTENUS continuent de vivre — ce qui gênait était le
     mouvement, pas la fraîcheur ; et que l'ordre reprenne À LA FERMETURE, sans
     quoi la correction remplacerait un défaut par un pire. */
  const page = await fresh();
  const h = new Date(Date.now() - 3600_000).toISOString();
  await page.evaluate((iso) => {
    window.__fx = {
      un:    { id: 'o1', createdAt: iso, viewers: 300, game: 'Just Chatting', tags: [] },
      deux:  { id: 'o2', createdAt: iso, viewers: 200, game: 'Just Chatting', tags: [] },
      trois: { id: 'o3', createdAt: iso, viewers: 100, game: 'Just Chatting', tags: [] },
    };
    window.__addCard('un', 'Discussions', '300');
    window.__addCard('deux', 'Discussions', '200');
    window.__addCard('trois', 'Discussions', '100');
  }, h);
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 3, 9000);
  await page.evaluate(() =>
    document.querySelector(`[data-tse-sort-mode="viewers"]`)?.click());
  await wait(page, 600);

  const ordre = () => page.evaluate(() =>
    [...document.querySelectorAll('.side-nav-card')].map(c => c.dataset.tseLogin));
  ok('au départ, le tri par spectateurs range un, deux, trois',
     JSON.stringify(await ordre()) === JSON.stringify(['un', 'deux', 'trois']),
     JSON.stringify(await ordre()));

  /* ── ON SURVOLE « trois », PUIS ON LE FAIT PASSER EN TÊTE ────────────────
     Sans la retenue, le tri le déplacerait de deux rangs — et le pointeur,
     lui, ne bougerait pas. */
  await hoverLogin(page, 'trois');
  await attendre(page,
    () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 6000);
  await page.evaluate(() => { window.__fx.trois.viewers = 9000; window.tse.rescan(); });
  await wait(page, 1200);
  ok('pendant qu\'un aperçu est ouvert, l\'ordre affiché ne bouge pas',
     JSON.stringify(await ordre()) === JSON.stringify(['un', 'deux', 'trois']),
     JSON.stringify(await ordre()));
  /* LA FRAÎCHEUR N'EST PAS SUSPENDUE, seulement le mouvement : le compteur de
     la carte survolée montre bien sa nouvelle valeur. Une retenue qui gèlerait
     aussi les contenus remplacerait une gêne par une carte qui ment. */
  const compteur = await page.evaluate(() =>
    [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.dataset.tseLogin === 'trois')
      ?.querySelector('.tse-viewers')?.textContent || '');
  ok('…mais les contenus, eux, continuent de se mettre à jour',
     /9/.test(compteur), JSON.stringify(compteur));

  /* ── ET L'ORDRE REPREND DÈS QU'ON LÂCHE ─────────────────────────────────
     La fermeture programme un scan : sans lui, la liste resterait figée
     jusqu'au relevé suivant, c'est-à-dire une demi-minute après. */
  await page.evaluate(() => {
    [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.dataset.tseLogin === 'trois')
      ?.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
  });
  await attendre(page,
    () => [...document.querySelectorAll('.side-nav-card')][0]?.dataset.tseLogin === 'trois',
    6000);
  ok('…et il reprend sa place dès que l\'aperçu se ferme',
     JSON.stringify(await ordre()) === JSON.stringify(['trois', 'un', 'deux']),
     JSON.stringify(await ordre()));

  await page.close();
}

titre('104. Top Chaînes avec une seule chaîne suivie, et elle est décorée');
{
  /* ── LE SIGNALEMENT ───────────────────────────────────────────────────────
     « Gros problème, on ne voit que IronMouse dans Top Chaînes. Actuellement
     elle est également la seule en live dans mes chaînes suivies. » Le rapport
     donnait la cause en deux chiffres : pool 2 124, fabriquées 0.

     LE MODE TOP CHAÎNES NE DESSINE PAS SES CARTES, IL LES CLONE. Il lui faut
     donc un MODÈLE — une carte native en direct — et il n'acceptait qu'une
     carte NEUTRE, pour ne pas transposer ses décorations sur une chaîne qui
     n'a rien à voir. Une seule chaîne suivie en direct, portant une pastille
     de collaboration : aucun modèle, et un classement mondial parfaitement
     connu qui ne s'affichait nulle part.

     ON NE REFUSE PLUS LA CARTE, ON LA NETTOIE. `scrubClone` retire désormais
     aussi les décorations de TWITCH — mini-avatars, pastilles de rôle, « +N »
     de collaboration — et la carte décorée devient un modèle de second choix.
     La carte SPONSORISÉE reste écartée : sa mise en page diffère.

     TROIS ASSERTIONS : que le classement s'affiche, que la carte fabriquée ne
     porte AUCUNE des marques du modèle, et que le modèle neutre reste préféré
     quand il en existe un. */
  const page = await fresh();
  const h = new Date(Date.now() - 3600_000).toISOString();
  await page.evaluate((iso) => {
    window.__fx = {
      // L'UNIQUE chaîne suivie en direct, et elle est décorée : collaboration
      // (« +2 » dans sa catégorie) et mini-avatar de co-stream.
      seule: { id: 's1', createdAt: iso, viewers: 900, game: 'Just Chatting', tags: [] },
    };
    window.__costreamHost = { seule: 'hote' };
    window.__addCard('seule', 'Discussions', '900');
    const d = [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.querySelector('a[href="/seule"]'));
    /* LE « +N » DANS SON PROPRE ÉLÉMENT, et non accolé à la catégorie. La
       différence décide du test : accolé, la pastille collab le RETIRE du
       texte, donc le clone est propre sans qu'on ait rien fait. Dans son
       propre élément, elle se contente de le MASQUER — et `scrubClone` efface
       les styles, si bien qu'un « +2 » reparaîtrait sur la carte fabriquée. */
    const sp = document.createElement('span');
    sp.textContent = '+2';
    d.querySelector('[data-a-target="side-nav-card-metadata"]').appendChild(sp);
    /* ET SON PSEUDO N'A PAS LE CROCHET DE TWITCH. C'est le second signalement,
       sur la même chaîne : la disposition « En live avec » ne porte pas
       data-a-target="side-nav-title". Le repli de modèle ne servait alors à
       rien — le clonage renonçait juste après, et « Top Chaînes » restait vide
       avec « modele: repli » écrit dans le rapport. */
    d.querySelector('p[data-a-target="side-nav-title"]').removeAttribute('data-a-target');
    const cats = [];
    for (let i = 0; i < 3; i++) {
      const streams = [];
      for (let k = 0; k < 30; k++) {
        streams.push({ login: `g${i}_${k}`, viewers: 5000 - k, tags: ['English'] });
      }
      cats.push({ name: 'c' + i, viewers: 400_000 - i, streams });
    }
    window.__cats = cats;
  }, h);
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 1, 9000);
  await attendre(page,
    () => !!document.querySelector('.tse-collab-badge'), 9000);

  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await attendre(page, () => window.tse.global.top(30).length > 0, 9000);
  await attendre(page,
    () => document.querySelectorAll('[data-tse-synthetic="true"]').length > 0, 9000);
  await wait(page, 900);

  const etat = await page.evaluate(() => {
    const faites = [...document.querySelectorAll('.side-nav-card[data-tse-synthetic="true"]')];
    return {
      fabriquees: faites.length,
      /* AUCUNE MARQUE DU MODÈLE NE DOIT AVOIR VOYAGÉ. Le « +2 » ferait naître
         une pastille de collaboration sur une chaîne qui ne collabore avec
         personne, et le mini-avatar ferait annoncer un co-stream inexistant. */
      collab: faites.filter(c => !!c.querySelector('.tse-collab-badge')).length,
      plus:   faites.filter(c => /\+\s*\d/.test(c.textContent || '')).length,
      mini:   faites.filter(c =>
        !!c.querySelector('img[alt^="Co-stream d\'un stream de "]')).length,
      icone:  faites.filter(c => !!c.querySelector('[class*="iconContainer--"]')).length,
      /* OÙ LE NOM ET LA CATÉGORIE ONT ÉTÉ ÉCRITS. Le repli choisit la ligne du
         pseudo sans le crochet de Twitch : s'il se trompait de ligne, le nom
         irait dans la catégorie — la carte resterait « fabriquée », les
         compteurs seraient verts, et elle afficherait n'importe quoi. */
      lignes: faites.slice(0, 1).map(c => [...c.querySelectorAll(
        '[data-a-target="side-nav-card-metadata"] p')].map(x => x.textContent.trim())),
    };
  });
  ok('le classement s\'affiche même quand l\'unique carte disponible est décorée',
     etat.fabriquees >= 10, JSON.stringify(etat));
  /* LE RAPPORT NE DOIT PLUS AVOIR DE RAISON DE RENONCER. Un « modele: repli »
     accompagné de « fabriquees 0 » ne disait pas ce qui avait manqué ; c'est
     l'écart qu'un utilisateur a rapporté deux fois de suite. */
  const refus = await page.evaluate(() =>
    window.tse.panneau.rapport().page.modeleRefus);
  ok('…et le rapport ne signale aucun renoncement du clonage',
     refus === null, String(refus));
  ok('…le nom et la catégorie sont écrits chacun sur sa ligne',
     JSON.stringify(etat.lignes[0] || []) === JSON.stringify(['g0_0', 'c0']),
     JSON.stringify(etat.lignes));
  ok('…et aucune des marques du modèle n\'a voyagé sur les cartes fabriquées',
     etat.collab === 0 && etat.plus === 0 && etat.mini === 0 && etat.icone === 0,
     JSON.stringify(etat));

  /* LE MODÈLE NEUTRE RESTE PRÉFÉRÉ, ET C'EST LE RAPPORT QUI LE DIT. Une fois
     les décorations nettoyées, les deux modèles produisent des cartes
     identiques : la préférence ne se lit donc nulle part dans le DOM. Elle
     n'est pas décorative pour autant — c'est l'assurance du jour où Twitch
     inventera une décoration que le nettoyage ne connaît pas — et le rapport
     nomme la voie employée, ce qui la rend observable ET utile sur le terrain. */
  const voieRepli = await page.evaluate(() => window.tse.panneau.rapport().page.modele);
  ok('…et le rapport dit que le modèle vient du repli, faute de carte neutre',
     voieRepli === 'repli', String(voieRepli));
  await page.evaluate((iso) => {
    window.__fx.propre = { id: 's2', createdAt: iso, viewers: 800,
                           game: 'Just Chatting', tags: [] };
    window.__addCard('propre', 'Discussions', '800');
    window.tse.rescan();
  }, h);
  await wait(page, 1200);
  /* ON PROVOQUE UN CLONAGE, ET CE N'EST PAS UN ARTIFICE. `modeleVoie` n'est
     écrit que quand une carte est RÉELLEMENT fabriquée : sans clone à faire,
     le rapport garde la dernière voie employée, ce qui est exact — il dit
     d'où vient le modèle en service, pas celui qu'on choisirait.

     Cette assertion mesurait donc la préférence PAR RICOCHET : jusqu'en
     4.13.6, un retour d'onglet détruisait toutes les cartes fabriquées, si
     bien qu'une reconstruction suivait chaque `rescan()` et recalculait la
     voie. Ce démontage était le défaut corrigé en 4.13.7 — et l'assertion en
     dépendait sans le dire. On retire donc une carte pour que la passe
     suivante ait quelque chose à cloner : c'est le moment, et le seul, où la
     préférence a un sens. */
  await page.evaluate(() => {
    document.querySelector('.side-nav-card[data-tse-synthetic="true"]')?.remove();
  });
  await wait(page, 1500);
  const voieNeutre = await page.evaluate(() => window.tse.panneau.rapport().page.modele);
  ok('…et le modèle neutre reprend la main au prochain clonage',
     voieNeutre === 'neutre', String(voieNeutre));

  /* ── LE TROISIÈME APPELANT DU REPÈRE, ET IL ÉCRIVAIT DÉJÀ FAUX ───────────
     `cardNameEl` sert aussi à l'aperçu, qui lit le pseudo SUR LA CARTE pour
     nommer un hôte de co-stream. Privé du crochet, il retombait sur la
     capitalisation du login : le badge annonçait « Co-stream de Seule » quand
     la carte de l'hôte, deux lignes plus haut, affichait « seule ». Personne
     ne l'a signalé — c'est précisément pourquoi il fallait l'attraper ici.

     ON AJOUTE DONC UNE TROISIÈME CARTE, co-streameuse de `seule`, et on la
     survole : le nom de l'hôte vient de la carte sans crochet. Elle arrive
     APRÈS les assertions de modèle, qu'elle fausserait en s'y mêlant. */
  await page.evaluate((iso) => {
    window.__costreamHost.duo = 'seule';
    window.__fx.duo = { id: 's3', createdAt: iso, viewers: 700,
                        game: 'Just Chatting', tags: [] };
    window.__addCard('duo', 'Discussions', '700');
    window.tse.rescan();
  }, h);
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 3, 9000);
  await hoverLogin(page, 'duo');
  await attendre(page,
    () => !!document.querySelector('.tse-preview__badge--costream strong'), 8000);
  const hote = await page.evaluate(() =>
    document.querySelector('.tse-preview__badge--costream strong')?.textContent ?? null);
  ok('…et l\'aperçu nomme l\'hôte avec le pseudo de SA carte, non la capitalisation du login',
     hote === 'seule', String(hote));

  await page.close();
}

/* ═════════ LA CHAÎNE QUI N'ANNONCE AUCUNE CATÉGORIE ═════════════════════
   Signalement sur la 4.5.2 : « j'ai plus de cartes dans Top Chaînes quand je
   n'ai plus qu'une seule qui a *en live avec* ». Le rapport disait, mot pour
   mot, ce que ce scénario reproduit : « modele: repli », « modeleRefus:
   pseudo », « fabriquees 0 ».

   LE REPLI DE LA 4.5.2 SE MORDAIT LA QUEUE. Il écartait « la catégorie » en
   la demandant à `cardCategoryEl` — dont le DERNIER repli est « le premier
   <p> de la metadata », c'est-à-dire LE PSEUDO dès que la chaîne n'annonce
   aucune catégorie. Sur une carte sans crochet ET sans catégorie, une garde
   écartait le nom, l'autre la catégorie, et il ne restait rien à écrire.

   ET LE DÉFAUT EN CACHAIT UN SECOND, qui ne se serait vu qu'après. La même
   confusion faisait lire le pseudo comme catégorie : la fabrication écrivait
   donc le NOM, puis la CATÉGORIE par-dessus, dans le même <p>. Trente cartes
   nommées d'après leur catégorie — un « Top Chaînes » plein, et faux. */
{
  titre('105. Une chaîne sans catégorie, et sans le crochet du pseudo');
  const page = await fresh();
  const h = new Date(Date.now() - 3600_000).toISOString();
  await page.evaluate((iso) => {
    /* L'UNIQUE CHAÎNE SUIVIE EN DIRECT, dans le décor exact du signalement :
       une carte « En live avec » — donc sans data-a-target="side-nav-title" —
       qui n'annonce AUCUNE catégorie. Twitch ne rend alors pas un <p> vide :
       il ne rend pas de <p> du tout, et la metadata n'a plus qu'une ligne. */
    window.__fx = { seule: { id: 's1', createdAt: iso, viewers: 900,
                             game: null, tags: [] } };
    window.__costreamHost = { seule: 'hote' };
    window.__addCard('seule', null, '900');
    const d = [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.querySelector('a[href="/seule"]'));
    d.querySelector('p[data-a-target="side-nav-title"]').removeAttribute('data-a-target');
    const cats = [];
    for (let i = 0; i < 3; i++) {
      const streams = [];
      for (let k = 0; k < 30; k++) {
        streams.push({ login: `g${i}_${k}`, viewers: 5000 - k, tags: ['English'] });
      }
      cats.push({ name: 'c' + i, viewers: 400_000 - i, streams });
    }
    window.__cats = cats;
  }, h);
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 1, 9000);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await attendre(page, () => window.tse.global.top(30).length > 0, 9000);
  await wait(page, 1500);

  const etat = await page.evaluate(() => {
    const p = window.tse.panneau.rapport().page;
    const faites = [...document.querySelectorAll(
      '.side-nav-card[data-tse-synthetic="true"]')];
    return {
      fabriquees: faites.length, modele: p.modele, refus: p.modeleRefus,
      /* CE QUE LA CARTE FABRIQUÉE PORTE VRAIMENT. Le compte de cartes ne suffit
         pas : une fabrication qui écrit la catégorie par-dessus le nom les
         fabrique toutes, et les compteurs restent verts. */
      lignes: faites.slice(0, 1).map(c => [...c.querySelectorAll(
        '[data-a-target="side-nav-card-metadata"] p')].map(x => x.textContent.trim())),
      // La carte NATIVE, elle, ne doit pas s'être vu inventer une catégorie.
      categorieNative: [...document.querySelectorAll('.side-nav-card')]
        .find(c => c.dataset.tseLogin === 'seule')?.dataset.tseCategory ?? null,
    };
  });
  ok('le classement s\'affiche même quand la seule carte n\'a pas de catégorie',
     etat.fabriquees >= 10, JSON.stringify(etat));
  ok('…et le rapport nomme le modèle au lieu de n\'en trouver aucun',
     etat.modele === 'repli' && etat.refus === null, JSON.stringify(etat));
  ok('…et la carte fabriquée porte le PSEUDO, que rien n\'est venu écraser',
     JSON.stringify(etat.lignes[0] || []) === JSON.stringify(['g0_0']),
     JSON.stringify(etat.lignes));
  /* UNE CARTE SANS CATÉGORIE N'A PAS DE CATÉGORIE. Le repli lisait le pseudo :
     `data-tse-category` valait « seule », et les filtres s'y appliquaient. */
  ok('…et la chaîne sans catégorie n\'en a pas vu naître une à son nom',
     etat.categorieNative !== 'seule', String(etat.categorieNative));
  await page.close();
}

/* ═════════ LE MODÈLE MÉMORISÉ, ET CE QUI LUI VOLAIT LA PLACE ═══════════
   Le second choix de modèle, ajouté en 4.5.1, passe AVANT le modèle mémorisé.
   S'il se révèle inexploitable, la fabrication rend null et le clonage
   abandonne pour de bon : le rapport dit qu'un modèle a été trouvé, et rien
   n'en sort. C'est la forme générale du défaut rapporté deux fois de suite,
   et elle survivrait à la correction du cas particulier.

   ON EXIGE DONC DU CANDIDAT ce que la fabrication exigera de son clone. La
   carte que Twitch rend dans une disposition qu'on ne sait pas lire — ici, le
   pseudo dans un <span> — n'est ni adoptée ni MÉMORISÉE : elle laisse la place
   au modèle relevé plus tôt dans la session. */
{
  titre('106. Le modèle mémorisé reprend la main sur un candidat illisible');
  const page = await fresh();
  const h = new Date(Date.now() - 3600_000).toISOString();
  const lot = (pref) => {
    const cats = [];
    for (let i = 0; i < 3; i++) {
      const streams = [];
      for (let k = 0; k < 30; k++) {
        streams.push({ login: `${pref}${i}_${k}`, viewers: 5000 - k, tags: ['English'] });
      }
      cats.push({ name: 'c' + i, viewers: 400_000 - i, streams });
    }
    return cats;
  };
  await page.evaluate(({ iso, cats }) => {
    window.__fx = {
      propre:  { id: 's1', createdAt: iso, viewers: 800, game: 'Just Chatting', tags: [] },
      bizarre: { id: 's2', createdAt: iso, viewers: 900, game: 'Just Chatting', tags: [] },
    };
    /* C'EST LE TRI QUI DÉCIDE DE L'ORDRE, ET DONC DU TEST. Les deux boucles de
       modèle prennent le PREMIER candidat neutre, et l'extension range les
       cartes par spectateurs : la carte illisible doit donc être la PLUS
       REGARDÉE, sans quoi la carte propre passe devant et le garde n'a plus
       rien à écarter. Rédigé d'abord sur l'ordre d'insertion, ce décor laissait
       survivre le mutant qui retire le garde. */
    window.__addCard('bizarre', 'Discussions', '900');
    window.__addCard('propre', 'Discussions', '800');
    // Une chaîne suivie encore hors ligne : elle servira à éprouver l'AUTRE
    // boucle de modèle, celle des cartes en avance sur Twitch.
    window.__addCard('dormant', 'Discussions', 'Déconnecté', false);
    /* LA CARTE QUE LE CLONAGE NE SAIT PAS LIRE. Elle est bien native, bien en
       direct et parfaitement NEUTRE — elle serait donc élue modèle du premier
       coup — mais son pseudo vit dans un <span>. Aucune ligne à réécrire, donc
       aucun clone exploitable, et rien ne se fabriquait plus nulle part. */
    const b = [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.querySelector('a[href="/bizarre"]'));
    b.querySelectorAll('[data-a-target="side-nav-card-metadata"] p').forEach((p) => {
      const s = document.createElement('span');
      s.textContent = p.textContent;
      for (const a of [...p.attributes]) s.setAttribute(a.name, a.value);
      p.replaceWith(s);
    });
    window.__cats = cats;
  }, { iso: h, cats: lot('g') });
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 2, 9000);

  /* ── L'AUTRE BOUCLE DE MODÈLE : LES CARTES EN AVANCE SUR TWITCH ────────
     Même sélection, même défaut, et aucune mémoire pour la rattraper. Si la
     carte illisible est élue, plus une seule chaîne n'est posée en avance —
     et le rapport n'en dit rien, puisqu'il n'y a pas de carte à compter. */
  await page.evaluate(() => {
    window.__fx.dormant = { id: 's3', createdAt: new Date().toISOString(),
                            viewers: 500, game: 'Just Chatting', tags: [] };
  });
  await attendre(page,
    () => !!document.querySelector('.side-nav-card[data-tse-synthetic="true"]'), 6000);
  const avance = await page.evaluate(() =>
    !!document.querySelector('.side-nav-card[data-tse-synthetic="true"]'));
  ok('la carte en avance est posée, la carte illisible n\'ayant pas pris le modèle',
     avance === true, String(avance));

  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await attendre(page, () => window.tse.global.top(30).length > 0, 9000);
  await attendre(page,
    () => document.querySelectorAll('[data-tse-synthetic="true"]').length > 0, 9000);
  await wait(page, 900);
  const un = await page.evaluate(() => ({
    modele: window.tse.panneau.rapport().page.modele,
    fabriquees: document.querySelectorAll('[data-tse-synthetic="true"]').length,
  }));
  ok('la carte neutre LISIBLE sert de modèle, et non la première venue',
     un.modele === 'neutre' && un.fabriquees >= 10, JSON.stringify(un));

  /* ELLE DISPARAÎT, et il ne reste que celle qu'on ne sait pas lire. Le
     palmarès change au même instant : sans modèle exploitable, les nouvelles
     chaînes ne seraient jamais posées — et le classement mentirait en silence
     au lieu de rester vide, ce qui est pire. */
  await page.evaluate((cats) => {
    delete window.__fx.propre;
    [...document.querySelectorAll('.side-nav-card')]
      .filter(c => c.querySelector('a[href="/propre"]')).forEach(c => c.remove());
    window.__cats = cats;
    window.tse.rescan();
  }, lot('h'));
  await attendre(page,
    () => window.tse.global.top(30).some(r => r.login.startsWith('h')), 9000);
  await wait(page, 1500);
  const deux = await page.evaluate(() => {
    const p = window.tse.panneau.rapport().page;
    const faites = [...document.querySelectorAll('[data-tse-synthetic="true"]')];
    return { modele: p.modele, refus: p.modeleRefus, fabriquees: faites.length,
             neufs: faites.filter(c => (c.dataset.tseLogin || '').startsWith('h')).length };
  });
  ok('…et quand il ne reste qu\'une carte illisible, le modèle mémorisé reprend la main',
     deux.modele === 'memoire', JSON.stringify(deux));
  ok('…si bien que le classement continue de suivre le palmarès',
     deux.neufs >= 10 && deux.refus === null, JSON.stringify(deux));
  await page.close();
}

/* ═════════ QUAND TWITCH TITRE AUSSI LA LIGNE DU PSEUDO ═════════════════
   Le repérage du pseudo a été corrigé trois fois, et chaque rapport suivant
   l'a démenti. La 4.5.3 ramenait le repère à un seul critère — « la ligne qui
   ne porte pas de `title` », la catégorie portant toujours le sien. Il est
   juste, et il est FRAGILE : Twitch pose aussi un `title` sur le pseudo quand
   il le tronque. Les deux lignes en portent alors un, le critère unique ne les
   départage plus — il les écarte TOUTES — et la carte entière est refusée.

   DEUX REPÈRES VALENT MIEUX QU'UN, et le second est un filet : à défaut de
   ligne sans `title`, la PREMIÈRE du groupe. Le pseudo est au-dessus de la
   catégorie dans toutes les dispositions connues de Twitch, et il n'y a ici
   qu'une ligne à se tromper.

   LE MÊME `title` TROMPAIT `cardCategoryEl`, qui prenait « le premier p[title] »
   — donc le pseudo. La chaîne se voyait ranger sous une catégorie à son propre
   nom, et la carte fabriquée portait sa catégorie à la place de son pseudo. */
{
  titre('107. Twitch titre les deux lignes, et le repère unique ne suffit plus');
  const page = await fresh();
  const h = new Date(Date.now() - 3600_000).toISOString();
  await page.evaluate((iso) => {
    window.__fx = { seule: { id: 's1', createdAt: iso, viewers: 900,
                             game: 'Just Chatting', tags: [] } };
    window.__costreamHost = { seule: 'hote' };
    window.__addCard('seule', 'Discussions', '900');
    const d = [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.querySelector('a[href="/seule"]'));
    /* LE DÉCOR EXACT : pas de crochet d'automatisation — la disposition « En
       live avec » —, et un `title` sur le pseudo comme sur la catégorie. */
    const nom = d.querySelector('p[data-a-target="side-nav-title"]');
    nom.removeAttribute('data-a-target');
    nom.setAttribute('title', 'seule');
    const cats = [];
    for (let i = 0; i < 3; i++) {
      const streams = [];
      for (let k = 0; k < 30; k++) {
        streams.push({ login: `g${i}_${k}`, viewers: 5000 - k, tags: ['English'] });
      }
      cats.push({ name: 'c' + i, viewers: 400_000 - i, streams });
    }
    window.__cats = cats;
  }, h);
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 1, 9000);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await attendre(page, () => window.tse.global.top(30).length > 0, 9000);
  await wait(page, 1500);

  const etat = await page.evaluate(() => {
    const p = window.tse.panneau.rapport().page;
    const faites = [...document.querySelectorAll(
      '.side-nav-card[data-tse-synthetic="true"]')];
    return {
      fabriquees: faites.length, modele: p.modele, refus: p.modeleRefus,
      sortie: p.sortie,
      lignes: faites.slice(0, 1).map(c => [...c.querySelectorAll(
        '[data-a-target="side-nav-card-metadata"] p')].map(x => x.textContent.trim())),
      categorieNative: [...document.querySelectorAll('.side-nav-card')]
        .find(c => c.dataset.tseLogin === 'seule')?.dataset.tseCategory ?? null,
      // Le recensement doit VOIR ce décor : c'est lui qui devra trancher la
      // prochaine fois, et une mesure qu'on n'éprouve pas ne mesure rien.
      recense: window.tse.panneau.rapport().lignes,
    };
  });
  ok('le classement s\'affiche quand les DEUX lignes portent un title',
     etat.fabriquees >= 10, JSON.stringify(etat));
  ok('…et la carte fabriquée porte le pseudo, non la catégorie',
     JSON.stringify(etat.lignes[0] || []) === JSON.stringify(['g0_0', 'c0']),
     JSON.stringify(etat.lignes));
  /* LA CHAÎNE NE SE RANGE PAS SOUS SON PROPRE NOM. C'est l'autre moitié du
     même défaut, et elle ne se voyait nulle part : les filtres s'appliquaient
     à une catégorie qui n'existe pas. */
  ok('…et la chaîne garde SA catégorie, et non son pseudo pour catégorie',
     etat.categorieNative === 'Just Chatting', String(etat.categorieNative));
  ok('…et le rapport dit que la passe est allée jusqu\'au bout',
     etat.sortie === 'ok' && etat.refus === null, JSON.stringify(etat));
  /* LE RECENSEMENT DOIT DIRE CE DÉCOR, sans quoi il ne servira pas le jour où
     il faudra trancher : une carte, aucun crochet, deux lignes toutes deux
     titrées, et un pseudo retrouvé quand même. */
  ok('…et le recensement du balisage décrit ce décor sans se tromper',
     etat.recense.crochet === 0 && etat.recense.p2 === 1
     && etat.recense.toutesTitrees === 1 && etat.recense.sansNom === 0
     && etat.recense.nomTitre === 1,
     JSON.stringify(etat.recense));
  await page.close();
}

/* ═════════ LE MODÈLE QUI NE SE DÉCOUVRE MAUVAIS QU'AU CLONAGE ═══════════
   Un candidat peut passer toutes les gardes et ne se révéler inexploitable
   qu'une fois CLONÉ : `scrubClone` retire les décorations de Twitch, et si
   l'une d'elles enveloppe le pseudo, le clone perd sa ligne de nom. La passe
   abandonnait alors tout — « fabriquees 0 » sur un classement parfaitement
   connu — et le mauvais modèle s'était DÉJÀ installé dans la mémoire de la
   session, où il remplaçait celui qui marchait.

   DEUX CORRECTIONS, ET ELLES SE TIENNENT : le modèle ne se mémorise qu'après
   avoir produit une carte, et un clone raté rejoue la mémoire au lieu de
   condamner la passe. L'une sans l'autre ne sert à rien — la mémoire rejouée
   serait le mauvais modèle. */
{
  titre('108. Un clone raté ne condamne plus la passe');
  const page = await fresh();
  const h = new Date(Date.now() - 3600_000).toISOString();
  const lot = (pref) => {
    const cats = [];
    for (let i = 0; i < 3; i++) {
      const streams = [];
      for (let k = 0; k < 30; k++) {
        streams.push({ login: `${pref}${i}_${k}`, viewers: 5000 - k, tags: ['English'] });
      }
      cats.push({ name: 'c' + i, viewers: 400_000 - i, streams });
    }
    return cats;
  };
  await page.evaluate(({ iso, cats }) => {
    window.__fx = {
      propre: { id: 's1', createdAt: iso, viewers: 800, game: 'Just Chatting', tags: [] },
      piege:  { id: 's2', createdAt: iso, viewers: 900, game: 'Just Chatting', tags: [] },
    };
    /* LE PIÈGE EST LA PLUS REGARDÉE : c'est le tri qui décide de l'ordre des
       candidats, et il range par spectateurs. Sans cela, la carte propre
       passerait devant et le piège ne serait jamais choisi. */
    window.__addCard('piege', 'Discussions', '900');
    window.__addCard('propre', 'Discussions', '800');
    /* SON GROUPE NOM + CATÉGORIE VIT DANS UNE DÉCORATION QUE LE NETTOYAGE
       RETIRE. La carte VIVANTE, elle, a bien son pseudo : elle passe donc
       toutes les gardes, et ne se révèle mauvaise qu'une fois clonée — le
       nettoyage emporte l'étui, et avec lui les deux lignes. C'est le seul
       décor qui éprouve vraiment le rattrapage : envelopper la seule ligne du
       pseudo ne suffit pas, le repli prendrait celle de la catégorie. */
    const p = [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.querySelector('a[href="/piege"]'));
    const groupe = p.querySelector('.side-nav-card__metadata');
    const etui = document.createElement('div');
    etui.className = 'iconContainer--secondary';
    groupe.replaceWith(etui);
    etui.appendChild(groupe);
    window.__cats = cats;
  }, { iso: h, cats: lot('g') });
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 2, 9000);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await attendre(page, () => window.tse.global.top(30).length > 0, 9000);
  await attendre(page,
    () => document.querySelectorAll('[data-tse-synthetic="true"]').length > 0, 9000);
  await wait(page, 900);
  const un = await page.evaluate(() => {
    const p = window.tse.panneau.rapport().page;
    return { modele: p.modele, sortie: p.sortie, essais: p.modeleEssais,
             fabriquees: document.querySelectorAll('[data-tse-synthetic="true"]').length };
  });
  ok('le classement s\'affiche malgré le modèle qui se défait au clonage',
     un.fabriquees >= 10 && un.sortie === 'ok', JSON.stringify(un));
  /* ET LE RAPPORT DIT QU'IL A FALLU S'Y REPRENDRE. Sans ce compteur, une passe
     qui essaie trois modèles avant d'en trouver un bon se lit exactement comme
     une passe qui réussit du premier coup — or ce n'est pas la même santé. */
  ok('…et le rapport dit qu\'un modèle s\'est défait avant celui qui a servi',
     un.essais === 1 && un.modele === 'neutre', JSON.stringify(un));

  /* LA CARTE PROPRE DISPARAÎT. Il ne reste que le piège — et la mémoire, qui
     ne doit PAS l'avoir enregistré. */
  await page.evaluate((cats) => {
    delete window.__fx.propre;
    [...document.querySelectorAll('.side-nav-card')]
      .filter(c => c.querySelector('a[href="/propre"]')).forEach(c => c.remove());
    window.__cats = cats;
    window.tse.rescan();
  }, lot('h'));
  await attendre(page,
    () => window.tse.global.top(30).some(r => r.login.startsWith('h')), 9000);
  await wait(page, 1500);
  const deux = await page.evaluate(() => {
    const p = window.tse.panneau.rapport().page;
    const faites = [...document.querySelectorAll('[data-tse-synthetic="true"]')];
    return { modele: p.modele, sortie: p.sortie, refus: p.modeleRefus,
             neufs: faites.filter(c => (c.dataset.tseLogin || '').startsWith('h')).length };
  });
  ok('…et la mémoire n\'a pas enregistré le modèle qui ne produit rien',
     deux.modele === 'memoire' && deux.sortie === 'ok', JSON.stringify(deux));
  ok('…si bien que le classement continue de suivre le palmarès',
     deux.neufs >= 10, JSON.stringify(deux));
  await page.close();
}

/* ═════════ TWITCH SORT LE PSEUDO DU GROUPE ═════════════════════════════
   Signalement : « le nom de streamer et sa catégorie sur Top Chaînes sont
   inversés ». Et pour la première fois, le rapport portait de quoi répondre
   sans deviner — le recensement ajouté la veille disait :

     crochet  9 / 10     ← le crochet d'automatisation est bien là
     p1       10         ← mais le groupe nom+catégorie n'a qu'UNE ligne

   Ce groupe en a toujours porté DEUX. Twitch en a sorti le pseudo : il vit
   désormais à côté, dans le bloc marqué, et `.side-nav-card__metadata` ne
   porte plus que la catégorie. Les neuf cartes qui gardent le crochet ne s'en
   ressentent pas ; la dixième — une carte décorée, celle qui sert justement de
   modèle — cherchait son pseudo DANS le groupe, et n'y trouvait que la
   catégorie. La carte fabriquée portait donc sa catégorie en guise de pseudo,
   et son pseudo en guise de catégorie.

   TROIS RÉDACTIONS ONT CHERCHÉ UN ATTRIBUT, et le terrain les a démenties
   l'une après l'autre. C'est L'ORDRE qui désigne le pseudo, et lui seul : il
   est la première ligne, dans toutes les dispositions observées. */
{
  titre('109. Twitch sort le pseudo du groupe, et les deux lignes s\'inversent');
  const page = await fresh();
  const h = new Date(Date.now() - 3600_000).toISOString();
  await page.evaluate((iso) => {
    window.__fx = { yugi: { id: 's1', createdAt: iso, viewers: 4700,
                            game: 'Rocket League', tags: [] } };
    window.__addCard('yugi', 'Rocket League', '4,7 k');
    const d = [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.querySelector('a[href="/yugi"]'));
    /* LE BALISAGE RELEVÉ SUR LE TERRAIN, et il tient en une ligne : le pseudo
       SORT de `.side-nav-card__metadata`, qui ne garde que la catégorie. */
    const boite = d.querySelector('[data-a-target="side-nav-card-metadata"]');
    const groupe = d.querySelector('.side-nav-card__metadata');
    const nom = d.querySelector('p[data-a-target="side-nav-title"]');
    // Carte DÉCORÉE : pas de crochet — c'est elle qui sert de modèle, et c'est
    // la seule des dix pour qui le repérage comptait.
    nom.removeAttribute('data-a-target');
    nom.setAttribute('title', 'Yugi');
    boite.insertBefore(nom, groupe);
    window.__cats = [{ name: 'WARDOGS', viewers: 400_000, streams:
      Array.from({ length: 30 }, (_, k) => ({ login: 'w' + k, viewers: 31_000 - k,
                                              tags: ['English'] })) }];
  }, h);
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 1, 9000);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await attendre(page, () => window.tse.global.top(30).length > 0, 9000);
  await wait(page, 1500);

  const etat = await page.evaluate(() => {
    const r = window.tse.panneau.rapport();
    const faites = [...document.querySelectorAll(
      '.side-nav-card[data-tse-synthetic="true"]')];
    return {
      fabriquees: faites.length, sortie: r.page.sortie,
      lignes: faites.slice(0, 1).map(c => [...c.querySelectorAll(
        '[data-a-target="side-nav-card-metadata"] p')].map(x => x.textContent.trim())),
      recense: r.lignes,
    };
  });
  ok('le classement s\'affiche quand Twitch a sorti le pseudo du groupe',
     etat.fabriquees >= 10 && etat.sortie === 'ok', JSON.stringify(etat));
  /* LE DÉFAUT SIGNALÉ, ET IL NE SE VOIT QUE LÀ. Compter les cartes ne dit rien :
     elles étaient toutes fabriquées, et toutes fausses. */
  ok('…et le pseudo est sur la PREMIÈRE ligne, la catégorie sur la seconde',
     JSON.stringify(etat.lignes[0] || []) === JSON.stringify(['w0', 'WARDOGS']),
     JSON.stringify(etat.lignes));
  /* ET LE RECENSEMENT NOMME LE DÉPLACEMENT. C'est lui qui a permis de répondre
     du premier coup ; il doit donc dire ce décor, sans quoi il ne servira pas
     la prochaine fois que Twitch déplacera quelque chose. */
  ok('…et le recensement dit que le pseudo a quitté le groupe',
     etat.recense.p1 === 1 && etat.recense.b2 === 1
     && etat.recense.nomHorsGroupe === 1 && etat.recense.sansNom === 0,
     JSON.stringify(etat.recense));
  await page.close();
}

/* ═════════ AUCUN ATTRIBUT NE DÉSIGNE LE PSEUDO ═════════════════════════
   Le scénario précédent reproduit le balisage du terrain, où les DEUX lignes
   portent un `title`. L'ancienne heuristique — « le pseudo est la ligne sans
   title » — y rend le même résultat que la règle d'ordre, par accident : elle
   ne trouve rien et retombe sur la première ligne. Elle survivait donc au banc.

   CELUI-CI LA DÉPARTAGE. Une carte où seul le PSEUDO porte un `title` — Twitch
   le pose dès qu'il tronque, et une catégorie courte n'en a pas besoin — et
   l'heuristique désigne alors la CATÉGORIE, avec aplomb. C'est la troisième
   fois qu'un attribut prétend désigner le pseudo et se trompe ; cette
   assertion existe pour qu'il n'y en ait pas de quatrième. */
{
  titre('110. Aucun attribut ne désigne le pseudo — seul l\'ordre le fait');
  const page = await fresh();
  const h = new Date(Date.now() - 3600_000).toISOString();
  await page.evaluate((iso) => {
    window.__fx = { zora: { id: 's1', createdAt: iso, viewers: 900,
                            game: 'Just Chatting', tags: [] } };
    window.__addCard('zora', 'Discussions', '900');
    const d = [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.querySelector('a[href="/zora"]'));
    const nom = d.querySelector('p[data-a-target="side-nav-title"]');
    nom.removeAttribute('data-a-target');   // carte décorée : pas de crochet
    nom.setAttribute('title', 'zora');      // le pseudo est titré…
    d.querySelector('p[title="Discussions"]').removeAttribute('title'); // …la catégorie non
    window.__cats = [{ name: 'c0', viewers: 400_000, streams:
      Array.from({ length: 30 }, (_, k) => ({ login: 'g' + k, viewers: 5000 - k,
                                              tags: ['English'] })) }];
  }, h);
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 1, 9000);
  await page.evaluate(() =>
    document.querySelector('#tse-mode-row [data-tse-mode="global"]').click());
  await attendre(page, () => window.tse.global.top(30).length > 0, 9000);
  await wait(page, 1500);

  const etat = await page.evaluate(() => {
    const faites = [...document.querySelectorAll(
      '.side-nav-card[data-tse-synthetic="true"]')];
    return {
      fabriquees: faites.length,
      lignes: faites.slice(0, 1).map(c => [...c.querySelectorAll(
        '[data-a-target="side-nav-card-metadata"] p')].map(x => x.textContent.trim())),
    };
  });
  ok('le classement s\'affiche quand seul le pseudo porte un title',
     etat.fabriquees >= 10, JSON.stringify(etat));
  ok('…et c\'est bien le pseudo qui est écrit sur la première ligne',
     JSON.stringify(etat.lignes[0] || []) === JSON.stringify(['g0', 'c0']),
     JSON.stringify(etat.lignes));
  await page.close();
}

/* ═════════ LE CSS S'ACCROCHAIT AU CROCHET DE TWITCH ════════════════════
   Signalement : « le symbole Subathon à côté du nom du streamer est collé à
   lui », et la précision qui donne la cause — « côté Top Chaînes, quand il n'y
   a qu'une chaîne suivie ».

   LE JS AVAIT APPRIS À SE PASSER DU CROCHET, PAS LA FEUILLE DE STYLE. Quatre
   règles visaient la ligne du pseudo par p[data-a-target=side-nav-title].
   La pastille se posait donc bien — `cardNameEl` retrouve la ligne — mais la
   règle qui met cette ligne en « display: flex » avec un « gap: 4px » ne
   s'appliquait pas. Sans gap, la pastille touche le nom.

   ET LE DÉFAUT VOYAGE AVEC LE CLONE. Une chaîne suivie unique et décorée sert
   de modèle à Top Chaînes ; ses trente cartes fabriquées n'ont donc pas le
   crochet non plus. C'est là que l'utilisateur l'a vu, et nulle part ailleurs.

   ON MESURE L'ÉCART, PAS LA FEUILLE DE STYLE. Lire « gap » sur l'élément dirait
   que la déclaration est là ; seule la géométrie dit que les deux boîtes ne se
   touchent pas. */
{
  titre('111. La pastille de subathon n\'est plus collée au pseudo');
  const page = await fresh();
  await page.evaluate(() => {
    window.__cats = [{ name: 'cSub', viewers: 9000,
                       streams: [{ login: 'mouseglobal', viewers: 8400 }] }];
    window.__fx = {
      mouseglobal: { id: 'g1',
        createdAt: new Date(Date.now() - 2277 * 60_000).toISOString(),
        viewers: 8400, game: 'Just Chatting', tags: [],
        title: '!MOUSEATHON DAY 10 AHHHH' },
      seule: { id: 'm',
        createdAt: new Date(Date.now() - 60 * 60_000).toISOString(),
        viewers: 1000, game: 'Just Chatting', tags: [], title: 'rien' },
    };
    window.__addCard('seule', 'Discussions', '1 k');
    /* L'UNIQUE CHAÎNE SUIVIE EST DÉCORÉE, donc sans crochet — c'est le décor
       du signalement, et c'est ce qui fait voyager le défaut sur les trente
       cartes fabriquées, qui sont ses clones. */
    const d = [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.querySelector('a[href="/seule"]'));
    d.querySelector('p[data-a-target="side-nav-title"]').removeAttribute('data-a-target');
  });
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 1, 9000);
  await page.evaluate(() => window.tse.global.on());
  await attendre(page, () => !!document.querySelector(
    '.side-nav-card[data-tse-synthetic="true"] .tse-subathon-jour'), 12000);
  await wait(page, 600);

  const etat = await page.evaluate(() => {
    const c = document.querySelector('.side-nav-card[data-tse-synthetic="true"][data-tse-subathon-day]');
    const puce = c && c.querySelector('.tse-subathon-jour');
    const nom  = c && c.querySelector('.tse-subathon-nom');
    if (!puce || !nom) return { manque: true };
    const rn = nom.getBoundingClientRect(), rp = puce.getBoundingClientRect();
    return {
      // L'écart VISUEL : du bord droit du nom au bord gauche de la pastille.
      ecart: Math.round(rp.left - rn.right),
      // Elles doivent rester sur la MÊME ligne : un espace obtenu en poussant
      // la pastille à l'étage du dessous ne serait pas une correction.
      memeLigne: Math.abs(Math.round(rp.top - rn.top)) <= 4,
      marquee: !!c.querySelector('p.tse-nom'),
    };
  });
  ok('la carte fabriquée porte la marque que le CSS suit, faute de crochet',
     etat.marquee === true, JSON.stringify(etat));
  ok('…et la pastille de subathon ne touche plus le pseudo',
     etat.ecart >= 3 && etat.ecart <= 12, JSON.stringify(etat));
  ok('…sans avoir été renvoyée à la ligne pour autant',
     etat.memeLigne === true, JSON.stringify(etat));
  await page.close();
}

/* ═════════ LA RÈGLE QUI POUVAIT EFFACER LE PSEUDO ══════════════════════
   Trouvée par l'audit, pas par un signalement — et c'est ce qui la rend digne
   d'un scénario. Twitch peut afficher une 3e ligne (le titre du direct) dans le
   bloc metadata ; on la masque en visant « tout frère suivant du groupe ».

   CETTE RÈGLE A ÉTÉ ÉCRITE QUAND LE GROUPE PORTAIT LES DEUX LIGNES. Tout ce
   qui le suivait était alors forcément un intrus. Depuis, Twitch a SORTI le
   pseudo du groupe — le recensement du rapport l'a montré en un nombre — et il
   se trouve qu'il le pose AVANT. Un frère précédent n'est pas atteint par « ~ » :
   la règle ne fait donc rien de mal aujourd'hui.

   LE JOUR OÙ L'ORDRE CHANGERAIT, elle effacerait le pseudo de TOUTES les
   cartes, d'un coup et sans un mot — le genre de panne qu'aucun compteur ne
   voit. Ce scénario joue ce jour-là. */
{
  titre('112. Le pseudo posé après le groupe n\'est pas effacé par la 3e ligne');
  const page = await fresh();
  const h = new Date(Date.now() - 3600_000).toISOString();
  await page.evaluate((iso) => {
    window.__fx = { apres: { id: 's1', createdAt: iso, viewers: 900,
                             game: 'Just Chatting', tags: [] } };
    window.__addCard('apres', 'Discussions', '900');
    const d = [...document.querySelectorAll('.side-nav-card')]
      .find(c => c.querySelector('a[href="/apres"]'));
    const boite = d.querySelector('[data-a-target="side-nav-card-metadata"]');
    const groupe = d.querySelector('.side-nav-card__metadata');
    const nom = d.querySelector('p[data-a-target="side-nav-title"]');
    nom.removeAttribute('data-a-target');
    // Le pseudo SORT du groupe, et se pose APRÈS lui — l'ordre inverse de
    // celui qu'on observe aujourd'hui.
    boite.appendChild(nom);
    /* ET LA 3e LIGNE DE TWITCH EST LÀ AUSSI, sans quoi le scénario ne
       vérifierait que la moitié : la règle doit continuer de la masquer. */
    const titreDirect = document.createElement('div');
    titreDirect.textContent = '[DROPS] rediffusion';
    boite.insertBefore(titreDirect, nom);
  }, h);
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 1, 9000);
  await wait(page, 600);

  const etat = await page.evaluate(() => {
    const c = [...document.querySelectorAll('.side-nav-card')]
      .find(x => x.dataset.tseLogin === 'apres');
    const nom = c && c.querySelector('p.tse-nom');
    const troisieme = c && [...c.querySelectorAll(
      '[data-a-target="side-nav-card-metadata"] > div')]
      .find(e => /rediffusion/.test(e.textContent || ''));
    const vu = (e) => !!e && getComputedStyle(e).display !== 'none'
                   && !!e.getBoundingClientRect().height;
    return { nomTrouve: !!nom, nomVisible: vu(nom),
             nomTexte: nom ? (nom.textContent || '').trim() : null,
             troisiemeVisible: vu(troisieme), troisiemeTrouvee: !!troisieme };
  });
  ok('le pseudo posé après le groupe garde sa marque',
     etat.nomTrouve === true && etat.nomTexte === 'apres', JSON.stringify(etat));
  ok('…et il reste visible, là où la règle l\'effaçait',
     etat.nomVisible === true, JSON.stringify(etat));
  ok('…tandis que la 3e ligne de Twitch, elle, est toujours masquée',
     etat.troisiemeTrouvee === true && etat.troisiemeVisible === false,
     JSON.stringify(etat));
  await page.close();
}

/* ═════════ LE BATTEMENT DU STREAM FRAIS ═══════════════════════════════
   Signalement : « peux-tu faire un clignotement plus visible pour les nouveaux
   streams qui sont violet ? On le remarque à peine. » Il allait de 0,7 à 1
   d'opacité — trente pour cent d'écart sur une barre de trois pixels, dans une
   colonne qui en compte quinze.

   ON MESURE L'AMPLITUDE, PAS LA DÉCLARATION. Lire « animation-name » sur
   l'élément dirait que le battement existe ; seul l'échantillonnage dit qu'on
   le VOIT. On parcourt donc un cycle entier — dont la durée est lue sur
   l'animation elle-même, jamais recopiée — et l'on regarde ce que l'opacité et
   la largeur rendue ont parcouru.

   CE SCÉNARIO A CHANGÉ DE PROMESSE EN 4.14. Il s'appelait « visible, et
   immobile sur demande » : un audit avait trouvé que cette barre était la
   seule animation à ignorer « prefers-reduced-motion », et on l'y avait
   arrêtée. Le bloc entier a depuis été retiré sur demande — les deux
   navigateurs ne rendaient pas la même chose, un seul relayant le réglage du
   système. Ce qui est éprouvé ici est donc le battement lui-même ; son
   INVARIANCE face à ce réglage est éprouvée plus bas, par le scénario qui
   mesure les deux régimes et exige qu'ils soient identiques. */
{
  titre('113. Le battement du stream frais — visible, et le même pour tous');
  const page = await fresh();
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.evaluate(() => {
    window.__fx = { neuf: { id: 's1', createdAt: new Date().toISOString(),
                            viewers: 900, game: 'Just Chatting', tags: [] } };
    window.__addCard('neuf', 'Discussions', '900');
  });
  await attendre(page,
    () => !!document.querySelector('.side-nav-card.tse-fresh'), 9000);

  const mesure = await page.evaluate(async () => {
    const c = document.querySelector('.side-nav-card.tse-fresh');
    /* LA DURÉE SE LIT SUR L'ANIMATION, ELLE NE SE RECOPIE PAS. Écrite en dur,
       elle mentirait dès que le cycle changerait de vitesse — et c'est
       précisément ce qui vient d'arriver. */
    const anim = document.getAnimations()
      .find(a => a.effect?.target === c && a.effect?.pseudoElement === '::before');
    if (!anim) return { sansAnimation: true };
    const duree = anim.effect.getComputedTiming().duration;
    const ops = [], largeurs = [];
    const debut = performance.now();
    while (performance.now() - debut < duree * 1.1) {
      const st = getComputedStyle(c, '::before');
      ops.push(parseFloat(st.opacity));
      // La largeur RENDUE : le scaleX ne change pas « width », il change ce
      // qu'on voit. Lire la matrice de transformation est la seule mesure qui
      // dise la même chose que l'œil.
      const m = new DOMMatrixReadOnly(st.transform);
      largeurs.push(parseFloat(st.width) * m.a);
      await new Promise(requestAnimationFrame);
    }
    return { duree, opMin: Math.min(...ops), opMax: Math.max(...ops),
             lMin: Math.min(...largeurs), lMax: Math.max(...largeurs) };
  });
  ok('la barre du stream frais bat vraiment, et l\'opacité parcourt un large écart',
     !mesure.sansAnimation && mesure.opMin <= 0.4 && mesure.opMax >= 0.95,
     JSON.stringify(mesure));
  /* L'ÉCART EST CE QUI REND LE SIGNAL VISIBLE, et l'ancien n'en avait pas
     assez : 0,7 → 1 est un rapport de 1,4 ; on en exige plus du double. */
  ok('…d\'un rapport d\'au moins deux et demi, là où l\'ancien battement valait 1,4',
     !mesure.sansAnimation && (mesure.opMax / mesure.opMin) >= 2.5,
     JSON.stringify(mesure));
  /* ET ELLE RESPIRE EN LARGEUR. Une barre de trois pixels qui ne fait que
     changer d'opacité reste une barre de trois pixels ; celle-ci en fait six
     à son sommet, sans provoquer la moindre mise en page. */
  ok('…et la barre s\'élargit visiblement au passage, sans changer sa « width »',
     !mesure.sansAnimation && (mesure.lMax - mesure.lMin) >= 2,
     JSON.stringify(mesure));

  /* ── MOUVEMENT RÉDUIT : L'EXTENSION NE S'EN MÊLE PLUS ───────────────────
     TROISIÈME TOUR DE CES DEUX ASSERTIONS, et le dernier. La 4.7 arrêtait ce
     battement net ; un utilisateur l'a signalé trois fois, et sa commande a
     fini par rendre « mouvementReduit: true, animations: 0 » — barre présente,
     immobile. La 4.9 a donc coupé le MOUVEMENT (scaleX) en gardant l'OPACITÉ,
     en s'appuyant sur la WCAG, qui définit l'animation de mouvement comme
     celle qui crée l'illusion d'un déplacement et exclut explicitement les
     changements d'opacité. Ces deux lignes mesuraient ce compromis.

     LE COMPROMIS LUI-MÊME EST TOMBÉ EN 4.14.0, et par la même voie : la
     mouture Firefox n'avait jamais reçu ce bloc, les deux ont été comparées
     côte à côte, et c'est celle SANS bloc qui a été retenue. Plus une seule
     règle sous « prefers-reduced-motion » dans tout le produit.

     ON NE SUPPRIME PAS POUR AUTANT : on retourne la mesure. Comparer le relevé
     réduit au relevé libre est plus exigeant que constater un arrêt, car
     l'égalité tombe dans les DEUX sens — si une règle réduite reparaissait,
     ou si le battement libre changeait sans que celui-ci suive. */
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await wait(page, 300);
  const calme = await page.evaluate(async () => {
    const c = document.querySelector('.side-nav-card.tse-fresh');
    const lire = () => { const st = getComputedStyle(c, '::before');
      const m = new DOMMatrixReadOnly(st.transform);
      return { o: parseFloat(st.opacity), l: parseFloat(st.width) * (m.a || 1),
               ombre: st.boxShadow }; };
    const anim = document.getAnimations()
      .find(a => a.effect?.target === c && a.effect?.pseudoElement === '::before');
    const duree = anim ? anim.effect.getComputedTiming().duration : 2000;
    let oMin = 9, oMax = -1, lMin = 9e9, lMax = -1, ombre = '';
    const fin = performance.now() + duree * 1.1;
    while (performance.now() < fin) {
      const v = lire();
      oMin = Math.min(oMin, v.o); oMax = Math.max(oMax, v.o);
      lMin = Math.min(lMin, v.l); lMax = Math.max(lMax, v.l); ombre = v.ombre;
      await new Promise(requestAnimationFrame);
    }
    return { anims: anim ? 1 : 0, duree, oMin, oMax,
             lMin: +lMin.toFixed(2), lMax: +lMax.toFixed(2), ombre };
  });
  const memeCadence = calme.anims === 1 && calme.duree === mesure.duree;
  ok('mouvement réduit : le battement bat à la MÊME cadence qu\'en mouvement libre',
     memeCadence, JSON.stringify({ libre: mesure.duree, calme: calme.duree,
                                   anims: calme.anims }));
  /* Et de la même amplitude, en opacité COMME EN LARGEUR : c'est la largeur
     qui portait tout l'écart entre les deux moutures, puisque c'est elle que
     le bloc supprimé figeait. Un dixième de pixel de tolérance, pour le seul
     échantillonnage par rAF. */
  ok('…et de la même amplitude, l\'élargissement de la barre y compris',
     Math.abs((calme.lMax - calme.lMin) - (mesure.lMax - mesure.lMin)) < 0.15
     && calme.lMax - calme.lMin >= 2
     && Math.abs(calme.oMin - mesure.opMin) < 0.06
     && Math.abs(calme.oMax - mesure.opMax) < 0.06
     && calme.ombre !== 'none',
     JSON.stringify({ largeurs: [[mesure.lMin, mesure.lMax], [calme.lMin, calme.lMax]],
                      opacites: [[mesure.opMin, mesure.opMax], [calme.oMin, calme.oMax]] }));
  await page.close();
}

/* ═════════ UNE GARANTIE ÉCRITE QUI NE TENAIT PAS ═══════════════════════
   Trouvée par l'audit, en croisant chaque @keyframes du produit avec le bloc
   « prefers-reduced-motion ». Les deux arcs-en-ciel du subathon — la pastille
   sur la carte, le badge dans l'aperçu — continuaient de tourner chez qui
   demande explicitement l'immobilité, pour deux raisons différentes :

     — la PASTILLE est déclarée sur trois classes, l'annulation sur une seule :
       la spécificité l'emportait ;
     — le BADGE est déclaré plus bas dans la feuille, à spécificité égale :
       l'ordre l'emportait.

   CE N'EST PAS UN DÉTAIL DE STYLE. Ces deux animations changent de teinte huit
   fois par seconde et demie, soit 5,3 fois par seconde, et le seul réglage par
   lequel un utilisateur peut demander qu'elles se calment ne les atteignait
   pas. La garantie était écrite, et elle ne tenait pas.

   CE QUE LE RÉGLAGE VAUT A CHANGÉ DEUX FOIS. La 4.9 a remplacé l'arrêt par un
   RALENTISSEMENT à huit secondes le tour ; la 4.14.0 a retiré le bloc entier,
   après comparaison des moutures Chrome et Firefox — cette dernière ne l'avait
   jamais reçu, et c'est elle qui a été jugée juste. Il n'existe plus une seule
   règle « prefers-reduced-motion » dans le produit.

   LE DÉFAUT D'ORIGINE RESTE POURTANT COUVERT, et mieux qu'avant. On ne mesure
   plus « ralenti », on mesure l'ÉGALITÉ entre les deux relevés : si une règle
   réduite revenait — par spécificité, par ordre de feuille, ou écrite exprès —
   les deux cadences divergeraient et ces lignes tomberaient. C'est exactement
   la bascule que l'audit d'alors cherchait, prise par l'autre bout. */
{
  titre('114. Mouvement réduit — les arcs-en-ciel tournent comme partout ailleurs');
  const page = await fresh();
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.evaluate(() => {
    window.__fx = { thon: { id: 's1',
      createdAt: new Date(Date.now() - 2277 * 60_000).toISOString(),
      viewers: 900, game: 'Just Chatting', tags: [],
      title: '!SUBATHON DAY 10 ahhh' } };
    window.__addCard('thon', 'Discussions', '900');
  });
  await attendre(page, () => !!document.querySelector('.tse-subathon-jour'), 12000);
  await hoverLogin(page, 'thon');
  await attendre(page,
    () => !!document.querySelector('.tse-preview__badge--subathon'), 8000);

  const lire = () => page.evaluate(() => {
    const p = document.querySelector('.tse-subathon-jour');
    const b = document.querySelector('.tse-preview__badge--subathon');
    const st = (e) => e ? getComputedStyle(e) : null;
    /* LA DURÉE SE LIT SUR LE STYLE CALCULÉ, jamais recopiée : c'est le seul
       nombre qui distingue « ralenti » de « à pleine vitesse », et le
       recopier ferait mesurer au banc sa propre copie. */
    const sec = (e) => { const d = st(e)?.animationDuration || '0s';
      return d.endsWith('ms') ? parseFloat(d) / 1000 : parseFloat(d); };
    return { puceAnim: st(p)?.animationName, badgeAnim: st(b)?.animationName,
             puceDuree: sec(p), badgeDuree: sec(b),
             puceCoul: st(p)?.color, badgeCoul: st(b)?.color,
             puceTexte: (p?.textContent || '').trim(),
             anims: document.getAnimations().length };
  });
  const a = await lire();
  /* UNE DEMI-PÉRIODE, PAS UNE PÉRIODE ENTIÈRE. L'attente valait 1 500 ms du
     temps où le cycle réduit durait huit secondes ; à pleine cadence, c'est
     EXACTEMENT sa période, et les deux échantillons retombent sur la même
     teinte. Une attente commensurable au cycle qu'elle mesure ne mesure rien. */
  await wait(page, 500);
  const b = await lire();

  ok('mouvement réduit : les deux arcs-en-ciel tournent encore',
     a.puceAnim !== 'none' && a.badgeAnim !== 'none', JSON.stringify(a));
  /* LA MESURE QUI COMPTE. Une durée lue ne dit pas qu'on voie quelque chose :
     c'est la COULEUR qui le dit. Un tiers de tour suffit largement. */
  ok('…et leur couleur dérive pour de bon',
     a.puceCoul !== b.puceCoul && a.badgeCoul !== b.badgeCoul,
     JSON.stringify({ a: [a.puceCoul, a.badgeCoul], b: [b.puceCoul, b.badgeCoul] }));
  /* ON NE TOUCHE PAS AU MOUVEMENT, ON NE PERD PAS L'INFORMATION NON PLUS. */
  ok('…et la pastille garde sa marque, jour compris',
     /\d/.test(a.puceTexte), JSON.stringify(a.puceTexte));

  /* ── ET LA MÊME CHOSE, AU CENTIÈME PRÈS, QUAND LE MOUVEMENT EST AUTORISÉ ─
     C'est ici que le défaut d'origine serait repris : une règle réduite qui
     reparaîtrait, par spécificité ou par ordre de feuille, ferait diverger ces
     deux durées. L'égalité stricte est le contrat. */
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await wait(page, 200);
  const c1 = await lire();
  await wait(page, 500);
  const c2 = await lire();
  ok('mouvement autorisé : exactement la même cadence, à la milliseconde',
     c1.puceDuree === a.puceDuree && c1.badgeDuree === a.badgeDuree,
     JSON.stringify({ reduit: [a.puceDuree, a.badgeDuree],
                      libre: [c1.puceDuree, c1.badgeDuree] }));
  ok('…et c\'est bien une cadence vive des deux côtés, pas deux fois l\'immobilité',
     c1.puceAnim !== 'none' && c1.badgeAnim !== 'none'
     && c1.puceDuree > 0 && c1.puceDuree <= 2 && c1.badgeDuree <= 2
     && (c1.puceCoul !== c2.puceCoul || c1.badgeCoul !== c2.badgeCoul),
     JSON.stringify({ durees: [c1.puceDuree, c1.badgeDuree],
                      couleurs: [c1.puceCoul, c2.puceCoul] }));
  await page.close();
}

/* ═════════ LES DEUX THÈMES DE TWITCH ═══════════════════════════════════
   « Il existe un thème clair sur Twitch. J'aimerais que tu adaptes
   automatiquement entièrement l'extension. » Cette feuille n'en connaissait
   qu'un : ses surfaces étaient écrites en dur pour le sombre, si bien qu'en
   clair l'extension posait des panneaux noirs au milieu d'une page blanche.

   CE QUI SE MESURE ICI N'EST PAS L'ASPECT, C'EST LA LISIBILITÉ. Une capture
   ne prouve rien — elle montre ce qu'on veut y voir — et « adapté » n'est pas
   une opinion : c'est un rapport de contraste. On relève donc, sur chaque
   texte que l'extension dessine, le contraste contre son fond RÉELLEMENT
   composé — les badges sont translucides, leur fond n'est pas la surface du
   panneau mais le mélange des deux — et l'on exige le seuil AA dans les deux
   thèmes.

   LE HARNAIS POSE LES VARIABLES DE TWITCH, sans quoi ces nombres ne voudraient
   rien dire : la première rédaction relevait du texte clair « sur du gris 153 »
   — le fond du harnais — et déclarait tout bon. C'est en donnant à la page
   les deux palettes de Twitch que trois défauts sont apparus, dont un qui
   datait du thème SOMBRE. */
{
  titre('115. Le thème clair — chaque texte tient le seuil, dans les deux thèmes');
  const page = await fresh();
  await page.evaluate(() => {
    window.__fx = { alpha: { id: 'a', createdAt: new Date(Date.now() - 3600e3).toISOString(),
                             viewers: 900, game: 'Just Chatting', tags: [] } };
    window.__addCard('alpha', 'Discussions', '900');
  });
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 1, 9000);
  await hoverLogin(page, 'alpha');
  await attendre(page,
    () => !!document.querySelector('.tse-preview[data-tse-visible="true"]'), 8000);
  /* UN BADGE DE CHAQUE ESPÈCE, POSÉ À LA MAIN. Les réunir tous dans un même
     aperçu ne se produit pas dans la vie ; c'est pourtant la seule façon de
     les mesurer d'un coup, et chacun est mesuré contre SON propre fond. */
  await page.evaluate(() => {
    const z = document.querySelector('.tse-preview__badges')
           || document.querySelector('.tse-preview__body');
    for (const m of ['hype', 'discount', 'costream', 'squad', 'sponsor', 'sub',
                     'exsub', 'ccl', 'switch', 'subathon', '']) {
      const b = document.createElement('span');
      b.className = 'tse-preview__badge' + (m ? ' tse-preview__badge--' + m : '');
      b.textContent = 'Aa'; z.appendChild(b);
    }
  });
  await wait(page, 200);

  const mesurer = () => page.evaluate(() => {
    const lin = (c) => { c /= 255; return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; };
    const L = (r) => 0.2126 * lin(r[0]) + 0.7152 * lin(r[1]) + 0.0722 * lin(r[2]);
    const rgb = (s) => { const m = /(\d+(?:\.\d+)?)[,\s]+(\d+(?:\.\d+)?)[,\s]+(\d+(?:\.\d+)?)(?:[,\s/]+([\d.]+))?/.exec(s || '');
      return m ? [+m[1], +m[2], +m[3], m[4] === undefined ? 1 : +m[4]] : null; };
    const over = (f, b) => f[3] >= 1 ? f : [0, 1, 2].map(i => f[i] * f[3] + b[i] * (1 - f[3]));
    const ratio = (a, b) => { const la = L(a), lb = L(b);
      return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05); };
    /* LE FOND EFFECTIF SE REMONTE : un badge translucide sur un panneau opaque
       ne se juge pas contre sa propre déclaration de fond. */
    const fondDe = (el) => {
      let e = el; const pile = [];
      while (e) { const c = rgb(getComputedStyle(e).backgroundColor);
        if (c && c[3] > 0) pile.push(c);
        if (c && c[3] >= 1) break; e = e.parentElement; }
      let f = [255, 255, 255];
      for (let i = pile.length - 1; i >= 0; i--) f = over(pile[i], f);
      return f;
    };
    const lire = (sel) => { const e = document.querySelector(sel); if (!e) return null;
      const fond = fondDe(e);
      return { sel, c: +ratio(over(rgb(getComputedStyle(e).color), fond), fond).toFixed(2) }; };
    const badges = [...document.querySelectorAll('.tse-preview__badge')]
      .map(b => '.' + [...b.classList].filter(c => c.startsWith('tse-preview__badge')).join('.'));
    /* L'ENCRE : UNE MESURE DE SENS, PAS DE VALEUR. Une trentaine de surfaces
       de cette feuille sont posées « à l'encre » — un lavis dont seules les
       composantes basculent. Vérifier la variable, c'est vérifier une
       déclaration ; ce qui compte est que le lavis ÉCLAIRCISSE en sombre et
       ASSOMBRISSE en clair. Le badge neutre est exactement cela : un fond
       d'encre à 8 % sur le panneau, et rien d'autre. */
    const neutre = [...document.querySelectorAll('.tse-preview__badge')]
      .find(b => ![...b.classList].some(c => c.startsWith('tse-preview__badge--')));
    const panneau = rgb(getComputedStyle(
      (neutre || document.body).closest('.tse-preview') || document.body).backgroundColor)
      || [255, 255, 255];
    const lavis = neutre ? over(rgb(getComputedStyle(neutre).backgroundColor), panneau) : null;
    return {
      theme: document.documentElement.getAttribute('data-tse-theme'),
      rapport: window.tse.panneau.rapport().page.theme,
      encreEclaircit: lavis ? L(lavis) > L(panneau) : null,
      cibles: ['.tse-dd-btn', '.tse-sort-toggle', '.tse-mode-tab[aria-pressed="false"]',
               '.tse-viewers', '.tse-uptime', '.tse-preview__title',
               ...new Set(badges)].map(lire).filter(Boolean),
    };
  });

  const sombre = await mesurer();
  ok('le thème sombre est reconnu, posé sur la racine, et dit par le rapport',
     sombre.theme === 'dark' && sombre.rapport === 'dark', JSON.stringify(sombre.theme));
  ok('…et chacun des textes de l\'extension y tient le seuil AA',
     sombre.cibles.length >= 15 && sombre.cibles.every(c => c.c >= 4.5),
     JSON.stringify(sombre.cibles.filter(c => c.c < 4.5)));

  /* LE BASCULEMENT SE FAIT SANS RECHARGEMENT — c'est un interrupteur du menu
     de Twitch, et la page ne bouge pas autour. Un thème qui n'arriverait qu'au
     prochain survol laisserait l'aperçu noir sur une page devenue blanche. */
  await page.evaluate(() => document.documentElement.setAttribute('data-a-theme', 'light'));
  await wait(page, 300);
  const clair = await mesurer();
  ok('le passage en clair est vu sans rechargement',
     clair.theme === 'light' && clair.rapport === 'light', JSON.stringify(clair.theme));
  ok('…et chacun des textes y tient le seuil AA lui aussi',
     clair.cibles.length >= 15 && clair.cibles.every(c => c.c >= 4.5),
     JSON.stringify(clair.cibles.filter(c => c.c < 4.5)));
  /* ET L'ENCRE A CHANGÉ DE SENS. Sans cette assertion, une encre restée
     blanche passait tout le reste du scénario : les textes tiennent leur
     seuil, et trente lavis deviennent invisibles sans qu'un seul contraste
     bouge. Le mutant qui la fige a survécu à la première rédaction. */
  ok('…et l\'encre a changé de sens : elle éclaircit en sombre, elle assombrit en clair',
     sombre.encreEclaircit === true && clair.encreEclaircit === false,
     JSON.stringify({ sombre: sombre.encreEclaircit, clair: clair.encreEclaircit }));

  /* L'ARC-EN-CIEL SE MESURE SUR TOUT SON TOUR. Sa couleur de repos ne dit rien
     des sept autres : la première rédaction n'avait vérifié qu'elle, et la
     sonde a saisi le badge en plein cycle à 4,45:1 — sous le seuil, un
     huitième du temps. On échantillonne donc le tour entier. */
  const pire = await page.evaluate(async () => {
    const lin = (c) => { c /= 255; return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; };
    const L = (r) => 0.2126 * lin(r[0]) + 0.7152 * lin(r[1]) + 0.0722 * lin(r[2]);
    const rgb = (s) => { const m = /(\d+(?:\.\d+)?)[,\s]+(\d+(?:\.\d+)?)[,\s]+(\d+(?:\.\d+)?)(?:[,\s/]+([\d.]+))?/.exec(s || '');
      return m ? [+m[1], +m[2], +m[3], m[4] === undefined ? 1 : +m[4]] : null; };
    const over = (f, b) => f[3] >= 1 ? f : [0, 1, 2].map(i => f[i] * f[3] + b[i] * (1 - f[3]));
    const ratio = (a, b) => { const la = L(a), lb = L(b);
      return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05); };
    const e = document.querySelector('.tse-preview__badge--subathon');
    const panneau = rgb(getComputedStyle(e.closest('.tse-preview')).backgroundColor) || [255, 255, 255];
    const anim = document.getAnimations().find(a => a.effect?.target === e);
    const duree = anim ? anim.effect.getComputedTiming().duration : 1500;
    let pire = 99;
    const fin = performance.now() + duree * 1.1;
    while (performance.now() < fin) {
      const st = getComputedStyle(e);
      const fond = over(rgb(st.backgroundColor), panneau);
      pire = Math.min(pire, ratio(over(rgb(st.color), fond), fond));
      await new Promise(requestAnimationFrame);
    }
    return +pire.toFixed(2);
  });
  ok('…et l\'arc-en-ciel du subathon tient le seuil sur TOUT son tour, pas seulement au repos',
     pire >= 4.5, `pire image : ${pire}:1`);

  /* ── UN TEXTE PEINT PAR UN DÉGRADÉ ÉCHAPPE À TOUTE LECTURE DE COULEUR ────
     C'EST LE TROU QUI A LAISSÉ PASSER LE RECTANGLE BLANC. Tout ce scénario
     mesure « color ». Le pseudo d'une chaîne abonnée n'en a pas : il est
     rempli par un dégradé découpé au texte, et son « -webkit-text-fill-color »
     vaut « transparent ». Le relevé le lisait donc comme un texte invisible et
     l'écartait, dans les deux thèmes — y compris en sombre, où il est parfait.
     Le contrôle passait en ne regardant rien.

     LA MÉTHODE EXISTAIT DÉJÀ, quatre lignes plus haut : l'arc-en-ciel du
     subathon se vérifie sur TOUS ses arrêts, parce qu'aucun instantané ne
     suffit. On l'applique ici. Les arrêts se lisent sur le style CALCULÉ —
     jamais recopiés de la feuille — et chacun doit tenir le seuil sur le fond
     réellement composé sous lui.

     ON ÉPROUVE LES DEUX CHEMINS DU CLAIR : celui que Twitch donne, et celui
     que le réglage force. La 4.8 avait repeint toute la feuille et laissé l'or
     derrière ; le forcé a simplement rendu le défaut visible plus tôt. */
  const orAbonne = async () => page.evaluate(() => {
    const c = document.querySelector('.side-nav-card');
    if (!c) return null;
    c.classList.add('tse-sub');
    c.querySelector('p[title]')?.classList.add('tse-sub-cat');
    const lum = (v) => { const t = v.map((x) => { const y = x / 255;
      return y <= 0.03928 ? y / 12.92 : Math.pow((y + 0.055) / 1.055, 2.4); });
      return 0.2126 * t[0] + 0.7152 * t[1] + 0.0722 * t[2]; };
    const rap = (a, d) => { const x = lum(a), y = lum(d);
      return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
    const fondOpaque = (e) => { let n = e;
      while (n) { const m = /rgba?\((\d+), (\d+), (\d+)(?:, ([\d.]+))?\)/
          .exec(getComputedStyle(n).backgroundColor);
        if (m && (m[4] === undefined || +m[4] > 0.5)) return [+m[1], +m[2], +m[3]];
        n = n.parentElement; }
      return [255, 255, 255]; };
    const mesure = (sel) => { const e = document.querySelector(sel); if (!e) return null;
      const st = getComputedStyle(e);
      const arrets = [...(st.backgroundImage || '').matchAll(/rgba?\((\d+), (\d+), (\d+)/g)]
        .map((m) => [+m[1], +m[2], +m[3]]);
      if (!arrets.length) return null;
      const d = fondOpaque(e);
      return { n: arrets.length,
               pire: +Math.min(...arrets.map((a) => rap(a, d))).toFixed(2) }; };
    return { nom: mesure('.side-nav-card.tse-sub p.tse-nom'),
             cat: mesure('.side-nav-card.tse-sub .tse-sub-cat') };
  });

  await page.evaluate(() => { document.documentElement.setAttribute('data-a-theme', 'light');
                              window.tse.options.remettre(); });
  await wait(page, 300);
  const orClair = await orAbonne();
  await page.evaluate(() => { document.documentElement.setAttribute('data-a-theme', 'dark');
                              window.tse.options.poser('theme', 'light'); });
  await wait(page, 300);
  const orForce = await orAbonne();
  await page.evaluate(() => { window.tse.options.remettre(); });
  await wait(page, 300);
  const orSombre = await orAbonne();

  /* Le nombre d'arrêts entre au contrat : un dégradé réduit à une seule
     couleur tiendrait n'importe quel seuil sans plus rien vouloir dire. */
  ok('le pseudo d\'une chaîne abonnée est bien peint par un dégradé à plusieurs arrêts',
     !!orSombre && !!orSombre.nom && orSombre.nom.n >= 4
     && !!orSombre.cat && orSombre.cat.n >= 4, JSON.stringify(orSombre));
  ok('…et chacun de ses arrêts tient le seuil AA en thème sombre',
     !!orSombre && orSombre.nom.pire >= 4.5 && orSombre.cat.pire >= 4.5,
     JSON.stringify(orSombre));
  ok('…comme en clair donné par Twitch, où il valait 1,08:1',
     !!orClair && !!orClair.nom && orClair.nom.pire >= 4.5
     && !!orClair.cat && orClair.cat.pire >= 4.5, JSON.stringify(orClair));
  ok('…et en clair FORCÉ, sur le fond que le réglage impose',
     !!orForce && !!orForce.nom && orForce.nom.pire >= 4.5
     && !!orForce.cat && orForce.cat.pire >= 4.5, JSON.stringify(orForce));
  await page.close();
}

/* ═════════ FAIRE DIRE À LA PAGE CE QU'ON NE PEUT PAS Y VOIR ════════════
   « Toujours pas de clignotement côté Chrome » est arrivé deux fois, et j'y ai
   répondu deux fois par une hypothèse — la seconde étant que le navigateur
   rapportait « mouvement réduit ». Aucune des deux n'était vérifiable d'ici :
   cette machine ne joint pas Twitch, et un battement ne se prouve pas par un
   raisonnement.

   QUATRE NOMBRES REMPLACENT LES DEUX HYPOTHÈSES. Le rapport dit désormais
   combien de cartes sont fraîches, combien d'animations portent la barre, dans
   quel état elles sont, et si l'utilisateur a demandé l'immobilité. Chacune de
   ces quatre réponses ferme une branche entière de l'enquête, et aucune ne
   demande à être devinée.

   ET UNE COMMANDE POUR L'AMPLITUDE, parce qu'un instantané ne suffit pas : une
   animation peut tourner et ne rien montrer. « await tse.battement() » relève
   le rendu image par image sur un cycle entier — durée lue sur l'animation,
   jamais recopiée — et rend l'écart d'opacité réellement parcouru.

   CE SCÉNARIO ÉPROUVE LE DIAGNOSTIC LUI-MÊME, dans ses trois situations. Un
   diagnostic qu'on ne mesure pas ment aussi bien qu'un autre — ce dépôt en a
   livré deux qui regardaient à côté, et c'est un audit qui les a trouvés. */
{
  titre('116. Le battement se constate — le rapport et la commande le disent');
  const page = await fresh();
  await page.emulateMedia({ reducedMotion: 'no-preference' });

  /* ── SITUATION 1 : AUCUNE CHAÎNE FRAÎCHE ────────────────────────────────
     C'est la réponse la plus banale, et celle qu'aucune hypothèse n'aurait
     produite : il n'y a rien à voir parce qu'il n'y a rien à montrer. */
  await page.evaluate(() => {
    window.__fx = { vieux: { id: 'v', createdAt: new Date(Date.now() - 6 * 3600e3).toISOString(),
                             viewers: 900, game: 'Just Chatting', tags: [] } };
    window.__addCard('vieux', 'Discussions', '900');
  });
  await attendre(page,
    () => document.querySelectorAll('[data-tse-viewers]').length === 1, 9000);
  const rien = await page.evaluate(async () => ({
    rapport: window.tse.panneau.rapport().page.battement,
    mesure: await window.tse.battement(),
  }));
  ok('sans chaîne fraîche, le rapport le dit et la commande le nomme',
     rien.rapport.fraiches === 0 && rien.rapport.animations === 0
     && /aucune chaîne/.test(rien.mesure.verdict),
     JSON.stringify(rien));

  /* ── SITUATION 2 : LE BATTEMENT TOURNE ──────────────────────────────────
     Le cas nominal. On exige que la commande mesure une AMPLITUDE, pas
     seulement qu'elle trouve une animation. */
  await page.evaluate(() => {
    window.__fx.neuf = { id: 'n', createdAt: new Date().toISOString(),
                         viewers: 800, game: 'Just Chatting', tags: [] };
    window.__addCard('neuf', 'Discussions', '800');
  });
  await attendre(page,
    () => !!document.querySelector('.side-nav-card.tse-fresh'), 9000);
  const vivant = await page.evaluate(async () => ({
    rapport: window.tse.panneau.rapport().page.battement,
    mesure: await window.tse.battement(),
  }));
  ok('quand une chaîne est fraîche, le rapport compte la carte et l\'animation',
     vivant.rapport.fraiches >= 1 && vivant.rapport.animations >= 1
     && vivant.rapport.etat === 'running', JSON.stringify(vivant.rapport));
  ok('…et la commande mesure l\'amplitude réellement parcourue',
     vivant.mesure.rapport >= 2.5 && vivant.mesure.opaciteMin <= 0.4
     && vivant.mesure.largeurMax - vivant.mesure.largeurMin >= 2,
     JSON.stringify(vivant.mesure));
  ok('…et son verdict le dit en toutes lettres',
     /le battement est bien là/.test(vivant.mesure.verdict), vivant.mesure.verdict);

  /* ── SITUATION 3 : ELLE TOURNE, ET ON NE VOIT RIEN ──────────────────────
     La branche pour laquelle cette commande existe. Une animation peut être
     présente, en cours, à la bonne durée — et parfaitement invisible, parce
     que son amplitude est plate. C'est exactement ce qu'un rapport
     d'instantané ne peut PAS dire, et c'est le défaut que l'utilisateur
     décrit : « ça ne clignote pas », sans que rien ne paraisse cassé.

     ON APLATIT LES ARRÊTS SANS TOUCHER À L'ANIMATION : même nom, même durée,
     même état « running ». Seule l'amplitude disparaît. */
  await page.evaluate(() => {
    const st = document.createElement('style');
    st.id = 'aplatir';
    st.textContent = '@keyframes tse-fresh-pulse {'
      + '0%, 100% { opacity: 1; transform: scaleX(1); }'
      + '50% { opacity: 1; transform: scaleX(1); } }';
    document.head.appendChild(st);
  });
  await wait(page, 200);
  const plat = await page.evaluate(async () => ({
    rapport: window.tse.panneau.rapport().page.battement,
    mesure: await window.tse.battement(),
  }));
  ok('une animation qui tourne mais ne montre rien est NOMMÉE comme telle',
     plat.rapport.etat === 'running' && /AMPLITUDE PLATE/.test(plat.mesure.verdict),
     JSON.stringify({ etat: plat.rapport.etat, verdict: plat.mesure.verdict,
                      rapport: plat.mesure.rapport }));
  await page.evaluate(() => document.getElementById('aplatir').remove());
  await wait(page, 200);

  /* ── SITUATION 4 : LE RÉGLAGE SYSTÈME NE CHANGE PLUS RIEN ────────────────
     CETTE SITUATION A CHANGÉ DE SENS EN 4.14, et l'assertion avec elle. Le
     bloc « prefers-reduced-motion » a été retiré sur demande : « retire le CSS
     qui réduit les animations sur Chrome ; sur Firefox il n'y est pas et c'est
     parfait ». Les deux navigateurs ne rendaient pas la même chose parce qu'un
     seul relayait le réglage du système.

     ON NE SE CONTENTE PAS DE RETIRER L'ANCIENNE ASSERTION : on exige
     l'INVARIANCE, qui est plus forte. La barre doit battre EXACTEMENT pareil
     que le système demande moins de mouvement ou non — sans quoi il resterait
     quelque part une règle qu'on croirait partie. */
  const avant = await page.evaluate(async () => await window.tse.battement());
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await wait(page, 300);
  const calme = await page.evaluate(async () => ({
    rapport: window.tse.panneau.rapport().page,
    mesure: await window.tse.battement(),
  }));
  ok('le navigateur dit bien que le mouvement réduit est demandé',
     calme.rapport.mouvementReduit === true && calme.rapport.battement.animations === 1,
     JSON.stringify(calme.rapport.battement));
  /* L'ASSERTION QUI TIENT LE RETRAIT : même verdict, même amplitude. Remettre
     le bloc de mouvement réduit fait diverger les deux et la fait tomber. */
  ok('…et la barre bat exactement comme sans ce réglage',
     calme.mesure.verdict === avant.verdict
     && Math.abs(calme.mesure.rapport - avant.rapport) < 0.25,
     JSON.stringify({ avant: avant.verdict, avantRapport: avant.rapport,
                      apres: calme.mesure.verdict, apresRapport: calme.mesure.rapport }));
  await page.close();
}

/* ═════════ LES RÉGLAGES — LA TABLE, ET CE QU'ELLE STOCKE ═════════════════
   Vingt-deux réglages font quelques milliards de configurations, et aucun banc
   ne les couvre. Ce qu'on peut éprouver, et qui vaut plus qu'un échantillon de
   combinaisons, ce sont les INVARIANTS de la mécanique :

     — un défaut de « choix » qui ne serait pas dans sa propre liste rendrait le
       réglage impossible à poser, sans que rien ne le dise ;
     — une valeur refusée doit laisser l'ancienne en place, pas un trou ;
     — le stockage ne doit contenir QUE des écarts, et disparaître quand il n'y
       en a plus. C'est ce qui permet à un défaut de changer un jour sans
       s'imposer à ceux qui l'avaient touché.

   LE DERNIER EST LE PLUS IMPORTANT DES TROIS et il se vérifie sur la CLÉ, pas
   sur le comportement : une clé absente est la preuve qu'aucun défaut n'a été
   gravé dans le navigateur de personne. */
{
  titre('117. Les réglages — la table, ses défauts, et ce que le stockage retient');
  const page = await fresh();
  await wait(page, 300);

  const table = await page.evaluate(() => {
    const defs = window.tse.panneau('options').defs;
    const defauts = window.tse.options.defauts();
    const horsListe = Object.entries(defs)
      .filter(([, d]) => d.type === 'choix')
      .filter(([id, d]) => !d.valeurs.includes(defauts[id]))
      .map(([id]) => id);
    const jeuxNonVides = Object.entries(defs)
      .filter(([, d]) => d.type === 'jeu')
      .filter(([id]) => defauts[id].length !== 0)
      .map(([id]) => id);
    return { n: Object.keys(defs).length, horsListe, jeuxNonVides,
             cle: localStorage.getItem('tse:options') };
  });
  ok('la table porte ses dix-neuf réglages', table.n === 19, String(table.n));
  /* CELUI-CI A UNE CIBLE PRÉCISE : trois défauts sont lus dans CFG plutôt que
     recopiés — apercuQualite, abosPeriode et topN. Changer une de ces trois
     constantes sans toucher à la liste des valeurs permises rendrait le
     réglage impossible à poser, et l'interface l'afficherait pourtant. */
  ok('…et chaque défaut de choix appartient à sa propre liste de valeurs',
     table.horsListe.length === 0, table.horsListe.join(', '));
  /* CELLE-CI SE LIT SUR LE FICHIER SOURCE, et c'est le fond du sujet : la
     constante de production vaut six heures, mais tests/build.mjs la réécrit à
     quatre secondes pour que le relevé des abonnements soit éprouvable. La
     page chargée par le banc ne peut donc PAS répondre à la question posée
     ici. Le premier jet dérivait le défaut du réglage de cette constante ; le
     banc a montré du premier coup que le défaut devenait 0,0011 — absent de sa
     propre liste, impossible à poser, introuvable dans le menu.

     LES DEUX SONT DONC SÉPARÉS, et cette assertion garde la seule chose qui
     les relie encore : en production, ils disent la même durée. Changer la
     constante pour huit heures sans toucher au réglage ferait diverger ce que
     le menu affiche de ce que le produit attend. */
  {
    const src = readFileSync(join(ICI, '..', 'content.js'), 'utf8');
    const ttl = /SUBS_PAGE_TTL:\s*(\d+) \* (\d+) \* ([\d_]+)/.exec(src);
    const def = /abosPeriode:\s*\{ defaut: (\d+)/.exec(src);
    const heures = ttl
      ? Number(ttl[1]) * Number(ttl[2]) * Number(ttl[3].replace(/_/g, '')) / 3_600_000
      : null;
    ok('…et le défaut des heures dit la même durée que la constante de production',
       heures !== null && def !== null && heures === Number(def[1]),
       JSON.stringify({ heures, defaut: def && def[1] }));
  }
  ok('…les jeux partent vides, c\'est-à-dire tout actif',
     table.jeuxNonVides.length === 0, table.jeuxNonVides.join(', '));
  ok('…et rien n\'est écrit tant que rien n\'est touché', table.cle === null,
     String(table.cle));

  /* ── CE QUI S'ÉCRIT, ET CE QUI NE S'ÉCRIT PAS ───────────────────────── */
  const ecrit = await page.evaluate(() => {
    window.tse.options.poser('duree', false);
    const apres = JSON.parse(localStorage.getItem('tse:options') || 'null');
    window.tse.options.poser('duree', true);
    return { apres, retour: localStorage.getItem('tse:options') };
  });
  ok('poser un écart n\'écrit QUE cet écart',
     !!ecrit.apres && Object.keys(ecrit.apres).length === 1 && ecrit.apres.duree === false,
     JSON.stringify(ecrit.apres));
  ok('…et revenir au défaut retire la clé au lieu d\'écrire « {} »',
     ecrit.retour === null, String(ecrit.retour));

  /* ── CE QUI VIENT DU DEHORS ─────────────────────────────────────────── */
  const refus = await page.evaluate(() => {
    const avant = window.tse.options();
    const r = {
      horsListe: window.tse.options.poser('topN', 5000),
      mauvaisType: window.tse.options.poser('duree', 'oui'),
      inconnu: window.tse.options.poser('nexistePas', true),
      jeuSale: window.tse.options.poser('badges', ['hype', 'inventé', 'hype']),
    };
    return { r, topN: window.tse.options().topN, duree: window.tse.options().duree,
             badges: window.tse.options().badges, avantTopN: avant.topN };
  });
  ok('une valeur hors liste est refusée, et l\'ancienne tient',
     refus.r.horsListe === false && refus.topN === refus.avantTopN,
     JSON.stringify(refus));
  ok('…un mauvais type aussi', refus.r.mauvaisType === false && refus.duree === true,
     JSON.stringify(refus.r));
  ok('…un identifiant inconnu aussi', refus.r.inconnu === false, String(refus.r.inconnu));
  /* UN JEU SE NETTOIE AU LIEU D'ÊTRE REFUSÉ, et la nuance compte : un import
     venu d'une version antérieure peut nommer un badge disparu. Le refuser en
     bloc perdrait les dix autres ; on garde ce qu'on reconnaît. */
  ok('…mais un jeu se nettoie : membres inconnus retirés, doublons fondus',
     refus.badges.length === 1 && refus.badges[0] === 'hype',
     JSON.stringify(refus.badges));

  /* ── LE STOCKAGE QUI MENT ───────────────────────────────────────────── */
  const sale = await page.evaluate(() => {
    localStorage.setItem('tse:options', '{"topN":9999,"theme":"rose","duree":false}');
    /* On relit comme le ferait un autre onglet : c'est le seul chemin par
       lequel du JSON arbitraire entre en cours de vie. */
    window.dispatchEvent(new StorageEvent('storage', { key: 'tse:options' }));
    const v = window.tse.options();
    return { topN: v.topN, theme: v.theme, duree: v.duree };
  });
  ok('un stockage corrompu ne passe pas : chaque champ est validé séparément',
     sale.topN === 30 && sale.theme === 'auto' && sale.duree === false,
     JSON.stringify(sale));
  await page.evaluate(() => { localStorage.removeItem('tse:options');
                              window.tse.options.remettre(); });
  await page.close();
}

/* ═════════ TOUT PAR DÉFAUT = LE COMPORTEMENT D'AVANT ═════════════════════
   C'est l'invariant qui protège les mille assertions écrites avant les
   réglages, et il ne repose pas sur des valeurs bien choisies : il repose sur
   des attributs ABSENTS. Tout le bloc CSS des réglages est écrit en
   « html[data-tse-off~="…"] » ; sans attribut sur la racine, pas un de ces
   sélecteurs ne s'apparie, et la feuille est celle d'avant au caractère près.

   ON LE VÉRIFIE DANS LES DEUX SENS : l'attribut est absent au départ, et il
   apparaît avec EXACTEMENT le jeton attendu quand on coupe quelque chose. Un
   contrôle qui ne ferait que constater l'absence passerait sur un produit où
   plus rien ne s'éteint. */
{
  titre('118. Les réglages qui passent par la feuille — absents par défaut, exacts quand ils agissent');
  const page = await fresh();
  await page.evaluate(() => {
    window.__fx = { alpha: { id: 'a', createdAt: new Date(Date.now() - 95 * 60_000).toISOString(),
                             viewers: 900, game: 'Just Chatting', tags: [] } };
    window.__addCard('alpha', 'Just Chatting', '900');
  });
  await wait(page, 1200);

  const vierge = await page.evaluate(() => ({
    off: document.documentElement.getAttribute('data-tse-off'),
    or: document.documentElement.getAttribute('data-tse-or'),
    apercu: document.documentElement.getAttribute('data-tse-apercu'),
    dureeVisible: getComputedStyle(document.querySelector('.tse-uptime')).display,
  }));
  ok('aucun attribut de réglage sur la racine tant que rien n\'est touché',
     vierge.off === null && vierge.or === null && vierge.apercu === null,
     JSON.stringify(vierge));
  ok('…et la durée s\'affiche, comme avant les réglages',
     vierge.dureeVisible !== 'none', vierge.dureeVisible);

  /* ── UN INTERRUPTEUR : LE JETON, PUIS L'EFFET ───────────────────────── */
  const coupe = await page.evaluate(() => {
    window.tse.options.poser('duree', false);
    return { off: document.documentElement.getAttribute('data-tse-off'),
             display: getComputedStyle(document.querySelector('.tse-uptime')).display };
  });
  ok('couper la durée pose son jeton, et lui seul',
     coupe.off === 'duree', String(coupe.off));
  /* LA MESURE QUI COMPTE. Un jeton posé ne prouve pas qu'une règle existe :
     c'est le style CALCULÉ qui dit si l'œil voit encore la durée. Le mutant
     qui retire la règle CSS laisse le jeton intact et tombe ici. */
  ok('…et la durée disparaît vraiment', coupe.display === 'none', coupe.display);

  /* ── « VIENT DE DÉMARRER » EST DEUX CHOSES ──────────────────────────────
     Le réglage ne retirait que la barre, et un utilisateur a demandé que tous
     les éléments partent. Le lavis violet du fond de carte se voit autant que
     la barre — c'est même lui qui la fait remarquer. On exige donc les deux,
     et sur le style calculé : le mutant qui ne neutralise qu'une des deux
     déclarations de fond tombe ici. */
  const frais = await page.evaluate(() => {
    window.tse.options.remettre();
    const c = document.querySelector('.side-nav-card');
    c.classList.add('tse-fresh');
    const avant = { barre: getComputedStyle(c, '::before').display,
                    lavis: getComputedStyle(c).backgroundImage };
    window.tse.options.poser('fresh', false);
    return { avant, apres: { barre: getComputedStyle(c, '::before').display,
                             lavis: getComputedStyle(c).backgroundImage } };
  });
  ok('une carte fraîche porte sa barre ET son lavis',
     frais.avant.barre !== 'none' && frais.avant.lavis !== 'none', JSON.stringify(frais.avant));
  ok('…et les couper retire les deux, pas seulement la barre',
     frais.apres.barre === 'none' && frais.apres.lavis === 'none', JSON.stringify(frais.apres));

  /* ── CE QUI RESTE PREND TOUTE LA LIGNE ──────────────────────────────────
     ASSERTION TOURNÉE, ET C'EST UN SECOND RETOUR QUI L'A EXIGÉ. Elle
     demandait que le filtre survivant se RECENTRE — la première réponse à
     « il reste collé au bord ». Centrer corrigeait l'alignement et laissait
     la moitié de la barre vide ; l'utilisateur a demandé mieux, que le
     survivant REMPLISSE la ligne. On mesure donc une largeur, pas un
     alignement : le champ restant doit couvrir la rangée entière.

     LE TRI, LUI, RESTE CENTRÉ : ses six boutons ne s'étirent pas, et les
     étaler à deux mettrait un bouton dans chaque coin. Les deux rangées n'ont
     pas la même réponse parce qu'elles n'ont pas le même problème. */
  const remplissage = await page.evaluate(() => {
    window.tse.options.remettre();
    const lire = () => {
      const r = (s) => { const e = document.querySelector(s);
        const b = e.getBoundingClientRect(); return Math.round(b.width); };
      const nom = document.querySelector('.tse-dd--lang .tse-dd-current .tse-dd-nom');
      return { tri: getComputedStyle(document.querySelector('.tse-sort-row')).justifyContent,
               rangee: r('.tse-filter-row'), cat: r('.tse-filter-field--cat'),
               lang: r('.tse-filter-field--lang'),
               nom: nom ? nom.textContent : null,
               nomVisible: nom ? getComputedStyle(nom).display !== 'none' : null };
    };
    const plein = lire();
    window.tse.options.poser('filtreCategorie', false);
    const sansCat = lire();
    window.tse.options.remettre();
    window.tse.options.poser('filtreLangue', false);
    return { plein, sansCat, sansLang: lire() };
  });
  ok('les boutons de tri sont centrés, quel que soit leur nombre',
     remplissage.plein.tri === 'center', remplissage.plein.tri);
  ok('…le filtre langue prend toute la ligne quand la catégorie part',
     remplissage.sansCat.cat === 0
     && remplissage.sansCat.lang === remplissage.sansCat.rangee,
     JSON.stringify(remplissage.sansCat));
  ok('…et le filtre catégorie en fait autant quand la langue part',
     remplissage.sansLang.lang === 0
     && remplissage.sansLang.cat === remplissage.sansLang.rangee,
     JSON.stringify(remplissage.sansLang));
  /* LE NOM EST TOUJOURS CONSTRUIT, JAMAIS TOUJOURS MONTRÉ. C'est ce qui
     permet à la bascule du réglage de n'exiger aucune reconstruction du
     menu — et c'est exactement ce qu'on vérifie : présent des deux côtés,
     visible d'un seul. */
  ok('le nom de la langue est dans le DOM même quand il ne se voit pas',
     remplissage.plein.nom === remplissage.sansCat.nom
     && typeof remplissage.plein.nom === 'string' && remplissage.plein.nom.length > 0,
     JSON.stringify([remplissage.plein.nom, remplissage.sansCat.nom]));
  ok('…et il n\'apparaît que dans la ligne élargie',
     remplissage.plein.nomVisible === false && remplissage.sansCat.nomVisible === true,
     JSON.stringify([remplissage.plein.nomVisible, remplissage.sansCat.nomVisible]));

  /* ── UN JEU : UN MEMBRE, UN JETON PRÉFIXÉ ───────────────────────────── */
  const jeu = await page.evaluate(() => {
    window.tse.options.remettre();
    window.tse.options.poser('badges', ['hype']);
    window.tse.options.poser('tris', ['alpha']);
    return document.documentElement.getAttribute('data-tse-off');
  });
  ok('un membre de jeu devient un jeton préfixé, pas son nom nu',
     jeu === 'badge-hype tri-alpha', String(jeu));

  /* ── UN CHOIX : SON PROPRE ATTRIBUT, ET RIEN QUAND IL VAUT SON DÉFAUT ─ */
  const choix = await page.evaluate(() => {
    window.tse.options.remettre();
    const neutre = document.documentElement.getAttribute('data-tse-or');
    window.tse.options.poser('abonnes', 'discret');
    const pose = document.documentElement.getAttribute('data-tse-or');
    window.tse.options.poser('abonnes', 'plein');
    return { neutre, pose, retire: document.documentElement.getAttribute('data-tse-or') };
  });
  ok('un choix qui vaut son défaut n\'écrit aucun attribut',
     choix.neutre === null && choix.retire === null, JSON.stringify(choix));
  ok('…et il en écrit un dès qu\'il s\'en écarte', choix.pose === 'discret', String(choix.pose));

  /* ── CHAQUE RÉGLAGE « css » EST NOMMÉ PAR UNE RÈGLE, ET RÉCIPROQUEMENT ──
     L'AUDIT A CHERCHÉ CE TROU À LA MAIN, ce qui n'est bon qu'une fois. Un
     réglage marqué « css: true » dont aucune règle ne porte le jeton est un
     interrupteur qui ne fait RIEN : il s'affiche, il se coche, il s'écrit au
     stockage, et rien ne bouge. Aucune des assertions précédentes ne
     l'attraperait — elles éprouvent les réglages qu'elles nomment, pas ceux
     qu'on ajoutera.

     ON LIT LA FEUILLE RENDUE, PAS LA SOURCE : « document.styleSheets » dit ce
     que le navigateur a réellement accepté, là où une lecture du fichier
     compterait aussi les règles qu'une faute de syntaxe aurait fait tomber.

     LES DEUX CHOIX SONT HORS DE CE CONTRAT et pour une raison qui se dit :
     « abonnes » et « apercuTaille » portent une VALEUR, pas un interrupteur ;
     ils ont leur propre attribut, et le scénario les couvre plus haut. */
  const contratCss = await page.evaluate(() => {
    const defs = window.tse.panneau('options').defs;
    const jetons = new Set();
    for (const f of document.styleSheets) {
      let regles = [];
      try { regles = [...f.cssRules]; } catch { continue; }
      for (const r of regles) {
        for (const m of (r.selectorText || '').matchAll(/data-tse-off~="([a-zA-Z-]+)"/g)) {
          jetons.add(m[1]);
        }
      }
    }
    const attendus = [];
    for (const [id, d] of Object.entries(defs)) {
      if (!d.css) continue;
      if (d.type === 'bool') attendus.push(id);
      else if (d.type === 'jeu') {
        const prefixe = id === 'badges' ? 'badge-' : 'tri-';
        for (const m of d.valeurs) attendus.push(prefixe + m);
      }
    }
    return { sansRegle: attendus.filter((t) => !jetons.has(t)),
             orphelines: [...jetons].filter((t) => !attendus.includes(t)),
             n: attendus.length };
  });
  ok(`chacun des ${contratCss.n} jetons de réglage est nommé par une règle de la feuille`,
     contratCss.sansRegle.length === 0, contratCss.sansRegle.join(', '));
  ok('…et aucune règle ne vise un jeton que plus aucun réglage ne produit',
     contratCss.orphelines.length === 0, contratCss.orphelines.join(', '));

  /* ── ET LE CHEMIN DU RETOUR ─────────────────────────────────────────── */
  const retour = await page.evaluate(() => {
    window.tse.options.poser('duree', false);
    window.tse.options.remettre();
    return { off: document.documentElement.getAttribute('data-tse-off'),
             display: getComputedStyle(document.querySelector('.tse-uptime')).display };
  });
  ok('tout remettre par défaut rend la page à son état d\'origine',
     retour.off === null && retour.display !== 'none', JSON.stringify(retour));
  await page.close();
}

/* ═════════ LES RÉGLAGES QUI NE PASSENT PAS PAR LA FEUILLE ════════════════
   Quatre d'entre eux changent du COMPORTEMENT, pas de l'apparence, et ceux-là
   ne peuvent pas se vérifier sur un attribut. On les éprouve chacun par ce
   qu'il produit : un texte qui change de forme, un aperçu qui ne s'ouvre pas,
   un thème qui cesse de suivre Twitch, une requête qui ne part plus. */
{
  titre('119. Les réglages de comportement — mesurés sur ce qu\'ils produisent');
  const page = await fresh();
  await page.evaluate(() => {
    window.__fx = { alpha: { id: 'a', createdAt: new Date(Date.now() - 259 * 60_000).toISOString(),
                             viewers: 900, game: 'Just Chatting', tags: [] } };
    window.__addCard('alpha', 'Just Chatting', '900');
  });
  await wait(page, 1200);

  const lireDuree = () => page.evaluate(() =>
    document.querySelector('.tse-uptime')?.textContent ?? null);

  ok('la durée se dit « 4h19 » par défaut', (await lireDuree()) === '4h19', await lireDuree());
  /* LE FORMAT SE VOIT SANS RECHARGEMENT : poser le réglage programme un scan
     ordinaire, pas une réinitialisation sous voile. */
  await page.evaluate(() => window.tse.options.poser('dureeFormat', 'colon'));
  await wait(page, 700);
  ok('…« 4:19 » quand on le demande', (await lireDuree()) === '4:19', await lireDuree());
  await page.evaluate(() => window.tse.options.poser('dureeFormat', 'min'));
  await wait(page, 700);
  ok('…et « 259 min » sur l\'autre', (await lireDuree()) === '259 min', await lireDuree());

  /* ── LE THÈME FORCÉ CESSE DE SUIVRE TWITCH ──────────────────────────── */
  const theme = await page.evaluate(() => {
    window.tse.options.remettre();
    document.documentElement.setAttribute('data-a-theme', 'dark');
    const suivi = document.documentElement.getAttribute('data-tse-theme');
    window.tse.options.poser('theme', 'light');
    const force = document.documentElement.getAttribute('data-tse-theme');
    /* ON BOUSCULE TWITCH PENDANT QUE LE RÉGLAGE TIENT : c'est tout l'objet du
       mode forcé, et l'observateur de racine pourrait le défaire. */
    document.documentElement.setAttribute('data-a-theme', 'dark');
    return { suivi, force, apresSecousse: document.documentElement.getAttribute('data-tse-theme') };
  });
  ok('« auto » suit le thème de Twitch', theme.suivi === 'dark', JSON.stringify(theme));
  /* ── FORCER N'EST PAS SUIVRE, ET LA FEUILLE DOIT CESSER D'EMPRUNTER ─────
     En « auto », nos surfaces se servent chez Twitch — « var(--color-…) » —
     et c'est le bon comportement. Forcé, cette délégation se retourne : un
     utilisateur a demandé le clair pendant que Twitch restait sombre, et nos
     textes sont passés au noir sur des fonds restés noirs. On mesure donc le
     FOND et la COULEUR rendus de la barre, pas la déclaration : la seconde
     moitié du défaut — une variable qui ne rattrape pas un « color » déjà
     hérité — ne se voit que là. */
  const forces = await page.evaluate(() => {
    const nav = document.querySelector('#side-nav');
    const lire = () => ({ fond: getComputedStyle(nav).backgroundColor,
                          texte: getComputedStyle(nav).color,
                          force: document.documentElement.hasAttribute('data-tse-force') });
    window.tse.options.remettre();
    document.documentElement.setAttribute('data-a-theme', 'dark');
    const auto = lire();
    window.tse.options.poser('theme', 'light');
    return { auto, force: lire() };
  });
  const clair = (c) => { const m = /(\d+), (\d+), (\d+)/.exec(c || ''); return m
    ? (0.2126 * +m[1] + 0.7152 * +m[2] + 0.0722 * +m[3]) > 128 : null; };
  ok('en « auto », le drapeau de forçage n\'est pas posé',
     forces.auto.force === false, JSON.stringify(forces.auto));
  /* FORCER CE QUE TWITCH FAIT DÉJÀ NE DOIT RIEN FAIRE, et « rien » se mesure :
     pas d'attribut, et un fond IDENTIQUE à celui du mode auto. Un signalement
     l'a exigé — forcé en sombre sur un Twitch déjà sombre, la barre devenait
     plus foncée que d'habitude, nos repeintures s'ajoutant aux siennes. */
  const memeQueAuto = await page.evaluate(() => {
    const nav = document.querySelector('#side-nav');
    const lire = () => ({ force: document.documentElement.hasAttribute('data-tse-force'),
                          fond: getComputedStyle(nav).backgroundColor });
    window.tse.options.remettre();
    document.documentElement.setAttribute('data-a-theme', 'dark');
    const auto = lire();
    window.tse.options.poser('theme', 'dark');
    return { auto, force: lire() };
  });
  ok('forcer le thème que Twitch porte déjà ne pose aucun attribut',
     memeQueAuto.force.force === false, JSON.stringify(memeQueAuto.force));
  ok('…et laisse la barre exactement comme en « auto »',
     memeQueAuto.force.fond === memeQueAuto.auto.fond, JSON.stringify(memeQueAuto));
  ok('…forcé en clair, la barre reçoit un fond CLAIR et une encre SOMBRE',
     forces.force.force === true && clair(forces.force.fond) === true
     && clair(forces.force.texte) === false, JSON.stringify(forces.force));
  ok('…et le forcer le remplace, même quand Twitch se rappelle à nous',
     theme.force === 'light' && theme.apresSecousse === 'light', JSON.stringify(theme));

  /* ── L'APERÇU COUPÉ NE S'ARME MÊME PAS ──────────────────────────────── */
  const apercu = await page.evaluate(async () => {
    window.tse.options.remettre();
    const carte = document.querySelector('.side-nav-card');
    const survoler = () => carte.dispatchEvent(new MouseEvent('mouseenter', { bubbles: false }));
    survoler();
    await new Promise(r => setTimeout(r, 600));
    const ouvert = !!document.querySelector('.tse-preview');
    document.querySelector('.tse-preview')?.remove();
    window.tse.options.poser('apercu', false);
    survoler();
    await new Promise(r => setTimeout(r, 600));
    return { ouvert, coupe: !!document.querySelector('.tse-preview'),
             voileCoupe: document.body.classList.contains('tse-preview-active') };
  });
  ok('l\'aperçu s\'ouvre au survol quand il est actif', apercu.ouvert === true,
     JSON.stringify(apercu));
  /* LE VOILE RESTE POSÉ. « .tw-dialog-layer » est le conteneur modal que
     Twitch pose sous son propre tooltip de carte ; l'extension le masque
     pendant le survol via ce drapeau. L'interrupteur, d'abord placé avant
     lui, RENDAIT donc à Twitch un tooltip masqué depuis toujours : « quand
     on décoche l'aperçu on a quand même une petite fenêtre horizontale ».
     Un interrupteur qui ramène quelque chose n'est pas un interrupteur. */
  ok('…et le coupant, le voile qui masque le tooltip de Twitch reste posé',
     apercu.voileCoupe === true, JSON.stringify(apercu));
  /* CELUI-CI EST LE VRAI : coupé, RIEN ne doit s'armer — ni minuteur, ni
     préchargement, ni requête de métadonnées. Un aperçu qui préparerait son
     contenu en coulisses serait un réglage menteur, et le seul à pouvoir s'en
     apercevoir regarderait son trafic réseau. */
  ok('…et coupé, il ne s\'ouvre pas du tout', apercu.coupe === false,
     JSON.stringify(apercu));
  await page.evaluate(() => window.tse.options.remettre());
  await page.close();
}

/* ═════════ L'ONGLET OPTIONS — LA PRÉSENTATION EST UN CONTRAT ═════════════
   Le panneau ne porte pas la table des réglages : il la reçoit. Ce qu'il porte,
   c'est un ORDRE — GROUPES_OPT — et cet ordre est la seule chose qui puisse se
   désynchroniser de content.js sans que rien ne le dise. Un réglage oublié d'un
   groupe n'apparaîtrait nulle part ; un identifiant fantôme dans un groupe
   n'afficherait rien. Ni l'un ni l'autre ne jette d'erreur.

   ON COMPARE DONC LES DEUX ENSEMBLES, dans les deux sens, et on le fait à
   travers le DOM RÉELLEMENT PEINT plutôt qu'en relisant la table : c'est la
   différence entre vérifier une déclaration et vérifier un résultat. */
{
  titre('120. L\'onglet Options — chaque réglage a sa ligne, et son contrôle');

  const stub = (msg) => {
    const T = (k, sub) => {
      const m = msg[k] ? msg[k].message : k;
      if (sub === undefined) return m;
      const args = Array.isArray(sub) ? sub : [sub];
      return m.replace(/\$(\d)/g, (_, i) => args[Number(i) - 1] ?? '');
    };
    /* LA TABLE DU FAUX EST CELLE DU PRODUIT, recopiée ici une seule fois :
       c'est la seule recopie du banc, et elle est délibérée — le panneau doit
       être éprouvé SANS content.js, puisque c'est ainsi qu'il tourne. Le
       scénario 117 tient l'autre bout, sur la vraie table. */
    const DEFS = {
      apercu: { defaut: true, type: 'bool' },
      apercuVideo: { defaut: true, type: 'bool' },
      apercuQualite: { defaut: '360p30', type: 'choix',
                       valeurs: ['160p30', '360p30', '480p30', '720p60'] },
      apercuTaille: { defaut: 'normal', type: 'choix', valeurs: ['petit', 'normal', 'grand'] },
      badges: { defaut: [], type: 'jeu',
                valeurs: ['ccl', 'costream', 'squad', 'sub', 'exsub', 'sponsor',
                          'hype', 'discount', 'switch', 'reprise', 'subathon'] },
      duree: { defaut: true, type: 'bool' },
      dureeFormat: { defaut: 'hm', type: 'choix', valeurs: ['hm', 'colon', 'min'] },
      fresh: { defaut: true, type: 'bool' },
      collab: { defaut: true, type: 'bool' },
      abonnes: { defaut: 'plein', type: 'choix', valeurs: ['plein', 'discret', 'aucun'] },
      subathonJour: { defaut: true, type: 'bool' },
      stories: { defaut: true, type: 'bool' },
      abosPeriode: { defaut: 6, type: 'choix', valeurs: [3, 6, 12, 24] },
      topN: { defaut: 30, type: 'choix', valeurs: [10, 30, 50] },
      topOnglet: { defaut: true, type: 'bool' },
      tris: { defaut: [], type: 'jeu',
              valeurs: ['viewers', 'subs', 'popular', 'uptime', 'alpha', 'costream'] },
      filtreCategorie: { defaut: true, type: 'bool' },
      filtreLangue: { defaut: true, type: 'bool' },
      theme: { defaut: 'auto', type: 'choix', valeurs: ['auto', 'dark', 'light'] },
    };
    const valeurs = {};
    for (const [id, d] of Object.entries(DEFS)) {
      valeurs[id] = Array.isArray(d.defaut) ? d.defaut.slice() : d.defaut;
    }
    window.__defs = DEFS;
    window.__poses = [];
    const paquet = () => {
      const modifies = Object.entries(DEFS).filter(([id, d]) => (Array.isArray(d.defaut)
        ? valeurs[id].length !== 0 : valeurs[id] !== d.defaut)).map(([id]) => id);
      return { defs: DEFS, valeurs, defauts: Object.fromEntries(
                 Object.entries(DEFS).map(([id, d]) => [id, d.defaut])),
               modifies, resume: { reglages: Object.keys(DEFS).length,
                                   modifies: modifies.length } };
    };
    window.chrome = {
      i18n: { getMessage: T, getUILanguage: () => 'fr' },
      tabs: { query: () => Promise.resolve([{ id: 1 }]) },
      runtime: {
        getManifest: () => ({ version: '9.9.9' }),
        sendMessage: (m) => {
          if (m.type === 'tse-panneau-etat') return Promise.resolve({ ok: true, ponts: [1] });
          if (m.action === 'setOption') {
            window.__poses.push(m.arg);
            valeurs[m.arg.id] = m.arg.valeur;
            return Promise.resolve({ ok: true, data: { ok: true, ...paquet() } });
          }
          if (m.action === 'resetOptions') {
            for (const [id, d] of Object.entries(DEFS)) {
              valeurs[id] = Array.isArray(d.defaut) ? d.defaut.slice() : d.defaut;
            }
            return Promise.resolve({ ok: true, data: { ok: true, ...paquet() } });
          }
          if (m.section === 'options') return Promise.resolve({ ok: true, data: paquet() });
          return Promise.resolve({ ok: true, data: { colonnes: ['login'], lignes: [], resume: {} } });
        },
      },
    };
  };

  const messages = JSON.parse(readFileSync(join(ICI, '..', '_locales', 'fr', 'messages.json'), 'utf8'));
  const page = await browser.newPage({ viewport: { width: 760, height: 580 } });
  page.on('pageerror', (e) => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
  await page.addInitScript(stub, messages);
  await page.goto(pathToFileURL(join(ICI, '..', 'panneau.html')).href);
  await attendre(page, () => document.querySelectorAll('.rail-item').length > 0);
  await page.evaluate(() => [...document.querySelectorAll('.rail-item')]
    .find((b) => b.dataset.id === 'options').click());
  await attendre(page, () => !document.getElementById('reglages').hidden, 6000);

  const vue = await page.evaluate(() => {
    const lignes = [...document.querySelectorAll('#reglages [data-reg]')];
    return {
      peints: lignes.map((l) => l.dataset.reg),
      /* Le contrôle est ce qui prouve que la ligne SERT : une ligne sans
         interrupteur ni menu ni case est un libellé, pas un réglage. */
      sansControle: lignes.filter((l) => !l.querySelector('input, select'))
                          .map((l) => l.dataset.reg),
      groupes: [...document.querySelectorAll('#reglages .reg-groupe')].length,
      cases: document.querySelectorAll('#reglages [data-reg="badges"] .reg-case').length,
      tris: document.querySelectorAll('#reglages [data-reg="tris"] .reg-case').length,
      menus: document.querySelectorAll('#reglages .reg-menu').length,
      /* Une clé rendue telle quelle est la signature d'un libellé manquant :
         « optApercuVideo » au lieu de « Flux vidéo en direct ». */
      brutes: lignes.map((l) => l.querySelector('.reg-nom').textContent)
                    .filter((t) => /^opt[A-Z]/.test(t)),
      tuiles: [...document.querySelectorAll('#resume .tuile-val')].map((t) => t.textContent),
    };
  });
  /* LE CONTRAT SE VÉRIFIE PAR LE CONTENU, PAS PAR LE COMPTE. Deux erreurs
     opposées — un réglage oublié d'un groupe, un identifiant fantôme dans un
     autre — se compensent exactement dans un total. On compare donc les deux
     ensembles membre à membre, dans les deux sens. */
  const contrat = await page.evaluate((peints) => {
    const table = Object.keys(window.__defs);
    return { oublies: table.filter((id) => !peints.includes(id)),
             fantomes: peints.filter((id) => !table.includes(id)) };
  }, vue.peints);

  ok('les dix-neuf réglages de la page ont chacun leur ligne',
     contrat.oublies.length === 0, contrat.oublies.join(', '));
  ok('…et aucune ligne fantôme : l\'ordre du panneau couvre exactement la table',
     contrat.fantomes.length === 0, contrat.fantomes.join(', '));
  ok('…chacune porte un contrôle, pas seulement un libellé',
     vue.sansControle.length === 0, vue.sansControle.join(', '));
  ok('…et aucun libellé ne sort en clé brute',
     vue.brutes.length === 0, vue.brutes.join(', '));
  ok('les onze badges et les six tris ont leurs cases',
     vue.cases === 11 && vue.tris === 6, JSON.stringify([vue.cases, vue.tris]));
  ok('les cartouches disent le compte, et zéro modifié au départ',
     vue.tuiles[0] === '19' && vue.tuiles[1] === '0', JSON.stringify(vue.tuiles));

  /* ── CE QUI PART VERS LA PAGE ───────────────────────────────────────── */
  await page.evaluate(() => document.querySelector(
    '#reglages [data-reg="duree"] input').click());
  await attendre(page, () => window.__poses.length > 0, 4000);
  const pose = await page.evaluate(() => window.__poses[window.__poses.length - 1]);
  ok('cocher un interrupteur envoie son identifiant et un booléen',
     pose.id === 'duree' && pose.valeur === false, JSON.stringify(pose));

  /* UN JEU ENVOIE CE QU'ON RETIRE, pas ce qu'on garde : le retournement se
     fait dans le panneau, une fois, et c'est ici qu'on le constate. */
  await page.evaluate(() => document.querySelector(
    '#reglages [data-reg="badges"] .reg-case input').click());
  await attendre(page, () => window.__poses.length > 1, 4000);
  const poseJeu = await page.evaluate(() => window.__poses[window.__poses.length - 1]);
  ok('décocher un badge envoie la liste de ce qu\'on RETIRE',
     poseJeu.id === 'badges' && Array.isArray(poseJeu.valeur)
     && poseJeu.valeur.length === 1 && poseJeu.valeur[0] === 'ccl',
     JSON.stringify(poseJeu));

  /* UN MENU REND SON TYPE D'ORIGINE. La valeur d'un <option> est toujours une
     chaîne ; « 30 » n'est pas 30, et la validation de la page refuserait la
     chaîne sans que l'interface le montre. */
  await page.evaluate(() => {
    const sel = document.querySelector('#reglages [data-reg="topN"] select');
    /* ON LE FOCALISE D'ABORD, parce que c'est ce qu'un utilisateur fait : on
       ne change pas un menu sans l'avoir atteint. Sans ce focus, l'assertion
       du rattrapage plus bas mesurait un décor que le banc n'avait pas posé —
       elle a échoué sur du code sain, ce qui est la pire sorte d'échec. */
    sel.focus();
    sel.value = '50';
    sel.dispatchEvent(new Event('change'));
  });
  await attendre(page, () => window.__poses.length > 2, 4000);
  const poseNombre = await page.evaluate(() => window.__poses[window.__poses.length - 1]);
  ok('un menu de nombres renvoie un NOMBRE, pas la chaîne de son <option>',
     poseNombre.id === 'topN' && poseNombre.valeur === 50
     && typeof poseNombre.valeur === 'number', JSON.stringify(poseNombre));

  /* ── LE POINT DES MODIFIÉS, ET LE FOCUS QUI SURVIT ──────────────────── */
  const apres = await page.evaluate(() => ({
    points: document.querySelectorAll('#reglages .reg-ligne--modifie').length,
    tuiles: [...document.querySelectorAll('#resume .tuile-val')].map((t) => t.textContent),
    focus: document.activeElement.closest('[data-reg]')?.dataset.reg ?? null,
  }));
  ok('les lignes modifiées se marquent', apres.points === 3, JSON.stringify(apres.points));
  /* REPEINDRE DÉTRUIT L'ÉLÉMENT QU'ON VIENT D'ACTIONNER. Sans le rattrapage du
     focus, cocher trois cases de suite au clavier devient impossible — le
     focus retombe sur le corps du document après la première. */
  ok('…et le focus reste sur le réglage qu\'on vient de toucher',
     apres.focus === 'topN', String(apres.focus));

  /* ── LE MASQUAGE DES DIAGNOSTICS ──────────────────────────────────────
     ASSERTION TOURNÉE : ces cinq chapitres ne servent qu'à signaler un
     problème, et les montrer à tout le monde donnait au panneau l'air d'un
     outil de débogage. Ils partent donc MASQUÉS, et c'est l'interrupteur qui
     les rallume. On éprouve le chemin dans ce sens-là. */
  const diag = await page.evaluate(() => {
    const visible = () => [...document.querySelectorAll('.rail-item')]
      .filter((b) => b.dataset.groupe === 'grpDiag')
      .filter((b) => getComputedStyle(b).display !== 'none').length;
    const titres = () => [...document.querySelectorAll('.rail-groupe')]
      .filter((h) => h.dataset.groupe === 'grpDiag')
      .filter((h) => getComputedStyle(h).display !== 'none').length;
    const avant = { items: visible(), titre: titres() };
    /* On vise le groupe par son marqueur, pas par son rang : un groupe inséré
       plus haut aurait fait cliquer sur autre chose, et l'assertion aurait
       échoué en accusant le mauvais coupable. */
    document.querySelector('#reglages [data-grp="panneau"]')
      .querySelectorAll('.reg-bascule input')[0].click();
    return { avant, apres: { items: visible(), titre: titres() } };
  });
  ok('les cinq chapitres de diagnostic sont masqués d\'emblée, titre compris',
     diag.avant.items === 0 && diag.avant.titre === 0, JSON.stringify(diag.avant));
  ok('…et l\'interrupteur les rallume tous les cinq',
     diag.apres.items === 5 && diag.apres.titre === 1, JSON.stringify(diag.apres));

  /* ── CE QUI NE DOIT PLUS DÉBORDER ──────────────────────────────────────
     LE DÉFAUT DE LA 4.10.0, ET IL SE MESURE EN UN NOMBRE. Les cases sont
     posées en absolu par-dessus leur piste ; sans ancêtre positionné,
     « absolu » se rapporte au document. Les dix-neuf cases se retrouvaient à
     des centaines de pixels du haut, « documentElement.scrollHeight » passait
     de 580 à 2033, et une popup de barre d'outils se dimensionne là-dessus :
     une fenêtre de sept cents pixels, cartouches et pied hors champ.

     ON MESURE LE DOCUMENT, PAS LA RÈGLE. « position: relative » sur le
     libellé se vérifierait en lisant le style ; ce qui compte est qu'aucun
     élément ne sorte de la fenêtre, quelle qu'en soit la cause. */
  const debord = await page.evaluate(() => ({
    hauteur: document.documentElement.scrollHeight,
    /* LA SECONDE ASSERTION A DÛ ÊTRE REFAITE, et l'erreur mérite d'être dite :
       elle comptait d'abord les éléments dont le bas dépassait 620 px dans la
       FENÊTRE. Or « #reglages » défile : tout ce qui est sous la ligne de
       flottaison dépasse légitimement, et le relevé en trouvait quarante-
       trois sur un produit sain. Une assertion qui échoue sur du code juste
       est pire qu'une assertion absente — on apprend à l'ignorer.

       CE QU'ON VEUT NOMMER EST PRÉCIS : un élément posé en absolu SANS
       ancêtre positionné se rapporte au bloc conteneur initial, c'est-à-dire
       au document. « offsetParent » le dit sans détour, et rien d'autre ne
       peut le satisfaire par accident. */
    orphelins: [...document.querySelectorAll('#reglages *')]
      .filter((e) => getComputedStyle(e).position === 'absolute')
      .filter((e) => !e.offsetParent || e.offsetParent === document.body)
      .map((e) => e.tagName + '.' + (e.parentElement?.className || '?')),
  }));
  ok('le document ne dépasse pas la fenêtre de la popup',
     debord.hauteur <= 580, JSON.stringify(debord.hauteur));
  ok('…et aucun élément posé en absolu ne se rapporte au document lui-même',
     debord.orphelins.length === 0, JSON.stringify(debord.orphelins.slice(0, 4)));
  await page.close();
}

/* ═════════ SE FAIRE TROUVER, DEPUIS LA BARRE LATÉRALE ════════════════════
   Depuis Chrome 89, une extension fraîchement installée n'est PAS dans la barre
   d'outils : elle est rangée derrière le bouton « pièce de puzzle ». Tout ce que
   ce produit sait faire vivait donc derrière un clic que personne ne savait
   pouvoir donner.

   LA RÉPONSE EST UN SECOND CHEMIN, POSÉ LÀ OÙ L'UTILISATEUR REGARDE DÉJÀ :
   une roue crantée dans le titre de la barre latérale. Trois choses peuvent mal
   tourner, et aucune ne se verrait sans contrôle :

     — la roue n'est PAS REPOSÉE quand React remonte le titre, et disparaît à
       la première navigation interne ;
     — elle est posée DANS le <h3>, que « renameRootTitle » réécrit à chaque
       passe : elle s'efface une fois par seconde ;
     — le titre n'est pas mis en « flex », et la roue tombe sous le titre au
       lieu de se poser à sa droite. */
{
  titre('121. La roue crantée — dans le titre, et elle y reste');

  const page = await fresh();
  const poser = () => page.evaluate(() => {
    window.__fx = { alpha: { id: 'a', createdAt: new Date(Date.now() - 3600e3).toISOString(),
                             viewers: 900, game: 'G', tags: [] } };
    window.__addCard('alpha', 'G', '900');
  });
  await poser();
  await wait(page, 1500);

  const vue = await page.evaluate(() => {
    const r = document.getElementById('tse-roue');
    const t = document.querySelector('#side-nav .side-nav__title');
    const st = t && getComputedStyle(t);
    return {
      presente: !!r,
      /* À CÔTÉ DU <h3>, PAS DEDANS. « renameRootTitle » écrit `textContent` sur
         le <h3> à chaque passe : une roue posée dedans serait effacée une fois
         par seconde, et le seul symptôme serait un bouton qui clignote. */
      apresH3: !!(r && r.previousElementSibling
                    && r.previousElementSibling.tagName === 'H3'),
      dansTitre: !!(t && r && t.contains(r)),
      /* ── CE QUE LE DÉCOR TAISAIT, ET QUE LE TERRAIN A PAYÉ ─────────────
         La première rédaction faisait `appendChild`. Avec un <h3> SEUL dans
         le bloc, c'est indiscernable de « juste après le titre » — et le
         décor n'avait qu'un <h3>. Sur le vrai Twitch, ce bloc porte aussi le
         bouton de repli de la barre : la roue se posait donc après lui, à
         l'extrême droite, collée au chevron plutôt qu'au titre.

         ON MESURE DEUX CHOSES QUI TOMBENT ENSEMBLE : l'ordre des nœuds, et
         l'ÉCART en pixels entre la fin du titre et le début de la roue. Le
         premier seul se satisferait d'une marge automatique qui repousse la
         roue à l'autre bout ; le second seul se satisferait d'un titre qui
         se trouve court ce jour-là. */
      ordre: t ? [...t.children].map((e) => e.id || e.tagName) : null,
      ecart: (() => {
        const h3 = t && t.querySelector('h3');
        if (!h3 || !r) return null;
        return Math.round(r.getBoundingClientRect().left
                        - h3.getBoundingClientRect().right);
      })(),
      marque: t && t.getAttribute('data-tse-roue'),
      flex: st && st.display,
      /* Un bouton sans nom accessible n'est pas trouvable au lecteur d'écran,
         et celui-ci s'adresse d'abord à qui ne sait pas où chercher. */
      nom: r && r.getAttribute('aria-label'),
      infobulle: r && r.getAttribute('title'),
      type: r && r.getAttribute('type'),
      /* L'emoji est décoratif : le nom est sur le bouton, et le laisser lisible
         ferait annoncer « rouage » par-dessus. */
      dent: r && r.querySelector('.tse-roue-dent[aria-hidden="true"]')
              ? r.querySelector('.tse-roue-dent').textContent : null,
    };
  });
  ok('la roue est posée dans le titre de la barre latérale',
     vue.presente === true && vue.dansTitre === true, JSON.stringify(vue));
  ok('…à CÔTÉ du <h3>, que le renommage réécrit à chaque passe',
     vue.apresH3 === true, JSON.stringify(vue));
  /* COLLÉE AU TITRE, ET LE BOUTON DE REPLI DE TWITCH RESTE À SA DROITE.
     Douze pixels : le vide qu'une gouttière de rangée laisse, pas celui que
     laisse une barre latérale entière. */
  ok('…collée à droite du titre, devant le bouton de repli de Twitch',
     vue.ordre && vue.ordre[0] === 'H3' && vue.ordre[1] === 'tse-roue'
     && vue.ordre[2] === 'native-collapse'
     && vue.ecart !== null && vue.ecart >= 0 && vue.ecart <= 12,
     JSON.stringify(vue.ordre) + ' écart ' + vue.ecart);
  ok('…le titre porte notre marqueur et passe en rangée',
     vue.marque === 'true' && vue.flex === 'flex', JSON.stringify(vue));
  ok('…elle a un nom accessible, une infobulle, et une dent muette',
     typeof vue.nom === 'string' && vue.nom.length > 5 && vue.infobulle === vue.nom
     && vue.type === 'button' && vue.dent === '\u2699\uFE0F', JSON.stringify(vue));
  /* ── LA DENT EST DANS UN <span>, ET C'EST STRUCTUREL ───────────────────
     Le bouton porte le battement du premier lancement, qui anime
     « transform: scale ». La rotation au survol anime « transform » elle
     aussi : posée sur le MÊME élément, elle écraserait le battement et la roue
     cesserait de battre dès qu'on l'approche.

     ON ÉPROUVE LA RÈGLE, PAS SON EFFET, et c'est délibéré : le survol ne se
     simule pas au clavier ni au message — « :hover » ne répond qu'à un vrai
     pointeur, que ce banc ne déplace pas. Ce qui peut casser est l'endroit où
     la règle est POSÉE, et c'est cela qu'on lit.

     ASSERTION REFAITE : elle lisait « transitionProperty », et la 4.13 est
     passée d'une transition à une animation continue — une roue crantée est
     symétrique, un demi-tour la ramenait sur elle-même sans que rien ne se
     voie. L'ancienne lecture rendait « all » sur un produit sain. */
  ok('…et la rotation est déclarée sur la dent, pas sur le bouton qui bat',
     !!vue.dent
     && /\.tse-roue:hover \.tse-roue-dent[\s\S]{0,120}animation: tse-roue-tourne/
          .test(fileText('../content.js'))
     && !/\.tse-roue:hover \{[\s\S]{0,120}animation: tse-roue-tourne/
          .test(fileText('../content.js')),
     JSON.stringify(vue.dent));

  /* ── CE QUE REACT EMPORTE, LA PASSE SUIVANTE LE REPOSE ─────────────────
     C'est le mode de panne le plus probable de tout ce scénario : Twitch est
     une application à page unique, et son titre est remonté à chaque
     navigation interne. Une roue posée une seule fois disparaîtrait au premier
     clic sur une chaîne, sans erreur, sans trace. */
  const repose = await page.evaluate(async () => {
    const t = document.querySelector('#side-nav .side-nav__title');
    /* On rejoue exactement ce que fait React : le titre est REMPLACÉ par un
       nœud neuf, pas vidé. Vider aurait laissé le même élément en place et
       n'aurait donc pas éprouvé la garde « contains ». */
    const neuf = document.createElement('div');
    neuf.className = t.className;
    neuf.appendChild(document.createElement('h3'));
    t.replaceWith(neuf);
    const apresPerte = !document.getElementById('tse-roue');
    await new Promise((r) => setTimeout(r, 1600));
    const r2 = document.getElementById('tse-roue');
    return { apresPerte, revenue: !!r2,
             dansLeNeuf: !!(r2 && neuf.contains(r2)),
             /* Une seule : reposer sans retirer l'ancienne donnerait deux
                boutons, dont un orphelin dans un nœud détaché. */
             combien: document.querySelectorAll('#tse-roue, .tse-roue').length };
  });
  ok('un titre remplacé par React emporte la roue…',
     repose.apresPerte === true, JSON.stringify(repose));
  ok('…et la passe suivante la repose, une seule fois, dans le titre neuf',
     repose.revenue === true && repose.dansLeNeuf === true && repose.combien === 1,
     JSON.stringify(repose));
  await page.close();
}

/* ═════════ LE PANNEAU PAR-DESSUS LA PAGE ═════════════════════════════════
   La roue ouvre le panneau dans un CADRE posé sur Twitch. Ce qui se vérifie ici
   n'est pas le panneau — les scénarios 69 à 120 s'en chargent — mais le cadre :
   son adresse, sa taille, et les quatre façons d'en sortir.

   L'ADRESSE EST LE POINT SENSIBLE. content.js tourne en monde MAIN : il n'a pas
   « chrome.runtime », donc pas « getURL ». Elle lui arrive par un message, et un
   message est quelque chose que N'IMPORTE QUEL script de la page peut émettre.
   Sans filtre, une page hostile ferait charger SON adresse dans un cadre qui a
   l'air du nôtre — c'est-à-dire un hameçonnage avec notre décor autour. */
{
  titre('122. Le panneau incrusté — son adresse, sa taille, et comment on en sort');

  const page = await fresh();
  /* UNE FENÊTRE ASSEZ GRANDE POUR LE CADRE. Il fait 1100 × 760 et se borne à
     la fenêtre : mesuré dans une fenêtre par défaut, il rendait 696 px de haut
     et l'assertion aurait décrit le décor plutôt que le produit. */
  await page.setViewportSize({ width: 1400, height: 900 });
  await page.evaluate(() => {
    window.__fx = { alpha: { id: 'a', createdAt: new Date(Date.now() - 3600e3).toISOString(),
                             viewers: 900, game: 'G', tags: [] } };
    window.__addCard('alpha', 'G', '900');
  });
  await wait(page, 1500);

  /* ── AVANT L'ADRESSE, RIEN NE S'OUVRE ────────────────────────────────── */
  const sansUrl = await page.evaluate(async () => {
    document.getElementById('tse-roue').click();
    await new Promise((r) => setTimeout(r, 60));
    return !!document.getElementById('tse-incruste');
  });
  ok('sans adresse, le clic n\'ouvre pas un cadre vide',
     sansUrl === false, String(sansUrl));

  /* ── UNE ADRESSE QUI N'EST PAS CELLE D'UNE EXTENSION EST REFUSÉE ─────── */
  const hostile = await page.evaluate(async () => {
    for (const url of ['https://exemple.invalid/panneau.html',
                       'javascript:alert(1)',
                       '//exemple.invalid/x']) {
      window.postMessage({ tse: 'tse-url-res', url }, '*');
    }
    await new Promise((r) => setTimeout(r, 80));
    document.getElementById('tse-roue').click();
    await new Promise((r) => setTimeout(r, 60));
    return !!document.getElementById('tse-incruste');
  });
  ok('…et une adresse qui n\'est pas celle d\'une extension est refusée',
     hostile === false, String(hostile));

  /* ── L'ADRESSE DU PONT OUVRE LE CADRE ────────────────────────────────── */
  const ouvert = await page.evaluate(async () => {
    window.postMessage({ tse: 'tse-url-res', url: 'chrome-extension://tse/panneau.html' }, '*');
    await new Promise((r) => setTimeout(r, 60));
    document.getElementById('tse-roue').click();
    await new Promise((r) => setTimeout(r, 60));
    const v = document.getElementById('tse-incruste');
    const cadre = v && v.querySelector('.tse-incruste-cadre');
    const f = v && v.querySelector('iframe');
    const st = cadre && getComputedStyle(cadre);
    return { ouvert: !!v, src: f && f.getAttribute('src'),
             largeur: st && st.width, hauteur: st && st.height,
             role: v && v.getAttribute('role'),
             modal: v && v.getAttribute('aria-modal'),
             nomme: !!(v && v.getAttribute('aria-label')),
             croix: !!(v && v.querySelector('.tse-incruste-croix')),
             /* Le bac à sable retirerait au cadre son origine d'extension,
                donc « chrome.runtime » — c'est-à-dire tout ce que le panneau
                sait faire. Il ne doit pas y en avoir. */
             bacASable: f && f.hasAttribute('sandbox') };
  });
  ok('l\'adresse du pont ouvre le cadre, sur le panneau',
     ouvert.ouvert === true && ouvert.src === 'chrome-extension://tse/panneau.html',
     JSON.stringify(ouvert));
  /* ── LA TAILLE, ET POURQUOI ELLE N'EST PLUS CELLE DE LA POPUP ──────────
     LES DEUX CHEMINS MENAIENT AU MÊME PANNEAU À LA MÊME TAILLE, et c'était le
     contrat de la 4.12. Il a été révisé depuis, sur retour de terrain : la
     popup est bornée à 800 × 600 par le NAVIGATEUR, pas par nous, et imposer
     cette borne au cadre revenait à montrer trois lignes de tableau sur un
     écran qui en offrait vingt. Le cadre prend donc 1100 × 760, et la feuille
     du panneau relâche ses deux nombres quand elle se sait incrustée. */
  ok('…aux dimensions du cadre : 1100 × 760',
     ouvert.largeur === '1100px' && ouvert.hauteur === '760px', JSON.stringify(ouvert));
  /* ET LE PANNEAU REMPLIT CE QU'ON LUI DONNE : sans la règle qui relâche ses
     deux nombres, il resterait une boîte de 760 × 580 dans un coin du cadre. */
  ok('…et la feuille du panneau relâche ses deux nombres en incrustation',
     /html\[data-vue="incruste"\][\s\S]{0,120}width: 100%; height: 100%/
       .test(readFileSync(join(ICI, '..', 'panneau.css'), 'utf8')));
  ok('…annoncé comme fenêtre modale et nommé, et sans croix',
     ouvert.role === 'dialog' && ouvert.modal === 'true'
     && ouvert.nomme === true && ouvert.croix === false, JSON.stringify(ouvert));
  ok('…et sans bac à sable, qui lui retirerait son origine d\'extension',
     ouvert.bacASable === false, JSON.stringify(ouvert));

  /* ── LE CADRE N'A PLUS DE CROIX, ET C'EST MESURÉ ─────────────────────
     UNE MESURE DE POSITION VIVAIT ICI : la croix devait chevaucher le coin
     haut-droit du cadre, traverser ses deux bords, rester dans la fenêtre.
     Elle a été retirée en 4.14 à la demande de l'auteur, et le contrat se
     retourne : ce qu'on exige maintenant, c'est qu'AUCUN bouton ne soit posé
     sur cette fenêtre. Les deux sorties qui restent — Échap et le clic hors
     du cadre — sont éprouvées juste en dessous, séparément. */
  const sansCroix = await page.evaluate(() => {
    const cadre = document.querySelector('.tse-incruste-cadre');
    return { boutons: cadre.querySelectorAll('button').length,
             enfants: [...cadre.children].map((n) => n.tagName.toLowerCase()) };
  });
  ok('le cadre ne porte qu\'un contenu : son panneau, et rien d\'autre',
     sansCroix.boutons === 0
     && JSON.stringify(sansCroix.enfants) === JSON.stringify(['iframe']),
     JSON.stringify(sansCroix));

  /* ── QUATRE SORTIES, ET ELLES ÉCHOUENT SÉPARÉMENT ────────────────────── */
  const sortir = async (geste) => page.evaluate(async (g) => {
    if (!document.getElementById('tse-incruste')) {
      document.getElementById('tse-roue').click();
      await new Promise((r) => setTimeout(r, 60));
    }
    const v = document.getElementById('tse-incruste');
    const f = v.querySelector('iframe');
    if (g === 'echap') {
      document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    } else if (g === 'voile') {
      v.click();
    } else if (g === 'cadre') {
      /* LE CLIC DANS LE CADRE NE DOIT PAS FERMER. C'est l'assertion qui manque
         le plus souvent : un « fermer au clic sur le voile » écrit sans garde
         ferme aussi quand on clique le panneau lui-même. */
      f.click();
    } else if (g === 'message') {
      /* LE CHEMIN DU PANNEAU. Échap frappée DANS le cadre ne remonte pas
         jusqu'ici — deux origines — donc panneau.js le poste au parent. On
         rejoue ce message en nommant sa vraie source. */
      window.dispatchEvent(new MessageEvent('message',
        { data: { tse: 'tse-panneau-fermer' }, source: f.contentWindow }));
    } else if (g === 'imposteur') {
      /* LA MÊME DEMANDE, VENUE D'AILLEURS. Un script de la page qui poste ce
         message ne doit pas pouvoir fermer une fenêtre qu'il n'a pas ouverte. */
      window.dispatchEvent(new MessageEvent('message',
        { data: { tse: 'tse-panneau-fermer' }, source: window }));
    }
    await new Promise((r) => setTimeout(r, 80));
    return !document.getElementById('tse-incruste');
  }, geste);

  ok('le clic DANS le cadre ne ferme pas', (await sortir('cadre')) === false);
  ok('un message de fermeture venu de la page est ignoré',
     (await sortir('imposteur')) === false);
  /* PAS DE CROIX, ET C'EST UNE DEMANDE. La 4.12.2 en avait posé une ; la 4.14
     la retire. On n'efface pas l'assertion pour autant — on la retourne : son
     ABSENCE est désormais le contrat, et les deux sorties qui restent portent
     donc seules la fermeture. Une croix qui reviendrait par inadvertance fait
     tomber celle-ci. */
  ok('aucune croix n\'est posée sur le cadre',
     (await page.evaluate(() => !document.querySelector('.tse-incruste-croix')
        && !document.querySelector('#tse-incruste button'))) === true);
  ok('la touche Échap ferme', (await sortir('echap')) === true);
  ok('le clic sur le voile ferme', (await sortir('voile')) === true);
  ok('…et le panneau lui-même peut demander sa fermeture',
     (await sortir('message')) === true);

  /* ── CE QUI EST POSÉ EST RETIRÉ ──────────────────────────────────────── */
  /* Un écouteur de touche posé sur le document et jamais retiré s'accumule à
     chaque ouverture. Le symptôme n'apparaît qu'après plusieurs allers-retours,
     et il est alors attribué à tout autre chose. */
  const propre = await page.evaluate(async () => {
    for (let i = 0; i < 4; i++) {
      document.getElementById('tse-roue').click();
      await new Promise((r) => setTimeout(r, 40));
      document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
      await new Promise((r) => setTimeout(r, 40));
    }
    return { voiles: document.querySelectorAll('.tse-incruste').length,
             cadres: document.querySelectorAll('.tse-incruste-cadre').length };
  });
  ok('quatre allers-retours ne laissent aucun voile derrière eux',
     propre.voiles === 0 && propre.cadres === 0, JSON.stringify(propre));

  /* ── LE CHEMIN COURT ──────────────────────────────────────────────────
     LE DÉTOUR N'AVAIT DE SENS QUE POUR LA POPUP. Depuis la barre d'outils, le
     panneau demande au service worker, qui demande au pont, qui demande à la
     page : trois sauts, et chacun peut manquer. Incrusté, le panneau EST dans
     la page — et un retour de terrain a montré ce que le détour coûtait :
     « Ouvrez un onglet twitch.tv et mettez-le au premier plan », affiché
     par-dessus la page Twitch qu'il décrivait.

     LE CAS QUI NE SE RÉPARE PAS AUTREMENT : l'extension rechargée pendant que
     la page vit. content.js survit — il n'appelle aucune API d'extension —
     mais bridge.js devient orphelin et ne peut PLUS se rebrancher. Le worker
     n'a alors aucun port pour cet onglet, définitivement.

     ON ÉPROUVE LA MOITIÉ QUI VIT ICI : la page répond à SON cadre, et à lui
     seul. L'autre moitié — le panneau qui pose la question — est éprouvée
     dans son propre scénario, avec un vrai panneau dans un vrai cadre. */
  const court = await page.evaluate(async () => {
    if (!document.getElementById('tse-incruste')) {
      document.getElementById('tse-roue').click();
      await new Promise((r) => setTimeout(r, 60));
    }
    const f = document.querySelector('.tse-incruste-frame');
    /* Le cadre n'a pas pu charger l'adresse d'extension de ce décor : il porte
       donc encore son « about:blank », de même origine, où l'on peut écouter. */
    const w = f.contentWindow;
    const recues = [];
    w.addEventListener('message', (e) => { if (e.data && e.data.tse === 'tse-incruste-res') recues.push(e.data); });
    window.dispatchEvent(new MessageEvent('message', {
      data: { tse: 'tse-incruste-req', id: 7, section: 'roster' }, source: w }));
    await new Promise((r) => setTimeout(r, 250));
    /* LA MÊME DEMANDE, VENUE D'AILLEURS. Un script de la page ne doit pas
       pouvoir se faire servir par un cadre qu'il n'a pas ouvert. */
    window.dispatchEvent(new MessageEvent('message', {
      data: { tse: 'tse-incruste-req', id: 8, section: 'roster' }, source: window }));
    await new Promise((r) => setTimeout(r, 250));
    return { combien: recues.length, premiere: recues[0] || null };
  });
  ok('la page sert son cadre directement, sans worker ni pont',
     court.combien === 1 && !!court.premiere && court.premiere.id === 7
     && court.premiere.ok === true && !!court.premiere.data,
     JSON.stringify(court).slice(0, 220));
  ok('…et une demande venue de la page elle-même n\'est pas servie',
     court.combien === 1, String(court.combien));

  /* ── ET DEUX CLICS NE FONT PAS DEUX CADRES ───────────────────────────── */
  const double = await page.evaluate(async () => {
    document.getElementById('tse-roue').click();
    document.getElementById('tse-roue').click();
    await new Promise((r) => setTimeout(r, 80));
    return document.querySelectorAll('.tse-incruste').length;
  });
  ok('…et deux clics de suite n\'ouvrent qu\'un seul cadre',
     double === 1, String(double));
  await page.close();
}

/* ═════════ LE PREMIER LANCEMENT ══════════════════════════════════════════
   La roue est là pour tout le monde ; le BATTEMENT et la BULLE ne sont là que
   pour une installation neuve. Sa difficulté n'est pas de s'afficher, c'est de
   ne s'afficher qu'aux nouveaux et de ne pas disparaître au second chargement.

   content.js ne peut pas savoir qu'une installation vient d'avoir lieu — le
   service worker, seul à le savoir, en est séparé par deux mondes. Il reconnaît
   l'inverse : une mémoire déjà remplie prouve une ANCIENNETÉ. Or cette mémoire
   se remplit en quelques secondes, d'où la règle qui fait tout tenir — la
   décision se prend UNE FOIS et s'écrit. */
{
  titre('123. Le premier lancement — la roue bat, la bulle désigne, une seule fois');

  const page = await fresh();
  const poser = () => page.evaluate(() => {
    window.__fx = { alpha: { id: 'a', createdAt: new Date(Date.now() - 3600e3).toISOString(),
                             viewers: 900, game: 'G', tags: [] } };
    window.__addCard('alpha', 'G', '900');
  });
  const etat = () => page.evaluate(() => {
    const r = document.getElementById('tse-roue');
    const b = document.getElementById('tse-bulle');
    return { neuf: r && r.getAttribute('data-tse-neuf'),
             anime: r ? getComputedStyle(r).animationName : null,
             bulle: !!b,
             titre: b ? b.querySelector('.tse-bulle-titre').textContent : null,
             texte: b ? b.querySelector('.tse-bulle-texte').textContent : null,
             /* SUR LE CORPS, PAS DANS LA BARRE : c'est ce qui lui permet de
                déborder sur le site plutôt que d'hériter des 240 px de la
                barre et de tout ce qui la rogne. */
             surLeCorps: b ? b.parentElement === document.body : null,
             croix: b ? !!b.querySelector('.tse-bulle-croix[aria-label]') : null,
             fleche: b ? !!b.querySelector('.tse-bulle-fleche[aria-hidden="true"]') : null,
             cle: localStorage.getItem('tse:roue'),
             vieilleCle: localStorage.getItem('tse:accueil'),
             roster: !!localStorage.getItem('tse:roster') };
  });

  /* ── ASSERTION TOURNÉE PAR UN RETOUR DE TERRAIN ───────────────────────
     Elle exigeait l'inverse : « une mémoire déjà remplie vaut ancienneté,
     donc ni bulle ni battement ». C'était juste pour le bandeau de la 4.11,
     qui annonçait une icône vieille de plusieurs versions ; c'est FAUX pour la
     roue, qui n'existait pas la veille.

     CE QUE LA MESURE A MONTRÉ : réinstaller l'extension n'efface pas le
     localStorage de twitch.tv. Un utilisateur de longue date restait donc
     classé « ancien » à jamais et ne voyait jamais la bulle, quel que soit le
     nombre de réinstallations — c'est-à-dire exactement la personne à qui il
     fallait annoncer la roue. Le signal porte désormais sa propre clé : ce
     qu'on retient n'est plus l'âge de l'utilisateur, c'est ce qu'il a vu. */
  await page.evaluate(() => {
    localStorage.clear();
    localStorage.setItem('tse:roster', JSON.stringify({ v: 1, m: { alpha: Date.now() } }));
    /* La clé du bandeau de la 4.11, laissée par une version précédente. Elle
       ne doit plus rien décider — et elle doit disparaître au passage. */
    localStorage.setItem('tse:accueil', 'vu');
  });
  await page.reload();
  await poser();
  await wait(page, 1500);
  const ancien = await etat();
  ok('un roster rempli et l\'ancien bandeau renvoyé n\'empêchent plus le signal',
     ancien.bulle === true && ancien.neuf === 'true' && ancien.cle === 'montre',
     JSON.stringify(ancien));
  ok('…et la clé morte du bandeau de la 4.11 est retirée du stockage',
     ancien.vieilleCle === null, JSON.stringify(ancien.vieilleCle));

  /* ── UNE MÉMOIRE VIDE LE VOIT AUSSI, ÉVIDEMMENT ──────────────────────── */
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await poser();
  await wait(page, 1500);
  const neuf = await etat();
  ok('clé absente vaut signal jamais montré : la roue bat',
     neuf.neuf === 'true' && neuf.anime === 'tse-roue-bat' && neuf.cle === 'montre',
     JSON.stringify(neuf));
  ok('…et la bulle est là, avec sa flèche muette et une croix nommée',
     neuf.bulle === true && neuf.fleche === true && neuf.croix === true,
     JSON.stringify(neuf));
  /* LE LIBELLÉ VIENT DE LA TABLE DE LANGUE. Une phrase écrite dans la fonction
     ne serait traduite nulle part, et cette bulle s'adresse d'abord à quelqu'un
     qui ne sait pas encore ce qu'il vient d'installer. */
  ok('…son titre et son texte viennent de la table de langue, pas d\'identifiants',
     typeof neuf.titre === 'string' && neuf.titre.length > 10
     && typeof neuf.texte === 'string' && neuf.texte.length > 40
     && !/^ui[A-Z]/.test(neuf.titre) && !/^ui[A-Z]/.test(neuf.texte),
     JSON.stringify([neuf.titre, neuf.texte]));
  ok('…et elle est posée sur le corps du document, pas dans la barre',
     neuf.surLeCorps === true, JSON.stringify(neuf.surLeCorps));

  /* ── LA FLÈCHE DÉSIGNE LA ROUE, ET C'EST MESURÉ ──────────────────────── */
  /* UN DÉCALAGE ÉCRIT EN DUR NE POUVAIT PAS MARCHER, et il a fallu une mesure
     pour le voir : la bulle se place par rapport à la BARRE, la roue par
     rapport au rembourrage que TWITCH donne à son titre. Relevé avant
     correction : flèche à 223 px, centre de la roue à 234,5 — elle désignait le
     bord du bouton. */
  const vise = await page.evaluate(() => {
    const c = (e) => { const r = e.getBoundingClientRect(); return r.left + r.width / 2; };
    const roue = document.getElementById('tse-roue');
    const fleche = document.querySelector('.tse-bulle-fleche');
    const bulle = document.getElementById('tse-bulle');
    const rb = bulle.getBoundingClientRect();
    const rbar = document.querySelector('#side-nav').getBoundingClientRect();
    return { ecart: Math.abs(c(roue) - c(fleche)),
             /* ELLE DOIT DÉBORDER SUR LE SITE, et c'est une demande explicite :
                enfermée dans les 240 px de la barre, la phrase s'empilait sur
                quatre lignes de même poids. On mesure donc les deux bords —
                celui qui s'appuie sur la barre, et celui qui la dépasse. */
             largeur: Math.round(rb.width),
             depasse: Math.round(rb.right - rbar.right),
             alignee: Math.round(rb.left - rbar.left),
             /* Elle ne doit pas sortir de la fenêtre pour autant. */
             dansLaFenetre: rb.right <= window.innerWidth && rb.left >= 0,
             /* Au-dessus de la bulle, sinon elle ne désigne rien : une flèche
                posée à l'intérieur d'un bloc de la même couleur est invisible. */
             auDessus: fleche.getBoundingClientRect().top < bulle.getBoundingClientRect().top,
             /* Et sous la roue : la bulle est ce qui explique le bouton, elle
                ne peut pas le recouvrir. */
             sousLaRoue: bulle.getBoundingClientRect().top
                       >= roue.getBoundingClientRect().bottom - 1 };
  });
  ok('la flèche vise le centre de la roue, à quelques pixels près',
     vise.ecart <= 6, JSON.stringify(vise));
  ok('la bulle s\'appuie sur le bord gauche de la barre, sans sortir de la fenêtre',
     vise.alignee === 0 && vise.largeur === 330
     && vise.dansLaFenetre === true, JSON.stringify(vise));

  /* ── LE DÉBORDEMENT, MESURÉ À LA VRAIE LARGEUR DE LA BARRE ─────────────
     ASSERTION REFAITE, ET L'ERREUR EST INSTRUCTIVE. La première exigeait que
     la bulle dépasse le bord droit de « #side-nav » — et ce décor-ci n'a pas
     la feuille de Twitch : sa barre prend TOUTE la page, donc une carte de
     330 px ne dépassait rien du tout. Relevé : « depasse: -934 ». L'assertion
     ne mesurait pas le produit, elle mesurait le décor.

     ON POSE DONC LA LARGEUR RÉELLE — deux cent quarante pixels, celle de la
     barre de Twitch — le temps de la mesure. C'est le seul endroit du banc qui
     en a besoin, et le dire ici vaut mieux que de la poser partout : les
     autres scénarios mesurent des cartes, pas des débordements. */
  const deborde = await page.evaluate(async () => {
    const barre = document.querySelector('#side-nav');
    const avant = barre.style.width;
    barre.style.width = '240px';
    /* On attend la passe suivante : c'est elle qui replace la bulle. */
    await new Promise((r) => setTimeout(r, 1600));
    const rb = document.getElementById('tse-bulle').getBoundingClientRect();
    const rbar = barre.getBoundingClientRect();
    const mesure = { largeurBarre: Math.round(rbar.width),
                     depasse: Math.round(rb.right - rbar.right),
                     dansLaFenetre: rb.right <= window.innerWidth };
    barre.style.width = avant;
    return mesure;
  });
  ok('…et à la largeur réelle de la barre, elle déborde franchement sur le site',
     deborde.largeurBarre === 240 && deborde.depasse > 40
     && deborde.dansLaFenetre === true, JSON.stringify(deborde));
  ok('…elle dépasse au-dessus de la bulle, et la bulle est sous la roue',
     vise.auDessus === true && vise.sousLaRoue === true, JSON.stringify(vise));

  /* ── LA DÉCISION SURVIT AU REMPLISSAGE DE LA MÉMOIRE ─────────────────── */
  await page.reload();
  await poser();
  await wait(page, 1500);
  const second = await etat();
  /* C'EST L'ASSERTION QUI TIENT TOUT LE MÉCANISME. Sans la décision écrite, le
     roster se remplit en quelques secondes, l'ancienneté devient vraie au
     chargement suivant, et la bulle n'aurait été montrée qu'à ceux qui
     regardaient l'écran à la bonne seconde. */
  ok('le roster s\'est rempli entre-temps, et la bulle reste : la décision est écrite',
     second.roster === true && second.bulle === true && second.cle === 'montre',
     JSON.stringify(second));

  /* ── LA CROIX LA RENVOIE, ET LE BATTEMENT S'ARRÊTE AVEC ELLE ─────────── */
  const apres = await page.evaluate(async () => {
    document.querySelector('.tse-bulle-croix').click();
    await new Promise((r) => setTimeout(r, 60));
    const r = document.getElementById('tse-roue');
    return { bulle: !!document.getElementById('tse-bulle'),
             neuf: r.getAttribute('data-tse-neuf'),
             anime: getComputedStyle(r).animationName,
             /* La roue RESTE : ce qu'on renvoie est le signal, pas le chemin. */
             roue: !!r,
             cle: localStorage.getItem('tse:roue') };
  });
  ok('la croix retire la bulle, arrête le battement, et garde la roue',
     apres.bulle === false && apres.neuf === null && apres.anime === 'none'
     && apres.roue === true && apres.cle === 'vu', JSON.stringify(apres));

  await page.reload();
  await poser();
  await wait(page, 1500);
  const jamais = await etat();
  ok('…et rien ne revient au rechargement suivant',
     jamais.bulle === false && jamais.neuf === null, JSON.stringify(jamais));

  /* ── UNE ROUE SANS SURFACE EMPORTE LA BULLE ──────────────────────────
     COLONNE RÉDUITE, ET C'EST LE CAS QUE LA POSITION FIXE A CRÉÉ. Tant que la
     bulle vivait DANS la barre, deux règles de feuille la masquaient avec
     elle. Posée sur le corps du document, elle n'a plus de parent pour la
     cacher à notre place : une barre repliée laisserait une carte flottant au
     milieu de l'écran, pointant vers un bouton qui n'existe plus. */
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await poser();
  await wait(page, 1500);
  const repliee = await page.evaluate(async () => {
    const avant = !!document.getElementById('tse-bulle');
    /* On retire sa surface à la roue, comme le fait le repli de la barre. */
    document.querySelector('#side-nav .side-nav__title').style.display = 'none';
    await new Promise((r) => setTimeout(r, 1600));
    return { avant, apres: !!document.getElementById('tse-bulle') };
  });
  ok('une roue sans surface — barre repliée — emporte la bulle avec elle',
     repliee.avant === true && repliee.apres === false, JSON.stringify(repliee));

  /* ── LE CLIC SUR LA ROUE VAUT LECTURE ────────────────────────────────── */
  /* Quelqu'un qui ouvre le panneau a trouvé la roue. Continuer à la faire
     battre serait insister après coup. */
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await poser();
  await wait(page, 1500);
  const parLaRoue = await page.evaluate(async () => {
    const avant = !!document.getElementById('tse-bulle');
    document.getElementById('tse-roue').click();
    await new Promise((r) => setTimeout(r, 60));
    return { avant, bulle: !!document.getElementById('tse-bulle'),
             neuf: document.getElementById('tse-roue').getAttribute('data-tse-neuf'),
             cle: localStorage.getItem('tse:roue') };
  });
  ok('ouvrir le panneau par la roue renvoie le signal aussi',
     parLaRoue.avant === true && parLaRoue.bulle === false
     && parLaRoue.neuf === null && parLaRoue.cle === 'vu', JSON.stringify(parLaRoue));

  /* ── MOUVEMENT RÉDUIT : DEUX PAGES CÔTE À CÔTE, RIEN NE DOIT LES SÉPARER ─
     CETTE ANIMATION EST DU MOUVEMENT AU SENS STRICT — un changement de TAILLE,
     ce que la WCAG appelle l'illusion d'un déplacement — et jusqu'à la 4.14.0
     une règle l'éteignait ici. Le produit n'en pose plus une seule : la
     mouture Firefox ne l'avait jamais reçue, les deux ont été comparées, et
     c'est celle sans règle qui a été retenue.

     ON GARDE POURTANT LE PIÈGE QUI JUSTIFIAIT CE BLOC. La règle du battement
     vit PLUS BAS dans la feuille, à spécificité égale : c'est exactement la
     configuration qui a fait passer l'arc-en-ciel du subathon à travers ce
     réglage pendant deux versions, dans un sens comme dans l'autre. Deux pages
     identiques à la préférence près, et l'exigence que leur battement porte le
     même nom et la même durée, prennent ce piège quel que soit le sens.

     L'AMPLITUDE BALAYÉE, PAS LA MATRICE INSTANTANÉE : deux pages n'en sont
     jamais à la même phase du cycle, et comparer deux transformations lues
     d'un coup ne mesurerait que l'instant où on les a lues. */
  const roueSous = async (mouvement) => {
    const p = await browser.newPage();
    p.on('pageerror', (e) => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
    await p.emulateMedia({ reducedMotion: mouvement });
    await p.goto(URL_PAGE);
    await p.evaluate(() => localStorage.clear());
    await p.reload();
    await p.evaluate(() => {
      window.__fx = { alpha: { id: 'a', createdAt: new Date(Date.now() - 3600e3).toISOString(),
                               viewers: 900, game: 'G', tags: [] } };
      window.__addCard('alpha', 'G', '900');
    });
    await wait(p, 1500);
    const vu = await p.evaluate(async () => {
      const r = document.getElementById('tse-roue');
      const st = getComputedStyle(r);
      /* L'AMPLITUDE SE BALAIE, ELLE NE SE LIT PAS D'UN COUP. Une seule lecture
         de la matrice ne dit que la phase où on est tombé, et le cycle repasse
         par l'identité deux fois par tour : l'assertion tiendrait ou tomberait
         au hasard de la milliseconde. On balaie un cycle entier et on garde
         les deux extrêmes. */
      const ech = [];
      const duree = parseFloat(st.animationDuration) * 1000 || 1600;
      const fin = performance.now() + duree * 1.1;
      while (performance.now() < fin) {
        ech.push(new DOMMatrixReadOnly(getComputedStyle(r).transform).a);
        await new Promise(requestAnimationFrame);
      }
      return { neuf: r.getAttribute('data-tse-neuf'), anime: st.animationName,
               duree: st.animationDuration, tours: st.animationIterationCount,
               eMin: +Math.min(...ech).toFixed(4), eMax: +Math.max(...ech).toFixed(4),
               /* LA ROTATION AU SURVOL EST DU MOUVEMENT ELLE AUSSI ; elle n'est
                  pas un signal, elle accuse réception du pointeur. */
               rotation: getComputedStyle(r.querySelector('.tse-roue-dent')).transitionDuration,
               /* Ce qui DIT, par opposition à ce qui bouge. Une roue qui
                  perdrait son halo ne signalerait plus rien du tout. */
               halo: st.boxShadow,
               bulle: !!document.getElementById('tse-bulle') };
    });
    await p.close();
    return vu;
  };
  const calme = await roueSous('reduce');
  const vif = await roueSous('no-preference');
  ok('mouvement réduit : le battement de la roue est le même qu\'en mouvement libre',
     calme.anime === vif.anime && calme.duree === vif.duree
     && calme.tours === vif.tours && calme.rotation === vif.rotation,
     JSON.stringify({ calme, vif }));
  // Et c'est bien un battement, pas deux fois rien : l'égalité seule serait
  // vraie aussi si les deux pages étaient également immobiles.
  ok('…et c\'est un vrai battement, nommé et d\'amplitude mesurable',
     calme.anime === 'tse-roue-bat' && parseFloat(calme.duree) > 0
     && calme.eMax - calme.eMin >= 0.02,
     JSON.stringify({ anime: calme.anime, duree: calme.duree,
                      amplitude: +(calme.eMax - calme.eMin).toFixed(4) }));
  // La MÊME amplitude des deux côtés, pas seulement la même déclaration :
  // c'est ce que l'œil voit, et c'est là que la règle supprimée agissait.
  ok('…et la même amplitude en mouvement réduit qu\'en mouvement libre',
     Math.abs((calme.eMax - calme.eMin) - (vif.eMax - vif.eMin)) < 0.01,
     JSON.stringify({ calme: [calme.eMin, calme.eMax], vif: [vif.eMin, vif.eMax] }));
  ok('…et le signal reste : la roue est marquée, son halo est posé, la bulle est là',
     calme.neuf === 'true' && /rgba?\(/.test(calme.halo) && calme.bulle === true,
     JSON.stringify(calme));
  await page.close();
}

/* ═════════ LE PANNEAU DANS UN CADRE, SANS ONGLET NI WORKER ═══════════════
   L'AUTRE MOITIÉ DU CHEMIN COURT. Le scénario 122 éprouve la page qui répond ;
   celui-ci éprouve le panneau qui demande — et il le fait dans les conditions
   EXACTES de la panne signalée : `tabs.query` ne rend AUCUN onglet, et
   `runtime.sendMessage` échoue. C'est ce que voit un panneau dont l'extension
   a été rechargée pendant que la page vivait.

   AVANT LA 4.13, CE DÉCOR DONNAIT « ouvrez un onglet twitch.tv ». Le panneau
   ne doit plus jamais le dire quand il est DANS la page qu'il décrit. */
{
  titre('124. Le panneau incrusté — il parle à la page, pas au worker');

  const messages = JSON.parse(readFileSync(join(ICI, '..', '_locales', 'fr', 'messages.json'), 'utf8'));
  const hote = join(ICI, 'cadre-tmp.html');
  /* Un hôte minimal : un cadre, et un répondant. Il tient le rôle que content.js
     tient sur une vraie page, et rien de plus — ce qu'on éprouve ici est le
     panneau, pas la page. */
  writeFileSync(hote, `<!DOCTYPE html><meta charset="utf-8"><body>
<iframe id="f" src="../panneau.html" style="width:1100px;height:760px;border:0"></iframe>
<script>
window.__vues = [];
addEventListener('message', (e) => {
  const d = e.data;
  if (!d || d.tse !== 'tse-incruste-req') return;
  window.__vues.push(d);
  e.source.postMessage({ tse: 'tse-incruste-res', id: d.id, ok: true,
                         data: { colonnes: ['login'], lignes: [], resume: {} } }, '*');
});
</script></body>`);

  const page = await browser.newPage({ viewport: { width: 1400, height: 900 } });
  page.on('pageerror', (e) => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
  await page.addInitScript((msg) => {
    window.chrome = {
      i18n: { getMessage: (k, sub) => {
          const m = msg[k] ? msg[k].message : k;
          if (sub === undefined || sub === null) return m;
          const args = Array.isArray(sub) ? sub : [sub];
          return String(m).replace(/\$(\d)/g,
            (t, i) => (args[i - 1] === undefined ? t : String(args[i - 1])));
        }, getUILanguage: () => 'fr' },
      /* AUCUN onglet, AUCUN worker : la panne du terrain, reproduite. */
      tabs: { query: () => Promise.resolve([]) },
      runtime: { getManifest: () => ({ version: '9.9.9' }),
                 sendMessage: () => Promise.reject(new Error('worker absent')) },
    };
  }, messages);
  await page.goto(pathToFileURL(hote).href);
  await attendre(page, () => !!document.getElementById('f'), 6000);
  await wait(page, 1200);

  const cadre = () => page.frames().find((f) => f.url().includes('panneau.html'));
  const dedans = await cadre().evaluate(() => ({
    vue: document.documentElement.getAttribute('data-vue'),
    rail: document.querySelectorAll('.rail-item').length,
  }));
  ok('le panneau encadré se reconnaît incrusté, et se peint',
     dedans.vue === 'incruste' && dedans.rail > 0, JSON.stringify(dedans));
  /* IL REMPLIT LE CADRE. Sans la règle qui relâche ses deux nombres, il
     resterait une boîte de 760 × 580 dans un coin de 1100 × 760. */
  const taille = await cadre().evaluate(() => [document.body.clientWidth,
                                               document.body.clientHeight]);
  ok('…et il remplit le cadre au lieu de rester à la taille d\'une popup',
     taille[0] === 1100 && taille[1] === 760, JSON.stringify(taille));

  /* Le mode d'emploi ne demande RIEN à personne : c'est une section de données
     qu'il faut ouvrir pour voir passer une demande. */
  await cadre().evaluate(() => {
    const b = [...document.querySelectorAll('.rail-item')].find((x) => x.dataset.id === 'roster');
    if (b) b.click();
  });
  await wait(page, 800);
  const vu = await page.evaluate(() => window.__vues.length);
  ok('…il demande à la PAGE, sans onglet actif ni service worker',
     vu >= 1, String(vu));

  const message = await cadre().evaluate(() => {
    const m = document.getElementById('message');
    return m.hidden ? null : document.getElementById('message-texte').textContent;
  });
  /* CE QU'IL NE DOIT PLUS DIRE. Le message affiché — s'il y en a un — est celui
     d'un jeu de données vide, pas celui d'un onglet introuvable : toute la
     différence entre « la page a répondu, elle n'a rien » et « je n'ai trouvé
     personne à qui parler ». */
  ok('…et n\'annonce plus « ouvrez un onglet twitch.tv » par-dessus Twitch',
     typeof message === 'string' && !/twitch\.tv/i.test(message)
     && !/onglet|tab\b/i.test(message), JSON.stringify(message));

  await page.close();
  rmSync(hote, { force: true });
}

/* ═════════ UNE RÉPONSE TRONQUÉE NE JUGE QUE CE QU'ELLE CONTENAIT ═════════
   LE DÉFAUT QU'UN RAPPORT DE TERRAIN A RÉVÉLÉ : « KyriaTV a disparu alors
   qu'elle était présente au tout début ». Elle n'était pas terminée — elle
   avait été ÉVINCÉE.

   TOUTES LES SOURCES DU CLASSEMENT SONT DES « TOP N ». La voie du tag demande
   les GLOBAL_TAG_MAX premières du monde ; la descente demande les
   GLOBAL_STREAMS_MAX premières de CHAQUE catégorie. Le pool, lui, en contient
   des centaines — 283 relevées chez l'utilisateur contre trente rendues par le
   tag. Sans plancher, chaque passe donnait donc une absence à deux cent
   cinquante chaînes bien vivantes, au seul motif qu'elles vivent sous le
   trentième rang. Trois passes, et tout ce qui est sous ce rang est évincé.

   « EN LICE » N'EST PAS « REGARDÉE ». Le raisonnement d'origine tenait que la
   requête du tag étant une, globale et ordonnée, une absence y était réelle.
   Le trou : être en lice et PERDRE ne dit rien d'autre que « je suis sous le
   rang trente ». */
{
  titre('125. Le classement — une réponse tronquée ne juge que ce qu\'elle contenait');

  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 30 * 60_000).toISOString();
    window.__fx = { suivi1: { id: 'id-suivi1', createdAt: h, viewers: 400,
                              game: 'Just Chatting', tags: [] } };
    window.__addCard('suivi1', 'Just Chatting', '400');
    const cats = [];
    for (let i = 0; i < 4; i++) {
      const streams = [];
      for (let k = 0; k < 30; k++) {
        streams.push({ login: `en${i}_${k}`, viewers: 9000 - i * 100 - k, tags: ['English'] });
      }
      cats.push({ name: 'c' + i, viewers: 500_000 - i, streams });
    }
    /* Deux chaînes françaises MODESTES. Elles entrent au pool par la descente
       — leur catégorie n'a qu'elles, la réponse est donc exhaustive — et se
       trouvent très en dessous du plancher du classement par tag. */
    cats.push({ name: 'frcat', viewers: 499_000, streams: [
      { login: 'petite1', viewers: 100, tags: ['Français'] },
      { login: 'petite2', viewers: 90,  tags: ['Français'] },
    ] });
    window.__cats = cats;
    /* Un classement par tag PLEIN — trente entrées, comme GLOBAL_TAG_MAX —
       dont la plus basse est à 1 000. C'est ce qui en fait une réponse
       TRONQUÉE : elle s'est arrêtée avant d'arriver aux petites. */
    const top = [];
    for (let k = 0; k < 30; k++) {
      top.push({ login: `fr${k}`, viewers: 5000 - k * 100, tags: ['Français'] });
    }
    window.__tagTop = { 'Français': top };
  });
  await wait(page, 2500);
  await page.evaluate(() => {
    const b = [...document.querySelectorAll('.tse-mode-tab')].find(x => x.dataset.tseMode === 'global');
    if (b) b.click();
  });
  await wait(page, 2500);
  await page.evaluate(() => {
    const opt = [...document.querySelectorAll('#tse-lang-dd .tse-dd-opt')]
      .find(o => (o.dataset.value || '') === 'Français');
    if (opt) opt.click();
  });
  await wait(page, 3500);

  const g = await page.evaluate(() => {
    const r = window.tse.global.report();
    return { misses: r.misses, sousPlancher: r.sousPlancher, evicted: r.evicted,
             tagsServis: r.tags.servis,
             petites: window.tse.global.top(500)
               .filter((x) => x.login.startsWith('petite')).map((x) => x.login) };
  });
  ok('la voie du tag a bien répondu — sans quoi rien de ce qui suit ne prouve rien',
     g.tagsServis > 0, JSON.stringify(g));
  /* LE COMPTEUR QUI AURAIT MONTRÉ LE DÉFAUT SANS ATTENDRE UN RAPPORT. Il
     compte les absences qu'on REFUSE de compter : la réponse s'arrêtait avant
     d'arriver jusqu'à ces chaînes. */
  ok('les chaînes sous le plancher de la réponse ne prennent AUCUNE absence',
     g.misses === 0 && g.sousPlancher >= 2, JSON.stringify(g));
  ok('…elles restent donc au classement, et rien n\'est évincé',
     g.evicted === 0 && g.petites.length === 2, JSON.stringify(g));
  await page.close();
}

/* ═════════ LE CACHE AVANT/ARRIÈRE ════════════════════════════════════════
   LACUNE TROUVÉE PAR AUDIT, et le dépôt avait déjà payé la même ailleurs :
   bridge.js écoute « pagehide » et « pageshow » depuis qu'un rapport
   d'utilisateur a montré un port mort pour le reste de la vie de la page. Dans
   content.js, rien ne les écoutait.

   CE QUE ÇA DONNAIT : on quitte Twitch, on revient par le bouton Précédent. Le
   navigateur restaure la page telle qu'elle était, DOM gelé compris. Nos
   minuteurs étaient à l'arrêt, le cycle de re-fetch en pause, et Twitch n'a
   rien pu muter puisqu'il n'y avait plus d'yeux. La barre revenait avec les
   compteurs d'il y a une heure et des chaînes terminées présentées en direct.

   ET « visibilitychange » NE LE RATTRAPE PAS À COUP SÛR : une page restaurée
   depuis ce cache peut revenir sans que la visibilité ait changé de valeur.

   PLAYWRIGHT NE SAIT PAS DÉCLENCHER UNE VRAIE RESTAURATION, et c'est dit :
   l'événement est rejoué à la main. Ce qu'on éprouve est donc la RÉACTION à
   cet événement, pas le fait que le navigateur l'émette — ce dernier point est
   une propriété de la plateforme, pas du produit. */
{
  titre('126. Le cache avant/arrière — une page restaurée est une page périmée');

  const page = await fresh();
  await page.evaluate(() => {
    window.__fx = { alpha: { id: 'a', createdAt: new Date(Date.now() - 3600e3).toISOString(),
                             viewers: 900, game: 'G', tags: [] } };
    window.__addCard('alpha', 'G', '900');
  });
  await wait(page, 2500);

  const motifs = () => page.evaluate(() =>
    window.tse.panneau.rapport().journaux.cycles.map((x) => x.detail || x.evt));

  const avant = await motifs();
  const restaure = await page.evaluate(async () => {
    window.dispatchEvent(new PageTransitionEvent('pageshow', { persisted: true }));
    await new Promise((r) => setTimeout(r, 400));
    return window.tse.panneau.rapport().journaux.cycles.map((x) => x.detail || x.evt);
  });
  ok('une page restaurée depuis le cache pose le voile et repeuple',
     restaure.length > avant.length
     && restaure.some((m) => /cache avant/.test(m || '')),
     JSON.stringify(restaure));

  /* `persisted` DISTINGUE LES DEUX « pageshow ». Au chargement ordinaire il
     vaut false, et le démarrage a déjà tout fait : refaire tomber le voile
     là-dessus serait un clignotement à chaque ouverture de page. */
  const ordinaire = await page.evaluate(async () => {
    const n = window.tse.panneau.rapport().journaux.cycles.length;
    window.dispatchEvent(new PageTransitionEvent('pageshow', { persisted: false }));
    await new Promise((r) => setTimeout(r, 400));
    return { n, apres: window.tse.panneau.rapport().journaux.cycles.length };
  });
  ok('…et un « pageshow » ordinaire ne déclenche rien',
     ordinaire.n === ordinaire.apres, JSON.stringify(ordinaire));

  /* LE VOILE SE LÈVE. Un voile posé et jamais levé est pire que pas de voile :
     la barre reste masquée sur une page que l'utilisateur regarde. */
  await attendre(page, () => !document.body.classList.contains('tse-loading'), 8000);
  ok('…et le voile se lève de lui-même une fois la barre stable',
     await page.evaluate(() => !document.body.classList.contains('tse-loading')));
  await page.close();
}

/* ═════════ UN SÉLECTEUR MORT NE DOIT PAS RENDRE « ZÉRO » EN SILENCE ══════
   LE RAPPORT : « le système de récupération des abonnements ne fonctionne
   plus, je fais le bouton et rien ne se passe. » Le relevé tournait pourtant —
   horodatage à jour, « en attente : false » — et rendait ZÉRO sur un compte
   qui portait douze abonnements une heure plus tôt.

   LE GARDE-FOU EXISTAIT, ET IL ÉTAIT AVEUGLE. Il jugeait sur la MÉMOIRE :

       if (!trouves.length) { const connus = …; if (connus) erreurs.noter(…) }

   « zéro trouvé, zéro connu » étant le compte de quelqu'un sans abonnement, il
   se taisait — et la mémoire venait justement d'être effacée. Deux pannes
   rendaient le même chiffre, et une seule était dite.

   LA PAGE SAIT MIEUX QUE NOUS, ET C'EST LE SEUL TÉMOIN QUI TIENNE. Un onglet
   qui s'est AFFICHÉ — sa barre latérale est là, donc l'application de Twitch
   est debout — et où le sélecteur n'accroche RIEN ne décrit pas un compte
   vide. Ce verdict ne dépend d'aucune mémoire, donc aucun effacement ne peut
   l'aveugler.

   PUIS UN SECOND RAPPORT A MONTRÉ QU'IL Y AVAIT DEUX CAUSES, PAS UNE. La page
   affichait, en toutes lettres, « Impossible d'afficher vos abonnements pour
   le moment » : sa PROPRE requête avait échoué. Zéro carte, page parfaitement
   rendue, et notre sélecteur parfaitement valide. Accuser le sélecteur là
   aurait envoyé la recherche exactement du mauvais côté.

   D'OÙ LE TÉMOIN SUPPLÉMENTAIRE : ce que Twitch a ÉCRIT à la place des
   cartes. Quand il écrit quelque chose, on le recopie et on s'arrête là —
   aucune déduction de notre part ne vaut la phrase de la page. Les deux décors
   ci-dessous ne diffèrent QUE par cela, et le relevé doit les séparer. */
{
  titre('127. Abonnements — zéro carte, deux causes, et le relevé les sépare');

  const PLAYER = '<!doctype html><html><body>x</body></html>';
  const amorcer = () => {
    /* MÉMOIRE VIDE, comme après un « Effacer l'historique » — la condition
       exacte dans laquelle l'ancien garde-fou se taisait. */
    localStorage.clear();
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = { omofficial: { id: '1', createdAt: h, viewers: 500, game: 'G', tags: [] } };
    window.__addCard('omofficial', 'G', '500');
  };
  const relever = async (p) => {
    await p.evaluate(amorcer);
    await attendre(p, () => !!localStorage.getItem('tse:substs'), 25_000);
    return p.evaluate(() => {
      const r = window.tse.panneau.rapport();
      return { onglets: r.relevesAbonnements.onglets || [],
               connus: window.tse.panneau('subs').lignes.length,
               erreurs: r.erreurs.map((e) => `${e.message || ''} ${e.detail || ''}`) };
    });
  };

  /* ── 1. LE SÉLECTEUR MORT ────────────────────────────────────────────────
     Twitch renomme son attribut : la page rend EXACTEMENT les mêmes cartes,
     sous un autre nom, et n'écrit aucun message. */
  const RENOMME = () => { window.__subCardAttr = 'subscription-card-v2'; };
  const pageMorte = await freshTwitch(PLAYER, [], '/', RENOMME);
  const vu = await relever(pageMorte);

  /* CE QUE LE BILAN DOIT PORTER, et c'est lui qui rend les pannes
     distinguables : une page qui n'a jamais chargé n'a pas montré sa barre ;
     une page affichée, barre présente, zéro carte, est autre chose. */
  const affiches = vu.onglets.filter((o) => o.charge && o.barre && o.noeuds > 0);
  ok('le bilan dit, onglet par onglet, ce que la page a montré',
     vu.onglets.length >= 3 && affiches.length >= 1,
     JSON.stringify(vu.onglets));
  ok('…les onglets se sont bien affichés, et n\'ont rendu aucune carte',
     affiches.length >= 1 && affiches.every((o) => o.cartes === 0),
     JSON.stringify(affiches));
  /* L'ASSERTION QUI TIENT TOUT : la mémoire est vide, donc l'ancien verdict se
     taisait. Le nouveau parle quand même, parce qu'il regarde la page. */
  ok('…et le relevé le DIT, alors même que la mémoire était vide',
     vu.connus === 0
     && vu.erreurs.some((e) => /aucun ne rend/.test(e) && /subscription-card/.test(e)),
     JSON.stringify(vu.erreurs));
  await pageMorte.close();

  /* ── 2. LA PAGE QUE TWITCH REFUSE DE SERVIR ──────────────────────────────
     Le sélecteur est INTACT. La page s'affiche, et met un message là où les
     cartes auraient dû être. Le relevé rend zéro — correctement — et doit
     recopier la phrase plutôt que d'inventer un coupable. */
  const PHRASE = 'Impossible d\'afficher vos abonnements pour le moment.';
  const REFUS = () => {
    window.__subsMessage = 'Impossible d\'afficher vos abonnements pour le moment.';
  };
  const pageRefus = await freshTwitch(PLAYER, [], '/', REFUS);
  const vu2 = await relever(pageRefus);
  const muets = vu2.onglets.filter((o) => o.charge && o.barre);

  ok('la phrase de Twitch est relevée, onglet par onglet',
     muets.length >= 1 && muets.every((o) => o.cartes === 0 && o.texte.includes(PHRASE)),
     JSON.stringify(vu2.onglets));
  /* ET ELLE PREND LE PAS SUR NOTRE DÉDUCTION. Sans cette assertion, le relevé
     accuserait son propre sélecteur d'une panne qui ne le concerne pas — et
     c'est précisément la fausse piste que le rapport de terrain a créée. */
  ok('…et le verdict la recopie au lieu d\'accuser notre sélecteur',
     vu2.erreurs.some((e) => e.includes(PHRASE))
     && !vu2.erreurs.some((e) => /ne correspond plus|à revérifier/.test(e)),
     JSON.stringify(vu2.erreurs));
  /* LA BARRE LATÉRALE NE DOIT PAS PARTIR AVEC. La phrase vient de `main` seul :
     un repli sur le document entier verserait la barre — ses en-têtes, et donc
     ses pseudonymes — dans un journal que l'utilisateur nous enverra ensuite.
     « Chaînes suivies » est le premier texte du document : un repli sur `body`
     le ferait apparaître en tête de chaque phrase relevée. */
  ok('…sans emporter avec elle le contenu de la barre latérale',
     muets.every((o) => !/Chaînes suivies|Afficher plus/.test(o.texte)),
     JSON.stringify(muets.map((o) => o.texte)));
  await pageRefus.close();
}

/* ═════════ UNE RÉPONSE SANS STREAM NE RETIRE PLUS PERSONNE ═══════════════
   LE RAPPORT, ET SA PRÉCISION DÉCISIVE : « KyriaTV a disparu de Top Chaînes »,
   puis « ça se produit quand je survole à la suite les cartes des streamers en
   co-stream ». Deux captures à quelques secondes d'écart : quatre chaînes
   « Discussions » à 3,6 k et 41 m — chiffres STRICTEMENT identiques, la
   signature d'un seul stream affiché quatre fois — présentes, puis disparues.

   ET LE RAPPORT DISAIT « evicted 0 ». C'est ce chiffre qui a désigné le
   coupable : la voie d'éviction documentée — trois confirmations, un compteur,
   un plancher de réponse depuis la 4.13.1 — n'était pas celle qui les
   retirait. Il en existait une seconde :

       if (viewers === null) { liste.splice(i, 1); return true; }

   Une seule réponse, aucune confirmation, AUCUN COMPTEUR. Un retrait qui ne
   s'inscrit nulle part est un retrait qu'aucun rapport ne peut désigner, et
   c'est ce qui l'a rendu introuvable pendant deux enquêtes.

   `viewers` vaut null quand `user(login).stream` est nul — c'est EXACTEMENT la
   réponse pour un invité en co-stream : le répertoire le liste, notre propre
   marche l'y a vu avec les chiffres de l'hôte, et il n'a pourtant pas de
   stream à lui. On donnait raison à la seconde source contre la première.

   Le survol ne causait pas le retrait : il l'AVANÇAIT. Chaque aperçu fermé
   programme un scan, chaque scan redemande les entrées périmées — survoler
   d'affilée un groupe de co-stream, c'est déclencher les requêtes sur
   exactement ces logins-là. */
{
  titre('128. Top Chaînes — une réponse sans stream ne retire plus personne');

  const page = await fresh();
  await page.evaluate(() => {
    const cats = [];
    for (let i = 0; i < 10; i++) cats.push({ name: 'c' + i, viewers: 50_000 - i, streams: [] });
    for (let k = 0; k < 40; k++) {
      cats[k % 10].streams.push({ login: 's' + String(k).padStart(2, '0'),
                                  viewers: 4000 - k * 100 });
    }
    window.__cats = cats;
  });
  await page.evaluate(() => window.tse.global.on());
  ok('s00 est en tête du classement au départ',
     await page.evaluate(() => window.tse.global.top(1)[0]?.login) === 's00');

  /* LA COUCHE STRUCTURELLE EST GELÉE : seule la file TseChannels peut encore
     agir. Sans ce gel, la marche suivante réinstallerait s00 et le scénario
     mesurerait le hasard plutôt que la règle. */
  await page.evaluate(() => {
    window.__globalFail = true;
    /* s00 DEVIENT UN INVITÉ : le répertoire le liste toujours — la marche
       gelée garde son entrée — mais sa réponse de chaîne est sans stream. */
    window.__fx = { s00: null };
    window.__addCard('s00', 'Just Chatting', '4 k');
  });
  await wait(page, 1200);

  const apres = await page.evaluate(() => {
    const t = window.tse.global.top(50);
    const r = window.tse.global.report();
    return { rang: t.findIndex((x) => x.login === 's00'),
             viewers: t.find((x) => x.login === 's00')?.viewers ?? null,
             creux: r.creux, evicted: r.evicted };
  });

  /* L'ASSERTION QUI TIENT TOUT. Remettre le `splice` fait tomber celle-ci, et
     elle seule suffit : c'est la disparition du rapport, rejouée. */
  ok('une réponse sans stream ne retire pas la chaîne du classement',
     apres.rang >= 0, JSON.stringify(apres));
  ok('…et elle ne lui invente pas non plus un compteur',
     apres.viewers === 4000, JSON.stringify(apres));
  /* CE QUI MANQUAIT AU RAPPORT. « evicted 0 » pendant que des chaînes
     disparaissaient : le désaccord n'était compté nulle part. */
  ok('…mais le désaccord est COMPTÉ, ce qu\'aucun chiffre ne disait',
     apres.creux > 0 && apres.evicted === 0, JSON.stringify(apres));

  /* ── ET QUAND LES DEUX SOURCES S'ACCORDENT, ON RETIRE ─────────────────────
     La marche cesse elle aussi de voir s00. Attendre deux absences de plus
     n'apprendrait rien : le creux tranche dès la première, et le retrait se
     compte comme tous les autres. */
  await page.evaluate(() => {
    window.__globalFail = false;
    for (const c of window.__cats) c.streams = c.streams.filter((s) => s.login !== 's00');
  });
  await attendre(page, () => !window.tse.global.top(50).some((r) => r.login === 's00'), 12_000);
  const fin = await page.evaluate(() => {
    const r = window.tse.global.report();
    return { present: window.tse.global.top(50).some((x) => x.login === 's00'),
             evicted: r.evicted };
  });
  ok('la marche cesse de la voir à son tour, et le creux tranche aussitôt',
     !fin.present, JSON.stringify(fin));
  ok('…et ce retrait-là se compte, contrairement à celui qu\'on a retiré',
     fin.evicted > 0, JSON.stringify(fin));
  await page.close();
}

/* ═════════ LA PASTILLE N'AVAIT QU'UNE SOURCE, ET ELLE MANQUAIT SOUVENT ═══
   LE RAPPORT : « FrostyQc a le badge "En live avec…" et n'a pas la pastille
   sur son avatar, c'est normal ? » — en Top Chaînes, langue FR.

   NON. La pastille ne se lisait que dans le « +N » que Twitch écrit sur SA
   carte. Or en Top Chaînes les cartes sont des clones fabriqués, nettoyés par
   `scrubClone`, et Twitch n'écrit jamais de « +N » pour une chaîne qu'on ne
   suit pas : la pastille y était STRUCTURELLEMENT impossible.

   ET POURTANT L'EXTENSION SAVAIT. L'aperçu de la même carte affichait « En
   live avec DarthArcusal », lu dans le cache Guest Star — que le scan remplit
   pour toutes les cartes visibles, pas seulement au survol. L'information
   était en mémoire au moment où la carte était dessinée.

   RIEN À VOIR AVEC LA BARRE DE GROUPE, qui exige deux cartes visibles du même
   direct et reste donc absente ici : une barre qui REGROUPE n'a rien à relier
   sur une ligne seule. La pastille parle d'une chaîne, pas d'un ensemble. */
{
  titre('129. Pastille de co-stream — Guest Star, quand Twitch n\'écrit pas son « +N »');

  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    const chaine = (id, jeu, v) => ({ id, createdAt: h, viewers: v, game: jeu, tags: [] });
    window.__cats = [{ name: 'Super Mario 64', viewers: 9000,
                       streams: [{ login: 'frosty', viewers: 8400 }] }];
    /* IDENTIFIANTS NUMÉRIQUES, ET CE N'EST PAS COSMÉTIQUE. `buildGuestStarOp`
       écarte tout identifiant non numérique (`/^[0-9]+$/`) et ne demande alors
       RIEN. Un décor à identifiants inventés produit donc zéro requête Guest
       Star, silencieusement — et l'assertion tombe en accusant le produit. */
    window.__fx = {
      frosty: chaine('8801', 'Super Mario 64', 8400),
      darth:  chaine('8802', 'Super Mario 64', 500),
      /* UNE CARTE DE TWITCH DOIT ÊTRE LÀ : Top Chaînes CLONE une carte native
         pour fabriquer les siennes, et sans modèle il n'en fabrique aucune. */
      modele: chaine('7001', 'Discussions', 1000),
      seule:  chaine('7002', 'Discussions', 900),
      /* Minuscules : `loginFromHref` abaisse la casse avant d'écrire
         `dataset.tseLogin`, et une clé capitalisée ne se retrouve plus. */
      avecn:  chaine('7003', 'Discussions', 800),
    };
    /* La session : darth héberge, frosty est invité. `mates` vaut donc
       exactement un pour frosty — l'hôte, lui-même exclu. */
    window.__gs = {
      '8801': { hostId: '8802', hostLogin: 'darth',
                guests: [{ id: '8801', login: 'frosty', viewers: 8400, combined: 8900 }] },
      /* avecn est DANS une session lui aussi, et Twitch écrit quand même son
         « +N ». Les deux sources se contredisent : c'est le cas qui fixe la
         priorité, et sans lui le repli pourrait la prendre sans qu'on le voie. */
      '7003': { hostId: '8802', hostLogin: 'darth',
                guests: [{ id: '7003', login: 'avecn', viewers: 800, combined: 900 }] },
    };
    window.__addCard('modele', 'Discussions', '1 k');
    window.__addCard('seule',  'Discussions', '900');
    const a = window.__addCard('avecn', 'Discussions', '800');
    const sp = document.createElement('span');
    sp.textContent = '+3';
    a.querySelector('[data-a-target="side-nav-card-metadata"]').appendChild(sp);
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 3, 12_000);
  await attendre(page, () => !!document.querySelector('.tse-collab-badge'), 12_000);

  const suivies = await page.evaluate(() => {
    const get = (l) => [...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === l);
    const badge = (l) => get(l)?.querySelector('.tse-collab-badge')?.textContent ?? null;
    return { seule: badge('seule'), avecN: badge('avecn') };
  });
  /* LE « +N » DE TWITCH RESTE PRIORITAIRE : c'est son nombre sur sa carte, et
     le repli n'est qu'un ajout. Inverser la priorité fait tomber celle-ci. */
  ok('le « +N » de Twitch garde la main sur une carte qui en porte un',
     suivies.avecN === '3', JSON.stringify(suivies));
  /* ET LA PASTILLE NE S'INVENTE PAS : hors session et sans « +N », rien. */
  ok('…et une chaîne hors session n\'en reçoit toujours aucune',
     suivies.seule === null, JSON.stringify(suivies));

  /* ── LE CAS DU RAPPORT : TOP CHAÎNES, CARTE FABRIQUÉE ───────────────────
     Aucun « +N » ne peut s'y trouver. Sans le repli Guest Star, la pastille y
     est impossible — c'est l'assertion qui tient tout ce scénario. */
  await page.evaluate(() => window.tse.global.on());
  await attendre(page,
    () => [...document.querySelectorAll('.side-nav-card[data-tse-global="true"]')]
      .some((c) => c.dataset.tseLogin === 'frosty'), 12_000);
  await attendre(page,
    () => !![...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === 'frosty')
      ?.querySelector('.tse-collab-badge'), 12_000);

  const top = await page.evaluate(() => {
    const c = [...document.querySelectorAll('.side-nav-card')]
      .find((x) => x.dataset.tseLogin === 'frosty');
    return { fabriquee: c?.dataset.tseSynthetic === 'true',
             plus: /\+\s*\d/.test(c?.textContent || ''),
             badge: c?.querySelector('.tse-collab-badge')?.textContent ?? null,
             hote: !!c?.querySelector('.tse-collab-host') };
  });
  ok('la carte du classement est bien fabriquée, et ne porte aucun « +N »',
     top.fabriquee === true && top.plus === false, JSON.stringify(top));
  ok('…et elle porte pourtant la pastille, comptée sur Guest Star',
     top.badge === '1', JSON.stringify(top));
  ok('…posée sur l\'avatar, comme celle que Twitch fournit',
     top.hote === true, JSON.stringify(top));
  await page.close();
}

/* ═════════ LE CLASSEMENT DOIT TRIER SUR LE NOMBRE QU'IL AFFICHE ══════════
   LE RAPPORT, TROISIÈME REPRISE : six co-streamers « Aniimo » affichés à
   2,9 k, et trois d'entre eux quittent leur place pendant qu'on les survole.
   Ni « creux », ni « sousPlancher », ni presque aucun « evicted » au rapport —
   parce qu'AUCUN RETRAIT N'AVAIT LIEU. Les deux correctifs précédents
   visaient des suppressions ; celui-ci ne supprime rien du tout.

   LA CARTE ET LE CLASSEMENT NE PARLAIENT PAS DU MÊME NOMBRE. En co-stream,
   Twitch montre à chaque participant le compteur COMBINÉ de la session, et
   c'est ce que la marche récolte au répertoire. Puis la réponse de chaîne
   arrive avec le compteur PROPRE — quelques centaines — et c'est lui qui
   entrait au classement, tandis que la carte continuait d'afficher le
   combiné. Une ligne montrait 2,9 k en étant triée sur 400.

   CE QUI SE VOIT ALORS N'EST PAS UNE DISPARITION MAIS UNE CHUTE : la ligne
   dégringole sous des lignes à trois cents, ou sort du top trente. De l'autre
   côté de l'écran, ça ne se distingue pas — et c'est pourquoi deux enquêtes
   ont cherché un retrait qui n'existait pas. */
{
  titre('130. Top Chaînes — le classement trie sur le nombre qu\'il affiche');

  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    const c = (id, v) => ({ id, createdAt: h, viewers: v, game: 'Aniimo', tags: [] });
    /* LE RÉPERTOIRE REND LE COMBINÉ — 2 900 pour chacun des deux invités,
       exactement comme Twitch le fait. C'est ce nombre qui les place en tête. */
    window.__cats = [
      { name: 'Aniimo', viewers: 9000,
        streams: [{ login: 'shlorox', viewers: 2900 }, { login: 'tinkerleo', viewers: 2900 }] },
      { name: 'Autre', viewers: 4000,
        streams: [{ login: 'milieu', viewers: 800 }, { login: 'modele', viewers: 700 }] },
    ];
    /* ET LA RÉPONSE DE CHAÎNE REND LE COMPTEUR PROPRE : 400 chacun. C'est
       l'écart qui fait tout ce scénario — trié sur 400, tinkerleo passerait
       sous « milieu » (800) tout en affichant 2,9 k. */
    window.__fx = {
      shlorox:   c('9101', 400),
      tinkerleo: c('9102', 400),
      milieu:    c('9103', 800),
      modele:    c('9104', 700),
    };
    window.__gs = {
      '9101': { hostId: '9100', hostLogin: 'aniimo',
                guests: [{ id: '9101', login: 'shlorox',   viewers: 400, combined: 2900 },
                         { id: '9102', login: 'tinkerleo', viewers: 400, combined: 2900 }] },
      '9102': { hostId: '9100', hostLogin: 'aniimo',
                guests: [{ id: '9101', login: 'shlorox',   viewers: 400, combined: 2900 },
                         { id: '9102', login: 'tinkerleo', viewers: 400, combined: 2900 }] },
    };
    window.__addCard('modele', 'Autre', '700');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => window.tse.global.on());
  /* ON ATTEND QUE LA RÉPONSE DE CHAÎNE SOIT PASSÉE, sans quoi on mesurerait
     l'amorce de la marche — c'est-à-dire l'état AVANT le défaut. « milieu »
     n'est en co-stream d'aucune sorte : son compteur propre EST son compteur
     affiché, et le voir posé prouve que le lot est arrivé. */
  await attendre(page, () => [...document.querySelectorAll('.side-nav-card')]
    .some((c) => c.dataset.tseLogin === 'milieu' && c.dataset.tseViewers === '800'), 15_000);
  await wait(page, 1200);

  const vu = await page.evaluate(() => {
    const rang = window.tse.global.top(50).map((r) => `${r.login}:${r.viewers}`);
    const carte = (l) => [...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === l);
    return { rang,
             affiche: { shlorox: carte('shlorox')?.dataset.tseViewers ?? null,
                        tinkerleo: carte('tinkerleo')?.dataset.tseViewers ?? null } };
  });

  ok('la carte d\'un co-streamer affiche bien le compteur combiné',
     vu.affiche.shlorox === '2900' && vu.affiche.tinkerleo === '2900',
     JSON.stringify(vu.affiche));
  /* L'ASSERTION QUI TIENT TOUT : remettre `entry.viewers` fait passer les deux
     à 400, et elle tombe. */
  ok('…et le classement porte LE MÊME nombre, pas le compteur propre',
     vu.rang.includes('shlorox:2900') && vu.rang.includes('tinkerleo:2900'),
     vu.rang.join(' '));
  /* LA CONSÉQUENCE VISIBLE, et c'est elle que l'utilisateur décrivait : triés
     sur 400, les deux passaient SOUS une chaîne qui en affiche 800. */
  ok('…si bien qu\'ils restent au-dessus d\'une chaîne qui en affiche moins',
     vu.rang.indexOf('shlorox:2900') < vu.rang.indexOf('milieu:800')
     && vu.rang.indexOf('tinkerleo:2900') < vu.rang.indexOf('milieu:800'),
     vu.rang.join(' '));
  /* ET HORS CO-STREAM, RIEN NE CHANGE : le compteur propre reste la vérité. */
  ok('…tandis qu\'une chaîne hors session garde son propre compteur',
     vu.rang.includes('milieu:800'), vu.rang.join(' '));
  await page.close();
}

/* ═════════ UN RETOUR D'ONGLET NE DÉTRUIT PAS CE QU'ON A POSÉ ═════════════
   LE RAPPORT : « je vois des cartes apparaître et disparaître dans les
   co-streams, notamment quand je change de fenêtre quelques secondes puis j'y
   reviens. » Et, au rapport de diagnostic, « evicted 0 » et « creux 0 » : rien
   n'était retiré du classement. Ce n'était donc pas un retrait de plus.

   `invalidateAndRescan` — le chemin du retour d'onglet — effaçait le pseudo de
   TOUTES les cartes, y compris celles que NOUS avons fabriquées. Or
   `syncGlobalCards` identifie les siennes par ce pseudo et retire celles qui
   n'en ont plus ; pour une carte fabriquée, « retirer » veut dire `remove()`.
   Un simple retour d'onglet détruisait donc les trente cartes du classement
   avant de les refabriquer.

   LE PSEUDO N'EST PAS LA MÊME CHOSE SUR LES DEUX. Sur une carte de Twitch il
   est une LECTURE, et l'effacer force à tout relire — c'est le but. Sur une
   carte que nous avons posée il est notre SEULE identité, et l'effacer ne
   relit rien : il perd la carte. */
{
  titre('131. Top Chaînes — un retour d\'onglet ne détruit pas les cartes qu\'on a posées');

  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    const c = (id, v) => ({ id, createdAt: h, viewers: v, game: 'Aniimo', tags: [] });
    window.__cats = [{ name: 'Aniimo', viewers: 9000, streams: [
      { login: 'shlorox', viewers: 2900 }, { login: 'tinkerleo', viewers: 2800 },
      { login: 'milieu', viewers: 700 }, { login: 'modele', viewers: 600 }] }];
    window.__fx = { shlorox: c('9101', 400), tinkerleo: c('9102', 400),
                    milieu: c('9103', 700), modele: c('9104', 600) };
    /* La carte native sert de MODÈLE au clonage, et le classement l'emprunte
       aussi pour elle-même : c'est elle qui ressortait EN DOUBLE. */
    window.__addCard('modele', 'Aniimo', '600');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => window.tse.global.on());
  await attendre(page, () => document.querySelectorAll('.side-nav-card').length >= 4, 12_000);
  await wait(page, 1500);

  /* ON MARQUE LES CARTES AVANT, et c'est ce qui distingue « conservée » de
     « refabriquée à l'identique ». Un simple relevé de pseudos ne le dirait
     pas : la reconstruction rend les mêmes noms, sur d'autres nœuds. */
  const avant = await page.evaluate(() => {
    const cartes = [...document.querySelectorAll('.side-nav-card')];
    cartes.forEach((c, i) => { c.dataset.tseTemoin = 't' + i; });
    return cartes.map((c) => `${c.dataset.tseLogin}/${c.dataset.tseSynthetic === 'true' ? 'fab' : 'nat'}`);
  });
  ok('le décor porte bien des cartes fabriquées ET une carte native',
     avant.filter((x) => x.endsWith('/fab')).length >= 2
     && avant.some((x) => x.endsWith('/nat')), JSON.stringify(avant));

  /* L'ABSENCE, plus longue que REVISIT_RELOAD_MS (1 500 ms sous les durées du
     banc) : c'est le seuil au-delà duquel le retour invalide et reconstruit. */
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { value: true, configurable: true });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await wait(page, 2200);
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { value: false, configurable: true });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await wait(page, 3000);

  const apres = await page.evaluate(() => {
    const cartes = [...document.querySelectorAll('.side-nav-card')];
    const logins = cartes.map((c) => c.dataset.tseLogin ?? null);
    return { logins,
             temoins: cartes.filter((c) => c.dataset.tseTemoin).length,
             sansLogin: logins.filter((l) => !l).length,
             doublons: logins.length - new Set(logins).size };
  });

  /* L'ASSERTION QUI TIENT TOUT : mesurée avant le correctif, la carte native
     empruntée ressortait accompagnée de son clone refabriqué. */
  ok('aucune carte n\'est dupliquée par le retour d\'onglet',
     apres.doublons === 0, JSON.stringify(apres));
  ok('…aucune ne perd son pseudo au passage',
     apres.sansLogin === 0, JSON.stringify(apres));
  /* ET ELLES N'ONT PAS ÉTÉ REFABRIQUÉES : ce sont les MÊMES nœuds, ceux qu'on
     a marqués. Sans ce témoin, un démontage-remontage passerait pour un
     non-événement. */
  ok('…et ce sont les mêmes nœuds, pas des cartes refaites à l\'identique',
     apres.temoins === apres.logins.length && apres.temoins >= 4,
     JSON.stringify(apres));
  await page.close();
}

/* ═════════ EN SESSION, LE COMPTEUR PROPRE N'EST JAMAIS LE BON ════════════
   LE RAPPORT, QUATRIÈME REPRISE : six co-streamers « Aniimo » affichés à 4 k,
   dont TROIS quittent la liste. Et au rapport : misses 0, sousPlancher 0,
   creux 0, evicted 0 — littéralement rien n'avait quitté le pool.

   C'EST LE TROU LAISSÉ OUVERT PAR LA 4.13.6. Celle-ci préférait le compteur
   COMBINÉ de la session quand elle le connaissait ; sinon elle retombait sur
   le compteur PROPRE. Or sur une session à six, Twitch ne porte le
   `collaborationViewersCount` que pour CERTAINS participants. Les autres
   retombaient donc à quelques centaines et sortaient du top trente — trois
   gardaient 4 000, trois descendaient à 300.

   EN SESSION, LE COMPTEUR PROPRE N'EST JAMAIS LE BON NOMBRE : ce n'est pas
   celui que Twitch affiche, donc pas celui que la carte montre, donc pas celui
   qui doit trier. À défaut de combiné, on garde ce que le RÉPERTOIRE a dit.
   NE RIEN ÉCRIRE EST ICI LA BONNE ÉCRITURE. */
{
  titre('132. Co-stream — sans combiné, le classement garde le nombre du répertoire');

  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    const c = (id, v) => ({ id, createdAt: h, viewers: v, game: 'Aniimo', tags: [] });
    /* LE RÉPERTOIRE REND LE COMBINÉ — 4 000 pour les deux co-streamers. */
    window.__cats = [{ name: 'Aniimo', viewers: 9000, streams: [
      { login: 'naguura', viewers: 4000 }, { login: 'tinkerleo', viewers: 4000 },
      { login: 'milieu', viewers: 900 }, { login: 'modele', viewers: 800 }] }];
    /* ET LA RÉPONSE DE CHAÎNE REND LE COMPTEUR PROPRE : 300 chacun. C'est
       l'écart qui fait tout — trié sur 300, un co-streamer passe sous une
       chaîne qui en affiche 900 tout en montrant 4 k. */
    window.__fx = { naguura: c('9201', 300), tinkerleo: c('9202', 300),
                    milieu: c('9203', 900), modele: c('9204', 800) };
    /* LA SESSION NE PORTE DE COMBINÉ QUE POUR NAGUURA. Pour tinkerleo, Twitch
       n'en donne pas — c'est le cas observé sur une session à six, et c'est le
       seul point qui les distingue dans ce décor. */
    const guests = [{ id: '9201', login: 'naguura', viewers: 300, combined: 4000 },
                    { id: '9202', login: 'tinkerleo', viewers: 300 }];
    window.__gs = { '9201': { hostId: '9200', hostLogin: 'aniimo', guests },
                    '9202': { hostId: '9200', hostLogin: 'aniimo', guests } };
    window.__addCard('modele', 'Aniimo', '800');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => window.tse.global.on());
  /* ON ATTEND QUE LA RÉPONSE DE CHAÎNE SOIT PASSÉE : « milieu » n'est en
     session d'aucune sorte, son compteur propre EST son compteur affiché, et
     le voir posé prouve que le lot est arrivé. */
  await attendre(page, () => [...document.querySelectorAll('.side-nav-card')]
    .some((c) => c.dataset.tseLogin === 'milieu' && c.dataset.tseViewers === '900'), 15_000);
  await wait(page, 1500);

  const vu = await page.evaluate(() => {
    const rang = window.tse.global.top(50).map((r) => `${r.login}:${r.viewers}`);
    const aff = (l) => [...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === l)?.dataset.tseViewers ?? null;
    return { rang, naguura: aff('naguura'), tinkerleo: aff('tinkerleo'), milieu: aff('milieu') };
  });

  ok('le co-streamer dont la session donne son combiné le garde',
     vu.rang.includes('naguura:4000') && vu.naguura === '4000', JSON.stringify(vu));
  /* L'ASSERTION QUI TIENT TOUT : sans elle, tinkerleo retombe à 300 — mesuré. */
  ok('…et celui dont elle n\'en donne pas garde le nombre du répertoire',
     vu.rang.includes('tinkerleo:4000'), vu.rang.join(' '));
  ok('…sa carte l\'affiche aussi, au lieu de son compteur propre',
     vu.tinkerleo === '4000', String(vu.tinkerleo));
  /* LA CONSÉQUENCE VISIBLE, et c'est elle que l'utilisateur décrivait. */
  ok('…si bien qu\'aucun des deux ne passe sous une chaîne qui en affiche moins',
     vu.rang.indexOf('naguura:4000') < vu.rang.indexOf('milieu:900')
     && vu.rang.indexOf('tinkerleo:4000') < vu.rang.indexOf('milieu:900'),
     vu.rang.join(' '));
  /* ET LA RÈGLE NE DÉBORDE PAS : hors session, le compteur propre fait foi. */
  ok('…tandis qu\'une chaîne hors session garde bien le sien',
     vu.rang.includes('milieu:900') && vu.milieu === '900', JSON.stringify(vu));
  await page.close();
}

/* ═════════ LA SIGNATURE DE CO-STREAM EST DANS LE RÉPERTOIRE ══════════════
   LE RAPPORT, CINQUIÈME REPRISE, ET SA PRÉCISION DÉCISIVE : « ils ont été 5,
   puis pendant une demi-seconde ils sont passés à 3, puis revenus à 5. Puis là
   ils ne sont plus que 3. Je n'ai pas quitté la fenêtre. »

   UNE OSCILLATION, ET C'EST CE MOT QUI A TOUT DONNÉ. `LIVE_TTL` et
   `GLOBAL_STRUCT_TICK` valent TOUS DEUX 30 s : la marche remonte les
   co-streamers au compteur du répertoire, le lot de chaînes les fait retomber
   à leur compteur propre, la marche suivante les remonte. Deux sources qui
   gagnent à tour de rôle, et le classement qui bat avec elles. Mesuré :

       classement : lyritvjamie:4900   ← restauré par la marche
       carte      : lyritvjamie=300    ← dégradé par le lot de chaînes

   ET AUCUN GARDE-FOU GUEST STAR NE POUVAIT L'ATTRAPER. Pour ces
   participants-là, Twitch répond `session: null` alors que son PROPRE
   répertoire les affiche tous au même compteur. Quatre correctifs ont cherché
   le signal chez Guest Star ; il n'y est pas.

   LE RÉPERTOIRE, LUI, LE DIT. Plusieurs chaînes d'une même catégorie portant
   EXACTEMENT le même compteur, c'est la signature d'un combiné — celle-là même
   que ce produit utilise déjà pour regrouper les cartes. */
{
  titre('133. Co-stream — la signature du répertoire tient quand Guest Star se tait');

  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    const c = (id, v) => ({ id, createdAt: h, viewers: v, game: 'Aniimo', tags: [] });
    /* DEUX CHAÎNES AU MÊME COMPTEUR dans la même catégorie : la signature. */
    window.__cats = [{ name: 'Aniimo', viewers: 9000, streams: [
      { login: 'naguura', viewers: 4900 }, { login: 'lyritvjamie', viewers: 4900 },
      { login: 'milieu', viewers: 900 }, { login: 'modele', viewers: 800 }] }];
    /* Leurs compteurs PROPRES sont dérisoires. « milieu », lui, n'a pas de
       jumeau : son compteur frais (950) doit continuer de s'appliquer — c'est
       la fraîcheur que le scénario 34 garantit, et qu'on ne sacrifie pas. */
    window.__fx = { naguura: c('9301', 300), lyritvjamie: c('9302', 300),
                    milieu: c('9303', 950), modele: c('9304', 800) };
    /* GUEST STAR NE CONNAÎT QUE NAGUURA. Pour lyritvjamie, `session: null` —
       et c'est exactement ce que le terrain a montré. */
    window.__gs = { '9301': { hostId: '9300', hostLogin: 'aniimo',
      guests: [{ id: '9301', login: 'naguura', viewers: 300, combined: 4900 }] } };
    window.__addCard('modele', 'Aniimo', '800');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => window.tse.global.on());
  await attendre(page, () => [...document.querySelectorAll('.side-nav-card')]
    .some((c) => c.dataset.tseLogin === 'milieu' && c.dataset.tseViewers === '950'), 15_000);

  const lire = () => page.evaluate(() => {
    const aff = (l) => [...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === l)?.dataset.tseViewers ?? null;
    return { rang: window.tse.global.top(50).map((r) => `${r.login}:${r.viewers}`),
             naguura: aff('naguura'), lyri: aff('lyritvjamie'), milieu: aff('milieu') };
  });
  const un = await lire();

  ok('la chaîne que Guest Star connaît garde son combiné',
     un.rang.includes('naguura:4900') && un.naguura === '4900', JSON.stringify(un));
  /* L'ASSERTION QUI TIENT TOUT : Guest Star se tait sur elle, et c'est la
     signature du répertoire — deux chaînes au même compteur — qui la sauve. */
  ok('…et celle sur laquelle il se tait garde le nombre du répertoire',
     un.rang.includes('lyritvjamie:4900'), un.rang.join(' '));
  ok('…sa carte aussi, au lieu de son compteur propre',
     un.lyri === '4900', String(un.lyri));
  /* LA FRAÎCHEUR ORDINAIRE N'EST PAS SACRIFIÉE : sans jumeau, le compteur
     frais du lot continue de reclasser, ce que le scénario 34 exige. */
  ok('…tandis qu\'une chaîne sans jumeau reçoit bien son compteur frais',
     un.rang.includes('milieu:950') && un.milieu === '950', JSON.stringify(un));

  /* ── ET ÇA NE BAT PAS — MAIS CE RELEVÉ UNIQUE NE LE PROUVE PAS ─────────
     CE QU'UNE MESURE A MONTRÉ, ET QUI N'EST PAS CORRIGÉ ICI. Ce relevé
     unique, quatre secondes plus tard, éprouve « la valeur à cet instant » et
     non « la valeur ne bat pas ». Remplacé le temps d'une mesure par vingt
     relevés espacés de deux cents millisecondes, il a montré un battement
     RÉEL et reproductible : un à deux relevés sur vingt portent « milieu:900 »
     — la valeur du répertoire — au lieu de « 950 », le compteur frais. Cinq
     passes sur cinq.

     LA CAUSE EST CONNUE : la marche reconstruit le classement depuis son pool,
     et sa lecture de répertoire, plus RÉCENTE en date de lecture, écrase le
     compteur venu de TseChannels, plus juste en contenu. Le témoin remonte au
     relevé suivant, d'où l'alternance.

     POURQUOI L'ASSERTION RESTE EN L'ÉTAT. Le défaut est ANTÉRIEUR à tout ce
     que cette version touche, et il vit dans le module qui a déjà coûté
     plusieurs versions — la corriger au passage, sans l'instruire, est
     exactement la façon dont on livre une régression. Elle est donc laissée
     telle quelle, et le battement est écrit ici pour qu'il ne se reperde pas :
     c'est un sujet à lui seul, avec sa version. */
  await wait(page, 4000);
  const deux = await lire();
  ok('…et rien de tout cela ne bat d\'un cycle à l\'autre',
     deux.rang.includes('lyritvjamie:4900') && deux.lyri === '4900'
     && deux.rang.includes('naguura:4900') && deux.milieu === '950',
     JSON.stringify(deux));  await page.close();
}

/* ═════════ UNE CARTE FABRIQUÉE EST UNE CARTE COMME LES AUTRES ════════════
   AUDIT DEMANDÉ : « que les cartes clonées sur Top Chaînes soient identiques à
   une carte normale ». Ce scénario EST l'audit, figé.

   LA MÉTHODE : deux chaînes aux données RIGOUREUSEMENT identiques — même
   compteur, même ancienneté, même catégorie, même langue. L'une a une carte de
   Twitch, que le classement emprunte ; l'autre n'en a pas, et sa carte est
   donc CLONÉE. On compare les deux au même instant, dans le même mode.

   CE QUI A LE DROIT DE DIFFÉRER, et rien d'autre :
     • `tseSynthetic`   — le marqueur lui-même ;
     • `tseTwitchOrder` — l'ordre de Twitch, dont une carte fabriquée ne fait
       délibérément pas partie (elle décalerait l'indice des suivantes) ;
     • `tseLangs`       — le filtre de langue des cartes, dont TOUTE carte du
       classement est exemptée (cf. applyCardFilter) ; l'absence est donc sans
       effet, et la présence sur la native est un reliquat du mode suivi.

   CE QUE CET AUDIT A TROUVÉ : la carte fabriquée n'annonçait RIEN aux lecteurs
   d'écran. `scrubClone` retirait la phrase de Twitch — à raison, elle portait
   le compteur de la chaîne source — mais concluait qu'on ne saurait pas la
   réécrire. La phrase est pourtant déjà dans la bonne langue : seul le nombre
   était faux. */
{
  titre('134. Top Chaînes — une carte fabriquée est indiscernable d\'une carte native');

  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 125 * 60_000).toISOString();
    const c = (id) => ({ id, createdAt: h, viewers: 2000, game: 'Art',
                         tags: ['Français'], title: 'Jour 12 du subathon !' });
    window.__cats = [{ name: 'Art', viewers: 90_000, streams: [
      { login: 'jumeaunat', viewers: 2000 }, { login: 'jumeaufab', viewers: 2000 }] }];
    window.__fx = { jumeaunat: c('7401'), jumeaufab: c('7402'),
                    /* Le modèle à cloner : sans carte native, rien n'est fabriqué. */
                    modele: { id: '7404', createdAt: h, viewers: 400,
                              game: 'Discussions', tags: [] } };
    /* ABONNÉ AUX DEUX : la décoration « abonné » doit voyager aussi. */
    try {
      localStorage.setItem('tse:subs', JSON.stringify({
        jumeaunat: [1, Date.now()], jumeaufab: [1, Date.now()] }));
    } catch { /* stockage refusé : les assertions le diront */ }
    window.__addCard('modele', 'Discussions', '400');
    window.__addCard('jumeaunat', 'Art', '2 k');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 2, 12_000);
  await page.evaluate(() => window.tse.global.on());
  await attendre(page, () => [...document.querySelectorAll('.side-nav-card')]
    .some((c) => c.dataset.tseLogin === 'jumeaufab' && c.dataset.tseViewers), 15_000);
  await wait(page, 1500);

  const vu = await page.evaluate(() => {
    const trouve = (l) => [...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === l);
    const TOLERE = new Set(['tseSynthetic', 'tseTwitchOrder', 'tseLangs']);
    const empreinte = (card, login) => {
      if (!card) return null;
      const norm = (s) => (s ?? '').replace(new RegExp(login, 'gi'), '<login>');
      const statut = card.querySelector('.side-nav-card__live-status');
      return {
        data: Object.fromEntries(Object.entries({ ...card.dataset })
          .filter(([k]) => !TOLERE.has(k)).map(([k, v]) => [k, norm(v)]).sort()),
        classes: [...card.classList].sort().join(' '),
        injections: [...card.querySelectorAll('[class^="tse-"], [class*=" tse-"]')]
          .map((n) => `${n.className}:${norm(n.textContent).trim()}`).sort(),
        href: norm(card.querySelector('a[href^="/"]')?.getAttribute('href')),
        structure: [
          !!card.querySelector('a[data-a-target="side-nav-card"]'),
          !!card.querySelector('a[data-test-selector="followed-channel"]'),
          !!card.querySelector('.tw-image-avatar'),
          !!card.querySelector('[data-a-target="side-nav-card-metadata"]'),
          !!card.querySelector('.side-nav-card__metadata'),
          !!card.querySelector('p[data-a-target="side-nav-title"]'),
          !!card.querySelector('.side-nav-card__live-status'),
          !!card.querySelector('.tw-channel-status-indicator'),
        ].join(','),
        /* CE QUE LE LECTEUR D'ÉCRAN ENTEND, en regard de ce que l'œil lit. */
        annonce: [...(statut?.querySelectorAll('*') || [])]
          .filter((n) => !n.children.length && n.getAttribute('aria-hidden') !== 'true'
                      && !String(n.className).includes('tse-'))
          .map((n) => n.textContent.trim()).filter(Boolean),
        oeil: card.querySelector('.tse-viewers')?.textContent ?? null,
      };
    };
    const nat = trouve('jumeaunat'), fab = trouve('jumeaufab');
    return {
      decor: { natSynth: nat?.dataset.tseSynthetic === 'true',
               natEmpruntee: nat?.dataset.tseGlobal === 'true',
               fabSynth: fab?.dataset.tseSynthetic === 'true' },
      nat: empreinte(nat, 'jumeaunat'), fab: empreinte(fab, 'jumeaufab'),
    };
  });

  /* LE DÉCOR D'ABORD : sans lui, tout le reste comparerait deux clones. */
  ok('le décor oppose bien une carte native empruntée à une carte fabriquée',
     vu.decor.natEmpruntee === true && vu.decor.natSynth === false
     && vu.decor.fabSynth === true, JSON.stringify(vu.decor));

  const champs = ['data', 'classes', 'injections', 'href', 'structure'];
  for (const champ of champs) {
    ok(`…et leur « ${champ} » est identique`,
       JSON.stringify(vu.nat?.[champ]) === JSON.stringify(vu.fab?.[champ]),
       `native: ${JSON.stringify(vu.nat?.[champ])}\n            fabriquée: ${JSON.stringify(vu.fab?.[champ])}`);
  }

  /* L'ÉCART QUE CET AUDIT A TROUVÉ, et qu'aucune des lignes ci-dessus ne
     couvrait avant lui : la carte fabriquée n'annonçait rien du tout. */
  ok('…la carte fabriquée annonce son compteur aux lecteurs d\'écran',
     vu.fab?.annonce.length > 0 && vu.fab.annonce.some((t) => t.includes(vu.fab.oeil)),
     JSON.stringify({ annonce: vu.fab?.annonce, oeil: vu.fab?.oeil }));
  /* ET LE DÉFAUT SYMÉTRIQUE, sur la carte native : l'œil lisait notre
     compteur, le lecteur d'écran annonçait celui de Twitch. */
  ok('…et la native annonce le nombre qu\'elle AFFICHE, pas celui de Twitch',
     vu.nat?.annonce.some((t) => t.includes(vu.nat.oeil)),
     JSON.stringify({ annonce: vu.nat?.annonce, oeil: vu.nat?.oeil }));
  await page.close();
}

/* ═════════ CE QUE LA SESSION COMPTE, ET CE QUE LA LISTE MONTRE ═══════════
   CINQ VERSIONS ONT CHERCHÉ POURQUOI UN CO-STREAMER « DISPARAÎT » de Top
   Chaînes sans pouvoir trancher, faute du seul chiffre qui départage les deux
   causes possibles :

     • il A ÉTÉ CLASSÉ PUIS PERDU — c'est notre fuite, et ça se répare ;
     • il N'A JAMAIS ÉTÉ CLASSÉ — le répertoire de Twitch ne le range pas dans
       la langue demandée, et il n'y a rien à réparer chez nous.

   LES DEUX SE RESSEMBLENT À L'ÉCRAN : deux cartes groupées portant chacune une
   pastille qui annonce plus de participants qu'il n'y a de lignes. La pastille
   vient de la session (Guest Star), le groupe vient des cartes présentes, et
   rien ne réconciliait les deux.

   `classesNonAffichees` est ce chiffre, et lui seul nous accuse. */
{
  titre('135. Co-stream — la session et la liste se comptent séparément');

  const page = await fresh();
  await page.evaluate(() => {
    const h = (min) => new Date(Date.now() - min * 60_000).toISOString();
    const trio = ['aa', 'bb', 'absent'];
    /* ── QUATRE MEMBRES, ET DEUX ESPÈCES D'ABSENTS ────────────────────────
       « absent » porte un combiné : depuis la 4.15.7 il est classé dessus,
       comme Twitch l'affiche, et il obtient donc une carte. « petit », lui,
       n'en a pas — Twitch rend `collaborationViewersCount: null` sur certains
       participants, c'est observé — et il reste donc sous la coupe sur son
       audience propre. C'est le cas SAIN que `sousLaCoupe` décrit, et il
       fallait le distinguer du défaut : jusqu'ici ce décor n'en jouait qu'un
       seul, celui que la 4.15.7 a corrigé. */
    const guests = [
      ...trio.map((l, i) => ({ id: '80' + i, login: l, viewers: 300, combined: 1300 })),
      { id: '803', login: 'petit', viewers: 40, combined: null }];
    /* CINQUANTE CHAÎNES au-dessus du seuil : « absent », à quarante
       spectateurs dans une autre catégorie, ne peut pas entrer au top 30. Sans
       ce bruit, le décor classerait tout et ne jouerait plus le cas. */
    const bruit = [...Array(50)].map((_, i) => ({ login: 'n' + i, viewers: 900 - i }));
    window.__cats = [
      { name: 'VALORANT', viewers: 90_000, streams: [
        { login: 'aa', viewers: 1300 }, { login: 'bb', viewers: 1300 },
        { login: 'modele', viewers: 1200 }, ...bruit] },
      { name: 'Discussions', viewers: 80, streams: [
        { login: 'absent', viewers: 40 }, { login: 'petit', viewers: 40 }] },
    ];
    window.__fx = Object.fromEntries([
      ['aa', { id: '800', createdAt: h(60), viewers: 300, game: 'VALORANT', tags: [] }],
      ['bb', { id: '801', createdAt: h(490), viewers: 300, game: 'VALORANT', tags: [] }],
      ['absent', { id: '802', createdAt: h(120), viewers: 40, game: 'Discussions', tags: [] }],
      ['petit', { id: '803', createdAt: h(120), viewers: 40, game: 'Discussions', tags: [] }],
      ['modele', { id: '812', createdAt: h(30), viewers: 1200, game: 'VALORANT', tags: [] }],
      ...bruit.map((x) => [x.login, { id: 'b' + x.login, createdAt: h(30),
                                      viewers: x.viewers, game: 'VALORANT', tags: [] }]),
    ]);
    /* La session compte CINQ membres : l'hôte et les quatre invités. */
    window.__gs = Object.fromEntries(trio.map((l, i) =>
      ['80' + i, { hostId: '8000', hostLogin: 'hote', guests }]));
    window.__addCard('modele', 'VALORANT', '1,2 k');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => window.tse.global.on());
  await attendre(page, () => (window.tse.panneau.rapport().coStream?.groupes || 0) > 0, 15_000);
  await wait(page, 1500);

  const vu = await page.evaluate(() => ({
    bilan: window.tse.panneau.rapport().coStream,
    absentClasse: window.tse.global.top(30).some((r) => r.login === 'absent'),
    absentAffiche: !![...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === 'absent'),
    pastilles: [...document.querySelectorAll('.side-nav-card.tse-costream')]
      .map((c) => c.querySelector('.tse-collab-badge')?.textContent ?? null),
  }));

  /* LE DÉCOR JOUE BIEN LE CAS : la pastille annonce plus de participants qu'il
     n'y a de lignes groupées — la contradiction même du rapport de terrain. */
  ok('la pastille annonce plus de participants que la liste n\'en montre',
     vu.pastilles.length === 3 && vu.pastilles.every((x) => x === '4'),
     JSON.stringify(vu.pastilles));
  /* ── CE QUE LA 4.15.7 A RENVERSÉ ICI, ET POURQUOI C'EST JUSTE ───────────
     CETTE ASSERTION EXIGEAIT LE CONTRAIRE : que « absent », membre de session
     connu du pool, reste hors du classement et hors de l'écran. Elle décrivait
     donc le défaut comme un contrat. Le rapport de terrain l'a dit autrement —
     « des co-streams non visibles sur Top Chaînes » — et la règle de la maison
     tranche depuis la 4.13.6 : le nombre qui TRIE est celui qui est AFFICHÉ,
     et en session Twitch affiche le combiné. Un membre dont on connaît le
     combiné a donc sa place au classement, carte comprise. */
  ok('…et le membre dont on connaît le combiné est classé dessus, et affiché',
     vu.absentClasse === true && vu.absentAffiche === true, JSON.stringify(vu));

  /* LE BILAN REND COMPTE DE TOUS LES MEMBRES, SANS EN PERDRE : c'est ce qui
     rend ses trois nombres lisibles ensemble plutôt qu'un à un. */
  const b = vu.bilan;
  ok('le bilan compte la session entière, et chaque membre dans une seule case',
     b.groupes === 1 && b.membres === 5
     && b.affiches + b.horsClassement + b.sousLaCoupe
        + b.classesNonAffichees === b.membres,
     JSON.stringify(b));
  /* ── QUATRE CASES, ET LA QUATRIÈME EST CELLE QUI MANQUAIT ────────────────
     L'ASSERTION PORTAIT L'ANCIENNE CONFUSION, et c'est elle qui m'a égaré sur
     un rapport de terrain. « horsClassement » rangeait ensemble deux choses
     que tout sépare : une chaîne que la MARCHE ne connaît pas, et une chaîne
     parfaitement connue, retombée sous le trentième rang parce qu'elle a
     perdu son compteur combiné. J'ai lu « horsClassement 9 » comme « neuf
     inconnues » alors que c'était le second cas — celui qui désignait le
     défaut de la 4.14.2.

     ICI LE DÉCOR PORTE LES DEUX : un membre que le répertoire ignore, et un
     membre connu mais sous la coupe. Les compter à part est ce qui rend le
     bilan lisible ; les confondre, c'est ce qui a coûté deux versions.

     ── ET LA 4.18 A VIDÉ LA TROISIÈME CASE, PAR CONSTRUCTION ──────────────
     Cette assertion exigeait « sousLaCoupe 1 ». Elle ne le peut plus, et ce
     n'est pas une régression : depuis qu'un co-stream occupe UNE place,
     l'ensemble de ses membres sort avec elle. « petit » était sous la coupe
     parce qu'on le triait sur son audience PROPRE ; il est désormais affiché
     parce qu'il appartient à la place — c'est mot pour mot la demande de
     l'utilisateur, « affiche l'ensemble des streamers d'un co-stream ».

     CE QUE LES CASES VEULENT DIRE MAINTENANT, en mode « Top Chaînes » : rien,
     ou presque, pour une session que Guest Star connaît — la 4.18.1 complète
     les places avec les membres que le répertoire ne rend PAS, donc même
     « horsClassement » se vide. Les quatre cases gardent tout leur sens en
     mode SUIVI, où aucune complétion n'a lieu, et sous filtre de langue, où
     l'on s'abstient de compléter faute de connaître la langue d'un membre. */
  ok('…et il sépare « inconnu de la marche » de ce que la place fait remonter',
     b.affiches === 5 && b.horsClassement === 0 && b.sousLaCoupe === 0,
     JSON.stringify(b));
  /* ── L'ASSERTION DU COMPTEUR AVEUGLE EST PARTIE AVEC SA CONDITION ──────
     `sousLaCoupeAvecCombine` a été écrit contre un angle mort : il lisait le
     cache des CARTES pour retrouver l'identifiant d'un membre qui, par
     définition de cette branche, n'en a pas. Il valait donc zéro quoi qu'il
     arrive, et un rapport portant « sousLaCoupe 14 · sousLaCoupeAvecCombine 0 »
     se lisait « rien d'anormal ». Une assertion vivait ici pour dire qu'il
     valait zéro PARCE QUE C'ÉTAIT VRAI.

     ELLE NE PEUT PLUS ÉCHOUER. Depuis que le co-stream occupe une place,
     « petit » n'est plus sous la coupe : `sousLaCoupe` vaut zéro, donc
     `sousLaCoupeAvecCombine` aussi, mécaniquement. Une assertion qui ne peut
     plus être fausse n'est plus une assertion — la garder apprendrait à lui
     faire confiance à tort, ce que ce fichier a déjà payé trois fois.

     CE QUI LA REMPLACE EXISTE DÉJÀ : le scénario 143 tient la moitié qui
     compte — un membre SANS carte dont le combiné est connu — et c'est là que
     l'angle mort se verrait revenir. */
  /* ET SUR UNE LISTE SAINE, AUCUNE FUITE : toute chaîne au classement a sa
     carte. C'est ce zéro que le terrain devra confirmer — ou démentir. */
  ok('…et aucun membre classé ne reste sans carte',
     b.classesNonAffichees === 0, JSON.stringify(b));
  await page.close();
}

/* ═════════ LA SIGNATURE SE LIT COMME L'ŒIL LA LIT ═══════════════════════
   LA 4.13.9 COMPARAIT LES VALEURS EXACTES, et un rapport de terrain l'a mise
   en défaut : trois co-streamers affichés « 1,1 k » n'ont PAS le même nombre
   exact. Twitch échantillonne le compteur combiné une fois par participant, et
   les relevés diffèrent de quelques unités.

   LA LEÇON ÉTAIT DÉJÀ DANS LE PRODUIT, dix mille lignes plus bas, au-dessus de
   l'heuristique qui regroupe les cartes : « deux valeurs exactes voisines
   (1 663 / 1 661) ne doivent pas faire échouer un regroupement que Twitch
   affiche comme identique. » La signature du classement l'ignorait — elle ne
   protégeait donc que les sessions qui n'en avaient pas besoin.

   MESURÉ AVANT CORRECTIF, sur le décor ci-dessous :
       relevé 1 : milieu:900, modele:800, bb:300, aa:300, cc:300
       relevé 2 : bb:1148, aa:1101, cc:1093, milieu:900, modele:800
   Les trois tombent à leur compteur propre, la marche les remonte, et ainsi de
   suite — l'oscillation, exactement. */
{
  titre('136. Co-stream — la signature du classement se lit comme l\'œil la lit');

  const page = await fresh();
  await page.evaluate(() => {
    const h = (min) => new Date(Date.now() - min * 60_000).toISOString();
    /* TROIS COMBINÉS VOISINS MAIS DISTINCTS — 1101, 1148, 1093 — qui
       s'affichent TOUS « 1,1 k ». C'est le relevé de Twitch, et c'est le seul
       point qui distingue ce décor de celui du scénario 133. */
    window.__cats = [{ name: 'VALORANT', viewers: 90_000, streams: [
      { login: 'aa', viewers: 1101 }, { login: 'bb', viewers: 1148 },
      { login: 'cc', viewers: 1093 },
      { login: 'milieu', viewers: 900 }, { login: 'modele', viewers: 800 }] }];
    const c = (id, min) => ({ id, createdAt: h(min), viewers: 300,
                              game: 'VALORANT', tags: [] });
    window.__fx = {
      aa: c('950', 60), bb: c('951', 490), cc: c('952', 120),
      milieu: { id: '953', createdAt: h(30), viewers: 900, game: 'VALORANT', tags: [] },
      modele: { id: '954', createdAt: h(30), viewers: 800, game: 'VALORANT', tags: [] },
    };
    /* GUEST STAR NE DIT RIEN D'EUX : c'est la signature du répertoire, et elle
       seule, qui doit les tenir. */
    window.__addCard('modele', 'VALORANT', '800');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => window.tse.global.on());
  await attendre(page, () => [...document.querySelectorAll('.side-nav-card')]
    .some((c) => c.dataset.tseLogin === 'milieu' && c.dataset.tseViewers === '900'), 15_000);

  const rang = () => page.evaluate(() =>
    window.tse.global.top(10).map((r) => `${r.login}:${r.viewers}`));
  const un = await rang();
  ok('les trois co-streamers gardent le nombre du répertoire',
     ['aa:1101', 'bb:1148', 'cc:1093'].every((x) => un.includes(x)), un.join(' '));
  /* LA CONSÉQUENCE VISIBLE : sans le correctif, les trois passent SOUS une
     chaîne qui en affiche 900 — mesuré. */
  ok('…et aucun ne passe sous une chaîne qui en affiche moins',
     ['aa:1101', 'bb:1148', 'cc:1093']
       .every((x) => un.indexOf(x) < un.indexOf('milieu:900')), un.join(' '));
  await wait(page, 4000);
  const deux = await rang();
  ok('…et rien ne bat d\'un cycle à l\'autre',
     ['aa:1101', 'bb:1148', 'cc:1093'].every((x) => deux.includes(x))
     && deux.includes('milieu:900'), deux.join(' '));
  await page.close();

  /* ── ET LE COMPTEUR QUI ÉTAIT AVEUGLE LÀ OÙ LE BUG VIT ───────────────────
     Le bilan de la 4.13.11 ne parcourait que les GROUPES ACTIFS, or un groupe
     n'est actif qu'à partir de DEUX cartes visibles. Une session réduite à un
     seul membre à l'écran — le cas même qu'on cherche — n'était comptée nulle
     part : le premier rapport de terrain a rendu « pastilles 3 » sur les
     cartes et un bilan rigoureusement à zéro. */
  const p2 = await fresh();
  await p2.evaluate(() => {
    const h = (min) => new Date(Date.now() - min * 60_000).toISOString();
    const trio = ['seulvu', 'part1', 'part2'];
    /* ── LES DEUX ABSENTS N'ONT PAS DE COMBINÉ, ET C'EST LE CAS QU'ON JOUE ──
       Twitch rend `collaborationViewersCount: null` pour certains
       participants d'une même session — c'est observé, et c'est écrit au-dessus
       de la requête. Ces deux-là restent donc sous la coupe sur leur audience
       propre, ce qui est le cas SAIN. Depuis la 4.15.7, un membre dont le
       combiné est connu remonte au classement et obtient une carte : lui donner
       un combiné ici ferait deux membres visibles, donc un groupe dessiné, et
       le scénario cesserait de jouer la session réduite à UN seul visible. */
    const guests = [
      { id: '900', login: 'seulvu', viewers: 300, combined: 1300 },
      { id: '901', login: 'part1', viewers: 40, combined: null },
      { id: '902', login: 'part2', viewers: 40, combined: null }];
    const bruit = [...Array(50)].map((_, i) => ({ login: 'n' + i, viewers: 900 - i }));
    window.__cats = [
      { name: 'VALORANT', viewers: 90_000, streams: [
        { login: 'seulvu', viewers: 1300 }, { login: 'modele', viewers: 1200 }, ...bruit] },
      { name: 'Discussions', viewers: 80, streams: [
        { login: 'part1', viewers: 40 }, { login: 'part2', viewers: 40 }] },
    ];
    window.__fx = Object.fromEntries([
      ['seulvu', { id: '900', createdAt: h(60), viewers: 300, game: 'VALORANT', tags: [] }],
      ['part1', { id: '901', createdAt: h(490), viewers: 40, game: 'Discussions', tags: [] }],
      ['part2', { id: '902', createdAt: h(120), viewers: 40, game: 'Discussions', tags: [] }],
      ['modele', { id: '912', createdAt: h(30), viewers: 1200, game: 'VALORANT', tags: [] }],
      ...bruit.map((x) => [x.login, { id: 'b' + x.login, createdAt: h(30),
                                      viewers: x.viewers, game: 'VALORANT', tags: [] }]),
    ]);
    window.__gs = Object.fromEntries(trio.map((l, i) =>
      ['90' + i, { hostId: '9000', hostLogin: 'hote', guests }]));
    window.__addCard('modele', 'VALORANT', '1,2 k');
  });
  await attendre(p2, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await p2.evaluate(() => window.tse.global.on());
  await attendre(p2, () => (window.tse.panneau.rapport().coStream?.sessions || 0) > 0, 15_000);
  await wait(p2, 1200);

  const vu = await p2.evaluate(() => ({
    bilan: window.tse.panneau.rapport().coStream,
    dessines: document.querySelectorAll('.side-nav-card.tse-costream').length,
  }));
  /* ── CE QUE LA 4.18 A CHANGÉ ICI, ET POURQUOI C'EST LA DEMANDE ─────────
     CETTE ASSERTION EXIGEAIT « groupes 0 · dessines 0 » : une session dont un
     seul membre était visible ne dessinait rien, et le scénario existait pour
     qu'elle soit COMPTÉE malgré tout. Depuis qu'un co-stream occupe UNE place,
     ses deux membres sous la coupe sortent avec elle — le groupe se dessine,
     et il ne reste absent que celui dont la marche ignore jusqu'à l'existence.

     LE SUJET DU SCÉNARIO SURVIT ENTIER : une session est vue et comptée même
     quand tous ses membres ne sont pas là. Ce qui change est le NOMBRE de
     membres que la liste peut montrer, et c'est précisément la correction
     demandée — « affiche l'ensemble des streamers d'un co-stream ». */
  ok('la session est vue, et la place fait remonter ses membres sous la coupe',
     vu.bilan.sessions === 1 && vu.bilan.groupes === 1 && vu.dessines === 3,
     JSON.stringify(vu));
  /* ── ET LA 4.18.1 A VIDÉ LA DERNIÈRE CASE ─────────────────────────────
     Cette assertion tenait « il reste le seul que la marche ignore ». Elle ne
     le peut plus : la place se complète désormais avec les membres que le
     répertoire ne rend pas, et c'est précisément la demande — « le co-stream
     devrait être composé de trois streamers, là il n'y en a que deux ». En
     mode « Top Chaînes » et hors filtre de langue, une session connue de
     Guest Star est donc affichée ENTIÈRE. */
  ok('…et il ne reste plus personne dehors',
     vu.bilan.affiches === 4 && vu.bilan.horsClassement === 0
     && vu.bilan.sousLaCoupe === 0
     && vu.bilan.classesNonAffichees === 0, JSON.stringify(vu.bilan));
  /* MÊME RAISON QU'AU SCÉNARIO 135 : l'assertion qui vivait ici tenait
     « aucun des deux n'y est avec un combiné connu ». Les deux ne sont plus
     sous la coupe — la place les en a sortis — et le compteur vaut donc zéro
     mécaniquement. Retirée plutôt que laissée verdir sur du vide. */
  await p2.close();
}

/* ═════════ UN DÉCOR QUI BOUCLE, OU QUI SAUTE ═════════════════════════════
   SIGNALÉ DEPUIS LE TERRAIN, CAPTURE À L'APPUI : « j'aimerais que les effets
   CSS soient parfaitement bouclés, ce qui n'est pas le cas sur le fond de ce
   type de carte ». Le fond de la carte abonnée, quinze secondes le tour.

   TROIS DE SES QUATRE NAPPES N'ARRIVAIENT PAS OÙ ELLES PARTAIENT — 0 % d'un
   côté, 100 % de l'autre — et avec un fond qui ne se répète pas, ce sont deux
   points différents de la carte. Quinze secondes de dérive lente, puis un saut
   sec. La quatrième bouclait déjà : le remède était posé à côté du défaut.

   RIEN NE TENAIT CE CONTRAT. Le banc mesurait la couleur, la vitesse, le plan
   d'empilement de ce décor — jamais sa COUTURE, qui n'existe qu'à une image du
   cycle et qu'aucune capture ne montre. Ce scénario la mesure, et il ne tient
   aucune liste : il demande à chaque animation quelles propriétés elle touche,
   par `getKeyframes()`, et compare le rendu à la première et à la dernière
   image. Une animation ajoutée demain est donc couverte sans qu'on y pense.

   DEUX EXCEPTIONS, ET ELLES SE PROUVENT AU LIEU DE S'EXCUSER. Une valeur qui
   diffère aux deux bouts n'est pas forcément une couture : elle peut être hors
   cadre, ou décalée d'exactement une tuile. Ces deux cas-là ne sont pas
   inscrits sur une liste d'exemptions — ils sont CALCULÉS, en pixels rendus,
   par les deux assertions qui suivent. Le jour où l'un cesse d'être vrai, il
   tombe du côté des coutures. */
{
  titre('137. Le décor de la carte abonnée — chaque cycle revient où il est parti');
  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = { abo: { id: '1', createdAt: h, viewers: 900, game: 'G', tags: [] } };
    window.__addCard('abo', 'G', '900');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);

  const releve = await page.evaluate(() => {
    const carte = [...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === 'abo');
    if (!carte) return { erreur: 'carte absente' };
    /* LA MARQUE EST POSÉE ICI, DANS LA MÊME ÉVALUATION QUE LA MESURE. Le scan
       suivant la retirerait — applySubStyle nettoie ce qui ne lui revient pas —
       et ce qu'on éprouve n'est pas le relevé des abonnements, c'est la feuille
       de style seule : les images-clés, telles que le moteur les interpole. */
    carte.classList.add('tse-sub');
    void carte.offsetHeight;
    const IGNORE = new Set(['offset', 'computedOffset', 'easing', 'composite']);
    const vues = [];
    for (const a of carte.getAnimations({ subtree: true })) {
      const cible = a.effect.target;
      const pseudo = a.effect.pseudoElement || null;
      const duree = a.effect.getComputedTiming().duration;
      if (!Number.isFinite(duree) || duree <= 0) continue;
      const props = new Set();
      for (const k of a.effect.getKeyframes())
        for (const nom of Object.keys(k)) if (!IGNORE.has(nom)) props.add(nom);
      const lire = (t) => {
        a.currentTime = t;
        const st = getComputedStyle(cible, pseudo);
        return [...props].map((n) => n.startsWith('--')
          ? st.getPropertyValue(n).trim() : String(st[n]));
      };
      /* LA DERNIÈRE IMAGE, PAS LE REBOUCLAGE : à `duree` exacte le moteur a
         déjà repassé à zéro, et tout paraîtrait boucler. Une milliseconde
         avant, on lit ce que l'œil voit juste avant le saut. */
      const debut = lire(0);
      const fin = lire(duree - 1);
      /* UNE VALEUR SE COMPARE COUCHE PAR COUCHE, et d'abord comme du texte.
         « background-position » en porte quatre, séparées par des virgules :
         les fondre en une seule chaîne dirait « ça diffère » sans dire OÙ, et
         c'est justement le OÙ qui sépare la couture de l'exception.

         PUIS COMME DES NOMBRES : quinze secondes d'interpolation laissent un
         résidu de virgule flottante — « 0,0101333 % » là où on a écrit
         « 0 % » — qui n'est pas une couture. Le centième de pour-cent est
         large pour ce résidu, et mille fois trop serré pour une nappe qui ne
         reviendrait pas où elle est partie. */
      const couches = (x, y) => {
        if (x === y) return [];
        const a2 = x.split(','), b2 = y.split(',');
        if (a2.length !== b2.length) return [-1];
        const dur = [];
        for (let i = 0; i < a2.length; i++) {
          if (a2[i].trim() === b2[i].trim()) continue;
          const u = parseFloat(a2[i]), v = parseFloat(b2[i]);
          if (Number.isFinite(u) && Number.isFinite(v) && Math.abs(u - v) < 0.02) continue;
          dur.push(i);
        }
        return dur;
      };
      vues.push({ nom: a.animationName, duree, props: [...props],
        coutures: [...props].map((n, i) => {
          const dur = couches(debut[i], fin[i]);
          return dur.length ? { prop: n, couches: dur, debut: debut[i], fin: fin[i] } : null;
        }).filter(Boolean) });
    }
    return { vues };
  });

  // Le décor doit EXISTER, sans quoi « aucune couture » serait vrai pour rien.
  const noms = (releve.vues || []).map((v) => v.nom);
  ok('la carte abonnée porte bien ses animations de décor',
     noms.includes('tse-sub-lueur') && noms.includes('tse-sub-titre')
     && noms.includes('tse-sub-halo'), JSON.stringify(noms));

  /* LA COUTURE DU FOND — celle qui a été signalée. Les quatre nappes sont
     jugées ensemble, et une seule d'entre elles a le droit de différer : le
     balayage, dont la deuxième assertion prouve qu'il est hors cadre. */
  const lueur = (releve.vues || []).find((v) => v.nom === 'tse-sub-lueur');
  /* LA NAPPE 0 EST LE BALAYAGE — la seule qui ait le droit de différer, et
     l'assertion suivante prouve pourquoi. Les trois autres sont celles qui
     sautaient : c'est ici, et nulle part ailleurs, que le défaut signalé
     reviendrait se déclarer. */
  const sautent = lueur
    ? lueur.coutures.flatMap((c) => c.couches.filter((i) => i !== 0).map((i) => [c.prop, i]))
    : [['aucune animation', -1]];
  ok('la lueur de fond revient exactement où elle est partie, nappe par nappe',
     sautent.length === 0, JSON.stringify({ sautent, releve: lueur }));

  /* ET TOUT LE RESTE DU DÉCOR, sans liste à tenir : ce qui reste après les
     deux exceptions calculées plus bas doit être vide. */
  const autres = (releve.vues || [])
    .filter((v) => v.nom !== 'tse-sub-lueur' && v.nom !== 'tse-sub-titre')
    .filter((v) => v.coutures.length);
  ok('…et aucune autre animation du décor ne saute en fin de cycle',
     autres.length === 0, JSON.stringify(autres));

  /* ── EXCEPTION 1 : LE BALAYAGE EST HORS CADRE AUX DEUX BOUTS ────────────
     Il ne boucle pas, il n'a pas à boucler : il traverse la carte une fois par
     cycle et attend le suivant en coulisse. « En coulisse » n'est pas une
     opinion — on convertit sa position en pixels rendus, à partir de sa propre
     taille de fond et de la largeur de la boîte, et on exige que l'image ne
     touche pas l'intervalle peint. Le retour de 210 % à −110 % est sec, et il
     ne se voit pas parce qu'il se fait entièrement en dehors. */
  const balayage = await page.evaluate(() => {
    const carte = [...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === 'abo');
    carte.classList.add('tse-sub');
    void carte.offsetHeight;
    const a = carte.getAnimations({ subtree: true })
      .find((x) => x.animationName === 'tse-sub-lueur');
    if (!a) return { erreur: 'lueur absente' };
    const ou = (t) => {
      a.currentTime = t;
      const st = getComputedStyle(carte, '::after');
      const W = parseFloat(st.width);
      const large = parseFloat(st.backgroundSize.split(',')[0]) / 100 * W;
      const pos = parseFloat(st.backgroundPositionX.split(',')[0]);
      const gauche = pos / 100 * (W - large);
      return { W: +W.toFixed(1), gauche: +gauche.toFixed(1),
               droite: +(gauche + large).toFixed(1) };
    };
    const d = a.effect.getComputedTiming().duration;
    return { debut: ou(0), fin: ou(d - 1) };
  });
  const dehors = (x) => x && (x.droite <= 0 || x.gauche >= x.W);
  ok('le balayage est entièrement hors de la carte à la première image comme à la dernière',
     dehors(balayage.debut) && dehors(balayage.fin),
     JSON.stringify(balayage));

  /* ── EXCEPTION 2 : L'OR DU NOM SE DÉCALE D'UNE TUILE ENTIÈRE ────────────
     Il va de 0 % à 300 %, et sa tuile fait 300 % : un pas d'exactement une
     tuile, sur un fond qui se répète. Ce pas n'est invisible qu'à une
     condition — que les deux bords de la tuile portent la même couleur — et
     c'est la condition qu'on vérifie, sur le dégradé tel qu'il est calculé. */
  const or = await page.evaluate(() => {
    const nom = [...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === 'abo')?.querySelector('p.tse-nom');
    if (!nom) return { erreur: 'nom absent' };
    const st = getComputedStyle(nom);
    const couleurs = [...st.backgroundImage.matchAll(/rgba?\([^)]*\)/g)].map((m) => m[0]);
    return { taille: parseFloat(st.backgroundSize), repete: st.backgroundRepeat,
             premiere: couleurs[0], derniere: couleurs[couleurs.length - 1],
             stops: couleurs.length };
  });
  const pasOr = (releve.vues || []).find((v) => v.nom === 'tse-sub-titre');
  const bordOr = pasOr && pasOr.coutures.find((c) => c.prop === 'backgroundPositionX');
  ok('le dégradé du nom avance d\'exactement une tuile, et la tuile se raccorde à elle-même',
     !!bordOr && Math.abs(parseFloat(bordOr.fin) - or.taille) < 0.1
     && or.repete === 'repeat' && or.stops >= 2
     && or.premiere === or.derniere,
     JSON.stringify({ pas: bordOr && bordOr.fin, ...or }));
  await page.close();
}

/* ═════════ UN POOL SANS RÉSERVE ÉVINCE CE QUE RIEN NE REMPLACE ═══════════
   DEUX RAPPORTS DE TERRAIN À QUATRE-VINGT-CINQ SECONDES D'INTERVALLE, et c'est
   leur ÉCART qui nomme le défaut. Le premier, la liste entière en place :

     pool 223 · threshold 959 · evicted 0

   Le second, pris juste après un changement de langue, avec un groupe de
   co-stream de trois chaînes disparu de l'affichage :

     pool 29 · threshold 0 · evicted 7 · walks 6 · light 6

   LE POOL EST PASSÉ DE 223 À 29, et la chaîne de causes est mécanique :

     1. un changement de langue emprunte LA VOIE DU TAG, qui repart d'un pool
        VIDE — les chaînes portées ne sont pas celles de la nouvelle langue ;
     2. cette voie le remplit avec la réponse du tag, plafonnée par l'API à
        GLOBAL_TAG_MAX = 30. Le pool a donc EXACTEMENT la profondeur de ce
        qu'il affiche, et pas une chaîne de plus ;
     3. `nthViewers` rend zéro quand le pool est plus court que le top : il n'y
        a pas de trentième rang. `threshold` vaut donc 0 ;
     4. la passe légère ne s'élargit que `if (threshold > 0)` — elle ne
        s'élargit donc JAMAIS, et ne visite plus que ses dix catégories
        d'amorce. Le pool reste à plat jusqu'à la marche complète suivante,
        cent cinquante secondes plus tard ;
     5. dans ce pool, le plancher de réponse ne protège plus PERSONNE : il dit
        « sous ce compteur, la réponse s'était arrêtée », et il n'y a personne
        en dessous. Chaque échantillonnage de Twitch — mesuré, documenté dix
        mille lignes plus haut : « rubius présent quatre fois sur six » — compte
        alors comme une vraie absence. Trois passes, et la chaîne est évincée,
        sans rien derrière pour la remplacer.

   LES CO-STREAMS PARTENT EN GROUPE, ET C'EST STRUCTUREL. Leurs membres
   portent tous le compteur COMBINÉ — un nombre haut, donc toujours au-dessus
   du plancher — et le répertoire range volontiers la session sous un seul
   participant. Les autres sont absents tout en ayant l'air d'avoir dû y être.
   Le groupe entier disparaît d'un coup, ce que le terrain décrit mot pour mot :
   « y'a encore des co-streams qui disparaissent quand y'a une update ».

   CE SCÉNARIO REJOUE LA SÉQUENCE EXACTE : pool profond, changement de langue,
   puis des passes où le trio est absent du répertoire. */
{
  titre('138. Top Chaînes — un pool sans réserve n\'évince plus ce que rien ne remplace');
  const page = await fresh();
  await page.evaluate(() => {
    /* UNE DESCENTE PROFONDE D'ABORD : quinze catégories bien remplies, de quoi
       donner au pool la réserve qu'il avait dans le premier rapport. */
    const cats = [];
    for (let i = 0; i < 15; i++) {
      const streams = [];
      for (let k = 0; k < 30; k++) {
        streams.push({ login: `en${i}_${k}`, viewers: 9000 - i * 100 - k,
                       tags: ['English'] });
      }
      cats.push({ name: 'c' + i, viewers: 500_000 - i, streams });
    }
    /* DEUX FRANÇAISES MODESTES, et elles ne sont pas décoratives : le menu de
       langue n'offre que ce que le pool contient. Sans elles, l'option
       « Français » n'existe pas et le scénario mesurerait un clic dans le
       vide — ce qu'il a fait au premier essai. */
    cats.push({ name: 'frcat', viewers: 499_000, streams: [
      { login: 'petite1', viewers: 100, tags: ['Français'] },
      { login: 'petite2', viewers: 90,  tags: ['Français'] },
    ] });
    window.__cats = cats;
    window.__tagTop = {};
  });
  await wait(page, 2500);
  await page.evaluate(() => {
    const b = [...document.querySelectorAll('.tse-mode-tab')]
      .find((x) => x.dataset.tseMode === 'global');
    if (b) b.click();
  });
  await attendre(page, () => window.tse.global.report().pool > 100, 15_000);
  const profond = await page.evaluate(() => {
    const r = window.tse.global.report();
    return { pool: r.pool, threshold: r.threshold };
  });
  ok('au départ le pool a de la réserve, et un seuil',
     profond.pool > 100 && profond.threshold > 0, JSON.stringify(profond));

  /* ── LE CHANGEMENT DE LANGUE, ET LA VOIE DU TAG QUI APLATIT ──────────────
     Trente entrées, comme l'API les plafonne, dont LE TRIO DE CO-STREAM : même
     catégorie, même compteur combiné, comme Twitch les rend. */
  await page.evaluate(() => {
    /* VINGT-NEUF, PAS TRENTE, et c'est tout le scénario. `nthViewers` rend
       zéro quand le pool est PLUS COURT que le top : à trente pile, le seuil
       vaut 2 100 et la garde ne se déclenche pas. Le terrain a rendu 29 — une
       entrée écartée par `readStream`, un empileur de tags — et c'est ce 29
       qui met le seuil à zéro. Le premier jet de ce scénario en posait trente
       et ne reproduisait rien. */
    const top = [];
    for (let k = 0; k < 26; k++) {
      top.push({ login: `fr${k}`, viewers: 5000 - k * 100, game: 'c0',
                 tags: ['Français'] });
    }
    for (const l of ['duoA', 'duoB', 'duoC']) {
      top.push({ login: l, viewers: 2100, game: 'c0', tags: ['Français'] });
    }
    window.__tagTop = { 'Français': top };
  });
  /* L'OPTION EST ATTENDUE, PUIS SON CLIC EST CONSTATÉ. Cliquer sans vérifier
     a donné, au premier essai, trois assertions vertes sur un décor qui
     n'avait pas changé de langue du tout. */
  await attendre(page, () => !![...document.querySelectorAll('#tse-lang-dd .tse-dd-opt')]
    .find((o) => (o.dataset.value || '') === 'Français'), 15_000);
  const clique = await page.evaluate(() => {
    const opt = [...document.querySelectorAll('#tse-lang-dd .tse-dd-opt')]
      .find((o) => (o.dataset.value || '') === 'Français');
    if (!opt) return false;
    opt.click();
    return true;
  });
  ok('le menu offre bien la langue, et le clic porte',
     clique === true, String(clique));
  await attendre(page, () => window.tse.global.report().tags.servis > 0, 15_000);
  await wait(page, 500);
  const aPlat = await page.evaluate(() => {
    const r = window.tse.global.report();
    return { pool: r.pool, threshold: r.threshold, servis: r.tags.servis,
             trio: window.tse.global.top(500)
               .filter((x) => x.login.startsWith('duo')).length };
  });
  /* LA PRÉMISSE DU SCÉNARIO. Sans elle, tout ce qui suit mesurerait autre
     chose : c'est bien un pool de la profondeur de l'affichage, sans seuil. */
  ok('la voie du tag laisse un pool sans réserve, et sans seuil',
     aPlat.servis > 0 && aPlat.pool <= 30 && aPlat.threshold === 0
     && aPlat.trio === 3, JSON.stringify(aPlat));

  /* ── ET MAINTENANT TWITCH ÉCHANTILLONNE ─────────────────────────────────
     Le trio sort du répertoire ET du classement par tag, comme le fait une
     session que Twitch range sous son seul hôte. On laisse passer LARGEMENT
     plus que GLOBAL_MISS_CONFIRM passes. */
  await page.evaluate(() => {
    window.__tagTop['Français'] = window.__tagTop['Français']
      .filter((x) => !x.login.startsWith('duo'));
    for (const c of window.__cats) {
      c.streams = (c.streams || []).filter((x) => !x.login.startsWith('duo'));
    }
  });
  /* ON LAISSE PASSER LE TEMPS QU'IL FAUT POUR ÉVINCER, PAS UN DÉLAI ROND.
     Mesuré sur le mutant : trois passes légères suffisent — « misses 9,
     evicted 3 », les trois d'un coup. On attend donc la disparition, et c'est
     de NE PAS l'obtenir que l'assertion tire sa force. */
  await attendre(page,
    () => window.tse.global.top(500)
            .filter((x) => x.login.startsWith('duo')).length < 3, 25_000);

  const apres = await page.evaluate(() => {
    const r = window.tse.global.report();
    return { pool: r.pool, evicted: r.evicted, sansReserve: r.sansReserve,
             misses: r.misses,
             trio: window.tse.global.top(500)
               .filter((x) => x.login.startsWith('duo')).map((x) => x.login) };
  });
  /* L'ASSERTION QUI PORTE LE RAPPORT. Remettre l'éviction sans réserve la fait
     tomber, et elle seule suffit : c'est le groupe disparu, rejoué. */
  ok('le groupe de co-stream survit à l\'échantillonnage dans un pool sans réserve',
     apres.trio.length === 3, JSON.stringify(apres));
  ok('…rien n\'est évincé tant que le pool n\'a pas de réserve',
     apres.evicted === 0, JSON.stringify(apres));
  /* ET LE REFUS SE COMPTE. « evicted 0 » pendant que des chaînes
     disparaissaient, c'est ce qui avait rendu le premier rapport muet : le
     nombre qui aurait tout dit n'existait pas. */
  /* LES ABSENCES SONT BIEN COMPTÉES — ce n'est pas elles qu'on refuse. La
     garde est au RETRAIT, pas au constat : une chaîne peut accumuler ses
     absences sans qu'on la retire d'un pool qui n'a pas de quoi la remplacer.
     Le jour où le pool se recreuse, elles redeviennent décisives. */
  ok('…et le refus de retirer est LUI-MÊME compté, ce qu\'aucun chiffre ne disait',
     apres.sansReserve > 0 && apres.misses > 0, JSON.stringify(apres));

  /* ── LA PASSE LÉGÈRE RECREUSE, AU LIEU D'ATTENDRE LA MARCHE COMPLÈTE ─────
     C'est l'autre moitié du correctif, et elle se mesure à part : sans elle,
     la garde ci-dessus se contenterait de FIGER un pool à plat. */
  ok('…et le pool se recreuse au lieu de rester à la profondeur de l\'affichage',
     apres.pool > aPlat.pool, JSON.stringify({ avant: aPlat.pool, apres: apres.pool }));
  await page.close();
}

/* ═════════ UNE SESSION QUI MAIGRIT N'EST PAS UNE SESSION QUI FINIT ═══════
   LE DÉFAUT QUE DEUX CAPTURES ONT NOMMÉ, ET QUE TROIS RAPPORTS N'ONT PAS SU
   DIRE. Le rapport de terrain était complet et il disait vrai : « pool 707,
   evicted 0, creux 0, sansReserve 0 ». Aucun des chemins de retrait n'avait
   servi. Et pourtant, d'une capture à l'autre à une minute d'intervalle, un
   groupe de cinq co-streamers « Valheim, 4 k » tombait à deux, et un groupe
   de quatre « WARDOGS, 1,9 k » tombait à un.

   CE SONT LES CAPTURES QUI PORTENT LA PREUVE : la pastille d'un survivant
   passe de « 4 » à « 2 », et son compteur de 1,9 k à 1,7 k. La session n'avait
   pas disparu — elle avait MAIGRI, dans le cache.

   LE CHEMIN, DANS L'ORDRE :

     1. le lot Guest Star rend une liste d'invités plus courte ;
     2. `flushGuestStar` écrivait cette liste telle quelle, et pour les chaînes
        dont la réponse ne portait plus rien, il écrivait « pas de session » —
        mates vidés, combiné à null, hôte à null ;
     3. le lot de chaînes suivant lit alors `getCollabViewers` à null et
        `getHostId` à null, et écrit le compteur PROPRE au classement : trois
        cents spectateurs là où le combiné en affichait quatre mille ;
     4. la carte sort du top 30. Rien n'a été évincé, rien n'a été creusé :
        elle est simplement tombée.

   ET LA GARDE DE SIGNATURE NE POUVAIT PAS L'ARRÊTER. Elle protège les
   compteurs PARTAGÉS par au moins deux entrées. Or le combiné rétréci est
   écrit AVEC AUTORITÉ — c'est le combiné, il fait foi — donc il baisse le
   compteur d'un membre ; les autres cessent alors de partager sa valeur, et
   la garde se relâche au moment précis où elle servirait. C'est une cascade,
   et elle s'arrête d'elle-même quand il ne reste qu'un ou deux membres : ce
   que les deux captures montrent, exactement.

   CE SCÉNARIO PREND LA FIN DE LA CASCADE, qui est la partie mesurable : un
   duo, dont l'un reçoit un combiné rétréci et l'autre plus de session du
   tout. Mutant — la garde retirée — les deux pastilles disparaissent ; avec,
   elles tiennent, et le classement garde le nombre du répertoire. */
{
  titre('139. Co-stream — une session qui maigrit ne se perd pas d\'un coup');
  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    const c = (id, v) => ({ id, createdAt: h, viewers: v, game: 'Valheim', tags: [] });
    /* DEUX CO-STREAMERS AU MÊME COMBINÉ, et leurs audiences propres sont
       dérisoires : c'est tout l'écart que le défaut exploite. « milieu » sert
       de témoin de fraîcheur ordinaire, comme au scénario 133. */
    window.__cats = [{ name: 'Valheim', viewers: 9000, streams: [
      { login: 'unaa', viewers: 4000 }, { login: 'unbb', viewers: 4000 },
      { login: 'milieu', viewers: 900 }, { login: 'modele', viewers: 800 }] }];
    window.__fx = { unaa: c('9401', 300), unbb: c('9402', 300),
                    milieu: c('9404', 950), modele: c('9405', 800) };
    const guests = [
      { id: '9401', login: 'unaa', viewers: 300, combined: 4000 },
      { id: '9402', login: 'unbb', viewers: 300, combined: 4000 }];
    window.__gs = {
      '9401': { hostId: '9400', hostLogin: 'unaa', guests },
      '9402': { hostId: '9400', hostLogin: 'unaa', guests } };
    window.__addCard('modele', 'Valheim', '800');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => window.tse.global.on());
  await attendre(page, () => [...document.querySelectorAll('.side-nav-card')]
    .some((c) => c.dataset.tseLogin === 'milieu' && c.dataset.tseViewers === '950'), 15_000);
  await wait(page, 1500);

  const lire = () => page.evaluate(() => {
    const aff = (l) => [...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === l)?.dataset.tseViewers ?? null;
    const r = window.tse.panneau.rapport().coStream;
    return { rang: window.tse.global.top(50)
               .filter((x) => x.login.startsWith('un')).map((x) => `${x.login}:${x.viewers}`),
             cartes: ['unaa', 'unbb'].map(aff),
             pastilles: [...document.querySelectorAll('.side-nav-card.tse-costream')]
               .map((c) => c.querySelector('.tse-collab-badge')?.textContent ?? null),
             gardees: r.gardees, chutes: r.chutes };
  });
  const plein = await lire();
  /* LA PRÉMISSE : sans elle, tout ce qui suit mesurerait un décor sans
     co-stream, et serait vert pour rien. */
  ok('les deux co-streamers portent le combiné, et leur pastille',
     plein.rang.length === 2 && plein.rang.every((x) => x.endsWith(':4000'))
     && plein.pastilles.length === 2, JSON.stringify(plein));

  /* ── LA SESSION MAIGRIT ─────────────────────────────────────────────────
     Twitch ne rend plus que l'hôte dans la liste d'invités, avec un combiné
     plus petit ; pour l'autre membre, la réponse ne porte plus de session.
     C'est mot pour mot ce que les captures montrent. On attend PLUS que
     GUEST_STAR_TTL, sans quoi aucun lot ne repart et le décor ne joue rien —
     ce qui a rendu le premier jet de ce scénario vert pour rien. */
  await page.evaluate(() => {
    window.__gs = { '9401': { hostId: '9400', hostLogin: 'unaa',
      guests: [{ id: '9401', login: 'unaa', viewers: 300, combined: 1700 }] } };
  });
  await attendre(page, () => (window.tse.panneau.rapport().coStream?.gardees || 0) > 0, 40_000);
  await wait(page, 1500);
  const maigre = await lire();

  /* L'ASSERTION QUI PORTE LE RAPPORT. Mutant : « pastilles: [] ». */
  ok('la session rétrécie ne détruit pas les sessions connues',
     maigre.pastilles.length === 2, JSON.stringify(maigre));
  ok('…et le membre sur lequel Guest Star se tait garde le nombre du répertoire',
     maigre.rang.includes('unbb:4000') && maigre.cartes[1] === '4000',
     JSON.stringify(maigre));
  /* LE COMBINÉ FRAIS DE LA CHAÎNE INTERROGÉE, LUI, EST CRU : c'est la seule
     chose de cette réponse qui porte sur ELLE, et la refuser figerait le
     compteur d'une session qui rétrécit pour de bon. */
  ok('…tandis que le combiné frais de la chaîne interrogée est bien pris',
     maigre.cartes[0] === '1700', JSON.stringify(maigre.cartes));
  /* ET LE REFUS SE COMPTE, comme sousPlancher, creux et sansReserve avant lui.
     C'est le quatrième chemin de retrait, et le premier qui se voyait sur une
     capture d'écran sans se voir dans aucun rapport. */
  /* SEUL « gardees » PORTE LE CONTRAT ICI. La première écriture exigeait aussi
     « chutes > 0 », et c'était une erreur d'assertion : qu'un compteur révisé à
     la baisse passe par setViewers pendant CE scénario dépend de l'ordre des
     deux files, pas de la garde qu'on éprouve. Vu vert sur une branche et
     rouge sur l'autre, à décor identique — une assertion qui dépend du hasard
     ne mesure rien, et affaiblit celle d'à côté en la rendant suspecte. */
  ok('…et la garde se compte au rapport, ce qu\'aucun chiffre ne disait',
     maigre.gardees > 0, JSON.stringify(maigre));
  await page.close();
}

/* ═════════ LE RÉPERTOIRE CONTRE LE COMBINÉ, ET LE PIÈGE SANS RETOUR ══════
   LE DERNIER ÉCRIVAIN QUI N'ÉTAIT NI GARDÉ NI COMPTÉ. Trois versions ont
   cherché ce défaut ; c'est un rapport ÉQUIPÉ DES COMPTEURS DE LA 4.14.2 qui
   l'a désigné, par pure élimination :

     sousLaCoupe 8 · horsClassement 0 · chutes 2 · chuteMax 24
     chutesHorsEcran 0 · evicted 0 · gardees 0 · pool 753

   Douze membres de session, quatre affichés, HUIT dans le pool sous le
   trentième rang. Rien d'évincé, aucune session perdue, et aucune chute de
   compteur digne de ce nom — vingt-quatre spectateurs au maximum. Les huit
   avaient donc perdu leur combiné SANS passer par `setViewers`, qui est le
   seul endroit où vivent les trois gardes et les trois compteurs.

   IL NE RESTAIT QU'UN CHEMIN. `harvest` écrit le répertoire dans le pool par
   `pool.set(login, rec)`, en REMPLAÇANT l'enregistrement entier. Ni la garde
   de signature, ni celle de la réserve, ni le compteur de chutes ne voient
   passer cette écriture. Or le répertoire range couramment une session sous
   son seul hôte : les autres participants y figurent avec leur audience
   PROPRE — trois cents au lieu de quatre mille — et retombent sous la coupe.

   ET C'EST UN PIÈGE, PAS UN SCINTILLEMENT. Le combiné n'arrive que par la voie
   des CARTES, et une chaîne sous le trentième rang n'a pas de carte. Rien ne
   peut donc la relever : elle reste en bas jusqu'à ce que le répertoire change
   d'avis. Les captures le montrent — cinq co-streamers « Valheim, 4,1 k »,
   puis un seul, et les quatre autres jamais revenus.

   DEUX RÉGLAGES DU DÉCOR ONT ÉTÉ NÉCESSAIRES, et chacun a d'abord donné un
   scénario vert pour rien :

     — LA RÉPONSE PAR CATÉGORIE EST PLAFONNÉE À TRENTE. Dans une seule
       catégorie chargée de bruit, les membres à trois cents n'y figurent même
       pas : le décor jouait leur ABSENCE du pool, pas leur chute sous la
       coupe. Le bruit vit donc dans sa propre catégorie ;
     — IL FAUT UNE AMORCE PAR CARTE SUIVIE. Guest Star n'est résolu que pour
       les chaînes qui ont une carte ; sans cette amorce, la session n'est
       jamais connue et le décor joue son absence au lieu du blocage. */
{
  titre('140. Co-stream — le combiné connu prime sur ce que le répertoire raconte');
  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    const c = (id, v) => ({ id, createdAt: h, viewers: v, game: 'Valheim', tags: [] });
    const bruit = [];
    for (let k = 0; k < 35; k++) bruit.push({ login: 'n' + k, viewers: 2000 - k * 20 });
    /* LE RÉPERTOIRE RANGE LA SESSION SOUS SON HÔTE : unaa y figure avec le
       combiné, unbb et uncc avec leur audience propre. C'est le seul point du
       décor qui compte, et c'est ce que le terrain montre. */
    window.__cats = [
      { name: 'Autre', viewers: 200_000, streams: bruit },
      { name: 'Valheim', viewers: 90_000, streams: [
        { login: 'unaa', viewers: 4000 },
        { login: 'unbb', viewers: 300 }, { login: 'uncc', viewers: 300 },
        { login: 'modele', viewers: 800 }] }];
    window.__fx = Object.fromEntries([
      ['unaa', c('9401', 300)], ['unbb', c('9402', 300)], ['uncc', c('9403', 300)],
      ['modele', c('9405', 800)],
      ...bruit.map((x) => [x.login, { id: 'b' + x.login, createdAt: h,
                                      viewers: x.viewers, game: 'Autre', tags: [] }]),
    ]);
    const guests = [
      { id: '9401', login: 'unaa', viewers: 300, combined: 4000 },
      { id: '9402', login: 'unbb', viewers: 300, combined: 4000 },
      { id: '9403', login: 'uncc', viewers: 300, combined: 4000 }];
    window.__gs = {
      '9401': { hostId: '9400', hostLogin: 'unaa', guests },
      '9402': { hostId: '9400', hostLogin: 'unaa', guests },
      '9403': { hostId: '9400', hostLogin: 'unaa', guests } };
    window.__addCard('unaa', 'Valheim', '4 k');
    window.__addCard('unbb', 'Valheim', '300');
    window.__addCard('uncc', 'Valheim', '300');
    window.__addCard('modele', 'Valheim', '800');
  });
  /* L'AMORCE : on attend que Guest Star soit RÉSOLU, pas qu'un délai passe. */
  await attendre(page,
    () => document.querySelectorAll('.side-nav-card.tse-costream').length >= 2, 15_000);
  await page.evaluate(() => window.tse.global.on());
  await wait(page, 4000);

  const vu = await page.evaluate(() => {
    const g = window.tse.global.report();
    const co = window.tse.panneau.rapport().coStream;
    return { top: window.tse.global.top(30)
               .filter((x) => x.login.startsWith('un')).map((x) => `${x.login}:${x.viewers}`),
             tous: window.tse.global.top(999)
               .filter((x) => x.login.startsWith('un')).map((x) => `${x.login}:${x.viewers}`),
             bas: g.repertoireBas, haut: g.repertoireHaut,
             sousLaCoupe: co.sousLaCoupe, piegees: co.sousLaCoupeAvecCombine };
  });

  /* L'ASSERTION QUI PORTE LE RAPPORT. Mutant : « unaa:4000 » seul au top, et
     « uncc:300, unbb:300 » dans le pool — sous la coupe, sans retour. */
  ok('les membres que le répertoire range bas gardent le combiné de leur session',
     vu.top.length === 3 && vu.top.every((x) => x.endsWith(':4000')),
     JSON.stringify(vu));
  ok('…aucun ne reste piégé sous la coupe avec un combiné connu',
     vu.piegees === 0, JSON.stringify(vu));
  /* ET L'ÉCART SE COMPTE : sans ce nombre, l'assertion ci-dessus serait vraie
     aussi le jour où le répertoire se mettrait à rendre le combiné tout seul,
     et le banc ne mesurerait plus rien. */
  ok('…et le désaccord entre le répertoire et le combiné est COMPTÉ',
     vu.bas > 0 && vu.haut === 0, JSON.stringify(vu));
  await page.close();
}

/* ═════════ DEUX ONGLETS TWITCH NE RELÈVENT PAS DEUX FOIS ═════════════════
   QUESTION VENUE DU TERRAIN : « le relevé d'abonnement se fait dès
   l'initialisation ? » La réponse mesurée est NON dans le cas courant — le
   garde de période rend la main sans rien charger — et OUI dans deux cas qui
   le méritent : une extension fraîchement installée, et un relevé plus vieux
   que la période choisie.

   MAIS LA QUESTION EN A OUVERT UNE AUTRE, et celle-là cachait un défaut.
   L'horodatage est écrit à la FIN du relevé, et c'est voulu : il veut dire
   « un relevé est allé à son terme », et quiconque le lit doit trouver le
   résultat déjà en mémoire. Entre le début et la fin, il vaut donc encore
   l'ancienne date — et une seconde page Twitch qui démarre pendant ce temps
   la lit, la croit périmée, et part à son tour.

   MESURÉ : deux onglets ouverts ensemble sur un profil neuf chargeaient HUIT
   pages de Twitch en cachette au lieu de quatre. Une session restaurée à cinq
   onglets en aurait chargé vingt.

   POURQUOI CE SCÉNARIO SERT SA PROPRE PAGE, et c'est le point qui a failli
   me faire conclure l'inverse. Tout ce banc travaille en `file://`, où CHAQUE
   PAGE A SON PROPRE `localStorage` : deux pages y sont deux mondes, aucune ne
   voit l'horodatage de l'autre, et le défaut y est donc à la fois invisible
   et impossible à corriger. Ma première mesure a montré « huit iframes » avec
   le correctif en place, et j'ai cru le correctif inopérant — alors que le
   décor ne pouvait rien mesurer du tout.

   Il faut donc une ORIGINE, et une seule pour les deux pages : un serveur
   local, et deux onglets du MÊME contexte — `browser.newPage()` en ouvre un
   par page, ce qui recloisonne le stockage et reproduit le même piège. */
{
  titre('141. Abonnements — deux onglets ouverts ensemble ne relèvent qu\'une fois');
  const { createServer } = await import('node:http');
  const { extname } = await import('node:path');
  const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8',
                  '.json': 'application/json', '.css': 'text/css' };
  const serveur = createServer((req, res) => {
    const rel = decodeURIComponent((req.url || '/').split('?')[0]).replace(/^\/+/, '');
    try {
      const corps = readFileSync(join(ICI, rel));
      res.writeHead(200, { 'Content-Type': TYPES[extname(rel)] || 'application/octet-stream' });
      res.end(corps);
    } catch { res.writeHead(404); res.end('non'); }
  });
  await new Promise((r) => serveur.listen(0, '127.0.0.1', r));
  const base = `http://127.0.0.1:${serveur.address().port}/page.html`;

  /* LE NOMBRE D'ONGLETS DU RELEVÉ SE LIT SUR LE PRODUIT, il ne se recopie
     pas : le jour où un onglet s'ajoute ou disparaît, cette borne suit toute
     seule au lieu de faire tomber le scénario pour une raison étrangère. */
  const srcAbos = readFileSync(join(ICI, '..', 'content.js'), 'utf8');
  const compteOnglets = (cle) =>
    (new RegExp(cle + ":\\s*\\[([^\\]]*)\\]").exec(srcAbos)?.[1] || '')
      .split(',').filter((x) => x.trim()).length;
  const CFG_TABS_ATTENDUS = compteOnglets('SUBS_PAGE_TABS')
                          + compteOnglets('SUBS_PAGE_TABS_PAST');
  ok('le décor connaît le nombre d\'onglets que le relevé visite',
     CFG_TABS_ATTENDUS >= 2, String(CFG_TABS_ATTENDUS));

  const ctx = await browser.newContext();
  const poser = (p) => p.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = { roicheese: { id: '2', createdAt: h, viewers: 400, game: 'G', tags: [] } };
    window.__addCard('roicheese', 'G', '400');
  });
  try {
    const a = await ctx.newPage();
    const b2 = await ctx.newPage();
    let na = 0, nb = 0;
    /* ON COMPTE LES IFRAMES À LA SOURCE, pas dans le rapport. Le premier jet
       lisait `rapport().abonnements`, qui n'existe pas — le champ s'appelle
       `relevesAbonnements` — et rendait donc « zéro onglet » partout, y
       compris là où quatre pages venaient de se charger. Un instrument muet
       est pire qu'aucun : il confirme ce qu'on espère. */
    a.on('frameattached', () => { na += 1; });
    b2.on('frameattached', () => { nb += 1; });
    a.on('pageerror', (e) => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
    b2.on('pageerror', (e) => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });

    await a.goto(base);
    /* LES DEUX PARTAGENT BIEN UNE ORIGINE. Sans cette vérification, le
       scénario entier peut passer au vert sur un décor qui ne mesure rien. */
    await a.evaluate(() => localStorage.setItem('tse:temoin', 'A'));
    await b2.goto(base);
    const partage = await b2.evaluate(() => localStorage.getItem('tse:temoin'));
    ok('les deux onglets partagent bien un stockage — sans quoi rien n\'est mesuré',
       partage === 'A', String(partage));

    /* UN RELEVÉ DE ROUTINE, ET NON UNE INSTALLATION NEUVE. La première
       écriture de ce scénario partait d'un profil vierge — et c'était le
       mauvais décor, découvert par un rapport de terrain : le TOUT PREMIER
       relevé ne se fait plus disputer par personne, parce qu'il n'a lieu
       qu'une fois et que l'utilisateur attend devant un écran vide. Le bail
       garde ce qu'il a toujours eu à garder : le relevé qui REVIENT toutes
       les six heures, et dont le doublon se répète. */
    await a.evaluate(() => {
      localStorage.clear();
      localStorage.setItem('tse:substs', '2:' + (Date.now() - 30_000));
    });
    na = 0; nb = 0;
    // Deux onglets, départ simultané : une session restaurée.
    await Promise.all([a.reload(), b2.reload()]);
    await Promise.all([poser(a), poser(b2)]);
    /* ON ATTEND LA CONDITION, PAS UN DÉLAI ROND. La première écriture posait
       neuf secondes, soit à peu près le pire cas d'un relevé au banc — abandon
       à six secondes, apaisement à 2,6 — et l'assertion de l'horodatage est
       tombée sur un relevé qui n'avait pas fini. Un délai qui frôle la durée
       qu'il attend ne mesure pas cette durée, il la tire au sort. */
    await attendre(a, () => {
      const r = window.tse.panneau.rapport().relevesAbonnements || {};
      return (r.horodatage || 0) > 0;
    }, 20_000);
    await wait(a, 800);   // laisse l'onglet rangé lire l'horodatage partagé

    const lire = (p) => p.evaluate(() => {
      const r = window.tse.panneau.rapport().relevesAbonnements || {};
      return { onglets: (r.onglets || []).length, differes: r.differes || 0,
               horodatage: r.horodatage || 0 };
    });
    const ra = await lire(a);
    const rb = await lire(b2);
    const totalIframes = na + nb;
    const releveurs = [ra, rb].filter((x) => x.onglets > 0).length;
    const rangés = [ra, rb].filter((x) => x.differes > 0).length;

    /* L'ASSERTION QUI PORTE LA MESURE. Mutant — le bail retiré — les deux
       relèvent, et le total passe à huit. */
    ok('un seul des deux onglets relève, l\'autre se range',
       releveurs === 1 && rangés === 1,
       JSON.stringify({ a: ra, b: rb, iframes: [na, nb] }));
    /* ET ON COMPTE LES PAGES RÉELLEMENT CHARGÉES : l'assertion ci-dessus
       serait vraie aussi le jour où plus personne ne relèverait du tout. */
    ok('…et le nombre de pages Twitch chargées en cachette ne double pas',
       totalIframes > 0 && totalIframes <= CFG_TABS_ATTENDUS,
       `${totalIframes} iframe(s) pour ${CFG_TABS_ATTENDUS} onglet(s) de relevé`);
    /* LE RELEVÉ A BIEN ABOUTI, et les deux pages le savent : l'horodatage est
       partagé, donc celle qui s'est rangée n'en refera pas un dans la foulée. */
    ok('…et l\'horodatage du relevé est visible des DEUX onglets',
       ra.horodatage > 0 && rb.horodatage === ra.horodatage,
       JSON.stringify({ a: ra.horodatage, b: rb.horodatage }));

    /* ── ET LE TOUT PREMIER RELEVÉ NE SE FAIT BLOQUER PAR RIEN ────────────
       LE RAPPORT DE TERRAIN, REJOUÉ AU CHIFFRE PRÈS. Un bail laissé par une
       page morte — rechargement, navigation, onglet fermé au mauvais instant
       — bloquait le premier relevé d'une installation neuve, et rien ne
       réessayait : « horodatage : jamais », aucun onglet, aucune erreur, et
       un utilisateur qui attend plusieurs minutes devant un panneau vide.

       DEUX CORRECTIFS SE MESURENT ICI D'UN COUP : le premier relevé ignore le
       bail, et le bail se rend au départ de la page. Le second ne suffisait
       pas — il ne peut rien pour un bail déjà laissé par une page d'AVANT. */
    const neuf = await ctx.newPage();
    let nn = 0;
    neuf.on('frameattached', () => { nn += 1; });
    neuf.on('pageerror', (e) => { fail++; console.log('  ✗ ERREUR PAGE:', e.message); });
    await neuf.goto(base);
    await neuf.evaluate(() => {
      localStorage.clear();                       // installation neuve
      localStorage.setItem('tse:subsrun', 'pagemorte:' + Date.now());
    });
    await neuf.reload();
    nn = 0;
    await poser(neuf);
    await attendre(neuf, () => {
      const r = window.tse.panneau.rapport().relevesAbonnements || {};
      return (r.horodatage || 0) > 0;
    }, 20_000);
    const vuNeuf = await neuf.evaluate(() => {
      const r = window.tse.panneau.rapport().relevesAbonnements || {};
      return { horodatage: r.horodatage || 0, differes: r.differes || 0,
               onglets: (r.onglets || []).length };
    });
    ok('un bail laissé par une page morte ne bloque pas le PREMIER relevé',
       vuNeuf.horodatage > 0 && vuNeuf.onglets >= 2 && nn >= 2,
       JSON.stringify({ ...vuNeuf, iframes: nn }));
    ok('…et il part sans même se ranger une fois',
       vuNeuf.differes === 0, JSON.stringify(vuNeuf));
  } finally {
    await ctx.close();
    await new Promise((r) => serveur.close(r));
  }
}

/* ═════════ LA CARTE ET LA FRISE DISENT LE MÊME NOMBRE ════════════════════
   DEUX DÉFAUTS SIGNALÉS ENSEMBLE, ET C'EST LA MÊME DURÉE QUI EST EN CAUSE.

   1) « LE TEMPS SUR LA CARTE NE SE MET PAS AUTOMATIQUEMENT À JOUR — IL SE MET
   QUAND ON PASSE LA SOURIS. » Capture à l'appui : une chaîne à « 10h15 », puis
   « 57h32 » dès l'aperçu ouvert. Ce n'était PAS un défaut de rafraîchissement,
   et c'est pour cela que le minuteur de la carte n'y pouvait rien : il faisait
   battre la bonne mécanique sur la mauvaise origine. Une coupure survenue
   AVANT l'ouverture de la page n'est dans aucune mémoire — ni la nôtre, qui
   n'existait pas, ni celle de Twitch, qui ne sert que le tronçon courant.
   Seule l'archive le dit, et la sonde qui la lit ne partait qu'au survol.

   2) « BEAUCOUP DE CARTES ONT ENVIRON UNE MINUTE DE DÉCALAGE AVEC
   PRÉCÉDEMMENT. » La cause tient en un nombre : CATEGORY_TRAIL_TOLERANCE vaut
   QUATRE-VINGT-DIX SECONDES. `inconnuMs` mesure la part non observée du
   direct ; sous la tolérance on la met à zéro — à juste titre, une seconde de
   hachuré ne dit rien — mais on la mettait à zéro SANS LA RENDRE À PERSONNE.
   Le total de la frise vaut `inconnuMs + Σ segments` : cette part disparaissait
   donc du total, tandis que la carte, qui compte depuis l'origine, ne perdait
   rien. Deux durées pour un même direct, l'écart valant l'oubli.

   CE SCÉNARIO MESURE LES DEUX, ET LE SECOND EXIGE DEUX DÉCORS : un écart
   au-dessus de la tolérance, qui passait déjà, et un écart en dessous, qui est
   le cas signalé. Sans le premier, on ne saurait pas si le correctif a cassé
   la part non observée légitime. */
{
  titre('142. La durée d\'un direct — la carte et la frise disent le même nombre');

  /* ── 1. L'ORIGINE SANS SURVOL ────────────────────────────────────────── */
  {
    const page = await fresh();
    await page.evaluate(() => {
      const neuf  = new Date(Date.now() - 60_000).toISOString();          // tronçon : 1 min
      const vieux = new Date(Date.now() - 5 * 3600_000).toISOString();    // archive : 5 h
      window.__fx = { revenu: { id: 'r1', sid: 's-r1', createdAt: neuf,
                                viewers: 900, game: 'VALORANT', tags: [] } };
      /* La PREMIÈRE archive est celle du direct en cours ; c'est la SECONDE
         qui raccorde. Le trou visé est de 1,2 s — cf. le scénario 102 pour la
         raison de ce chiffre : `lengthSeconds` est un entier de secondes. */
      window.__vodRecent = {
        revenu: [
          { createdAt: neuf, lengthSeconds: 60, chapitres: [] },
          { createdAt: vieux,
            lengthSeconds: Math.round((Date.parse(neuf) - 1_200 - Date.parse(vieux)) / 1000),
            chapitres: [{ pos: 0, jeu: 'Just Chatting' }] },
        ],
      };
      window.__addCard('revenu', 'VALORANT', '900');
    });
    /* ON N'OUVRE JAMAIS L'APERÇU DE CETTE CARTE, et c'est tout le scénario :
       la durée doit être juste sans que personne ne la survole. */
    await attendre(page, () => {
      const c = [...document.querySelectorAll('.side-nav-card')]
        .find((x) => x.dataset.tseLogin === 'revenu');
      return /h/.test(c?.querySelector('.tse-uptime')?.textContent || '');
    }, 12_000);
    const vu = await page.evaluate(() => {
      const c = [...document.querySelectorAll('.side-nav-card')]
        .find((x) => x.dataset.tseLogin === 'revenu');
      const r = window.tse.panneau.rapport().reseau.chapitres.reprise;
      return { duree: c?.querySelector('.tse-uptime')?.textContent || '',
               survols: window.tse.panneau.rapport().frise.survols,
               sondes: r.sondes, adoptees: r.adoptees };
    });
    /* L'ASSERTION QUI PORTE LE RAPPORT. Mutant — la sonde rendue au seul
       survol — la carte affiche « 1m » au lieu de « 5h00 ». */
    ok('la carte porte la durée du direct entier sans qu\'on l\'ait survolée',
       /^5h/.test(vu.duree), JSON.stringify(vu));
    /* ET C'EST BIEN SANS SURVOL : sans ce témoin, l'assertion ci-dessus
       passerait aussi le jour où un survol se glisserait dans le décor. */
    ok('…et aucun survol n\'a eu lieu — c\'est la sonde du lot qui a servi',
       vu.survols === 0 && vu.sondes >= 1 && vu.adoptees >= 1, JSON.stringify(vu));
    await page.close();
  }

  /* ── 2. LA CARTE ET LA FRISE, AU MÊME NOMBRE ─────────────────────────── */
  {
    const page = await fresh();
    await page.evaluate(() => {
      const h3    = new Date(Date.now() - 3 * 3600_000).toISOString();
      const court = new Date(Date.now() - 3 * 3600_000 - 60_000).toISOString();
      window.__fx = {
        /* ÉCART LARGE : le premier chapitre tombe une heure après le départ,
           bien au-dessus de la tolérance. La part non observée est réelle, et
           elle doit le rester — c'est le témoin de non-régression. */
        large: { id: 'a1', sid: 's-a1', createdAt: h3, viewers: 900, game: 'Rust', tags: [] },
        /* ÉCART SERRÉ : une minute, SOUS les quatre-vingt-dix secondes de
           tolérance. C'est le cas signalé, et lui seul. */
        serre: { id: 'a2', sid: 's-a2', createdAt: court, viewers: 800, game: 'Rust', tags: [] },
      };
      window.__vod = {
        large: { chapitres: [{ pos: 0, jeu: 'Just Chatting' }, { pos: 3600_000, jeu: 'Rust' }] },
        serre: { chapitres: [{ pos: 60_000, jeu: 'Rust' }] },
      };
      window.__addCard('large', 'Rust', '900');
      window.__addCard('serre', 'Rust', '800');
    });
    await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 2, 12_000);
    await wait(page, 1500);

    const mesurer = async (login) => {
      await hoverLogin(page, login);
      await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 9000);
      await wait(page, 300);
      const r = await page.evaluate((l) => {
        const c = [...document.querySelectorAll('.side-nav-card')]
          .find((x) => x.dataset.tseLogin === l);
        return { carte: c?.querySelector('.tse-uptime')?.textContent || '',
                 frise: document.querySelector('.tse-preview__frise-total')?.textContent || '' };
      }, login);
      await page.evaluate((l) => {
        [...document.querySelectorAll('.side-nav-card')]
          .find((x) => x.dataset.tseLogin === l)
          ?.dispatchEvent(new MouseEvent('mouseleave', { bubbles: false }));
      }, login);
      await attendre(page,
        () => !document.querySelector('.tse-preview[data-tse-visible="true"]'), 4000);
      return r;
    };

    const large = await mesurer('large');
    const serre = await mesurer('serre');
    /* LE TÉMOIN D'ABORD : un écart franc passait déjà, et doit continuer. */
    ok('au-dessus de la tolérance, la carte et la frise s\'accordaient déjà',
       large.carte === large.frise && /^3h/.test(large.carte), JSON.stringify(large));
    /* L'ASSERTION QUI PORTE LE RAPPORT. Mutant — le filet non rendu au premier
       segment — « carte 3h01 » contre « frise 3h00 ». */
    ok('…et sous la tolérance elles s\'accordent aussi, ce qui n\'était pas le cas',
       serre.carte === serre.frise && /^3h01/.test(serre.carte), JSON.stringify(serre));
    await page.close();
  }

  /* ── 3. TOUTES LES CARTES, ET PAS SEULEMENT LES PREMIÈRES ─────────────────
     LE DÉFAUT QUE CE BLOC TIENT. Le lot choisissait ses sondes AVANT les
     gardes de la sonde, sur le seul critère « cette chaîne a un direct ».
     L'ordre du lot étant celui de la liste, donc stable, le budget retombait
     à chaque cycle sur LES MÊMES chaînes — déjà sondées, refusées en une
     ligne — et plus aucune origine n'était apprise après le premier relevé.

     IL FAUT PLUS DE CARTES QUE LE BUDGET D'UN LOT, sans quoi le défaut
     n'existe pas : c'est pourquoi le bloc 1, avec sa chaîne unique, passait
     déjà. Quatorze pour un budget de douze — le rapport de terrain en portait
     vingt-quatre, et c'est le même dépassement. Le décompte du budget se lit
     donc ici : ce bloc tombe si RECONNECT_PROBE_PER_BATCH atteint quatorze
     sans que la sélection soit corrigée, ce qui est exactement ce qu'on veut
     qu'il dise — la couverture ne doit pas dépendre du budget d'un lot. */
  {
    const page = await fresh();
    const N = 20;
    /* ── ON ATTEND QUE LE VOILE SOIT TOMBÉ, ET C'EST LE SUJET ─────────────
       Ce bloc mesure la cadence de CROISIÈRE. Sous le voile, la sonde dispose
       d'une bourse à part, dépensée d'un coup (cf. scénario 144) : y mesurer
       la croisière reviendrait à reprocher à la règle de ne pas s'appliquer là
       où elle ne s'applique pas. Le banc l'a pris tout seul — « pointe 20 »
       alors que la croisière en permet douze. */
    await attendre(page, () => !document.body.classList.contains('tse-loading'), 12_000);
    await page.evaluate((n) => {
      const neuf  = new Date(Date.now() - 60_000).toISOString();          // tronçon : 1 min
      const vieux = new Date(Date.now() - 5 * 3600_000).toISOString();    // archive : 5 h
      window.__fx = {};
      window.__vodRecent = {};
      for (let i = 0; i < n; i++) {
        const l = 'revenu' + i;
        window.__fx[l] = { id: 'r' + i, sid: 's-r' + i, createdAt: neuf,
                           viewers: 900 - i, game: 'VALORANT', tags: [] };
        // Même raccord que le bloc 1 : trou de 1,2 s entre l'archive d'avant
        // et le départ du tronçon courant (cf. scénario 102).
        window.__vodRecent[l] = [
          { createdAt: neuf, lengthSeconds: 60, chapitres: [] },
          { createdAt: vieux,
            lengthSeconds: Math.round((Date.parse(neuf) - 1_200 - Date.parse(vieux)) / 1000),
            chapitres: [{ pos: 0, jeu: 'Just Chatting' }] },
        ];
        window.__addCard(l, 'VALORANT', String(900 - i));
      }
    }, N);
    /* AUCUN SURVOL ICI NON PLUS, et plusieurs cycles de relevé pour laisser
       au défaut toutes ses chances : s'il suffisait d'attendre, il n'y aurait
       rien à corriger. */
    await attendre(page, () => {
      const cs = [...document.querySelectorAll('.side-nav-card')]
        .filter((x) => /^revenu\d+$/.test(x.dataset.tseLogin || ''));
      return cs.length >= 20
        && cs.every((c) => /^5h/.test(c.querySelector('.tse-uptime')?.textContent || ''));
    }, 15_000);
    const vu = await page.evaluate(() => {
      const cs = [...document.querySelectorAll('.side-nav-card')]
        .filter((x) => /^revenu\d+$/.test(x.dataset.tseLogin || ''));
      const r = window.tse.panneau.rapport().reseau.chapitres.reprise;
      /* LA FORME ET LA CADENCE DES REQUÊTES, et pas seulement leur résultat.
         Voir plus bas pourquoi l'une et l'autre sont tenues ici. */
      const envois = (window.__calls || [])
        .filter((a) => (a.names || []).includes('TseVodRecent'));
      const lots = envois.map((a) => a.names.filter((n) => n === 'TseVodRecent').length);
      /* ── ET ON ÉCARTE CE QUI EST PARTI SOUS LE VOILE ───────────────────
         Ce bloc attend la chute du voile avant de poser ses cartes, et cela
         suffisait… jusqu'au jour où un second cycle s'est intercalé sur un
         banc chargé : « pointe 16 » là où la croisière en permet douze, sans
         qu'aucune règle n'ait été enfreinte — la bourse du voile a la sienne.
         L'assertion épousait donc une hypothèse au lieu de mesurer un fait.
         Le harnais date désormais chaque appel de l'état du voile, et on ne
         garde que la croisière : ce qu'on prétend mesurer. */
      const croisiere = envois.filter((a) => !a.voile);
      /* LA POINTE : combien de sondes ont tenu dans la fenêtre la plus
         chargée. C'est exactement la grandeur que la règle borne, et elle ne
         se lit pas dans une liste — d'où l'horodatage posé par le harnais. */
      const ts = croisiere.map((a) => a.t).sort((x, y) => x - y);
      let pointe = 0;
      for (let i = 0; i < ts.length; i++) {
        const dans = ts.filter((t) => t >= ts[i] && t < ts[i] + 2000).length;
        if (dans > pointe) pointe = dans;
      }
      return { durees: cs.map((c) => c.querySelector('.tse-uptime')?.textContent || ''),
               survols: window.tse.panneau.rapport().frise.survols,
               sondes: r.sondes, adoptees: r.adoptees, differees: r.differees,
               plusGrosLot: lots.length ? Math.max(...lots) : 0, lots: lots.length,
               enCroisiere: croisiere.length, pointe };
    });
    /* L'ASSERTION QUI PORTE LE RAPPORT. Mutant — le budget pris avant les
       gardes — douze cartes sur vingt affichent « 5h00 », les huit autres
       restent à « 1m », indéfiniment. */
    ok('les vingt cartes portent la durée du direct entier, pas seulement les premières',
       vu.durees.length === 20 && vu.durees.every((d) => /^5h/.test(d)), JSON.stringify(vu));
    /* ET LE COMPTE LE DIT AUSSI : vingt sondes parties, vingt origines
       adoptées, zéro survol. Sans ce témoin, l'assertion ci-dessus passerait
       le jour où les durées viendraient d'ailleurs. */
    ok('…apprises par le lot, sans un seul survol',
       vu.survols === 0 && vu.sondes >= 20 && vu.adoptees >= 20,
       JSON.stringify({ ...vu, durees: undefined }));
    /* ── ET CHACUNE DANS SA PROPRE REQUÊTE ────────────────────────────────
       CE QUE LE DÉCOR NE PEUT PAS MONTRER, ET QU'IL FAUT DONC ÉCRIRE. Le
       harnais répond à tout, groupé ou non : les deux formes y passent au
       vert. Le terrain, lui, en refuse une, et deux rapports l'ont chiffré —
       une opération par requête, 8 sondes servies sur 8 ; douze par requête,
       5 sur 48, le reste en « service error ». Aucune origine apprise.

       CETTE ASSERTION NE MESURE DONC PAS UN COMPORTEMENT, ELLE TIENT UNE
       FORME. Elle existe pour qu'on ne regroupe pas une seconde fois, un jour
       où l'idée paraîtra de nouveau économique — et elle dira alors, au banc
       et non chez l'utilisateur, que la forme a changé. */
    ok('…et chaque sonde part dans sa propre requête, comme le terrain l\'exige',
       vu.lots >= 20 && vu.plusGrosLot === 1,
       JSON.stringify({ lots: vu.lots, plusGrosLot: vu.plusGrosLot }));
    /* ── ET SIX PAR FENÊTRE DE TEMPS, NON PAR LOT ─────────────────────────
       « SIX PAR LOT » VOULAIT DIRE « SIX PAR CYCLE », et ce n'est pas ce que
       ça disait. Un lot part dès qu'une carte réclame une chaîne inconnue du
       cache — donc bien plus souvent qu'un cycle, et sans répit en Top
       Chaînes. Le rapport de terrain l'a chiffré : une sonde toutes les deux
       secondes, et Twitch qui en refusait un tiers.

       CE QUE CETTE ASSERTION MESURE EST LA CADENCE, et rien d'autre : la
       fenêtre la plus chargée de tout le scénario. Elle a demandé un
       horodatage au harnais, parce qu'une cadence ne se lit pas dans une
       liste d'appels. Mutant — le budget repris par lot — « pointe 14 » là où
       la règle en permet six. */
    ok('…et la fenêtre de temps borne la cadence, que le lot soit gros ou non',
       vu.pointe <= 12 && vu.differees > 0 && vu.enCroisiere >= 12,
       JSON.stringify({ pointe: vu.pointe, differees: vu.differees,
                        enCroisiere: vu.enCroisiere }));
    await page.close();
  }

  /* ── 4. UNE MINUTE D'ÉCART ENTRE DEUX NOMBRES QUI SONT LE MÊME ────────────
     SIGNALÉ AINSI : « beaucoup de cartes ont environ une minute de décalage
     avec la partie Précédemment ». LA CAUSE TIENT EN UN VERBE : le total de
     la frise s'ARRONDISSAIT là où la carte TRONQUE, alors que les deux
     mesurent le même écart à maintenant. Un direct portait donc deux durées,
     à deux centimètres l'une de l'autre.

     LE RETARD D'AFFICHAGE, LUI, A ÉTÉ ÉCARTÉ PAR LA MESURE. Le compteur ne
     bat qu'à la minute, ce qui semblait un second coupable — mais chaque
     balayage réécrit la durée depuis le dataset (cf. applyChannelData), et
     REFRESH_TICK en programme un toutes les cinq secondes. La carte n'est
     donc jamais en retard de plus de cinq secondes sur elle-même, et on n'a
     rien changé de ce côté-là.

     LA PHASE EST CHOISIE, ET NON SUBIE. L'écart n'existe qu'au-delà de la
     demi-minute — en deçà, arrondi et troncature tombent sur le même nombre
     et le défaut se cache. Le décor pose donc le départ quarante secondes
     après une minute pleine : la mesure a lieu une ou deux secondes plus
     tard, et il reste dix-huit secondes de marge avant que la phase ne
     change de camp. */
  {
    const page = await fresh();
    await page.evaluate(() => {
      window.__fx = { phase: { id: 'p1', sid: 's-p1', viewers: 900, game: 'Rust', tags: [],
                               createdAt: new Date(Date.now() - 3 * 3600_000 - 40_000).toISOString() } };
      window.__vod = { phase: { chapitres: [{ pos: 0, jeu: 'Rust' }] } };
      window.__addCard('phase', 'Rust', '900');
    });
    await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
    await attendre(page, () => {
      const c = [...document.querySelectorAll('.side-nav-card')]
        .find((x) => x.dataset.tseLogin === 'phase');
      return /^3h00/.test(c?.querySelector('.tse-uptime')?.textContent || '');
    }, 9000);
    await hoverLogin(page, 'phase');
    await attendre(page, () => !!document.querySelector('.tse-preview__frise'), 9000);
    await wait(page, 300);
    const vu = await page.evaluate(() => {
      const c = [...document.querySelectorAll('.side-nav-card')]
        .find((x) => x.dataset.tseLogin === 'phase');
      /* LA LIGNE DE LÉGENDE DE LA CATÉGORIE EN COURS. Le décor n'en a qu'une,
         et elle couvre donc tout le direct : ce qu'elle annonce EST le total,
         et les deux se lisent l'un sous l'autre. */
      const encours = document.querySelector(
        '.tse-preview__frise-ligne--encours .tse-preview__frise-duree');
      return { carte: c?.querySelector('.tse-uptime')?.textContent || '',
               frise: document.querySelector('.tse-preview__frise-total')?.textContent || '',
               ligne: (encours?.textContent || '').split('·')[0].trim() };
    });
    /* L'ASSERTION QUI PORTE LE RAPPORT. Mutant — le total rendu par
       `formatDuree` — « carte 3h00 » contre « frise 3h01 ». */
    ok('passé la demi-minute, la frise ne prend pas une minute d\'avance sur la carte',
       vu.carte === vu.frise && /^3h00/.test(vu.carte), JSON.stringify(vu));
    /* ── ET LA LIGNE DU DESSOUS COMPTE COMME LES DEUX AUTRES ───────────────
       SECOND RAPPORT, sur la même capture : « le uptime sur la carte est
       pareil que celui à côté de Précédemment, cependant on peut voir une
       différence d'une minute sur le temps en dessous de la frise ». La 4.15.2
       n'avait corrigé que le TOTAL ; la ligne de la catégorie en cours, elle,
       arrondissait encore — et sur une frise à une seule catégorie, cette
       ligne est le total. Mutant — la ligne rendue par `formatDuree` —
       « frise 3h00 » contre « ligne 3h01 ». */
    ok('…et la ligne de la catégorie en cours non plus, elle qui EST ce total',
       vu.ligne === vu.frise && /^3h00/.test(vu.ligne), JSON.stringify(vu));
    await page.close();
  }
}

/* ═════════ LE COMBINÉ D'UN MEMBRE QU'ON N'INTERROGERA JAMAIS ══════════════
   RAPPORT DE TERRAIN : « des co-streams non visibles sur Top Chaînes », avec
   « sousLaCoupe 14 » — quatorze membres de session connus du classement mais
   retombés sous la coupe, donc triés sur leur audience PROPRE au lieu du
   combiné que Twitch affiche.

   CE QUI REND CE CAS PARTICULIER : on n'interroge Guest Star que sur des
   identifiants connus, et on ne connaît que ceux des chaînes ayant une carte.
   Un membre sous la coupe n'a pas de carte ; AUCUNE requête ne partira jamais
   pour lui. Sa seule source possible est la réponse obtenue pour un autre
   membre — qui porte bien son identifiant et son combiné, et dont on ne
   gardait que le login et le nom.

   LE DÉCOR REPREND CELUI DU SCÉNARIO 139, qui fait provablement partir la
   requête, et lui ajoute un troisième membre SANS entrée de chaîne et sans
   carte. Le répertoire ne lui donne que cent vingt spectateurs. */
{
  titre('143. Co-stream — le combiné d\'un membre qu\'on n\'interrogera jamais');

  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    const c = (id, v) => ({ id, createdAt: h, viewers: v, game: 'Valheim', tags: [] });
    window.__cats = [{ name: 'Valheim', viewers: 9000, streams: [
      { login: 'unaa', viewers: 4000 }, { login: 'unbb', viewers: 4000 },
      { login: 'sanscarte', viewers: 120 },
      { login: 'milieu', viewers: 900 }, { login: 'modele', viewers: 800 }] }];
    /* « sanscarte » n'a PAS d'entrée ici, et c'est tout le scénario. */
    window.__fx = { unaa: c('9401', 300), unbb: c('9402', 300),
                    milieu: c('9404', 950), modele: c('9405', 800) };
    const guests = [
      { id: '9401', login: 'unaa', viewers: 300, combined: 4000 },
      { id: '9402', login: 'unbb', viewers: 300, combined: 4000 },
      { id: '9403', login: 'sanscarte', viewers: 120, combined: 4000 }];
    window.__gs = {
      '9401': { hostId: '9400', hostLogin: 'unaa', guests },
      '9402': { hostId: '9400', hostLogin: 'unaa', guests } };
    window.__addCard('modele', 'Valheim', '800');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => window.tse.global.on());
  await attendre(page, () => [...document.querySelectorAll('.side-nav-card')]
    .some((c) => c.dataset.tseLogin === 'milieu' && c.dataset.tseViewers === '950'), 15_000);
  await attendre(page, () => window.tse.global.top(50)
    .some((r) => r.login === 'sanscarte' && r.viewers === 4000), 12_000);

  const vu = await page.evaluate(() => {
    const appels = (window.__calls || []).flatMap((a) => a.names || []);
    return { gs: appels.filter((n) => /GuestStar/.test(n)).length,
             membres: window.tse.global.top(50)
               .filter((x) => ['unaa', 'unbb', 'sanscarte'].includes(x.login))
               .map((x) => `${x.login}:${x.viewers}`) };
  });
  /* LA PRÉMISSE : sans requête Guest Star, tout le reste mesurerait un décor
     sans session et serait vert pour rien. */
  ok('la session a bien été résolue pour les membres qui ont une carte',
     vu.gs >= 1 && vu.membres.includes('unaa:4000') && vu.membres.includes('unbb:4000'),
     JSON.stringify(vu));
  /* L'ASSERTION QUI PORTE LE RAPPORT. Mutant — les combinés des autres membres
     jetés, comme avant — « sanscarte:120 » : l'audience propre, donc la sortie
     du classement, donc la carte qui n'apparaît jamais. */
  ok('…et le membre sans carte est classé sur le combiné, pas sur son audience propre',
     vu.membres.includes('sanscarte:4000'), JSON.stringify(vu));
  await page.close();
}

/* ═════════ TOUT DOIT ÊTRE PRÊT QUAND LE VOILE DISPARAÎT ══════════════════
   RAPPORT DE TERRAIN : « je t'assure qu'au tout début il m'annonçait une
   vingtaine d'heures sur ce compte ; maintenant il met bien les coupures. Je
   veux que cette data concernant les coupures soit prise en compte DURANT le
   voile, tout doit être prêt lorsque le voile disparaît. »

   CE QUE LE JOURNAL DATAIT : « cycle 484 ms · levée 10720 ms ». Dix secondes
   de voile, pendant lesquelles douze sondes par trente secondes en laissaient
   partir quatre. Les autres cartes apprenaient leur origine APRÈS la levée,
   d'où un compteur qui passe de vingt heures à soixante-huit sous les yeux.

   CE QUE CE SCÉNARIO MESURE, ET RIEN D'AUTRE : ce que les cartes affichaient
   À L'INSTANT où le voile est tombé. Pas avant, pas après. L'observateur vit
   dans la page et ne se déclenche qu'après avoir VU le voile posé — sans cette
   condition il capturerait la première mutation venue, voile absent, et serait
   vert pour rien. */
{
  titre('144. Le voile — les origines sont apprises avant qu\'il ne tombe');

  const page = await fresh();
  await page.evaluate(() => {
    const neuf  = new Date(Date.now() - 60_000).toISOString();
    const vieux = new Date(Date.now() - 5 * 3600_000).toISOString();
    /* Le même raccord qu'au scénario 102 : un trou de 1,2 s entre l'archive
       d'avant et le départ du tronçon courant. */
    const arch = () => [
      { createdAt: neuf, lengthSeconds: 60, chapitres: [] },
      { createdAt: vieux,
        lengthSeconds: Math.round((Date.parse(neuf) - 1_200 - Date.parse(vieux)) / 1000),
        chapitres: [{ pos: 0, jeu: 'Just Chatting' }] }];
    window.__fx = {}; window.__vodRecent = {};
    window.__cats = [{ name: 'Rust', viewers: 90_000, streams: [] }];
    /* QUARANTE CHAÎNES POUR TRENTE PLACES : il en faut plus que le budget
       ordinaire d'une fenêtre, sans quoi la cadence de croisière suffirait et
       le décor ne jouerait pas le cas. */
    for (let i = 0; i < 40; i++) {
      const l = 'rev' + i;
      window.__fx[l] = { id: 'i-' + l, sid: 's-' + l, createdAt: neuf,
                         viewers: 900 - i, game: 'Rust', tags: [] };
      window.__vodRecent[l] = arch();
      window.__cats[0].streams.push({ login: l, viewers: 900 - i });
    }
    window.__fx.modele = { id: 'i-modele', sid: 's-modele', createdAt: neuf,
                           viewers: 500, game: 'Rust', tags: [] };
    window.__addCard('modele', 'Rust', '500');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => {
    window.__aLaLevee = null;
    window.__voileVu = false;
    const mo = new MutationObserver(() => {
      if (document.body.classList.contains('tse-loading')) { window.__voileVu = true; return; }
      if (window.__voileVu && window.__aLaLevee === null) {
        window.__leveeInfo = window.tse.panneau.rapport().reseau.chapitres.reprise;
        window.__aLaLevee = [...document.querySelectorAll('.side-nav-card')]
          .filter((c) => /^rev\d+$/.test(c.dataset.tseLogin || ''))
          .map((c) => c.querySelector('.tse-uptime')?.textContent || '');
      }
    });
    mo.observe(document.body, { attributes: true, attributeFilter: ['class'] });
    document.querySelector('#tse-mode-row [data-tse-mode="global"]')?.click();
  });
  await attendre(page, () => window.__voileVu === true, 8000);
  await attendre(page, () => window.__aLaLevee !== null, 15_000);
  const vu = await page.evaluate(() => ({
    aLaLevee: window.__aLaLevee, voileVu: window.__voileVu,
    levee: window.__leveeInfo }));
  /* LA PRÉMISSE : sans voile observé, tout ce qui suit mesurerait une page
     ordinaire et serait vert sans rien dire. */
  ok('le voile a bien été posé, puis levé',
     vu.voileVu === true && Array.isArray(vu.aLaLevee) && vu.aLaLevee.length >= 20,
     JSON.stringify({ voileVu: vu.voileVu, n: (vu.aLaLevee || []).length }));
  /* L'ASSERTION QUI PORTE LE RAPPORT. Mutant — la bourse du voile ramenée à
     celle de la croisière — onze cartes sur trente portent « 5h00 » et
     dix-neuf « 1m », avec « enFile 19 » au moment même de la levée. */
  ok('…et aucune carte ne porte encore la durée de son tronçon à cet instant',
     (vu.aLaLevee || []).every((d) => /^5h/.test(d)),
     JSON.stringify({ levee: vu.levee, vues: (vu.aLaLevee || []).slice(0, 8) }));
  /* ET LE COMPTE LE DIT AUSSI : les origines ont été adoptées SOUS le voile,
     ce qui est la seule chose qui distingue « prêt à la levée » de « corrigé
     juste après ». Sans ce témoin, une levée tardive suffirait à passer. */
  ok('…parce qu\'elles ont été apprises sous le voile, et non corrigées après',
     vu.levee && vu.levee.sousVoile >= 20 && vu.levee.enFile === 0,
     JSON.stringify(vu.levee));
  await page.close();
}

/* ═════════ UN REFUS DE TWITCH NE DOIT PAS COÛTER UNE MINUTE ══════════════
   RAPPORT DE TERRAIN, EN DEUX PHRASES : « le changement arrive au bout d'une
   minute ou 2 », et le rapport qui l'accompagne porte « reseau 11 » sur
   trente-sept sondes — près d'un tiers refusé par Twitch — avec « sousVoile 1 »
   sur deux adoptions.

   LA MINUTE EST DANS UNE CONSTANTE : RECONNECT_PROBE_RETRY. Elle a sa raison
   d'être en croisière — réessayer tout de suite ajoute sa requête à celles qui
   viennent d'être refusées, et nourrit la cause. Sous le voile, ce
   raisonnement tombe : personne ne navigue, la dépense est bornée par le voile
   lui-même, et une origine apprise une minute plus tard est exactement ce que
   l'utilisateur voit se corriger sous ses yeux.

   ET UN REFUS N'ÉTAIT NULLE PART. La sonde n'était plus en vol, et la chaîne
   n'était pas en file : le verrou de voile ne la comptait donc pas. En la
   remettant en file, on répare les deux choses d'un coup — le vidage la
   reprend, et le voile sait qu'il l'attend.

   LE DÉCOR REFUSE LES TROIS PREMIÈRES SONDES, ce qui est le « reseau 11 » du
   terrain en miniature : une réponse 200 porteuse d'erreurs GraphQL, la forme
   exacte que Twitch rend. */
{
  titre('145. Un refus de Twitch ne coûte pas une minute sous le voile');

  const page = await fresh();
  await page.evaluate(() => {
    const neuf  = new Date(Date.now() - 60_000).toISOString();
    const vieux = new Date(Date.now() - 5 * 3600_000).toISOString();
    window.__fx = {}; window.__vodRecent = {};
    for (let i = 0; i < 8; i++) {
      const l = 'rev' + i;
      window.__fx[l] = { id: 'i-' + l, sid: 's-' + l, createdAt: neuf,
                         viewers: 900 - i, game: 'Rust', tags: [] };
      window.__vodRecent[l] = [
        { createdAt: neuf, lengthSeconds: 60, chapitres: [] },
        { createdAt: vieux,
          lengthSeconds: Math.round((Date.parse(neuf) - 1_200 - Date.parse(vieux)) / 1000),
          chapitres: [{ pos: 0, jeu: 'Just Chatting' }] }];
      window.__addCard(l, 'Rust', String(900 - i));
    }
    window.__refusSondes = 3;
    const vrai = window.fetch;
    window.fetch = async (url, opt) => {
      const body = JSON.parse(opt.body);
      if (body.some((o) => o.operationName === 'TseVodRecent') && window.__refusSondes > 0) {
        window.__refusSondes--;
        return { ok: true, json: async () => [{ errors: [{ message: 'service error' }] }] };
      }
      return vrai(url, opt);
    };
  });
  await attendre(page, () => {
    const cs = [...document.querySelectorAll('.side-nav-card')]
      .filter((c) => /^rev\d+$/.test(c.dataset.tseLogin || ''));
    return cs.length >= 8
      && cs.every((c) => /^5h/.test(c.querySelector('.tse-uptime')?.textContent || ''));
  }, 20_000);
  const vu = await page.evaluate(() => {
    const b = window.tse.panneau.rapport().reseau.chapitres.reprise;
    return { reseau: b.reseau, adoptees: b.adoptees, sousVoile: b.sousVoile };
  });
  /* LA PRÉMISSE : le décor a bien joué des refus. Sans eux, tout ce qui suit
     mesurerait un chemin nominal et serait vert pour rien. */
  ok('le décor a bien essuyé des refus de Twitch',
     vu.reseau >= 3 && vu.adoptees >= 8, JSON.stringify(vu));
  /* L'ASSERTION QUI PORTE LE RAPPORT. Mutant — la minute de report appliquée
     aussi sous le voile — « sousVoile 5 » sur huit adoptions : les trois
     chaînes refusées apprennent leur origine APRÈS la levée, ce qui est
     exactement « le changement arrive au bout d'une minute ou 2 ». */
  ok('…et toutes les origines sont apprises sous le voile malgré eux',
     vu.sousVoile === vu.adoptees, JSON.stringify(vu));
  await page.close();
}

/* ═════════ LE VOILE, SA BORNE ET SA CADENCE ══════════════════════════════
   RAPPORT DE TERRAIN, TROIS LIGNES DU JOURNAL DU VOILE :
       64876 ms  cycle  entrée dans Top Chaînes
       79904 ms  levée  DÉLAI MAXIMAL          ← quinze secondes tout rond
      121567 ms  cycle  changement de langue
      136593 ms  levée  DÉLAI MAXIMAL          ← quinze secondes tout rond
   Deux cycles sur trois levés par le plafond dur, et les quarante-quatre
   refus de Twitch du même rapport tombent exactement dans ces deux fenêtres.

   UNE SEULE CAUSE POUR LES DEUX. `majVerrouVoile` rendait la main à
   l'échéance ET remettait son échéance à zéro ; l'appel suivant, voyant du
   travail encore en cours, s'en accordait une NEUVE. La borne annoncée « et
   pas une seconde de plus » était une fenêtre glissante, reconduite tant
   qu'une sonde restait à faire. Et ces quinze secondes coûtent DEUX FOIS,
   parce que tout ce qui se règle sur `enCycle()` reste en régime de voile
   pendant ce temps — dont le report d'un refus, à 400 ms.

   POURQUOI LE BANC NE L'A PAS VU : sa borne valait cinq secondes pour un
   voile qui meurt à 1,2 s. Le plafond dur tombait toujours le premier, donc
   la borne n'était la contrainte de RIEN et ne pouvait pas manquer. Elle vaut
   maintenant 300 ms ici — un quart du plafond — et c'est ce rapport-là qui
   rend l'écart lisible.

   ON MESURE LA DURÉE DU VERROU, et non le motif de la levée : le motif
   dépend du plafond dur, donc d'une seconde constante, là que la durée se
   compare directement au nombre que le code annonce. Mutant — la borne
   reposée — verrou tenu 1029 ms pour 300 annoncées. */
{
  titre('146. Le voile — la borne du verrou, et la cadence des sondes');

  /* ── a) LA BORNE SE CONSOMME UNE FOIS, MÊME SI LE TRAVAIL NE FINIT PAS ──
     Twitch refuse TOUT : il reste donc en permanence des chaînes à sonder, ce
     qui est exactement la condition qui reconduisait la borne. */
  {
    const page = await fresh();
    await page.evaluate(() => {
      const neuf  = new Date(Date.now() - 60_000).toISOString();
      const vieux = new Date(Date.now() - 5 * 3600_000).toISOString();
      window.__fx = {}; window.__vodRecent = {};
      for (let i = 0; i < 30; i++) {
        const l = 'rev' + i;
        window.__fx[l] = { id: 'i-' + l, sid: 's-' + l, createdAt: neuf,
                           viewers: 900 - i, game: 'Rust', tags: [] };
        window.__vodRecent[l] = [
          { createdAt: neuf, lengthSeconds: 60, chapitres: [] },
          { createdAt: vieux,
            lengthSeconds: Math.round((Date.parse(neuf) - 1_200 - Date.parse(vieux)) / 1000),
            chapitres: [{ pos: 0, jeu: 'Just Chatting' }] }];
        window.__addCard(l, 'Rust', String(900 - i));
      }
      window.__refus = 0;
      const vrai = window.fetch;
      window.fetch = async (url, opt) => {
        const body = JSON.parse(opt.body);
        if (body.some((o) => o.operationName === 'TseVodRecent')) {
          window.__refus++;
          return { ok: true, json: async () => [{ errors: [{ message: 'service error' }] }] };
        }
        return vrai(url, opt);
      };
      /* LE VERROU SE CONSTATE, IL NE SE DÉDUIT PAS de l'instant où le voile se
         lève : celui-ci dépend aussi de la stabilité de la sidebar et du
         plafond dur, donc mesurerait trois choses à la fois. On échantillonne
         `verrous()`, qui dit ce qui est POSÉ, et on garde l'étendue du verrou
         « origines » à l'intérieur d'un cycle. */
      window.__spans = [];
      let debut = null, dernier = null, enCycle = false;
      setInterval(() => {
        const voile = document.body.classList.contains('tse-loading');
        if (voile) enCycle = true;
        if ((window.tse?.verrous?.() || []).includes('origines')) {
          if (debut === null) debut = performance.now();
          dernier = performance.now();
        }
        if (!voile && enCycle) {
          if (debut !== null) window.__spans.push(Math.round(dernier - debut));
          debut = null; dernier = null; enCycle = false;
        }
      }, 10);
    });
    await attendre(page, () => (window.__spans || []).length >= 1, 8000);
    const vu = await page.evaluate(() => {
      const r = window.tse.panneau.rapport().reseau;
      return { spans: window.__spans, refus: window.__refus,
               rapporte: r.refus, echecs: r.echecs,
               enFile: r.chapitres.reprise.enFile };
    });
    /* LA PRÉMISSE, EN DEUX MOITIÉS. Sans refus, le travail finirait et la
       borne n'aurait rien à borner ; sans verrou posé, l'étendue mesurée
       serait zéro et l'assertion qui suit passerait sans rien voir. */
    ok('le décor tient le travail ouvert, et le verrou a bien été posé',
       vu.refus >= 3 && (vu.spans || []).length >= 1 && vu.spans[0] > 0,
       JSON.stringify(vu));
    /* L'ASSERTION QUI PORTE LE RAPPORT. La borne vaut 300 ms au banc ; on
       laisse le double, ce qui couvre le réveil de secours (+50 ms) et le pas
       d'échantillonnage sans jamais approcher les 1029 ms du mutant. */
    ok('…et il n\'a pas tenu plus que la borne qu\'il s\'annonce',
       vu.spans[0] <= 600, JSON.stringify(vu));
    /* ET LE RAPPORT LE DIT. Le dernier rapport de terrain portait « echecs 0 »
       au-dessus de quarante-quatre refus consignés deux sections plus bas :
       qui le lisait concluait que le transport allait bien. Un refus se compte
       désormais, à part de l'échec de transport — les deux n'appellent pas la
       même conclusion, et c'est pour ça qu'ils font deux nombres. */
    ok('…et le rapport nomme ces refus au lieu d\'annoncer un réseau parfait',
       vu.rapporte >= 3 && vu.echecs === 0, JSON.stringify(vu));
    await page.close();
  }

  /* ── b) LA BOURSE SE DÉPENSE À UNE CADENCE, PAS EN UNE MILLISECONDE ─────
     Quarante chaînes pour une bourse de quarante : la couverture attendue est
     TOTALE, et c'est ce qui rend l'assertion de cadence honnête — elle ne
     peut pas être obtenue en sondant moins. */
  {
    const page = await fresh();
    await page.evaluate(() => {
      const neuf  = new Date(Date.now() - 60_000).toISOString();
      const vieux = new Date(Date.now() - 5 * 3600_000).toISOString();
      window.__fx = {}; window.__vodRecent = {};
      for (let i = 0; i < 40; i++) {
        const l = 'rev' + i;
        window.__fx[l] = { id: 'i-' + l, sid: 's-' + l, createdAt: neuf,
                           viewers: 900 - i, game: 'Rust', tags: [] };
        window.__vodRecent[l] = [
          { createdAt: neuf, lengthSeconds: 60, chapitres: [] },
          { createdAt: vieux,
            lengthSeconds: Math.round((Date.parse(neuf) - 1_200 - Date.parse(vieux)) / 1000),
            chapitres: [{ pos: 0, jeu: 'Just Chatting' }] }];
        window.__addCard(l, 'Rust', String(900 - i));
      }
      window.__sondes = [];
      const vrai = window.fetch;
      window.fetch = async (url, opt) => {
        if (JSON.parse(opt.body).some((o) => o.operationName === 'TseVodRecent')) {
          window.__sondes.push(performance.now());
        }
        return vrai(url, opt);
      };
    });
    await attendre(page, () =>
      window.tse.panneau.rapport().reseau.chapitres.reprise.adoptees >= 40, 8000);
    const vu = await page.evaluate(() => {
      const s = window.__sondes;
      /* LA POINTE SE MESURE SUR LA FENÊTRE QUE LA CADENCE BORNE — 50 ms ici —
         et pas sur une seconde ronde : une fenêtre choisie au hasard ne
         dirait rien du nombre que le code tient. */
      let pointe = 0;
      for (let i = 0; i < s.length; i++) {
        let n = 0;
        for (let j = i; j < s.length && s[j] - s[i] < 50; j++) n++;
        if (n > pointe) pointe = n;
      }
      const b = window.tse.panneau.rapport().reseau.chapitres.reprise;
      return { n: s.length, pointe,
               etendueMs: s.length ? Math.round(s[s.length - 1] - s[0]) : 0,
               sousVoile: b.sousVoile, adoptees: b.adoptees };
    });
    /* LA PRÉMISSE : la couverture est entière et sous le voile. Une cadence
       basse obtenue en sondant moins ne vaudrait rien. */
    ok('les quarante origines sont apprises, et sous le voile',
       vu.adoptees >= 40 && vu.sousVoile >= 40, JSON.stringify(vu));
    /* L'ASSERTION QUI PORTE LE RAPPORT. Mutant — la bourse rendue d'un bloc,
       comme avant — « pointe 40, etendueMs 1 » : quarante requêtes simultanées
       sur un point d'entrée anonyme, la forme même qu'un limiteur punit, et
       les 40,7 % de refus que le terrain a mesurés. */
    ok('…sans que plus de huit sondes ne partent dans la même fenêtre',
       vu.pointe <= 8 && vu.etendueMs >= 150, JSON.stringify(vu));
    await page.close();
  }
}

/* ═════════ L'ONGLET LE PLUS LOURD NE SE LIT PAS DEUX FOIS ════════════════
   RAPPORT DE TERRAIN, DEUX LIGNES JUMELLES dans le relevé des abonnements :
       onglet expired  affiché · 5331 nœuds · barre oui · 74 carte(s)
       onglet expired  affiché · 5309 nœuds · barre oui · 74 carte(s)
   Le même onglet, la même moisson, deux chargements de page complets.

   LA CAUSE TIENT DANS L'ORDRE DE DEUX LIGNES. Le relevé lit les expirés SEULS
   et EN PREMIER quand il ne connaît pas encore l'étiquette de l'ancienneté —
   c'est sur leurs cartes, les plus simples, qu'elle s'apprend. Puis la ligne
   suivante décidait de relire les expirés « si l'étiquette est connue »… ce
   que la passe précédente venait justement de rendre vrai. Toujours vraie,
   donc, et l'onglet le plus lourd du relevé repartait pour un tour.

   IL N'Y AVAIT RIEN À ALLER RECHERCHER : `mois(carte, true)` apprend
   l'étiquette ET rend l'ancienneté dans le même passage, donc la première
   lecture est complète — les deux lignes du rapport rendent bien les mêmes
   soixante-quatorze chaînes. Ce qui manquait, c'est qu'on RETIENNE ce qui a
   été lu, au lieu de relire un état qui a changé entre-temps.

   LE COÛT N'EST PAS THÉORIQUE : ce relevé tient le voile (verrou « subs »),
   et cet onglet-là est le plus gros de tous. */
{
  titre('147. Le relevé — l\'onglet des expirés ne se lit qu\'une fois');

  const page = await freshTwitch('<!doctype html><html><body>x</body></html>', [], '/', () => {
    /* LES CADRES SE COMPTENT À LA SOURCE. Ils sont posés dans le document
       parent, et leur `src` porte l'onglet : un observateur les voit tous,
       y compris ceux qui sont retirés aussitôt après. */
    if (window.top !== window) return;   // le relevé pose ses cadres au sommet
    window.__cadres = [];
    const mo = new MutationObserver((muts) => {
      for (const m of muts) for (const n of m.addedNodes) {
        if (n.tagName === 'IFRAME' && /\/subscriptions\?/.test(n.src || '')) {
          window.__cadres.push(decodeURIComponent(n.src.split('tab=')[1] || ''));
        }
      }
    });
    // documentElement n'existe pas encore à document_start : on réessaie,
    // plutôt que de jeter et de faire échouer la page entière.
    const armer = () => {
      if (!document.documentElement) { setTimeout(armer, 0); return; }
      mo.observe(document.documentElement, { childList: true, subtree: true });
    };
    armer();
  });
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    window.__fx = { omofficial: { id: '1', createdAt: h, viewers: 500, game: 'G', tags: [] } };
    window.__addCard('omofficial', 'G', '500');
  });
  /* On attend le relevé À SON TERME — son horodatage — et non une durée : les
     quatre onglets sont quatre pages, et leur durée dépend de la machine. */
  await attendre(page, () => !!localStorage.getItem('tse:substs'), 15_000);
  await wait(page, 500);     // laisse un éventuel cadre de trop se poser
  const vu = await page.evaluate(() => ({
    cadres: window.__cadres,
    expired: window.__cadres.filter(t => t === 'expired').length,
    subs: (window.tse.subs() || []).length }));
  /* LA PRÉMISSE : le relevé est bien allé chercher ses onglets, expirés
     compris. Sans cela, « zéro expired » passerait pour une réussite. */
  ok('le relevé a bien visité ses onglets, expirés compris',
     vu.expired >= 1 && vu.cadres.length >= 4, JSON.stringify(vu));
  /* L'ASSERTION QUI PORTE LE RAPPORT. Mutant — la relecture conditionnée à
     l'étiquette, que la passe d'avant vient d'apprendre — deux « expired »,
     soit un chargement de page complet pour rien, sous le voile. */
  ok('…et il n\'a chargé l\'onglet le plus lourd qu\'une seule fois',
     vu.expired === 1, JSON.stringify(vu));
  await page.close();
}

/* ═════════ LA SONDE NE SE DÉPENSE PAS SUR UN SUBATHON ════════════════════
   DEUX RAPPORTS DE TERRAIN DE SUITE, LE MÊME ÉCART D'UNE UNITÉ :
       trouvees 5 · adoptees 4 · subathons.detectes 1
       trouvees 4 · adoptees 3 · subathons.detectes 1
   Une chaîne dont la sonde trouvait bien son chaînage, et dont l'adoption le
   jetait ensuite.

   `adopterReprise` REFUSE LES SUBATHONS, et il a raison : un direct qui ne
   s'arrête pas n'a pas de « reprise après coupure », ses interruptions ne
   veulent pas dire la même chose. Mais il refusait APRÈS la requête, quand
   elle était déjà partie et déjà payée.

   ET LE COMMENTAIRE DU LOT ANNONÇAIT LA GARDE : « une chaîne dont il n'y a
   rien à apprendre — déjà sondée, déjà chaînée, SUBATHON ». Elle n'était
   écrite nulle part dans le code. Même classe de défaut que la borne du
   verrou du scénario 146 : une phrase qui décrit un comportement que le
   programme n'a pas.

   CE QUE ÇA COÛTAIT : une requête sur le point d'entrée qu'on rationne — le
   même dont on vient de ramener le refus de 40,7 % à 21 % — une place de la
   bourse du voile, et le voile retenu pour une réponse qu'on allait jeter.

   ET LE RAPPORT Y GAGNE UN TÉMOIN : `trouvees` et `adoptees` s'accordent
   désormais, si bien qu'un écart entre eux veut enfin dire quelque chose. */
{
  titre('148. La sonde d\'origine — rien à apprendre d\'un subathon');

  const page = await fresh();
  await page.evaluate(() => {
    const neuf  = new Date(Date.now() - 60_000).toISOString();
    const vieux = new Date(Date.now() - 5 * 3600_000).toISOString();
    window.__fx = {}; window.__vodRecent = {};
    /* TROIS CHAÎNES ORDINAIRES ET UNE EN SUBATHON, toutes avec le MÊME
       chaînage : c'est ce qui rend la mesure concluante — la seule chose qui
       distingue la quatrième est son titre. */
    for (const l of ['rev0', 'rev1', 'rev2', 'thonneur']) {
      window.__fx[l] = { id: 'i-' + l, sid: 's-' + l, createdAt: neuf,
                         viewers: 900, game: 'Rust', tags: [],
                         title: l === 'thonneur' ? 'SUBATHON DAY 12 | !socials' : 'Stream' };
      window.__vodRecent[l] = [
        { createdAt: neuf, lengthSeconds: 60, chapitres: [] },
        { createdAt: vieux,
          lengthSeconds: Math.round((Date.parse(neuf) - 1_200 - Date.parse(vieux)) / 1000),
          chapitres: [{ pos: 0, jeu: 'Just Chatting' }] }];
      window.__addCard(l, 'Rust', '900');
    }
    window.__sondes = [];
    const vrai = window.fetch;
    window.fetch = async (url, opt) => {
      for (const o of JSON.parse(opt.body)) {
        if (o.operationName === 'TseVodRecent') window.__sondes.push(o.variables.login);
      }
      return vrai(url, opt);
    };
  });
  await attendre(page, () =>
    window.tse.panneau.rapport().reseau.chapitres.reprise.adoptees >= 3, 10_000);
  await wait(page, 400);      // laisse une sonde de trop le temps de partir
  const vu = await page.evaluate(() => {
    const r = window.tse.panneau.rapport();
    return { sondes: window.__sondes,
             surLeThon: window.__sondes.filter(l => l === 'thonneur').length,
             subathons: r.subathons?.detectes,
             trouvees: r.reseau.chapitres.reprise.trouvees,
             adoptees: r.reseau.chapitres.reprise.adoptees };
  });
  /* LA PRÉMISSE, EN DEUX MOITIÉS. Le subathon doit être RECONNU — sans quoi
     on mesurerait une chaîne ordinaire — et les trois autres doivent être
     sondées, sans quoi « zéro sonde sur le thon » serait vrai pour la
     mauvaise raison. */
  ok('le subathon est reconnu, et les chaînes ordinaires sont bien sondées',
     vu.subathons === 1 && vu.sondes.length >= 3
     && ['rev0', 'rev1', 'rev2'].every(l => vu.sondes.includes(l)),
     JSON.stringify(vu));
  /* L'ASSERTION QUI PORTE LE RAPPORT. Mutant — la garde retirée —
     « surLeThon 1 », et « trouvees 4 · adoptees 3 » : l'écart d'une unité des
     deux rapports de terrain, reproduit à l'identique. */
  ok('…mais pas une seule sonde n\'est partie sur le subathon',
     vu.surLeThon === 0 && vu.trouvees === vu.adoptees, JSON.stringify(vu));
  await page.close();
}

/* ═════════ LA SIGNATURE DU COMBINÉ N'A PAS DE FRONTIÈRE ══════════════════
   LE SIGNALEMENT REVIENT POUR LA TROISIÈME FOIS, et cette fois avec le détail
   qui manquait : « il est réapparu et revenu à la normale quelques secondes
   après ». Disparue puis revenue — donc pas évincée, pas éteinte : RÉTROGRADÉE,
   le temps qu'une marche la restaure.

   LE RAPPORT LE DÉSIGNAIT AVEC LE COMPTEUR ÉCRIT POUR ÇA :
       sousLaCoupe 3 · sousLaCoupeAvecCombine 3
       chutes 131 · chuteMax 14326 · chutesHorsEcran 16
   Trois membres dont on CONNAÎT le combiné, et qui sont quand même sous la
   coupe — « c'est le défaut, en un seul nombre », dit le commentaire qui l'a
   posé. Et seize cartes sorties de l'écran par une chute de compteur.

   LA GARDE EXISTE POURTANT : un compteur PROPRE n'a pas le droit d'écraser une
   entrée qui porte la signature d'un combiné. Elle reconnaissait cette
   signature à l'ÉGALITÉ DU NOMBRE AFFICHÉ — et c'est là qu'elle cède, parce
   qu'un nombre affiché a des frontières. Les deux valeurs que le code cite
   lui-même en exemple le montrent :

       11 736 → « 11,7 k »        11 821 → « 11,8 k »

   Deux membres d'une même session, deux signatures, aucun jumeau, aucune
   protection. La capture du terrain montre le même groupe coupé en deux :
   « 17 k · 17 k · 16,9 k · 16,9 k ».

   LE BANC NE POUVAIT PAS LE VOIR : le scénario 133 pose 4900 et 4900, des
   compteurs STRICTEMENT identiques, c'est-à-dire le seul cas que la garde
   savait traiter. Celui-ci joue les nombres du terrain. */
{
  titre('149. Co-stream — la signature tient malgré l\'échantillonnage de Twitch');

  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    const c = (id, v) => ({ id, createdAt: h, viewers: v, game: 'Aniimo', tags: [] });
    /* LES DEUX NOMBRES DU TERRAIN, ET PAS DEUX NOMBRES ÉGAUX. Twitch
       échantillonne le combiné une fois par participant ; l'écart est de 0,7 %
       et il suffit à les mettre de part et d'autre d'un arrondi. */
    window.__cats = [{ name: 'Aniimo', viewers: 30_000, streams: [
      { login: 'naguura', viewers: 11_736 }, { login: 'lyritvjamie', viewers: 11_821 },
      { login: 'milieu', viewers: 900 }, { login: 'modele', viewers: 800 }] }];
    window.__fx = { naguura: c('9301', 300), lyritvjamie: c('9302', 300),
                    milieu: c('9303', 950), modele: c('9304', 800) };
    window.__gs = {};   // Guest Star se tait : `session: null`, comme le terrain
    window.__addCard('modele', 'Aniimo', '800');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => window.tse.global.on());
  /* On attend la FRAÎCHEUR de « milieu » : elle prouve que le lot de chaînes
     est passé, donc que les compteurs propres ont bien été proposés au
     classement. Sans elle, on mesurerait un classement que rien n'a attaqué. */
  await attendre(page, () => [...document.querySelectorAll('.side-nav-card')]
    .some((c) => c.dataset.tseLogin === 'milieu' && c.dataset.tseViewers === '950'), 15_000);
  const vu = await page.evaluate(() => {
    const aff = (l) => [...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === l)?.dataset.tseViewers ?? 'ABSENTE';
    const g = window.tse.panneau.rapport().global;
    return { naguura: aff('naguura'), lyritvjamie: aff('lyritvjamie'),
             milieu: aff('milieu'), chutes: g.chutes, chuteMax: g.chuteMax };
  });
  /* LA PRÉMISSE, ET ELLE EST LA MOITIÉ DU SCÉNARIO : la fraîcheur ordinaire
     ne doit PAS être sacrifiée à la garde. « milieu » n'a pas de jumeau, son
     compteur frais doit s'appliquer — c'est ce que le scénario 34 garantit et
     qu'une tolérance trop large casserait en silence. */
  ok('une chaîne sans jumeau garde son compteur frais',
     vu.milieu === '950', JSON.stringify(vu));
  /* L'ASSERTION QUI PORTE LE RAPPORT. Mutant — la signature comparée sur le
     nombre affiché — les deux tombent à « 300 », leur audience propre, avec
     « chuteMax 11521 ». C'est la disparition que l'utilisateur voit, et la
     marche suivante les restaure : « revenu à la normale quelques secondes
     après ». */
  ok('…et les deux membres d\'une même session gardent leur combiné',
     vu.naguura === '11736' && vu.lyritvjamie === '11821' && vu.chutes === 0,
     JSON.stringify(vu));
  await page.close();
}

/* ═════════ LES DEUX BADGES NE DISENT PAS LA MÊME CHOSE ═══════════════════
   SIGNALÉ COMME UN DOUBLON, CAPTURE À L'APPUI : le badge bleu disait
   « Co-stream avec LittleBigWhale » et le violet « En live avec
   LittleBigWhale », l'un sous l'autre, pour la même personne.

   ILS RÉPONDENT POURTANT À DEUX QUESTIONS DIFFÉRENTES, et c'est ce qui les
   départage. Le bleu dit AVEC QUI DE CETTE LISTE la chaîne diffuse — il parle
   de ce que l'utilisateur a sous les yeux. Le violet dit qui d'AUTRE est dans
   la session sans y figurer — il parle de ce que la liste ne peut pas montrer.

   D'OÙ LA RÈGLE, telle que l'utilisateur l'a posée : en « Top Chaînes », où le
   groupe est affiché au complet, le violet n'a plus rien à dire et disparaît ;
   en « Chaînes suivies », les membres suivis vont au bleu et les autres au
   violet. Les deux listes se partagent la MÊME source — les membres que Guest
   Star rend — pour qu'aucun nom ne tombe entre les deux. */
{
  titre('150. Aperçu — le bleu nomme ce qu\'on voit, le violet ce qu\'on ne voit pas');

  /* Trois membres d'une même session ; seul le nombre de CARTES change d'un
     cas à l'autre. C'est ce qui rend la mesure concluante : rien d'autre ne
     bouge. */
  const jouer = async (cartes) => {
    const page = await fresh();
    await page.evaluate((cartes) => {
      const h = new Date(Date.now() - 60 * 60_000).toISOString();
      const c = (id, v) => ({ id, createdAt: h, viewers: v, game: 'Rust', tags: [] });
      const guests = [
        { id: '1', login: 'alpha', viewers: 300, combined: 9000 },
        { id: '2', login: 'beta',  viewers: 300, combined: 9000 },
        { id: '3', login: 'gamma', viewers: 300, combined: 9000 }];
      window.__gs = { 1: { hostId: '1', hostLogin: 'alpha', guests },
                      2: { hostId: '1', hostLogin: 'alpha', guests },
                      3: { hostId: '1', hostLogin: 'alpha', guests } };
      window.__fx = { alpha: c('1', 9000), beta: c('2', 9000), gamma: c('3', 9000) };
      for (const l of cartes) window.__addCard(l, 'Rust', '9 k');
    }, cartes);
    await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 10_000);
    await wait(page, 1200);
    await page.evaluate(() => [...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === 'alpha')
      ?.dispatchEvent(new MouseEvent('mouseenter', { bubbles: false })));
    await attendre(page, () => !!document.querySelector('.tse-preview__badge--costream, .tse-preview__badge--squad'), 6000);
    await wait(page, 400);
    const vu = await page.evaluate(() => {
      const t = (s) => document.querySelector(s)?.textContent?.trim() || null;
      return { bleu: t('.tse-preview__badge--costream'),
               violet: t('.tse-preview__badge--squad') };
    });
    await page.close();
    return vu;
  };

  const tous  = await jouer(['alpha', 'beta', 'gamma']);
  const deux  = await jouer(['alpha', 'beta']);

  /* ── ET « DANS LA BARRE » N'EST PAS « QUELQUE PART DANS LA BARRE » ──────
     SIGNALÉ, AVEC L'HYPOTHÈSE JUSTE : « je vois que LittleBigWhale est en
     co-stream avec JulietteArz, mais je ne suis pas JulietteArz — peut-être
     parce qu'elle est présente plus bas dans "Chaînes live" ? »

     C'était exactement ça. La barre latérale de Twitch ne contient pas que la
     liste suivie : elle porte aussi « Chaînes live » et « Catégories
     recommandées », dont les cartes ont la MÊME classe. Un co-streamer qui y
     figurait passait pour visible dans la liste, et son nom partait au badge
     bleu — celui qui dit « de cette liste ». */
  const ailleurs = await (async (survole) => {
    const page = await fresh();
    await page.evaluate(() => {
      const h = new Date(Date.now() - 60 * 60_000).toISOString();
      const c = (id, v) => ({ id, createdAt: h, viewers: v, game: 'Rust', tags: [] });
      const guests = [
        { id: '1', login: 'lbw', viewers: 2100, combined: 2100 },
        { id: '2', login: 'juliettearz', viewers: 2000, combined: 2100 }];
      window.__gs = { 1: { hostId: '1', hostLogin: 'lbw', guests },
                      2: { hostId: '1', hostLogin: 'lbw', guests } };
      window.__fx = { lbw: c('1', 2100), juliettearz: c('2', 2100) };
      window.__addCard('lbw', 'Rust', '2,1 k');          // dans la liste suivie
      window.__addReco('juliettearz', 'Rust', '2 k');    // dans « Chaînes live »
    });
    await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 10_000);
    await wait(page, 1200);
    await page.evaluate((l) => [...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === l)
      ?.dispatchEvent(new MouseEvent('mouseenter', { bubbles: false })), survole);
    await attendre(page, () => !!document.querySelector('.tse-preview__badge--costream, .tse-preview__badge--squad'), 6000);
    await wait(page, 400);
    const vu = await page.evaluate(() => {
      const t = (s) => document.querySelector(s)?.textContent?.trim() || null;
      return { bleu: t('.tse-preview__badge--costream'),
               violet: t('.tse-preview__badge--squad'),
               recoVue: !!document.querySelector('#reco .side-nav-card') };
    });
    await page.close();
    return vu;
  });
  const depuisSuivies = await ailleurs('lbw');
  const depuisLive    = await ailleurs('juliettearz');

  /* LA PRÉMISSE : le bleu nomme bien ce qui est à l'écran. Sans elle,
     « le violet a disparu » serait vrai d'un aperçu vide. */
  ok('le bleu nomme les membres que la barre affiche',
     /beta/.test(tous.bleu || '') && /gamma/.test(tous.bleu || ''),
     JSON.stringify(tous));
  /* L'ASSERTION QUI PORTE LA DEMANDE. Mutant — le violet listant tous les
     membres, comme avant — « Co-stream avec beta, gamma » ET « En live avec
     beta, gamma » : les deux mêmes noms, l'un sous l'autre, exactement la
     capture de l'utilisateur. */
  ok('…et quand ils y sont TOUS, le violet n\'a plus rien à dire',
     tous.violet === null, JSON.stringify(tous));
  /* L'AUTRE MOITIÉ DE LA RÈGLE, et elle est indispensable : sans elle, un
     violet supprimé purement et simplement passerait aussi. */
  ok('…mais le membre absent de la barre, lui, est nommé par le violet seul',
     /beta/.test(deux.bleu || '') && !/gamma/.test(deux.bleu || '')
     && /gamma/.test(deux.violet || '') && !/beta/.test(deux.violet || ''),
     JSON.stringify(deux));
  /* LA PRÉMISSE DU TROISIÈME CAS : le décor a bien posé une carte HORS de la
     liste suivie. Sans elle, « le bleu ne la nomme pas » serait vrai d'une
     carte qui n'existe nulle part. */
  ok('le décor pose bien une carte hors de la liste, dans « Chaînes live »',
     depuisSuivies.recoVue === true, JSON.stringify(depuisSuivies));
  /* L'ASSERTION QUI PORTE LE PREMIER SIGNALEMENT. Mutant — la recherche portée
     sur le document entier — « Co-stream avec juliettearz » au bleu et rien au
     violet : la capture de l'utilisateur, à l'identique. */
  ok('…et une chaîne qui n\'est QUE là n\'est pas « de cette liste »',
     depuisSuivies.bleu === null && /juliettearz/i.test(depuisSuivies.violet || ''),
     JSON.stringify(depuisSuivies));
  /* ET LE MÊME SIGNALEMENT VU DE L'AUTRE CÔTÉ : « sur la partie "Chaînes
     live", JulietteArz a le badge bleu ». Viser la liste suivie en dur
     corrigeait le cas où le MEMBRE était ailleurs et laissait entier celui où
     c'est la carte SURVOLÉE qui l'est. Mutant — la section suivie en dur —
     « Co-stream avec lbw » au bleu depuis une carte de « Chaînes live ». */
  ok('…et depuis « Chaînes live », c\'est la liste suivie qui devient l\'ailleurs',
     depuisLive.bleu === null && /lbw/i.test(depuisLive.violet || ''),
     JSON.stringify(depuisLive));
}

/* ═════════ LE COMBINÉ D'UN MEMBRE QU'ON N'INTERROGERA JAMAIS ═════════════
   LE SIGNALEMENT, EN UNE QUESTION : « il y a un co-stream de trois et on n'en
   voit que deux en carte — pourquoi PestilenceRIOT n'est pas visible ? »

   ET LE RAPPORT LE CHIFFRAIT avec le compteur écrit pour ça :
       sousLaCoupe 6 · sousLaCoupeAvecCombine 6
   Six membres dont on CONNAÎT le combiné, et qui restent sous la coupe.

   LA BOUCLE SE REFERMAIT SUR ELLE-MÊME. `readStream` sait déjà qu'un combiné
   connu prime sur ce que le répertoire raconte — c'est la 4.14.3 — mais il le
   cherche À LA CLÉ DE LA CHAÎNE ELLE-MÊME, dans le cache Guest Star. Or on
   n'interroge Guest Star que sur les chaînes qui ont une CARTE. Un membre sans
   carte n'a donc pas d'entrée ; le répertoire le range à son audience propre,
   quelques centaines ; il reste sous le trentième rang ; donc il n'a pas de
   carte ; donc on ne l'interroge pas. Rien ne pouvait rouvrir ce cercle.

   OR ON LE CONNAÎT DÉJÀ : la réponse Guest Star d'un membre qui a une carte
   porte la liste de TOUS ses camarades, chacun avec son combiné. Rien de neuf
   n'est demandé à Twitch — on cesse de ranger cette moitié-là sous une clé que
   personne n'interroge. */
{
  titre('151. Co-stream — le combiné fait entrer au classement un membre sans carte');

  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 60 * 60_000).toISOString();
    const c = (id, v) => ({ id, createdAt: h, viewers: v, game: 'Aniimo', tags: [] });
    /* « hote » a une carte, donc Guest Star sera interrogé SUR LUI. « absent »
       est son camarade : aucune carte, donc jamais interrogé, et le répertoire
       le range à son audience propre. Trois chaînes ordinaires s'intercalent
       entre les deux nombres, pour que la place au classement se voie. */
    window.__cats = [{ name: 'Aniimo', viewers: 90_000, streams: [
      { login: 'hote', viewers: 11_736 }, { login: 'absent', viewers: 300 },
      { login: 'g1', viewers: 9_000 }, { login: 'g2', viewers: 8_000 },
      { login: 'g3', viewers: 7_000 }, { login: 'modele', viewers: 800 }] }];
    window.__fx = { hote: c('1', 11_736), absent: c('2', 300), g1: c('3', 9_000),
                    g2: c('4', 8_000), g3: c('5', 7_000), modele: c('6', 800) };
    window.__gs = { 1: { hostId: '1', hostLogin: 'hote', guests: [
      { id: '1', login: 'hote', viewers: 11_736, combined: 11_736 },
      { id: '2', login: 'absent', viewers: 300, combined: 11_736 }] } };
    window.__addCard('hote', 'Aniimo', '11,7 k');
    window.__addCard('modele', 'Aniimo', '800');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => window.tse.global.on());
  await attendre(page, () => window.tse.global.top(10)
    .some((r) => r.login === 'g1' && r.viewers === 9000), 15_000);
  await wait(page, 2500);     // laisse Guest Star répondre et la marche publier
  const vu = await page.evaluate(() => ({
    rang: window.tse.global.top(10).map((r) => `${r.login}:${r.viewers}`),
    repertoireBas: window.tse.panneau.rapport().global.repertoireBas }));
  /* LA PRÉMISSE : le décor tient bien un classement peuplé, sans quoi « absent
     est en tête » serait vrai d'une liste de deux. */
  ok('le classement est peuplé et les chaînes ordinaires y sont à leur place',
     ['g1:9000', 'g2:8000', 'g3:7000'].every((x) => vu.rang.includes(x)),
     JSON.stringify(vu));
  /* L'ASSERTION QUI PORTE LE SIGNALEMENT. Mutant — le combiné cherché par le
     seul identifiant — « absent:300 », bon dernier derrière « modele:800 »,
     et « repertoireBas 0 » : le répertoire n'a jamais été corrigé. */
  ok('…et le membre sans carte porte son combiné, donc sa place',
     vu.rang.includes('absent:11736')
     && vu.rang.indexOf('absent:11736') < vu.rang.indexOf('g1:9000')
     && vu.repertoireBas > 0,
     JSON.stringify(vu));
  await page.close();
}

/* ═════════ UN CO-STREAM OCCUPE UNE PLACE, PAS CINQ ══════════════════════
   DEMANDÉ APRÈS UNE CAPTURE QUI NE LAISSAIT AUCUN DOUTE : « affiche l'ensemble
   des streamers d'un co-stream, MAIS considère l'ensemble d'un co-stream comme
   UNE place. S'il y a du coup 38 cartes, ce n'est pas grave — l'important est
   d'avoir les 30 meilleures PLACES. »

   CE QUE LA CAPTURE MONTRAIT, et qui est le vrai défaut : un groupe de cinq
   COUPÉ EN DEUX par une chaîne étrangère. Les membres d'une session portent
   chacun leur propre échantillon du compteur combiné — 4 795, 4 788, 4 782 —
   et un solo à 4 785 vient se glisser au milieu. Trié chaîne par chaîne, le
   groupe se disloque à l'écran, barre de liaison comprise.

   DEUX COUCHES À TENIR, ET LE SCÉNARIO LES TIENT TOUTES LES DEUX : le
   CLASSEMENT compte des places (les cinq membres sortent ensemble, et ne
   consomment qu'un rang), et l'ORDRE DES CARTES dit la même chose (le groupe
   se range à la position de son meilleur membre). Corriger l'une sans l'autre
   laisserait le défaut visible.

   UNE PLACE VIENT DE GUEST STAR, ET DE LUI SEUL. La première rédaction
   acceptait aussi la proximité des compteurs — celle qui protège déjà le
   combiné. Mesuré au banc sur ce décor : elle rangeait « p1:3000 », « p2:2900 »
   et « p3:2800 » dans une seule place. Trois chaînes sans rapport fondues en un
   groupe, et deux vraies places de moins à l'écran. Les deux questions ne se
   ressemblent que de loin : « ce compteur est-il un combiné ? » est une
   PROTECTION, dont le faux positif coûte un rafraîchissement retardé ; « ces
   chaînes sont-elles le même direct ? » est une STRUCTURE, dont le faux
   positif cache de vraies chaînes. */
{
  titre('152. Top Chaînes — un co-stream occupe une place, pas cinq');

  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    /* LES CINQ ÉCHANTILLONS DU TERRAIN, et le solo qui se glisse au milieu :
       4 785 tombe entre 4 788 et 4 782. C'est le seul point du décor qui
       compte, et sans lui le scénario serait vert sans rien mesurer. */
    const grp = [['m1', 4795], ['m2', 4788], ['m3', 4782], ['m4', 4776], ['m5', 4771]];
    const streams = [
      { login: 'gros1', viewers: 9000 }, { login: 'gros2', viewers: 8000 },
      ...grp.map(([l, v]) => ({ login: l, viewers: v })),
      { login: 'intrus', viewers: 4785 },
      { login: 'p1', viewers: 3000 }, { login: 'p2', viewers: 2900 },
      { login: 'p3', viewers: 2800 }, { login: 'modele', viewers: 800 },
    ];
    window.__cats = [{ name: 'MLBB', viewers: 90_000, streams }];
    window.__fx = {}; window.__gs = {};
    /* IDENTIFIANTS NUMÉRIQUES, et ce n'est pas un détail de décor : la
       résolution Guest Star ne part pas sur un identifiant d'une autre forme,
       et le banc rendait alors « aucune requête Guest Star » — donc aucune
       session, donc aucune place. Mesuré en cherchant pourquoi. */
    for (const st of streams) {
      window.__fx[st.login] = { id: String(700_000 + st.viewers), createdAt: h,
                                viewers: st.viewers, game: 'MLBB', tags: [] };
    }
    const idDe = (l) => window.__fx[l].id;
    const guests = grp.map(([l, v]) => ({ id: idDe(l), login: l, viewers: v, combined: v }));
    for (const [l] of grp) {
      window.__gs[idDe(l)] = { hostId: idDe('m1'), hostLogin: 'm1', guests };
    }
    window.__addCard('modele', 'MLBB', '800');
    for (const [l, v] of grp) window.__addCard(l, 'MLBB', String(v));
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => window.tse.global.on());
  await attendre(page, () => window.tse.global.top(5)
    .filter((r) => /^m\d$/.test(r.login)).length >= 5, 15_000);
  await wait(page, 1500);
  const vu = await page.evaluate(() => ({
    top5: window.tse.global.top(5).map((r) => r.login),
    cartes: [...document.querySelectorAll('.side-nav-card[data-tse-global="true"]')]
      .map((c) => c.dataset.tseLogin),
  }));
  const rang = (l) => vu.cartes.indexOf(l);
  /* LA PRÉMISSE : cinq places demandées rendent NEUF chaînes — deux solos, les
     cinq du groupe, puis le suivant. Sans elle, « le groupe est contigu »
     serait vrai d'une liste qui n'en contiendrait qu'un membre. */
  ok('cinq places rendent neuf chaînes : le groupe compte pour une',
     vu.top5.length === 9 && ['m1', 'm2', 'm3', 'm4', 'm5'].every((l) => vu.top5.includes(l)),
     JSON.stringify(vu.top5));
  /* L'ASSERTION QUI PORTE LA DEMANDE. Mutant — le classement compté chaîne par
     chaîne — « top5 » rend cinq chaînes et s'arrête à « intrus », les trois
     derniers membres du groupe restant dehors. */
  ok('…et l\'intrus ne coupe plus le groupe en deux',
     rang('m5') < rang('intrus') && rang('m1') < rang('m2')
     && rang('m2') < rang('m3') && rang('m3') < rang('m4') && rang('m4') < rang('m5'),
     JSON.stringify(vu.cartes));
  /* ET LES SOLOS NE BOUGENT PAS. Sans ce témoin, un tri qui mettrait tous les
     groupes en tête passerait aussi — ce n'est pas ce qui a été demandé. */
  ok('…tandis que les solos gardent leur rang au compteur',
     rang('gros1') < rang('gros2') && rang('gros2') < rang('m1')
     && rang('intrus') < rang('p1') && rang('p1') < rang('p2'),
     JSON.stringify(vu.cartes));
  await page.close();
}

/* ═════════ UNE PLACE EST COMPLÈTE, OU ELLE N'EST PAS UNE PLACE ══════════
   SIGNALÉ AINSI : « où est Lukawaaa ? le co-stream devrait être composé de
   trois streamers, là il n'y en a que deux. »

   LES DEUX AUTRES ÉTAIENT BIEN LÀ, groupés, à leur rang : la place de la 4.18
   faisait son travail. Le troisième était introuvable parce qu'il n'est dans
   AUCUN classement — le répertoire de Twitch ne l'a jamais rendu, ni en tête
   de sa catégorie ni ailleurs, et `setViewers` ne CRÉE jamais d'entrée. Une
   règle de tri ne peut pas faire apparaître ce qui n'existe nulle part.

   ON COMPLÈTE DONC LA PLACE avec ce que Guest Star a déjà dit : il nomme les
   participants et donne leur combiné. Rien de neuf n'est demandé à Twitch. Le
   reste — catégorie, ancienneté, avatar — arrive par la voie ordinaire dès que
   la carte existe.

   ET CELA NE TOUCHE PAS LE POOL, délibérément : un enregistrement que le
   répertoire ne rend jamais accumulerait ses absences et se ferait évincer en
   trois passes. La complétion vit à l'AFFICHAGE, là où la question se pose.

   LE DÉCOR EST CELUI DU TERRAIN, ET C'EST TOUT SON INTÉRÊT : « luka » EXISTE
   — il a un stream, une catégorie, Twitch répond pour lui — mais aucun sommet
   de catégorie ne le rend. Sans cette nuance le scénario mesurerait une chaîne
   inexistante, ce qui n'est pas le cas signalé. */
{
  titre('153. Top Chaînes — le membre que le répertoire ne rend jamais');

  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    const streams = [
      { login: 'gros1', viewers: 13_400 }, { login: 'gros2', viewers: 12_300 },
      { login: 'gpk', viewers: 10_600 }, { login: 'shachlos', viewers: 10_600 },
      ...Array.from({ length: 8 }, (_, i) => ({ login: 'b' + i, viewers: 9000 - i * 100 })),
      { login: 'modele', viewers: 800 },
    ];
    window.__cats = [{ name: 'Dota 2', viewers: 200_000, streams }];
    window.__fx = {}; window.__gs = {};
    for (const st of streams) {
      window.__fx[st.login] = { id: String(800_000 + st.viewers), createdAt: h,
                                viewers: st.viewers, game: 'Dota 2', tags: [] };
    }
    /* « luka » existe sur Twitch — stream, catégorie, réponse — mais l'annuaire
       ne le rend dans AUCUN sommet de catégorie : le répertoire range la
       session sous l'hôte. C'est le cas du terrain, et le seul point du décor
       qui compte. */
    window.__fx.luka = { id: '999111', createdAt: h, viewers: 250,
                         game: 'Dota 2', tags: [] };
    const idDe = (l) => window.__fx[l].id;
    const guests = [
      { id: idDe('gpk'), login: 'gpk', viewers: 10_600, combined: 10_600 },
      { id: idDe('shachlos'), login: 'shachlos', viewers: 10_600, combined: 10_600 },
      { id: '999111', login: 'luka', viewers: 250, combined: 10_600 },
    ];
    for (const l of ['gpk', 'shachlos']) {
      window.__gs[idDe(l)] = { hostId: idDe('gpk'), hostLogin: 'gpk', guests };
    }
    // Twitch répond aussi pour le troisième dès qu'on l'interroge : c'est ce
    // qui permet au groupe de se DESSINER, et non seulement d'exister.
    window.__gs['999111'] = { hostId: idDe('gpk'), hostLogin: 'gpk', guests };
    window.__addCard('modele', 'Dota 2', '800');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => window.tse.global.on());
  await attendre(page, () => window.tse.global.top(4)
    .some((r) => r.login === 'luka'), 15_000);
  await wait(page, 1500);
  const vu = await page.evaluate(() => ({
    top4: window.tse.global.top(4).map((r) => `${r.login}:${r.viewers}`),
    cartes: [...document.querySelectorAll('.side-nav-card[data-tse-global="true"]')]
      .map((c) => c.dataset.tseLogin),
    groupees: [...document.querySelectorAll('.side-nav-card.tse-costream')]
      .map((c) => c.dataset.tseLogin),
  }));
  /* LA PRÉMISSE : les deux membres que le répertoire rend sont bien là, à leur
     rang. Sans elle, « les trois y sont » serait vrai d'une liste vide. */
  ok('les deux membres que le répertoire rend sont au classement',
     vu.top4.includes('shachlos:10600') && vu.top4.includes('gpk:10600'),
     JSON.stringify(vu.top4));
  /* L'ASSERTION QUI PORTE LE SIGNALEMENT. Mutant — la place laissée
     incomplète — « luka » n'apparaît ni au classement ni à l'écran, et le
     groupe se dessine à deux : la capture de l'utilisateur, à l'identique. */
  ok('…et le troisième, que le répertoire ignore, est complété par la session',
     vu.top4.includes('luka:10600') && vu.cartes.includes('luka'),
     JSON.stringify({ top4: vu.top4, cartes: vu.cartes.slice(0, 6) }));
  /* ET IL EST DESSINÉ AVEC LES AUTRES, pas seulement présent. Un membre
     complété mais laissé hors du groupe afficherait un co-stream qu'on ne
     reconnaît pas comme tel. */
  ok('…et le groupe se dessine à trois, contigus',
     ['shachlos', 'gpk', 'luka'].every((l) => vu.groupees.includes(l))
     && Math.max(...['shachlos', 'gpk', 'luka'].map((l) => vu.cartes.indexOf(l)))
        - Math.min(...['shachlos', 'gpk', 'luka'].map((l) => vu.cartes.indexOf(l))) === 2,
     JSON.stringify({ groupees: vu.groupees, cartes: vu.cartes.slice(0, 6) }));
  await page.close();
}

/* ═════════ DIRE POURQUOI IL EST LÀ, ET QUI N'Y EST PAS ══════════════════
   DEUX DEMANDES, NÉES DE LA MÊME LIMITE DE LA 4.18.1.

   LA PREMIÈRE : sous filtre de langue, un membre de co-stream qui ne porte pas
   la langue choisie était CACHÉ, faute de savoir quoi dire de lui. Un co-stream
   amputé par le filtre est un co-stream faux ; la bonne réponse n'était pas de
   le cacher mais de dire POURQUOI il est là. « Le drapeau de SA langue sur la
   carte, à droite du pseudo. Si subathon, entre le pseudo et le logo. »

   LA SECONDE : « si un streamer fait partie d'un co-stream mais n'est pas en
   live, il faudrait avertir l'utilisateur. » La réponse Guest Star le disait
   DÉJÀ — elle demande `stream` par participant, et il vaut null pour qui
   participe sans diffuser — et on le jetait. Aucune requête nouvelle.

   TROIS CONSÉQUENCES, ET LE SCÉNARIO LES TIENT TOUTES :
     — pas de carte pour qui ne diffuse pas (« Top Chaînes » classe des chaînes
       EN DIRECT ; lui en donner une lui prêterait le compteur du groupe) ;
     — la pastille de l'avatar continue de compter la SESSION, donc elle
       annonce plus de monde que la liste n'en montre ;
     — l'aperçu raccorde les deux nombres en nommant les absents, et « En live
       avec » cesse de nommer des gens qui ne sont pas en live. */
{
  titre('154. Co-stream — le drapeau de l\'autre langue, et qui ne diffuse pas');

  const page = await fresh();
  await page.evaluate(() => {
    const h = new Date(Date.now() - 3600_000).toISOString();
    const streams = [
      { login: 'gros1', viewers: 13_400, tags: ['Français'] },
      { login: 'hote', viewers: 10_600, tags: ['Français'] },
      /* LE MEMBRE D'UNE AUTRE LANGUE. Il n'a pas le tag demandé : sans la
         place, le filtre l'écarterait — et le co-stream serait amputé. */
      { login: 'ru', viewers: 10_600, tags: ['Русский'] },
      ...Array.from({ length: 6 }, (_, i) => ({ login: 'b' + i, viewers: 9000 - i * 100,
                                                tags: ['Français'] })),
      { login: 'modele', viewers: 800, tags: ['Français'] },
    ];
    window.__cats = [{ name: 'Dota 2', viewers: 200_000, streams }];
    window.__fx = {}; window.__gs = {};
    for (const st of streams) {
      window.__fx[st.login] = { id: String(800_000 + st.viewers), createdAt: h,
                                viewers: st.viewers, game: 'Dota 2', tags: st.tags,
                                // « ru » est AUSSI en subathon : le drapeau doit se
                                // glisser ENTRE le pseudo et la pastille du jour.
                                title: st.login === 'ru' ? 'SUBATHON DAY 12 | !socials'
                                                         : 'Stream' };
    }
    const idDe = (l) => window.__fx[l].id;
    const guests = [
      { id: idDe('hote'), login: 'hote', viewers: 10_600, combined: 10_600 },
      { id: idDe('ru'), login: 'ru', viewers: 10_600, combined: 10_600 },
      /* `sansStream` : DANS la session, sans diffuser. C'est ce que Twitch rend
         pour l'invité d'un Guest Star qui n'a pas de chaîne en direct. */
      { id: '777222', login: 'muet', viewers: null, combined: null, sansStream: true },
    ];
    for (const l of ['hote', 'ru']) {
      window.__gs[idDe(l)] = { hostId: idDe('hote'), hostLogin: 'hote', guests };
    }
    window.__addCard('modele', 'Dota 2', '800');
  });
  await attendre(page, () => document.querySelectorAll('[data-tse-viewers]').length >= 1, 12_000);
  await page.evaluate(() => window.tse.global.on());
  await wait(page, 2500);
  await page.evaluate(() => {
    const opt = [...document.querySelectorAll('#tse-lang-dd .tse-dd-opt')]
      .find((o) => (o.dataset.value || '') === 'Français');
    if (!opt) throw new Error('« Français » absent de la liste des langues');
    opt.click();
  });
  await attendre(page, () => !!document.querySelector('.tse-lang-mark'), 10_000);
  await wait(page, 800);
  const vu = await page.evaluate(() => ({
    visibles: [...document.querySelectorAll('.side-nav-card[data-tse-global="true"]')]
      .filter((c) => getComputedStyle(c).display !== 'none').map((c) => c.dataset.tseLogin),
    muetAffiche: !![...document.querySelectorAll('.side-nav-card')]
      .find((c) => c.dataset.tseLogin === 'muet'),
    drapeaux: [...document.querySelectorAll('.tse-lang-mark')]
      .map((m) => m.closest('.side-nav-card')?.dataset.tseLogin + ':' + m.dataset.langue),
    ordre: (() => {
      const c = [...document.querySelectorAll('.side-nav-card')]
        .find((x) => x.dataset.tseLogin === 'ru');
      const p = c?.querySelector('p[data-a-target="side-nav-title"]');
      return p ? [...p.children].map((e) => e.className) : null;
    })(),
    pastille: [...document.querySelectorAll('.side-nav-card')]
      .filter((c) => c.dataset.tseLogin === 'hote')
      .map((c) => c.querySelector('.tse-collab-badge')?.textContent ?? null),
  }));
  /* LA PRÉMISSE : le filtre est bien actif et il a bien trié. Sans elle, « ru
     est visible » serait vrai d'une liste que rien n'a filtrée. */
  ok('le filtre « Français » est actif et la liste lui obéit',
     vu.visibles.includes('hote') && vu.visibles.includes('b0')
     && !vu.visibles.includes('muet'), JSON.stringify(vu.visibles));
  /* L'ASSERTION QUI PORTE LA PREMIÈRE DEMANDE. Mutant — la complétion
     abstenue sous filtre, comme en 4.18.1 — « ru » disparaît et le co-stream
     se montre amputé. */
  ok('…mais le membre d\'une autre langue reste là, avec le drapeau de la sienne',
     vu.visibles.includes('ru') && vu.drapeaux.length === 1
     && vu.drapeaux[0] === 'ru:Русский', JSON.stringify(vu.drapeaux));
  /* LA POSITION DEMANDÉE, AU MOT PRÈS : « à droite du pseudo ; si subathon,
     entre le pseudo et le logo subathon ». Mutant — le drapeau ajouté en fin
     de <p> sans égard pour la pastille — l'ordre devient nom · jour · drapeau. */
  ok('…posé entre le pseudo et la pastille de subathon',
     JSON.stringify(vu.ordre)
       === JSON.stringify(['tse-subathon-nom', 'tse-lang-mark', 'tse-subathon-jour']),
     JSON.stringify(vu.ordre));
  /* L'ASSERTION QUI PORTE LA SECONDE DEMANDE. Mutant — `enLigne` ignoré —
     « muet » reçoit une carte portant le compteur du groupe, sur une chaîne
     qui ne diffuse pas. */
  ok('…et celui qui ne diffuse pas n\'a aucune carte, la pastille comptant la session',
     vu.muetAffiche === false && vu.pastille.length === 1 && vu.pastille[0] === '2',
     JSON.stringify({ muet: vu.muetAffiche, pastille: vu.pastille }));

  // ── ET L'APERÇU RACCORDE LES DEUX NOMBRES ────────────────────────────
  await page.evaluate(() => [...document.querySelectorAll('.side-nav-card')]
    .find((c) => c.dataset.tseLogin === 'hote')
    ?.dispatchEvent(new MouseEvent('mouseenter', { bubbles: false })));
  await attendre(page, () => !!document.querySelector('.tse-preview__badge--muet'), 8000);
  const badges = await page.evaluate(() => {
    const t = (sel) => document.querySelector(sel)?.textContent?.trim() || null;
    return { bleu: t('.tse-preview__badge--costream'),
             violet: t('.tse-preview__badge--squad'),
             muet: t('.tse-preview__badge--muet') };
  });
  ok('l\'aperçu nomme celui qui est dans la session sans diffuser',
     /muet/.test(badges.muet || ''), JSON.stringify(badges));
  /* ET « EN LIVE AVEC » CESSE DE MENTIR : il nommait tous les participants,
     y compris ceux qui ne diffusent pas. Ici il n'a personne à nommer — le
     seul autre membre visible est déjà au badge bleu — et il se tait. */
  ok('…et « En live avec » ne nomme plus personne qui ne soit en live',
     badges.violet === null && /ru/.test(badges.bleu || ''),
     JSON.stringify(badges));
  await page.close();
}

/* ═════════ CE QUE LE BANC NE SAIT PAS TENIR, ET QUI SE DIT ══════════════
   LA 4.15.9 FAIT ATTENDRE AU VOILE les chaînes dont il ne sait RIEN encore —
   pas seulement les sondes déjà parties. La correction est MESURÉE : sur un
   décor où la réponse de chaîne traîne 1,2 s, le voile se levait à 250 ms, il
   se lève à 1245 ms.

   ELLE N'A PAS SON ASSERTION, ET C'EST ÉCRIT PLUTÔT QUE TU. Trois formes ont
   été essayées, aucune ne tient :

     — lire les durées à la levée : l'observateur de mutation se déclenche
       entre la réponse et l'écriture sur la carte, donc il lit un DOM en
       retard de quelques millisecondes sur lui-même ;
     — exiger un témoin du voile posé : il faut l'amorcer sur l'état courant,
       le voile du démarrage étant antérieur au script du scénario ;
     — comparer la date de levée à un seuil : le seuil dépend de l'instant où
       le premier lot part, qui n'est pas maîtrisé.

   CE QUI RESTE COUVERT : le scénario 144 tient l'autre moitié — sous le voile,
   les origines SONT apprises et les durées lues à la levée. Ce qui n'est pas
   couvert est l'attente des chaînes encore inconnues, vérifiée à la main.
   Écrire ce trou ici vaut mieux qu'une assertion qui passerait au vert sans
   rien mesurer : c'est ce qu'ont fait les trois tentatives ci-dessus. */

/* ═════════ LE BANC SE COMPTE, ET LES README DOIVENT LE DIRE JUSTE ═════════
   Les deux README annoncent la taille de ce banc. Ils ne peuvent pas la
   connaître : ils la recopient. Résultat, avant cette ligne, un même fichier
   se contredisait à deux pages d'intervalle — « 561 assertions, 66 scénarios »
   d'un côté, « 64 scénarios, 544 assertions » de l'autre, alors qu'il y en
   avait 579 et 67. Personne ne l'avait vu : rien ne reliait la phrase au banc.

   C'est ici que le lien se fait, parce que c'est ici que le nombre existe.
   Contrairement aux tailles de paquet, il n'y a AUCUNE tolérance : un banc a
   un nombre d'assertions exact, et ajouter une assertion sans toucher aux deux
   README est une omission, pas une dérive. Le message d'échec donne le chiffre
   à écrire, ce qui rend la corvée d'une dizaine de secondes.

   L'assertion se compte ELLE-MÊME : au moment où elle s'évalue elle n'est pas
   encore dans le total, d'où le +1. Sans lui, le banc annoncerait éternellement
   une assertion de moins qu'il n'en a. */
{
  titre('68. Le banc — sa taille est celle que les README annoncent');
  const total = pass + fail + 1;          // +1 : cette assertion-ci
  const dits = [];
  for (const doc of ['README.md', 'README.en.md']) {
    const texte = readFileSync(join(ICI, '..', doc), 'utf8');
    const m = /(\d+)\s+(?:scénarios|scenarios),\s*(\d+)\s+assertions/.exec(texte);
    dits.push({ doc, scen: m && Number(m[1]), ass: m && Number(m[2]) });
  }
  const faux = dits.filter(d => d.scen !== nbScenarios || d.ass !== total);
  ok(`les README annoncent la taille réelle du banc (${nbScenarios} scénarios, ${total} assertions)`,
     faux.length === 0,
     faux.map(d => `${d.doc} dit ${d.scen} scénarios / ${d.ass} assertions`).join(' | ')
       || '(ligne introuvable)');
}

await browser.close();
console.log(`\n${'═'.repeat(50)}`);
if (echecs.length) {
  console.log(`${echecs.length} ÉCHEC(S) :`);
  for (const e of echecs) {
    console.log(`  • ${e.scenario}`);
    console.log(`      ${e.assertion}${e.detail ? '  —  ' + e.detail : ''}`);
  }
  console.log('═'.repeat(50));
}
console.log(`${pass} réussis, ${fail} échoués — moteur ${MOTEUR}\n`);
process.exit(fail ? 1 : 0);
